#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define GPIO pins for SPI communication
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11
#define CE0_PIN 8

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int speed;
    int mode;
} spi_config_t;

// Function prototypes
int initialize_spi(spi_config_t config);
int read_mcp3008(int channel);
void log_data(int adc_value);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the SPI interface
int initialize_spi(spi_config_t config) {
    spi_handle = spiOpen(config.channel, config.speed, config.mode);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", config.channel, spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct the SPI message to send to the MCP3008
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer the SPI message
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to log the data with a timestamp
void log_data(int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, ADC Value: %d\n", timestamp, adc_value);
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI parameters
    spi_config_t spi_config = {
        .channel = SPI_CHANNEL,
        .speed = SPI_SPEED,
        .mode = SPI_MODE
    };

    // Initialize SPI
    if (initialize_spi(spi_config) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read the ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            // Log the data
            log_data(adc_value);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

