#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GAIN_4_096 0x0000 // Gain of ±4.096V
#define MODE_SINGLE_SHOT 0x0100 // Single-shot mode
#define AIN0 0x4000 // AIN0 single-ended
#define SAMPLE_RATE 128 // 128 SPS
#define VREF 4.096 // Reference voltage
#define MAX_CURRENT 100.0 // Maximum expected current (Amps)
#define MIN_CURRENT 0.0 // Minimum expected current (Amps)
#define ERROR_VALUE -1.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_ads1115();
int16_t read_conversion();
float convert_to_current(int16_t raw_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure ADS1115
int config_ads1115() {
    uint16_t config = (MODE_SINGLE_SHOT << 15) | (GAIN_4_096 << 12) | (AIN0 << 4) | (SAMPLE_RATE << 0);
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read conversion result
int16_t read_conversion() {
    char buf[1];
    char read_buf[2];
    buf[0] = CONVERSION_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C (conversion reg): %d\n", result);
        return ERROR_VALUE;
    }

    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return ERROR_VALUE;
    }

    // Byte swap
    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    return raw_value;
}

// Convert raw value to current
float convert_to_current(int16_t raw_value) {
    float current = ((float)raw_value / 32767.0) * VREF * (MAX_CURRENT / VREF);
    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (config_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("ADS1115 configured. Reading current...\n");

    // Main loop
    while (!terminate) {
        int16_t raw_value = read_conversion();
        if (raw_value == ERROR_VALUE) {
            fprintf(stderr, "Error reading conversion, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        float current = convert_to_current(raw_value);
        printf("Current: %.3f A\n", current);

        gpioDelay(500); // 500ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

