#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define TEMPERATURE_THRESHOLD 60.0
#define TEMPERATURE_REG 0x00
#define TEMP_SCALE 0.0625
#define TEMP_OFFSET 0.5
#define ADC_CHANNEL 0
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "fire_log.txt"
#define DEBOUNCE_DELAY 50 // milliseconds
#define POLLING_DELAY 100 // milliseconds

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;
static int buzzer_state = 0; // 0 = off, 1 = on

// Function prototypes
int initialize();
void cleanup();
void signal_handler(int signal);
int read_flame_sensor();
float read_temperature();
void control_buzzer(int state);
void log_event(const char *message);
void log_temperature(float temperature);
void log_error(const char *message);

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to cleanup resources
void cleanup() {
    running = 0; // Stop the main loop

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int reading = gpioRead(FLAME_SENSOR_GPIO);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay in microseconds
    return gpioRead(FLAME_SENSOR_GPIO) == reading ? reading : 0; // Return the stable reading
}

// Function to read the temperature from the LM393-based heat sensor
float read_temperature() {
    char config[3] = {0x01, 0x80, 0x00}; // Single-ended AIN0, +/- 4.096V, 128 SPS
    char data[2];
    int16_t raw_temp;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        log_error("Failed to configure ADS1115");
        return -1.0; // Indicate error
    }
    gpioDelay(10); // Wait for conversion

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        log_error("Failed to read ADS1115");
        return -1.0; // Indicate error
    }

    raw_temp = (data[0] << 8) | data[1];
    return (float)raw_temp * TEMP_SCALE + TEMP_OFFSET;
}

// Function to control the buzzer
void control_buzzer(int state) {
    gpioWrite(BUZZER_GPIO, state);
    buzzer_state = state;
}

// Function to log an event to the log file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Function to log a temperature reading
void log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] Temperature: %.2f\u00b0C\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, temperature);
    fflush(log_file);
}

// Function to log an error message
void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

