#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0" // SPI device file
#define FAN_GPIO 18                 // GPIO pin for the cooling fan
#define CURRENT_THRESHOLD 5.0      // Current threshold in Amperes
#define LOG_FILE "current_log.txt"  // Log file name
#define SPI_SPEED 1000000          // SPI clock speed (1 MHz)
#define SPI_MODE 0                 // SPI mode

// Global variables
int spi_fd = -1;                 // SPI file descriptor
FILE *log_file = NULL;          // Log file pointer
volatile sig_atomic_t terminate = 0; // Termination flag

// Function prototypes
int spi_init(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_adc(int fd);
float calculate_current(int adc_value);
int log_data(float current);
int control_fan(float current);
void signal_handler(int signal);
void cleanup();

// SPI Initialization
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }
    return 0;
}

// Read ADC Value
int read_adc(int fd) {
    uint8_t tx_buf[3] = {0x01, 0x80, 0x00}; // Start bit, single-ended channel 0, dummy byte
    uint8_t rx_buf[3] = {0};

    if (spi_transfer(fd, tx_buf, rx_buf, 3) == -1) {
        fprintf(stderr, "Error reading ADC value\n");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Calculate Current
float calculate_current(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // This needs to be calibrated based on the sensor's datasheet and
