    // The formula is: ppm = A * exp(B * raw_data) + C
    // where A, B, and C are calibration constants.

    // Example constants (replace with your calibration values)
    float A = 0.1;  // Example value
    float B = 0.01; // Example value
    float C = 0.0;  // Example value

    return A * exp(B * raw_data) + C;
}

// Function to log data to file
int log_data(float co_ppm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
