    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s, %.2f ppm\n", timestamp, co_ppm);
    fclose(log_file);
    return 0;
}

