// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define SPI_CE_PIN 8
#define SPI_MOSI_PIN 10
#define SPI_MISO_PIN 9
#define SPI_SCLK_PIN 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD_RATE 1000000 // 1 MHz

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
int read_flame_sensor();
int log_data(int flame_presence, float temperature);
void signal_handler(int signal);

// Structure to hold SPI configuration
typedef struct {
    int ce_pin;
    int mosi_pin;
    int miso_pin;
    int sclk_pin;
    int baud_rate;
} spi_config_t;

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_config_t spi_config = {
        .ce_pin = SPI_CE_PIN,
        .mosi_pin = SPI_MOSI_PIN,
        .miso_pin = SPI_MISO_PIN,
        .sclk_pin = SPI_SCLK_PIN,
        .baud_rate = SPI_BAUD_RATE
    };

    spi_handle = spiOpen(spi_config.ce_pin, spi_config.baud_rate, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to read flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to log data to CSV file
int log_data(int flame_presence, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_presence, temperature);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read flame sensor
        int flame_presence = read_flame_sensor();

        // Read temperature (replace with actual temperature sensor reading)
        float temperature = 25.0; // Example temperature

        // Log data
        if (log_data(flame_presence, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

