    while (!terminate) {
        uint16_t ox_value;
        float co_ppm;

        // Read CO sensor data
        if (read_sensor_data(CO_REG, &ox_value) == 0) {
            co_ppm = convert_to_ppm(ox_value);

            // Log data
            if (log_data(co_ppm) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Check for alert
            if (check_alert(co_ppm)) {
                time_t now = time(NULL);
                if (write_alert(now, co_ppm) != 0) {
                    fprintf(stderr, "Failed to write alert\n");
                }
            }

            printf("CO: %.2f ppm\n", co_ppm);
        } else {
            fprintf(stderr, "Failed to read CO sensor data\n");
        }

        gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL, 0); // Sleep for 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Air quality monitoring stopped.\n");

    return 0;
}

