#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define WARNING_LED_GPIO 17
#define BUFFER_SIZE 100
#define AVERAGE_THRESHOLD 50.0 // Amperes
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int16_t read_ads1115();
float convert_to_current(int16_t raw_value);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Function to initialize the I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the ADS1115
int16_t read_ads1115() {
    char config[3];
    char data[2];
    int16_t raw_value;

    // Configure the ADS1115 for single-ended A0, 4.096V range, continuous conversion mode, 128 SPS
    config[0] = CONFIG_REG;
    config[1] = 0xC3; // 0b11000011
    config[2] = 0x83; // 0b10000011

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    if (i2cWriteDevice(i2c_handle, CONVERSION_REG, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device for conversion\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    raw_value = (data[0] << 8) | data[1];

    return raw_value;
}

// Function to convert the raw ADC value to current (Amperes)
float convert_to_current(int16_t raw_value) {
    // Assuming a 4.096V reference and a 16-bit ADC (2^15 values)
    float voltage = (float)raw_value * 4.096 / 32768.0;
    float current = voltage / 0.1; // Assuming 0.1V/A sensitivity
    return current;
}

// Function to add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Function to control the warning LED
void control_led(int on) {
    gpioWrite(WARNING_LED_GPIO, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    control_led(0); // Turn off the LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for the warning LED
    gpioSetMode(WARNING_LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize the circular buffer
    CircularBuffer current_buffer;
    init_circular_buffer(&current_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read the ADC value
        int16_t raw_value = read_ads1115();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        // Convert the raw value to current
        float current = convert_to_current(raw_value);

        // Add the current to the circular buffer
        add_to_buffer(&current_buffer, current);

        // Calculate the average current
        float average_current = calculate_average(&current_buffer);

        // Check if the average current exceeds the threshold
        if (average_current > AVERAGE_THRESHOLD) {
            control_led(1); // Turn on the LED
        } else {
            control_led(0); // Turn off the LED
        }

        // Delay to achieve the desired sampling rate
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

