#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_CONTROL         (0x0F)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Enable Register Values
#define TCS34725_ENABLE_AIEN     (0x10) // ALS Interrupt Enable
#define TCS34725_ENABLE_WEN      (0x08) // Wait enable
#define TCS34725_ENABLE_AEN      (0x02) // ALS Enable
#define TCS34725_ENABLE_PON      (0x01) // Power on

// Integration Time
#define TCS34725_INTEGRATIONTIME_2_4MS  (0xFF) // 2.4ms - 1 cycle = 4096 counts

// Gain
#define TCS34725_GAIN_1X            (0x00) // 1x gain

// Global Variables
static int i2c_handle;
static FILE *log_file;
static volatile int running = 1;

// Function Prototypes
int tcs34725_init(int i2c_handle);
int tcs34725_read_data(int i2c_handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void log_data(FILE *log_file, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);
int check_sensor_id(int i2c_handle);

// Signal Handler
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Check Sensor ID
int check_sensor_id(int i2c_handle) {
    char id;
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, &id, 1) != 1) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", id);
        return -1;
    }
    return 0;
}

// Initialize TCS34725
int tcs34725_init(int i2c_handle) {
    int status;

    // Enable power and ALS
    status = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN);
    if (status != 0) {
        fprintf(stderr, "Error writing to enable register: %d\n", status);
        return -1;
    }

    // Set integration time
    status = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ATIME, TCS34725_INTEGRATIONTIME_2_4MS);
    if (status != 0) {
        fprintf(stderr, "Error writing to integration time register: %d\n", status);
        return -1;
    }

    // Set gain
    status = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CONTROL, TCS34725_GAIN_1X);
    if (status != 0) {
        fprintf(stderr, "Error writing to gain register: %d\n", status);
        return -1;
    }

    return 0;
}

// Read Data from TCS34725
int tcs34725_read_data(int i2c_handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char data[8];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CDATA, data, 8);
    if (status != 8) {
        fprintf(stderr, "Error reading data: %d\n", status);
        return -1;
    }

    *clear = (uint16_t)((data[1] << 8) | data[0]);
    *red   = (uint16_t)((data[3] << 8) | data[2]);
    *green = (uint16_t)((data[5] << 8) | data[4]);
    *blue  = (uint16_t)((data[7] << 8) | data[6]);

    return 0;
}

// Log Data to CSV File
void log_data(FILE *log_file, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(log_file);
}

int main() {
    uint16_t clear, red, green, blue;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725
    if (tcs34725_init(i2c_handle) != 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check Sensor ID
    if (check_sensor_id(i2c_handle) != 0) {
        fprintf(stderr, "TCS34725 sensor ID check failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,clear,red,green,blue\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

