#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR_SHUTDOWN_PIN 17
#define SPI_CE0 8
#define SPI_SCLK 11
#define SPI_MOSI 10
#define SPI_MISO 9

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define over-current threshold (in amperes)
#define OVER_CURRENT_THRESHOLD 10.0

// Define MLX91211 sensitivity (in V/A) - Example value, check datasheet
#define MLX91211_SENSITIVITY 0.1 // V/A

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define log file name
#define LOG_FILE "current_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_current(int adc_value);
void log_current(float current);
void handle_over_current();
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to current (in amperes)
float adc_to_current(int adc_value) {
    float voltage = (float)adc_value * (3.3 / 1024.0); // Assuming 3.3V reference
    float current = voltage / MLX91211_SENSITIVITY; // Convert voltage to current
    return current;
}

// Function to log current to file
void log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to handle over-current event
void handle_over_current() {
    printf("Over-current detected! Shutting down motor.\n");
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0); // Set GPIO low to disable motor
    log_current(-1.0); // Log over-current event
    gpioDelay(1000); // Wait 1 second
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Set GPIO high to enable motor
    printf("Motor re-enabled.\n");
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CE0, PI_OUTPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is new or empty
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
    }
    rewind(log_file);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Ensure motor is enabled on exit
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value);

        // Log current
        log_current(current);

        // Check for over-current condition
        if (current > OVER_CURRENT_THRESHOLD) {
            handle_over_current();
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

