#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 105.0f
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for ADS1115 configuration
typedef struct {
    uint8_t config;
} ads1115_config_t;

// Function prototypes
int init_i2c();
int read_ads1115(int handle, int channel, int *adc_value);
float convert_pressure(int adc_value);
float convert_temperature(int adc_value);
void control_led(int gpio, int state);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int read_ads1115(int handle, int channel, int *adc_value) {
    ads1115_config_t config;
    int retries = 0;

    // Configure ADS1115 for single-ended mode, AIN0, +/-4.096V, continuous conversion
    config.config = 0x4003; // Single-ended, AIN0, +/-4.096V, Continuous, 128 SPS

    while (retries < RETRY_COUNT) {
        if (i2cWriteByteData(handle, CONFIG_REG, config.config) >= 0) {
            break; // Write successful
        } else {
            log_error("Failed to write configuration to ADS1115");
            retries++;
            gpioDelay(1000); // Wait before retrying
        }
    }

    if (retries == RETRY_COUNT) {
        log_error("Failed to write configuration after multiple retries");
        return -1;
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        int raw_value = i2cReadWordData(handle, CONVERSION_REG);
        if (raw_value >= 0) {
            *adc_value = raw_value;
            break; // Read successful
        } else {
            log_error("Failed to read ADC value");
            retries++;
            gpioDelay(1000); // Wait before retrying
        }
    }

    if (retries == RETRY_COUNT) {
        log_error("Failed to read ADC value after multiple retries");
        return -1;
    }

    return 0;
}

// Convert ADC value to pressure in kPa
float convert_pressure(int adc_value) {
    // Assuming a linear relationship between ADC value and pressure
    // This needs to be calibrated based on the MLX90834 datasheet
    float pressure = (adc_value * 4.096f) / 32768.0f * 100.0f; // kPa
    return pressure;
}

// Convert ADC value to temperature in °C
float convert_temperature(int adc_value) {
    // Assuming a linear relationship between ADC value and temperature
    // This needs to be calibrated based on the MLX90834 datasheet
    float temperature = (adc_value * 4.096f) / 32768.0f * 100.0f; // °C
    return temperature;
}

// Control the LED state
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Log errors to a file
void log_error(const char *message) {
    FILE *fp = fopen("error.log", "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        perror("Failed to open error log file");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int adc_pressure, adc_temperature;
    float pressure, temperature;

    // Main loop
    while (!terminate) {
        // Read pressure and temperature
        if (read_ads1115(i2c_handle, 0, &adc_pressure) == 0 && read_ads1115(i2c_handle, 1, &adc_temperature) == 0) {
            // Convert ADC values to pressure and temperature
            pressure = convert_pressure(adc_pressure);
            temperature = convert_temperature(adc_temperature);

            // Print pressure and temperature
            printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

            // Control LED based on pressure
            if (pressure > PRESSURE_THRESHOLD) {
                control_led(GPIO_LED, 1); // Turn LED on
            } else {
                control_led(GPIO_LED, 0); // Turn LED off
            }
        } else {
            log_error("Failed to read sensor data");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    control_led(GPIO_LED, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

