void log_data(float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to set the alarm state
void set_alarm_state(int alarm_state) {
    gpioWrite(ALARM_PIN, alarm_state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(ALARM_PIN, 0); // Turn off alarm
    if (log_file != NULL) {
        fclose(log_file);
    }
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        log_data(voltage);

        // Alarm control based on voltage
        if (voltage > 2.5) {
            set_alarm_state(1); // Turn on alarm
        } else {
            set_alarm_state(0); // Turn off alarm
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

