#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define FULL_SCALE_VOLTAGE 4.096 // V
#define PRESSURE_RANGE 0.0f - 100.0f // kPa
#define SAMPLE_RATE 1 // Hz
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for ADS1115 configuration
typedef struct {
    uint8_t config;
} ads1115_config_t;

// Function prototypes
int initialize_i2c();
int initialize_ads1115();
int16_t read_adc16();
float convert_to_pressure(int16_t adc_value);
int validate_pressure(float pressure);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize ADS1115
int initialize_ads1115() {
    // Configuration: Single-shot mode, AIN0, +/-4.096V, 128 SPS
    ads1115_config_t config = {
        .config = 0x4003 // Single-shot, AIN0, +/-4.096V, 128 SPS
    };

    int result = i2cWriteByteData(i2c_handle, CONFIG_REG, config.config);
    if (result < 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read ADC value from ADS1115
int16_t read_adc16() {
    int16_t adc_value = i2cReadWordData(i2c_handle, CONVERSION_REG);
    if (adc_value < 0) {
        fprintf(stderr, "Failed to read ADC value: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

// Convert ADC value to pressure
float convert_to_pressure(int16_t adc_value) {
    float voltage = (adc_value * FULL_SCALE_VOLTAGE) / 32768.0f;
    float pressure = (voltage / FULL_SCALE_VOLTAGE) * PRESSURE_RANGE;
    return pressure;
}

// Validate pressure value
int validate_pressure(float pressure) {
    if (pressure < PRESSURE_RANGE || pressure > 100.0f) {
        fprintf(stderr, "Pressure value out of range: %.2f kPa\n", pressure);
        return -1;
    }
    return 0;
}

// Log pressure value with timestamp
int log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Initialize ADS1115
    if (initialize_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Pressure sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t adc_value = -1;
        for (int i = 0; i < MAX_RETRIES; ++i) {
            adc_value = read_adc16();
            if (adc_value >= 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Retrying ADC read (%d/%d)\n", i + 1, MAX_RETRIES);
                gpioDelay(1000); // Wait 1ms before retrying
            }
        }

        if (adc_value >= 0) {
            float pressure = convert_to_pressure(adc_value);
            if (validate_pressure(pressure) == 0) {
                log_pressure(pressure);
            }
        } else {
            fprintf(stderr, "Failed to read ADC after multiple retries.\n");
        }

        gpioDelay(1000000 / SAMPLE_RATE); // Delay for 1 second (1000000 us / 1 Hz)
    }

    // Cleanup and exit
    cleanup();
    printf("Pressure sensor logging stopped.\n");
    return 0;
}

