#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0      // MCP3208 channel connected to HIH-4602-A
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with your email address
#define EMAIL_SUBJECT "Humidity Alert"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
int log_data(float humidity, float temperature);
int send_email_alert(float humidity);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    float humidity;
    float temperature;
} sensor_data_t;

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the MCP3208 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // Construct the SPI message to send to the MCP3208
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer the SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate humidity from ADC value
float calculate_humidity(int adc_value) {
    // HIH-4602-A datasheet specifies a linear relationship between ADC value and humidity.
    // Assuming 0 ADC = 0% RH and 4095 ADC = 100% RH (12-bit ADC)
    float humidity = ((float)adc_value / 4095.0) * 100.0;
    return humidity;
}

// Function to calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    // HIH-4602-A datasheet specifies a linear relationship between ADC value and temperature.
    // Assuming 0 ADC = 0°C and 4095 ADC = 50°C (example, adjust based on your sensor)
    float temperature = ((float)adc_value / 4095.0) * 50.0;
    return temperature;
}

// Function to log data to a file
int log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(log_file);

    return 0;
}

// Function to send an email alert using ssmtp
int send_email_alert(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    char command[256];
    snprintf(command, sizeof(command), "echo \"Subject: %s\nFrom: %s\nTo: %s\n\nHumidity exceeded threshold!\nTimestamp: %s\nHumidity: %.2f%%\" | ssmtp %s", EMAIL_SUBJECT, "sender@example.com", EMAIL_RECIPIENT, timestamp, humidity, EMAIL_RECIPIENT);

    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error executing system command\n");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(adc_value);
        float temperature = calculate_temperature(adc_value);

        // Log data
        if (log_data(humidity, temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Check humidity threshold and send email alert
        if (humidity > HUMIDITY_THRESHOLD) {
            printf("Humidity threshold exceeded: %.2f%%\n", humidity);
            if (send_email_alert(humidity) != 0) {
                fprintf(stderr, "Error sending email alert\n");
            }
        }

        // Wait for 5 seconds
        gpioDelay(5000); // pigpio's delay function (milliseconds)
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("Humidity monitoring stopped.\n");

    return 0;
}

