#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0
#define GPIO_CE0 8
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11
#define LOG_FILE "temperature_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(int channel, int speed);
int spi_transfer(int handle, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_adc(int handle, int channel);
float adc_to_temperature(int adc_value);
int log_temperature(float temperature);
void signal_handler(int signal);
int initialize_gpio();
int cleanup_gpio();

// SPI Initialization
int spi_init(int channel, int speed) {
    int handle = spiOpen(channel, speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", handle);
        return -1;
    }
    return handle;
}

// SPI Transfer
int spi_transfer(int handle, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    int result = spiXfer(handle, tx_buf, rx_buf, len);
    if (result != len) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ADC Value
int read_adc(int handle, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // MCP3208 configuration: single-ended, channel 0
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(handle, tx_buf, rx_buf, 3) != 0) {
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to Temperature Conversion
float adc_to_temperature(int adc_value) {
    float voltage = (adc_value / 1023.0) * 3.3;
    float temperature = (voltage - 0.5) * 100;
    return temperature;
}

// Log Temperature Data
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    // Check if the file is newly created
    struct stat file_info;
    if (stat(LOG_FILE, &file_info) == 0 && file_info.st_size == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fclose(log_file);
    return 0;
}

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_CE0, PI_OUTPUT);
    gpioSetMode(GPIO_MOSI, PI_OUTPUT);
    gpioSetMode(GPIO_MISO, PI_INPUT);
    gpioSetMode(GPIO_SCLK, PI_OUTPUT);

    gpioWrite(GPIO_CE0, 1); // Deselect the chip initially
    gpioWrite(GPIO_MOSI, 0);
    gpioWrite(GPIO_SCLK, 0);

    return 0;
}

// Cleanup GPIO
int cleanup_gpio() {
    gpioWrite(GPIO_CE0, 1); // Deselect the chip
    gpioTerminate();
    return 0;
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    spi_handle = spi_init(SPI_CHANNEL, SPI_SPEED);
    if (spi_handle < 0) {
        cleanup_gpio();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(spi_handle, MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Try again
        }

        // Convert to temperature
        float temperature = adc_to_temperature(adc_value);

        // Validate temperature range
        if (temperature < -40.0 || temperature > 125.0) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
            continue; // Skip logging
        }

        // Log temperature
        if (log_temperature(temperature) != 0) {
            fprintf(stderr, "Error logging temperature\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    spiClose(spi_handle);
    cleanup_gpio();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

