#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define GAIN_0 1.0
#define GAIN_1 10.0
#define SAMPLE_RATE 16000
#define BUFFER_SIZE 1024

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data
typedef struct {
    int16_t left;
    int16_t right;
} audio_sample_t;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float apply_gain(float sample, float gain);
void process_audio(audio_sample_t *buffer, int buffer_size, float gain_left, float gain_right);
void print_audio_data(audio_sample_t *buffer, int buffer_size);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Apply gain to audio sample
float apply_gain(float sample, float gain) {
    return sample * gain;
}

// Process audio data for noise cancellation
void process_audio(audio_sample_t *buffer, int buffer_size, float gain_left, float gain_right) {
    for (int i = 0; i < buffer_size; i++) {
        int adc_left = read_mcp3008(MCP3008_CHANNEL_0);
        int adc_right = read_mcp3008(MCP3008_CHANNEL_1);

        if (adc_left == -1 || adc_right == -1) {
            fprintf(stderr, "Error reading ADC values\n");
            continue; // Skip to the next sample
        }

        // Convert ADC values to 16-bit signed integers (assuming 10-bit ADC)
        int16_t left_sample = (int16_t)(adc_left - 512); // Center the values around 0
        int16_t right_sample = (int16_t)(adc_right - 512);

        buffer[i].left = (int16_t)(apply_gain(left_sample, gain_left));
        buffer[i].right = (int16_t)(apply_gain(right_sample, gain_right));
    }
}

// Print audio data to CSV format
void print_audio_data(audio_sample_t *buffer, int buffer_size) {
    for (int i = 0; i < buffer_size; i++) {
        printf("%d,%d\n", buffer[i].left, buffer[i].right);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <gain_value>\n", argv[0]);
        return 1;
    }

    float gain = atof(argv[1]);
    if (gain < GAIN_0 || gain > GAIN_1) {
        fprintf(stderr, "Gain value must be between %f and %f\n", GAIN_0, GAIN_1);
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    audio_sample_t audio_buffer[BUFFER_SIZE];

    while (!terminate) {
        process_audio(audio_buffer, BUFFER_SIZE, gain, gain);
        print_audio_data(audio_buffer, BUFFER_SIZE);
        gpioDelay(1000); // Delay for 1ms (adjust as needed)
    }

    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

