int log_error(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_error("Invalid MCP3008 channel");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Dummy byte

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        log_error("SPI transfer failed");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage (assuming 3.3V reference)
float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1023.0;
}

// Function to read ambient temperature from file
float read_ambient_temperature() {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (fp == NULL) {
        log_error("Failed to open ambient temperature file");
        return DEFAULT_AMBIENT_TEMP;
    }

    float temperature;
    if (fscanf(fp, "%f", &temperature) != 1) {
