    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int raw_adc = -1;
        float voltage = -1.0;
        float temperature = DEFAULT_AMBIENT_TEMP;
        float compensated_voltage = -1.0;
