#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW 70.0
#define READ_INTERVAL_MS 5000 // 5 seconds
#define JSON_FILE "water_levels.json"

// Global variables
int spi_handle;
FILE *json_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_water_level(int adc_value);
void log_data(float water_level);
void control_led(float water_level);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int led_gpio;
    float water_level_threshold_high;
    float water_level_threshold_low;
    int read_interval_ms;
    char json_file[64];
} Config;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (return code %d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate water level percentage
float calculate_water_level(int adc_value) {
    // Assuming ADC range is 0-1023, and water level range is 0-100%
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to JSON file
void log_data(float water_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ldZ", ts.tv_nsec / 1000000);

    fprintf(json_file, "{\"timestamp\": \"%s\", \"water_level\": %.2f}\n", timestamp, water_level);
    fflush(json_file); // Ensure data is written to file immediately
}

// Function to control LED based on water level
void control_led(float water_level) {
    if (water_level > WATER_LEVEL_THRESHOLD_HIGH) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else if (water_level < WATER_LEVEL_THRESHOLD_LOW) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (return code %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open JSON file for appending
    json_file = fopen(JSON_FILE, "a");
    if (json_file == NULL) {
        fprintf(stderr, "Error: Failed to open JSON file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write opening bracket for JSON array
    fprintf(json_file, "[\n");
    fflush(json_file);

    return 0;
}

// Cleanup function
void cleanup() {
    // Close SPI channel
    spiClose(spi_handle);

    // Turn off LED
    gpioWrite(LED_GPIO, 0);

    // Close JSON file
    if (json_file != NULL) {
        fprintf(json_file, "]\n");
        fclose(json_file);
    }

    // Terminate pigpio library
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            // Optionally add a delay before retrying
            gpioDelay(100); // 100ms delay
            continue; // Skip to the next iteration
        }

        // Calculate water level
        float water_level = calculate_water_level(adc_value);

        // Log data
        log_data(water_level);

        // Control LED
        control_led(water_level);

        // Sleep for the specified interval
        gpioDelay(READ_INTERVAL_MS); // Delay in milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

