#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define MIN_ADC 300
#define MAX_ADC 700
#define MOISTURE_THRESHOLD 30
#define LOGGING_INTERVAL 60 // seconds
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with actual email
#define MSMTP_CONFIG_FILE "/etc/msmtp/msmtp.conf" // Or another valid msmtp config file

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_moisture(int adc_value, int min_adc, int max_adc);
void log_data(float moisture);
void send_email_alert(float moisture);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to moisture percentage
float adc_to_moisture(int adc_value, int min_adc, int max_adc) {
    float moisture = 100.0 - ((float)(adc_value - min_adc) / (float)(max_adc - min_adc)) * 100.0;
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;
    return moisture;
}

// Function to log data to file
void log_data(float moisture) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send email alert using msmtp
void send_email_alert(float moisture) {
    char command[256];
    snprintf(command, sizeof(command), "echo \"Subject: Plant Alert\n\nMoisture level: %.2f%%\" | msmtp -t %s", moisture, EMAIL_RECIPIENT);
    int status = popen(command, "r");
    if (status == -1) {
        fprintf(stderr, "Error: Failed to execute msmtp command\n");
    } else {
        int exit_status = pclose(status);
        if (exit_status != 0) {
            fprintf(stderr, "Error: msmtp command exited with status %d\n", exit_status);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 500000, 0); // SPI channel, baud rate, flags
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle = %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("plant_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int spi_channel = SPI_CHANNEL;
    int adc_channel = ADC_CHANNEL;
    int min_adc = MIN_ADC;
    int max_adc = MAX_ADC;
    int moisture_threshold = MOISTURE_THRESHOLD;
    int logging_interval = LOGGING_INTERVAL;
    char *email_recipient = EMAIL_RECIPIENT;
    char msmtp_config_path[256] = MSMTP_CONFIG_FILE;

    // Check for command-line arguments
    if (argc > 1) {
        spi_channel = atoi(argv[1]);
    }
    if (argc > 2) {
        adc_channel = atoi(argv[2]);
    }
    if (argc > 3) {
        min_adc = atoi(argv[3]);
    }
    if (argc > 4) {
        max_adc = atoi(argv[4]);
    }
    if (argc > 5) {
        moisture_threshold = atoi(argv[5]);
    }
    if (argc > 6) {
        logging_interval = atoi(argv[6]);
    }
    if (argc > 7) {
        email_recipient = argv[7];
    }
    if (argc > 8) {
        strcpy(msmtp_config_path, argv[8]);
    }

    // Validate arguments
    if (spi_channel < 0 || spi_channel > 7) {
        fprintf(stderr, "Error: Invalid SPI channel %d\n", spi_channel);
        return 1;
    }
    if (adc_channel < 0 || adc_channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", adc_channel);
        return 1;
    }
    if (min_adc < 0 || min_adc > 1023) {
        fprintf(stderr, "Error: Invalid minimum ADC value %d\n", min_adc);
        return 1;
    }
    if (max_adc < 0 || max_adc > 1023) {
        fprintf(stderr, "Error: Invalid maximum ADC value %d\n", max_adc);
        return 1;
    }
    if (moisture_threshold < 0 || moisture_threshold > 100) {
        fprintf(stderr, "Error: Invalid moisture threshold %d\n", moisture_threshold);
        return 1;
    }
    if (logging_interval < 0) {
        fprintf(stderr, "Error: Invalid logging interval %d\n", logging_interval);
        return 1;
    }

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to moisture percentage
        float moisture = adc_to_moisture(adc_value, min_adc, max_adc);

        // Log data
        log_data(moisture);

        // Check moisture threshold and send email alert
        if (moisture < moisture_threshold) {
            send_email_alert(moisture);
        }

        // Wait for the next logging interval
        sleep(logging_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

