#include <sys/stat.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// SPI device settings
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// MCP3008 channel
#define MCP3008_CHANNEL 0

// Moisture percentage calculation parameters
#define ADC_MAX 1023
#define MOISTURE_MAX 100

// Global variables
int spi_fd = -1; // SPI file descriptor
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    int mode;
    int bits_per_word;
    int speed;
} spi_config_t;

// Function prototypes
int spi_init(spi_config_t *config);
int spi_read_adc(int channel);
float calculate_moisture_percentage(int adc_value);
void log_data(int adc_value, float moisture_percentage);
void signal_handler(int signal);

// SPI initialization function
int spi_init(spi_config_t *config) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &config->mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &config->bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &config->speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read ADC function
int spi_read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Moisture percentage calculation function
float calculate_moisture_percentage(int adc_value) {
    return ((float)adc_value / ADC_MAX) * MOISTURE_MAX;
}

// Data logging function
void log_data(int adc_value, float moisture_percentage) {
    printf("Raw ADC Value: %d, Moisture Percentage: %.2f%%\n", adc_value, moisture_percentage);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // SPI configuration
    spi_config_t spi_config = {
        .mode = SPI_MODE,
        .bits_per_word = SPI_BITS_PER_WORD,
        .speed = SPI_SPEED
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(&spi_config);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("Soil Moisture Sensor Reader\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = spi_read_adc(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Log data
        log_data(adc_value, moisture_percentage);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    close(spi_fd);
    printf("Exiting cleanly.\n");

    return 0;
}

