#include <pigpio.h>

// Define GPIO pins
#define SPI_CE0 8  // GPIO8 (BCM)
#define SPI_CE1 7  // GPIO7 (BCM)
#define SPI_MOSI 10 // GPIO10 (BCM)
#define SPI_MISO 9 // GPIO9 (BCM)
#define SPI_SCLK 11 // GPIO11 (BCM)

// Define SPI channel
#define SPI_CHANNEL_CE0 0
#define SPI_CHANNEL_CE1 1

// Define SPI baud rate
#define SPI_BAUD_RATE 1000000 // 1 MHz

// Define pressure sensor parameters
#define ADC_MAX_VALUE 1023.0
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 1000.0

// Define sensor absent voltage thresholds
#define SENSOR_ABNENT_VOLTAGE_LOW 0.0
#define SENSOR_ABNENT_VOLTAGE_HIGH 3.3

// Global variables
int spi_handle_ce0 = -1;
int spi_handle_ce1 = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    float pressure;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_spi(int ce_pin, int channel);
int read_adc(int spi_handle, int channel);
float convert_adc_to_pressure(int adc_value);
void log_sensor_data(int sensor_id, float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi(int ce_pin, int channel) {
    int handle = spiOpen(channel, SPI_BAUD_RATE, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "SPI initialisation failed for channel %d (CE%d)\n", channel, ce_pin);
        return -1;
    }
    return handle;
}

// Function to read ADC value from MCP3008
int read_adc(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to pressure
float convert_adc_to_pressure(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0;
    }
    return PRESSURE_MIN + (float)adc_value * (PRESSURE_MAX - PRESSURE_MIN) / ADC_MAX_VALUE;
}

// Function to log sensor data
void log_sensor_data(int sensor_id, float pressure) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    printf("%s, Sensor ID: %d, Pressure: %.2f\n", buf, sensor_id, pressure);
}

