#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LOG_INTERVAL 5 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(int channel, int speed);
int spi_read_adc(int channel);
float calculate_moisture(int adc_value);
void log_moisture(float moisture);
void signal_handler(int signal);

// Structure for SPI configuration (optional, but good practice)
typedef struct {
    int channel;
    int speed;
} spi_config_t;

// SPI initialization function
int spi_init(int channel, int speed) {
    spi_handle = spiOpen(channel, speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return spi_handle;
}

// SPI read ADC function
int spi_read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 single-ended read)
    uint8_t spi_tx_buf[3];
    uint8_t spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Calculate moisture percentage function
float calculate_moisture(int adc_value) {
    // Assuming ADC range is 0-1023
    float moisture = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture;
}

// Log moisture data function
void log_moisture(float moisture) {
    printf("Moisture: %.2f%%\n", moisture);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init(SPI_CHANNEL, SPI_SPEED) < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = spi_read_adc(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Try again
        }

        // Calculate moisture percentage
        float moisture = calculate_moisture(adc_value);

        // Clamp moisture value
        if (moisture < 0.0) moisture = 0.0;
        if (moisture > 100.0) moisture = 100.0;

        // Log moisture data
        log_moisture(moisture);

        // Wait for the next reading
        sleep(LOG_INTERVAL);
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

