#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0" // SPI device file
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_SENSORS 4
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int channel;
    float voltage;
} sensor_data_t;

// Function prototypes
int spi_init(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_mcp3008(int fd, int channel);
float adc_to_voltage(int adc_value);
int log_data(FILE *fp, sensor_data_t *sensor_data, int num_sensors);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }
    return 0;
}

// Read MCP3008 Channel
int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) == -1) {
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to Voltage Conversion
float adc_to_voltage(int adc_value) {
    return (adc_value * 3.3) / 1024.0;
}

// Log Data to CSV File
int log_data(FILE *fp, sensor_data_t *sensor_data, int num_sensors) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s", timestamp);
    for (int i = 0; i < num_sensors; i++) {
        fprintf(fp, ",%.2f", sensor_data[i].voltage);
    }
    fprintf(fp, "\n");
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Cleanup Resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd == -1) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Sensor1,Sensor2,Sensor3,Sensor4\n");
    }

    sensor_data_t sensor_data[NUM_SENSORS];

    // Main loop
    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(spi_fd, i);
            if (adc_value == -1) {
                fprintf(stderr, "Error reading sensor %d, skipping.\n", i);
                sensor_data[i].voltage = -1.0; // Indicate error
            } else {
                sensor_data[i].voltage = adc_to_voltage(adc_value);
            }
        }

        log_data(log_file, sensor_data, NUM_SENSORS);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

