#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;
int pump_state = 0; // 0 = off, 1 = on

// Structure for circular buffer
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
void control_pump(int moisture_level);
void log_data(int moisture_level, int pump_state);
void print_buffer();
void signal_handler(int signal);
void timer_callback();

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    int result = spiXfer(spi_handle, spi_data, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to control the water pump
void control_pump(int moisture_level) {
    if (moisture_level < LOW_THRESHOLD && pump_state == 0) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump on
        pump_state = 1;
        printf("Pump turned ON\n");
    } else if (moisture_level > HIGH_THRESHOLD && pump_state == 1) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump off
        pump_state = 0;
        printf("Pump turned OFF\n");
    }
}

// Function to log data to the circular buffer
void log_data(int moisture_level, int pump_state) {
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        time_t timestamp = log_buffer[i].timestamp;
        struct tm *timeinfo = localtime(&timestamp);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Moisture: %d, Pump: %s\n", time_str, log_buffer[i].moisture_level, log_buffer[i].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Timer callback function
void timer_callback() {
    int moisture_level = read_mcp3008(0);
    if (moisture_level < 0) {
        fprintf(stderr, "Failed to read moisture level\n");
        return;
    }

    control_pump(moisture_level);
    log_data(moisture_level, pump_state);
    print_buffer();

    gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 5 seconds
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the system
    if (initialize()) {
        return 1;
    }

    // Set up timer callback
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL * 1000, timer_callback, NULL); // Timer 0, every SAMPLE_INTERVAL seconds

    printf("Soil Moisture Monitoring and Pump Control\n");

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep to reduce CPU usage
    }

    // Cleanup
    gpioWrite(PUMP_GPIO, 0); // Turn pump off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

