// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_max30102();
int read_spo2();
int read_hr();
void log_data(int spo2, int hr);
void signal_handler(int signal);
int verify_sensor();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Verify sensor presence
int verify_sensor() {
    int part_id;
    part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x07) {
        fprintf(stderr, "Error: Invalid Part ID (0x%02X). Sensor may be missing or malfunctioning.\n", part_id);
        return -1;
    }
    printf("MAX30102 sensor found (Part ID: 0x%02X).\n", part_id);
    return 0;
}

// Initialize MAX30102
