    // Reset the device
    if (i2cWriteByteData(i2c_handle, 0x00, 0x40) < 0) {
        fprintf(stderr, "Error: Failed to reset MAX30102.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure the sensor
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x03) < 0) { // SPO2 mode
        fprintf(stderr, "Error: Failed to set SPO2 mode.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x08, 0x27) < 0) { // LED pulse width
