#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3         // Reference voltage
#define LOG_FILE "analog_log.csv"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, int channel, float voltage);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    float vref;
    char *log_file;
    int retry_count;
    int retry_delay_ms;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    VREF,
    LOG_FILE,
    RETRY_COUNT,
    RETRY_DELAY_MS
};

// Function to read from MCP3008 channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * config.vref;
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // YYYY-MM-DDTHH:MM:SSZ\0

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log data to CSV file
int log_data(const char *timestamp, int channel, float voltage) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%.3f\n", timestamp, channel, voltage);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // CE0, SPI0, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", config.log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Channel,Voltage\n");
    fflush(log_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Starting data logging...\n");

    // Main loop
    while (!terminate) {
        for (int channel = 0; channel < 3; channel++) {
            int adc_value = -1;
            for (int i = 0; i < config.retry_count; i++) {
                adc_value = read_mcp3008(channel);
                if (adc_value >= 0) {
                    break; // Success, exit retry loop
                } else {
                    fprintf(stderr, "Error: MCP3008 read failed for channel %d, retry %d\n", channel, i + 1);
                    gpioDelay(config.retry_delay_ms * 1000); // Delay in microseconds
                }
            }

            if (adc_value >= 0) {
                float voltage = convert_to_voltage(adc_value);
                char *timestamp = get_iso8601_timestamp();
                if (log_data(timestamp, channel, voltage) != 0) {
                    fprintf(stderr, "Error: Failed to log data for channel %d\n", channel);
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Error: Failed to read from channel %d after multiple retries\n", channel);
            }
        }

        gpioDelay(500000); // 500 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

