// Define GPIO pins
#define BUZZER_PIN 24
#define SPI_CE0 8
#define SPI_CE1 7

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000

// Define threshold value
#define THRESHOLD 500

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
void control_buzzer(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Open SPI channel CE0
    spi_handle = spiOpen(SPI_CE0, SPI_BAUD, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    // Construct SPI message
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to control the buzzer
void control_buzzer(int state) {
    gpioWrite(BUZZER_PIN, state);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("MQ-2 Gas Sensor Monitoring\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Continue to the next iteration
        }

        // Control buzzer based on threshold
        if (adc_value >= THRESHOLD) {
            control_buzzer(1); // Turn buzzer on
        } else {
            control_buzzer(0); // Turn buzzer off
        }

        // Print ADC value
        printf("ADC Value: %d\n", adc_value);

        // Wait for 500ms
        gpioDelay(500); // pigpio's delay function
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

