#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY 50 // milliseconds
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
bool running = true;

// Calibration data
int16_t baseline_values[CALIBRATION_SAMPLES];
int baseline_index = 0;

// Function prototypes
int16_t read_ads1115(int fd, int channel);
int16_t calibrate_sensor(int fd);
int16_t calculate_distance(int16_t adc_value);
bool is_door_open(int gpio, int pull);
void activate_relay(int gpio, int duration);
void log_event(const char *event);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read from ADS1115 ADC
int16_t read_ads1115(int fd, int channel) {
    uint8_t config[3];
    int16_t adc_value;
    int retries = I2C_RETRY_COUNT;

    // Configure ADS1115 for single-ended input on the specified channel
    config[0] = 0x01; // Configuration register
    config[1] = (0x40 | (channel << 4)) | 0x80; // Single-ended, AIN0/AIN1, start single conversion
    config[2] = 0x83; // 128 SPS, +/-4.096V, Disable comparator

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
            perror("Error: I2C_SLAVE");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        if (write(fd, config, 3) != 3) {
            perror("Error: I2C write");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        usleep(9000); // Wait for conversion (at least 8ms)

        if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
            perror("Error: I2C_SLAVE");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        uint8_t data[2];
        if (read(fd, data, 2) != 2) {
            perror("Error: I2C read");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        adc_value = (data[0] << 8) | data[1];
        return adc_value;
    }

    fprintf(stderr, "Error: Failed to read ADS1115 after multiple retries.\n");
    return 0; // Return 0 on failure
}

