        gpioTerminate();
        return -1;
    }

    // Calibrate the sensor
    calibrate_sensor(i2c_fd);

    // Open log file
    log_file = fopen("/var/log/door_events.log", "a");
    if (log_file == NULL) {
        perror("Error: Could not open log file");
        close(i2c_fd);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Deactivate relay
    gpioWrite(RELAY_GPIO, 0);

    // Close I2C bus
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

