    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup() != 0) {
        fprintf(stderr, "Error: Setup failed, exiting.\n");
        return 1;
    }

    printf("Door access control system started.\n");

    while (running) {
        // Read ADC value
        int16_t adc_value = read_ads1115(i2c_fd, 0); // Read from channel 0
        if (adc_value == 0) {
            fprintf(stderr, "Error: Failed to read ADC value.\n");
            continue; // Skip to the next iteration
        }

        // Calculate distance
        int16_t distance = calculate_distance(adc_value);

        // Check if distance is below threshold
        if (distance < THRESHOLD) {
            printf("Distance below threshold (%d < %d). Activating relay.\n", distance, THRESHOLD);

            // Activate relay
            activate_relay(RELAY_GPIO, PULSE_DURATION);

            // Read door sensor
            bool door_open = is_door_open(DOOR_SENSOR_GPIO, PI_PUD_UP);

            // Log event
            if (door_open) {
                log_event("door opened");
            } else {
                log_event("door not opened");
            }
        }

        usleep(SAMPLE_INTERVAL * 1000); // Sample every 200ms
    }

    cleanup();
    printf("Door access control system stopped.\n");
    return 0;
}

