#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <pigpio.h>

// Define GPIO pins for chip select
#define CS0 8
#define CS1 7
#define CS2 25

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define ADC channel
#define ADC_CHANNEL 0

// Define CSV file name
#define CSV_FILE "soil_moisture_log.csv"

// Global variables
int spi_fd = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_open(int channel, int speed, int mode);
int spi_read_adc(int spi_fd, int channel);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);
int initialize_gpio(void);
int cleanup_gpio(void);

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int speed;
    int mode;
} spi_config_t;

// Function to open SPI interface
int spi_open(int channel, int speed, int mode) {
    int fd = spiOpen(channel, speed, mode);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, fd);
        return -1;
    }
    return fd;
}

// Function to read ADC value from MCP3008
int spi_read_adc(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    if (spiXfer(spi_fd, &tr, &tr, 3) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log data to CSV file
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(CS0, PI_OUTPUT);
    gpioSetMode(CS1, PI_OUTPUT);
    gpioSetMode(CS2, PI_OUTPUT);

    gpioWrite(CS0, 1);
    gpioWrite(CS1, 1);
    gpioWrite(CS2, 1);

    return 0;
}

// Function to cleanup GPIO pins
int cleanup_gpio(void) {
    gpioWrite(CS0, 1);
    gpioWrite(CS1, 1);
    gpioWrite(CS2, 1);
    gpioTerminate();
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open SPI interface
    spi_fd = spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        cleanup_gpio();
        return 1;
    }

    // Open CSV file
    fp = fopen(CSV_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", CSV_FILE);
        spiClose(spi_fd);
        cleanup_gpio();
        return 1;
    }

    // Check if the file is newly created and write the header
    struct stat buffer;
    if (stat(CSV_FILE, &buffer) == 0 && buffer.st_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");
    }

    // Main loop
    while (!terminate) {
        int sensor1_value = -1, sensor2_value = -1, sensor3_value = -1;

        // Read sensor 1
        sensor1_value = spi_read_adc(spi_fd, ADC_CHANNEL);
        if (sensor1_value < 0) {
            fprintf(stderr, "Error reading sensor 1\n");
        }

        // Read sensor 2
        sensor2_value = spi_read_adc(spi_fd, ADC_CHANNEL);
        if (sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor 2\n");
        }

        // Read sensor 3
        sensor3_value = spi_read_adc(spi_fd, ADC_CHANNEL);
        if (sensor3_value < 0) {
            fprintf(stderr, "Error reading sensor 3\n");
        }

        // Log data to file
        if (log_data(fp, sensor1_value, sensor2_value, sensor3_value) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    fclose(fp);
    spiClose(spi_fd);
    cleanup_gpio();

    return 0;
}

