    tr.bits_per_word = 8;

    if (spiXfer(spi_fd, &tr, &tr, 3) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log data to CSV file
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(CS0, PI_OUTPUT);
    gpioSetMode(CS1, PI_OUTPUT);
    gpioSetMode(CS2, PI_OUTPUT);

    gpioWrite(CS0, 1);
    gpioWrite(CS1, 1);
    gpioWrite(CS2, 1);

    return 0;
}

// Function to cleanup GPIO pins
int cleanup_gpio(void) {
    gpioWrite(CS0, 1);
    gpioWrite(CS1, 1);
    gpioWrite(CS2, 1);
    gpioTerminate();
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open SPI interface
    spi_fd = spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        cleanup_gpio();
        return 1;
    }

    // Open CSV file
    fp = fopen(CSV_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", CSV_FILE);
        spiClose(spi_fd);
        cleanup_gpio();
        return 1;
    }

    // Check if the file is newly created and write the header
    struct stat buffer;
    if (stat(CSV_FILE, &buffer) == 0 && buffer.st_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");
    }

    // Main loop
    while (!terminate) {
        int sensor1_value = -1, sensor2_value = -1, sensor3_value = -1;

        // Read sensor 1
        sensor1_value = spi_read_adc(spi_fd, ADC_CHANNEL);
        if (sensor1_value < 0) {
            fprintf(stderr, "Error reading sensor 1\n");
        }

        // Read sensor 2
        sensor2_value = spi_read_adc(spi_fd, ADC_CHANNEL);
        if (sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor 2\n");
        }

        // Read sensor 3
        sensor3_value = spi_read_adc(spi_fd, ADC_CHANNEL);
        if (sensor3_value < 0) {
            fprintf(stderr, "Error reading sensor 3\n");
        }

        // Log data to file
        if (log_data(fp, sensor1_value, sensor2_value, sensor3_value) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    fclose(fp);
    spiClose(spi_fd);
    cleanup_gpio();

    return 0;
}

