#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 18
#define LOG_FILE "irrigation.log"

// Default values
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60

// Global variables
int spi_handle;
int threshold = DEFAULT_THRESHOLD;
int pump_duration = DEFAULT_DURATION;
int sleep_interval = DEFAULT_SLEEP_INTERVAL;
FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
int calculate_moisture_percentage(int adc_value);
void control_pump(int activate);
void log_message(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    int retries = 3;
    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            log_message("SPI communication error. Retrying...");
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    log_message("Error: SPI communication failed after multiple retries.");
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
int calculate_moisture_percentage(int adc_value) {
    // Assuming 0-1023 ADC value corresponds to 0-3V
    // 0V = 0%, 3V = 100%
    return (int)(((float)adc_value / 1023.0) * 100.0);
}

// Function to control the water pump
void control_pump(int activate) {
    gpioWrite(RELAY_GPIO, activate);
    log_message(activate ? "Pump activated" : "Pump deactivated");
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure the message is written to the file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Received signal, shutting down...");
    control_pump(0); // Ensure pump is off
    cleanup();
    exit(0);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output for the relay
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_message("System initialized successfully.");
    return 0;
}

// Cleanup function
void cleanup() {
    log_message("Cleaning up...");
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                pump_duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the system
    if (initialize()) {
        return 1;
    }

    log_message("Starting irrigation control...");

    // Main loop
    while (1) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_message("Error reading ADC value, skipping irrigation cycle.");
            gpioDelay(sleep_interval * 1000); // Sleep even if ADC read fails
            continue;
        }

        int moisture_percentage = calculate_moisture_percentage(adc_value);

        char log_buffer[100];
        snprintf(log_buffer, sizeof(log_buffer), "Moisture percentage: %d%%", moisture_percentage);
        log_message(log_buffer);

        if (moisture_percentage < threshold) {
            control_pump(1); // Activate pump
            gpioDelay(pump_duration * 1000); // Run pump for specified duration
            control_pump(0); // Deactivate pump
        }

        gpioDelay(sleep_interval * 1000); // Wait before next check
    }

    return 0;
}

