#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "/var/log/sound_events.log"
#define DYNAMIC_THRESHOLD 500
#define NUM_SAMPLES 100

// GPIO pins
#define CE0 8
#define CLK 11
#define MOSI 10
#define MISO 9

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int speed;
} spi_config_t;

// Function prototypes
int initialize_spi(spi_config_t config);
int read_mcp3008(int channel);
int detect_peak(int sample, int threshold, int *history, int history_size);
int log_event(int sample);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize SPI
int initialize_spi(spi_config_t config) {
    spi_handle = spiOpen(config.channel, config.speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read MCP3008 channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Detect peak
int detect_peak(int sample, int threshold, int *history, int history_size) {
    if (sample > threshold) {
        // Check if the sample is higher than the maximum in the history
        int max_in_history = 0;
        for (int i = 0; i < history_size; i++) {
            if (history[i] > max_in_history) {
                max_in_history = history[i];
            }
        }

        if (sample > max_in_history) {
            return 1; // Peak detected
        }
    }
    return 0; // No peak detected
}

// Log event
int log_event(int sample) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    fprintf(log_file, "%s, %d\n", timestamp, sample);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_config_t spi_config = {SPI_CHANNEL, SPI_SPEED};
    if (initialize_spi(spi_config) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    int history[NUM_SAMPLES];
    for (int i = 0; i < NUM_SAMPLES; i++) {
        history[i] = 0; // Initialize history
    }

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Update history
        history[0] = adc_value; // Shift history
        for (int i = 1; i < NUM_SAMPLES; i++) {
            history[i] = history[i - 1];
        }

        // Detect peak
        if (detect_peak(adc_value, DYNAMIC_THRESHOLD, history, NUM_SAMPLES)) {
            // Log event
            if (log_event(adc_value) != 0) {
                fprintf(stderr, "Error logging event\n");
            }
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Sound level monitoring stopped.\n");
    return 0;
}

