#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GAIN_4_096V 0x4000 // +/- 4.096V
#define VOLTAGE_RANGE 3.3
#define THRESHOLD_GAUSS 500.0
#define GPIO_PIN 27
#define SAMPLE_RATE_HZ 1
#define BUFFER_SIZE 10

// Global variables
static int i2c_fd;
static volatile sig_atomic_t program_running = 1;

// Circular buffer
static float buffer[BUFFER_SIZE];
static int buffer_index = 0;

// Function prototypes
int init_i2c();
int16_t read_adc();
float convert_to_voltage(int16_t adc_value);
float convert_to_gauss(float voltage);
void update_buffer(float value);
bool check_threshold(float gauss_value);
void control_gpio(bool on);
void log_message(int priority, const char *message);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(ADS1115_ADDR);
    if (i2c_fd == -1) {
        log_message(LOG_ERR, "Failed to initialize I2C.");
        return -1;
    }
    log_message(LOG_INFO, "I2C initialized successfully.");
    return 0;
}

// Function to read ADC value
int16_t read_adc() {
    int16_t adc_value;
    int config = GAIN_4_096V | 0x8000 | 0x4000; // Single-ended AIN0, 4.096V, Continuous conversion

    if (wiringPiI2CWriteReg16(i2c_fd, CONFIG_REG, config) == -1) {
        log_message(LOG_ERR, "Failed to write to configuration register.");
        return -1;
    }

    delay(10); // Wait for conversion

    adc_value = wiringPiI2CReadReg16(i2c_fd, CONVERSION_REG);
    if (adc_value == -1) {
        log_message(LOG_ERR, "Failed to read ADC value.");
        return -1;
    }

    // ADS1115 returns MSB first, so swap bytes
    adc_value = (adc_value >> 8) | (adc_value << 8);

    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int16_t adc_value) {
    float voltage = (float)adc_value * VOLTAGE_RANGE / 32768.0;
    return voltage;
}

// Function to convert voltage to magnetic field strength (Gauss)
float convert_to_gauss(float voltage) {
    // Assuming a linear relationship between voltage and magnetic field
    // This is a placeholder; you'll need to calibrate the sensor and determine the actual relationship.
    // Example: 1V = 1000 Gauss, 0V = 0 Gauss
    float gauss = voltage * 1000.0; // Example conversion
    return gauss;
}

// Function to update the circular buffer
void update_buffer(float value) {
    buffer[buffer_index] = value;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check if the threshold is exceeded
bool check_threshold(float gauss_value) {
    return gauss_value > THRESHOLD_GAUSS;
}

// Function to control GPIO pin
void control_gpio(bool on) {
    digitalWrite(GPIO_PIN, on ? HIGH : LOW);
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
    control_gpio(false); // Turn off GPIO
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    closelog();
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        log_message(LOG_ERR, "Failed to initialize wiringPi.");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    // Configure GPIO pin as output
    pinMode(GPIO_PIN, OUTPUT);
    control_gpio(false); // Ensure it starts LOW

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message(LOG_INFO, "Program started.");

    // Main loop
    while (program_running) {
        int16_t adc_value = read_adc();
        if (adc_value != -1) {
            float voltage = convert_to_voltage(adc_value);
            float gauss = convert_to_gauss(voltage);

            log_message(LOG_INFO, "ADC Value: %d, Voltage: %.3f V, Gauss: %.3f G", adc_value, voltage, gauss);

            update_buffer(gauss);

            if (check_threshold(gauss)) {
                log_message(LOG_WARNING, "Threshold exceeded! Shutting down motor.");
                control_gpio(true); // Turn on GPIO
            } else {
                control_gpio(false); // Turn off GPIO
            }
        } else {
            log_message(LOG_ERR, "Failed to read ADC value, skipping.");
        }

        delay(1000 / SAMPLE_RATE_HZ); // Sample at 1 Hz
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_gpio(false);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    closelog();

    return 0;
}

