#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 18
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10 // seconds
#define READ_INTERVAL 60      // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int control_gpio(int gpio, int level);
int log_event(int moisture_level);
void signal_handler(int signal);
int validate_channel(int channel);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, shutting down...\n");
}

// Validate ADC channel
int validate_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }
    return 0;
}

// Read MCP3008 ADC
int read_mcp3008(int channel) {
    if (validate_channel(channel) != 0) {
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Control GPIO
int control_gpio(int gpio, int level) {
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Log event
int log_event(int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Moisture Level: %d\n", timestamp, moisture_level);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("watering_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read moisture level
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            continue; // Skip to the next iteration
        }

        // Validate moisture level
        if (moisture_level < 0 || moisture_level > 1023) {
            fprintf(stderr, "Warning: Invalid moisture level %d, skipping watering\n", moisture_level);
            log_event(moisture_level);
            sleep(READ_INTERVAL);
            continue;
        }

        // Check if below threshold
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold (%d < %d). Activating pump.\n", moisture_level, MOISTURE_THRESHOLD);

            // Activate pump
            if (control_gpio(RELAY_GPIO, 1) != 0) {
                fprintf(stderr, "Error: Failed to activate pump\n");
            } else {
                sleep(WATERING_DURATION);
                printf("Pump deactivated.\n");

                // Deactivate pump
                if (control_gpio(RELAY_GPIO, 0) != 0) {
                    fprintf(stderr, "Error: Failed to deactivate pump\n");
                }

                // Log event
                log_event(moisture_level);
            }
        }

        // Wait before next reading
        sleep(READ_INTERVAL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_gpio(RELAY_GPIO, 0); // Ensure pump is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

