#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SPI_CE0 8  // CE0 connected to GPIO8 (BCM)
#define SPI_CE1 7  // CE1 connected to GPIO7 (BCM)
#define PWM_PIN 18 // PWM output connected to GPIO18 (BCM)

// SPI configuration
#define SPI_CHANNEL 0 // SPI0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0      // Mode 0

// PWM configuration
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1024      // 0-1023 duty cycle

// Global variables
int spi_handle0, spi_handle1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_adc(int spi_handle, int channel);
int calculate_pwm_value(int adc_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read ADC value from MCP3008
int spi_read_adc(int spi_handle, int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;                  // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate PWM value
int calculate_pwm_value(int adc_value) {
    return (int)(((float)adc_value / 1023.0) * PWM_RANGE);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure PWM pin as output
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Open SPI channels
    spi_handle0 = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle0 < 0) {
        fprintf(stderr, "SPI0 open failed: %d\n", spi_handle0);
        gpioTerminate();
        return 1;
    }

    spi_handle1 = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle1 < 0) {
        fprintf(stderr, "SPI1 open failed: %d\n", spi_handle1);
        spiClose(spi_handle0);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values from both channels
        int adc_value0 = spi_read_adc(spi_handle0, 0);
        int adc_value1 = spi_read_adc(spi_handle1, 0);

        // Calculate PWM values
        int pwm_value0 = calculate_pwm_value(adc_value0);
        int pwm_value1 = calculate_pwm_value(adc_value1);

        // Set PWM values
        gpioPWM(PWM_PIN, pwm_value0);
        gpioPWM(PWM_PIN, pwm_value1);

        // Print results
        printf("ADC0: %d, PWM0: %d\n", adc_value0, pwm_value0);
        printf("ADC1: %d, PWM1: %d\n", adc_value1, pwm_value1);

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up
    spiClose(spi_handle0);
    spiClose(spi_handle1);
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();

    return 0;
}

