#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_LED 17
#define DEFAULT_THRESHOLD 100.0
#define BLINK_DURATION 1000 // milliseconds
#define BLINK_FREQUENCY 2     // Hz

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int configure_ads1115();
int read_magnetic_field(double *field_strength);
void blink_led();
void signal_handler(int signal);
void cleanup();

// Structure for ADS1115 configuration
typedef struct {
    uint8_t config_reg;
    uint16_t gain;
    uint16_t single_differential;
    uint16_t os;
    uint16_t pga;
} ads1115_config_t;

// Function to initialize the ADS1115
int configure_ads1115() {
    ads1115_config_t config = {
        .config_reg = 0x83, // Single-ended AIN0, PGA 4.096V, 128 SPS, Start single conversion
        .gain = 0x04,       // PGA 4.096V
        .single_differential = 0x00, // Single-ended
        .os = 0x03,         // 128 SPS
        .pga = 0x03          // PGA 4.096V
    };

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config.gain << 12) | (config.pga << 8) | config.single_differential | config.os;
    buf[2] = 0x83; // Configuration register value

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 configuration register\n");
        return -1;
    }

    return 0;
}

// Function to read the magnetic field strength from the ADS1115
int read_magnetic_field(double *field_strength) {
    char buf[1];
    char read_buf[2];
    int16_t adc_value;

    buf[0] = CONVERSION_REG;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to ADS1115 conversion register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register\n");
        return -1;
    }

    adc_value = (read_buf[0] << 8) | read_buf[1];

    // Convert ADC value to Gauss (assuming 16-bit ADC and 4.096V range)
    *field_strength = (double)adc_value * 4.096 / 32767.0 / 4.096; // Scale to Gauss

    return 0;
}

// Function to blink the LED
void blink_led() {
    gpioWrite(GPIO_LED, 1); // Turn LED on
    gpioDelay(50);          // Wait 50ms
    gpioWrite(GPIO_LED, 0); // Turn LED off
    gpioDelay(50);          // Wait 50ms
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    double field_strength;

    // Parse command-line arguments
    if (argc > 1) {
        threshold = atof(argv[1]);
        printf("Threshold set to: %.2f Gauss\n", threshold);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        fprintf(stderr, "ADS1115 configuration failed\n");
        cleanup();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_magnetic_field(&field_strength) == 0) {
            printf("Magnetic Field Strength: %.2f Gauss\n", field_strength);

            if (field_strength > threshold) {
                blink_led();
            }
        } else {
            fprintf(stderr, "Error reading magnetic field\n");
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

