#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define MCP3008 channel numbers
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define MCP3008_CHANNEL_2 2

// Define VREF (Reference Voltage)
#define VREF 3.3

// Global variables for SPI handle and file pointer
int spi_handle = -1;
FILE *fp = NULL;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value, float vref);
char* get_timestamp();
int write_to_csv(char *timestamp, float voltage0, float voltage1, float voltage2);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float voltage0;
    float voltage1;
    float voltage2;
} sensor_data_t;

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    uint8_t tx_buffer[3];
    uint8_t rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value, float vref) {
    return (adc_value / 1023.0) * vref;
}

// Function to get timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Static to persist across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to write data to CSV file
int write_to_csv(char *timestamp, float voltage0, float voltage1, float voltage2) {
    if (fp == NULL) {
        fprintf(stderr, "File pointer is NULL\n");
        return -1;
