#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <wiringPiI2C.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define ADC_CHANNEL 0
#define LOG_FILE "tamper_log.csv"
#define ERROR_CODE -1
#define SLEEP_DURATION 5 // seconds

// Global variables
static volatile int keepRunning = 1;
static int i2c_fd;
static int spi_fd;

// Function prototypes
int read_mcp3008(int channel);
float read_bh1750();
void log_data(FILE *fp, int sound_level, float light_level, int error_code);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = -1; // Initialize to error value

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI read failed\n");
        return ERROR_CODE;
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to read from BH1750 sensor
float read_bh1750() {
    int lux = -1; // Initialize to error value
    int data[2];

    if (wiringPiI2CWrite(i2c_fd, BH1750_CONTINUOUS_HIGH_RES_MODE) == -1) {
        fprintf(stderr, "Failed to set BH1750 mode\n");
        return ERROR_CODE;
    }

    delay(180); // Wait for measurement (at least 180ms)

    data[0] = wiringPiI2CReadReg8(i2c_fd, 0x00);
    data[1] = wiringPiI2CReadReg8(i2c_fd, 0x01);

    if (data[0] == -1 || data[1] == -1) {
        fprintf(stderr, "Failed to read BH1750 data\n");
        return ERROR_CODE;
    }

    lux = (data[0] << 8) | data[1];

    return (float)lux / 1.2; // Convert to lux
}

// Function to log data to CSV file
void log_data(FILE *fp, int sound_level, float light_level, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%.2f,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    keepRunning = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return -1;
    }

    // Initialize wiringPiSPI
    if ((spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED)) == -1) {
        fprintf(stderr, "wiringPiSPI initialisation failed\n");
        gpioTerminate();
        return -1;
    }

    // Initialize wiringPiI2C
    i2c_fd = wiringPiI2CSetup(BH1750_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2C initialisation failed\n");
        gpioTerminate();
        return -1;
    }

    // Create log file and write header
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return -1;
    }
    fprintf(fp, "Timestamp,Sound Level (dB),Light Level (Lux),Error Code\n");
    fclose(fp);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        // No explicit I2C close function in wiringPi, but we can reset the I2C bus.
        // This might not be necessary, but it's good practice.
        // wiringPiI2CClose(i2c_fd); // Removed as wiringPiI2CClose is not a standard function
    }
    if (spi_fd != -1) {
        // No explicit SPI close function in wiringPi, but we can reset the SPI bus.
        // wiringPiSPIClose(SPI_CHANNEL); // Removed as wiringPiSPIClose is not a standard function
    }
    gpioTerminate();
}

int main() {
    FILE *fp;
    int sound_level;
    float light_level;
    int error_code;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Tamper detection system started. Logging to %s\n", LOG_FILE);

    // Main loop
    while (keepRunning) {
        // Read sensor data
        sound_level = read_mcp3008(ADC_CHANNEL);
        light_level = read_bh1750();

        // Log data
        error_code = 0;
        if (sound_level == ERROR_CODE) {
            fprintf(stderr, "Error reading sound level\n");
            error_code = ERROR_CODE;
        }
        if (light_level == ERROR_CODE) {
            fprintf(stderr, "Error reading light level\n");
            error_code = ERROR_CODE;
        }

        fp = fopen(LOG_FILE, "a");
        if (fp == NULL) {
            fprintf(stderr, "Failed to open log file for appending\n");
            keepRunning = 0; // Exit loop if file opening fails
            continue; // Skip logging this iteration
        }
        log_data(fp, sound_level, light_level, error_code);
        fclose(fp);

        // Sleep for 5 seconds
        sleep(SLEEP_DURATION);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

