#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define NUM_RETRIES 3

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
float calculate_moisture_percentage(float voltage);
void control_pump(float moisture_percentage);
void log_data(float moisture_percentage);
void signal_handler(int signal);
void cleanup();

// Structure for SPI configuration (optional, but good practice)
typedef struct {
    int channel;
    int speed;
} spi_config_t;

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float voltage = convert_to_voltage(adc_value);
            float moisture_percentage = calculate_moisture_percentage(voltage);
            log_data(moisture_percentage);
            control_pump(moisture_percentage);
        } else {
            fprintf(stderr, "Failed to read ADC value. Retrying.\n");
        }
        sleep(60);
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    spi_config_t spi_config = {SPI_CHANNEL, SPI_SPEED};
    spi_handle = spiOpen(spi_config.channel, spi_config.speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

float convert_to_voltage(int adc_value) {
    return (adc_value * 3.3) / 1024.0;
}

float calculate_moisture_percentage(float voltage) {
    // Assuming 0V = 0% and 3.3V = 100%
    return (voltage / 3.3) * 100.0;
}

void control_pump(float moisture_percentage) {
    if (moisture_percentage < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump on
        printf("Pump ON\n");
    } else {
        gpioWrite(PUMP_GPIO, 0); // Turn pump off
        printf("Pump OFF\n");
    }
}

void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Moisture: %.2f%%\n", timestamp, moisture_percentage);
}

void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

