// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VALVE_GPIO 17
#define PWM_FREQUENCY 100 // Hz
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"
#define SAMPLE_DELAY_MS 500
#define LOG_INTERVAL_S 5

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float calculate_average(int sample1, int sample2, int sample3);
void set_valve_position(float average);
void log_data(int sample1, int sample2, int sample3, float average, int valve_position);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int valve_gpio;
    int pwm_frequency;
    int pwm_range;
    char log_file[64];
    int sample_delay_ms;
    int log_interval_s;
} Config;

// Initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate the average of three samples
float calculate_average(int sample1, int sample2, int sample3) {
    if (sample1 == -1 || sample2 == -1 || sample3 == -1) {
        return -1.0; // Indicate failure
    }
    return (float)(sample1 + sample2 + sample3) / 3.0;
}

// Set the valve position using PWM
void set_valve_position(float average) {
    if (average < 0) {
        average = 0;
    } else if (average > 1023) {
        average = 1023;
    }

    int duty_cycle = (int)(average / 10.23); // Map 0-1023 to 0-100
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    gpioPWM(VALVE_GPIO, duty_cycle);
}

// Log data to file
void log_data(int sample1, int sample2, int sample3, float average, int valve_position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %d, %d, %d, %.2f, %d\n", timestamp, sample1, sample2, sample3, average, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(VALVE_GPIO, 0); // Stop PWM
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    printf("Irrigation system started\n");

    while (!terminate) {
        int sample1 = read_mcp3008(0);
        int sample2 = read_mcp3008(1);
        int sample3 = read_mcp3008(2);

        if (sample1 == -1 || sample2 == -1 || sample3 == -1) {
            fprintf(stderr, "Error reading sensor data, skipping this sample\n");
            gpioDelay(SAMPLE_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        float average = calculate_average(sample1, sample2, sample3);
        if (average == -1.0) {
            fprintf(stderr, "Error calculating average, skipping this sample\n");
            gpioDelay(SAMPLE_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        int valve_position = (int)(average / 10.23); // Map 0-1023 to 0-100
        if (valve_position < 0) valve_position = 0;
        if (valve_position > 100) valve_position = 100;

        set_valve_position(average);
        log_data(sample1, sample2, sample3, average, valve_position);

        gpioDelay(SAMPLE_DELAY_MS * 1000); // Delay in microseconds
    }

    cleanup();
    printf("Irrigation system stopped\n");
    return 0;
}

