#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define RETRY_COUNT 5
#define RETRY_DELAY_BASE_MS 10
#define MAX_RETRIES_DELAY_MS (RETRY_COUNT * 10) // Exponential backoff
#define LOG_FILE "soil_data.txt"
#define ERROR_LOG_FILE "error_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_adc(int channel);
float adc_to_moisture_percentage(int adc_value);
int log_data(float moisture_percentage);
int log_error(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for SPI configuration (optional, but good practice)
typedef struct {
    int channel;
    int speed;
} spi_config_t;

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to cleanup resources before exiting
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to read ADC value from MCP3008
int spi_read_adc(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value = -1;
    int retries = 0;

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    while (retries < RETRY_COUNT) {
        int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (spi_result == 3) {
            // Extract ADC value
            adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            break; // Exit retry loop on success
        } else {
            log_error("SPI transfer failed");
            retries++;
            gpioDelay(RETRY_DELAY_BASE_MS * (1 << retries)); // Exponential backoff
        }
    }

    if (adc_value == -1) {
        log_error("Failed to read ADC after multiple retries");
    }

    return adc_value;
}

