    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to cleanup resources before exiting
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

