#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define DHT22_PIN 4
#define SPI_CHANNEL 0
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0    // cm
#define MIN_DISTANCE 2.0      // cm
#define MAX_FREQUENCY 1000.0  // Hz
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_ADC_VALUE 1023.0  // MCP3008
#define MIN_ADC_VALUE 0.0     // MCP3008
#define MAX_DHT22_READ_RETRIES 3
#define DHT22_READ_DELAY_US 1000 // 1ms delay

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static float distance = 0.0;
static float temperature = 0.0;
static int spi_handle;
static int last_valid_distance = 0.0;
static int last_valid_adc_value = 0;
static int last_valid_volume = 0;
static float hysteresis_threshold = 5.0; // cm

// Calibration parameters
static float distance_calibration_offset = 0.0;
static float distance_calibration_scale = 1.0;
static float adc_to_volume_scale = 1.0;

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int init_spi();
int init_pwm();
int init_logging();
int read_dht22(float *temperature);
int read_hc_sr04(float *distance);
int read_ldr(int *adc_value);
float map_distance_to_frequency(float distance);
int map_adc_to_volume(int adc_value);
void set_pwm_frequency(float frequency);
void set_pwm_duty_cycle(int duty_cycle);
void log_data(float distance, float temperature, int adc_value, int volume, float frequency);
void load_calibration_params();
void save_calibration_params();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(DHT22_PIN, PI_INPUT); // DHT22 is an input
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(PWM_PIN, 0); // Initialize PWM frequency to 0
    gpioSetPWMrange(PWM_PIN, 1000); // Set PWM range to 1000

    return 0;
}

// Initialize SPI communication
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // Open SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize PWM output
int init_pwm() {
    gpioSetPWMfrequency(PWM_PIN, 0); // Initialize PWM frequency to 0
    gpioSetPWMrange(PWM_PIN, 1000); // Set PWM range to 1000
    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen("theremin_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }
    return 0;
}

// Read DHT22 sensor data (using a simple approach - replace with a proper DHT22 library if available)
int read_dht22(float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int j = 0;

    gpioSetMode(DHT22_PIN, PI_OUTPUT);
    gpioWrite(DHT22_PIN, PI_LOW);
    gpioDelay(1);
    gpioWrite(DHT22_PIN, PI_HIGH);
    gpioDelay(30); //30us
    gpioSetMode(DHT22_PIN, PI_INPUT);

    // Read data
    for (int i = 0; i < 40; i++) {
        int count = 0;
        while (gpioRead(DHT22_PIN) == laststate) {
            count++;
            gpioDelay(1);
            if (count > 200) {
                return 1; // Timeout
            }
        }
        laststate = gpioRead(DHT22_PIN);

        if (count > 40) {
            data[j / 8] <<= 1;
            if (count > 80) {
                data[j / 8] |= 1;
            }
            j++;
        }
    }

    // Check checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return 1; // Checksum error
    }

    *temperature = (float)((data[2] & 0x7F) * 256 + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0;
}

// Read HC-SR04 ultrasonic sensor data
int read_hc_sr04(float *distance) {
    gpioWrite(TRIG_PIN, PI_HIGH);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIG_PIN, PI_LOW);

    int start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == PI_LOW) {
        if (gpioTick() - start_tick > 50000) { // Timeout after 50ms
            fprintf(stderr, "HC-SR04 timeout\n");
            return 1;
        }
    }
    int echo_start = gpioTick();

    while (gpioRead(ECHO_PIN) == PI_HIGH) {
        if (gpioTick() - echo_start > 50000) { // Timeout after 50ms
            fprintf(stderr, "HC-SR04 timeout\n");
            return 1;
        }
    }
    int echo_end = gpioTick();

    int pulse_width = echo_end - echo_start;

    if (pulse_width <= 0) {
        fprintf(stderr, "HC-SR04 invalid pulse width: %d\n", pulse_width);
        return 1;
    }

    *distance = (float)pulse_width / 1000000.0 * SPEED_OF_SOUND / 2.0;

    // Validate distance
    if (*distance < MIN_DISTANCE || *distance > MAX_DISTANCE) {
        fprintf(stderr, "HC-SR04 invalid distance: %.2f cm\n", *distance);
        return 1;
    }

    return 0;
}

// Read LDR sensor data via MCP3008 ADC
int read_ldr(int *adc_value) {
    unsigned char spi_data[3];
    int count;

    // MCP3008 configuration: single-ended channel 0
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = 0x80; // Single-ended, channel 0
    spi_data[2] = 0x00; // Don't care

    count = spiXfer(spi_handle, spi_data, spi_data, 3);
    if (count != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", count);
        return 1;
    }

    *adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return 0;
}

// Map distance to audio frequency
float map_distance_to_frequency(float distance) {
    float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;
    return frequency;
}

// Map ADC value to audio volume
int map_adc_to_volume(int adc_value) {
    float volume = (float)adc_value * adc_to_volume_scale;
    if (volume > MAX_DHT22_READ_RETRIES) volume = MAX_DHT22_READ_RETRIES;
    if (volume < MIN_DHT22_READ_RETRIES) volume = MIN_DHT22_READ_RETRIES;
    return (int)volume;
}

// Set PWM frequency
void set_pwm_frequency(float frequency) {
    gpioSetPWMfrequency(PWM_PIN, (int)frequency);
}

// Set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    gpioPWM(PWM_PIN, duty_cycle);
}

// Log data to file
void log_data(float distance, float temperature, int adc_value, int volume, float frequency) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Distance: %.2f cm, Temperature: %.2f C, ADC: %d, Volume: %d, Frequency: %.2f Hz\n",
            timestamp, distance, temperature, adc_value, volume, frequency);
    fflush(log_file);
}

// Load calibration parameters from file
void load_calibration_params() {
    FILE *fp = fopen("theremin_config.txt", "r");
    if (fp != NULL) {
        if (fscanf(fp, "%f,%f,%f", &distance_calibration_offset, &distance_calibration_scale, &adc_to_volume_scale) == 3) {
            printf("Calibration parameters loaded: offset=%.2f, scale=%.2f, adc_scale=%.2f\n", distance_calibration_offset, distance_calibration_scale, adc_to_volume_scale);
        } else {
            fprintf(stderr, "Error reading calibration parameters from file, using defaults.\n");
        }
        fclose(fp);
    } else {
        printf("Calibration file not found, using defaults.\n");
    }
}

// Save calibration parameters to file
void save_calibration_params() {
    FILE *fp = fopen("theremin_config.txt", "w");
    if (fp != NULL) {
        fprintf(fp, "%.2f,%.2f,%.2f", distance_calibration_offset, distance_calibration_scale, adc_to_volume_scale);
        fclose(fp);
        printf("Calibration parameters saved.\n");
    } else {
        perror("Error opening calibration file for writing");
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();
}

int main() {
    // Load calibration parameters
    load_calibration_params();

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO, SPI, and PWM
    if (init_gpio() != 0 || init_spi() != 0 || init_pwm() != 0 || init_logging() != 0) {
        cleanup();
        return 1;
    }

    float distance_hc_sr04, distance_dht22;
    int adc_value;
    float frequency, volume;

    // Main loop
    while (running) {
        // Read sensor data
        if (read_hc_sr04(&distance_hc_sr04) == 0 && read_dht22(&distance_dht22) == 0) {
            // Apply hysteresis
            float distance_hc_sr04_hyst = distance_hc_sr04;
            if (fabs(distance_hc_sr04_hyst - distance_hc_sr04) > hysteresis_threshold) {
                distance_hc_sr04 = distance_hc_sr04_hyst;
            }

            // Apply calibration
            distance = (distance_hc_sr04 + distance_dht22) / 2.0; // Simple averaging
            distance = distance_calibration_offset + distance * distance_calibration_scale;

            // Read LDR data
            if (read_ldr(&adc_value) == 0) {
                // Apply calibration
                volume = map_adc_to_volume(adc_value);
                volume = volume * adc_to_volume_scale;

                // Map distance to frequency
                frequency = map_distance_to_frequency(distance);

                // Set PWM frequency and duty cycle
                set_pwm_frequency(frequency);
                set_pwm_duty_cycle((int)volume);

                // Log data
                log_data(distance, distance_dht22, adc_value, volume, frequency);
            } else {
                fprintf(stderr, "Failed to read LDR data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

