            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d). Retrying...\n", i + 1);
            gpioDelay(RETRY_DELAY * 1000000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries. Re-initializing SPI.\n", MAX_RETRIES);
    cleanup();
    return initialize_spi();
