            aqi = aqi_breakpoints[sensor_id][2] * (aqi - aqi_breakpoints[sensor_id][0]) / (aqi_breakpoints[sensor_id][1] - aqi_breakpoints[sensor_id][0]) + aqi_breakpoints[sensor_id][0];
