    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; ++i) {
            int adc_value = read_mcp3008(sensor_channels[i]);
            if (adc_value >= 0) {
                float aqi = calculate_aqi(adc_value, i);
                log_data(i, adc_value, aqi);
