// Function to classify alcohol level
int classify_alcohol_level(float voltage) {
    if (voltage > 50.0) {
        return 1; // Alcohol detected!
    } else if (voltage < 20.0) {
        return 2; // Sobriety confirmed.
    } else {
        return 0; // Alcohol level within acceptable range.
    }
}

// Function to log data to file
int log_data(float voltage, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Voltage: %.2fV, Status: %s\n", timestamp, voltage, status);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Function to check for sensor presence
int check_sensor_presence() {
    int sensor_absent = 1;
    int adc_value;
    int retries = 0;

    while (sensor_absent && retries < MAX_RETRIES) {
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            if (adc_value > 0 && adc_value < 1023) {
                sensor_absent = 0; // Sensor detected
            }
        } else {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    if (sensor_absent) {
        fprintf(stderr, "Sensor absent (returned 0 or 1023 after multiple retries).\n");
        return -1; // Sensor absent
    }

    return 0; // Sensor present
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0 CE0, 1MHz, SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check for sensor presence
    if (check_sensor_presence() != 0) {
        fprintf(stderr, "Program terminated due to sensor absence.\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value.\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Classify alcohol level
        int status = classify_alcohol_level(voltage);

        // Log data
        if (log_data(voltage, status) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Print to console
        printf("Voltage: %.2fV, Status: %s\n", voltage, status);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second in microseconds
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

