#define SPI_MOSI 10
#define SPI_MISO 9

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define moisture threshold
#define MOISTURE_THRESHOLD 300

// Define log file name
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
int control_pump(int state);
int log_data(int moisture_level, int pump_status);
void signal_handler(int signal);
void cleanup();

// Structure to hold SPI configuration
typedef struct {
    int ce_pin;
    int sclk_pin;
    int mosi_pin;
    int miso_pin;
    int spi_channel;
    int spi_speed;
    int spi_mode;
} spi_config_t;

// Function to initialize the pigpio library and SPI interface
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    spi_config_t spi_config = {
        .ce_pin = SPI_CE,
        .sclk_pin = SPI_SCLK,
        .mosi_pin = SPI_MOSI,
        .miso_pin = SPI_MISO,
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .spi_mode = SPI_MODE
    };

    spi_handle = spiOpen(spi_config.ce_pin, spi_config.spi_speed, spi_config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to control the water pump
int control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    return 0;
}

// Function to log data to file
int log_data(int moisture_level, int pump_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %d, Pump: %s\n", timestamp,
