    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read moisture level
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Failed to read moisture level\n");
            log_data(-1, -1); // Log error
        } else {
            // Control pump
            int pump_state = (moisture_level < MOISTURE_THRESHOLD) ? 1 : 0;
            control_pump(pump_state);

            // Log data
            log_data(moisture_level, pump_state);
        }

        // Wait 60 seconds
        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    printf("Irrigation system stopped.\n");
    return 0;
}

