    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map ADC value to motor speed
int map_adc_to_speed(int adc_value) {
    // Map ADC value (0-1023) to speed (0-255)
    return (int)(((float)adc_value / 1023.0) * MAX_SPEED);
}

// Function to set motor speed and direction
void set_motor_speed(int motor_number, int speed, int direction) {
    int enable_pin;
    int direction_pin;

    if (motor_number == 1) {
        enable_pin = MOTOR1_ENABLE_PIN;
        direction_pin = MOTOR1_FORWARD;
    } else if (motor_number == 2) {
        enable_pin = MOTOR2_ENABLE_PIN;
        direction_pin = MOTOR2_FORWARD;
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor_number);
        return;
    }

    gpioWrite(enable_pin, 1); // Enable motor

    if (direction == FORWARD) {
        gpioWrite(direction_pin, 1);
    } else if (direction == BACKWARD) {
        gpioWrite(direction_pin, 0);
    } else {
        fprintf(stderr, "Error: Invalid direction %d\n", direction);
        gpioWrite(enable_pin, 0); // Disable motor
        return;
    }

    gpioPWM(enable_pin, speed); // Set motor speed
}

// Function to set motor direction
void set_motor_direction(int motor_number, int direction) {
    int direction_pin;

    if (motor_number == 1) {
        direction_pin = MOTOR1_FORWARD;
    } else if (motor_number == 2) {
        direction_pin = MOTOR2_FORWARD;
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor_number);
        return;
    }

    if (direction == FORWARD) {
        gpioWrite(direction_pin, 1);
    } else if (direction == BACKWARD) {
        gpioWrite(direction_pin, 0);
    } else {
        fprintf(stderr, "Error: Invalid direction %d\n", direction);
    }
}

// Function to cleanup GPIO and SPI resources
void cleanup() {
    printf("Cleaning up...\n");

    // Disable motors
    gpioWrite(MOTOR1_ENABLE_PIN, 0);
    gpioWrite(MOTOR2_ENABLE_PIN, 0);

    // Stop PWM
    gpioPWM(MOTOR1_ENABLE_PIN, 0);
    gpioPWM(MOTOR2_ENABLE_PIN, 0);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR1_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR2_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR2_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENABLE_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENABLE_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR1_ENABLE_PIN, 255);
    gpioSetPWMrange(MOTOR2_ENABLE_PIN, 255);

    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed with code %d\n", spi_handle);
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    printf("Program started. Running...\n");

    while (1) {
        // Read ADC values from potentiometers
        int pot1_adc = read_mcp3008(POT1_CHANNEL);
        int pot2_adc = read_mcp3008(POT2_CHANNEL);

        if (pot1_adc == -1 || pot2_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values. Retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Map ADC values to motor speeds
        int motor1_speed = map_adc_to_speed(pot1_adc);
        int motor2_speed = map_adc_to_speed(pot2_adc);

        // Set motor speeds and directions
        set_motor_speed(1, motor1_speed, current_motor_state.motor1_direction);
        set_motor_speed(2, motor2_speed, current_motor_state.motor2_direction);
        set_motor_direction(1, current_motor_state.motor1_direction);
        set_motor_direction(2, current_motor_state.motor2_direction);

        // Update motor state
        current_motor_state.motor1_speed = motor1_speed;
        current_motor_state.motor2_speed = motor2_speed;
        current_motor_state.motor1_direction = (pot1_adc > pot2_adc) ? FORWARD : BACKWARD; // Adjust direction based on potentiometer values
        current_motor_state.motor2_direction = (pot1_adc > pot2_adc) ? FORWARD : BACKWARD;

        // Accelerate phase (0-255)
        for (int i = MIN_SPEED; i <= MAX_SPEED; i++) {
            set_motor_speed(1, i, current_motor_state.motor1_direction);
            set_motor_speed(2, i, current_motor_state.motor2_direction);
            gpioDelay(10000); // 10ms delay
        }

        // Constant-speed phase (2 seconds)
        gpioDelay(2000000); // 2 seconds

        // Decelerate phase (255-0)
        for (int i = MAX_SPEED; i >= MIN_SPEED; i--) {
            set_motor_speed(1, i, current_motor_state.motor1_direction);
            set_motor_speed(2, i, current_motor_state.motor2_direction);
            gpioDelay(10000); // 10ms delay
        }

        // Pause for 5 seconds
        gpioDelay(5000000); // 5 seconds

        // Reverse direction
        set_motor_direction(1, BACKWARD);
        set_motor_direction(2, FORWARD);
        gpioDelay(100000); // 100ms delay

        // Repeat the cycle
    }

    return 0;
}

