// Define GPIO pins
#define LED_PIN 17
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 10

// Global variables
int spi_handle;
double baseline;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
double calibrate_baseline();
void control_led(int state);
void signal_handler(int signal);

// Structure to hold GPIO modes
typedef struct {
    int cs_mode;
    int mosi_mode;
    int miso_mode;
    int sclk_mode;
} gpio_modes_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpio_modes_t modes = {PI_OUTPUT, PI_OUTPUT, PI_OUTPUT, PI_OUTPUT};

    gpioSetMode(LED_PIN, modes.mosi_mode);
    gpioSetMode(CS_PIN, modes.cs_mode);
    gpioSetMode(MOSI_PIN, modes.mosi_mode);
    gpioSetMode(MISO_PIN, modes.miso_mode);
    gpioSetMode(SCLK_PIN, modes.sclk_mode);

    gpioWrite(LED_PIN, 0); // Turn LED off initially

    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    spiXfer(spi_handle, spi_data, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calibrate the baseline
double calibrate_baseline() {
    double sum = 0.0;
    int num_samples = 0;
    int sample_count = 0;

    printf("Calibrating baseline... Please wait.\n");
    while (num_samples < 500 && !terminate) {
        int raw_value = read_mcp3008(0);
        if (raw_value >= 0) {
            sum += raw_value;
            num_samples++;
            sample_count++;
        } else {
            fprintf(stderr, "Error reading MCP3008 during calibration\n");
            return -1.0; // Indicate calibration failure
        }
        gpioDelay(10); // Small delay between samples
    }

    if (num_samples == 0) {
        fprintf(stderr, "Calibration failed: No samples collected.\n");
        return -1.0; // Indicate calibration failure
    }

    baseline = sum / num_samples;
    printf("Calibration complete. Baseline: %lf\n", baseline);
    return baseline;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Calibrate the baseline
    double baseline_value = calibrate_baseline();
    if (baseline_value < 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int raw_value = read_mcp3008(0);
        if (raw_value >= 0) {
            double normalized_value = (double)raw_value - baseline;
            if (normalized_value > 0) {
                // Check if the normalized value exceeds the threshold
                if (normalized_value > 0) {
                    control_led(1); // Turn LED on
                    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay
                    if (gpioRead(LED_PIN) == 0) {
                        control_led(0); // Turn LED off
                    }
                }
            }
        } else {
            fprintf(stderr, "Error reading MCP3008 in main loop\n");
        }
        gpioDelay(10); // Small delay between readings
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

