#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define LOG_FILE "airflow_log.txt"
#define SAMPLE_INTERVAL_MS 100
#define VREF 3.3 // Reference voltage for MCP3008

// Calibration curve parameters (example values, adjust based on your sensor)
#define MIN_VOLTAGE 0.5  // Minimum voltage output (0% flow)
#define MAX_VOLTAGE 4.5  // Maximum voltage output (100% flow)
#define MIN_FLOW 0.0     // Minimum airflow (SLPM)
#define MAX_FLOW 20.0    // Maximum airflow (SLPM)

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_adc(int channel);
float voltage_to_airflow(int adc_value);
int log_data(float airflow);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int adc_channel;
    float vref;
    char *log_file;
    int sample_interval_ms;
    float min_voltage;
    float max_voltage;
    float min_flow;
    float max_flow;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    ADC_CHANNEL,
    VREF,
    LOG_FILE,
    SAMPLE_INTERVAL_MS,
    MIN_VOLTAGE,
    MAX_VOLTAGE,
    MIN_FLOW,
    MAX_FLOW
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler); // Register signal handler

    while (!terminate) {
        int adc_value = read_adc(config.adc_channel);
        if (adc_value >= 0) {
            float airflow = voltage_to_airflow(adc_value);
            if (log_data(airflow) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        gpioDelay(config.sample_interval_ms * 1000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

float voltage_to_airflow(int adc_value) {
    // Convert ADC value to voltage
    float voltage = (float)adc_value / 1023.0 * config.vref;

    // Linear interpolation
    float airflow = config.min_flow + (voltage - config.min_voltage) * (config.max_flow - config.min_flow) / (config.max_voltage - config.min_voltage);

    // Clamp airflow to valid range
    if (airflow < config.min_flow) {
        airflow = config.min_flow;
    } else if (airflow > config.max_flow) {
        airflow = config.max_flow;
    }

    return airflow;
}

int log_data(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, airflow);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

