int gpio_set_direction(int pin, int direction);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);
uint32_t get_timestamp_ns();
int write_log_entry(uint32_t timestamp, int adc_value);
void signal_handler(int signal);

// SPI Initialization
int spi_init(int channel, int speed) {
    int fd;
    struct spi_ioc_transfer transfer[1];

    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Configure max speed
    uint32_t speed_limit = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_limit) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

