    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    gpio_fd = gpio_init(GPIO_CE);
    if (gpio_fd < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(spi_fd);
        return 1;
    }

    // Set GPIO direction to output
    gpio_set_direction(GPIO_CE, PI_OUTPUT);

    // Open log file
    log_file = fopen("audio_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    printf("Audio logging started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        // Get timestamp
        uint32_t timestamp = get_timestamp_ns();

        // Read ADC value
        int adc_value = spi_read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed\n");
            continue; // Continue to the next iteration
        }

        // Write log entry
        if (write_log_entry(timestamp, adc_value) != 0) {
            fprintf(stderr, "Log write failed\n");
        }

        // Sleep for the remaining time
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = SAMPLE_PERIOD - (timestamp % SAMPLE_PERIOD); // Calculate remaining time
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    close(spi_fd);
    gpioWrite(GPIO_CE, 0); // Set CE low
    gpioTerminate();
    fclose(log_file);

    printf("Audio logging stopped.\n");
