#define MCP3008_CHANNEL 0
#define VREF 3.3
#define LOG_FILE "gas_log.txt"
#define RETRY_DELAY_MS 100
#define READ_DELAY_S 1

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
int log_data(float voltage, float ppm);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float vref;
    char *log_file;
    int retry_delay_ms;
    int read_delay_s;
} config_t;

config_t config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    VREF,
    LOG_FILE,
    RETRY_DELAY_MS,
    READ_DELAY_S
};

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

