    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", config.log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            // Retry after a delay
            gpioDelay(config.retry_delay_ms * 1000); // Convert ms to us
            continue;
        }

        // Convert to voltage
