#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define ADXL335 sensitivity (3.3V full scale)
#define ADXL335_SENSITIVITY 0.3 // 300mV/g

// Define Kalman filter parameters
#define Q_ANGLE 0.01
#define Q_BIAS 0.003
#define R_MEASUREMENT 0.03

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
float x_angle = 0.0;
float y_angle = 0.0;
float z_angle = 0.0;
float p_angle = 1.0;
float q_angle = 0.01;
float p_bias = 1.0;
float b_bias = 0.0;
float p = 1.0;

// Function prototypes
int initialize_spi();
int read_adc_channel(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_g(float voltage);
void kalman_filter(float measurement);
void print_acceleration(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC channel
int read_adc_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

