void kalman_filter(float measurement) {
    // Prediction step
    float y_pred = x_angle;
    float p_pred = p_angle + Q_ANGLE;

    // Measurement update step
    float K = p_pred / (p_pred + R_MEASUREMENT);
    x_angle += K * (measurement - y_pred);
    p_bias += K * (measurement - y_pred);

    p = p_pred + Q_BIAS - K * R_MEASUREMENT;
}

// Print acceleration values
void print_acceleration(float x, float y, float z) {
    printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x, y, z);
}

