    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("ADXL335 accelerometer data acquisition and Kalman filter demo\n");

    while (!terminate) {
        // Read ADC values
        int x_adc = read_adc_channel(0);
        int y_adc = read_adc_channel(1);
        int z_adc = read_adc_channel(2);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to voltage and acceleration
        float x_voltage = adc_to_voltage(x_adc);
        float y_voltage = adc_to_voltage(y_adc);
        float z_voltage = adc_to_voltage(z_adc);

        float x_g = voltage_to_g(x_voltage);
        float y_g = voltage_to_g(y_voltage);
        float z_g = voltage_to_g(z_voltage);

        // Apply Kalman filter
        kalman_filter(x_g);
        kalman_filter(y_g);
        kalman_filter(z_g);

        // Print acceleration values
        print_acceleration(x_g, y_g, z_g);

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100);
    }

    // Close SPI interface
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

