#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Define the magnetic field strength range (in millitesla)
#define MIN_MG 100.0
#define MAX_MG 100.0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl-C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the digital state of a Hall-Effect sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to simulate an ADC by interpreting HIGH as 3.3V and LOW as 0.0V
float simulate_adc(int sensor_value) {
    return (float)sensor_value * 3.3;
}

// Function to convert the ADC value to a magnetic field strength in millitesla
float convert_to_mT(float adc_value) {
    // Linear conversion: 0V = -100mT, 3.3V = +100mT
    return (adc_value - 0.0) * (100.0 / 3.3);
}

// Function to log the magnetic field strength values to a file
int log_magnetic_field(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1; // Indicate an error
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read the digital state of each sensor
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor values, skipping logging.\n");
            gpioDelay(100); // Wait 100ms before the next iteration
            continue; // Skip the rest of the loop and try again
        }

        // Simulate ADC and convert to millitesla
        float sensor1_mT = convert_to_mT(simulate_adc(sensor1_value));
        float sensor2_mT = convert_to_mT(simulate_adc(sensor2_value));
        float sensor3_mT = convert_to_mT(simulate_adc(sensor3_value));

        // Check if any magnetic field strength is outside the range
        if (sensor1_mT < -100.0 || sensor1_mT > 100.0) {
            fprintf(stderr, "Warning: Sensor 1 magnetic field strength (%.2f mT) is outside the expected range.\n", sensor1_mT);
        }
        if (sensor2_mT < -100.0 || sensor2_mT > 100.0) {
            fprintf(stderr, "Warning: Sensor 2 magnetic field strength (%.2f mT) is outside the expected range.\n", sensor2_mT);
        }
        if (sensor3_mT < -100.0 || sensor3_mT > 100.0) {
            fprintf(stderr, "Warning: Sensor 3 magnetic field strength (%.2f mT) is outside the expected range.\n", sensor3_mT);
        }

        // Log the magnetic field strength values
        if (log_magnetic_field(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
            fprintf(stderr, "Error logging magnetic field values.\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    return 0;
}

