#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <mosquitto.h>
#include <jansson.h>
#include <pigpio.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60 // seconds

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
void signal_handler(int sig);
int connect_mqtt(void);
void disconnect_mqtt(void);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json_payload(const char *payload, int *led_state);
void set_led_state(int led_state);
void reconnect_delay(int delay_seconds);

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// MQTT connection function
int connect_mqtt(void) {
    int rc;

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Error: Out of memory.");
        return 1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, message_callback);

    rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Error: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Error subscribing: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    syslog(LOG_INFO, "Connected to MQTT broker.");
    return 0;
}

// MQTT disconnection function
void disconnect_mqtt(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        syslog(LOG_INFO, "Disconnected from MQTT broker.");
    }
}

// MQTT message callback
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        int led_state;
        if (parse_json_payload((char *)message->payload, &led_state) == 0) {
            set_led_state(led_state);
        } else {
            syslog(LOG_ERR, "Error parsing JSON payload.");
        }
    } else {
        syslog(LOG_ERR, "Empty message received.");
    }
}

// JSON parsing function
int parse_json_payload(const char *payload, int *led_state) {
    json_t *root;
    json_error_t error;

    root = json_loads(payload, 0, &error);
    if (!root) {
        syslog(LOG_ERR, "Error parsing JSON: %s", error.text);
        return 1;
    }

    json_t *led_state_json = json_object_get(root, "led_state");
    if (!led_state_json) {
        syslog(LOG_ERR, "JSON missing 'led_state' key.");
        json_decref(root);
        return 1;
    }

    if (!json_is_boolean(led_state_json)) {
        syslog(LOG_ERR, "'led_state' is not a boolean.");
        json_decref(root);
        return 1;
    }

    *led_state = json_boolean_value(led_state_json);
    json_decref(root);
    return 0;
}

// GPIO control function
void set_led_state(int led_state) {
    gpioWrite(GPIO_PIN, led_state);
    syslog(LOG_INFO, "LED set to state: %s", led_state ? "ON" : "OFF");
}

// Reconnection delay function
void reconnect_delay(int delay_seconds) {
    syslog(LOG_WARNING, "Reconnecting in %d seconds...", delay_seconds);
    sleep(delay_seconds);
}

int main(void) {
    int rc;
    int led_state = 0; // Initial LED state: OFF
    int reconnect_delay_seconds = 1;

    // Initialize syslog
    openlog("rpi_led_control", LOG_PID | LOG_CONS, LOG_USER);

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn LED off on startup

    // Connect to MQTT broker
    if (connect_mqtt() != 0) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker. Exiting.");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        rc = mosquitto_loop(mosq, -1, 1); // -1 means loop forever, 1 is max number of messages to process
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Error in mosquitto_loop: %s", mosquitto_strerror(rc));
            disconnect_mqtt();
            reconnect_delay(reconnect_delay_seconds);
            if (connect_mqtt() != 0) {
                syslog(LOG_ERR, "Failed to reconnect to MQTT broker. Exiting.");
                running = 0; // Exit loop if reconnection fails
            }
            reconnect_delay_seconds *= 2; // Exponential backoff
            if (reconnect_delay_seconds > MAX_RECONNECT_DELAY) {
                reconnect_delay_seconds = MAX_RECONNECT_DELAY;
            }
        }
    }

    // Cleanup
    disconnect_mqtt();
    gpioWrite(GPIO_PIN, 0); // Turn LED off
    gpioTerminate();
    closelog();

    return 0;
}

