#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <wiringPi.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define SERVER_IP "192.168.1.100"
#define SERVER_PORT 5000
#define DEBOUNCE_DELAY_MS 50

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, exiting...");
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    char *timestamp = get_timestamp();
    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Function to send an event to the server
int send_event(const char *message) {
    int sockfd;
    struct sockaddr_in servaddr;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    if (sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Function to read the vibration sensor value
int read_vibration_sensor() {
    return digitalRead(GPIO_PIN);
}

// Function to handle vibration detection
void handle_vibration() {
    char *timestamp = get_timestamp();
    char message[100];
    snprintf(message, sizeof(message), "Vibration detected at %s", timestamp);

    if (log_event(message) != 0) {
        syslog(LOG_ERR, "Failed to log event: %s", message);
    }

    if (send_event(message) != 0) {
        syslog(LOG_ERR, "Failed to send event: %s", message);
    }

    printf("%s\n", message);
    system("sudo shutdown -h now");
}

int main() {
    openlog("vibration_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting vibration monitor");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        perror("wiringPiSetupGpio failed");
        syslog(LOG_ERR, "wiringPiSetupGpio failed");
        return 1;
    }

    // Set GPIO pin as input
    pinMode(GPIO_PIN, INPUT);
    pullUpDnControl(GPIO_PIN, PUD_UP); // Enable internal pull-up resistor

    syslog(LOG_INFO, "Vibration monitor started on GPIO %d", GPIO_PIN);

    while (program_running) {
        if (read_vibration_sensor() == 0) { // Vibration detected (active low)
            handle_vibration();
            delay(DEBOUNCE_DELAY_MS); // Debounce
        }
        delay(10); // Small delay to reduce CPU usage
    }

    syslog(LOG_INFO, "Vibration monitor exiting");

    // Cleanup GPIO and close the chip
    digitalWrite(GPIO_PIN, LOW); // Release the GPIO line
    close("/dev/gpiochip0");

    closelog();
    return 0;
}

