#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_CHIP_ID_REG 0xD0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int bmp280_init();
int bmp280_read_calibration_data();
int bmp280_read_raw_data(int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temperature);
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine);
double bmp280_compensate_altitude(double pressure);
int bmp280_read_altitude(double *altitude);
int log_altitude(double altitude);
void signal_handler(int signal);
int verify_sensor();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// BMP280 initialization function
int bmp280_init() {
    // Set the sensor to forced mode and configure oversampling
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) { // Oversampling x1, Normal mode
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        return -1;
    }

    // Read calibration data
    if (bmp280_read_calibration_data() < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// BMP280 read calibration data function
int bmp280_read_calibration_data() {
    char data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, data, 26) < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib.dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib.dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib.dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib.dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib.dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib.dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib.dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib.dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib.dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib.dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib.dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// BMP280 read raw data function
int bmp280_read_raw_data(int32_t *temperature, int32_t *pressure) {
    char data[6];

    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, data, 6) < 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// BMP280 compensate temperature function
double bmp280_compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double T_fine;

    var1 = (((double)raw_temperature) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    T_fine = (var1 + var2);
    T = (var1 + var2) / 5120.0;
    return T;
}

// BMP280 compensate pressure function
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;
    double var3, var4, var5;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var3 = ((double)calib.dig_P3) * var1 * var1 / 524288.0;
    var4 = var3 + ((double)calib.dig_P2) * var1 / 524288.0;
    var5 = (1.0 + var4 / 32768.0) * ((double)calib.dig_P1);
    if (var5 == 0)
    {
        return 0; // avoid exception caused by division by zero
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var5;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return p;
}

// BMP280 compensate altitude function
double bmp280_compensate_altitude(double pressure) {
    double altitude;
    double p0 = 101325.0; // Standard sea level pressure in Pa

    altitude = 44330.0 * (1.0 - pow(pressure / p0, 0.1903));
    return altitude;
}

// BMP280 read altitude function
int bmp280_read_altitude(double *altitude) {
    int32_t raw_temperature, raw_pressure;
    double t_fine;

    if (bmp280_read_raw_data(&raw_temperature, &raw_pressure) < 0) {
        return -1;
    }

    t_fine = bmp280_compensate_temperature(raw_temperature);
    double pressure = bmp280_compensate_pressure(raw_pressure, t_fine);

    *altitude = bmp280_compensate_altitude(pressure);

    return 0;
}

// Log altitude function
int log_altitude(double altitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, altitude) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written to the file

    return 0;
}

// Verify sensor function
int verify_sensor() {
    char chip_id;
    if (i2cReadByteData(i2c_handle, BMP280_CHIP_ID_REG) < 0) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }
    chip_id = i2cReadByteData(i2c_handle, BMP280_CHIP_ID_REG);
    if (chip_id != 0x58) {
        fprintf(stderr, "Error: Invalid chip ID (0x%x)\n", chip_id);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    if (verify_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize BMP280
    if (bmp280_init() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        double altitude;
        if (bmp280_read_altitude(&altitude) == 0) {
            if (log_altitude(altitude) != 0) {
                fprintf(stderr, "Error logging altitude\n");
            }
        } else {
            fprintf(stderr, "Error reading altitude\n");
        }

        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
