// BMP280 initialization function
int bmp280_init() {
    // Set the sensor to forced mode and configure oversampling
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) { // Oversampling x1, Normal mode
