// BMP280 read raw data function
int bmp280_read_raw_data(int32_t *temperature, int32_t *pressure) {
    char data[6];

    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, data, 6) < 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// BMP280 compensate temperature function
double bmp280_compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double T_fine;

    var1 = (((double)raw_temperature) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    T_fine = (var1 + var2);
    T = (var1 + var2) / 5120.0;
    return T;
}

// BMP280 compensate pressure function
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;
    double var3, var4, var5;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var3 = ((double)calib.dig_P3) * var1 * var1 / 524288.0;
    var4 = var3 + ((double)calib.dig_P2) * var1 / 524288.0;
    var5 = (1.0 + var4 / 32768.0) * ((double)calib.dig_P1);
    if (var5 == 0)
    {
        return 0; // avoid exception caused by division by zero
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var5;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return p;
}

// BMP280 compensate altitude function
double bmp280_compensate_altitude(double pressure) {
    double altitude;
    double p0 = 101325.0; // Standard sea level pressure in Pa

    altitude = 44330.0 * (1.0 - pow(pressure / p0, 0.1903));
    return altitude;
}

// BMP280 read altitude function
int bmp280_read_altitude(double *altitude) {
    int32_t raw_temperature, raw_pressure;
    double t_fine;

    if (bmp280_read_raw_data(&raw_temperature, &raw_pressure) < 0) {
        return -1;
    }

    t_fine = bmp280_compensate_temperature(raw_temperature);
    double pressure = bmp280_compensate_pressure(raw_pressure, t_fine);

    *altitude = bmp280_compensate_altitude(pressure);

    return 0;
}

// Log altitude function
int log_altitude(double altitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, altitude) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written to the file

    return 0;
}

// Verify sensor function
int verify_sensor() {
    char chip_id;
    if (i2cReadByteData(i2c_handle, BMP280_CHIP_ID_REG) < 0) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }
    chip_id = i2cReadByteData(i2c_handle, BMP280_CHIP_ID_REG);
    if (chip_id != 0x58) {
        fprintf(stderr, "Error: Invalid chip ID (0x%x)\n", chip_id);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    if (verify_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize BMP280
    if (bmp280_init() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        double altitude;
        if (bmp280_read_altitude(&altitude) == 0) {
            if (log_altitude(altitude) != 0) {
                fprintf(stderr, "Error logging altitude\n");
            }
        } else {
            fprintf(stderr, "Error reading altitude\n");
        }

        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

