#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer temp_buffer;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void add_to_buffer(CircularBuffer *cb, float value);
float get_from_buffer(CircularBuffer *cb, int index);
int write_buffer_to_file(CircularBuffer *cb);
void signal_handler(int signal);
void cleanup();

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (%d)\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    return (adc_value * 3.3 / 1024.0) * 100.0;
}

// Function to add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to get a value from the circular buffer
float get_from_buffer(CircularBuffer *cb, int index) {
    if (index < 0 || index >= cb->count) {
        fprintf(stderr, "Error: Index out of bounds\n");
        return -1.0; // Indicate error
    }
    return cb->buffer[(cb->head - cb->count + index + BUFFER_SIZE) % BUFFER_SIZE];
}

// Function to write the buffer to a file
int write_buffer_to_file(CircularBuffer *cb) {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open file %s for writing\n", LOG_FILE);
        return -1;
    }

    size_t elements_written = fwrite(cb->buffer, sizeof(float), cb->count, fp);
    if (elements_written != cb->count) {
        fprintf(stderr, "Error: Failed to write all elements to file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close SPI and terminate pigpio
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    temp_buffer.head = 0;
    temp_buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Add to circular buffer
        add_to_buffer(&temp_buffer, temperature);

        // Print temperature
        printf("Temperature: %.2f °C\n", temperature);

        // Write buffer to file
        if (write_buffer_to_file(&temp_buffer) != 0) {
            fprintf(stderr, "Error: Failed to write buffer to file\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

