#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_SEC 1

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the GPIO pin for input with a pull-down resistor
int initialize_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to input mode\n", GPIO_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting pull-down resistor on GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return 0;
}

// Reads the digital value from the GPIO pin
int read_gpio() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return value;
}

// Logs the timestamp, GPIO pin, and state to the CSV file
int log_event(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, GPIO_PIN, state);
    fclose(fp);
    return 0;
}

// Prints an alarm message to stdout
void alarm_message() {
    printf("Flame detected on GPIO %d!\n", GPIO_PIN);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int state = read_gpio();
        if (state < 0) {
            fprintf(stderr, "Error reading GPIO, exiting...\n");
            break;
        }

        if (log_event(state) != 0) {
            fprintf(stderr, "Error logging event, exiting...\n");
            break;
        }

        if (state == 1) {
            alarm_message();
        }

        gpioDelay(POLL_INTERVAL_SEC * 1000000); // Delay for 1 second
    }

    // Cleanup
    gpioTerminate();
    printf("GPIO terminated. Exiting.\n");
    return 0;
}

