#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define MCP4725_ADDR 0x60
#define VREF 3.3f
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 0.5f

// Global variables
static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int i2c_init(const char *device);
int read_mcp3008(int spi_fd, int channel);
float adc_to_temperature(int adc_value);
int dac_write(int i2c_fd, int value);
int log_data(FILE *log_file, int adc_value, float temperature, float voltage);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = 500000; // 500 kHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C Initialization
int i2c_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MCP4725_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read MCP3008 ADC value
int read_mcp3008(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = 500000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC value to temperature (Celsius)
float adc_to_temperature(int adc_value) {
    float voltage = (adc_value / 1023.0f) * VREF;
    float temperature = (voltage - 0.5) / 0.01;
    return temperature;
}

// Write DAC value to MCP4725
int dac_write(int i2c_fd, int value) {
    uint16_t dac_value = (uint16_t)value;
    uint8_t data[2];

    // Write DAC value (MSB first)
    data[0] = (dac_value >> 4) & 0xFF; // MSB
    data[1] = (dac_value & 0x0F) << 4; // LSB

    struct i2c_msg msgs[2];
    msgs[0].addr = MCP4725_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = data;

    msgs[1].addr = MCP4725_ADDR;
    msgs[1].flags = I2C_M_RD; // Read is not needed, but required by ioctl
    msgs[1].len = 1;
    msgs[1].buf = data;

    if (ioctl(i2c_fd, I2C_RDWR, msgs) < 0) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Log data to file
int log_data(FILE *log_file, int adc_value, float temperature, float voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%d,%.2f,%.2f\n", timestamp, adc_value, temperature, voltage) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

// Cleanup resources
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in %f seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Convert to temperature
        float temperature = adc_to_temperature(adc_value);

        // Write to DAC
        if (dac_write(i2c_fd, (int)(temperature * 65535.0f / 100.0f)) < 0) {
            fprintf(stderr, "Error writing to DAC. Retrying in %f seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Calculate voltage
        float voltage = (adc_value / 1023.0f) * VREF;

        // Log data
        if (log_data(log_file, adc_value, temperature, voltage) < 0) {
            fprintf(stderr, "Error logging data. Retrying in %f seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Echo to stdout
        printf("ADC: %d, Temperature: %.2f C, Voltage: %.2f V\n", adc_value, temperature, voltage);

        // Wait for next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

