            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Echo to stdout
        printf("ADC: %d, Temperature: %.2f C, Voltage: %.2f V\n", adc_value, temperature, voltage);

        // Wait for next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

