#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define relay pins (BCM numbering)
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Function prototypes
int activate_relay(int relay_pin);
int deactivate_relay(int relay_pin);
int sequence_relay(int relay_pins[], int num_relays);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    // Deactivate all relays
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Release GPIO lines
    gpioTerminate();

    exit(0);
}

// Function to activate a relay
int activate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 0) != 0) { // Assuming active-high relays
        fprintf(stderr, "Error: Failed to activate relay on pin %d\n", relay_pin);
        return -1;
    }
    return 0;
}

// Function to deactivate a relay
int deactivate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to deactivate relay on pin %d\n", relay_pin);
        return -1;
    }
    return 0;
}

// Function to run the relay sequence
int sequence_relay(int relay_pins[], int num_relays) {
    for (int i = 0; i < num_relays; i++) {
        if (activate_relay(relay_pins[i]) != 0) {
            return -1; // Propagate error
        }
        gpioDelay(1000); // Activate for 1 second

        if (deactivate_relay(relay_pins[i]) != 0) {
            return -1; // Propagate error
        }
        gpioDelay(1000); // Deactivate for 1 second
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Define relay pins in an array
    int relay_pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int num_relays = sizeof(relay_pins) / sizeof(relay_pins[0]);

    // Set relay pins as outputs
    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set pin %d as output\n", relay_pins[i]);
            cleanup(0); // Clean up and exit
            return 1;
        }
        // Initialize all relays to inactive (LOW)
        if (deactivate_relay(relay_pins[i]) != 0) {
            cleanup(0);
            return 1;
        }
    }

    // Main loop
    while (1) {
        if (sequence_relay(relay_pins, num_relays) != 0) {
            fprintf(stderr, "Error: Relay sequence failed\n");
            cleanup(0);
            return 1;
        }
    }

    return 0; // This line will never be reached due to the infinite loop
}

