#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define ADC_CLK 26
#define ADC_DOUT 19
#define LED_PIN 16

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define LED_ON_TIME_MS 500

// Global variables
static volatile int running = 1;
static volatile unsigned long last_clap_time = 0;

// Function prototypes
int initialize_gpio();
int read_adc();
int detect_clap();
void control_led(int state);
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int clk_pin;
    int dout_pin;
    int led_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ADC_CLK, PI_INPUT);
    gpioSetMode(ADC_DOUT, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read ADC value using bit-banging
int read_adc() {
    int adc_value = 0;
    int i;

    // Wait for DOUT to go high (start of the clock)
    while (gpioRead(ADC_DOUT) == 0 && running) {
        // Wait for the clock to go high
        while (gpioRead(ADC_CLK) == 0 && running) {
            // Wait for the clock to go low
            while (gpioRead(ADC_CLK) == 1 && running) {
                // Do nothing, just wait
            }
        }
    }

    if (!running) return -1; // Exit if signal received

    // Read 10 bits of data
    for (i = 0; i < 10; i++) {
        // Wait for the clock to go high
        while (gpioRead(ADC_CLK) == 0 && running) {
            // Wait for the clock to go low
            while (gpioRead(ADC_CLK) == 1 && running) {
                // Do nothing, just wait
            }
        }

        // Read the data bit
        if (gpioRead(ADC_DOUT)) {
            adc_value |= (1 << i);
        }

        // Wait for the clock to go low
        while (gpioRead(ADC_CLK) == 1 && running) {
            // Do nothing, just wait
        }
    }

    return adc_value;
}

// Function to detect a clap event
int detect_clap() {
    int adc_value = read_adc();
    if (adc_value < 0) return 0; // Error reading ADC

    // Simple threshold-based clap detection
    if (adc_value > 500) { // Adjust threshold as needed
        return 1;
    }
    return 0;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (detect_clap()) {
            unsigned long current_time = gpioTick();

            // Debounce check
            if (current_time - last_clap_time > DEBOUNCE_DELAY_MS * 1000) {
                printf("Clap detected!\n");
                control_led(1); // Turn on LED
                gpioDelay(LED_ON_TIME_MS * 1000); // Wait for LED_ON_TIME_MS
                control_led(0); // Turn off LED
                last_clap_time = current_time;
            }
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return 0;
}

