#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200 // mm
#define LOG_FILE "distance_log.txt"

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value
int read_sensor() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data to a file
void log_data(int sensor_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %d\n", timestamp, sensor_value);
    fclose(fp);
}

// Function to determine if the feeder should be activated
void check_feeder(int sensor_value) {
    if (sensor_value == 0) { // Assuming 0 indicates proximity
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    printf("Feeder control program started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value == -1) {
            fprintf(stderr, "Retrying in 1 second...\n");
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        log_data(sensor_value);
        check_feeder(sensor_value);

        gpioDelay(100); // Delay for 100ms
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

