#define SPI_MISO 9
#define SPI_SCLK 11

// Define constants
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "soil_moisture.log"
#define SAMPLE_INTERVAL 60 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_adc(int channel);
float convert_to_percentage(int adc_value);
void control_pump(int pump_state);
void log_data(float moisture_percentage, int pump_status);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int pump_gpio;
    int spi_ce;
    int spi_mosi;
    int spi_miso;
    int spi_sclk;
    int moisture_threshold;
    char *log_file;
} Config;

Config config = {
    PUMP_GPIO,
    SPI_CE,
    SPI_MOSI,
    SPI_MISO,
    SPI_SCLK,
    MOISTURE_THRESHOLD,
    LOG_FILE
};

int main() {
    // Install signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay in microseconds
            continue; // Skip to the next iteration
        }

        // Convert to percentage
        float moisture_percentage = convert_to_percentage(adc_value);

        // Control pump
        int pump_status = (moisture_percentage < config.moisture_threshold) ? 1 : 0;
        control_pump(pump_status);

        // Log data
        log_data(moisture_percentage, pump_status);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.pump_gpio, PI_OUTPUT);
    gpioWrite(config.pump_gpio, 0); // Ensure pump is off initially

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(config.spi_ce, 1000000, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return 1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to moisture percentage
float convert_to_percentage(int adc_value) {
    // Assuming ADC range is 0-1023
    return ((float)adc_value / 1023.0) * 100.0;
}

// Control water pump
void control_pump(int pump_state) {
    gpioWrite(config.pump_gpio, pump_state); // 1 for ON, 0 for OFF
}

// Log data to file
void log_data(float moisture_percentage, int pump_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %.2f%%, Pump: %s\n", timestamp, moisture_percentage, pump_status ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.pump_gpio, 0); // Turn off pump
    gpioTerminate();
}

