#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define DRV5055_A1_VCC 3.3
#define DRV5055_A1_VOUT_MV 0.1 // Example: 0.1 V full scale
#define VREF 3.3
#define GPIO_CS 8 // BCM GPIO 8
#define GPIO_DIN 9 // BCM GPIO 9
#define GPIO_CLK 11 // BCM GPIO 11
#define GPIO_CS_PIN 8
#define GPIO_DOUT 10 // BCM GPIO 10
#define LOG_FILE "magnetic_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init();
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008(int fd, int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_magnetic_field(float voltage);
int log_data(time_t timestamp, float magnetic_field);
void signal_handler(int signal);

// SPI Initialization
int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Transfer
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

// Read MCP3008 Channel
int read_mcp3008(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) == -1) {
        fprintf(stderr, "Error reading MCP3008\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to Voltage Conversion
float adc_to_voltage(int adc_value, float vref) {
    return ((float)adc_value / 1023.0) * vref;
}

// Voltage to Magnetic Field Conversion
float voltage_to_magnetic_field(float voltage) {
    // Assuming a linear relationship between voltage and magnetic field
    // This is a placeholder; replace with the actual calibration data
    float sensitivity = DRV5055_A1_VCC / DRV5055_A1_VOUT_MV; // Example: 3.3V / 0.1V = 33
    return (voltage - (DRV5055_A1_VCC / 2.0)) * sensitivity; // Example: 0.5V offset
}

// Log Data to File
int log_data(time_t timestamp, float magnetic_field) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    fprintf(log_file, "%ld,%.2f\n", timestamp, magnetic_field);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin modes
    gpioSetMode(GPIO_CS, PI_OUTPUT);
    gpioSetMode(GPIO_DIN, PI_OUTPUT);
    gpioSetMode(GPIO_CLK, PI_OUTPUT);
    gpioSetMode(GPIO_CS_PIN, PI_OUTPUT);
    gpioSetMode(GPIO_DOUT, PI_INPUT);

    // Initialize SPI
    if (spi_init() == -1) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value, skipping sample\n");
            gpioDelay(500); // Wait 500ms
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, VREF);

        // Convert voltage to magnetic field
        float magnetic_field = voltage_to_magnetic_field(voltage);

        // Get timestamp
        time_t timestamp = time(NULL);

        // Log data
        if (log_data(timestamp, magnetic_field) == -1) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Print to console
        printf("Timestamp: %ld, Magnetic Field: %.2f\n", timestamp, magnetic_field);

        // Wait 500ms
        gpioDelay(500);
    }

    // Cleanup (should not reach here if signal handler works)
    close(spi_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

