// Define GPIO pins
#define SPI_CE 8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define log file name
#define LOG_FILE "current_log.txt"

// Global variables
static volatile int running = 1;
static int spi_handle;

// Structure to hold SPI configuration
typedef struct {
    int ce_pin;
    int mosi_pin;
    int miso_pin;
    int sclk_pin;
    int spi_channel;
    int spi_speed;
} spi_config_t;

// Function prototypes
int spi_init(spi_config_t *config);
int spi_read(spi_config_t *config, int channel);
float adc_to_current(int adc_value);
int log_current(float current);
void signal_handler(int signal);
int cleanup();

// SPI initialization function
int spi_init(spi_config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config->ce_pin, PI_OUTPUT);
    gpioSetMode(config->mosi_pin, PI_OUTPUT);
    gpioSetMode(config->miso_pin, PI_INPUT);
    gpioSetMode(config->sclk_pin, PI_OUTPUT);

    gpioWrite(config->ce_pin, 1); // Deactivate chip select initially

    spi_handle = spiOpen(config->spi_channel, config->spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// SPI read function
int spi_read(spi_config_t *config, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(config->ce_pin, 0); // Activate chip select
    gpioDelay(1); // Small delay

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(config->ce_pin, 1); // Deactivate chip select
    gpioDelay(1); // Small delay

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// ADC to current conversion function
float adc_to_current(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // and a reference voltage of 3.3V (VREF)
    float voltage = (adc_value / 1023.0) * 3.3;
    float current = voltage * 1000; // Example: 1V = 1000mA
    return current;
}

// Log current to file function
int log_current(float current) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s %.2f A\n", timestamp, current);
    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
int cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

int main() {
    // Initialize SPI configuration
    spi_config_t spi_config = {
        .ce_pin = SPI_CE,
        .mosi_pin = SPI_MOSI,
        .miso_pin = SPI_MISO,
        .sclk_pin = SPI_SCLK,
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED
    };

    // Initialize SPI
    if (spi_init(&spi_config) != 0) {
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Current sensor monitoring started. Press Ctrl+C to exit.\n");

    // Sampling loop
    while (running) {
        // Read ADC value
        int adc_value = spi_read(&spi_config, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample.\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value);

        // Log current to file
        if (log_current(current) != 0) {
            fprintf(stderr, "Error logging current, skipping.\n");
        }

        // Delay for 100ms
        gpioDelay(100000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

