    gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
    return value;
}

// Function to determine object presence based on sensor readings
int determine_object_presence(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0) ? 0 : 1; // Active-low
}

