#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_DIR "/home/pi/security_cam/"
#define LOG_FILE "/var/log/security_cam.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    program_running = 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    return 0;
}

int capture_image() {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[256];
    char command[512];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.jpg", timeinfo);
    snprintf(command, sizeof(command), "libcamera-still -o %s%s%s", CAPTURE_DIR, filename, "\0");

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        perror("execl failed");
        exit(EXIT_FAILURE);
    } else if (pid < 0) {
        // Fork failed
        syslog(LOG_ERR, "Fork failed");
        return -1;
    }

    int status;
    if (waitpid(pid, &status, 0) == -1) {
        syslog(LOG_ERR, "Waitpid failed");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        syslog(LOG_ERR, "Child process exited with non-zero status");
        return -1;
    }

    syslog(LOG_INFO, "Image captured: %s", filename);
    return 0;
}

int log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
    return 0;
}

int main() {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting security camera program");

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        syslog(LOG_ERR, "Failed to register signal handler");
        closelog();
        return 1;
    }

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "GPIO initialized successfully");

    while (program_running) {
        int motion_detected = gpioRead(GPIO_PIN);
        if (motion_detected) {
            syslog(LOG_INFO, "Motion detected!");

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

            // Re-read the pin after debounce
            if (gpioRead(GPIO_PIN) == motion_detected) {
                syslog(LOG_INFO, "Motion confirmed!");

                if (capture_image() != 0) {
                    syslog(LOG_ERR, "Image capture failed");
                } else {
                    log_event("Image captured successfully");
                }
            } else {
                syslog(LOG_WARNING, "Motion re-read failed, no image captured");
            }
        }

        gpioDelay(50 * 1000); // Poll every 50ms
    }

    syslog(LOG_INFO, "Shutting down security camera program");
    gpioTerminate();
    closelog();
    return 0;
}

