#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

// Define the camera device and buffer size
#define CAMERA_DEVICE "/dev/video0"
#define BUFFER_SIZE 640 * 480 * 1 // 640x480 grayscale image

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int camera_fd = -1;
void *buffer = NULL;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nSignal received, terminating...\n");
}

// Function to open the camera device
int open_camera(const char *device) {
    int fd = open(device, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to configure the camera for grayscale 8-bit format
int configure_camera(int fd) {
    unsigned char buffer[64];
    buffer[0] = 0x02; // Request format change
    buffer[1] = 0x00; // 8-bit grayscale

    if (ioctl(fd, VIDIOC_G_FMT, buffer) == -1) {
        fprintf(stderr, "Error changing format: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to allocate memory for the buffer
int allocate_buffer(int fd, size_t size) {
    buffer = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to unmap the buffer
void unmap_buffer(int fd) {
    if (buffer != NULL) {
        if (munmap(buffer, BUFFER_SIZE) == -1) {
            fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
        }
        buffer = NULL;
    }
}

// Function to save the frame as a PGM file
int save_frame(const void *frame, size_t size) {
    FILE *fp = fopen("image_0001.pgm", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening image_0001.pgm: %s\n", strerror(errno));
        return -1;
    }

    // Write PGM header
    fprintf(fp, "P5\n640 480\n255\n");

    // Write the frame data
    size_t bytes_written = fwrite(frame, 1, size, fp);
    if (bytes_written != size) {
        fprintf(stderr, "Error writing frame data: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to read a frame from the camera
int read_frame(int fd, void *frame, size_t size) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout reading from camera\n");
        return -1; // Timeout
    } else {
        ssize_t bytes_read = read(fd, frame, size);
        if (bytes_read == -1) {
            fprintf(stderr, "Error reading from camera: %s\n", strerror(errno));
            return -1;
        } else if (bytes_read != size) {
            fprintf(stderr, "Incomplete frame read (%zd bytes, expected %zu)\n", bytes_read, size);
            return -1; // Incomplete read
        }
        return 0;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    char *camera_device = CAMERA_DEVICE;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "c:")) != -1) {
        switch (opt) {
            case 'c':
                camera_device = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-c camera_device]\n", argv[0]);
                return 1;
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the camera device
    camera_fd = open_camera(camera_device);
    if (camera_fd == -1) {
        return 1;
    }

    // Configure the camera
    if (configure_camera(camera_fd) == -1) {
        close(camera_fd);
        return 1;
    }

    // Allocate memory for the buffer
    if (allocate_buffer(camera_fd, BUFFER_SIZE) == -1) {
        close(camera_fd);
        return 1;
    }

    // Main loop
    int frame_number = 1;
    while (!terminate) {
        if (read_frame(camera_fd, buffer, BUFFER_SIZE) == 0) {
            if (save_frame(buffer, BUFFER_SIZE) == 0) {
                printf("Saved frame %d\n", frame_number++);
            } else {
                fprintf(stderr, "Failed to save frame %d\n", frame_number);
            }
        } else {
            fprintf(stderr, "Failed to read frame\n");
        }
    }

    // Clean up resources
    unmap_buffer(camera_fd);
    close(camera_fd);

    printf("Exiting cleanly.\n");
    return 0;
}

