#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/select.h>

#define DEVICE_NAME "/dev/video0"
#define FRAME_LOG_FILE "frame_log.txt"
#define MAX_FRAME_SIZE 65536 // 64KB

// Structure to hold frame data and timestamp
typedef struct {
    unsigned char *data;
    long timestamp;
    size_t size;
} FrameData;

// Global variables
static int fd = -1;
static FrameData *frame_buffer = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int open_device(const char *device_name);
int init_device(int fd);
int start_capturing(int fd);
int stop_capturing(int fd);
int close_device(int fd);
int capture_frame(int fd, FrameData *frame);
int write_frame_data_to_file(FrameData frame);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to initialize the video device
int init_device(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Example resolution
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    // Allocate buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        return -1;
    }

    // Map buffer
    frame_buffer = (FrameData *)mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (frame_buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        return -1;
    }

    return 0;
}

// Function to start capturing
int start_capturing(int fd) {
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting capture");
        return -1;
    }

    return 0;
}

// Function to stop capturing
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping capture");
        return -1;
    }
    return 0;
}

// Function to close the device
int close_device(int fd) {
    if (frame_buffer != NULL) {
        if (munmap(frame_buffer, frame_buffer->size) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
        frame_buffer = NULL;
    }
    if (close(fd) < 0) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

// Function to capture a frame
int capture_frame(int fd, FrameData *frame) {
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    frame->data = frame_buffer;
    frame->size = buf.bytesused;
    frame->timestamp = time(NULL) * 1000000 + (time(NULL) / 1); // Milliseconds

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to write frame data to file
int write_frame_data_to_file(FrameData frame) {
    FILE *fp = fopen(FRAME_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%ld\n", frame.timestamp);
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open device
    fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    // Initialize device
    if (init_device(fd) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing(fd) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        FrameData frame;
        fd_set fds;
        struct timeval tv;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 1; // Timeout of 1 second
        tv.tv_usec = 0;

        int retval = select(fd + 1, &fds, NULL, NULL, &tv);

        if (retval == -1) {
            perror("Error in select");
            break;
        } else if (retval) {
            // Frame is ready
            if (capture_frame(fd, &frame) == 0) {
                if (write_frame_data_to_file(frame) != 0) {
                    fprintf(stderr, "Error writing to log file.\n");
                }
            } else {
                fprintf(stderr, "Error capturing frame.\n");
            }
        } else {
            // Timeout, continue capturing
            continue;
        }
    }

    // Stop capturing
    if (stop_capturing(fd) < 0) {
        fprintf(stderr, "Error stopping capture.\n");
    }

    // Close device
    if (close_device(fd) < 0) {
        fprintf(stderr, "Error closing device.\n");
    }

    return EXIT_SUCCESS;
}

