#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <linux/videodev2.h>
#include <sys/time.h>

#define VIDEO_DEVICE "/dev/video0"
#define NUM_BUFFERS 4
#define FRAME_SIZE (YUYV_FRAME_SIZE * 2) // YUYV is 2 bytes per pixel, 2 pixels per frame
#define MAX_UDP_PACKET_SIZE 65000
#define MAX_UDP_FRAMES (MAX_UDP_PACKET_SIZE / FRAME_SIZE)

#define FRAME_HEADER_SIZE 16
#define FRAME_HEADER_OFFSET 0

// Structure to hold frame metadata
typedef struct {
    unsigned int frame_index;
    unsigned int fragment_index;
    unsigned int total_frags;
    unsigned int payload_size;
} frame_header_t;

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int video_fd = -1;
void *buffers = NULL;
int buffer_count = 0;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, stopping...\n", signal);
}

// Function to initialize the V4L2 device
int init_v4l2() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Open the video device
    video_fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (video_fd == -1) {
        perror("Error opening video device");
        return -1;
    }

    // Check device capabilities
    if (ioctl(video_fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying device capabilities");
        close(video_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", VIDEO_DEVICE);
        close(video_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", VIDEO_DEVICE);
        close(video_fd);
        return -1;
    }

    // Set video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Example resolution
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(video_fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting video format");
        close(video_fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(video_fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        close(video_fd);
        return -1;
    }

    buffer_count = req.count;

    // Map buffers
    buffers = calloc(req.count, sizeof(void *));
    if (!buffers) {
        perror("Error allocating buffer memory");
        close(video_fd);
        return -1;
    }

    for (int i = 0; i < req.count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(video_fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            close(video_fd);
            return -1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            close(video_fd);
            return -1;
        }
    }

    return 0;
}

// Function to configure the V4L2 device for streaming
int configure_v4l2() {
    struct v4l2_buffer buf;

    for (int i = 0; i < buffer_count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(video_fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(video_fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to capture a single frame
int capture_frame(unsigned char **data, unsigned int *frame_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(video_fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    *data = (unsigned char *)buffers[buf.index];
    *frame_size = buf.bytesused;

    if (ioctl(video_fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to fragment a frame into UDP datagrams
int fragment_frame(unsigned char *frame_data, unsigned int frame_size, int *num_datagrams, unsigned char ***datagrams, unsigned int **datagram_sizes) {
    unsigned int num_frags = (frame_size + FRAME_SIZE - 1) / (FRAME_SIZE + FRAME_HEADER_SIZE);
    if (num_frags > MAX_UDP_FRAMES) {
        fprintf(stderr, "Error: Frame too large for UDP fragmentation.\n");
        return -1;
    }

    *datagrams = (unsigned char **)(malloc(num_frags * sizeof(unsigned char *)));
    if (*datagrams == NULL) {
        perror("Error allocating memory for datagrams");
        return -1;
    }

    *datagram_sizes = (unsigned int *)(malloc(num_frags * sizeof(unsigned int)));
    if (*datagram_sizes == NULL) {
        perror("Error allocating memory for datagram sizes");
        free(*datagrams);
        return -1;
    }

    for (unsigned int i = 0; i < num_frags; ++i) {
        *datagrams[i] = (unsigned char *)(frame_data + i * (FRAME_SIZE + FRAME_HEADER_SIZE));
        *datagram_sizes[i] = FRAME_SIZE;
    }

    *num_datagrams = num_frags;

    return 0;
}

// Function to send a UDP datagram
int send_udp_packet(const unsigned char *datagram, unsigned int datagram_size, const char *ip_address, int port) {
    int sockfd;
    struct sockaddr_in servaddr;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(port);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, ip_address, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    // Send datagram
    if (sendto(sockfd, datagram, datagram_size, 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Function to unmap buffers and close the video device
void cleanup() {
    if (buffers) {
        for (int i = 0; i < buffer_count; ++i) {
            if (munmap(buffers[i], buffers[i]->length) == -1) {
                perror("Error unmapping buffer");
            }
        }
        free(buffers);
    }

    if (video_fd != -1) {
        close(video_fd);
    }
}

int main(int argc, char *argv[]) {
    const char *ip_address = "127.0.0.1";
    int port = 5000;
    unsigned char *frame_data = NULL;
    unsigned int frame_size = 0;
    unsigned char **datagrams = NULL;
    unsigned int *datagram_sizes = NULL;
    int num_datagrams = 0;
    int i;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize V4L2 device
    if (init_v4l2() == -1) {
        fprintf(stderr, "V4L2 initialization failed.\n");
        return 1;
    }

    // Configure V4L2 device for streaming
    if (configure_v4l2() == -1) {
