void signal_handler(int sig)
{
    if (sig == SIGINT || sig == SIGTERM)
    {
        fprintf(stderr, "\nCaught signal %d, stopping...\n", sig);
        keep_running = 0;
    }
}

// Function to initialize the camera
int init_camera()
{
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1)
    {
        perror("Error opening device");
        return -1;
    }

    // Check device capabilities
    int capabilities = 0;
    if (ioctl(fd, VIDIOC_GCAP, &capabilities) == -1)
    {
        perror("Error getting capabilities");
        close(fd);
        return -1;
    }

    if (!(capabilities & V4L2_CAP_VIDEO_CAPTURE) || !(capabilities & V4L2_CAP_STREAMING))
    {
        fprintf(stderr, "Error: Device does not support video capture or streaming.\n");
        close(fd);
        return -1;
    }

    // Set pixel format
    enum v4l2_format format = { .type = V4L2_BUF_TYPE_VIDEO_CAPTURE, .fmt = V4L2_PIX_FMT_MJPEG };
    if (ioctl(fd, VIDIOC_S_FMT, &format) == -1)
    {
        perror("Error setting pixel format");
        close(fd);
        return -1;
    }

    // Request buffers
    enum v4l2_requestbuffers req = { .count = n_buffers, .type = V4L2_BUF_TYPE_VIDEO_CAPTURE, .card = 0 };
    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1)
    {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    if (req.count < n_buffers)
    {
        fprintf(stderr, "Error: Not enough buffer memory available.\n");
        close(fd);
        return -1;
    }

    // Map buffers
    for (int i = 0; i < n_buffers; i++)
    {
        struct v4l2_buffer buf = { .type = V4L2_BUF_TYPE_VIDEO_CAPTURE, .index = i, .buffer = NULL };
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1)
        {
            perror("Error querying buffer");
            close(fd);
            return -1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED)
        {
            perror("Error mapping buffer");
            close(fd);
            return -1;
        }
    }

    // Queue buffers
    for (int i = 0; i < n_buffers; i++)
    {
        struct v4l2_buffer buf = { .type = V4L2_BUF_TYPE_VIDEO_CAPTURE, .index = i, .buffer = buffers[i] };
        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1)
        {
            perror("Error queuing buffer");
            close(fd);
            return -1;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1)
    {
        perror("Error starting streaming");
        close(fd);
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(unsigned char *image_data)
{
    struct v4l2_buffer buf = { .type = V4L2_BUF_TYPE_VIDEO_CAPTURE, .index = 0, .buffer = buffers[0] };
    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1)
    {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Verify bytes used
    if (buf.bytesused == 0)
    {
        fprintf(stderr, "Error: No data captured (bytesused = 0).\n");
        return -1;
    }

    // Copy data to image buffer
    memcpy(image_data, buffers[0], buf.bytesused);

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1)
    {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

