int write_jpeg_to_file(unsigned char *jpeg_data, int jpeg_size)
{
    FILE *fp = fopen(IMAGE_JPEG_FILENAME, "wb");
    if (fp == NULL)
    {
        perror("Error opening file for writing");
        return -1;
    }

