    {
        fprintf(stderr, "JPEG encoding failed.\n");
        // Clean up already allocated resources
        for (int i = 0; i < n_buffers; i++)
        {
            if (buffers[i] != NULL) munmap(buffers[i], BUFFER_SIZE);
        }
        if (fd != -1) close(fd);
        if (mjpeg_data != NULL) free(mjpeg_data);
        if (jpeg_data != NULL) free(jpeg_data);
        return 1;
    }

    // Write JPEG to file
    if (write_jpeg_to_file(jpeg_data, IMAGE_JPEG_SIZE) == -1)
    {
        fprintf(stderr, "JPEG writing failed.\n");
        // Clean up already allocated resources
        for (int i = 0; i < n_buffers; i++)
        {
            if (buffers[i] != NULL) munmap(buffers[i], BUFFER_SIZE);
        }
        if (fd != -1) close(fd);
        if (mjpeg_data != NULL) free(mjpeg_data);
        if (jpeg_data != NULL) free(jpeg_data);
        return 1;
    }

    // Clean up resources
    for (int i = 0; i < n_buffers; i++)
    {
        if (buffers[i] != NULL) munmap(buffers[i], BUFFER_SIZE);
    }
    if (fd != -1) close(fd);
    if (mjpeg_data != NULL) free(mjpeg_data);
    if (jpeg_data != NULL) free(jpeg_data);

    printf("Image saved to %s\n", IMAGE_JPEG_FILENAME);

