    for (int i = 0; i < n_buffers; i++)
    {
        struct v4l2_buffer buf = { .type = V4L2_BUF_TYPE_VIDEO_CAPTURE, .index = i, .buffer = buffers[i] };
        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1)
        {
            perror("Error queuing buffer");
            close(fd);
            return -1;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1)
    {
        perror("Error starting streaming");
        close(fd);
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(unsigned char *image_data)
{
    struct v4l2_buffer buf = { .type = V4L2_BUF_TYPE_VIDEO_CAPTURE, .index = 0, .buffer = buffers[0] };
    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1)
    {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Verify bytes used
    if (buf.bytesused == 0)
    {
        fprintf(stderr, "Error: No data captured (bytesused = 0).\n");
        return -1;
    }

    // Copy data to image buffer
    memcpy(image_data, buffers[0], buf.bytesused);

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1)
    {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to encode MJPEG to JPEG (dummy implementation)
int encode_jpeg(unsigned char *mjpeg_data, unsigned char *jpeg_data, int jpeg_size)
{
    // This is a placeholder.  A real implementation would use a JPEG encoder.
    // For example, you could use libjpeg or a similar library.
    // This dummy implementation just copies the MJPEG data to the JPEG buffer.
    memcpy(jpeg_data, mjpeg_data, jpeg_size);
    return 0;
}

// Function to write the JPEG data to a file
int write_jpeg_to_file(unsigned char *jpeg_data, int jpeg_size)
{
    FILE *fp = fopen(IMAGE_JPEG_FILENAME, "wb");
    if (fp == NULL)
    {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(jpeg_data, 1, jpeg_size, fp);
    if (bytes_written != jpeg_size)
    {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %d\n", bytes_written, jpeg_size);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main()
{
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize camera
    if (init_camera() == -1)
    {
        fprintf(stderr, "Camera initialization failed.\n");
        return 1;
    }

    // Allocate memory for MJPEG and JPEG data
    unsigned char *mjpeg_data = (unsigned char *)malloc(BUFFER_SIZE);
    unsigned char *jpeg_data = (unsigned char *)malloc(IMAGE_JPEG_SIZE);
    if (!mjpeg_data || !jpeg_data)
    {
        perror("Error allocating memory");
        // Clean up already allocated resources
        for (int i = 0; i < n_buffers; i++)
        {
            if (buffers[i] != NULL) munmap(buffers[i], BUFFER_SIZE);
        }
        if (fd != -1) close(fd);
        if (mjpeg_data != NULL) free(mjpeg_data);
        if (jpeg_data != NULL) free(jpeg_data);
        return 1;
    }

    // Capture frame
    if (capture_frame(mjpeg_data) == -1)
    {
        fprintf(stderr, "Frame capture failed.\n");
        // Clean up already allocated resources
        for (int i = 0; i < n_buffers; i++)
        {
            if (buffers[i] != NULL) munmap(buffers[i], BUFFER_SIZE);
        }
        if (fd != -1) close(fd);
        if (mjpeg_data != NULL) free(mjpeg_data);
        if (jpeg_data != NULL) free(jpeg_data);
        return 1;
    }

    // Encode MJPEG to JPEG
    if (encode_jpeg(mjpeg_data, jpeg_data, IMAGE_JPEG_SIZE) == -1)
    {
        fprintf(stderr, "JPEG encoding failed.\n");
        // Clean up already allocated resources
        for (int i = 0; i < n_buffers; i++)
        {
            if (buffers[i] != NULL) munmap(buffers[i], BUFFER_SIZE);
        }
        if (fd != -1) close(fd);
        if (mjpeg_data != NULL) free(mjpeg_data);
        if (jpeg_data != NULL) free(jpeg_data);
        return 1;
    }

    // Write JPEG to file
    if (write_jpeg_to_file(jpeg_data, IMAGE_JPEG_SIZE) == -1)
    {
        fprintf(stderr, "JPEG writing failed.\n");
        // Clean up already allocated resources
        for (int i = 0; i < n_buffers; i++)
        {
            if (buffers[i] != NULL) munmap(buffers[i], BUFFER_SIZE);
        }
        if (fd != -1) close(fd);
        if (mjpeg_data != NULL) free(mjpeg_data);
        if (jpeg_data != NULL) free(jpeg_data);
        return 1;
    }

    // Clean up resources
    for (int i = 0; i < n_buffers; i++)
    {
        if (buffers[i] != NULL) munmap(buffers[i], BUFFER_SIZE);
    }
    if (fd != -1) close(fd);
    if (mjpeg_data != NULL) free(mjpeg_data);
    if (jpeg_data != NULL) free(jpeg_data);

    printf("Image saved to %s\n", IMAGE_JPEG_FILENAME);

