// Define GPIO pins
#define PAN_SERVO 4
#define TILT_SERVO 5
#define TILT_UP 6
#define TILT_DOWN 7
#define PAN_LEFT 8
#define PAN_RIGHT 9

// Define PWM frequency and period
#define PWM_FREQUENCY 50
#define PWM_PERIOD 20000 // 20 ms

// Define servo range
#define SERVO_MIN 25
#define SERVO_MAX 125

// Global variables
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int init_pwm();
int init_servo();
int init_buttons();
void set_pan_angle(int angle);
void set_tilt_angle(int angle);
void handle_button(int gpio, int level, uint32_t tick, void *user_data);
void poll_buttons();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(PAN_SERVO, PI_OUTPUT);
    gpioSetMode(TILT_SERVO, PI_OUTPUT);
    gpioSetMode(TILT_UP, PI_INPUT);
    gpioSetMode(TILT_DOWN, PI_INPUT);
    gpioSetMode(PAN_LEFT, PI_INPUT);
    gpioSetMode(PAN_RIGHT, PI_INPUT);

    gpioSetPullUpDown(TILT_UP, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT, PI_PUD_UP);

    return 0;
}

// Initialize PWM
int init_pwm() {
    gpioSetPWMfrequency(PAN_SERVO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO, PWM_FREQUENCY);
    gpioSetPWMrange(PAN_SERVO, 1000);
    gpioSetPWMrange(TILT_SERVO, 1000);

    gpioPWM(PAN_SERVO, 500); // Initial pan angle (midpoint)
    gpioPWM(TILT_SERVO, 500); // Initial tilt angle (midpoint)

    return 0;
}

// Initialize servo
int init_servo() {
    gpioServo(PAN_SERVO, 500); // Set initial pan angle
    gpioServo(TILT_SERVO, 500); // Set initial tilt angle
    return 0;
}

// Initialize buttons
int init_buttons() {
    gpioSetMode(PAN_LEFT, PI_INPUT);
    gpioSetMode(PAN_RIGHT, PI_INPUT);
    gpioSetMode(TILT_UP, PI_INPUT);
    gpioSetMode(TILT_DOWN, PI_INPUT);

    gpioSetPullUpDown(PAN_LEFT, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT, PI_PUD_UP);
    gpioSetPullUpDown(TILT_UP, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN, PI_PUD_UP);

    return 0;
}

// Set pan angle
void set_pan_angle(int angle) {
    if (angle < SERVO_MIN) angle = SERVO_MIN;
    if (angle > SERVO_MAX) angle = SERVO_MAX;
    gpioPWM(PAN_SERVO, angle);
}

// Set tilt angle
void set_tilt_angle(int angle) {
    if (angle < SERVO_MIN) angle = SERVO_MIN;
    if (angle > SERVO_MAX) angle = SERVO_MAX;
    gpioPWM(TILT_SERVO, angle);
}

// Button handler
void handle_button(int gpio, int level, uint32_t tick, void *user_data) {
    static int pan_angle = 75;
    static int tilt_angle = 75;

    if (gpio == PAN_LEFT) {
        pan_angle += 5;
        if (pan_angle > SERVO_MAX) pan_angle = SERVO_MAX;
        set_pan_angle(pan_angle);
    } else if (gpio == PAN_RIGHT) {
        pan_angle -= 5;
        if (pan_angle < SERVO_MIN) pan_angle = SERVO_MIN;
        set_pan_angle(pan_angle);
    } else if (gpio == TILT_UP) {
        tilt_angle += 5;
        if (tilt_angle > SERVO_MAX) tilt_angle = SERVO_MAX;
        set_tilt_angle(tilt_angle);
    } else if (gpio == TILT_DOWN) {
        tilt_angle -= 5;
        if (tilt_angle < SERVO_MIN) tilt_angle = SERVO_MIN;
        set_tilt_angle(tilt_angle);
    }
}

// Poll buttons
void poll_buttons() {
    gpioSetAlertFuncEx(PAN_LEFT, handle_button, NULL);
    gpioSetAlertFuncEx(PAN_RIGHT, handle_button, NULL);
    gpioSetAlertFuncEx(TILT_UP, handle_button, NULL);
    gpioSetAlertFuncEx(TILT_DOWN, handle_button, NULL);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize PWM
    if (init_pwm() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize servo
    if (init_servo() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize buttons
    if (init_buttons() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        poll_buttons();
        gpioDelay(50); // 50 ms
    }

    // Clean up
    gpioPWM(PAN_SERVO, 0); // Stop PWM
    gpioPWM(TILT_SERVO, 0); // Stop PWM
    gpioTerminate();

    return 0;
}

