#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <signal.h>
#include <jpeglib.h>
#include <math.h>

// Configuration
#define VIDEO_DEVICE "/dev/video0"
#define BUFFER_COUNT 2
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define JPEG_QUALITY 75
#define BLUR_RADIUS 5

// Global variables (minimize usage)
static volatile sig_atomic_t keep_running = 1;
static int fd = -1;
static void *buffers[BUFFER_COUNT];
static unsigned int buffer_size = 0;

// Structure to hold JPEG parameters
struct my_jpeg_compress_struct {
  struct jpeg_compress_struct cinfo;
  struct jpeg_error_mgr jerr;
};

// Structure to hold JPEG error handling parameters
struct my_error_mgr {
  struct jpeg_error_mgr pub;
  jmp_buf setjmp_buffer;
};

// Function prototypes
int init_mmap(void);
int capture_frame(void);
int start_streaming(void);
int stop_streaming(void);
int unmap_buffers(void);
int free_buffers(void);
int encode_jpeg(unsigned char *yuyv_data, int width, int height, char *jpeg_data, int *jpeg_size);
void blur_yuyv_to_rgb(unsigned char *yuyv_data, unsigned char *rgb_data, int width, int height);
void signal_handler(int sig);
int init_jpeg_compress(struct my_jpeg_compress *cinfo, unsigned char *buffer, int width, int height);

// Signal handler
void signal_handler(int sig) {
  if (sig == SIGINT) {
    fprintf(stderr, "Caught SIGINT, exiting...\n");
    keep_running = 0;
  }
}

// Initialize memory mapping
int init_mmap(void) {
  fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK, 0);
  if (fd < 0) {
    perror("Error opening video device");
    return -1;
  }

  struct v4l2_capability cap;
  if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
    perror("Error querying capabilities");
    close(fd);
    return -1;
  }

  if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
    fprintf(stderr, "Error: %s is not a video capture device\n", VIDEO_DEVICE);
    close(fd);
    return -1;
  }

  struct v4l2_format fmt;
  memset(&fmt, 0, sizeof(fmt));
  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width = FRAME_WIDTH;
  fmt.fmt.pix.height = FRAME_HEIGHT;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
  fmt.fmt.pix.field = V4L2_FIELD_NONE;

  if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
    perror("Error setting format");
    close(fd);
    return -1;
  }

  struct v4l2_requestbuffers req;
  memset(&req, 0, sizeof(req));
  req.count = BUFFER_COUNT;
  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  req.memory = V4L2_MEMORY_MMAP;

  if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
    perror("Error requesting buffers");
    close(fd);
    return -1;
  }

  buffers[0] = mmap(NULL, 0, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
  buffers[1] = mmap(NULL, 0, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 1);

  if (buffers[0] == MAP_FAILED || buffers[1] == MAP_FAILED) {
    perror("Error mapping buffers");
    close(fd);
    return -1;
  }

  buffer_size = req.count * sizeof(unsigned char) * FRAME_WIDTH * FRAME_HEIGHT * 2; // YUYV

  return 0;
}

// Capture a frame
int capture_frame(void) {
  struct v4l2_buffer buf;
  memset(&buf, 0, sizeof(buf));
  buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  buf.memory = V4L2_MEMORY_MMAP;
  buf.index = 0;

  if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
    perror("Error dequeuing buffer");
    return -1;
  }

  if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
    perror("Error queuing buffer");
    return -1;
  }

  return 0;
}

// Start streaming
int start_streaming(void) {
  struct v4l2_buffer buf;
  memset(&buf, 0, sizeof(buf));
  buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  buf.memory = V4L2_MEMORY_MMAP;
  buf.index = 0;

  if (ioctl(fd, VIDIOC_STREAMON, &buf) < 0) {
    perror("Error starting streaming");
    return -1;
  }

  return 0;
}

// Stop streaming
int stop_streaming(void) {
  struct v4l2_buffer buf;
  memset(&buf, 0, sizeof(buf));
  buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  buf.memory = V4L2_MEMORY_MMAP;
  buf.index = 0;

  if (ioctl(fd, VIDIOC_STREAMOFF, &buf) < 0) {
    perror("Error stopping streaming");
    return -1;
  }

  return 0;
}

// Unmap memory buffers
int unmap_buffers(void) {
  if (munmap(buffers[0], buffer_size) < 0) {
    perror("Error unmapping buffer 0");
    return -1;
  }
  if (munmap(buffers[1], buffer_size) < 0) {
    perror("Error unmapping buffer 1");
    return -1;
  }
  return 0;
}

// Free memory buffers
int free_buffers(void) {
  if (buffers[0]) free(buffers[0]);
  if (buffers[1]) free(buffers[1]);
  return 0;
}

// Encode YUYV to JPEG
int encode_jpeg(unsigned char *yuyv_data, int width, int height, char *jpeg_data, int *jpeg_size) {
  struct my_jpeg_compress cinfo;
  struct my_error_mgr jerr;

  cinfo.err = jpeg_std_error(&jerr.pub);
  jerr.pub.error_exit = my_error_exit;
  jpeg_create_compress(&cinfo);

  jpeg_mem_dest(&cinfo, jpeg_data, jpeg_size);

  cinfo.image_width = width;
  cinfo.image_height = height;
  cinfo.input_components = 2; // YUYV
  cinfo.in_color_space = JCS_YCbCr; // YCbCr

  jpeg_set_defaults(&cinfo);
  jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

  jpeg_start_compress(&cinfo, TRUE);

  JSAMPROW row_pointer[1];
  int row_stride = width * 2; // YUYV

  while (cinfo.next_scanline < cinfo.image_height) {
    row_pointer[0] = &yuyv_data[cinfo.next_scanline * row_stride];
    jpeg_write_scanlines(&cinfo, row_pointer, 1);
  }

  jpeg_finish_compress(&cinfo);
  jpeg_destroy_compress(&cinfo);

  return 0;
}

// Blur YUYV to RGB (Simplified blur)
void blur_yuyv_to_rgb(unsigned char *yuyv_data, unsigned char *rgb_data, int width, int height) {
  for (int y = 0; y < height; y++) {
    for (int x = 0; x < width; x++) {
      // Simple blur (replace with actual blur algorithm)
      // This is a placeholder, a real blur would involve averaging neighboring pixels
      int yuv_index = y * width * 2 + x * 2;
      int r = yuyv_data[yuv_index];
      int g = yuyv_data[yuv_index + 1];
      int b = yuyv_data[yuv_index + 2];

      // Convert YUV to RGB (simplified)
      int r_rgb = r * 0.299 + g * 0.587 + b * 0.114;
      int g_rgb = -0.1687 * r - 0.6823 * g + 0.6823 * b;
      int b_rgb = 0.0591 * r - 0.3413 * g + 0.9566 * b;

      // Clamp to 0-255 range
      r_rgb = (r_rgb < 0) ? 0 : ((r_rgb > 255) ? 255 : r_rgb);
      g_rgb = (g_rgb < 0) ? 0 : ((g_rgb > 255) ? 255 : g_rgb);
