      g_rgb = (g_rgb < 0) ? 0 : ((g_rgb > 255) ? 255 : g_rgb);
      b_rgb = (b_rgb < 0) ? 0 : ((b_rgb > 255) ? 255 : b_rgb);

      rgb_data[y * width * 3 + x * 3] = r_rgb;
      rgb_data[y * width * 3 + x * 3 + 1] = g_rgb;
      rgb_data[y * width * 3 + x * 3 + 2] = b_rgb;
    }
  }
}

