#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for servos and buttons
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define PWM range (microseconds)
#define PWM_RANGE 2000000 // 2,000,000 us

// Define minimum and maximum pulse widths (microseconds)
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

// Define center pulse width (microseconds)
#define CENTER_PULSE_WIDTH 1500

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping servos and exiting...\n", signal);
}

// Function to set the PWM pulse width for a given GPIO pin
void set_servo_pulse_width(int gpio_pin, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }

    gpioServo(gpio_pin, pulse_width);
}

// Function to handle button presses and adjust servo position
void handle_button_press(int button_pin, int servo_pin) {
    int current_pulse_width;

    // Read the current pulse width from the servo
    current_pulse_width = gpioServo(servo_pin);

    // Determine the direction to move based on the button press
    if (button_pin == UP_BUTTON_PIN) {
        if (current_pulse_width < MAX_PULSE_WIDTH) {
            current_pulse_width += 10;
        }
    } else if (button_pin == DOWN_BUTTON_PIN) {
        if (current_pulse_width > MIN_PULSE_WIDTH) {
            current_pulse_width -= 10;
        }
    } else if (button_pin == LEFT_BUTTON_PIN) {
        if (current_pulse_width < MAX_PULSE_WIDTH) {
            current_pulse_width += 10;
        }
    } else if (button_pin == RIGHT_BUTTON_PIN) {
        if (current_pulse_width > MIN_PULSE_WIDTH) {
            current_pulse_width -= 10;
        }
    }

    // Set the new pulse width
    set_servo_pulse_width(servo_pin, current_pulse_width);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set GPIO pins as outputs for PWM control
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors on button pins
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    // Set initial servo positions
    set_servo_pulse_width(PAN_SERVO_PIN, CENTER_PULSE_WIDTH);
    set_servo_pulse_width(TILT_SERVO_PIN, CENTER_PULSE_WIDTH);

    // Print startup message
    printf("Pan-Tilt Camera Mount Control\n");
    printf("Pan Servo: GPIO%d, Tilt Servo: GPIO%d, Center Position: %d us\n", PAN_SERVO_PIN, TILT_SERVO_PIN, CENTER_PULSE_WIDTH);

    // Main loop
    while (program_running) {
        // Handle button presses
        handle_button_press(UP_BUTTON_PIN, PAN_SERVO_PIN);
        handle_button_press(DOWN_BUTTON_PIN, PAN_SERVO_PIN);
        handle_button_press(LEFT_BUTTON_PIN, TILT_SERVO_PIN);
        handle_button_press(RIGHT_BUTTON_PIN, TILT_SERVO_PIN);

        // Delay to prevent excessive CPU usage
        gpioDelay(50); // 50 ms delay
    }

    // Stop servos and terminate pigpio
    set_servo_pulse_width(PAN_SERVO_PIN, 0); // Stop pan servo
    set_servo_pulse_width(TILT_SERVO_PIN, 0); // Stop tilt servo
    gpioTerminate();

    return 0;
}

