        handle_button_press(LEFT_BUTTON_PIN, TILT_SERVO_PIN);
        handle_button_press(RIGHT_BUTTON_PIN, TILT_SERVO_PIN);

        // Delay to prevent excessive CPU usage
        gpioDelay(50); // 50 ms delay
    }

