// Function to post an image to a server
int post_image(char *filename, char *timestamp, int motion_status, int gpio_pin) {
    Config config;
    char ip_address[20];
    snprintf(ip_address, sizeof(ip_address), "%s", config.ip_address);

    struct sockaddr_in server_addr;
