#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 50
#define CAPTURE_COMMAND "libcamera-still -o /home/pi/images/%Y%m%d_%H%M%S_mmm.jpg --width 640 --height 480 --quality 85 --timeout 2000 --nopreview"
#define LOG_FILE "/home/pi/motion_capture.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to generate a timestamped filename
char* generate_filename() {
    time_t rawtime;
    struct tm *timeinfo;
    char *filename = (char*)malloc(50 * sizeof(char)); // Allocate memory for the filename
    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, 50, "%Y%m%d_%H%M%S_mmm.jpg", timeinfo);
    return filename;
}

// Function to capture an image using libcamera-still
int capture_image() {
    char *filename = generate_filename();
    if (filename == NULL) {
        fprintf(stderr, "Failed to generate filename. Skipping capture.\n");
        return -1;
    }

    char command[256];
    snprintf(command, sizeof(command), "%s", CAPTURE_COMMAND);

    int status = system(command);
    free(filename);

    if (status == 0) {
        return 0; // Success
    } else {
        fprintf(stderr, "Capture command failed with status %d. Logging error.\n", status);
        return -1; // Failure
    }
}

// Function to log messages to a file
void log_message(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not initialized. Skipping log.\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the message is written to the file immediately
}

// Function to handle motion detection
void handle_motion() {
    log_message("Motion detected! Capturing image.");
    if (capture_image() != 0) {
        log_message("Image capture failed.");
    }
}

// Function to log errors
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s: ERROR: %s\n", timestamp, message);
    if (log_file != NULL) {
        fprintf(log_file, "%s: ERROR: %s\n", timestamp, message);
        fflush(log_file);
    }
}

// Callback function for GPIO interrupt
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge
        gpioDelay(DEBOUNCE_MS * 1000); // Debounce
        if (gpioRead(GPIO_PIN) == 0) { // Confirm the edge
            handle_motion();
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable callback
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    log_message("Starting motion detection...");

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set alert function for falling edge detection
    gpioSetAlertFuncEx(GPIO_PIN, motion_detected_callback, NULL);

    log_message("Motion detection started.");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable callback
    gpioTerminate(); // Terminate pigpio
    fclose(log_file);

    return 0;
}

