    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set alert function for falling edge detection
    gpioSetAlertFuncEx(GPIO_PIN, motion_detected_callback, NULL);

    log_message("Motion detection started.");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable callback
    gpioTerminate(); // Terminate pigpio
    fclose(log_file);

    return 0;
}

