#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH  640
#define HEIGHT 480
#define BUFFER_SIZE (WIDTH * HEIGHT * 2)
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define RETRY_COUNT 5
#define RETRY_DELAY_MS 10

// Structure to hold camera information
typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
} camera_t;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to query camera capabilities
int query_camera_capabilities(int fd, unsigned char *capabilities) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    memcpy(capabilities, &cap.capabilities, sizeof(cap.capabilities));
    return 0;
}

// Function to configure the camera
int configure_camera(int fd, unsigned char *capabilities) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    if (ioctl(fd, VIDIOC_C_FMT, &fmt) == -1) {
        perror("VIDIOC_C_FMT");
        return -1;
    }

    if (!(capabilities[0] & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Format does not support streaming\n");
        return -1;
    }

    if (!(capabilities[1] & V4L2_CAP_FRAME_CAPTURE)) {
        fprintf(stderr, "Format does not support frame capture\n");
        return -1;
    }

    if (!(capabilities[2] & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Format does not support streaming\n");
        return -1;
    }

    return 0;
}

// Function to request a single memory-mapped buffer
int request_buffer(int fd, camera_t *camera) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; // Request only one buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    camera->buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (camera->buffer == MAP_FAILED) {
        perror("mmap");
        return -1;
    }
    camera->buffer_size = BUFFER_SIZE;

    return 0;
}

// Function to start streaming
int start_streaming(int fd, camera_t *camera) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        return -1;
    }

    camera->buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (camera->buffer == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    return 0;
}

// Function to capture a single frame
int capture_frame(int fd, camera_t *camera) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    return 0;
}

// Function to check frame dimensions and format
int check_frame_dimensions_format(int fd, camera_t *camera) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (buf.bytesused != WIDTH * HEIGHT * 2) {
        fprintf(stderr, "Frame size mismatch: expected %d, got %d\n", WIDTH * HEIGHT * 2, buf.bytesused);
        return -1;
    }

    if (buf.bytesused != camera->buffer_size) {
        fprintf(stderr, "Frame size mismatch: expected %zu, got %zu\n", camera->buffer_size, buf.bytesused);
        return -1;
    }

    return 0;
}

// Function to crop the frame
int crop_frame(int fd, camera_t *camera) {
    unsigned char *cropped_buffer = (unsigned char *)malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (cropped_buffer == NULL) {
        perror("malloc");
        return -1;
    }

    for (int i = 0; i < CROP_HEIGHT; i++) {
        for (int j = 0; j < CROP_WIDTH; j++) {
            int y = i * WIDTH + j;
            int u = y + HEIGHT;
            int v = u + HEIGHT;

            cropped_buffer[i * CROP_WIDTH + j * 2] = camera->buffer[y * 2];
            cropped_buffer[i * CROP_WIDTH + j * 2 + 1] = camera->buffer[u * 2];
        }
    }

    FILE *fp = fopen("cropped.yuv", "wb");
    if (fp == NULL) {
        perror("fopen");
        free(cropped_buffer);
        return -1;
    }

    size_t bytes_written = fwrite(cropped_buffer, 1, CROP_WIDTH * CROP_HEIGHT * 2, fp);
    if (bytes_written != CROP_WIDTH * CROP_HEIGHT * 2) {
        fprintf(stderr, "Write error: expected %zu, wrote %zu\n", CROP_WIDTH * CROP_HEIGHT * 2, bytes_written);
        fclose(fp);
        free(cropped_buffer);
        return -1;
    }

    fclose(fp);
    free(cropped_buffer);
    return 0;
}

int main() {
    camera_t camera;
    unsigned char capabilities[3];
    struct v4l2_buffer buf;
    int retry;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    camera.fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (camera.fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Query camera capabilities
    if (query_camera_capabilities(camera.fd, capabilities) == -1) {
        close(camera.fd);
