    if (configure_camera(camera.fd, capabilities) == -1) {
        close(camera.fd);
        return EXIT_FAILURE;
    }

    // Request a single memory-mapped buffer
    if (request_buffer(camera.fd, &camera) == -1) {
        close(camera.fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(camera.fd, &camera) == -1) {
        munmap(camera.buffer, camera.buffer_size);
        close(camera.fd);
        return EXIT_FAILURE;
    }

