        }
    } while (retry < RETRY_COUNT && program_running);

    if (!program_running) {
        fprintf(stderr, "Stream stopped during capture\n");
        munmap(camera.buffer, camera.buffer_size);
        close(camera.fd);
        return EXIT_FAILURE;
    }

    // Check frame dimensions and format
    if (check_frame_dimensions_format(camera.fd, &camera) == -1) {
        munmap(camera.buffer, camera.buffer_size);
        close(camera.fd);
        return EXIT_FAILURE;
    }

    // Crop the frame
    if (crop_frame(camera.fd, &camera) == -1) {
        munmap(camera.buffer, camera.buffer_size);
        close(camera.fd);
        return EXIT_FAILURE;
    }

    // Stop streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera.fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
    }

    // Unmap the buffer
    if (munmap(camera.buffer, camera.buffer_size) == -1) {
        perror("munmap");
    }

    // Close the device
    if (close(camera.fd) == -1) {
        perror("close");
    }

    printf("Program finished successfully.\n");
    return EXIT_SUCCESS;
}

