void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to set the angle of a servo motor
int set_servo_angle(int gpio_pin, int angle) {
    // Calculate pulse width based on angle (SG90 servo)
    int pulse_width = 1000 + (int)((float)angle / 180.0 * 1000.0);

    // Set the PWM duty cycle
    gpioPWM(gpio_pin, pulse_width);

    return 0; // Indicate success
}

// Function to move the pan servo
int move_pan_servo(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Pan servo angle out of range (%d)\n", angle);
        return -1; // Indicate error
    }
    return set_servo_angle(PAN_SERVO_PIN, angle);
}

// Function to move the tilt servo
int move_tilt_servo(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Tilt servo angle out of range (%d)\n", angle);
        return -1; // Indicate error
    }
    return set_servo_angle(TILT_SERVO_PIN, angle);
