#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <math.h>

// OLED display dimensions
#define OLED_WIDTH 128
#define OLED_HEIGHT 64

// I2C address of the OLED display
#define OLED_ADDR 0x3C

// I2C bus number (usually 1 on Raspberry Pi)
#define I2C_BUS 1

// Font data (5x7 bitmap font for digits 0-9)
const unsigned char font[][5] = {
    {0x00, 0x00, 0x00, 0x00, 0x00},   // 0
    {0x00, 0x00, 0x5F, 0x00, 0x00},   // 1
    {0x00, 0x07, 0x00, 0x07, 0x00},   // 2
    {0x00, 0x14, 0x7F, 0x14, 0x7F},   // 3
    {0x00, 0x24, 0x2A, 0x7F, 0x2A},   // 4
    {0x00, 0x24, 0x2A, 0x25, 0x00},   // 5
    {0x00, 0x36, 0x49, 0x49, 0x36},   // 6
    {0x00, 0x00, 0x36, 0x49, 0x49},   // 7
    {0x00, 0x00, 0x49, 0x49, 0x36},   // 8
    {0x00, 0x00, 0x49, 0x49, 0x1E}    // 9
};

// Function to write a command to the OLED display
int oled_write_command(int fd, unsigned char command) {
    unsigned char buffer[2];
    buffer[0] = 0x00; // Control byte: command
    buffer[1] = command;
    if (write(fd, buffer, 2) != 2) {
        fprintf(stderr, "Error writing command to OLED: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write data to the OLED display
int oled_write_data(int fd, unsigned char data) {
    unsigned char buffer[2];
    buffer[0] = 0x40; // Control byte: data
    buffer[1] = data;
    if (write(fd, buffer, 2) != 2) {
        fprintf(stderr, "Error writing data to OLED: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the OLED display
int oled_init(int fd) {
    // Initialization sequence (refer to SSD1306 datasheet)
    oled_write_command(fd, 0xAE); // Display off
    oled_write_command(fd, 0xD5); // Set display clock divide ratio/oscillator frequency
    oled_write_command(fd, 0x80); // --ratio
    oled_write_command(fd, 0xA8); // Set multiplex ratio
    oled_write_command(fd, 0x3F); // --ratio
    oled_write_command(fd, 0xD3); // Set display offset
    oled_write_command(fd, 0x00); // --offset
    oled_write_command(fd, 0x40); // Set start line address
    oled_write_command(fd, 0x8D); // Charge pump setting
    oled_write_command(fd, 0x14); // --enable
    oled_write_command(fd, 0x20); // Set memory addressing mode
    oled_write_command(fd, 0x00); // --horizontal addressing mode
    oled_write_command(fd, 0xA1); // Set segment re-map
    oled_write_command(fd, 0xC8); // Set COM output scan direction
    oled_write_command(fd, 0xDA); // Set COM pins hardware configuration
    oled_write_command(fd, 0x12); // --configuration
    oled_write_command(fd, 0x81); // Set contrast control
    oled_write_command(fd, 0xCF); // --contrast
    oled_write_command(fd, 0xD9); // Set pre-charge period
    oled_write_command(fd, 0xF1); // --period
    oled_write_command(fd, 0xDB); // Set VCOM deselect level
    oled_write_command(fd, 0x40); // --level
    oled_write_command(fd, 0xA4); // Display all points off
    oled_write_command(fd, 0xA6); // Set normal display
    oled_write_command(fd, 0xAF); // Display on
    return 0;
}

// Function to clear the OLED display
int oled_clear(int fd) {
    for (int i = 0; i < OLED_WIDTH * (OLED_HEIGHT / 8); i++) {
        oled_write_data(fd, 0x00);
    }
    return 0;
}

// Function to set the cursor position (not used in this example, but included for completeness)
int oled_set_cursor(int fd, int col, int row) {
    // SSD1306 does not have a direct cursor command.  This is a placeholder.
    // In a real implementation, you would calculate the address to write to
    // based on the cursor position and write the appropriate data.
    return 0; // Indicate success (replace with actual cursor setting logic)
}

// Function to write a character to the OLED display at a specific position
int oled_write_char(int fd, int x, int y, char c) {
    if (c < '0' || c > '9') return -1; // Only handle digits for simplicity

    unsigned char data;
    for (int i = 0; i < 5; i++) {
        data = font[c - '0'][i];
        for (int j = 0; j < 8; j++) {
            if ((data >> j) & 0x01) {
                // Set pixel (x + i, y + j) to 1
                int address = (y + j) / 8 * OLED_WIDTH + x + i;
                if (address >= 0 && address < OLED_WIDTH * (OLED_HEIGHT / 8)) {
                    unsigned char buffer[2];
                    buffer[0] = 0x40; // Control byte: data
                    buffer[1] = 0x01; // Data byte
                    if (write(fd, buffer, 2) != 2) {
                        fprintf(stderr, "Error writing data to OLED: %s\n", strerror(errno));
                        return -1;
                    }
                    // Write the pixel data (0 or 1)
                    unsigned char pixel_data[2];
                    pixel_data[0] = 0x40; // Control byte: data
                    pixel_data[1] = (unsigned char)((1 << j) & 0x01); // Data byte
                    if (write(fd, pixel_data, 2) != 2) {
                        fprintf(stderr, "Error writing data to OLED: %s\n", strerror(errno));
                        return -1;
                    }
                }
            }
        }
    }
    return 0;
}

// Function to write a string to the OLED display at a specific position
int oled_write_string(int fd, int x, int y, const char *str) {
    int current_x = x;
    for (int i = 0; str[i] != '\0'; i++) {
        if (oled_write_char(fd, current_x, y, str[i]) != 0) {
            fprintf(stderr, "Error writing character to OLED\n");
            return -1;
        }
        current_x += 6; // Each character is 6 pixels wide
    }
    return 0;
}

// Function to read the CPU temperature from /sys/class/thermal/thermal_zone0/temp
float read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    float temperature = 0.0;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1.0; // Indicate error
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temperature = atoi(buffer) / 1000.0;
    } else {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    return temperature;
}

// Function to read the CPU usage percentage from /proc/stat
float read_cpu_usage() {
    FILE *fp;
    char buffer[50];
    unsigned long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    float cpu_usage = 0.0;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening proc/stat: %s\n", strerror(errno));
        return -1.0; // Indicate error
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        if (sscanf(buffer, "cpu  %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
                   &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) == 10) {
            unsigned long prev_idle = idle + iowait;
            unsigned long prev_non_idle = user + nice + system + irq + softirq + steal + guest + guest_nice;
            unsigned long prev_total = prev_idle + prev_non_idle;

            unsigned long current_idle = idle + iowait;
            unsigned long current_non_idle = user + nice + system + irq + softirq + steal + guest + guest_nice;
            unsigned long current_total = current_idle + current_non_idle;

            unsigned long totald = current_total - prev_total;
            unsigned long idled = current_idle - prev_idle;

            cpu_usage = (float)(totald - idled) / totald * 100.0;
        } else {
            fprintf(stderr, "Error parsing CPU stats: %s\n", strerror(errno));
            fclose(fp);
            return -1.0; // Indicate error
        }
    } else {
        fprintf(stderr, "Error reading CPU stats: %s\n", strerror(errno));
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    return cpu_usage;
}

// Function to render the temperature and CPU usage on the OLED display
int render_on_oled(int fd, float temperature, float cpu_usage) {
    char temp_str[20];
    char usage_str[20];

    snprintf(temp_str, sizeof(temp_str), "Temp: %.1f C", temperature);
    snprintf(usage_str, sizeof(usage_str), "Usage: %.1f%%", cpu_usage);

    oled_clear(fd);
    oled_write_string(fd, 0, 0, temp_str);
    oled_write_string(fd, 0, 16, usage_str);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    oled_clear(fd);
    close(fd);
    exit(0);
}

int main() {
    int fd;
    float temperature, cpu_usage;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(fd, I2C_SLAVE, OLED_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Initialize the OLED display
    if (oled_init(fd) != 0) {
        fprintf(stderr, "Error initializing OLED display\n");
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading CPU temperature, using previous value\n");
            // Consider implementing a retry mechanism here
        }

        // Read CPU usage
        cpu_usage = read_cpu_usage();
        if (cpu_usage < 0) {
            fprintf(stderr, "Error reading CPU usage, using previous value\n");
            // Consider implementing a retry mechanism here
        }

        // Render on OLED display
        if (render_on_oled(fd, temperature, cpu_usage) != 0) {
            fprintf(stderr, "Error rendering on OLED display\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // The following lines will never be reached due to the infinite loop.
    close(fd);
    return 0;
}

