// Constants
#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0

#define LCD_LINE_1 0x80 // 1st line
#define LCD_LINE_2 0xC0 // 2nd line

#define LCD_BACKLIGHT 0x08  // On
#define ENABLE 0b00000100 // Enable bit

#define I2C_BUS 1

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
double flow_rate = 0.0;
int i2c_handle;
int lcd_initialized = 0;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick);
double calculate_flow_rate(int pulses, double time_interval);
double calculate_total_volume(double flow_rate, double time_interval);
void lcd_init();
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear();
void lcd_set_cursor(int col, int row);
void signal_handler(int signal);
void log_data(double flow_rate, double total_volume);

// Interrupt handler for pulse counting
void pulse_counter(int gpio, int level, uint32_t tick)
{
    if (level == PI_HIGH)
    {
        pulse_count++;
    }
}

// Function to calculate flow rate (L/min)
double calculate_flow_rate(int pulses, double time_interval)
{
    return (double)pulses / time_interval * 7.5; // YF-S201: 7.5 pulses/L
}

// Function to calculate total volume (L)
double calculate_total_volume(double flow_rate, double time_interval)
{
    return total_volume + flow_rate * time_interval;
}

// LCD initialization function
void lcd_init()
{
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error: I2C handle is invalid.\n");
        return;
    }

    // Initialise display
    lcd_byte(0x33, LCD_CMD); // Initialise
    lcd_byte(0x32, LCD_CMD); // Initialise
    lcd_byte(0x06, LCD_CMD); // Cursor move direction
    lcd_byte(0x0C, LCD_CMD); // Turn on display, cursor blinking
    lcd_byte(0x28, LCD_CMD); // Data length, number of lines, font size
    lcd_byte(0x01, LCD_CMD); // Clear display
    gpioDelay(5000);          // Delay 5ms
    lcd_byte(0x06, LCD_CMD); // Cursor move direction
    lcd_byte(0x0C, LCD_CMD); // Turn on display, cursor blinking
    gpioDelay(5000);          // Delay 5ms
}

// Function to send a byte to the LCD
void lcd_byte(int bits, int mode)
{
    // Send byte to data pins
    // bits = the data
    // mode = 1 for data, 0 for command

    int bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    // High bits
    if (i2cWriteByteData(i2c_handle, 0x00, bits_high) < 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
    }
    gpioDelay(1); // Delay 1us
    if (i2cWriteByteData(i2c_handle, 0x00, bits_high | ENABLE) < 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
    }
    gpioDelay(1); // Delay 1us
    if (i2cWriteByteData(i2c_handle, 0x00, bits_high & ~ENABLE) < 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
    }
    gpioDelay(1); // Delay 1us

    // Low bits
    if (i2cWriteByteData(i2c_handle, 0x00, bits_low) < 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
    }
    gpioDelay(1); // Delay 1us
    if (i2cWriteByteData(i2c_handle, 0x00, bits_low | ENABLE) < 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
    }
    gpioDelay(1); // Delay 1us
    if (i2cWriteByteData(i2c_handle, 0x00, bits_low & ~ENABLE) < 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
    }
    gpioDelay(1); // Delay 1us
}

// Function to print a string to the LCD
void lcd_string(const char *s)
{
    while (*s) {
        lcd_byte(*s++, LCD_CHR);
    }
}

// Function to clear the LCD display
void lcd_clear()
{
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(2000); // Delay 2ms
}

// Function to set the cursor position on the LCD
void lcd_set_cursor(int col, int row)
{
    int row_offsets[] = {0x00, 0x40};
    lcd_byte(0x80 | (col + row_offsets[row]), LCD_CMD);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    exit(0);
}

// Function to log data to the console
void log_data(double flow_rate, double total_volume)
{
    printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, total_volume);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for the flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_initialized = 1;
    lcd_init();

    // Set up interrupt handler for pulse counting
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter, NULL);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    time_t start_time, current_time;
    time(&start_time);
    int prev_pulse_count = 0;

    while (1)
    {
        // Calculate flow rate and total volume
        time(&current_time);
        double time_interval = difftime(current_time, start_time);
        if (time_interval >= 1.0) {
            int current_pulse_count = pulse_count - prev_pulse_count;
            flow_rate = calculate_flow_rate(current_pulse_count, time_interval);
            total_volume = calculate_total_volume(flow_rate, time_interval);

            // Log data
            log_data(flow_rate, total_volume);

            // Update LCD display
            lcd_clear();
            lcd_set_cursor(0, 0);
            char buffer[32];
            snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min", flow_rate);
            lcd_string(buffer);
            lcd_set_cursor(0, 1);
            snprintf(buffer, sizeof(buffer), "Vol: %.2f L", total_volume);
            lcd_string(buffer);

            // Reset pulse count and start time
            pulse_count = 0;
            time(&start_time);
            prev_pulse_count = current_pulse_count;
        }

        gpioDelay(100); // Delay 100ms
    }

    return 0;
}

