#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define ANEMOMETER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SAMPLE_WINDOW_MS 500

// Global variables
static volatile int pulse_count = 0;
static int i2c_handle;
static int spi_handle;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
int read_mcp3008(int channel);
float calculate_wind_speed(int pulses);
int calculate_wind_direction(int adc_value);
void update_lcd(float wind_speed, int wind_direction);
void signal_handler(int signal);
int lcd_init();
void lcd_clear();
void lcd_set_cursor(int row, int col);
void lcd_write_string(const char *str);

// LCD commands
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_CURSORSHIFT 0x10
#define LCD_FUNCTIONSET 0x20
#define LCD_SETCGRAMADDR 0x40
#define LCD_SETDDRAMADDR 0x80

// LCD flags
#define LCD_ENTRYRIGHT 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01
#define LCD_ENTRYSHIFTDECREMENT 0x00

// LCD segment bits (a-g)
#define LCD_CHR 1<<0
#define LCD_CMD 1<<1

// LCD flags for display control
#define LCD_DISPLAYON 0x04
#define LCD_CURSORON 0x02
#define LCD_BLINKON 0x01

// LCD flags for entry mode
#define LCD_ENTRYRIGHT 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01
#define LCD_ENTRYSHIFTDECREMENT 0x00

// LCD flags for function set
#define LCD_8BITMODE 0x10
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_1LINE 0x00
#define LCD_5x10DOTS 0x04
#define LCD_5x8DOTS 0x00

// Function to write a command to the LCD
void lcd_write_command(unsigned char cmd) {
    char data_u, data_l;
    unsigned char data_t[4];
    data_u = (cmd&0xF0);
    data_l = ((cmd<<4)&0xF0);
    data_t[0] = data_u|LCD_CMD;
    data_t[1] = data_u|LCD_CHR;
    data_t[2] = data_l|LCD_CMD;
    data_t[3] = data_l|LCD_CHR;
    i2cWriteDevice(i2c_handle, (char *)data_t, 4);
}

// Function to write a character to the LCD
void lcd_write_data(unsigned char data) {
    char data_u, data_l;
    unsigned char data_t[4];
    data_u = (data&0xF0);
    data_l = ((data<<4)&0xF0);
    data_t[0] = data_u|LCD_CHR;
    data_t[1] = data_u|LCD_CHR;
    data_t[2] = data_l|LCD_CMD;
    data_t[3] = data_l|LCD_CHR;
    i2cWriteDevice(i2c_handle, (char *)data_t, 4);
}

// Function to initialize the LCD
int lcd_init() {
    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0); // Bus 1, address 0x27, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // 4-bit initialization sequence
    lcd_write_command(0x33); // Initialize
    lcd_write_command(0x32); // Initialize
    lcd_write_command(0x28); // 4-bit mode, 2 lines, 5x8 font
    lcd_write_command(0x0C); // Display on, cursor off, blink off
    lcd_write_command(0x06); // Increment cursor, no shift
    lcd_write_command(0x01); // Clear display

    return 0;
}

// Function to clear the LCD display
void lcd_clear() {
    lcd_write_command(LCD_CLEARDISPLAY);
    gpioDelay(2000); // Delay for clear display command
}

// Function to set the cursor position
void lcd_set_cursor(int row, int col) {
    unsigned char address;
    if (row == 0) {
        address = 0x00 + col;
    } else {
        address = 0x40 + col;
    }
    lcd_write_command(0x80 + address);
}

// Function to write a string to the LCD
void lcd_write_string(const char *str) {
    while (*str) {
        lcd_write_data(*str++);
    }
}

// Interrupt callback function
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate wind speed (m/s)
float calculate_wind_speed(int pulses) {
    // Assuming 1 pulse per revolution, and a known circumference
    // For example, if the anemometer has a circumference of 0.01 meters,
    // and 1 revolution takes 1 second, the wind speed would be 0.01 m/s.
    // This is a simplified example and needs calibration for accurate results.
