    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Initialize the LCD
    lcd_handle = i2cOpen(1, LCD_I2C_ADDR, 0); // I2C bus 1, address 0x27, no flags
    if (lcd_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", lcd_handle);
        gpioTerminate();
        return 1;
    }
    lcd_init();

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt callback for pulse counting
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL);

    // Main loop
    while (running) {
        // Disable interrupt temporarily for reading
        gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, NULL, NULL);

