        float flow_rate = calculate_flow_rate(pulses);

        // Display flow rate on LCD
        lcd_clear();
        lcd_set_cursor(0, 0);
        char buffer[17];
        snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);
        lcd_string(buffer);

        // Re-enable interrupt
        gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL);

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    i2cClose(lcd_handle);
    return 0;
}

