// Define GPIO pins for row anodes (8x8 LED matrix)
#define ROW_1 2
#define ROW_2 3
#define ROW_3 4
#define ROW_4 17
#define ROW_5 27
#define ROW_6 22
#define ROW_7 10
#define ROW_8 9

// Define GPIO pins for column cathodes (8x8 LED matrix)
#define COL_1 14
#define COL_2 15
#define COL_3 18
#define COL_4 23
#define COL_5 24
#define COL_6 25
#define COL_7 8
#define COL_8 7

// Define the size of the LED matrix
#define MATRIX_SIZE 8

// Define the delay between columns (in milliseconds)
#define DELAY_MS 150

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set row anodes as outputs
    gpioSetMode(ROW_1, PI_OUTPUT);
    gpioSetMode(ROW_2, PI_OUTPUT);
    gpioSetMode(ROW_3, PI_OUTPUT);
    gpioSetMode(ROW_4, PI_OUTPUT);
    gpioSetMode(ROW_5, PI_OUTPUT);
    gpioSetMode(ROW_6, PI_OUTPUT);
    gpioSetMode(ROW_7, PI_OUTPUT);
    gpioSetMode(ROW_8, PI_OUTPUT);

    // Set column cathodes as outputs
    gpioSetMode(COL_1, PI_OUTPUT);
    gpioSetMode(COL_2, PI_OUTPUT);
    gpioSetMode(COL_3, PI_OUTPUT);
    gpioSetMode(COL_4, PI_OUTPUT);
    gpioSetMode(COL_5, PI_OUTPUT);
    gpioSetMode(COL_6, PI_OUTPUT);
    gpioSetMode(COL_7, PI_OUTPUT);
    gpioSetMode(COL_8, PI_OUTPUT);

    // Set all row anodes to HIGH initially (off)
    gpioWrite(ROW_1, 1);
    gpioWrite(ROW_2, 1);
    gpioWrite(ROW_3, 1);
    gpioWrite(ROW_4, 1);
    gpioWrite(ROW_5, 1);
    gpioWrite(ROW_6, 1);
    gpioWrite(ROW_7, 1);
    gpioWrite(ROW_8, 1);

    // Set all column cathodes to HIGH initially (off)
    gpioWrite(COL_1, 1);
    gpioWrite(COL_2, 1);
    gpioWrite(COL_3, 1);
    gpioWrite(COL_4, 1);
    gpioWrite(COL_5, 1);
    gpioWrite(COL_6, 1);
    gpioWrite(COL_7, 1);
    gpioWrite(COL_8, 1);

    return 0; // Indicate success
}

// Function to clear the LED matrix
void clear_matrix() {
    gpioWrite(ROW_1, 0);
    gpioWrite(ROW_2, 0);
    gpioWrite(ROW_3, 0);
    gpioWrite(ROW_4, 0);
    gpioWrite(ROW_5, 0);
    gpioWrite(ROW_6, 0);
    gpioWrite(ROW_7, 0);
    gpioWrite(ROW_8, 0);

    gpioWrite(COL_1, 1);
    gpioWrite(COL_2, 1);
    gpioWrite(COL_3, 1);
    gpioWrite(COL_4, 1);
    gpioWrite(COL_5, 1);
    gpioWrite(COL_6, 1);
    gpioWrite(COL_7, 1);
    gpioWrite(COL_8, 1);
}

// Function to light the LED matrix sequentially
void light_matrix() {
    for (int col = 1; col <= MATRIX_SIZE; col++) {
        // Set the current column cathode LOW
        gpioWrite(COL_1, (col == 1) ? 0 : 1);
        gpioWrite(COL_2, (col == 2) ? 0 : 1);
        gpioWrite(COL_3, (col == 3) ? 0 : 1);
        gpioWrite(COL_4, (col == 4) ? 0 : 1);
        gpioWrite(COL_5, (col == 5) ? 0 : 1);
        gpioWrite(COL_6, (col == 6) ? 0 : 1);
        gpioWrite(COL_7, (col == 7) ? 0 : 1);
        gpioWrite(COL_8, (col == 8) ? 0 : 1);

        // Set the corresponding row anodes HIGH sequentially
        for (int row = 1; row <= MATRIX_SIZE; row++) {
            gpioWrite(ROW_1, (row == 1) ? 1 : 0);
            gpioWrite(ROW_2, (row == 2) ? 1 : 0);
            gpioWrite(ROW_3, (row == 3) ? 1 : 0);
            gpioWrite(ROW_4, (row == 4) ? 1 : 0);
            gpioWrite(ROW_5, (row == 5) ? 1 : 0);
            gpioWrite(ROW_6, (row == 6) ? 1 : 0);
            gpioWrite(ROW_7, (row == 7) ? 1 : 0);
            gpioWrite(ROW_8, (row == 8) ? 1 : 0);

            // Small delay to allow the LED to light up
            gpioDelay(1); // 1 ms delay
        }
    }
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("8x8 LED Matrix Animation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Clear the matrix
        clear_matrix();

        // Light the matrix
        light_matrix();

        // Delay for the specified time
        gpioDelay(DELAY_MS * 1000); // Convert milliseconds to microseconds
    }

    // Clean up GPIO pins before exiting
    gpioWrite(ROW_1, 1);
    gpioWrite(ROW_2, 1);
    gpioWrite(ROW_3, 1);
    gpioWrite(ROW_4, 1);
    gpioWrite(ROW_5, 1);
    gpioWrite(ROW_6, 1);
    gpioWrite(ROW_7, 1);
    gpioWrite(ROW_8, 1);

    gpioWrite(COL_1, 1);
    gpioWrite(COL_2, 1);
    gpioWrite(COL_3, 1);
    gpioWrite(COL_4, 1);
    gpioWrite(COL_5, 1);
    gpioWrite(COL_6, 1);
    gpioWrite(COL_7, 1);
    gpioWrite(COL_8, 1);

    gpioTerminate();

    printf("Program terminated.\n");

    return 0;
}

