// Define the I2C bus and address
#define I2C_BUS 1
#define VL53L3CX_ADDR 0x29

// Define the register addresses (example, adjust based on datasheet)
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int model_id;
    int i2c_handle;
} sensor_t;

// Function prototypes
int init_sensor(sensor_t *sensor);
int read_distance(sensor_t *sensor);
void print_timestamped_distances(sensor_t *sensor);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to initialize the VL53L3CX sensor
int init_sensor(sensor_t *sensor) {
    // Check the model ID
    int model_id = i2cReadByteData(sensor->i2c_handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    sensor->model_id = model_id;
    printf("VL53L3CX Model ID: 0x%02X\n", model_id);

