#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define REG_PARTID 0x00
#define REG_REVID 0x01
#define REG_SEQID 0x02

#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0 0x24
#define REG_PS1_DATA1 0x25

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_si1145_data(int *proximity, int *ambient_light);
int log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the Si1145 sensor
int si1145_init() {
    // Reset the device
    if (i2cWriteByteData(i2c_handle, 0x07, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145: %s\n", strerror(errno));
        return -1;
    }
