#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define POLL_INTERVAL_MS 100
#define BLINK_DURATION_MS 100

FILE *log_file = NULL;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to write to the log file
int write_to_log(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s Object detected\n", timestamp);
    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

// Callback function for falling edge detection
void falling_edge_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge detected (LOW)
        char *timestamp = get_iso8601_timestamp();
        if (write_to_log(timestamp) != 0) {
            fprintf(stderr, "Error writing to log file.\n");
        }
        free(timestamp); // Free the allocated memory
        gpioWrite(LED_PIN, 1); // Turn LED on
        gpioDelay(BLINK_DURATION_MS * 1000); // Wait for blink duration
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    gpioTerminate(); // Release GPIO resources
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Release GPIO resources
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up falling edge callback
    gpioSetAlertFunc(SENSOR_PIN, falling_edge_callback);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for polling interval
    }

    return 0; // This line will never be reached due to the infinite loop, but it's good practice to include it.
}

