// APDS9960 I2C address
#define APDS9960_I2C_ADDR 0x39

// APDS9960 register addresses
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_PTIME 0x82
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int apds9960_init();
int apds9960_read_proximity();
int apds9960_read_rgb(int *red, int *green, int *blue);
int apds9960_write_register(uint8_t reg, uint8_t value);
int apds9960_read_register(uint8_t reg, uint8_t *value);
void log_data(int red, int green, int blue, int proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the APDS9960 sensor
int apds9960_init() {
    // Enable proximity and ALS (Ambient Light Sensing)
    if (apds9960_write_register(APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error enabling APDS9960\n");
        return -1;
    }

    // Set proximity time (ATIME) to 100ms
    if (apds9960_write_register(APDS9960_ATIME, 0xEB) < 0) {
        fprintf(stderr, "Error setting proximity time\n");
        return -1;
    }

    // Set proximity pulse count (PPULSE) to 1
    if (apds9960_write_register(APDS9960_PPULSE, 0x01) < 0) {
        fprintf(stderr, "Error setting proximity pulse count\n");
        return -1;
    }

    // Set ALS gain (CONTROL) to 1x
    if (apds9960_write_register(APDS9960_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error setting ALS gain\n");
        return -1;
    }

    return 0;
}

// Read proximity value from the sensor
int apds9960_read_proximity() {
    uint8_t proximity_data;
    if (apds9960_read_register(APDS9960_PDATA, &proximity_data) < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }
    return proximity_data;
}

// Read RGB color values from the sensor
int apds9960_read_rgb(int *red, int *green, int *blue) {
    uint8_t red_data, green_data, blue_data;

    if (apds9960_read_register(APDS9960_CDATAL, &red_data) < 0) return -1;
    if (apds9960_read_register(APDS9960_CDATAH, &red_data) < 0) return -1;
    *red = (int16_t)((red_data << 8) | (red_data >> 8));

    if (apds9960_read_register(APDS9960_RDATAL, &green_data) < 0) return -1;
    if (apds9960_read_register(APDS9960_RDATAH, &green_data) < 0) return -1;
    *green = (int16_t)((green_data << 8) | (green_data >> 8));

    if (apds9960_read_register(APDS9960_GDATAL, &blue_data) < 0) return -1;
    if (apds9960_read_register(APDS9960_GDATAH, &blue_data) < 0) return -1;
    *blue = (int16_t)((blue_data << 8) | (blue_data >> 8));

    return 0;
}

// Write a byte to an APDS9960 register
int apds9960_write_register(uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C write error: %d\n", result);
        return -1;
    }
    return 0;
}

// Read a byte from an APDS9960 register
int apds9960_read_register(uint8_t reg, uint8_t *value) {
    int result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 1) {
        fprintf(stderr, "I2C write (register select) error: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, (char *)value, 1);
    if (result != 1) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return -1;
    }
    return 0;
}

// Log data to the CSV file
void log_data(int red, int green, int blue, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, red, green, blue, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
