        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int red, green, blue, proximity;
    int retry_count = 0;
    const int max_retries = 3;

