        proximity = apds9960_read_proximity();
        if (proximity < 0) {
            fprintf(stderr, "Error reading proximity, retrying...\n");
            retry_count++;
            if (retry_count > max_retries) {
                fprintf(stderr, "Max retries reached, exiting\n");
                break;
            }
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        if (apds9960_read_rgb(&red, &green, &blue) < 0) {
            fprintf(stderr, "Error reading RGB, retrying...\n");
            retry_count++;
            if (retry_count > max_retries) {
                fprintf(stderr, "Max retries reached, exiting\n");
                break;
            }
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Log data if proximity exceeds threshold
        if (proximity > PROXIMITY_THRESHOLD) {
            log_data(red, green, blue, proximity);
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup
    printf("Closing I2C bus and log file...\n");
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

