#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define CH101_ADDR 0x70
#define DISTANCE_REG 0x00 // Example register address
#define SAMPLE_INTERVAL_MS 200
#define LOG_FILE "distance_log.txt"
#define BUFFER_SIZE 20 // Size of the timestamp buffer

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold timestamp data
typedef struct {
    char date[11];
    char time[8];
    char buffer[BUFFER_SIZE];
} TimestampData;

// Function prototypes
int initialize_i2c();
int read_distance(int *distance_mm);
int log_distance(int distance_mm);
void print_distance(int distance_mm);
void signal_handler(int signal);
void get_timestamp(TimestampData *data);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read distance from the CH101 sensor
int read_distance(int *distance_mm) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    // Convert the two bytes to a distance in millimeters
    *distance_mm = (buf[0] << 8) | buf[1];

    return 0;
}

// Function to log the distance to a file
int log_distance(int distance_mm) {
    TimestampData data;
    get_timestamp(&data);

    if (fprintf(log_file, "%s,%d\n", data.date, data.time, distance_mm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to print the distance to stdout
void print_distance(int distance_mm) {
    TimestampData data;
    get_timestamp(&data);

    printf("%s,%d\n", data.date, data.time, distance_mm);
}

// Function to get the current timestamp
void get_timestamp(TimestampData *data) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(data->date, sizeof(data->date), "%Y-%m-%d", timeinfo);
    strftime(data->time, sizeof(data->time), "%H:%M:%S", timeinfo);
    snprintf(data->buffer, BUFFER_SIZE, "%s", data->date);
}

