        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int distance_mm;
    int result;

    // Main loop
    while (program_running) {
        result = read_distance(&distance_mm);
        if (result == 0) {
            if (log_distance(distance_mm) == 0) {
