                fprintf(stderr, "Error logging distance\n");
            }
        } else {
            fprintf(stderr, "Error reading distance, skipping\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

