// I2C initialization
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int *distance) {
    char cmd[1] = {0x00}; // Example command to trigger a measurement
    char buf[2]; // Example buffer for 2 bytes of data
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Small delay for measurement

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1]; // Combine bytes into distance
    return 0;
}

// Write sensor data
int write_sensor_data(int reg, int data) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (data >> 8) & 0xFF; // MSB
    buf[2] = data & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C (data): %d\n", result);
        return -1;
    }
    return 0;
