#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define MEASURE_COMMAND 0x01
#define INTRUSION_THRESHOLD 1000 // mm
#define SAMPLE_DELAY_MS 100
#define MEASUREMENT_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance;
    int valid;
} SensorData;

// Function prototypes
int init_i2c();
int send_command(int handle, uint8_t command);
int read_response(int handle, uint8_t *buffer, int count);
int validate_header(uint8_t *buffer);
int extract_distance(uint8_t *buffer);
int sample_sensor(int handle, SensorData *data);
float calculate_average_distance(SensorData *data, int num_samples);
int log_intrusion(float average_distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint8_t command) {
    int result = i2cWriteByte(handle, command);
    if (result != 0) {
        fprintf(stderr, "Error sending command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read response from the sensor
int read_response(int handle, uint8_t *buffer, int count) {
    int result = i2cReadDevice(handle, (char *)buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading response: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate the sensor response header
int validate_header(uint8_t *buffer) {
    if (buffer[0] != 0x01) {
        fprintf(stderr, "Invalid sensor response header\n");
        return -1;
    }
    return 0;
}

// Extract distance from the sensor response
int extract_distance(uint8_t *buffer) {
    int distance = (buffer[11] << 8) | buffer[12];
    return distance;
}

// Sample the sensor
int sample_sensor(int handle, SensorData *data) {
    uint8_t buffer[15];
    if (send_command(handle, MEASURE_COMMAND) != 0) {
        data->distance = -1; // Indicate error
        data->valid = 0;
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay for measurement
    if (read_response(handle, buffer, 15) != 0) {
        data->distance = -1; // Indicate error
        data->valid = 0;
        return -1;
    }
    if (validate_header(buffer) != 0) {
        data->distance = -1; // Indicate error
        data->valid = 0;
        return -1;
    }
    data->distance = extract_distance(buffer);
    data->valid = 1;
    return 0;
}

// Calculate the average distance
float calculate_average_distance(SensorData *data, int num_samples) {
    float sum = 0.0;
    int count = 0;
    for (int i = 0; i < num_samples; i++) {
        if (data[i].valid) {
            sum += data[i].distance;
            count++;
        }
    }
    if (count > 0) {
        return sum / count;
    } else {
        return -1.0; // Indicate no valid samples
    }
}

// Log intrusion event
int log_intrusion(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (average_distance < INTRUSION_THRESHOLD) {
        fprintf(log_file, "%s, %.2f\n", timestamp, average_distance);
        fflush(log_file); // Ensure data is written to file immediately
        return 0;
    } else {
        return -1; // No intrusion
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    SensorData sensor_data[10];
    int num_valid_samples = 0;

    // Main loop
    while (!terminate) {
        for (int i = 0; i < 10; i++) {
            if (sample_sensor(i2c_handle, &sensor_data[i]) == 0) {
                num_valid_samples++;
            }
            gpioDelay(SAMPLE_DELAY_MS * 1000); // Delay between samples
        }

        float average_distance = calculate_average_distance(sensor_data, 10);

        if (average_distance >= 0) {
            if (log_intrusion(average_distance) == 0) {
                printf("Intrusion detected! Average distance: %.2f mm\n", average_distance);
            }
        }

        gpioDelay(100 * 1000); // Delay between cycles
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

