// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int i2c_read_byte(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02x: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02x: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the model ID from the VL53L0X
int read_model_id(int handle) {
    int model_id = i2c_read_byte(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
