#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4A
#define DISTANCE_REG 0x00 // Replace with actual register address
#define DISTANCE_SIZE 2 // Replace with actual size of the distance data

int i2c_fd = -1; // Global file descriptor for I2C

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, closing I2C device and exiting.\n", sig);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        exit(0);
    }
}

// Function to initialize the I2C bus
int init_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to set the I2C slave address
int set_i2c_slave(int fd, unsigned char address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

// Function to read data from the I2C device
int read_i2c(int fd, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to write data to the I2C device
int write_i2c(int fd, unsigned char *data, int len) {
    if (write(fd, data, len) != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read the distance measurement
int read_distance(int fd, unsigned short *distance) {
    unsigned char data[DISTANCE_SIZE];
    if (read_i2c(fd, data, DISTANCE_SIZE) < 0) {
        return -1;
    }

    *distance = (data[0] << 8) | data[1]; // Combine the two bytes into a 16-bit value
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Set I2C slave address
    if (set_i2c_slave(i2c_fd, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor presence by reading a register
    unsigned char verify_data[1];
    if (read_i2c(i2c_fd, verify_data, 1) < 0) {
        fprintf(stderr, "Failed to read from sensor. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        unsigned short distance;
        if (read_distance(i2c_fd, &distance) == 0) {
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance. Continuing.\n");
        }

        nanosleep((const struct timespec[]){{0, 500000000}}, NULL); // 500ms
    }

    // The following lines will never be reached due to the infinite loop
    close(i2c_fd);
    return 0;
}

