        } else {
            fprintf(stderr, "%s - Error reading sensor data\n", timestamp);
        }

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

