#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 200000 // 200ms
#define MAX_DISTANCE 400 // cm
#define TIMEOUT_PULSE 38000 // 38ms

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    return 0;
}

void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

long measure_pulse_width() {
    long start_tick, end_tick, diff;

    // Wait for rising edge
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for falling edge
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    if (diff < 0) {
        diff += 0xFFFFFFFF; // Handle tick rollover
    }

    return diff;
}

float calculate_distance(long pulse_width) {
    if (pulse_width <= 0 || pulse_width > TIMEOUT_PULSE) {
        return -1.0; // Invalid pulse width
    }

    // Speed of sound in air (cm/us) = 0.0343 cm/us
    // Distance = (Time * Speed of Sound) / 2
    return (float)pulse_width * 0.0343 / 2.0;
}

void log_data(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);
}

void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    while (!terminate) {
        trigger_pulse();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            if (distance > 0 && distance <= MAX_DISTANCE) {
                log_data(distance);
            } else {
                fprintf(stderr, "Invalid distance measurement: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Timeout waiting for echo\n");
        }

        gpioDelay(1000); // Read every 1 second
    }

    cleanup_gpio();
    return 0;
}

