#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define MAGIC_WORD_LENGTH 8
#define RANGE_PROFILE_LENGTH 128
#define TARGET_THRESHOLD 1.0
#define ALERT_DURATION 2 // seconds
#define GPIO_PIN 17

// Structure to hold UART configuration
typedef struct {
    int fd;
    struct termios tty;
} uart_config_t;

// Global variables
volatile sig_atomic_t program_running = 1;
uart_config_t uart_config;

// Function prototypes
int uart_init(uart_config_t *config);
int uart_read_data(uart_config_t *config, unsigned char *buffer, int max_length);
int validate_header(const unsigned char *header, int length);
int decode_range_profile(const unsigned char *data, int length, float *distances, int num_bins);
int detect_target(float *distances, int num_bins, float threshold);
int log_intrusion(float distance);
void activate_alert(int gpio_pin, int duration_seconds);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// UART initialization function
int uart_init(uart_config_t *config) {
    config->fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (config->fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    if (tcgetattr(config->fd, &config->tty) != 0) {
        perror("Error getting UART attributes");
        close(config->fd);
        return -1;
    }

    config->tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD; // 8N1, no parity
    config->tty.c_iflag = IGNPAR; // Ignore parity errors
    config->tty.c_oflag = 0;
    config->tty.c_lflag = 0; // Non-canonical mode

    config->tty.c_cc[VMIN] = 0;  // Read doesn't block
    config->tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(config->fd, TCSANOW, &config->tty) != 0) {
        perror("Error setting UART attributes");
        close(config->fd);
        return -1;
    }

    return 0;
}

// UART read data function
int uart_read_data(uart_config_t *config, unsigned char *buffer, int max_length) {
    ssize_t bytes_read = read(config->fd, buffer, max_length);
    if (bytes_read < 0) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read == 0) {
        fprintf(stderr, "UART read timeout or no data available.\n");
        return 0; // No data read
    }
    return (int)bytes_read;
}

// Header validation function
int validate_header(const unsigned char *header, int length) {
    const unsigned char magic_word[] = {0x48, 0x4C, 0x4C, 0x4C, 0x4C, 0x4C, 0x4C, 0x4C};
    if (length != MAGIC_WORD_LENGTH) {
        return 0; // Invalid length
    }
    for (int i = 0; i < length; i++) {
        if (header[i] != magic_word[i]) {
            return 0; // Invalid header
        }
    }
    return 1; // Valid header
}

// Range profile decoding function
int decode_range_profile(const unsigned char *data, int length, float *distances, int num_bins) {
    if (length != RANGE_PROFILE_LENGTH) {
        fprintf(stderr, "Error: Invalid range profile length (%d). Expected %d.\n", length, RANGE_PROFILE_LENGTH);
        return -1;
    }

    for (int i = 0; i < num_bins; i++) {
        int16_t distance = 0;
        for (int j = 0; j < 2; j++) {
            distance |= ((data[i * 2 + j] & 0xFF) << (8 * (1 - j)));
        }
        distances[i] = (float)distance / 100.0; // Convert to meters
    }
    return 0;
}

// Target detection function
int detect_target(float *distances, int num_bins, float threshold) {
    for (int i = 0; i < num_bins; i++) {
        if (distances[i] <= threshold) {
            return 1; // Target detected
        }
    }
    return 0; // No target detected
}

