    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    FILE *fp = fopen("intrusion_log.csv", "a");
    if (fp == NULL) {
        perror("Error opening intrusion_log.csv");
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, distance);
    fclose(fp);

    return 0;
}

// Alert activation function
void activate_alert(int gpio_pin, int duration_seconds) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_seconds * 1000000); // Delay for 2 seconds (microseconds)
    gpioWrite(gpio_pin, 0); // Turn LED off
}

