    unsigned char buffer[RANGE_PROFILE_LENGTH + MAGIC_WORD_LENGTH];
    float distances[RANGE_PROFILE_LENGTH / 2];
    int header_length, data_length;

    printf("Starting intrusion detection system...\n");

    while (program_running) {
        header_length = uart_read_data(&uart_config, buffer, RANGE_PROFILE_LENGTH + MAGIC_WORD_LENGTH);
        if (header_length == MAGIC_WORD_LENGTH) {
            if (validate_header(buffer, header_length)) {
                data_length = uart_read_data(&uart_config, buffer + header_length, RANGE_PROFILE_LENGTH);
                if (data_length == RANGE_PROFILE_LENGTH) {
                    if (decode_range_profile(buffer, header_length + data_length, distances, RANGE_PROFILE_LENGTH / 2) == 0) {
                        if (detect_target(distances, RANGE_PROFILE_LENGTH / 2, TARGET_THRESHOLD)) {
                            printf("Target detected within %.2f meters!\n", TARGET_THRESHOLD);
                            log_intrusion(TARGET_THRESHOLD);
                            activate_alert(GPIO_PIN, ALERT_DURATION);
                        }
                    }
                }
            }
        }
        gpioDelay(10000); // Check every 10ms
    }

