#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x68 // Replace with the actual I2C address
#define DISTANCE_REG 0x00 // Replace with the actual register address
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 10.0 // Distance threshold in cm
#define LOG_FILE "distance_log.txt"
#define MEASUREMENT_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float distance;
    time_t timestamp;
} SensorData;

// Function prototypes
int init_i2c();
int read_distance(float *distance);
int log_data(float distance);
int set_gpio_alert(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read distance from the sensor
int read_distance(float *distance) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    // Convert the raw data to a distance value (adjust based on sensor datasheet)
    int raw_distance = (buf[0] << 8) | buf[1];
    *distance = (float)raw_distance * 0.1; // Example conversion, adjust as needed

    return 0;
}

// Function to log data to a file
int log_data(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fclose(log_file);

    return 0;
}

// Function to set GPIO alert based on distance
int set_gpio_alert(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO high
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO low
    }
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_PIN, 0); // Ensure GPIO is low on exit
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

