        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance
    if (read_byte(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance_mm) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    // Basic data validation (adjust based on datasheet)
    if (range_status != 0) {
        fprintf(stderr, "Invalid range status: 0x%02X\n", range_status);
