            print_parking_guidance(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
