#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x70
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define MAX_DISTANCE 2000  // Maximum measurable distance in mm
#define MIN_DISTANCE 10    // Minimum measurable distance in mm
#define MAX_BLINK_FREQUENCY 1000 // Hz
#define MIN_BLINK_FREQUENCY 10 // Hz
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(uint16_t *distance);
float calculate_frequency(uint16_t distance);
void set_led_frequency(float frequency);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int ch201_address;
    int led_gpio;
    int pwm_frequency;
    int pwm_range;
    int max_distance;
    int min_distance;
    int max_blink_frequency;
    int min_blink_frequency;
    int max_retries;
    int retry_delay_ms;
} config_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from CH201 sensor
int read_distance(uint16_t *distance) {
    char cmd[1] = {0x00}; // Example command to trigger a measurement
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
            fprintf(stderr, "Error writing to I2C: %d\n", i2c_handle);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
            fprintf(stderr, "Error reading from I2C: %d\n", i2c_handle);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        *distance = (buf[0] << 8) | buf[1];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Calculate LED blink frequency based on distance
float calculate_frequency(uint16_t distance) {
    float frequency = MAX_BLINK_FREQUENCY - ((float)(distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * (MAX_BLINK_FREQUENCY - MIN_BLINK_FREQUENCY);
    if (frequency < MIN_BLINK_FREQUENCY) {
        frequency = MIN_BLINK_FREQUENCY;
    }
    return frequency;
}

// Set LED blink frequency using PWM
void set_led_frequency(float frequency) {
    int period_us = 5000000 / (int)frequency; // Period in microseconds
    int half_period_us = period_us / 2;

    gpioPWM(LED_GPIO, 0); // Turn LED off
    gpioDelay(half_period_us * 1000); // Delay in microseconds

    gpioPWM(LED_GPIO, PWM_RANGE); // Turn LED on
    gpioDelay(half_period_us * 1000); // Delay in microseconds
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    i2cClose(i2c_handle);
    gpioPWM(LED_GPIO, 0); // Turn LED off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for LED
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t distance;
    float frequency;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            frequency = calculate_frequency(distance);
            set_led_frequency(frequency);
        } else {
            fprintf(stderr, "Failed to read distance, using default frequency\n");
            set_led_frequency(MAX_BLINK_FREQUENCY); // Use default frequency
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

