int initialize_sensor(int i2c_bus, int i2c_address) {
    i2c_handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance data from the MLX75030 sensor
int read_distance(int i2c_handle, int *distance_cm) {
    char buf[2];
    int result;

    // Trigger measurement
    result = i2cWriteByteData(i2c_handle, 0x00, MEASURE_CMD); // Example register and command
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (adjust as needed)
    gpioDelay(10); // 10 ms delay

    // Read distance data
    result = i2cReadI2CBlockData(i2c_handle, 0x01, buf, 2); // Example register and number of bytes
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Combine bytes to form distance value
