    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the sensor
    if (initialize_sensor(config.i2c_bus, config.i2c_address) != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", config.log_file_name);
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_cm\n");
    }
    fflush(log_file);

    // Main loop
    int distance_cm;
    while (!terminate) {
        if (read_distance(i2c_handle, &distance_cm) == 0) {
            if (log_data(log_file, distance_cm) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(config.sample_interval_ms * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

