#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_MS 50
#define POLL_DELAY_MS 10

FILE *log_file = NULL;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log events to a file
void log_event(int sensor_id, const char *event_type) {
    char *timestamp = get_iso8601_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    free(timestamp);
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // LOW to HIGH transition (Cleared)
        log_event(1, "CLEARED");
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // LOW to HIGH transition (Cleared)
        log_event(2, "CLEARED");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for input
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callbacks with debouncing
    gpioSetAlertFuncEx(SENSOR_1_GPIO, sensor1_callback, NULL);
    gpioSetAlertFuncEx(SENSOR_2_GPIO, sensor2_callback, NULL);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        gpioDelay(POLL_DELAY_MS * 1000); // Delay for 10ms
    }

    return 0; // This line will never be reached due to the infinite loop, but it's good practice to include it.
}

