#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdbool.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_ADDR 0x50
#define MEASUREMENT_REG 0x00 // Replace with actual register address
#define MEASUREMENT_LENGTH 2   // Replace with actual length
#define TIMEOUT_MS 50
#define SAMPLE_DELAY_MS 500
#define CSV_FILE "distance_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
bool running = true;

// Function prototypes
int i2c_open(const char *bus);
int i2c_set_slave(int fd, int addr);
int i2c_write_reg(int fd, unsigned char reg, unsigned char value);
int i2c_read_reg(int fd, unsigned char reg, unsigned char *data, int len);
int i2c_close(int fd);
int i2c_ioctl(int fd, unsigned char command);
int read_distance(int fd);
int log_data(FILE *fp, time_t timestamp, int distance);
void signal_handler(int sig);
char* get_iso8601_timestamp();

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

// I2C set slave address function
int i2c_set_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write register function
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02x: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read register function
int i2c_read_reg(int fd, unsigned char reg, unsigned char *data, int len) {
    unsigned char buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading from I2C register 0x%02x: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        fprintf(stderr, "Error closing I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C ioctl function
int i2c_ioctl(int fd, unsigned char command) {
    if (ioctl(fd, I2C_SLAVE, I2C_SLAVE_ADDR) < 0) {
        fprintf(stderr, "Error re-establishing I2C connection: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SMBUS_READ, &command) < 0) {
        fprintf(stderr, "Error using I2C SMBUS read: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read distance function
int read_distance(int fd) {
    unsigned char data[MEASUREMENT_LENGTH];
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = TIMEOUT_MS * 1000000; // Convert milliseconds to nanoseconds

    if (i2c_ioctl(fd, 0x00) < 0) { // Send command to trigger measurement
        fprintf(stderr, "Error triggering measurement.\n");
        return -1;
    }

    if (nanosleep(&ts, NULL) < 0) {
        fprintf(stderr, "nanosleep interrupted\n");
        return -1;
    }

    if (i2c_read_reg(fd, MEASUREMENT_REG, data, MEASUREMENT_LENGTH) < 0) {
        fprintf(stderr, "Error reading distance data.\n");
        return -1;
    }

    // Combine the two bytes to form the distance in millimeters
    int distance = (data[0] << 8) | data[1];
    return distance;
}

// Log data function
int log_data(FILE *fp, time_t timestamp, int distance) {
    if (fprintf(fp, "%s,%d\n", get_iso8601_timestamp(), distance) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

// Get ISO 8601 timestamp function
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *info;
    char *buffer = malloc(sizeof(char) * 30);
    if (buffer == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }

    time(&rawtime);
    info = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(buffer, 30, "%Y-%m-%dT%H:%M:%SZ", info);
    return buffer;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    running = false;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set slave address
    if (i2c_set_slave(i2c_fd, I2C_SLAVE_ADDR) < 0) {
        i2c_close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2c_close(i2c_fd);
        return 1;
    }

    // Main loop
    while (running) {
        int distance = read_distance(i2c_fd);
        if (distance >= 0) {
            time_t now = time(NULL);
            if (log_data(csv_file, now, distance) < 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading distance, skipping sample.\n");
        }

        usleep(SAMPLE_DELAY_MS * 1000); // Delay for 500ms
    }

    // Cleanup
    i2c_close(i2c_fd);
    fclose(csv_file);

    return 0;
}

