#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L5CX_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L5CX_REG_PRE_RANGE_CONFIG_MIN_SNR 0x0010
#define VL53L5CX_REG_FINAL_RANGE_CONFIG_MIN_SNR 0x0014
#define VL53L5CX_REG_SYSTEM_SEQUENCE_CONFIG 0x0022
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0000
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to write a byte to a VL53L5CX register
int vl53l5cx_write_register(int handle, uint8_t reg, uint8_t value)
{
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02x: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L5CX register
int vl53l5cx_read_register(int handle, uint8_t reg, uint8_t *value)
{
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%02x: %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(handle, value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%02x: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L5CX register
int vl53l5cx_read_word(int handle, uint8_t reg, uint16_t *value)
{
    char buf[1];
    buf[0] = reg;
    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read (word) 0x%02x: %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(handle, (char*)value, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%02x (word): %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L5CX sensor
int vl53l5cx_init(int handle)
{
    uint8_t model_id, revision_id;
    uint16_t min_snr;

    // Check sensor ID
    if (vl53l5cx_read_register(handle, VL53L5CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (vl53l5cx_read_register(handle, VL53L5CX_REG_IDENTIFICATION_REVISION_ID, &revision_id) != 0) {
        fprintf(stderr, "Error reading revision ID\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02x\n", model_id);
        return -1;
    }

    // Configure sensor for 8x8 zone grid (Example - adjust based on datasheet)
    if (vl53l5cx_write_register(handle, VL53L5CX_REG_PRE_RANGE_CONFIG_MIN_SNR, 0x01) != 0) return -1;
    if (vl53l5cx_write_register(handle, VL53L5CX_REG_FINAL_RANGE_CONFIG_MIN_SNR, 0x01) != 0) return -1;
    if (vl53l5cx_write_register(handle, VL53L5CX_REG_SYSTEM_SEQUENCE_CONFIG, 0x01) != 0) return -1;

    return 0;
}

// Function to read zone distances from the VL53L5CX sensor
int vl53l5cx_read_zone_distances(int handle, int *distances)
{
    uint16_t range_status;
    uint16_t distance_mm;

    // Read range status
    if (vl53l5cx_read_register(handle, VL53L5CX_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance data for each zone (Example - adjust based on datasheet)
    for (int i = 0; i < 64; i++) {
        if (vl53l5cx_read_word(handle, VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + (i * 2), &distance_mm) != 0) {
            fprintf(stderr, "Error reading distance %d\n", i);
            return -1;
        }
        distances[i] = (int)distance_mm; // Store distance in mm
    }

    return 0;
}

