    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L5CX sensor
    if (vl53l5cx_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L5CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    int distances[64];
    while (!terminate) {
        // Read zone distances
        if (vl53l5cx_read_zone_distances(i2c_handle, distances) == 0) {
            // Print distances to console
            for (int i = 0; i < 64; i++) {
                printf("%d ", distances[i]);
            }
            printf("\n");
        } else {
            fprintf(stderr, "Failed to read zone distances\n");
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

