// Global variable for the I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read distance from the MLX75030 sensor
int read_distance(int i2c_handle) {
    int distance = -1;
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, (char*)&distance, 2); // Read 2 bytes

        if (result == 2) {
            // Success, break the loop
            break;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
        return -1; // Indicate failure
    }

    return distance;
}

// Function to get the current timestamp in milliseconds
long long get_timestamp_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)(ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(1, MLX75030_ADDR, 0); // Bus 1, address 0x4A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MLX75030 Distance Sensor Reader\n");

    // Main loop
    while (1) {
        // Read the distance from the sensor
        int distance = read_distance(i2c_handle);

        // Get the current timestamp
        long long timestamp = get_timestamp_ms();

        // Log the distance and timestamp to the console
        if (distance >= 0) {
            printf("Timestamp: %lld ms, Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Failed to read distance. Skipping logging.\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100 * 1000); // Delay in microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper cleanup.
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

