#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT 50            // Timeout in milliseconds
#define SERVO_MIN_PULSE_WIDTH 1000 // Minimum pulse width for SG90 servo (us)
#define SERVO_MAX_PULSE_WIDTH 2000 // Maximum pulse width for SG90 servo (us)
#define SERVO_RANGE 180         // Servo angle range (degrees)
#define MIN_DISTANCE 2.0       // Minimum distance (cm)
#define MAX_DISTANCE 400.0      // Maximum distance (cm)

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float get_distance();
int set_servo_angle(float distance);
void log_data(float distance);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Initialize function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    // Stop servo
    gpioServo(SERVO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Function to get distance from HC-SR04 sensor
float get_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure echo pulse width
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT * 1000) { // Convert ms to us
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0; // Timeout
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT * 1000) { // Convert ms to us
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0; // Timeout
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to set servo angle
int set_servo_angle(float distance) {
    // Map distance to servo angle
    float angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * SERVO_RANGE;

    // Calculate pulse width
    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / SERVO_RANGE);

    // Set servo angle
    gpioServo(SERVO_PIN, pulse_width);

    return 0;
}

// Function to log data to file
void log_data(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    if (initialize()) {
        return 1;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float distance = get_distance();

        if (distance > 0) {
            set_servo_angle(distance);
            log_data(distance);
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
        }

        gpioDelay(200); // Wait 200 ms
    }

    cleanup();

    return 0;
}

