#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT 1000000        // Timeout in microseconds (1 second)
#define BUZZER_DURATION 500     // Buzzer duration in milliseconds

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, unsigned int tick);
double calculate_distance(unsigned int pulse_width);
void activate_buzzer();
void deactivate_buzzer();
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that echo has started
    } else if (level == 0) {
        if (start_tick != 0) {
            end_tick = tick;
            echo_received = 1; // Indicate that echo has ended
        }
    } else {
        // Ignore other levels (e.g., falling edge)
    }
}

// Function to calculate distance in centimeters
double calculate_distance(unsigned int pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, then divide by 2 for one-way distance
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1);
    gpioDelay(BUZZER_DURATION * 1000); // Convert ms to us
    gpioWrite(BUZZER_PIN, 0);
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_PIN, 0);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    deactivate_buzzer();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (1) {
        // Trigger the sensor
        trigger_sensor();

        // Wait for 100ms
        gpioDelay(100000); // 100 ms

        // Calculate distance
        unsigned int pulse_width = end_tick - start_tick;
        double distance = calculate_distance(pulse_width);

        // Validate distance
        if (distance < 2.0 || distance > 400.0) {
            fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
        } else {
            // Activate buzzer if distance is less than 30 cm
            if (distance < 30.0) {
                activate_buzzer();
            } else {
                deactivate_buzzer();
            }

            // Print distance
            printf("Distance: %.2f cm\n", distance);
        }
    }

    return 0;
}

