#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define OPEN_ANGLE 90
#define CLOSE_ANGLE 0
#define DISTANCE_THRESHOLD 200 // 20cm in mm
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_RANGE 20000 // 20ms
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void open_gate();
void close_gate();
void log_event(const char *event);
void signal_handler(int signal);
int request_status();

// VL53L1X register addresses (Example - adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Callback function for remote control commands
void remote_control_callback(int gpio, int level, uint32_t tick, void *user_data);

// VL53L1X Initialization
int init_vl53l1x() {
    // Example initialization sequence (replace with actual VL53L1X init)
    // This is a placeholder and needs to be replaced with the correct VL53L1X initialization sequence
    // based on the VL53L1X datasheet and the pigpio library documentation.

    // Reset the sensor
    char reset_cmd[] = {0x00, 0x01}; // Example reset command
    if (i2cWriteDevice(i2c_handle, reset_cmd, 2) != 0) {
        log_event("Error: Failed to reset VL53L1X");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Start ranging
    char start_ranging_cmd[] = {0x01, 0x00}; // Example start ranging command
    if (i2cWriteDevice(i2c_handle, start_ranging_cmd, 2) != 0) {
        log_event("Error: Failed to start VL53L1X ranging");
        return -1;
    }

    log_event("VL53L1X initialized");
    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    char cmd[] = {0x00}; // Command to request a reading
    char data[2]; // Buffer to store the distance data

    // Request a reading
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        log_event("Error: Failed to request distance reading");
        return -1;
    }

    // Read the distance data (2 bytes)
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        log_event("Error: Failed to read distance data");
        return -1;
    }

    // Combine the two bytes into a 16-bit distance value
    int distance = (data[0] << 8) | data[1];

    return distance;
}

// Open the gate
void open_gate() {
    // Set the servo angle to OPEN_ANGLE
    gpioServo(SERVO_PIN, OPEN_ANGLE);
    log_event("Gate opened");
}

// Close the gate
void close_gate() {
    // Set the servo angle to CLOSE_ANGLE
    gpioServo(SERVO_PIN, CLOSE_ANGLE);
    log_event("Gate closed");
}

// Log an event to the log file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Received signal, shutting down...");
    terminate = 1;
}

// Request the status of the VL53L1X sensor
int request_status() {
    char cmd[] = {0x00}; // Command to request status
    char data[2]; // Buffer to store the status data

    // Request status
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        log_event("Error: Failed to request status");
        return -1;
    }

    // Read the status data (2 bytes)
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        log_event("Error: Failed to read status data");
        return -1;
    }

    // Combine the two bytes into a 16-bit status value
    int status = (data[0] << 8) | data[1];

    return status;
}

// Callback function for remote control commands
void remote_control_callback(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    if (level == 1) { // Rising edge (command received)
        int status = request_status();
        if (status == 0) {
            log_event("Received remote control command");
            if (status == 1) {
                close_gate();
            } else if (status == 2) {
                open_gate();
            } else {
                log_event("Invalid status received, ignoring command");
            }
        } else {
            log_event("Failed to request status, ignoring command");
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error: Could not open I2C bus");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM range for servo control
    gpioSetPWMrange(SERVO_PIN, SERVO_RANGE);

    // Set PWM frequency for servo control
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50Hz

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback for remote control (using GPIO 4 as example - adjust if needed)
    gpioSetAlertFuncEx(4, remote_control_callback, NULL);

    log_event("Gate control program started");

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance > 0) {
            char event[100];
            snprintf(event, sizeof(event), "Distance: %d mm", distance);
            log_event(event);

            if (distance < DISTANCE_THRESHOLD) {
                close_gate();
            } else {
                open_gate();
            }
        } else {
            log_event("Error reading distance, retrying...");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Clean up
    log_event("Cleaning up...");
    close_gate(); // Ensure gate is closed on exit
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

