#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define OPEN_ANGLE 90
#define CLOSE_ANGLE 0
#define DISTANCE_THRESHOLD 200 // 20cm in mm
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_RANGE 20000 // 20ms
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void open_gate();
void close_gate();
void log_event(const char *event);
void signal_handler(int signal);
int request_status();

