    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error: Could not open I2C bus");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM range for servo control
    gpioSetPWMrange(SERVO_PIN, SERVO_RANGE);

    // Set PWM frequency for servo control
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50Hz

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback for remote control (using GPIO 4 as example - adjust if needed)
    gpioSetAlertFuncEx(4, remote_control_callback, NULL);

    log_event("Gate control program started");

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance > 0) {
            char event[100];
            snprintf(event, sizeof(event), "Distance: %d mm", distance);
            log_event(event);

            if (distance < DISTANCE_THRESHOLD) {
                close_gate();
            } else {
                open_gate();
            }
        } else {
            log_event("Error reading distance, retrying...");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Clean up
    log_event("Cleaning up...");
    close_gate(); // Ensure gate is closed on exit
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

