#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define TIMEOUT_US 30000  // Timeout in microseconds
#define MIN_PULSE_WIDTH_US 100 // Minimum valid pulse width in microseconds
#define MAX_PULSE_WIDTH_US 30000 // Maximum valid pulse width in microseconds
#define TIMEOUT_MS 60 // Timeout in milliseconds

// Global variables
static volatile int pulse_start_tick = 0;
static volatile int pulse_end_tick = 0;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width_us);
void log_distance(double distance);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int trig_initialized;
    int echo_initialized;
} ProgramState;

ProgramState state = {0, 0};

// Function to initialize the TRIG pin
int initialize_trig() {
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting TRIG pin as output\n");
        return -1;
    }
    if (gpioWrite(TRIG_PIN, 0) != 0) {
        fprintf(stderr, "Error writing LOW to TRIG pin\n");
        return -1;
    }
    state.trig_initialized = 1;
    return 0;
}

// Function to initialize the ECHO pin
int initialize_echo() {
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting ECHO pin as input\n");
        return -1;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting ECHO pin pull-down resistor\n");
        return -1;
    }
    state.echo_initialized = 1;
    return 0;
}

// Function to generate a 10 µs trigger pulse
void trigger_pulse() {
    if (initialize_trig() != 0) {
        fprintf(stderr, "TRIG initialization failed, cannot trigger pulse\n");
        return;
    }
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 µs pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for the ECHO pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start_tick = tick;
    } else if (level == 0) {
        pulse_end_tick = tick;
    }
}

// Function to calculate the distance in centimeters
double calculate_distance(int pulse_width_us) {
    // Speed of sound in air (approx. 343 m/s) = 0.0343 cm/us
    // Divide by 2 because the sound wave travels to the object and back
    return (double)pulse_width_us * 0.0343 / 2.0;
}

// Function to log the distance to stdout and a file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);

    FILE *fp = fopen("distance_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening distance_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s Distance: %.2f cm\n", timestamp, distance);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize TRIG and ECHO pins
    if (initialize_trig() != 0 || initialize_echo() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up interrupt on ECHO pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for ECHO pin\n");
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();

        // Wait for a maximum of TIMEOUT_MS milliseconds
        int timeout_count = 0;
        while (pulse_start_tick == 0 && timeout_count < TIMEOUT_MS) {
            gpioDelay(1000); // Check every 1 ms
            timeout_count++;
        }

        if (pulse_start_tick == 0) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            continue; // Skip to the next iteration
        }

        int timeout_count2 = 0;
        while (pulse_end_tick == 0 && timeout_count2 < TIMEOUT_MS) {
            gpioDelay(1000); // Check every 1 ms
            timeout_count2++;
        }

        if (pulse_end_tick == 0) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            continue; // Skip to the next iteration
        }

        // Calculate pulse width
        int pulse_width_us = pulse_end_tick - pulse_start_tick;

        // Validate pulse width
        if (pulse_width_us < MIN_PULSE_WIDTH_US || pulse_width_us > MAX_PULSE_WIDTH_US) {
            fprintf(stderr, "Invalid pulse width: %d us\n", pulse_width_us);
            continue; // Skip to the next iteration
        }

        // Calculate distance
        double distance = calculate_distance(pulse_width_us);

        // Log distance
        log_distance(distance);
    }

    // Clean up
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

