#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_GATE_OPEN 18
#define GPIO_GATE_CLOSE 19
#define DISTANCE_THRESHOLD 200 // mm
#define LOG_FILE "gate_events.log"
#define POLL_INTERVAL_MS 500

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
int vl53l1x_open_gate(int i2c_handle);
int vl53l1x_close_gate(int i2c_handle);
void log_event(const char *event);
void signal_handler(int signal);

// Helper function to write a register
int vl53l1x_write_register(int i2c_handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = value;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Helper function to read a register
int vl53l1x_read_register(int i2c_handle, uint16_t reg, uint8_t *value) {
    int result = i2cWriteDevice(i2c_handle, (char *)&reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %d\n", reg, result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, (char *)value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    uint8_t model_id, revision_id;

    // Check sensor ID
    if (vl53l1x_read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (vl53l1x_read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_REVISION_ID, &revision_id) != 0) {
        fprintf(stderr, "Error reading revision ID\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Soft reset
    if (vl53l1x_write_register(i2c_handle, 0x0000, 0x01) != 0) return -1;
    gpioDelay(100); // Wait for reset to complete

    // Recommended settings (adjust as needed)
    if (vl53l1x_write_register(i2c_handle, 0x002d, 0x00) != 0) return -1; // set bit 0 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x002e, 0x01) != 0) return -1; // set bit 1 of bit 2 to 1
    if (vl53l1x_write_register(i2c_handle, 0x002f, 0x00) != 0) return -1; // set bit 2 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x0030, 0x00) != 0) return -1; // set bit 3 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x0031, 0x00) != 0) return -1; // set bit 4 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x0032, 0x00) != 0) return -1; // set bit 5 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x0033, 0x00) != 0) return -1; // set bit 6 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x0034, 0x00) != 0) return -1; // set bit 7 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x0035, 0x00) != 0) return -1; // set bit 8 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x0036, 0x00) != 0) return -1; // set bit 9 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x0037, 0x00) != 0) return -1; // set bit 10 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x0038, 0x00) != 0) return -1; // set bit 11 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x0039, 0x00) != 0) return -1; // set bit 12 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x003a, 0x00) != 0) return -1; // set bit 13 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x003b, 0x00) != 0) return -1; // set bit 14 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x003c, 0x00) != 0) return -1; // set bit 15 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x003d, 0x00) != 0) return -1; // set bit 16 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x003e, 0x00) != 0) return -1; // set bit 17 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x003f, 0x00) != 0) return -1; // set bit 18 of bit 2 to 0
    if (vl53l1x_write_register(i2c_handle, 0x0040, 0x01) != 0) return -1; // start ranging
    if (vl53l1x_write_register(i2c_handle, 0x0010, 0x00) != 0) return -1; // set bit 0 of bit 1 to 0
