    if (vl53l1x_read_register(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (uint8_t *)&distance) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    return distance;
}

// VL53L1X gate open function
int vl53l1x_open_gate(int i2c_handle) {
    if (gpioWrite(GPIO_GATE_OPEN, 1) != 0) {
        fprintf(stderr, "Error opening gate (GPIO %d HIGH)\n", GPIO_GATE_OPEN);
        return -1;
    }
    if (gpioWrite(GPIO_GATE_CLOSE, 0) != 0) {
        fprintf(stderr, "Error closing gate (GPIO %d LOW)\n", GPIO_GATE_CLOSE);
        gpioWrite(GPIO_GATE_OPEN, 0);
        return -1;
    }
    return 0;
}

// VL53L1X gate close function
int vl53l1x_close_gate(int i2c_handle) {
    if (gpioWrite(GPIO_GATE_OPEN, 0) != 0) {
        fprintf(stderr, "Error closing gate (GPIO %d LOW)\n", GPIO_GATE_OPEN);
        return -1;
    }
    if (gpioWrite(GPIO_GATE_CLOSE, 1) != 0) {
        fprintf(stderr, "Error opening gate (GPIO %d HIGH)\n", GPIO_GATE_CLOSE);
        gpioWrite(GPIO_GATE_OPEN, 0);
        return -1;
    }
    return 0;
}

// Log event function
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    int distance;
    int gate_open = 0; // 0 = closed, 1 = open

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_GATE_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_GATE_CLOSE, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        distance = vl53l1x_read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
        } else {
            // Check for object detection
            if (distance < DISTANCE_THRESHOLD && !gate_open) {
                if (vl53l1x_open_gate(i2c_handle) == 0) {
                    log_event("Gate opened");
                    gate_open = 1;
                }
            } else if (distance >= DISTANCE_THRESHOLD && gate_open) {
                if (vl53l1x_close_gate(i2c_handle) == 0) {
                    log_event("Gate closed");
                    gate_open = 0;
                }
            }
        }

        gpioDelay(POLL_INTERVAL_MS); // Wait before next poll
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_GATE_OPEN, 0);
    gpioWrite(GPIO_GATE_CLOSE, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

