int vl53l1x_read_distance(uint16_t *distance) {
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        // Start measurement
        if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) {
            fprintf(stderr, "Error: Failed to start measurement (attempt %d)\n", retries + 1);
            gpioDelay(BASE_DELAY_MS * (1 << retries) * 1000); // Exponential backoff
            retries++;
            continue;
        }

        // Wait for data ready
        status = 0;
        while (status & 0x01) {
            status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
            if (status < 0) {
                fprintf(stderr, "Error: Failed to read status register (attempt %d)\n", retries + 1);
                gpioDelay(BASE_DELAY_MS * (1 << retries) * 1000); // Exponential backoff
                retries++;
                break;
            }
            gpioDelay(1000); // Check every 1 ms
        }

        if (!(status & 0x01)) {
            fprintf(stderr, "Error: Data not ready (attempt %d)\n", retries + 1);
            gpioDelay(BASE_DELAY_MS * (1 << retries) * 1000); // Exponential backoff
            retries++;
            continue;
        }

        // Read distance
        uint8_t msb, lsb;
        if (i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &msb) < 0) {
            fprintf(stderr, "Error: Failed to read MSB (attempt %d)\n", retries + 1);
            gpioDelay(BASE_DELAY_MS * (1 << retries) * 1000); // Exponential backoff
            retries++;
            continue;
        }
        if (i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &lsb) < 0) {
            fprintf(stderr, "Error: Failed to read LSB (attempt %d)\n", retries + 1);
            gpioDelay(BASE_DELAY_MS * (1 << retries) * 1000); // Exponential backoff
            retries++;
            continue;
        }

        *distance = (uint16_t)((msb << 8) | lsb);
        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to read distance after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

void motor_forward() {
    gpioWrite(MOTOR_FORWARD, 1);
    gpioWrite(MOTOR_BACKWARD, 0);
}

void motor_backward() {
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 1);
}

void motor_stop() {
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 0);
}

void trigger_callback(int gpio, int level, uint32_t tick) {
    uint16_t distance;
    int motor_state = 0;

    if (vl53l1x_read_distance(&distance) == 0) {
        if (distance < FORWARD_THRESHOLD) {
            motor_forward();
            motor_state = 1;
        } else if (distance > BACKWARD_THRESHOLD) {
            motor_backward();
            motor_state = 2;
        } else {
            motor_stop();
            motor_state = 0;
        }

        printf("Distance: %d mm, Motor: %s\n", distance, motor_state ? (motor_state == 1) ? "Forward" : "Backward" : "Stopped");
    } else {
        fprintf(stderr, "Error: Failed to read distance\n");
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    motor_stop();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Set ISR for trigger pin
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("VL53L1X sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100000); // 100 ms delay
    }

    return 0;
}

