#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define constants
#define MPR121_ADDR 0x5A
#define MPR121_SOFT_RESET 0x80
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

#define LED_PIN_0 17
#define LED_PIN_1 18
#define LED_PIN_2 27
#define LED_PIN_3 22

#define NUM_ELECTRODES 12

// Global variables
int i2c_fd;
FILE *log_file;
bool running = true;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status();
void led_pattern(int electrode);
void log_event(int electrode);
void cleanup(int signal);

// Structure to hold LED pin assignments
typedef struct {
    int pin0;
    int pin1;
    int pin2;
    int pin3;
} LedPins;

LedPins led_pins = {LED_PIN_0, LED_PIN_1, LED_PIN_2, LED_PIN_3};

// Function to initialize the MPR121 sensor
int mpr121_init() {
    int status;

    // Soft reset
    status = wiringPiI2CWriteReg8(i2c_fd, MPR121_SOFT_RESET, 0x63);
    if (status < 0) {
        fprintf(stderr, "Error: Soft reset failed: %s\n", strerror(errno));
        return -1;
    }
    delay(100); // Wait for reset to complete

    // Configure ECR register to enable all electrodes
    status = wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, 0x3F); // Enable all 12 electrodes
    if (status < 0) {
        fprintf(stderr, "Error: ECR configuration failed: %s\n", strerror(errno));
        return -1;
    }

    // Configure other registers (example values, adjust as needed)
    status = wiringPiI2CWriteReg8(i2c_fd, MPR121_CONFIG1, 0x20); // Example config 1
    if (status < 0) {
        fprintf(stderr, "Error: Config 1 failed: %s\n", strerror(errno));
        return -1;
    }

    status = wiringPiI2CWriteReg8(i2c_fd, MPR121_CONFIG2, 0x10); // Example config 2
    if (status < 0) {
        fprintf(stderr, "Error: Config 2 failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status() {
    int touch_status_l, touch_status_h;
    int status;

    touch_status_l = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) {
        fprintf(stderr, "Error: Failed to read touch status L: %s\n", strerror(errno));
        return -1;
    }

    touch_status_h = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_H);
    if (touch_status_h < 0) {
        fprintf(stderr, "Error: Failed to read touch status H: %s\n", strerror(errno));
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to generate a 4-bit LED pattern based on the electrode number
void led_pattern(int electrode) {
    int pin;

    // Determine the GPIO pin based on the electrode number
    pin = led_pins.pin0 + (electrode % 4) * 4;

    // Set the GPIO pin HIGH
    digitalWrite(pin, HIGH);
}

// Function to log the event to the console with a timestamp
void log_event(int electrode) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Electrode %d touched\n", timestamp, electrode);
}

// Cleanup function to release resources
void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");
    running = false;

    // Release GPIO pins
    digitalWrite(LED_PIN_0, LOW);
    digitalWrite(LED_PIN_1, LOW);
    digitalWrite(LED_PIN_2, LOW);
    digitalWrite(LED_PIN_3, LOW);

    // Close I2C
    close(i2c_fd);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    int touch_status;
    int electrode;

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: I2C setup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MPR121 sensor
    if (mpr121_init() == -1) {
        fprintf(stderr, "Error: MPR121 initialization failed\n");
        return 1;
    }

    // Configure LED pins as output
    pinMode(LED_PIN_0, OUTPUT);
    pinMode(LED_PIN_1, OUTPUT);
    pinMode(LED_PIN_2, OUTPUT);
    pinMode(LED_PIN_3, OUTPUT);

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    printf("Proximity art installation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        touch_status = mpr121_read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status\n");
        } else {
            for (electrode = 0; electrode < NUM_ELECTRODES; electrode++) {
                if (touch_status & (1 << electrode)) {
                    led_pattern(electrode);
                    log_event(electrode);
                }
            }
        }
        delay(50);
    }

    return 0;
}

