int mpr121_init() {
    // Reset the MPR121
    if (mpr121_write_register(0x80, 0x63) < 0) return -1;
    delay(100); // Wait for reset

    // Configure FFI
    mpr121_config_t config = {
        .ffi_config = 0x0C, // Enable electrode sensing
        .sfi_config = 0x01, // Set sample rate
        .esi_config = 0x01, // Enable electrode sensing
        .debounce_config = 0x0A, // Debounce configuration
        .afe_config = 0x0F, // AFE configuration
        .baseline_config = 0x0A // Baseline configuration
