    if (mpr121_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed.\n");
        return 1;
    }

    // Configure LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Open the log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open proximity.log: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status.\n");
        } else {
            // Check for proximity event
            if (touch_status & PROXIMITY_THRESHOLD) {
                printf("Proximity event detected!\n");
                log_event("Proximity event detected");
                led_on();
                delay(1000);
                led_off();
            }
        }
        delay(50); // Small delay to avoid busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    led_off();
    fclose(log_file);
    return 0;
}

