#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 30000 // 30ms timeout
#define MAX_DISTANCE 400 // Maximum distance in cm
#define MIN_DISTANCE 2   // Minimum distance in cm

volatile sig_atomic_t program_running = 1;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioDelay(5);              // Wait 5 microseconds
    gpioWrite(TRIGGER_PIN, 1); // Send a 10µs pulse
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measure_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout occurred
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout occurred
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Function to calculate distance in centimeters
float calculate_distance(long pulse_width) {
    return (pulse_width * 34300) / 2000000.0; // Speed of sound in cm/us
}

// Function to validate the distance
int validate_distance(float distance) {
    return (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE);
}

// Function to log the distance to a file
int log_distance(float distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fp = fopen("distance_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening distance_log.txt");
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, distance);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            if (validate_distance(distance)) {
                if (log_distance(distance) != 0) {
                    fprintf(stderr, "Error logging distance.\n");
                }
            } else {
                fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Timeout or error during pulse measurement.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

