// Helper function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int i2c_handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write failed");
        return -1;
    }
    return 0;
}

// Helper function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int i2c_handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write (address) failed");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, value, 1) != 1) {
        syslog(LOG_ERR, "I2C read failed");
        return -1;
    }
    return 0;
}

// Helper function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(int i2c_handle, uint8_t reg, uint16_t *value) {
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        syslog(LOG_ERR, "I2C write (address) failed");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        syslog(LOG_ERR, "I2C read failed");
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

