#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define TIMEOUT_US 30000  // 30ms timeout
#define MOVING_AVERAGE_SIZE 5
#define SERVO_MIN_PULSE_WIDTH 1000 // us
#define SERVO_MAX_PULSE_WIDTH 2000 // us
#define SERVO_NEUTRAL_PULSE_WIDTH 1500 // us
#define SERVO_RANGE 180 // degrees

// Global variables
volatile int pulse_width = 0;
volatile int new_pulse = 0;
volatile int running = 1;

// Moving average filter
float distance_history[MOVING_AVERAGE_SIZE];
int history_index = 0;
float distance = -1.0; // Initialize to an invalid value

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick);
float calculateDistance(uint32_t start_tick, uint32_t end_tick);
void setServoAngle(int angle);
void logData(float distance, int angle);
void signalHandler(int signal);
void cleanup();

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echoCallback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_width = tick;
        new_pulse = 1;
    } else if (level == 0) {
        if (new_pulse) {
            uint32_t end_tick = tick;
            distance = calculateDistance(pulse_width, end_tick);
            if (distance < 0) {
                distance = -1.0;
            }
            new_pulse = 0;
        }
    }
}

// Function to calculate distance in centimeters
float calculateDistance(uint32_t start_tick, uint32_t end_tick) {
    uint32_t diff = end_tick - start_tick;
    if (diff > TIMEOUT_US) {
        return -1.0; // Timeout
    }
    // Speed of sound: 343 m/s = 0.0343 cm/us
    // Distance = (Time * Speed of Sound) / 2
    return (float)diff * 0.0343 / 2.0;
}

// Function to set the servo angle
void setServoAngle(int angle) {
    if (angle < 0 || angle > SERVO_RANGE) {
        fprintf(stderr, "Error: Invalid servo angle: %d\n", angle);
        return;
    }
    int pulse_width_us = SERVO_NEUTRAL_PULSE_WIDTH - (angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / SERVO_RANGE);
    gpioServo(SERVO_PIN, pulse_width_us);
}

// Function to log data to a CSV file
void logData(float distance, int angle) {
    FILE *fp = fopen("distance_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open distance_log.csv for writing\n");
        return;
    }

    // Check if the file is empty and write the header if needed
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, distance, angle);

    fclose(fp);
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    setServoAngle(0); // Stop the servo
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize servo to neutral position
    setServoAngle(SERVO_NEUTRAL_PULSE_WIDTH);

    // Initialize moving average filter
    for (int i = 0; i < MOVING_AVERAGE_SIZE; i++) {
        distance_history[i] = 0.0;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Set up interrupt callback for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL);

    // Main loop
    while (running) {
        triggerSensor();
        gpioDelay(100); // 100 ms delay

        // Calculate moving average
        distance_history[history_index] = distance;
        history_index = (history_index + 1) % MOVING_AVERAGE_SIZE;

        float sum = 0.0;
        for (int i = 0; i < MOVING_AVERAGE_SIZE; i++) {
            sum += distance_history[i];
        }
        distance = sum / MOVING_AVERAGE_SIZE;

        // Set servo angle based on distance (example: proportional control)
        int angle = (int)((distance / 200.0) * SERVO_RANGE); // Map distance to angle (0-180)
        if (angle < 0) angle = 0;
        if (angle > SERVO_RANGE) angle = SERVO_RANGE;
        setServoAngle(angle);

        // Log data
        logData(distance, angle);

        // Check for invalid distance readings
        if (distance < 0 || distance > 400) {
            fprintf(stderr, "Warning: Invalid distance reading: %.2f cm\n", distance);
            setServoAngle(90); // Set to 90 degrees
        }
    }

    return 0;
}

