    for (int i = 0; i < MOVING_AVERAGE_SIZE; i++) {
        distance_history[i] = 0.0;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Set up interrupt callback for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL);

    // Main loop
    while (running) {
        triggerSensor();
        gpioDelay(100); // 100 ms delay

        // Calculate moving average
        distance_history[history_index] = distance;
        history_index = (history_index + 1) % MOVING_AVERAGE_SIZE;

        float sum = 0.0;
        for (int i = 0; i < MOVING_AVERAGE_SIZE; i++) {
            sum += distance_history[i];
        }
        distance = sum / MOVING_AVERAGE_SIZE;

        // Set servo angle based on distance (example: proportional control)
        int angle = (int)((distance / 200.0) * SERVO_RANGE); // Map distance to angle (0-180)
        if (angle < 0) angle = 0;
        if (angle > SERVO_RANGE) angle = SERVO_RANGE;
        setServoAngle(angle);

        // Log data
        logData(distance, angle);

        // Check for invalid distance readings
        if (distance < 0 || distance > 400) {
            fprintf(stderr, "Warning: Invalid distance reading: %.2f cm\n", distance);
            setServoAngle(90); // Set to 90 degrees
        }
    }

    return 0;
}

