#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT 20000          // us (200ms)
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 200.0     // cm
#define MIN_FREQUENCY 200.0    // Hz
#define MAX_FREQUENCY 2000.0   // Hz
#define LOG_BASE 2.0            // Base for logarithmic mapping

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int pulse_width = 0;
volatile int previous_frequency = 0; // Store the previous frequency

// Function prototypes
void triggerSensor();
long measurePulseWidth();
float calculateDistance(long pulse_width);
float mapDistanceToFrequency(float distance);
void setPWMFrequency(float frequency);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();      // Terminate pigpio
    exit(0);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long measurePulseWidth() {
    int start_sec, start_micros, end_sec, end_micros;
    long start_time, end_time, pulse_width;

    // Wait for the echo pin to go high (with timeout)
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT) {
        gpioDelay(1); // Wait 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1; // Timeout error
    }

    start_sec = gpioTime(PI_TIME_RELATIVE, &start_sec, &start_micros);
    start_time = (long)start_sec * 1000000 + start_micros;

    // Wait for the echo pin to go low (with timeout)
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT) {
        gpioDelay(1); // Wait 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1; // Timeout error
    }

    end_sec = gpioTime(PI_TIME_RELATIVE, &end_sec, &end_micros);
    end_time = (long)end_sec * 1000000 + end_micros;

    pulse_width = end_time - start_time;
    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map the distance to a frequency on a logarithmic scale
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return previous_frequency; // Use previous frequency if out of range
    }

    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    // Logarithmic mapping
    float frequency = MIN_FREQUENCY * (LOG_BASE ** ((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (LOG_BASE - 1.0)));
    return frequency;
}

// Function to set the PWM frequency
void setPWMFrequency(float frequency) {
    if (frequency <= 0) {
        gpioPWM(PWM_PIN, 0); // Stop PWM if frequency is invalid
        return;
    }

    // Calculate the PWM range (duty cycle)
    int range = 1000; // 50% duty cycle
    if (frequency > 1000) {
        range = 500; // Reduce range for higher frequencies
    }

    gpioSetPWMfrequency(PWM_PIN, (int)frequency);
    gpioSetPWMrange(PWM_PIN, range);
    gpioPWM(PWM_PIN, range / 2); // 50% duty cycle
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency initially to 0 (no sound)
    gpioPWM(PWM_PIN, 0);
    setPWMFrequency(0.0);

    // Install signal handler
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    while (1) {
        triggerSensor();
        long pulse_width = measurePulseWidth();

        if (pulse_width > 0) {
            float distance = calculateDistance(pulse_width);
            if (distance > 0) {
                float frequency = mapDistanceToFrequency(distance);
                setPWMFrequency(frequency);
                previous_frequency = frequency; // Update previous frequency
            } else {
                fprintf(stderr, "Invalid distance measurement\n");
            }
        } else {
            fprintf(stderr, "Error measuring pulse width\n");
        }

        gpioDelay(50); // Delay between readings
    }

    return 0;
}

