#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000 // 50ms timeout

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10 us trigger pulse
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start_tick = 0, end_tick = 0;

        // Wait for echo to go high with timeout
        int timeout_count = 0;
        while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_US) {
            gpioDelay(1); // Check every 1 us
            timeout_count++;
        }
        if (timeout_count >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            gpioDelay(500); // Wait before next measurement
            continue;
        }
        start_tick = gpioTick();

        // Wait for echo to go low with timeout
        timeout_count = 0;
        while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT_US) {
            gpioDelay(1);
            timeout_count++;
        }
        if (timeout_count >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            gpioDelay(500); // Wait before next measurement
            continue;
        }
        end_tick = gpioTick();

        uint32_t diff = end_tick - start_tick;

        if (diff > 0) {
            float distance = (float)diff * 0.0343 / 2.0; // cm
            if (distance < 2.0 || distance > 400.0) {
                printf("Invalid reading\n");
            } else {
                printf("Distance: %.2f cm", distance);
                if (distance < 10.0) {
                    printf(" Too close!\n");
                } else {
                    printf("\n");
                }
            }
        } else {
            printf("Invalid reading\n");
        }

        gpioDelay(500); // 500 ms delay
    }

    gpioTerminate();
    return 0;
}

