// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_spi();
int read_distance(uint16_t *distance);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

