#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1175_ADDR 0x60
#define ALS_REG 0x22 // Example register address for ALS
#define LOG_FILE "proximity_log.csv"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_als(uint16_t *als_value);
int write_register(uint8_t reg, uint8_t value);
int read_register(uint8_t reg, uint8_t *value);
int log_data(uint16_t als_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Read ALS value from the sensor
int read_als(uint16_t *als_value) {
    uint8_t data[2];
    int result = i2cReadI2CBlockData(i2c_fd, ALS_REG, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return -1;
    }

    *als_value = (data[1] << 8) | data[0]; // Assuming big-endian
    return 0;
}

// Write a byte to a register
int write_register(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_fd, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read a byte from a register
int read_register(uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Log data to file
int log_data(uint16_t als_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s,%u\n", timestamp, als_value);
    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    uint16_t als_value;
    while (!terminate) {
        if (read_als(&als_value) == 0) {
            if (log_data(als_value) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading ALS value\n");
        }
        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

