#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 register addresses
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x10
#define REG_PS1_DATA0 0x18

// Si1120 initialization commands
#define SI1120_RESET 0x01
#define SI1120_ALS_EN 0x02
#define SI1120_PS_EN 0x04
#define SI1120_MEAS_RATE 0x08

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1120_init();
int si1120_read_data(uint16_t *als, uint16_t *prox);
int si1120_write_register(uint8_t reg, uint8_t value);
int si1120_read_register(uint8_t reg, uint8_t *value);
int si1120_read_part_id(uint8_t *part_id);
int si1120_check_part_id(uint8_t expected_part_id);
int si1120_log_data(uint16_t als, uint16_t prox);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1120 sensor
int si1120_init() {
    uint8_t part_id;

    // Reset the sensor
    if (si1120_write_register(REG_PART_ID, SI1120_RESET) != 0) {
        fprintf(stderr, "Error: Failed to reset Si1120.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Check Part ID
    if (si1120_read_part_id(&part_id) != 0) {
        fprintf(stderr, "Error: Failed to read Si1120 Part ID.\n");
        return -1;
    }

    if (si1120_check_part_id(part_id) != 0) {
        fprintf(stderr, "Error: Si1120 Part ID does not match expected value.\n");
        return -1;
    }

    // Enable ALS and Proximity
    if (si1120_write_register(REG_ALS_EN, SI1120_ALS_EN) != 0) {
        fprintf(stderr, "Error: Failed to enable ALS.\n");
        return -1;
    }
    if (si1120_write_register(REG_PS_EN, SI1120_PS_EN) != 0) {
        fprintf(stderr, "Error: Failed to enable Proximity.\n");
        return -1;
    }

    // Set measurement rate
    if (si1120_write_register(REG_MEAS_RATE, SI1120_MEAS_RATE) != 0) {
        fprintf(stderr, "Error: Failed to set measurement rate.\n");
        return -1;
    }

    return 0;
}

// Function to read ALS and proximity data from the Si1120
int si1120_read_data(uint16_t *als, uint16_t *prox) {
    uint8_t als_low, als_high, prox_low, prox_high;

    // Read ALS data
    if (si1120_read_register(REG_ALS_VIS_DATA0, &als_low) != 0) {
        fprintf(stderr, "Error: Failed to read ALS data low byte.\n");
        return -1;
    }
    if (si1120_read_register(REG_ALS_VIS_DATA0 + 1, &als_high) != 0) {
        fprintf(stderr, "Error: Failed to read ALS data high byte.\n");
        return -1;
    }

    // Read Proximity data
    if (si1120_read_register(REG_PS1_DATA0, &prox_low) != 0) {
        fprintf(stderr, "Error: Failed to read Proximity data low byte.\n");
        return -1;
    }
    if (si1120_read_register(REG_PS1_DATA0 + 1, &prox_high) != 0) {
        fprintf(stderr, "Error: Failed to read Proximity data high byte.\n");
        return -1;
    }

    // Combine bytes into 16-bit values (little-endian)
    *als = (als_high << 8) | als_low;
    *prox = (prox_high << 8) | prox_low;

    return 0;
}

// Function to write a byte to a specific register
int si1120_write_register(uint8_t reg, uint8_t value) {
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to write to register 0x%02X (attempt %d): %d\n", reg, 4 - retries, result);
            gpioDelay(10); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Error: Failed to write to register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to read a byte from a specific register
int si1120_read_register(uint8_t reg, uint8_t *value) {
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to read from register 0x%02X (attempt %d): %d\n", reg, 4 - retries, result);
            gpioDelay(10); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Error: Failed to read from register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to read the Si1120 Part ID
int si1120_read_part_id(uint8_t *part_id) {
    return si1120_read_register(REG_PART_ID, part_id);
}

// Function to check the Si1120 Part ID
int si1120_check_part_id(uint8_t expected_part_id) {
    uint8_t part_id;
    if (si1120_read_part_id(&part_id) != 0) {
        return -1;
    }
    return (part_id == expected_part_id);
}

// Function to log the sensor data to a file
int si1120_log_data(uint16_t als, uint16_t prox) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, Prox: %u\n", timestamp, als, prox);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

