#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1182_PART_ID_REG 0x00
#define SI1182_MEAS_RATE_REG 0x08
#define SI1182_ALS_DATA_REG 0x22
#define SI1182_PS_DATA_REG 0x24
#define SI1182_ALS_DATA_LEN 2
#define SI1182_PS_DATA_LEN 2
#define SI1182_MEAS_RATE_DEFAULT 100 // Hz
#define SI1182_MEAS_RATE_REG_VALUE 100 // 100 Hz
#define SI1182_PART_ID 0x53
#define SI1182_ALS_DATA_REG_HIGH 0x22
#define SI1182_PS_DATA_REG_HIGH 0x24

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_block(int fd, uint8_t reg, uint8_t *data, int len);
int si1182_init(int fd);
int si1182_read_data(int fd, float *lux, int *proximity);
char* get_timestamp();
int log_data(const char *timestamp, float lux, int proximity);
void signal_handler(int signal);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t data[1];
    data[0] = reg;
    if (ioctl(fd, I2C_SLAVE, reg) < 0) {
        perror("I2C_SLAVE");
        return -1;
    }
    if (write(fd, data, 1) != 1) {
        perror("I2C write (reg select)");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("I2C read");
        return -1;
    }
    return data[0];
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t data[2];
    data[0] = reg;
    data[1] = value;
    if (ioctl(fd, I2C_SLAVE, reg) < 0) {
        perror("I2C_SLAVE");
        return -1;
    }
    if (write(fd, data, 2) != 2) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, reg) < 0) {
        perror("I2C_SLAVE");
        return -1;
    }
    if (write(fd, data, 1) != 1) {
        perror("I2C write (reg select)");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

// I2C write block function
int i2c_write_block(int fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (ioctl(fd, I2C_SLAVE, reg) < 0) {
        perror("I2C_SLAVE");
        return -1;
    }
    if (write(fd, buf, len + 1) != len + 1) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

// Si1182 initialization function
int si1182_init(int fd) {
    // Check Part ID
    int part_id = i2c_read_reg(fd, SI1182_PART_ID_REG);
    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Error: Incorrect Part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1182_PART_ID);
        return -1;
    }

    // Configure measurement rate
    if (i2c_write_reg(fd, SI1182_MEAS_RATE_REG, SI1182_MEAS_RATE_REG_VALUE) < 0) {
        fprintf(stderr, "Error: Failed to configure measurement rate.\n");
        return -1;
    }

    return 0;
}

// Si1182 data reading function
int si1182_read_data(int fd, float *lux, int *proximity) {
    uint8_t als_data[SI1182_ALS_DATA_LEN];
    uint8_t ps_data[SI1182_PS_DATA_LEN];

    if (i2c_read_block(fd, SI1182_ALS_DATA_REG_HIGH, als_data, SI1182_ALS_DATA_LEN) < 0) {
        fprintf(stderr, "Error: Failed to read ALS data.\n");
        return -1;
    }

    if (i2c_read_block(fd, SI1182_PS_DATA_REG_HIGH, ps_data, SI1182_PS_DATA_LEN) < 0) {
        fprintf(stderr, "Error: Failed to read PS data.\n");
        return -1;
    }

    // Convert ALS data to lux (example conversion, adjust as needed)
    uint16_t als_value = (als_data[1] << 8) | als_data[0];
    *lux = (float)als_value * 0.1; // Example scaling

    // Proximity data is a raw 16-bit value
    *proximity = (ps_data[1] << 8) | ps_data[0];

    return 0;
}

// Get timestamp function
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS.mmm

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    sprintf(timestamp + strlen(timestamp), ".%03d", (int)(rawtime % 60 * 1000 / 60)); // Add milliseconds

    return timestamp;
}

// Log data function
int log_data(const char *timestamp, float lux, int proximity) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, lux, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Initialize Si1182 sensor
    if (si1182_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: Si1182 initialization failed.\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    printf("Si1182 sensor initialized successfully.\n");

    // Main loop
    float lux;
    int proximity;
    char *timestamp;

    while (program_running) {
        // Read sensor data
        if (si1182_read_data(i2c_fd, &lux, &proximity) == 0) {
            // Get timestamp
            timestamp = get_timestamp();

            // Log data
            if (log_data(timestamp, lux, proximity) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }

            // Print data to stdout
            printf("%s,%.2f,%d\n", timestamp, lux, proximity);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        // Wait 100ms
        usleep(100000); // 100ms = 100000 microseconds
    }

    // Close resources before exiting
    printf("Closing resources...\n");
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

