#define TIMEOUT_US 100000       // Timeout for echo pulse in microseconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
float measure_distance();
int set_servo_angle(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Cleaning up and exiting.\n");
        program_running = 0;
        gpioTerminate();
        exit(0);
    }
}

// Function to measure distance using HC-SR04 sensor
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        return -1.0;
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        return -1.0;
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert microseconds to seconds, and by 2 for one-way distance

    return distance;
}

// Function to set servo angle based on distance
int set_servo_angle(float distance) {
    if (distance < 20.0) {
        distance = 20.0;
    } else if (distance > 200.0) {
        distance = 200.0;
    }

    // Map distance to pulse width (500-2500 us)
    float pulse_width = 500.0 + (200.0 - distance) * (1500.0 - 500.0) / (200.0 - 20.0);

    // Calculate pulse width in microseconds
    int pulse_width_us = (int)pulse_width;

    // Set servo angle
    gpioServo(SERVO_PIN, pulse_width_us);

    return 0;
}

