#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// GPIO pin for servo control
#define SERVO_PIN 18

// Distance thresholds (mm)
#define DISTANCE_THRESHOLD_FAR 250
#define DISTANCE_THRESHOLD_CLOSE 200

// PWM pulse widths (us)
#define PWM_WIDTH_FAR 1000
#define PWM_WIDTH_CLOSE 2000

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void set_servo_pulse_width(int gpio_pin, int pulse_width_us);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    // Check the model ID
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    // Set timing budget (example: 100ms)
    if (i2cWriteByteData(i2c_handle, 0x002D, 0x64) < 0) { // VL53L1X_REG_SYSRANGE_TIMING_BUDGET
        fprintf(stderr, "Error setting timing budget\n");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int i2c_handle) {
    int distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %d\n", distance);
        return -1;
    }
    return distance;
}

// Servo control function
void set_servo_pulse_width(int gpio_pin, int pulse_width_us) {
    gpioPWM(gpio_pin, pulse_width_us);
}

// Logging function
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Control servo based on distance
        if (distance > DISTANCE_THRESHOLD_FAR) {
            set_servo_pulse_width(SERVO_PIN, PWM_WIDTH_FAR);
            log_event("Gate opened");
        } else if (distance < DISTANCE_THRESHOLD_CLOSE) {
            set_servo_pulse_width(SERVO_PIN, PWM_WIDTH_CLOSE);
            log_event("Gate closed");
        } else {
            // Hysteresis: keep the current state if the distance is within the threshold
        }

        gpioDelay(50); // Delay to avoid excessive CPU usage
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    return 0;
}

