#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Si7005 I2C address
#define SI7005_ADDR 0x40

// Si7005 register addresses
#define SI7005_TEMP_REG 0x00
#define SI7005_HUMID_REG 0x02
#define SI7005_CONFIG_REG 0x00

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the Si7005 sensor
int initialize_si7005() {
    // Configure the sensor (e.g., enable temperature and humidity measurement)
    if (i2cWriteByteData(i2c_handle, SI7005_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the Si7005
int read_si7005(float *temperature, float *humidity) {
    unsigned char buf[2];
    int result;

    // Trigger a temperature measurement
    if (i2cWriteByteData(i2c_handle, SI7005_TEMP_REG, 0x00) < 0) {
        fprintf(stderr, "Error triggering temperature measurement\n");
        return -1;
    }
    gpioDelay(10); // Wait for conversion (10ms)

    // Read the temperature data
    result = i2cReadI2CBlockData(i2c_handle, SI7005_TEMP_REG, (char *)buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }
    int temp_raw = (buf[0] << 8) | buf[1];
    *temperature = (float)temp_raw / 100.0;

    // Trigger a humidity measurement
    if (i2cWriteByteData(i2c_handle, SI7005_HUMID_REG, 0x00) < 0) {
        fprintf(stderr, "Error triggering humidity measurement\n");
        return -1;
    }
    gpioDelay(10); // Wait for conversion (10ms)

    // Read the humidity data
    result = i2cReadI2CBlockData(i2c_handle, SI7005_HUMID_REG, (char *)buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }
    int humid_raw = (buf[0] << 8) | buf[1];
    *humidity = (float)humid_raw / 100.0;

    return 0;
}

int main() {
    float temperature, humidity;
    int init_result;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the Si7005 sensor
    init_result = initialize_si7005();
    if (init_result != 0) {
        fprintf(stderr, "Si7005 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        if (read_si7005(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data, re-initializing...\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            gpioInitialise();
            i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus\n");
                gpioTerminate();
                return 1;
            }
            if (initialize_si7005() != 0) {
                fprintf(stderr, "Si7005 re-initialization failed\n");
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }
        }
        gpioDelay(2000); // Wait 2 seconds
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

