#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig)
{
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050()
{
    // Wake up the MPU-6050 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Configure accelerometer range (+/- 2g)
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range\n");
        return -1;
    }

    // Configure gyroscope range (+/- 250 dps)
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read raw data from the MPU-6050
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z, int16_t *temperature)
{
    char buf[14];
    int result = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14);

    if (result != 14) {
        fprintf(stderr, "Error: Could not read data from MPU-6050 (read %d bytes)\n", result);
        return -1;
    }

    // Parse accelerometer data
    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Parse gyroscope data
    *gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z = (int16_t)((buf[12] << 8) | buf[13]);

    // Parse temperature data
    *temperature = (int16_t)((buf[2] << 8) | buf[3]);

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = i2cReadByteData(i2c_handle, 0x75);
    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: MPU-6050 not found (WHO_AM_I = 0x%x)\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, temperature;
    while (!terminate) {
        if (read_mpu6050_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z, &temperature) == 0) {
            printf("Accel: X=%6d, Y=%6d, Z=%6d  ", accel_x, accel_y, accel_z);
            printf("Gyro: X=%6d, Y=%6d, Z=%6d  ", gyro_x, gyro_y, gyro_z);
            printf("Temp=%6d\n", temperature);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }
        gpioDelay(100000); // 100ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

