#include <time.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// Measurement command (high repeatability)
#define MEASURE_CMD 0xFD

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read temperature and humidity from SHT40
int read_sht40(float *temperature, float *humidity) {
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0); // Corrected: Use i2cWriteByteData
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 10ms)
    gpioDelay(10); // Corrected: Use gpioDelay

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 6); // Corrected: Use i2cReadI2CBlockData
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate CRC for temperature
    uint8_t temp_data[2] = {data[0], data[1]};
    uint8_t temp_crc = data[2];
    if (crc8(temp_data, 2) != temp_crc) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    // Validate CRC for humidity
    uint8_t hum_data[2] = {data[3], data[4]};
    uint8_t hum_crc = data[5];
    if (crc8(hum_data, 2) != hum_crc) {
        fprintf(stderr, "Humidity CRC check failed!\n");
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

