#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
char* get_timestamp();
int log_data(sensor_data_t data, char* timestamp);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    uint16_t raw_ambient, raw_object;

    // Read ambient temperature
    raw_ambient = i2cReadWordData(i2c_handle, AMBIENT_TEMP_REG);
    if (raw_ambient < 0) {
        fprintf(stderr, "Error reading ambient temperature: %d\n", raw_ambient);
        data.ambient_temp = -1000.0; // Indicate error
    } else {
        data.ambient_temp = (float)raw_ambient * 0.02 - 273.15;
    }

    // Read object temperature
    raw_object = i2cReadWordData(i2c_handle, OBJECT_TEMP_REG);
    if (raw_object < 0) {
        fprintf(stderr, "Error reading object temperature: %d\n", raw_object);
        data.object_temp = -1000.0; // Indicate error
    } else {
        data.object_temp = (float)raw_object * 0.02 - 273.15;
    }

    return data;
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t now = time(NULL);
    struct tm *tstruct;
    char *buf = malloc(20 * sizeof(char)); // Allocate memory for the timestamp string
    if (buf == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }
    tstruct = localtime(&now);
    strftime(buf, 20, "%Y-%m-%d %H:%M:%S", tstruct);
    return buf;
}

// Function to log the data to a file
int log_data(sensor_data_t data, char* timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.ambient_temp, data.object_temp);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t sensor_data = read_sensor_data();

        // Get timestamp
        char* timestamp = get_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping log entry.\n");
            continue; // Skip logging if timestamp fails
        }

        // Log data
        if (log_data(sensor_data, timestamp) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait for the next sample
        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_SEC, 0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

