void convert_data(const uint8_t *data, float *pressure, float *temperature) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    *pressure = (float)raw_pressure / PRESSURE_SCALE_FACTOR;
    *temperature = (float)raw_temperature / TEMPERATURE_SCALE_FACTOR;
}

