    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SDP810 sensor
    if (init_sdp810() != 0) {
        fprintf(stderr, "SDP810 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

