    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is new and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t data[9];
    float pressure, temperature;

    // Main loop
    while (!terminate) {
        // Read data from sensor
        if (read_sdp810(data) == 0) {
            // Validate CRC-8 checksums
            if (validate_crc(data, 2) != 0 || validate_crc(data + 3, 2) != 0) {
                fprintf(stderr, "CRC validation failed, skipping this reading\n");
                continue; // Skip to the next iteration
            }

            // Convert data to physical units
            convert_data(data, &pressure, &temperature);

            // Log data to file
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Clean up
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

