#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define TRIGGER_COMMAND 0x362F
#define DATA_LENGTH 9
#define SAMPLE_INTERVAL_MS 100
#define FILENAME "airflow_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to trigger continuous measurement
int trigger_measurement() {
    char buf[2] = {(TRIGGER_COMMAND >> 8) & 0xFF, TRIGGER_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate CRC
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }
    return 0;
}

// Function to convert raw data to pressure and temperature
SensorData convert_data(const uint8_t *data) {
    SensorData sensor_data;
    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t raw_scale_factor = (data[6] << 8) | data[7];

    // Convert to physical units (refer to SDP800 datasheet)
    sensor_data.pressure = (float)raw_pressure / 240.0; // Pa
    sensor_data.temperature = (float)raw_temperature / 200.0; // °C

    return sensor_data;
}

// Function to log data to file
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");

    uint8_t data[DATA_LENGTH];
    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        gpioDelay(45000); // Wait 45ms

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        // Validate CRC
        if (validate_crc(data, DATA_LENGTH) != 0) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        // Convert data
        SensorData sensor_data = convert_data(data);

        // Log data
        if (log_data(sensor_data.pressure, sensor_data.temperature) != 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

