#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY 0xFD
#define LOG_FILE "sht40_log.txt"
#define ERROR_LOG_FILE "sht40_error.log"
#define SLEEP_SECONDS 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to read data from the SHT40 sensor
int read_sht40(int i2c_fd, uint8_t *data) {
    if (i2cWriteByte(i2c_fd, MEASURE_HIGH_REPEATABILITY) != 0) {
        fprintf(error_log_file, "%s", "Error writing measurement command\n");
        fflush(error_log_file);
        return -1;
    }

    gpioDelay(10); // Wait for measurement (datasheet specifies 12.1ms for high repeatability)

    if (i2cReadDevice(i2c_fd, (char *)data, 6) != 6) {
        fprintf(error_log_file, "%s", "Error reading data from sensor\n");
        fflush(error_log_file);
        return -1;
    }

    return 0;
}

// Function to validate CRC checksum
int validate_crc(const uint8_t *data) {
    uint8_t crc = crc8(data, 2);
    if (crc != data[2]) {
        fprintf(error_log_file, "%s", "CRC check failed\n");
        fflush(error_log_file);
        return -1;
    }
    return 0;
}

// Function to convert raw data to temperature and humidity
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int32_t temperature_raw = (data[0] << 8) | data[1];
    int32_t humidity_raw = (data[3] << 8) | data[4];

    sensor_data.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return sensor_data;
}

// Function to log data to a file
int log_data(FILE *log_file, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity) < 0) {
        fprintf(error_log_file, "%s", "Error writing to log file\n");
        fflush(error_log_file);
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Error opening error log file\n");
        fclose(log_file);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint8_t data[6];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read data from sensor
        if (read_sht40(i2c_fd, data) == 0) {
            // Validate CRC checksum
            if (validate_crc(data) == 0) {
                // Convert data to temperature and humidity
                sensor_data = convert_data(data);

                // Log data to file
                if (log_data(log_file, sensor_data.temperature, sensor_data.humidity) != 0) {
                    fprintf(error_log_file, "%s", "Error logging data\n");
                    fflush(error_log_file);
                }
            }
        } else {
            fprintf(error_log_file, "%s", "Error reading sensor data\n");
            fflush(error_log_file);
        }

        // Sleep for 5 seconds
        sleep(SLEEP_SECONDS);
    }

    // Clean up
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();

    return 0;
}

