int write_sensor_command(int i2c_handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteI2CBlockData(i2c_handle, 0, buf, 2);
    if (result != 2) {
