        // Write measurement command
        if (write_sensor_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error writing measurement command\n");
            break;
        }

        // Wait for at least 1ms
        gpioDelay(SAMPLE_INTERVAL_MS);

        // Read sensor data
        if (read_sensor_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Error reading sensor data\n");
            break;
        }

        // Validate CRC
        if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Skip to the next iteration
        }

        // Convert data
        sensor_data = convert_data(data);

        // Get current timestamp
        current_time = time(NULL);

        // Log data
        if (log_data(data_file, current_time, sensor_data.pressure, sensor_data.temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();

    return 0;
}

