#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer
sensor_data_t sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
void control_fan(float temperature);
void add_to_buffer(float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the sensor
int read_sensor_data(float *temperature, float *humidity) {
    unsigned char cmd_temp = 0xE3; // Command to measure temperature
    unsigned char cmd_humidity = 0xE5; // Command to measure humidity
    unsigned char buf[2];
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, (char *)&cmd_temp, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing temperature command: %d, retries left: %d\n", result, retries);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        gpioDelay(10000); // Wait 10ms for measurement

        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading temperature data: %d, retries left: %d\n", result, retries);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        unsigned int raw_temp = (buf[0] << 8) | buf[1];
        *temperature = (175.72 * raw_temp / 65536.0) - 46.85;

        result = i2cWriteDevice(i2c_handle, (char *)&cmd_humidity, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing humidity command: %d, retries left: %d\n", result, retries);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        gpioDelay(10000); // Wait 10ms for measurement

        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading humidity data: %d, retries left: %d\n", result, retries);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        unsigned int raw_humidity = (buf[0] << 8) | buf[1];
        *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Function to control the cooling fan
void control_fan(float temperature) {
    static int fan_on = 0; // Track fan state

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Temperature: %.2f\u00b0C)\n", temperature);
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Temperature: %.2f\u00b0C)\n", temperature);
    }
}

// Function to add data to the circular buffer
void add_to_buffer(float temperature, float humidity) {
    sensor_buffer[buffer_index].timestamp = time(NULL);
    sensor_buffer[buffer_index].temperature = temperature;
    sensor_buffer[buffer_index].humidity = humidity;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        time_t timestamp = sensor_buffer[i].timestamp;
        struct tm *timeinfo = localtime(&timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Temperature: %.2f\u00b0C, Humidity: %.2f%%\n", timestamp_str, sensor_buffer[i].temperature, sensor_buffer[i].humidity);
    }
    printf("--- End of Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int read_result;

    printf("Starting temperature monitoring...\n");

    while (!terminate) {
        read_result = read_sensor_data(&temperature, &humidity);

        if (read_result == 0) {
            printf("Temperature: %.2f\u00b0C, Humidity: %.2f%%\n", temperature, humidity);
            control_fan(temperature);
            add_to_buffer(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    cleanup();
    return 0;
}

