#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD40 I²C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// Data Ready flag
#define DATA_READY_FLAG 0x0208

// CRC8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int start_periodic_measurement();
int read_measurement(sensor_data_t *data);
int verify_checksum(uint8_t *data, int len);
int stop_periodic_measurement();
void log_data(sensor_data_t data);
void signal_handler(int signal);
uint8_t crc8(const uint8_t *data, int len);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// CRC8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize the SCD40 sensor
int initialize_sensor() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // I2C bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    uint8_t cmd[2];
    cmd[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send start periodic measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read measurement data
int read_measurement(sensor_data_t *data) {
    uint8_t cmd[2];
    uint8_t buffer[9];
    int result;

    cmd[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_READ_MEASUREMENT & 0xFF;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Wait for data to be ready

    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    // Verify checksums
    if (verify_checksum(buffer, 2) != 0 || verify_checksum(buffer + 2, 2) != 0 || verify_checksum(buffer + 4, 2) != 0) {
        fprintf(stderr, "Checksum verification failed\n");
        return -1;
    }

    data->co2 = (uint16_t)buffer[0] << 8 | buffer[1];
    data->temperature = (uint16_t)buffer[3] << 8 | buffer[4];
    data->humidity = (uint16_t)buffer[6] << 8 | buffer[7];

    return 0;
}

// Verify checksum
int verify_checksum(uint8_t *data, int len) {
    uint8_t crc = crc8(data, len);
    uint8_t received_crc = data[len];

    if (crc != received_crc) {
        fprintf(stderr, "Checksum mismatch: calculated 0x%02X, received 0x%02X\n", crc, received_crc);
        return -1;
    }
    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement() {
    uint8_t cmd[2];
    cmd[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send stop periodic measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written immediately
}

int main() {
    sensor_data_t sensor_data;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize sensor
    if (initialize_sensor() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Check data ready flag
        uint8_t data_ready_buffer[2];
        int result = i2cReadDevice(i2c_handle, (char *)data_ready_buffer, 2);
        if (result != 2) {
            fprintf(stderr, "Failed to read data ready flag: %d\n", result);
            gpioDelay(500); // Wait before retrying
            continue;
        }

        if ((data_ready_buffer[1] & 0x80) && (data_ready_buffer[1] & 0x40)) {
            // Data is ready, read measurement
            if (read_measurement(&sensor_data) == 0) {
                // Log data
                log_data(sensor_data);
            } else {
                fprintf(stderr, "Failed to read measurement\n");
            }
        }

        gpioDelay(500); // Poll every 500ms
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C handle and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    // Close log file
    fclose(log_file);

    return 0;
