#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// GPIO pin for CO2 warning LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 20

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer
sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_scd40(sensor_data_t *data);
int validate_checksum(uint8_t data[], int len);
int write_led(int state);
void signal_handler(int signal);
void log_error(const char *message);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from SCD40
int read_scd40(sensor_data_t *data) {
    char cmd[2] = {0x21, 0xB1}; // Read measurement command
    char buf[9]; // 3 words * 2 bytes/word + CRC
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay after write

    result = i2cReadDevice(i2c_handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    // Extract data
    data->co2 = (uint16_t)((buf[0] << 8) | buf[1]);
    uint8_t temp_data[2] = {buf[2], buf[3]};
    uint8_t hum_data[2] = {buf[4], buf[5]};

    data->temperature = -45 + 175 * ((uint16_t)((buf[2] << 8) | buf[3])) / 65535;
    data->humidity = 100 * ((uint16_t)((buf[4] << 8) | buf[5])) / 65535;

    // Validate checksums
    if (!validate_checksum((uint8_t*)buf, 2)) {
        fprintf(stderr, "CO2 checksum failed\n");
        return -1;
    }
    if (!validate_checksum((uint8_t*)(buf + 3), 2)) {
        fprintf(stderr, "Temperature checksum failed\n");
        return -1;
    }
    if (!validate_checksum((uint8_t*)(buf + 6), 2)) {
        fprintf(stderr, "Humidity checksum failed\n");
        return -1;
    }

    return 0;
}

// Function to validate CRC-8 checksum
int validate_checksum(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc = (crc << 1);
        }
    }

    if (crc != 0) {
        return 0; // Checksum failed
    }
    return 1; // Checksum passed
}

// Function to control the LED
int write_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    write_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to log errors
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    sensor_data_t sensor_data;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_scd40(&sensor_data) == 0) {
            // Store data in circular buffer
            circular_buffer[buffer_index] = sensor_data;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Print data
            printf("CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n",
                   sensor_data.co2, sensor_data.temperature, sensor_data.humidity);

            // Control LED based on CO2 level
            if (sensor_data.co2 > 1000) {
                write_led(1); // Turn on LED
            } else {
                write_led(0); // Turn off LED
            }
        } else {
            log_error("Failed to read sensor data");
        }

        // Wait 5 seconds
        gpioDelay(5000); // pigpio's delay function
    }

    return 0;
}

