    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    sensor_data_t sensor_data;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_scd40(&sensor_data) == 0) {
            // Store data in circular buffer
            circular_buffer[buffer_index] = sensor_data;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Print data
