    pulse_data_t pulse_data;
    int start_time, end_time, current_time;
    int timeout_count = 0;

    // Wait for the first edge
    while (gpioRead(GPIO_PIN) == 0 && timeout_count < 1000) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
    }

    if (timeout_count >= 1000) {
        log_data(log_file, "SENSOR MALFUNCTION: Timeout waiting for rising edge.");
        return -273.15; // Return absolute zero as error indicator
    }

    start_time = gpioTick();

    // Wait for the falling edge with timeout
    timeout_count = 0;
    while (gpioRead(GPIO_PIN) == 1 && timeout_count < 1000) {
        gpioDelay(1);
        timeout_count++;
    }

    if (timeout_count >= 1000) {
        log_data(log_file, "SENSOR MALFUNCTION: Timeout waiting for falling edge.");
        return -273.15; // Return absolute zero as error indicator
    }

    end_time = gpioTick();

    pulse_data.high_pulse_width = end_time - start_time;
    pulse_data.total_cycle_width = gpioTick() - start_time;

    // Calculate temperature (simplified formula, adjust as needed)
    float temperature = (float)pulse_data.high_pulse_width / (float)pulse_data.total_cycle_width * 100.0 - 50.0;

    // Validate temperature range
    if (temperature < -40.0 || temperature > 150.0) {
        log_data(log_file, "SENSOR MALFUNCTION: Temperature out of range.");
        return -273.15; // Return absolute zero as error indicator
    }

    return temperature;
}

