#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY 0x2400
#define LOG_FILE "environmental_data.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 1000
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t *data, int len);
SensorData convert_data(uint8_t *data);
SensorData apply_offset(SensorData data, float temperature_offset, float humidity_offset);
char* get_iso8601_timestamp();
int log_data(SensorData data, char* timestamp);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {(MEASURE_HIGH_REPEATABILITY >> 8) & 0xFF, MEASURE_HIGH_REPEATABILITY & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(15); // Wait for measurement (at least 15ms)

    result = i2cReadDevice(i2c_handle, (char*)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to validate CRC
int validate_crc(uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    uint8_t polynomial = 0x31; // 0x31 is the CRC polynomial for SHT35

    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }

    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    return 0;
}

// Function to convert raw data to temperature and humidity
SensorData convert_data(uint8_t *data) {
    SensorData sensor_data;
    int temperature_raw = (data[0] << 8) | data[1];
    int humidity_raw = (data[3] << 8) | data[4];

    sensor_data.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return sensor_data;
}

// Function to apply sinusoidal offset
SensorData apply_offset(SensorData data, float temperature_offset, float humidity_offset) {
    SensorData offset_data;
    offset_data.temperature = data.temperature + temperature_offset;
    offset_data.humidity = data.humidity + humidity_offset;

    // Clamp humidity to 0-100%
    if (offset_data.humidity < 0.0) {
        offset_data.humidity = 0.0;
    } else if (offset_data.humidity > 100.0) {
        offset_data.humidity = 100.0;
    }

    return offset_data;
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log data to file
int log_data(SensorData data, char* timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t sensor_data[6];
    SensorData raw_data, offset_data;
    char* timestamp;
    float temperature_offset = 2.0 + (2.0 * (time(NULL) % 60) / 60.0); // Offset between 0 and 2 degrees
    float humidity_offset = 5.0 + (5.0 * (time(NULL) % 60) / 60.0); // Offset between 0 and 5 percent

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, 2) == 0 && validate_crc(sensor_data + 3, 2) == 0) {
                // Convert data
                raw_data = convert_data(sensor_data);

                // Apply offset
                offset_data = apply_offset(raw_data, temperature_offset, humidity_offset);

                // Get timestamp
                timestamp = get_iso8601_timestamp();

                // Log data
                if (log_data(offset_data, timestamp) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }

                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "CRC validation failed, retrying...\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        gpioDelay(SLEEP_SECONDS * 1000); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

