            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }

    // Compare calculated CRC with received CRC
    if (crc != data[2] || crc != data[5]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }

    return 0;
