#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define MEASURE_HUMID_CMD 0xE5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "environment.log"
#define ERROR_LOG_FILE "error.log"

// Global variables
int i2c_handle;
FILE *log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int verify_crc(uint8_t data[], int len, uint8_t crc);
int log_data(sensor_data_t data);
int log_error(const char *message);
void signal_handler(int signal);
void reset_sensor();

// CRC polynomial
const uint8_t crc8_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xb9, 0x88, 0xdb, 0xea, 0x7d, 0x4c, 0x1f, 0x2e
};

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd;
    uint8_t buffer[3];
    int result;
    int retries = RETRY_COUNT;
    int i;

    // Measure temperature
    cmd = MEASURE_TEMP_CMD;
    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteByte(i2c_handle, cmd);
        if (result == 0) break; // Success
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        if (i == RETRY_COUNT - 1) {
            log_error("Failed to write temperature command after multiple retries.");
            return -1;
        }
    }
    if (i != RETRY_COUNT) {
        gpioDelay(10000); // Wait for measurement (10ms)

        for (i = 0; i < RETRY_COUNT; ++i) {
            result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
            if (result == 3) break; // Success
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            if (i == RETRY_COUNT - 1) {
                log_error("Failed to read temperature data after multiple retries.");
                return -1;
            }
        }
        if (i != RETRY_COUNT) {
            uint8_t crc_calculated = 0;
            for (int j = 0; j < 2; j++) {
                crc_calculated ^= buffer[j];
                crc_calculated = crc8_table[crc_calculated];
            }

            uint8_t crc_received = buffer[2];
            if (crc_calculated != crc_received) {
                log_error("Temperature CRC check failed.");
                return -1;
            }

            uint16_t raw_temperature = (buffer[0] << 8) | buffer[1];
            data->temperature = (175.72 * raw_temperature / 65536.0) - 46.85;
        } else {
            data->temperature = -999.0; // Indicate error
        }
    } else {
        data->temperature = -999.0; // Indicate error
    }

    // Measure humidity
    cmd = MEASURE_HUMID_CMD;
    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteByte(i2c_handle, cmd);
        if (result == 0) break; // Success
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        if (i == RETRY_COUNT - 1) {
            log_error("Failed to write humidity command after multiple retries.");
            return -1;
        }
    }
    if (i != RETRY_COUNT) {
        gpioDelay(10000); // Wait for measurement (10ms)

        for (i = 0; i < RETRY_COUNT; ++i) {
            result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
            if (result == 3) break; // Success
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            if (i == RETRY_COUNT - 1) {
                log_error("Failed to read humidity data after multiple retries.");
                return -1;
            }
        }
        if (i != RETRY_COUNT) {
            uint8_t crc_calculated = 0;
            for (int j = 0; j < 2; j++) {
                crc_calculated ^= buffer[j];
                crc_calculated = crc8_table[crc_calculated];
            }

            uint8_t crc_received = buffer[2];
            if (crc_calculated != crc_received) {
                log_error("Humidity CRC check failed.");
                return -1;
            }

            uint16_t raw_humidity = (buffer[0] << 8) | buffer[1];
            data->humidity = (125.0 * raw_humidity / 65536.0) - 6;
        } else {
            data->humidity = -999.0; // Indicate error
        }
    } else {
        data->humidity = -999.0; // Indicate error
    }

    return 0;
}

// Function to verify the CRC checksum
int verify_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t crc_calculated = 0;
    for (int i = 0; i < len; i++) {
        crc_calculated ^= data[i];
        crc_calculated = crc8_table[crc_calculated];
    }
    return (crc_calculated == crc);
}

// Function to log data to a CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file);

    return 0;
}

// Function to log errors to a file
int log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    clock_gettime(CLOCK_REALTIME, NULL);
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);

    fprintf(stderr, "%s: %s\n", timestamp, message);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to reset the sensor
void reset_sensor() {
    uint8_t cmd = 0xE0; // Soft reset command
    int result = i2cWriteByte(i2c_handle, cmd);
    if (result != 0) {
        log_error("Failed to send reset command.");
    } else {
        gpioDelay(100000); // Wait for reset to complete (100ms)
    }
}

int main() {
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Error opening error log file!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        log_error("I2C initialization failed.");
        fclose(log_file);
        fclose(error_log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            log_error("Failed to read sensor data.");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    fclose(error_log_file);
    gpioTerminate();

    return 0;
}

