#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASURE_CMD 0x362F // Continuous measurement command
#define DATA_LENGTH 9
#define FILENAME "airflow.dat"
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(int i2c_handle, uint8_t *data) {
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to write data to the sensor
int write_sensor_command(int i2c_handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw data to pressure and temperature
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // CRC validation
    uint8_t pressure_crc = data[2];
    uint8_t temperature_crc = data[5];

    if (crc8(data, 2) != pressure_crc) {
        fprintf(stderr, "Pressure CRC check failed!\n");
        sensor_data.pressure = -999.0; // Indicate error
    } else {
        sensor_data.pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    }

    if (crc8(data + 3, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        sensor_data.temperature = -999.0; // Indicate error
    } else {
        sensor_data.temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet
    }

    return sensor_data;
}

// Function to log data to a file
int log_data(FILE *fp, float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing pressure to file\n");
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing temperature to file\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open file for logging
    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t data[DATA_LENGTH];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Write measurement command
        if (write_sensor_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error writing measurement command, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Wait for conversion (datasheet specifies 20ms)
        gpioDelay(20000); // 20ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Convert data
        sensor_data = convert_data(data);

        // Log data to file
        if (log_data(fp, sensor_data.pressure, sensor_data.temperature) != 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(SAMPLE_INTERVAL * 1000000); // Convert seconds to microseconds
    }

    // Close I2C connection and file
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

