    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // CRC validation
    uint8_t pressure_crc = data[2];
    uint8_t temperature_crc = data[5];

    if (crc8(data, 2) != pressure_crc) {
        fprintf(stderr, "Pressure CRC check failed!\n");
        sensor_data.pressure = -999.0; // Indicate error
    } else {
        sensor_data.pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    }

    if (crc8(data + 3, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        sensor_data.temperature = -999.0; // Indicate error
    } else {
        sensor_data.temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet
    }

    return sensor_data;
}

// Function to log data to a file
int log_data(FILE *fp, float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing pressure to file\n");
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing temperature to file\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open file for logging
    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t data[DATA_LENGTH];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Write measurement command
        if (write_sensor_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error writing measurement command, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Wait for conversion (datasheet specifies 20ms)
        gpioDelay(20000); // 20ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Convert data
        sensor_data = convert_data(data);

        // Log data to file
        if (log_data(fp, sensor_data.pressure, sensor_data.temperature) != 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(SAMPLE_INTERVAL * 1000000); // Convert seconds to microseconds
    }

    // Close I2C connection and file
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

