#define SDP800_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F // Continuous measurement command
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    uint16_t status;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read data from the SDP800 sensor
int read_sdp800(int i2c_handle, sensor_data_t *data) {
    uint8_t buffer[9];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0, MEASURE_COMMAND >> 8);
    if (result != 0) {
        fprintf(stderr, "Error writing MSB of measurement command: %d\n", result);
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0, MEASURE_COMMAND & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Error writing LSB of measurement command: %d\n", result);
        return -1;
    }

    // Wait for conversion time (45ms)
    gpioDelay(45000); // 45ms

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Extract data from buffer
    data->pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->status = (uint16_t)((buffer[3] << 8) | buffer[4]);

    // CRC validation
    uint8_t crc_pressure = buffer[2];
    uint8_t crc_status = buffer[5];

    if (crc8(buffer, 2) != crc_pressure) {
        fprintf(stderr, "CRC error for pressure data\n");
        return -1;
    }

    if (crc8(buffer + 3, 2) != crc_status) {
        fprintf(stderr, "CRC error for status data\n");
        return -1;
    }

    return 0;
}

// Function to log data to a file
void log_data(FILE *log_file, int16_t pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sdp800(i2c_handle, &sensor_data) == 0) {
            // Log data
            log_data(log_file, sensor_data.pressure);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

