}

// Initialize
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 1000); // Set PWM range to 0-1000

    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x28, no flags
    if (i2c_handle < 0) {
