        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Read sensor data
int read_sensor(int i2c_handle) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit integer
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    return raw_pressure;
}

// Calculate flow rate (example formula, adjust as needed)
float calculate_flow_rate(int raw_pressure) {
    // This is a placeholder.  Replace with the actual formula from the datasheet.
