    // Example: flow_rate = (raw_pressure / 65535.0) * 20.0
    // where 20.0 is the maximum flow rate in SLPM.
    float flow_rate = (float)raw_pressure / 65535.0 * 20.0;
    return flow_rate;
}

// Set fan speed using PWM
void set_fan_speed(float flow_rate) {
    // Map flow rate to PWM duty cycle (0-1000)
    int duty_cycle = (int)(flow_rate * 10.0); // Example mapping
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000) duty_cycle = 1000;

    gpioPWM(FAN_GPIO, duty_cycle);
}

