        float flow_rate = calculate_flow_rate(raw_pressure);
        set_fan_speed(flow_rate);
        log_data((float)raw_pressure, flow_rate);

        gpioDelay(SAMPLE_INTERVAL_MS); // 100 ms delay
    }

    cleanup();
    return 0;
}

