#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5C

// LPS33HW register addresses
#define CTRL_REG1 0x20
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;
FILE *log_file;

// Function prototypes
int init_lps33hw();
int read_pressure(int32_t *pressure);
int read_temperature(int16_t *temperature);
void log_data(int32_t pressure, int16_t temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int32_t pressure;
    int16_t temperature;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LPS33HW
    if (init_lps33hw() != 0) {
        fprintf(stderr, "LPS33HW initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data;
        int retry_count = 0;
        int read_success = 0;

        // Retry reading pressure and temperature
        while (retry_count < 3 && !read_success) {
            if (read_pressure(&data.pressure) == 0 && read_temperature(&data.temperature) == 0) {
                read_success = 1;
            } else {
                fprintf(stderr, "I2C read failed, retrying... (%d/3)\n", retry_count + 1);
                retry_count++;
                gpioDelay(100); // Wait before retrying
            }
        }

        if (read_success) {
            log_data(data.pressure, data.temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data after multiple retries\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize LPS33HW
int init_lps33hw() {
    // Enable continuous data acquisition (ODR = 1 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x02) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return -1;
