#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SCD30_ADDR 0x61
#define LOG_FILE "air_quality.log"
#define CO2_THRESHOLD 800.0
#define CO2_HIGH_THRESHOLD 1200.0

// SCD30 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void control_ventilation(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the SCD30 sensor
int initialize_sensor() {
    char buf[2];
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(log_file, "%s I2C Write Error: Failed to start periodic measurement\n", __func__);
        fflush(log_file);
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to start
    return 0;
}

// Function to read data from the SCD30 sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data = {0.0, 0.0, 0.0};
    char buf[18];
    uint8_t crc[9];
    int i;

    // Read 18 bytes of data
    if (i2cReadDevice(i2c_handle, buf, 18) != 18) {
        fprintf(log_file, "%s I2C Read Error: Failed to read measurement data\n", __func__);
        fflush(log_file);
        return data; // Return default values on error
    }

    // Extract CRC bytes
    for (i = 0; i < 9; i++) {
        crc[i] = buf[i];
    }

    // CRC Check for CO2
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(log_file, "%s CRC Error: CO2 CRC mismatch\n", __func__);
        fflush(log_file);
        return data; // Return default values on CRC error
    }

    // CRC Check for Temperature
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(log_file, "%s CRC Error: Temperature CRC mismatch\n", __func__);
        fflush(log_file);
        return data; // Return default values on CRC error
    }

    // CRC Check for Humidity
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(log_file, "%s CRC Error: Humidity CRC mismatch\n", __func__);
        fflush(log_file);
        return data; // Return default values on CRC error
    }

    // Convert data
    data.co2 = *((float*)&buf[0]);
    data.temperature = *((float*)&buf[3]);
    data.humidity = *((float*)&buf[6]);

    return data;
}

// Function to log data to a file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file);
}

// Function to control ventilation based on CO2 levels
void control_ventilation(sensor_data_t data) {
    if (data.co2 < CO2_THRESHOLD) {
        fprintf(log_file, "%s Ventilation: OFF\n", __func__);
        fflush(log_file);
    } else if (data.co2 < CO2_HIGH_THRESHOLD) {
        fprintf(log_file, "%s Ventilation: LOW\n", __func__);
        fflush(log_file);
    } else {
        fprintf(log_file, "%s Ventilation: HIGH\n", __func__);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(log_file, "%s Signal received: %d. Terminating program.\n", __func__, signal);
    fflush(log_file);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(log_file, "%s Cleaning up resources.\n", __func__);
    fflush(log_file);

    // Stop periodic measurement
    char buf[2];
    buf[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(log_file, "%s I2C Write Error: Failed to stop periodic measurement\n", __func__);
        fflush(log_file);
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(log_file, "%s I2C Open Error: Failed to open I2C bus\n", __func__);
        fflush(log_file);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(log_file, "%s Sensor initialization failed. Exiting.\n", __func__);
        fflush(log_file);
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();

        if (data.co2 != 0.0) {
            log_data(data);
            control_ventilation(data);
        } else {
            fprintf(log_file, "%s Sensor not responding or data not ready\n", __func__);
            fflush(log_file);
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

