    if (crc8(&buf[0], 2) != buf[2] || crc8(&buf[3], 2) != buf[5] || crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Extract data
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    data->scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    return 0;
}

