// Define the I2C address of the SDP810 sensor
#define SDP810_I2C_ADDR 0x25

// Define the I2C bus number (usually 1 on Raspberry Pi)
#define I2C_BUS 1

// Define the trigger command for continuous measurement
#define TRIGGER_COMMAND 0x362F // Continuous measurement without averaging

// Define the CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variable to store the I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate the CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, float *pressure, float *temperature) {
    uint8_t trigger_command[2] = {(TRIGGER_COMMAND >> 8) & 0xFF, TRIGGER_COMMAND & 0xFF};
    uint8_t data[9];
    int result;

    // Send the trigger command
    result = i2cWriteDevice(i2c_handle, (char *)trigger_command, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for the conversion to complete (at least 45ms)
    gpioDelay(45000); // 45ms

    // Read 9 bytes of data from the sensor
    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Extract the raw pressure and temperature values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Calculate the pressure in Pascals
    *pressure = (float)raw_pressure / 60.0f; // Scale factor from datasheet

    // Calculate the temperature in degrees Celsius
    *temperature = (float)raw_temperature / 200.0f; // Scale factor from datasheet

    // CRC Check
    uint8_t crc_pressure = crc8(data, 2);
    uint8_t crc_temperature = crc8(data + 3, 2);

    if (crc_pressure != data[2] || crc_temperature != data[5]) {
        fprintf(stderr, "CRC check failed!\n");
        return -1;
    }

    return 0;
}

int main() {
    // Register the signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP810_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop to read and log data every second
    float pressure, temperature;
    while (1) {
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000000); // Wait for 1 second
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

