#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40
#define CONFIG_REG 0x0F
#define MEASUREMENT_REG 0x00
#define DRDY_REG 0x02
#define DRDY_VALUE 0x00 // Assuming no pull-up resistor

// Structure to hold temperature and humidity data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to configure the HDC1000 sensor
int config_hdc1000(int fd) {
    uint8_t config_value = 0x10; // 14-bit temperature and humidity resolution
    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (write(fd, &config_value, 1) != 1) {
        perror("Error writing to configuration register");
        return -1;
    }
    return 0;
}

// Function to trigger a temperature and humidity measurement
int trigger_measurement(int fd) {
    uint8_t trigger_value = 0x01; // Trigger measurement
    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (write(fd, &trigger_value, 1) != 1) {
        perror("Error writing to measurement trigger register");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity data from the HDC1000
int read_hdc1000(int fd, sensor_data_t *data) {
    uint8_t raw_data[4];
    int retries = 3; // Number of retries

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
            perror("Error setting I2C slave address");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Read 4 bytes from the measurement register
        if (read(fd, raw_data, 4) != 4) {
            perror("Error reading from measurement register");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Check DRDY bit
