    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to configure the HDC1000 sensor
int config_hdc1000(int fd) {
    uint8_t config_value = 0x10; // 14-bit temperature and humidity resolution
    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (write(fd, &config_value, 1) != 1) {
        perror("Error writing to configuration register");
        return -1;
    }
    return 0;
}

