int trigger_measurement(int fd) {
    uint8_t trigger_value = 0x01; // Trigger measurement
    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (write(fd, &trigger_value, 1) != 1) {
        perror("Error writing to measurement trigger register");
        return -1;
    }
    return 0;
}

