    int retries = 3; // Number of retries

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
            perror("Error setting I2C slave address");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

