#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
float read_temperature();
void log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int si7051_address;
    int sleep_interval;
} sensor_config_t;

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from Si7051
float read_temperature() {
    char buf[2];
    int result;

    result = i2cWriteByte(i2c_handle, MEASURE_TEMP_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1000.0; // Indicate error
    }

    gpioDelay(10); // Wait for conversion (datasheet says 11ms max)

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1000.0; // Indicate error
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = (175.72 * raw_temp / 65536.0) - 46.85;
    return temperature;
}

// Log temperature to console
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in %d seconds...\n", SLEEP_SECONDS);
        }
        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

