#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// I2C address of the ICP-10101 sensor
#define I2C_ADDR 0x69

// I2C bus number (typically 1 on Raspberry Pi)
#define I2C_BUS 1

// Measurement command (trigger measurement)
#define MEASURE_CMD 0x07

// Structure to hold temperature and pressure data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
sensor_data_t process_sensor_data(uint8_t *data);
char* get_iso8601_timestamp();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a measurement on the sensor
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Process raw sensor data
sensor_data_t process_sensor_data(uint8_t *data) {
    sensor_data_t sensor_data;
    // Extract raw temperature and pressure values
    int32_t raw_pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    int32_t raw_temperature = (data[3] << 16) | (data[4] << 8) | data[5];

    // Convert raw values to temperature (Celsius) and pressure (Pa)
    sensor_data.temperature = (float)raw_temperature / 100.0;
    sensor_data.pressure = (float)raw_pressure / 100.0;

    return sensor_data;
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    uint8_t sensor_data[6];
    sensor_data_t processed_data;
    char *timestamp;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        gpioDelay(7); // Wait 7ms for measurement to complete

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Process sensor data
        processed_data = process_sensor_data(sensor_data);

        // Get timestamp
        timestamp = get_iso8601_timestamp();

        // Print data to stdout
        printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, processed_data.temperature, processed_data.pressure);

        free(timestamp); // Free the allocated memory

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

