                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the SDP800 sensor
int read_sdp800(uint8_t *data) {
    char buf[3];
    int result;

    result = i2cWriteByte(i2c_handle, (MEASUREMENT_COMMAND >> 8) & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Failed to write MSB of measurement command: %s\n", strerror(errno));
        return -1;
    }

    result = i2cWriteByte(i2c_handle, MEASUREMENT_COMMAND & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Failed to write LSB of measurement command: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(8); // Wait 8ms

    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read data from sensor: %s\n", strerror(errno));
        return -1;
    }

    data[0] = buf[0];
    data[1] = buf[1];
    data[2] = buf[2];

    return 0;
}

// Function to verify the CRC-8 checksum
int verify_crc(const uint8_t *data) {
    uint8_t crc = crc8(data, 2);
    if (crc != data[2]) {
        fprintf(stderr, "CRC check failed!\n");
        return -1;
    }
    return 0;
}

// Function to convert raw data to pressure (Pa)
float convert_to_pressure(uint8_t msb, uint8_t lsb) {
    int16_t raw_pressure = (msb << 8) | lsb;
    return (float)raw_pressure / 60.0; // Sensitivity factor from datasheet
}

// Function to log the data to a file
int log_data(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file is newly created
    if (access(LOG_FILE, F_OK) == -1) {
        fprintf(log_file, "Timestamp,Pressure(Pa)\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fclose(log_file);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    uint8_t data[3];
    int retry;

    printf("Starting airflow monitoring...\n");

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_sdp800(data) == 0) {
                if (verify_crc(data) == 0) {
                    float pressure = convert_to_pressure(data[0], data[1]);
                    if (log_data(pressure) == 0) {
                        printf("Pressure: %.2f Pa\n", pressure);
                        break; // Exit retry loop on success
                    } else {
                        fprintf(stderr, "Failed to log data\n");
                    }
                } else {
                    fprintf(stderr, "CRC check failed, retrying...\n");
                }
            } else {
                fprintf(stderr, "Failed to read sensor data, retrying...\n");
            }
            retry++;
            gpioDelay(RETRY_DELAY_MS); // Wait before retrying
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after multiple retries. Exiting.\n");
            break; // Exit main loop if all retries failed
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Airflow monitoring stopped.\n");

    return 0;
}

