// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE 1048576 // 1 MB
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
SensorData process_sensor_data(uint8_t *data);
int write_to_log(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Process sensor data
SensorData process_sensor_data(uint8_t *data) {
    SensorData sensor_data;
    uint16_t humidity_raw = (data[0] << 8) | data[1];
    uint16_t temperature_raw = (data[2] << 8) | data[3];

    // Check status bits
    if ((data[0) & 0x80) != 0) {
        fprintf(stderr, "Sensor status error: %d\n", data[0] & 0x80);
        sensor_data.temperature = -999.0; // Indicate error
        sensor_data.humidity = -999.0;
        return sensor_data;
    }

    // Convert data
    sensor_data.humidity = ((float)humidity_raw / 16383) * 100;
    sensor_data.temperature = ((float)temperature_raw / 16383) * 165 - 40;

    return sensor_data;
}

// Write to log file
int write_to_log(SensorData data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fclose(fp);

    // Check log size and truncate if necessary
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size > MAX_LOG_SIZE) {
        fprintf(stderr, "Truncating log file to %d bytes...\n", MAX_LOG_SIZE);
        fseek(fp, MAX_LOG_SIZE - 1, SEEK_SET);
        ftruncate(fileno(fp), MAX_LOG_SIZE);
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    uint8_t data[4];
    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Process sensor data
            sensor_data = process_sensor_data(data);

            // Write to log file
            if (write_to_log(sensor_data) != 0) {
                fprintf(stderr, "Error writing to log file.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

