#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "pressure_log.txt"
#define TIMEOUT_US 10000 // 10ms timeout
#define MAX_PULSE_WIDTH 813 // Maximum pulse width in microseconds

// Structure to hold SENT data
typedef struct {
    unsigned int status;
    unsigned int data1;
    unsigned int data2;
    unsigned int data3;
    unsigned int checksum;
} SENTData;

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read SENT data from the sensor
int read_sent_data(SENTData *data) {
    unsigned int pulse_width;
    unsigned int start_time, end_time;
    int i;

    // Wait for the start of the synchronization pulse (56 ticks)
    start_time = gpioTick();
    while (gpioTick() - start_time < 56 * 1000) {
        if (gpioRead(GPIO_PIN) == 0) {
            break;
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (gpioTick() - start_time > 56 * 1000) {
        fprintf(stderr, "Error: Timeout waiting for synchronization pulse.\n");
        return -1; // Timeout error
    }

    // Read the data nibbles
    for (i = 0; i < 12; i++) {
        start_time = gpioTick();
        while (gpioTick() - start_time < TIMEOUT_US) {
            if (gpioRead(GPIO_PIN) == 1) {
                break;
            }
            gpioDelay(1);
        }

        if (gpioTick() - start_time > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for rising edge of pulse %d.\n", i);
            return -1; // Timeout error
        }

        start_time = gpioTick();
        while (gpioTick() - start_time < TIMEOUT_US) {
            if (gpioRead(GPIO_PIN) == 0) {
                break;
            }
            gpioDelay(1);
        }

        if (gpioTick() - start_time > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for falling edge of pulse %d.\n", i);
            return -1; // Timeout error
        }

        end_time = gpioTick();
        pulse_width = end_time - start_time;

        if (pulse_width < 12 * 1000 || pulse_width > 271 * 1000) {
            fprintf(stderr, "Error: Invalid pulse width for nibble %d: %d ticks.\n", i, pulse_width);
            return -1; // Invalid pulse width error
        }

        if (i < 3) {
            data->data[i / 4] = pulse_width;
        } else if (i < 11) {
            data->data[(i - 3) / 4] = pulse_width;
        } else {
            data->checksum = pulse_width;
        }
    }

    // Calculate checksum (sum of data nibbles modulo 256)
    unsigned int sum = 0;
    for (i = 0; i < 9; i++) {
        sum += data->data[i];
    }
    data->checksum = sum & 0xFF;

    // Verify checksum
    if (data->checksum != (data->data[0] + data->data[1] + data->data[2] + data->data[3] + data->data[6] + data->data[7] + data->data[8]) % 256) {
