#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x0A
#define DEVICE_ID 0x02
#define LOG_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int verify_device_id(int i2c_handle);
float read_temperature(int i2c_handle);
int log_temperature(float temperature, FILE *log_file);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to verify the TMP117 device ID
int verify_device_id(int i2c_handle) {
    int device_id;
    int result;

    result = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
        return -1;
    }
    device_id = result;

    if (device_id != DEVICE_ID) {
        fprintf(stderr, "Error: Incorrect device ID (0x%02X, expected 0x%02X)\n", device_id, DEVICE_ID);
        return -1;
    }

    printf("TMP117 device ID verified: 0x%02X\n", device_id);
    return 0;
}

// Function to read the temperature from the TMP117
float read_temperature(int i2c_handle) {
    int16_t raw_temp;
    float temperature;

    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw temperature to Celsius (see TMP117 datasheet)
    temperature = (float)raw_temp * 0.0078125;

    return temperature;
}

// Function to log the temperature to a binary file
int log_temperature(float temperature, FILE *log_file) {
    size_t bytes_written = fwrite(&temperature, sizeof(float), 1, log_file);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (verify_device_id(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append binary mode
    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature(i2c_handle);
        if (temperature > -999.0) { // Check for valid temperature reading
            if (log_temperature(temperature, log_file) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping logging.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

