#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// SHT40 command to measure temperature and humidity
#define SHT40_MEASURE_CMD 0xFD

// CRC8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize();
int read_sensor_data(sensor_data_t *data);
int validate_crc(uint8_t data[], int len, uint8_t crc);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// CRC8 calculation function
uint8_t crc8(const uint8_t *data, int len, uint8_t crc) {
    uint8_t polynomial = CRC8_POLYNOMIAL;
    uint8_t crc_value = crc;
    for (int i = 0; i < len; i++) {
        crc_value ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_value & 0x80) {
                crc_value = (crc_value << 1) ^ polynomial;
            } else {
                crc_value <<= 1;
            }
        }
    }
    return crc_value;
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SHT40_ADDR, 0); // I2C bus 1, SHT40 address, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read temperature and humidity from SHT40
int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd = SHT40_MEASURE_CMD;
    uint8_t buffer[6];

    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }

    gpioDelay(10); // Wait for measurement (datasheet specifies 10ms for high precision)

    if (i2cReadDevice(i2c_handle, buffer, 6) != 6) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    // Validate CRC for temperature
    if (validate_crc(buffer, 2, buffer[2]) != 0) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }

    // Validate CRC for humidity
    if (validate_crc(buffer + 3, 2, buffer[5]) != 0) {
        fprintf(stderr, "Humidity CRC validation failed\n");
        return -1;
    }

    // Convert data
    int temperature_raw = (buffer[0] << 8) | buffer[1];
    int humidity_raw = (buffer[3] << 8) | buffer[4];

    data->temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    data->humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

