#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
float read_temperature();
void add_to_buffer(CircularBuffer *cb, float temp);
float get_average_temperature(CircularBuffer *cb);
void flush_buffer_to_file(CircularBuffer *cb);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from TMP117
float read_temperature() {
    int raw_temp;
    float temp_celsius;

    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw temperature to Celsius (see TMP117 datasheet)
    temp_celsius = (float)(raw_temp >> 4) * 0.0078125;
    return temp_celsius;
}

// Function to add temperature to the circular buffer
void add_to_buffer(CircularBuffer *cb, float temp) {
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to calculate the average temperature from the buffer
float get_average_temperature(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Function to flush the buffer to a file
void flush_buffer_to_file(CircularBuffer *cb) {
    FILE *fp = fopen("temperature_log.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing!\n");
        return;
    }

    size_t elements_written = fwrite(cb->buffer, sizeof(float), cb->count, fp);
    if (elements_written != cb->count) {
        fprintf(stderr, "Error writing to file!\n");
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer temp_buffer;
    init_circular_buffer(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            add_to_buffer(&temp_buffer, temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);

        // Flush buffer to file every 10 samples (approx. every 50 seconds)
        if (temp_buffer.count >= 10) {
            flush_buffer_to_file(&temp_buffer);
            printf("Buffer flushed to file.\n");
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

