#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// SHTC3 commands
#define SHTC3_MEASURE_HIGH_PRECISION 0x2400

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_data(const uint8_t *data);
int log_data(const sensor_data_t *data);
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0); // Bus 1, address 0x70, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    char buf[2];
    buf[0] = (SHTC3_MEASURE_HIGH_PRECISION >> 8) & 0xFF;
    buf[1] = SHTC3_MEASURE_HIGH_PRECISION & 0xFF;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    gpioDelay(15); // Wait 15ms
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate data
int validate_data(const uint8_t *data) {
    uint8_t crc_calculated = calculate_crc(data, 2);
    if (crc_calculated != data[2]) {
        fprintf(stderr, "CRC check failed!\n");
        return -1;
    }

    uint8_t crc_humidity = calculate_crc(data + 3, 2);
    if (crc_humidity != data[5]) {
        fprintf(stderr, "CRC check failed for humidity!\n");
        return -1;
    }

    return 0;
}

// Log data to file
int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    uint8_t data[6];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Measurement trigger failed!\n");
            continue; // Try again
        }

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Sensor data read failed!\n");
            continue; // Try again
        }

        // Validate data
        if (validate_data(data) != 0) {
            fprintf(stderr, "Data validation failed!\n");
            continue; // Try again
        }

        // Convert data to temperature and humidity
        uint16_t temp_raw = (data[0] << 8) | data[1];
        uint16_t humidity_raw = (data[3] << 8) | data[4];

        sensor_data.temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
        sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;

        // Validate temperature and humidity ranges
        if (sensor_data.temperature < -40.0 || sensor_data.temperature > 125.0) {
            fprintf(stderr, "Temperature out of range!\n");
        } else if (sensor_data.humidity < 0.0 || sensor_data.humidity > 100.0) {
            fprintf(stderr, "Humidity out of range!\n");
        } else {
            // Log data
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Data logging failed!\n");
            }

            // Print data to stdout
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

