#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define MAX_TIMEOUT_MS 100
#define MAX_DHT11_READINGS 100

// Structure to hold DHT11 data
typedef struct {
    float temperature;
    float humidity;
    int status;
} DHT11Data;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int gpio_initialized = 0;

// Function prototypes
int dht11_start_signal();
int dht11_read_data(DHT11Data *data);
int dht11_checksum_check(unsigned char data[], int len);
void log_error(const char *message);
void signal_handler(int signal);
int read_dht11(DHT11Data *data);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Log error to file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "%s: %s\n", timestamp, message);
    }
}

// DHT11 start signal
int dht11_start_signal() {
    int i;
    for (i = 0; i < MAX_TIMEOUT_MS; i++) {
        if (gpioWrite(DHT11_GPIO, 0) != 0) {
            log_error("Failed to set GPIO low for start signal.");
            return -1;
        }
        gpioDelay(18); // 18ms
        if (gpioWrite(DHT11_GPIO, 1) != 0) {
            log_error("Failed to set GPIO high for start signal.");
            return -1;
        }
        gpioDelay(40); // 40us
        return 0; // Success
    }
    log_error("DHT11 start signal timeout.");
    return -1;
}

// Read data from DHT11
int dht11_read_data(DHT11Data *data) {
    unsigned char data_buffer[5] = {0, 0, 0, 0, 0};
    int i, j;
    int bit = 0;
    int byte = 0;
    int data_index = 0;
    int bit_index = 0;
    int start_signal_retries = 0;
    int data_retries = 0;

    // Retry start signal
    while (start_signal_retries < MAX_TIMEOUT_MS) {
        if (dht11_start_signal() == 0) {
            break; // Start signal successful
        }
        start_signal_retries++;
        gpioDelay(RETRY_DELAY_MS);
    }
