// SHT31-D I2C address
#define SHT31_ADDR 0x44

// Measurement command (High Repeatability, Clock Stretching disabled)
#define MEASURE_CMD 0x2C06

// Log file path
#define LOG_FILE "sht31d_data.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read temperature and humidity from SHT31-D
int read_sht31d(int i2c_handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[6];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result == 0) {
            gpioDelay(20); // Wait for measurement (adjust as needed)
            result = i2cReadDevice(i2c_handle, (char *)data, 6);
            if (result == 6) {
                // CRC validation
                if (crc8(data, 2) == data[2] && crc8(data + 3, 2) == data[5]) {
                    // Convert data to temperature and humidity
                    int temp_raw = (data[0] << 8) | data[1];
                    int hum_raw = (data[3] << 8) | data[4];

                    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);
                    *humidity = 100.0 * (float)hum_raw / 65535.0;

                    return 0; // Success
                } else {
                    fprintf(stderr, "CRC validation failed!\n");
                }
            } else {
                fprintf(stderr, "I2C read failed!\n");
            }
        } else {
            fprintf(stderr, "I2C write failed! Retrying...\n");
        }
        retries--;
        gpioDelay(10); // Wait before retrying
    }

    fprintf(stderr, "Failed to read SHT31-D after multiple retries.\n");
    return -1; // Failure
}

