// Function to read sensor data from ADPD105
int read_sensor_data(int i2c_handle, sensor_data_t *data) {
    char buf[6];
    int result;

    // Read 6 bytes of data (Red, Green, Blue)
    result = i2cReadI2CBlockData(i2c_handle, REG_RED_L, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return SENSOR_ERROR_VALUE; // Indicate error
    }

    // Combine high and low bytes for each color
    data->red = (buf[1] << 8) | buf[0];
    data->green = (buf[3] << 8) | buf[2];
    data->blue = (buf[5] << 8) | buf[4];

    return 0; // Indicate success
}

// Function to calculate correlated color temperature (CCT)
float calculate_cct(int red, int green, int blue) {
    // Implement CCT calculation formula from ADPD105 datasheet
    // This is a placeholder; replace with the actual formula
    float x = (float)red / (float)green;
    float y = (float)green / (float)blue;

    // Implement the CIE94 formula for CCT calculation
    float u = x * x + y * y - 0.3290;
    float v = 2 * x * y - 0.77;
    float u_prime = 4 * x * x * x + 3 * x * y * y - 0.238;
    float v_prime = 3 * x * x * y * y + 4 * x * y * y - 0.238;

    float delta_u = u_prime - u;
    float delta_v = v_prime - v;

    float ct = 449.0 * pow(delta_u, 1.0 / 3.0) + 3525.0 * pow(delta_v, 1.0 / 3.0) - 6850.0;

    return ct;
}

