#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
double temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
double running_average = 0.0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize();
double read_temperature();
void update_circular_buffer(double temperature);
double calculate_running_average();
void control_fan(double average_temperature);
void signal_handler(int signal);
void log_error(const char *message);

// Function to initialize the program
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    return 0;
}

// Function to read temperature from LM75B sensor
double read_temperature() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        log_error("Failed to read temperature from I2C");
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    double temperature = raw_temp * 0.125;

    return temperature;
}

// Function to update the circular buffer
void update_circular_buffer(double temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the running average
double calculate_running_average() {
    double sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the cooling fan
void control_fan(double average_temperature) {
    if (average_temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else if (average_temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to log errors
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Temperature monitoring and fan control started.\n");

    while (program_running) {
        double temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            update_circular_buffer(temperature);
            double average_temperature = calculate_running_average();
            control_fan(average_temperature);
            printf("Temperature: %.2f\u00b0C, Average: %.2f\u00b0C, Fan: %s\n",
                   temperature, average_temperature, gpioRead(FAN_GPIO) ? "ON" : "OFF");
        } else {
            // Retry on the next cycle
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    return 0;
}

