#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F // Continuous measurement without averaging
#define SAMPLE_INTERVAL 1.0 // seconds
#define PRESSURE_THRESHOLD 5.0 // Pa
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
int validate_crc(char *data, int len, uint8_t crc);
int convert_data(char *data, sensor_data_t *sensor_data);
int log_data(sensor_data_t sensor_data);
void signal_handler(int signal);
void cleanup();

// CRC8 calculation function
uint8_t crc8(const char *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C initialization function
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send command function
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data function
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Validate CRC function
int validate_crc(char *data, int len, uint8_t crc) {
    uint8_t calculated_crc = crc8(data, len);
    if (calculated_crc != crc) {
        fprintf(stderr, "CRC mismatch: calculated 0x%02X, received 0x%02X\n", calculated_crc, crc);
        return -1;
    }
    return 0;
}

// Convert data function
int convert_data(char *data, sensor_data_t *sensor_data) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    sensor_data->differential_pressure = (float)raw_pressure / 240.0; // Pa
    sensor_data->temperature = (float)raw_temperature / 200.0;     // °C

    return 0;
}

// Log data function
int log_data(sensor_data_t sensor_data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, sensor_data.differential_pressure, sensor_data.temperature);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("airflow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(log_file, "timestamp,differential_pressure,temperature\n"); // CSV header

    // Main loop
    sensor_data_t sensor_data;
    char read_buffer[9];

    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to send measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(45); // Wait 45ms

        // Read data
        if (read_data(i2c_handle, read_buffer, 9) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC
        if (validate_crc(read_buffer, 2, read_buffer[2]) != 0) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (validate_crc(read_buffer + 3, 2, read_buffer[5]) != 0) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert data
        if (convert_data(read_buffer, &sensor_data) != 0) {
            fprintf(stderr, "Failed to convert data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log data
        if (log_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to log data, retrying...\n");
        }

        // Check pressure threshold
        if (sensor_data.differential_pressure > PRESSURE_THRESHOLD) {
            fprintf(stderr, "Warning: Differential pressure exceeds threshold (%.2f Pa)\n", sensor_data.differential_pressure);
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

