// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x40
#define TEMP_REG 0x00
#define LED_GPIO 17
#define HYSTERESIS_TEMP 28.0
#define HYSTERESIS_TEMP_LOW 27.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
void control_led(float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read temperature from the sensor
float read_temperature() {
    int raw_temp;
    float temperature;

    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate error
    }

    // Convert raw temperature to Celsius (refer to STTS2004 datasheet)
    // Assuming the sensor returns a 12-bit temperature value, left-aligned.
    raw_temp = raw_temp >> 4; // Shift right to get the 12-bit value
    temperature = (float)raw_temp * 0.0625; // Each LSB is 0.0625 degrees C

    return temperature;
}

// Function to control the LED based on temperature
void control_led(float temperature) {
    static int led_state = 0; // 0 = off, 1 = on

    if (temperature > HYSTERESIS_TEMP && led_state == 0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        led_state = 1;
    } else if (temperature < HYSTERESIS_TEMP_LOW && led_state == 1) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
        led_state = 0;
    }
}

