#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25

// Define the CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Define the scaling factor for SDP800-500Pa
#define SCALE_FACTOR 0.1

// Global variables for I2C handle and file pointer
int i2c_handle;
FILE *log_file;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t *data);
sensor_data_t convert_data(uint8_t *data);
int log_data(sensor_data_t data);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads data from the sensor
int read_sensor_data(uint8_t *data) {
    char cmd[1] = {0x24}; // Trigger measurement command
    int result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(50000); // Wait 50ms

    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
