#define SI7021_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define MEASURE_HUMID_CMD 0xE5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 20
#define LOG_FILE "environment.log"
#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_sensor_data(uint8_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
