    uint16_t raw_temperature, raw_humidity;
    float temperature, humidity;

    // Check sensor presence
    if (read_sensor_data(data) != 0) {
        fprintf(log_file, "%s,ERROR: Si7021 sensor not found\n", __TIME__);
        fprintf(stderr, "%s,ERROR: Si7021 sensor not found\n", __TIME__);
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_sensor_data(data) == 0) {
            raw_temperature = (data[0] << 8) | data[1];
            temperature = convert_temperature(raw_temperature);
        } else {
            temperature = -999.0; // Indicate error
        }

        // Read humidity
        if (read_sensor_data(data) == 0) {
            raw_humidity = (data[0] << 8) | data[1];
            humidity = convert_humidity(raw_humidity);
        } else {
            humidity = -999.0; // Indicate error
        }

        // Log data
        if (temperature != -999.0 && humidity != -999.0) {
            log_data(temperature, humidity);
        } else {
            fprintf(log_file, "%s,ERROR: Failed to read sensor data\n", __TIME__);
            fprintf(stderr, "%s,ERROR: Failed to read sensor data\n", __TIME__);
        }

        gpioDelay(60000 * 1000); // Wait 60 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

