#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP810_ADDR 0x25

// Define the log file name
#define LOG_FILE "hvac_pressure_log.txt"

// Define the measurement command
#define MEASURE_CMD 0x362F // Continuous measurement without averaging

// Define the CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t *data, int len);
int convert_data(uint8_t *data, sensor_data_t *sensor_data);
int log_data(sensor_data_t sensor_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_Pa,temperature_C\n");
    }
    fflush(log_file);

    return 0;
}

// Trigger measurement function
int trigger_measurement() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Validate CRC function
int validate_crc(uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    uint8_t polynomial = CRC_POLYNOMIAL;
    uint8_t data_byte;

    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc = (crc << 1);
            }
        }
    }

    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }
    return 0;
}

// Convert data function
int convert_data(uint8_t *data, sensor_data_t *sensor_data) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    sensor_data->pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    sensor_data->temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return 0;
}

// Log data function
int log_data(sensor_data_t sensor_data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, sensor_data.pressure, sensor_data.temperature);
    fflush(log_file);
    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed\n");
        return 1;
    }

    uint8_t sensor_data[9];
    sensor_data_t sensor_data_t;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Measurement trigger failed\n");
            continue; // Continue to the next iteration
        }

        // Wait for at least 50ms
        gpioDelay(50);

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Sensor data read failed\n");
            continue; // Continue to the next iteration
        }

        // Validate CRC
        if (validate_crc(sensor_data, 9) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Continue to the next iteration
        }

        // Convert data
        if (convert_data(sensor_data, &sensor_data_t) != 0) {
            fprintf(stderr, "Data conversion failed\n");
            continue; // Continue to the next iteration
        }

        // Log data
        if (log_data(sensor_data_t) != 0) {
            fprintf(stderr, "Data logging failed\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

