// CRC polynomial and initial value
const unsigned char crc8_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xb9, 0x88, 0xdb, 0xea, 0x7d, 0x4c, 0x1f, 0x2e
};

// CRC calculation function
int validate_crc(unsigned char data[], int nbrOfBytes, unsigned char crc) {
    unsigned char crc_calculated = 0xFF;
    unsigned char data_copy[nbrOfBytes + 1];
    memcpy(data_copy, data, nbrOfBytes);
    data_copy[nbrOfBytes] = crc;

    for (int i = 0; i < nbrOfBytes; i++) {
        crc_calculated ^= data_copy[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ 0x31;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    if (crc_calculated != 0xFF) {
        return 0; // CRC check failed
    }
    return 1; // CRC check passed
}

// I2C initialization function
int init_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Start periodic measurement function
int start_periodic_measurement() {
    char cmd[2] = {(START_PERIODIC_MEASUREMENT_CMD >> 8) & 0xFF, START_PERIODIC_MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to send start periodic measurement command");
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(sensor_data_t *data) {
    char cmd[2] = {0xE4, 0xB8};
    char buffer[9];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to send read measurement command");
        return -1;
    }

    gpioDelay(1); // Small delay after sending the command

    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        log_error("Failed to read sensor data");
        return -1;
    }

    // Validate CRC for CO2
    if (!validate_crc(buffer, 2, buffer[2])) {
        log_error("CO2 CRC check failed");
        return -1;
    }

    // Validate CRC for Temperature
    if (!validate_crc(buffer + 3, 2, buffer[5])) {
        log_error("Temperature CRC check failed");
        return -1;
    }

    // Validate CRC for Humidity
    if (!validate_crc(buffer + 6, 2, buffer[8])) {
        log_error("Humidity CRC check failed");
        return -1;
    }

    // Convert data
    data->co2 = (buffer[0] << 8) | buffer[1];
    data->temperature = -45 + ((buffer[3] << 8) | buffer[4]) / 65535.0 * 175;
    data->humidity = ((buffer[6] << 8) | buffer[7]) / 65535.0 * 100;

    return 0;
}

