#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define SAMPLE_INTERVAL_SEC 1
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sdp810(int i2c_handle, uint8_t *data);
int validate_crc(uint8_t data[], int len, uint8_t crc);
sensor_data_t process_sdp810_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SDP810 sensor
int read_sdp810(int i2c_handle, uint8_t *data) {
    char cmd[1] = {0x24}; // Trigger measurement command
    int result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(50); // Wait for measurement (at least 45ms)

    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    return 0;
}

// Validate CRC
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t polynomial = CRC_POLYNOMIAL;
    uint8_t crc_calculated = CRC_INIT;

    for (int i = 0; i < len; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ polynomial;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    if (crc_calculated != crc) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }

    return 0;
}

// Process SDP810 data
sensor_data_t process_sdp810_data(uint8_t *data) {
    sensor_data_t sensor_data;

    // Extract pressure
    int16_t raw_pressure = (data[0] << 8) | data[1];
    sensor_data.pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet

    // Extract temperature
    int16_t raw_temperature = (data[3] << 8) | data[4];
    sensor_data.temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

