    int who_am_i = i2cReadByteData(i2c_handle, ICP10110_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x41) {
        fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x41\n", who_am_i);
        return -1;
    }

    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, ICP10110_RESET, 0x80) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure measurement (example: continuous mode, 16x oversampling)
    if (i2cWriteByteData(i2c_handle, ICP10110_MEAS_CFG, 0x03) < 0) { // Pressure: continuous, 16x oversampling
        fprintf(stderr, "Error configuring pressure measurement\n");
        return -1;
