    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open file for logging
    fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();

        if (data.pressure != -1.0 && data.temperature != -1000.0) {
            log_data(data);
            printf("%s,%.2f,%.2f\n", __TIME__, data.pressure, data.temperature);
        } else {
            fprintf(stderr, "Skipping sample due to error\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

