#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Constants
#define I2C_ADDR 0x69
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 95000.0 // Pa
#define LED_ON_TIME 500 // ms
#define LED_OFF_TIME 500 // ms
#define LED_ON_TIME_FAST 100 // ms
#define LED_OFF_TIME_FAST 100 // ms
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, uint8_t *data);
float calculate_pressure(uint16_t raw_pressure);
float calculate_temperature(uint16_t raw_temperature);
int verify_crc(uint8_t data[], int len);
void control_led(float pressure);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function to read sensor data from I2C
int read_sensor_data(int i2c_handle, uint8_t *data) {
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate pressure in Pascals
float calculate_pressure(uint16_t raw_pressure) {
    // Conversion formula from datasheet (example, adjust as needed)
    return (float)raw_pressure * 10.0; // Example: 10 Pa per unit
}

// Function to calculate temperature in Celsius
float calculate_temperature(uint16_t raw_temperature) {
    // Conversion formula from datasheet (example, adjust as needed)
    return (float)raw_temperature * 0.1; // Example: 0.1 degrees Celsius per unit
}

// Function to verify CRC checksum
int verify_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31; // Polynomial X^8 + X^5 + X^4 + 1
            else
                crc = (crc << 1);
        }
    }

    if (crc != 0xFF) {
        return 0; // CRC check failed
    }
    return 1; // CRC check passed
}

// Function to control the LED based on pressure
void control_led(float pressure) {
    if (pressure < PRESSURE_THRESHOLD) {
        // 5 Hz pattern
        gpioWrite(GPIO_LED, 1);
        gpioDelay(LED_ON_TIME_FAST);
        gpioWrite(GPIO_LED, 0);
        gpioDelay(LED_OFF_TIME_FAST);
    } else {
        // 1 Hz pattern
        gpioWrite(GPIO_LED, 1);
        gpioDelay(LED_ON_TIME);
        gpioWrite(GPIO_LED, 0);
        gpioDelay(LED_OFF_TIME);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO_LED as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    uint8_t sensor_data[6];
    sensor_data_t sensor_values;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data) == 0) {
            // Verify CRC
            if (verify_crc(sensor_data, 2) && verify_crc(sensor_data + 2, 2)) {
                // Calculate pressure and temperature
                uint16_t raw_pressure = (sensor_data[0] << 8) | sensor_data[1];
                uint16_t raw_temperature = (sensor_data[3] << 8) | sensor_data[4];

                sensor_values.pressure = calculate_pressure(raw_pressure);
                sensor_values.temperature = calculate_temperature(raw_temperature);

                // Print sensor data
                printf("Pressure: %.2f Pa, Temperature: %.2f C\n", sensor_values.pressure, sensor_values.temperature);

                // Control LED
                control_led(sensor_values.pressure);
            } else {
                fprintf(stderr, "CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

