        fprintf(stderr, "Failed to open log file. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperatures
        int raw_ambient_temp = read_temperature(i2c_handle, AMBIENT_TEMP_REG);
        int raw_object_temp = read_temperature(i2c_handle, OBJECT_TEMP_REG);

        if (raw_ambient_temp >= 0 && raw_object_temp >= 0) {
            // Convert to Celsius
