        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read temperature from the sensor
int read_temperature(int handle, int reg) {
    int retries = 0;
    int raw_temp = -1;
    while (retries < MAX_RETRIES) {
        raw_temp = i2cReadWordData(handle, reg);
        if (raw_temp >= 0) {
            return raw_temp;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, raw_temp);
            gpioDelay(RETRY_DELAY_MS);
            retries++;
        }
    }
    return -1; // Indicate failure after all retries
}

// Convert raw temperature to Celsius
float convert_to_celsius(int raw_temp) {
    // Formula from MLX90614 datasheet
    return (raw_temp * 0.02) - 273.15;
}

// Log temperature to file
int log_temperature(float ambient_temp, float object_temp) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }
}

// Control fan based on object temperature
int control_fan(float object_temp) {
    if (object_temp > Hysteresis_Temp) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        printf("Fan ON\n");
    } else if (object_temp < (Hysteresis_Temp - 1)) { // Allow for some margin
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        printf("Fan OFF\n");
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

