#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define SERVER_PORT 8080
#define MAX_RETRIES 3

int i2c_handle;
int server_fd;

// Structure to hold temperature and humidity data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    gpioTerminate();
    exit(0);
}

// Function to read data from the SHT40 sensor
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    unsigned char buf[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        // Send measurement command
        if (i2cWriteByte(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retry
            continue;
        }

        gpioDelay(10); // Wait for measurement (at least 10ms)

        // Read 6 bytes of data
        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result == 6) {
            // Convert data
            unsigned short temp_raw = (buf[0] << 8) | buf[1];
            unsigned short hum_raw = (buf[3] << 8) | buf[4];

            *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
            *humidity = -6.0 + 125.0 * (float)hum_raw / 65535.0;

            // Clamp humidity to 0-100%
            if (*humidity < 0.0) *humidity = 0.0;
            if (*humidity > 100.0) *humidity = 100.0;

            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retry
        }
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to format the HTML page
char* format_html(float temperature, float humidity) {
    char *html = malloc(256); // Allocate memory for the HTML string
    if (html == NULL) {
        fprintf(stderr, "Failed to allocate memory for HTML.\n");
        return NULL;
    }
    snprintf(html, 256, 
             "HTTP/1.1 200 OK\r\n" 
             "Content-Type: text/html\r\n" 
             "Connection: close\r\n" 
             "\r\n" 
             "<!DOCTYPE html><html><head><title>SHT40 Sensor Data</title></head><body><h1>SHT40 Sensor Data</h1><p>Temperature: %.2f &deg;C</p><p>Humidity: %.2f %%</p></body></html>", 
             temperature, humidity);
    return html;
}

// Function to send the HTTP response
int send_http_response(int server_fd, const char *html) {
    struct sockaddr_in server_addr;
    socklen_t server_addr_len = sizeof(server_addr);

    // Get server address
    if (getsockname(server_fd, (struct sockaddr *)&server_addr, &server_addr_len) == -1) {
        perror("getsockname");
        return -1;
    }

    // Construct HTTP response
    char response[512];
    snprintf(response, sizeof(response), 
             "HTTP/1.1 200 OK\r\n" 
             "Content-Type: text/html\r\n" 
             "Connection: close\r\n" 
             "Server: SHT40-Server\r\n" 
             "Location: http://localhost:%d\r\n" 
             "\r\n", SERVER_PORT);

    // Send response
    if (send(server_fd, response, strlen(response), 0) == -1) {
        perror("send");
        return -1;
    }

    // Send HTML content
    if (send(server_fd, html, strlen(html), 0) == -1) {
        perror("send");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to port
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(SERVER_PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 5) < 0) {
        perror("listen");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", SERVER_PORT);

    // Main loop
    while (1) {
        // Accept connection
        int client_fd = accept(server_fd, (struct sockaddr *)&server_addr, &server_addr_len);
        if (client_fd < 0) {
            perror("accept");
            continue; // Continue listening for other connections
        }

        // Read sensor data
        float temperature, humidity;
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            // Format HTML
            char *html = format_html(temperature, humidity);
            if (html != NULL) {
                // Send HTTP response
                if (send_http_response(client_fd, html) != 0) {
                    fprintf(stderr, "Failed to send HTTP response.\n");
                }
                free(html); // Free allocated memory
            } else {
                fprintf(stderr, "Failed to format HTML.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        close(client_fd);
    }

    // Cleanup (should not reach here in normal operation due to the signal handler)
    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

