        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed.\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    fp = fopen(config.csv_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();

        // Write to CSV file
        if (write_to_csv(temperature) != 0) {
            fprintf(stderr, "Failed to write to CSV file.\n");
        }

        // Sleep for 5 seconds
        gpioSleep(PI_TIME_RELATIVE, config.sleep_seconds, 0);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.tmp102_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

// Read temperature from TMP102
float read_temperature() {
    int raw_temp;
    float temperature;

    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    // Convert raw temperature to Celsius
    temperature = (float)((raw_temp >> 4) * 0.0625);
    return temperature;
}

// Write temperature to CSV file
int write_to_csv(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write to CSV file
    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Failed to write to CSV file: %s\n", strerror(errno));
        return 1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

