#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define HDC2010_MEASUREMENT_CONFIG 0x0F
#define HDC2010_TEMP_MSB 0x00
#define HDC2010_TEMP_LSB 0x01
#define HDC2010_HUM_MSB 0x02
#define HDC2010_HUM_LSB 0x03

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold temperature and humidity data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
void process_sensor_data(uint16_t raw_temp, uint16_t raw_hum, sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the HDC2010 sensor
int configure_sensor() {
    // Configure for temperature and humidity measurement, 14-bit resolution
    uint8_t config_value = 0x00; // Default configuration
    int result = i2cWriteByteData(i2c_handle, HDC2010_MEASUREMENT_CONFIG, config_value);
    if (result < 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    uint8_t raw_data[4];
    int result;

    // Trigger measurement (optional, but good practice)
    uint8_t trigger_measurement = 0x01;
    result = i2cWriteByteData(i2c_handle, 0x0E, trigger_measurement);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 7ms)
    gpioDelay(10); // Wait 10ms

    // Read temperature data
    result = i2cReadI2CBlockData(i2c_handle, HDC2010_TEMP_MSB, (char *)raw_data, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Check for NAK (Not Available) status
    if (raw_data[0] == 0x00) {
        fprintf(stderr, "NAK received from sensor\n");
        return -1; // Indicate NAK
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temp = (raw_data[0] << 8) | raw_data[1];
    uint16_t raw_hum = (raw_data[2] << 8) | raw_data[3];

    process_sensor_data(raw_temp, raw_hum, data);

    return 0;
}

// Process raw sensor data and convert to Celsius and percentage relative humidity
void process_sensor_data(uint16_t raw_temp, uint16_t raw_hum, sensor_data_t *data) {
    data->temperature = ((float)raw_temp / 65536.0) * 165.0 - 40.0;
    data->humidity = ((float)raw_hum / 65536.0) * 100.0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

