#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define the I2C address of the SDP800-500Pa sensor
#define SDP800_I2C_ADDR 0x25

// Define the I2C bus number (usually 1 on Raspberry Pi)
#define I2C_BUS 1

// Define the measurement command (continuous measurement without averaging)
#define MEASUREMENT_COMMAND 0x362F

// Define the CRC-8 checksum polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variable to store the I2C handle
int i2c_handle = -1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read data from the SDP800 sensor
int read_sdp800(int i2c_handle, uint16_t *pressure, uint16_t *temperature) {
    char buf[6];
    int result;

    // Send the measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, MEASUREMENT_COMMAND); // Command register address is 0x00
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for the measurement to complete (at least 45ms)
    gpioDelay(45000); // 45ms

    // Read 6 bytes of data from the sensor
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 6); // Read from command register address 0x00
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Extract the pressure and temperature values from the buffer
    *pressure = (uint16_t)((buf[0] << 8) | buf[1]);
    *temperature = (uint16_t)((buf[3] << 8) | buf[4]);

    // Validate CRC-8 checksums
    uint8_t crc_pressure = buf[2];
    uint8_t crc_temperature = buf[5];

    uint8_t data_pressure[2] = {buf[0], buf[1]};
    uint8_t data_temperature[2] = {buf[3], buf[4]};

    uint8_t crc_calculated_pressure = 0;
    uint8_t crc_calculated_temperature = 0;

    crc_calculated_pressure = crc8(data_pressure, 2);
    crc_calculated_temperature = crc8(data_temperature, 2);

    if (crc_calculated_pressure != crc_pressure) {
        fprintf(stderr, "CRC check failed for pressure: calculated 0x%02X, received 0x%02X\n", crc_calculated_pressure, crc_pressure);
        return -1;
    }

    if (crc_calculated_temperature != crc_temperature) {
        fprintf(stderr, "CRC check failed for temperature: calculated 0x%02X, received 0x%02X\n", crc_calculated_temperature, crc_temperature);
        return -1;
    }

    return 0;
}

// Function to calculate the CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SDP800-500Pa sensor reader started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        uint16_t pressure, temperature;

        // Read data from the sensor
        if (read_sdp800(i2c_handle, &pressure, &temperature) == 0) {
            // Print the raw pressure and temperature values
            printf("Pressure: %u Pa, Temperature: %u \u00b0C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 500ms
        gpioDelay(500000); // 500ms
    }

    // The following lines will never be reached because of the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

