#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0 // CE0 or CE1
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define TARGET_TEMP_FILE "profile.txt"
#define SAMPLE_INTERVAL 1 // seconds

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static FILE *target_file;
static double integral = 0.0;
static double previous_error = 0.0;

// Function Prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void set_relay_duty_cycle(double duty_cycle);
void log_temperature(double temperature);
void load_target_temperature_profile();
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from MAX6675 via SPI
double read_temperature() {
    unsigned char data[2];
    int result;

    result = spiRead(spi_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -273.15; // Return absolute zero on error
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (data[0] << 8) | data[1];
    raw_temp = raw_temp >> 3; // Shift right by 3 bits
    double temperature = raw_temp * 0.25;

    // Check for fault conditions (MAX6675 fault bit)
    if (data[1] & 0x04) {
        fprintf(stderr, "MAX6675 Fault detected!\n");
        return -273.15; // Return absolute zero on fault
    }

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = KP * error + KI * integral + KD * derivative;
    previous_error = error;
    return output;
}

// Function to set the solid-state relay duty cycle
void set_relay_duty_cycle(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;
    gpioPWM(RELAY_GPIO, (int)(duty_cycle * 255.0));
}

// Function to log temperature to file
void log_temperature(double temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to load target temperature profile from file
void load_target_temperature_profile() {
    char line[256];
    double target_temp;
    int i = 0;

    target_file = fopen(TARGET_TEMP_FILE, "r");
    if (target_file == NULL) {
        fprintf(stderr, "Error opening target temperature file: %s\n", TARGET_TEMP_FILE);
        return;
    }

    while (fgets(line, sizeof(line), target_file) != NULL && running) {
        if (sscanf(line, "%lf", &target_temp) == 1) {
            if (i == 0) {
                setpoint = target_temp;
            } else {
                fprintf(stderr, "Warning: Invalid target temperature profile format. Using last valid value: %.2f\n", setpoint);
            }
        } else {
            fprintf(stderr, "Warning: Invalid target temperature value: %s", line);
        }
        i++;
    }

    fclose(target_file);
    if (i == 0) {
        fprintf(stderr, "Error: Could not load target temperature profile from %s. Using default value (25.0).\n", TARGET_TEMP_FILE);
        setpoint = 25.0;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for relay control
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(RELAY_GPIO, 1000); // Set PWM frequency to 1 kHz
    gpioSetPWMrange(RELAY_GPIO, 255); // Set PWM range to 0-255

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open target temperature file
    target_file = fopen(TARGET_TEMP_FILE, "r");
    if (target_file == NULL) {
        fprintf(stderr, "Error opening target temperature file: %s\n", TARGET_TEMP_FILE);
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Load initial target temperature
    load_target_temperature_profile();

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    // Stop PWM signal
    gpioPWM(RELAY_GPIO, 0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Close target temperature file
    fclose(target_file);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    double target_temp = setpoint;
    double actual_temp;
    double pid_output;
    double duty_cycle;

    while (running) {
        actual_temp = read_temperature();
        if (actual_temp < -200.0) {
            fprintf(stderr, "Error reading temperature, skipping PID calculation.\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        pid_output = calculate_pid(target_temp, actual_temp);
        duty_cycle = pid_output; // Scale PID output to 0-1

        set_relay_duty_cycle(duty_cycle);
        log_temperature(actual_temp);

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

