        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read temperature from DS18B20 sensor
float read_temperature() {
    char filepath[100];
    FILE *fp;
    char buffer[256];
    float temperature = -1000.0; // Initialize to an invalid value
    int retries = 0;

    snprintf(filepath, sizeof(filepath), "/sys/bus/w1/devices/28-%02d-%02d-%02d-%02d-%02d-%02d/w1_slave", 2021, 12, 31, 0, 0, 0); // Dummy sensor ID
    fp = fopen(filepath, "r");
    if (fp == NULL) {
        perror("Error opening w1_slave file");
        return -1000.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Error reading w1_slave file");
        fclose(fp);
        return -1000.0;
    }

    if (fgets(buffer + 64, sizeof(buffer) - 64, fp) == NULL) {
        perror("Error reading w1_slave file");
        fclose(fp);
        return -1000.0;
    }

    fclose(fp);

    // Check CRC
    if (strncmp(buffer, "YES", 3) != 0) {
        fprintf(stderr, "CRC check failed\n");
        return -1000.0;
    }

    // Extract temperature
    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found\n");
        return -1000.0;
    }

    long temp_reading = strtol(temp_str + 2, NULL, 10);
    temperature = (float)temp_reading / 1000.0;

    return temperature;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, PIDGains gains, float *integral, float *previous_error) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = gains.Kp * error + gains.Ki * (*integral) + gains.Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm(float duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    gpioPWM(HEATER_GPIO, (int)duty_cycle);
}

// Function to set relay state
void set_relay(float state) {
    gpioWrite(RELAY_GPIO, (int)state);
}

// Function to log data to file
void log_data(float temperature, float setpoint, float pid_output, float pwm_duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, temperature, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to clean up resources before exiting
void cleanup() {
    set_relay(0.0); // Turn off relay
    set_pwm(0.0);   // Set PWM to 0
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki>\n", argv[0]);
        return 1;
    }

    float setpoint = atof(argv[1]);
    PIDGains gains = {atof(argv[2]), atof(argv[3]), 0.0}; // Kd is not provided, set to 0

    if (initialize() != 0) {
        return 1;
    }

    float integral = 0.0;
    float previous_error = 0.0;
    float temperature, pid_output, pwm_duty_cycle;
    int retries;

    while (running) {
        retries = 0;
        do {
            temperature = read_temperature();
            if (temperature < -900) {
                fprintf(stderr, "Error reading temperature, retrying...\n");
                retries++;
                sleep(1); // Wait before retrying
            } else {
                break; // Exit retry loop if temperature reading is valid
            }
        } while (retries < MAX_RETRIES);

        if (temperature < -900) {
            fprintf(stderr, "Failed to read temperature after %d retries. Heater will be turned off.\n", MAX_RETRIES);
            set_relay(0.0);
            set_pwm(0.0);
        } else {
            pid_output = calculate_pid(setpoint, temperature, gains, &integral, &previous_error);
            pwm_duty_cycle = pid_output; // Assuming PID output is directly the PWM duty cycle
            set_pwm(pwm_duty_cycle);
            set_relay(1.0); // Turn on heater
            log_data(temperature, setpoint, pid_output, pwm_duty_cycle);
        }

        sleep(5);
    }

    cleanup();
    return 0;
}

