#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_DELAY_MS 80
#define RETRY_DELAY_MS 10
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init(int i2c_handle);
int aht20_trigger_measurement(int i2c_handle);
int aht20_read_data(int i2c_handle, uint8_t *data);
float aht20_calculate_humidity(uint8_t *data);
void control_relay(int gpio_pin, float humidity);
void log_humidity(float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float humidity;
    time_t timestamp;
} SensorData;

// Function to initialize the AHT20 sensor
int aht20_init(int i2c_handle) {
    // No initialization needed for AHT20, but check if it's present
    // by reading the first byte.  If it's 0, it's not present.
    uint8_t data[1];
    if (i2cReadDevice(i2c_handle, data, 1) != 1) {
        fprintf(stderr, "Error: AHT20 sensor not found on I2C bus.\n");
        return -1;
    }
    return 0;
}

// Function to trigger a measurement on the AHT20 sensor
int aht20_trigger_measurement(int i2c_handle) {
    uint8_t command[3] = {0xAC, 0x33, 0x00};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, command, 3) == 3) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to trigger measurement (attempt %d).\n", retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Error: Failed to trigger measurement after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read data from the AHT20 sensor
int aht20_read_data(int i2c_handle, uint8_t *data) {
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cReadDevice(i2c_handle, data, 6) == 6) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to read data (attempt %d).\n", retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Error: Failed to read data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

