    // Main loop
    while (!terminate) {
        retry_count = 0;
        while (retry_count < MAX_RETRIES) {
            if (aht20_trigger_measurement(i2c_handle) == 0) {
                gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement

                if (aht20_read_data(i2c_handle, data) == 0) {
                    humidity = aht20_calculate_humidity(data);
                    log_humidity(humidity);
                    control_relay(GPIO_RELAY, humidity);
                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Error: Failed to read sensor data.\n");
                }
            } else {
                fprintf(stderr, "Error: Failed to trigger measurement.\n");
            }
            retry_count++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }

        if (retry_count == MAX_RETRIES) {
            fprintf(stderr, "Error: Failed to read sensor data after %d retries.\n", MAX_RETRIES);
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off on exit
    gpioTerminate();

    return 0;
