#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HTU21D_ADDR 0x40
#define MEASURE_CMD 0xE5
#define SERVER_URL "http://api.example.com/humidity"
#define POLL_INTERVAL 60 // seconds

int i2c_handle;
int sockfd;

// Function to read humidity from HTU21D sensor
float read_humidity() {
    unsigned char buf[3];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result != 0) {
        syslog(LOG_ERR, "I2C write error: %d", result);
        return -1.0;
    }

    // Wait for measurement (at least 50ms)
    gpioDelay(50000); // 50ms

    // Read 3 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (result != 3) {
        syslog(LOG_ERR, "I2C read error: %d", result);
        return -1.0;
    }

    // Check CRC
    unsigned short humidity_raw = (buf[0] << 8) | buf[1];
    unsigned short crc = buf[2];

    unsigned char crc_calculated[2];
    crc_calculated[0] = humidity_raw & 0xFF;
    crc_calculated[1] = (humidity_raw >> 8) & 0xFF;

    unsigned char data[2] = {0x00, 0x00};
    data[0] = 0x00;
    data[1] = 0x00;

    int crc_result = i2cWriteDevice(i2c_handle, (char *)data, 2);
    if (crc_result != 2) {
        syslog(LOG_ERR, "I2C CRC write error: %d", crc_result);
        return -1.0;
    }

    unsigned char crc_calculated_buf[2];
    crc_calculated_buf[0] = crc_calculated[0];
    crc_calculated_buf[1] = crc_calculated[1];

    result = i2cReadDevice(i2c_handle, (char *)crc_calculated_buf, 2);
    if (result != 2) {
        syslog(LOG_ERR, "I2C CRC read error: %d", result);
        return -1.0;
    }

    unsigned short crc_calculated_value = (crc_calculated_buf[0] << 8) | crc_calculated_buf[1];

    if (crc != crc_calculated_value) {
        syslog(LOG_ERR, "CRC mismatch: calculated 0x%04X, received 0x%04X", crc_calculated_value, crc);
        return -1.0;
    }

    // Convert raw humidity to percentage
    float humidity = -6.0 + 125.0 * (humidity_raw / 65536.0);
    return humidity;
}

// Function to post humidity data to server
int post_humidity(float humidity) {
    struct sockaddr_in server_addr;
    char json_data[50];
    int bytes_sent;

    // Create JSON data
    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed");
        return -1;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80); // Assuming HTTP port 80
    if (inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Connection failed");
        close(sockfd);
        return -1;
    }

    // Send data
    bytes_sent = send(sockfd, json_data, strlen(json_data), 0);
    if (bytes_sent < 0) {
        syslog(LOG_ERR, "Send failed");
        close(sockfd);
        return -1;
    }

    // Close socket
    close(sockfd);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    openlog("humidity_monitor", LOG_PID, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %d", i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Humidity monitor started");

    while (1) {
        float humidity = read_humidity();
        if (humidity >= 0) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (post_humidity(humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        sleep(POLL_INTERVAL);
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return 0;
}

