#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE_PATH "motion_log.csv"
#define MAX_LOG_FILE_SIZE 1048576 // 1MB

// Global variables
static int i2c_handle_tmp117 = -1;
static int i2c_handle_aht20 = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_tmp117(float *temperature);
int read_aht20(float *humidity);
int read_pir();
void log_data(float temperature, float humidity, int motion_detected);
void signal_handler(int signal);
void cleanup();
char* get_timestamp();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize I2C
int init_i2c() {
    i2c_handle_tmp117 = i2cOpen(1, TMP117_ADDR, 0); // Bus 1, TMP117 address
    if (i2c_handle_tmp117 < 0) {
        fprintf(stderr, "Error opening I2C device for TMP117: %s\n", strerror(errno));
        return -1;
    }

    i2c_handle_aht20 = i2cOpen(1, AHT20_ADDR, 0); // Bus 1, AHT20 address
    if (i2c_handle_aht20 < 0) {
        fprintf(stderr, "Error opening I2C device for AHT20: %s\n", strerror(errno));
        i2cClose(i2c_handle_tmp117);
        return -1;
    }

    return 0;
}

// Read temperature from TMP117
int read_tmp117(float *temperature) {
    char buf[2];
    int result;

    // Read temperature register (0x00)
    result = i2cReadDevice(i2c_handle_tmp117, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature from TMP117: %s\n", strerror(errno));
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = raw_temp * 0.0078125;

    return 0;
}

// Read humidity from AHT20
int read_aht20(float *humidity) {
    char buf[6];
    int result;

    // Trigger measurement (0x00, 0x30, 0x00)
    buf[0] = 0x00;
    buf[1] = 0x30;
    buf[2] = 0x00;
    result = i2cWriteDevice(i2c_handle_aht20, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error triggering AHT20 measurement: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (at least 80ms)
    gpioDelay(100000); // 100ms

    // Read 6 bytes of data (0x00, 0x00, 0x00, 0x00, 0x00, 0x00)
    result = i2cReadDevice(i2c_handle_aht20, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading humidity from AHT20: %s\n", strerror(errno));
        return -1;
    }

    // Validate checksum (not implemented for brevity)

    // Convert raw data to humidity (%)
    uint32_t raw_humidity = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | ((uint32_t)buf[3] >> 4);
    *humidity = raw_humidity * 100.0 / 0x100000;

    return 0;
}

// Read motion from PIR sensor
int read_pir() {
    return gpioRead(PIR_GPIO);
}

// Log data to CSV file
void log_data(float temperature, float humidity, int motion_detected) {
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp.\n");
        return;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
}

// Get current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Continuing without I2C sensors.\n");
    }

    // Open log file
    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    }
    fflush(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int motion_detected;
    int retry;

    // Main loop
    while (!terminate) {
        retry = 0;
        motion_detected = 0;

        // Read sensors with retries
        while (retry < RETRY_COUNT) {
            if (read_tmp117(&temperature) == 0 && read_aht20(&humidity) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Sensor read failed, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retry++;
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensors after multiple retries.\n");
        } else {
            motion_detected = read_pir();
        }

        // Log data
        log_data(temperature, humidity, motion_detected);

        // Check log file size and create new file if necessary
        fseek(log_file, 0, SEEK_END);
        file_size = ftell(log_file);
        if (file_size > MAX_LOG_FILE_SIZE) {
            fclose(log_file);
            log_file = fopen(LOG_FILE_PATH, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
                cleanup();
                return 1;
            }
            fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
            fflush(log_file);
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

