#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_motor();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, stopping program...\n", signal);
        program_running = 0;
        stop_motor(); // Stop the motor
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to read the rain sensor
int read_rain_sensor() {
    int rain_detected = 0;
    int sensor_value = gpioRead(RAIN_SENSOR_PIN);

    if (sensor_value == 0) { // Active-low logic
        rain_detected = 1;
    }

    return rain_detected;
}

// Function to close the window
void close_window() {
    printf("Closing window...\n");
    gpioWrite(MOTOR_IN1_PIN, 1); // Set IN1 HIGH
    gpioWrite(MOTOR_IN2_PIN, 0); // Set IN2 LOW
    gpioPWM(MOTOR_ENA_PIN, 100); // Set ENA to 50% (adjust as needed)
    gpioDelay(5000); // Run for 5 seconds
    stop_motor();
    printf("Window closed.\n");
}

// Function to stop the motor
void stop_motor() {
    printf("Stopping motor...\n");
    gpioWrite(MOTOR_IN1_PIN, 0); // Set IN1 LOW
    gpioWrite(MOTOR_IN2_PIN, 0); // Set IN2 LOW
    gpioPWM(MOTOR_ENA_PIN, 0); // Set ENA LOW
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set PWM range for ENA pin (0-255)
    gpioSetPWMrange(MOTOR_ENA_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected) {
            printf("Rain detected!\n");
            close_window();
        }

        gpioDelay(2000); // Poll every 2 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();

    return 0;
}

