#define LOAD_THRESHOLD_0 0
#define LOAD_THRESHOLD_1 50
#define LOAD_THRESHOLD_2 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_cpu_load();
void set_led_color(int red, int green, int blue);
void cleanup(int signal);

// Signal handler for SIGINT and SIGTERM
void cleanup(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signal);
    set_led_color(0, 0, 0); // Turn off LED
    wiringPiSetup(); // Reinitialize wiringPi to allow call() to work
    call(NULL, NULL, NULL); // Call the wiringPi API to stop PWM
    exit(0);
}

// Function to read CPU load from /proc/stat
int read_cpu_load() {
    FILE *fp;
    char line[256];
    int user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    int prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    double cpu_usage;
    int load;

    // Read the first line of /proc/stat
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1; // Indicate error
    }
    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Error reading /proc/stat");
        fclose(fp);
        return -1; // Indicate error
    }
    fclose(fp);

    // Parse the line
    if (sscanf(line, "cpu  %d %d %d %d %d %d %d %d %d %d",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        return -1; // Indicate error
    }

    // Store previous values for the next iteration
    prev_user = user;
    prev_nice = nice;
    prev_system = system;
    prev_idle = idle;
    prev_iowait = iowait;
    prev_irq = irq;
    prev_softirq = softirq;
    prev_steal = steal;
    prev_guest = guest;
    prev_guest_nice = guest_nice;

    // Calculate CPU usage
    int prev_idle_total = prev_idle + prev_iowait;
    int current_idle_total = idle + iowait;
    int prev_non_idle = prev_user + prev_nice + prev_system + prev_irq + prev_softirq + prev_steal;
    int current_non_idle = user + nice + system + irq + softirq + steal;
    int prev_total = prev_idle_total + prev_non_idle;
    int current_total = current_idle_total + current_non_idle;

    cpu_usage = (double)(current_total - prev_total) / (double)(current_total - prev_total);

    // Calculate load
    load = (int)(cpu_usage * 100.0);

    return load;
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    // Clamp values to 0-255 range
    red = (red < 0) ? 0 : (red > 255) ? 255 : red;
    green = (green < 0) ? 0 : (green > 255) ? 255 : green;
    blue = (blue < 0) ? 0 : (blue > 255) ? 255 : blue;

    // Convert PWM values to duty cycle (0-1023)
    int red_duty = (int)(((double)red / 255.0) * PWM_RANGE);
    int green_duty = (int)(((double)green / 255.0) * PWM_RANGE);
    int blue_duty = (int)(((double)blue / 255.0) * PWM_RANGE);

    // Set PWM values for each channel
    pwmWrite(RED_PIN, red_duty);
    pwmWrite(GREEN_PIN, green_duty);
    pwmWrite(BLUE_PIN, blue_duty);
}

int main() {
    int load;
    int previous_load = 0;
    int load_range = 0;
    int red, green, blue;

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Configure GPIO pins as PWM outputs
    pinMode(RED_PIN, PWM_OUTPUT);
    pinMode(GREEN_PIN, PWM_OUTPUT);
    pinMode(BLUE_PIN, PWM_OUTPUT);

    // Set PWM range
    pwmSetRange(PWM_RANGE);

    // Set PWM mode to mark:space
    pwmSetMode(PWM_MODE_MS);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    printf("CPU Load-Based RGB LED Control (Ctrl+C to exit)\n");

    while (program_running) {
        // Read CPU load
        load = read_cpu_load();

        if (load == -1) {
            fprintf(stderr, "Error reading CPU load, exiting...\n");
            break;
        }

        // Calculate load range
        if (load > LOAD_THRESHOLD_2) {
            load_range = 100;
        } else if (load > LOAD_THRESHOLD_1) {
            load_range = 50;
        } else if (load > LOAD_THRESHOLD_0) {
            load_range = 0;
        } else {
            load_range = 0; // Default to 0 if below any threshold
        }

        // Map load to RGB color gradient
        if (load_range == 100) {
            red = 255;
            green = 0;
            blue = 0;
        } else if (load_range == 50) {
            red = 255;
            green = 255;
            blue = 0;
        } else {
            red = 0;
            green = 255;
            blue = 0;
        }

        // Set LED color
        set_led_color(red, green, blue);

        // Store current load for next iteration
        previous_load = load;

        // Wait 500ms
        delay(500);
    }

    // Cleanup and exit
    cleanup(0);

    return 0;
}

