// UDP server address and port
#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000

// Global variables
int i2c_handle;
int udp_socket;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int init_i2c();
int read_calibration_data(struct bmp280_calib_data *calib);
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature, struct bmp280_calib_data calib);
double compensate_pressure(int32_t raw_pressure, int32_t t_fine, struct bmp280_calib_data calib);
int init_udp_socket();
int send_udp_packet(const char *json_data);
void signal_handler(int signal);
void cleanup();

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from an I2C register
int read_registers(int handle, uint8_t reg, char *buf, int len) {
    int result = i2cReadI2CBlockData(handle, reg, buf, len);
    if (result < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // Bus 1, address 0x76, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Set the BMP280 to forced mode
    if (write_register(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        cleanup();
        return -1;
    }

    // Read calibration data
    if (read_calibration_data(&calib) < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        cleanup();
        return -1;
    }

    return 0;
}

// Read calibration data from the BMP280
int read_calibration_data(struct bmp280_calib_data *calib) {
    char buf[26];
    if (read_registers(i2c_handle, BMP280_REG_CALIB_00, buf, 26) < 0) {
        return -1;
    }

    calib->dig_T1 = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    calib->dig_T2 = (int16_t)buf[2] | ((int16_t)buf[3] << 8);
    calib->dig_T3 = (int16_t)buf[4] | ((int16_t)buf[5] << 8);
    calib->dig_P1 = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);
    calib->dig_P2 = (int16_t)buf[8] | ((int16_t)buf[9] << 8);
    calib->dig_P3 = (int16_t)buf[10] | ((int16_t)buf[11] << 8);
    calib->dig_P4 = (int16_t)buf[12] | ((int16_t)buf[13] << 8);
    calib->dig_P5 = (int16_t)buf[14] | ((int16_t)buf[15] << 8);
    calib->dig_P6 = (int16_t)buf[16] | ((int16_t)buf[17] << 8);
    calib->dig_P7 = (int16_t)buf[18] | ((int16_t)buf[19] << 8);
    calib->dig_P8 = (int16_t)buf[20] | ((int16_t)buf[21] << 8);
    calib->dig_P9 = (int16_t)buf[22] | ((int16_t)buf[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from the BMP280
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    char buf[6];

    if (read_registers(i2c_handle, BMP280_REG_PRESS_MSB, buf, 6) < 0) {
        return -1;
    }

    *pressure = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | ((int32_t)buf[2] >> 4);
    *temperature = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | ((int32_t)buf[5] >> 4);

    return 0;
}

// Compensate temperature using calibration data
double compensate_temperature(int32_t raw_temperature, struct bmp280_calib_data calib) {
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using calibration data
double compensate_pressure(int32_t raw_pressure, int32_t t_fine, struct bmp280_calib_data calib) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return p;
}

// Initialize UDP socket
int init_udp_socket() {
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating socket\n");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        close(udp_socket);
        return -1;
    }

    return 0;
}

// Send UDP packet
int send_udp_packet(const char *json_data) {
    if (sendto(udp_socket, json_data, strlen(json_data), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error sending UDP packet\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Initialize UDP socket
    if (init_udp_socket() < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;
        double temperature, pressure;

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Error reading raw data\n");
            continue; // Continue to the next iteration
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature, calib);
        pressure = compensate_pressure(raw_pressure, (int32_t)((temperature * 5120.0)), calib);

        // Format data into JSON string
        char json_data[100];
        snprintf(json_data, sizeof(json_data), "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);

        // Send UDP packet
        if (send_udp_packet(json_data) < 0) {
            fprintf(stderr, "Error sending UDP packet\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

