#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define SPI_MODE 0
#define FAN_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 255
#define BUFFER_SIZE 20

// Temperature thresholds and duty cycle mapping
#define TEMP_THRESHOLD_1 25.0
#define TEMP_THRESHOLD_2 40.0
#define TEMP_THRESHOLD_3 60.0

#define DUTY_CYCLE_0 0
#define DUTY_CYCLE_1 127.5 // 50% of 255
#define DUTY_CYCLE_2 191.25 // 75% of 255
#define DUTY_CYCLE_3 255

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_max31855(int spi_handle, float *temperature);
int calculate_duty_cycle(float temperature);
int set_pwm_duty_cycle(int gpio, int duty_cycle);
int store_data(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature) {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1;
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -1;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1;
    }

    // Extract temperature data (bits 3-18, signed 16-bit integer)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 3;

    // Convert to Celsius (each bit is 0.25 degrees)
    *temperature = raw_temp * 0.25;

    return 0;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    if (temperature < TEMP_THRESHOLD_1) {
        return DUTY_CYCLE_0;
    } else if (temperature < TEMP_THRESHOLD_2) {
        // Linear ramp from 0% to 50%
        return (int)(((temperature - TEMP_THRESHOLD_1) / (TEMP_THRESHOLD_2 - TEMP_THRESHOLD_1)) * PWM_RANGE);
    } else if (temperature < TEMP_THRESHOLD_3) {
        // Steeper ramp from 50% to 200%
        float temp_diff = temperature - TEMP_THRESHOLD_2;
        float duty_cycle_diff = (temp_diff / (TEMP_THRESHOLD_3 - TEMP_THRESHOLD_2)) * (DUTY_CYCLE_2 - DUTY_CYCLE_1);
        return (int)(DUTY_CYCLE_1 + duty_cycle_diff);
    } else {
        return DUTY_CYCLE_3;
    }
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

// Function to store data in circular buffer
int store_data(float temperature, int duty_cycle) {
    temperature_buffer[buffer_index] = temperature;
    int duty_cycle_int = (int)duty_cycle; // Cast to int for storage
    temperature_buffer[buffer_index + 1] = duty_cycle_int; // Store duty cycle as integer
    buffer_index = (buffer_index + 2) % BUFFER_SIZE; // Increment index and wrap around
    return 0;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Data Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = i;
        if (i > 0) {
            index = (i - 1 + BUFFER_SIZE) % BUFFER_SIZE; // Correct index for previous entry
        }
        float temp = temperature_buffer[index];
        int duty_cycle = temperature_buffer[index + 1];
        printf("Timestamp: %ld, Temperature: %.2f, Duty Cycle: %d\n", index, temp, duty_cycle);
    }
    printf("--- End Log ---\n\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_max31855(spi_handle, &temperature) == 0) {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set PWM duty cycle
            if (set_pwm_duty_cycle(FAN_GPIO, duty_cycle) == 0) {
                // Store data
                store_data(temperature, duty_cycle);

                // Print temperature and duty cycle
                printf("Temperature: %.2f, Duty Cycle: %d\n", temperature, duty_cycle);
            } else {
                fprintf(stderr, "Failed to set PWM duty cycle\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Stop PWM
    set_pwm_duty_cycle(FAN_GPIO, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Print buffer
    print_buffer();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

