#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MAX31865_FAULT_REG 0x00000001
#define MAX31865_RTD_MSB_REG 0x00000002
#define MAX31865_RTD_LSB_REG 0x00000003
#define MAX31865_CONFIG_REG 0x00000004
#define MAX31865_CONFIG_VALUE 0xC2 // 3-wire, bias enabled
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int configure_max31865();
int read_max31865_data(uint8_t *data);
float calculate_temperature(uint16_t rtd_value);
int log_data(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int max31865_config_value;
} config_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, default flags
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Configure MAX31865
int configure_max31865() {
    uint8_t config_data[2];
    config_data[0] = (MAX31865_CONFIG_REG >> 8) & 0xFF;
    config_data[1] = MAX31865_CONFIG_REG & 0xFF;

    int result = spiWrite(spi_handle, config_data, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read data from MAX31865
int read_max31865_data(uint8_t *data) {
    int result = spiRead(spi_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from MAX31865: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate temperature using Callendar-Van Dusen equation
float calculate_temperature(uint16_t rtd_value) {
    float rtd_resistance = (float)rtd_value * 400.0 / 32768.0; // Convert RTD value to resistance (assuming 400 ohm reference resistor)
    float temperature = (rtd_resistance - 100.0) / 0.385; // Callendar-Van Dusen equation for Pt100
    return temperature;
}

// Log data to file
int log_data(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Configure MAX31865
    if (configure_max31865() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Main loop
    uint8_t data[4];
    uint16_t rtd_value;
    float temperature;
    int fault;

    while (!terminate) {
        // Read data from MAX31865
        if (read_max31865_data(data) == 0) {
            // Extract RTD value
            rtd_value = (data[2] << 8) | data[3];

            // Check for fault
            fault = data[0] & 0x07; // Extract fault bits

            if (fault) {
                fprintf(stderr, "Fault detected: %d\n", fault);
                fprintf(log_file, "Fault detected: %d\n", fault);
                fflush(log_file);
            } else {
                // Calculate temperature
                temperature = calculate_temperature(rtd_value);

                // Log data
                log_data(temperature);
                printf("Temperature: %.2f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            fprintf(log_file, "Error reading sensor data\n");
            fflush(log_file);
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

