double calculate_temperature(int raw_temp) {
    long x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
