#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "fan_log.txt"
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define DUTY_MIN 0
#define DUTY_MAX 255

static volatile int running = 1;

// Function to read the CPU temperature from the file
float read_temperature() {
    FILE *fp;
    char buffer[10];
    int temp_milli_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1.0; // Indicate error
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading temperature file: %s\n", strerror(errno));
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);

    temp_milli_celsius = atoi(buffer);
    if (temp_milli_celsius == 0 && errno == EINVAL) {
        fprintf(stderr, "Error converting temperature to integer\n");
        return -1.0;
    }

    return (float)temp_milli_celsius / 1000.0;
}

// Function to map the temperature to a duty cycle
int map_temperature_to_duty(float temperature) {
    if (temperature < TEMP_MIN) {
        return DUTY_MIN;
    } else if (temperature > TEMP_MAX) {
        return DUTY_MAX;
    } else {
        // Linear mapping
        return (int)(((temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * (DUTY_MAX - DUTY_MIN) + DUTY_MIN);
    }
}

// Function to set the PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    if (gpioPWM(PWM_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to log the data to a file
int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f°C, Duty Cycle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle);

    fclose(fp);
    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully...\n");
        running = 0;
    }
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read temperature
        temperature = read_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Consider implementing a retry mechanism here
            sleep(5);
            continue; // Skip to the next iteration
        }

        // Map temperature to duty cycle
        duty_cycle = map_temperature_to_duty(temperature);

        // Set PWM duty cycle
        if (set_pwm_duty_cycle(duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle, exiting.\n");
            running = 0; // Exit the loop if PWM setting fails
            break;
        }

        // Log data
        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, but continuing.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Stop the fan
    set_pwm_duty_cycle(0);

    // Terminate pigpio
    gpioTerminate();

    printf("Fan control program stopped.\n");

    return 0;
}

