#include <unistd.h>
#include <wiringPiI2C.h>
#include <wiringPi.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define BMP180_OSS 3

// Global variables
static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t program_running = 1;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature();
int read_raw_pressure();
double calculate_temperature(int ut);
double calculate_pressure(int up, int ut);
bool check_breach(double temperature, double pressure);
void log_breach(double temperature, double pressure);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(BMP180_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    ac1 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC1);
    ac2 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC2);
    ac3 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC3);
    ac4 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC4);
    ac5 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC5);
    ac6 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC6);
    b1 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_B1);
    b2 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_B2);
    mb = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MB);
    mc = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MC);
    md = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MD);

    // Check for errors during calibration data read
    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature() {
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x2E);
    delay(5); // Wait 4.5ms
    int msb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_LSB);
    int xlsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_XLSB);

    if (msb == -1 || lsb == -1 || xlsb == -1) {
        fprintf(stderr, "Error reading raw temperature data: %s\n", strerror(errno));
        return -1;
    }

    return (msb << 8) | (lsb << 6) | (xlsb >> 2);
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure() {
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6));
    delay(2 + (3 << BMP180_OSS)); // Wait for conversion

    int msb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_LSB);
    int xlsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_XLSB);

    if (msb == -1 || lsb == -1 || xlsb == -1) {
        fprintf(stderr, "Error reading raw pressure data: %s\n", strerror(errno));
        return -1;
    }

    return (msb << 16 | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int ut) {
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int up, int ut) {
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    int32_t x3 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x4 = ((int32_t)ac2 * b6) >> 11;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    uint32_t x1_pressure = ((uint32_t)ac3 * b6) >> 13;
    uint32_t x2_pressure = ((uint32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t x3_pressure = ((x1_pressure + x2_pressure + 2) >> 2);
    uint32_t b4 = ((uint32_t)ac4 * (x3_pressure + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);

    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1_pressure = (p >> 8) * (p >> 8);
    x1_pressure = (x1_pressure * 3038) >> 16;
    x2_pressure = (-7357 * p) >> 16;
    double pressure = p + ((x1_pressure + x2_pressure + 3791) >> 4);

    return pressure;
}

// Function to check if a breach has occurred
bool check_breach(double temperature, double pressure) {
    return (temperature > 30.0 || pressure < 950.0);
}

// Function to log a breach to a file
void log_breach(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Temperature: %.2f C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to close I2C and file
void cleanup() {
    if (i2c_fd != -1) {
        // No explicit I2C close function in wiringPi, but we can reset the device.
        // wiringPiI2CWrite(i2c_fd, 0); // Attempt to reset the device
        i2c_fd = -1; // Mark as closed
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() == -1) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("BMP180 breach monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int ut = read_raw_temperature();
        int up = read_raw_pressure();

        if (ut != -1 && up != -1) {
            double temperature = calculate_temperature(ut);
            double pressure = calculate_pressure(up, ut);

            if (check_breach(temperature, pressure)) {
                log_breach(temperature, pressure);
                printf("Breach detected! Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 1 second.\n");
        }

        delay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

