typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int bmp180_fd;
bmp180_calibration_data_t calibration_data;
circular_buffer_t buffer;
bool running = true;

// Function prototypes
int init_i2c();
int read_calibration_data(bmp180_calibration_data_t *cal);
