    cal->ac2 = wiringPiI2CReadReg16(bmp180_fd, BMP180_REG_CAL_AC2);
    cal->ac3 = wiringPiI2CReadReg16(bmp180_fd, BMP180_REG_CAL_AC3);
    cal->ac4 = wiringPiI2CReadReg16(bmp180_fd, BMP180_REG_CAL_AC4);
    cal->ac5 = wiringPiI2CReadReg16(bmp180_fd, BMP180_REG_CAL_AC5);
    cal->ac6 = wiringPiI2CReadReg16(bmp180_fd, BMP180_REG_CAL_AC6);
    cal->b1 = wiringPiI2CReadReg16(bmp180_fd, BMP180_REG_CAL_B1);
    cal->b2 = wiringPiI2CReadReg16(bmp180_fd, BMP180_REG_CAL_B2);
    cal->mb = wiringPiI2CReadReg16(bmp180_fd, BMP180_REG_CAL_MB);
    cal->mc = wiringPiI2CReadReg16(bmp180_fd, BMP180_REG_CAL_MC);
    cal->md = wiringPiI2CReadReg16(bmp180_fd, BMP180_REG_CAL_MD);

    if (cal->ac1 == -1 || cal->ac2 == -1 || cal->ac3 == -1 || cal->ac4 == -1 ||
        cal->ac5 == -1 || cal->ac6 == -1 || cal->b1 == -1 || cal->b2 == -1 ||
        cal->mb == -1 || cal->mc == -1 || cal->md == -1) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temp) {
    wiringPiI2CWriteReg8(bmp180_fd, BMP180_REG_CONTROL, 0x2E);
    delay(5); // Wait 4.5ms
    *raw_temp = wiringPiI2CReadReg16(bmp180_fd, BMP180_REG_MSB);
    if (*raw_temp == -1) {
        fprintf(stderr, "Error reading raw temperature: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure) {
    wiringPiI2CWriteReg8(bmp180_fd, BMP180_REG_CONTROL, 0x34 + (OSS << 6));
    delay(2 + (3 << OSS)); // Wait for conversion

    int msb = wiringPiI2CReadReg8(bmp180_fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(bmp180_fd, BMP180_REG_LSB);
    int xlsb = wiringPiI2CReadReg8(bmp180_fd, BMP180_REG_XLSB);

    if (msb == -1 || lsb == -1 || xlsb == -1) {
        fprintf(stderr, "Error reading raw pressure: %s\n", strerror(errno));
        return -1;
    }

    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

