float calculate_temperature(int raw_temp, bmp180_calibration_data_t cal) {
    long X1 = ((long)raw_temp - (long)cal.ac6) * ((long)cal.ac5) / pow(2, 15);
    long X2 = ((long)cal.mc * pow(2, 11)) / (X1 + cal.md);
    long B5 = X1 + X2;
    float temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Calculate pressure in Pascals
float calculate_pressure(int raw_pressure, int raw_temp, bmp180_calibration_data_t cal) {
    long X1 = ((long)raw_temp - (long)cal.ac6) * ((long)cal.ac5) / pow(2, 15);
    long X2 = ((long)cal.mc * pow(2, 11)) / (X1 + cal.md);
