    long p;
    if (B7 < 0x80000000) {
        p = (B7 * 2) / B4;
    } else {
        p = (B7 / B4) * 2;
    }

    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);
    float pressure = p + (X1 + X2 + 3791) / pow(2, 4);
    return pressure;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get data from the circular buffer
sensor_data_t get_from_buffer(circular_buffer_t *buffer, int index) {
    if (index < 0 || index >= buffer->count) {
        fprintf(stderr, "Error: Index out of bounds\n");
        sensor_data_t empty_data = {0, 0.0, 0.0};
        return empty_data;
    }
    int actual_index = (buffer->head - buffer->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->data[actual_index];
}

// Control the cooling fan
void control_fan(float temperature) {
    if (temperature > 30.0) {
        digitalWrite(FAN_PIN, HIGH); // Turn fan on
    } else {
        digitalWrite(FAN_PIN, LOW);  // Turn fan off
    }
}

// Timer callback function
void timer_callback() {
    int raw_temp, raw_pressure;
    float temperature, pressure;

    if (read_raw_temperature(&raw_temp) == -1 || read_raw_pressure(&raw_pressure) == -1) {
        fprintf(stderr, "Error reading sensor data, skipping this sample.\n");
