    }

    temperature = calculate_temperature(raw_temp, calibration_data);
    pressure = calculate_pressure(raw_pressure, raw_temp, calibration_data);

    time_t now = time(NULL);
    sensor_data_t data = {now, temperature, pressure};

    add_to_buffer(&buffer, data);

    printf("Timestamp: %ld, Temperature: %.2f C, Pressure: %.2f Pa\n", now, temperature, pressure);

    control_fan(temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;
    digitalWrite(FAN_PIN, LOW); // Turn fan off
    close(bmp180_fd);
    exit(0);
}

