    ac5 = bmp180_read_uint16(BMP180_REG_CAL_AC5);
    ac6 = bmp180_read_uint16(BMP180_REG_CAL_AC6);
    b1 = bmp180_read_int16(BMP180_REG_CAL_B1);
    b2 = bmp180_read_int16(BMP180_REG_CAL_B2);
    mb = bmp180_read_int16(BMP180_REG_CAL_MB);
    mc = bmp180_read_int16(BMP180_REG_CAL_MC);
    md = bmp180_read_int16(BMP180_REG_CAL_MD);

