    int msb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_LSB);
    int xlsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_XLSB);

    if (msb == -1 || lsb == -1 || xlsb == -1) {
        fprintf(stderr, "Error reading pressure data: %s\n", strerror(errno));
        return -1;
    }

    *up = ((long)msb << 16 | (long)lsb << 8 | (long)xlsb) >> (8 - BMP180_OSS);
    return 0;
}

// Function to compensate the temperature value
long bmp180_compensate_temperature(int ut)
{
