#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 17
#define SPI_CE0 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

// Define constants
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000
#define MAX_DUTY_CYCLE 800 // 80% of 1000
#define LOG_FILE "heater_log.csv"

// Global variables
static volatile int running = 1;
static double target_temperature = 25.0; // Default target temperature
static int spi_handle;
static FILE *log_file;

// Function prototypes
double read_temperature();
double calculate_error(double actual_temperature, double target_temperature);
double calculate_control_signal(double error, double Kp, double Ki, double dt);
void set_duty_cycle(int duty_cycle);
void log_data(double temperature, double duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// PI controller parameters
#define Kp 1.0
#define Ki 0.1
#define dt 1.0 // Time step in seconds

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        log_data(-999.0, -999.0); // Log error
        return -999.0; // Indicate error
    }

    // Check for fault conditions
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        log_data(-999.0, 0.0); // Log error
        return -999.0;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        log_data(-999.0, 0.0); // Log error
        return -999.0;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        log_data(-999.0, 0.0); // Log error
        return -999.0;
    }

    // Extract temperature data (bits 31:18 are the thermocouple temperature)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate the error between the actual temperature and the target temperature
double calculate_error(double actual_temperature, double target_temperature) {
    return target_temperature - actual_temperature;
}

// Function to calculate the control signal using a PI controller
double calculate_control_signal(double error, double Kp, double Ki, double dt) {
    static double integral = 0.0;
    static double previous_error = 0.0;

    double proportional = Kp * error;
    integral += Ki * error * dt;
    // Anti-windup: limit the integral term
    if (integral > MAX_DUTY_CYCLE) integral = MAX_DUTY_CYCLE;
    if (integral < 0) integral = 0;

    double control_signal = proportional + integral;

    previous_error = error;

    return control_signal;
}

// Function to set the duty cycle of the PWM signal
void set_duty_cycle(int duty_cycle) {
    if (duty_cycle > MAX_DUTY_CYCLE) {
        duty_cycle = MAX_DUTY_CYCLE;
    }
    if (duty_cycle < 0) {
        duty_cycle = 0;
    }
    gpioPWM(HEATER_PIN, duty_cycle);
}

// Function to log data to a file
void log_data(double temperature, double duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CE0, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(0, 2000000, 0); // SPI0, 2MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature,DutyCycle\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off heater
    set_duty_cycle(0);

    // Close SPI interface
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        target_temperature = atof(argv[1]);
        printf("Target temperature set to: %.2f\n", target_temperature);
    }

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read temperature
        double temperature = read_temperature();

        if (temperature != -999.0) {
            // Calculate error
            double error = calculate_error(temperature, target_temperature);

            // Calculate control signal
            double control_signal = calculate_control_signal(error, Kp, Ki, dt);

            // Set duty cycle
            int duty_cycle = (int)control_signal;
            set_duty_cycle(duty_cycle);

            // Log data
            log_data(temperature, duty_cycle);
        } else {
            // Log error
            log_data(-999.0, 0.0);
        }

        // Wait for a short period
        gpioDelay(100); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

