#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature thresholds
#define TEMP_THRESHOLD_1 40000
#define TEMP_THRESHOLD_2 59999

// Define PWM range
#define PWM_RANGE 255

// Define common anode supply voltage
#define VCC 3.3

// Define current limiting resistors (example values)
#define RED_RESISTOR 100
#define GREEN_RESISTOR 100
#define BLUE_RESISTOR 100

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *temperature_file = NULL;

// Function prototypes
int read_temperature();
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Structure to hold RGB color values
typedef struct {
    int red;
    int green;
    int blue;
} RGBColor;

// Function to read temperature from file
int read_temperature() {
    int temperature = -1; // Default to error value
    char line[256];
    char *token;
    int temp_milli_celsius = 0;

    temperature_file = fopen("temperature.txt", "r");
    if (temperature_file == NULL) {
        fprintf(stderr, "Error: Could not open temperature.txt\n");
        return -1;
    }

    if (ferror(temperature_file)) {
        fprintf(stderr, "Error: Failed to read temperature.txt\n");
        fclose(temperature_file);
        return -1;
    }

    if (fgets(line, sizeof(line), temperature_file) == NULL) {
        fprintf(stderr, "Error: Failed to read line from temperature.txt\n");
        fclose(temperature_file);
        return -1;
    }

    fclose(temperature_file);

    token = strtok(line, ",");
    if (token != NULL) {
        temperature = atoi(token);
        if (temperature < 0) {
            fprintf(stderr, "Error: Invalid temperature value: %d\n", temperature);
            return -1;
        }
        token = strtok(NULL, ",");
        if (token != NULL) {
            temp_milli_celsius = atoi(token);
            if (temp_milli_celsius < 0) {
                fprintf(stderr, "Error: Invalid temperature value: %d\n", temp_milli_celsius);
                return -1;
            }
        }
    }

    return temp_milli_celsius;
}

// Function to set RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    // Invert PWM values for common anode
    int red_pwm = PWM_RANGE - red;
    int green_pwm = PWM_RANGE - green;
    int blue_pwm = PWM_RANGE - blue;

    gpioPWM(RED_PIN, red_pwm);
    gpioPWM(GREEN_PIN, green_pwm);
    gpioPWM(BLUE_PIN, blue_pwm);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(RED_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioPWM(RED_PIN, PWM_RANGE); // Turn off all channels
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN, PWM_RANGE);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int temperature = read_temperature();

        if (temperature == -1) {
            // Error reading temperature, skip this iteration
            gpioDelay(500000); // 0.5 seconds
            continue;
        }

        // Determine LED color based on temperature
        RGBColor color;
        if (temperature < TEMP_THRESHOLD_1) {
            color.red = 0;
            color.green = 0;
            color.blue = 255;
        } else if (temperature < TEMP_THRESHOLD_2) {
            color.red = 0;
            color.green = 255;
            color.blue = 0;
        } else {
            color.red = 255;
            color.green = 0;
            color.blue = 0;
        }

        set_led_color(color.red, color.green, color.blue);

        // Print temperature and LED color
        printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n", temperature, color.red, color.green, color.blue);

        gpioDelay(500000); // 0.5 seconds
    }

    // Cleanup GPIO
    cleanup_gpio();

    printf("Program finished.\n");
    return 0;
}

