#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read DHT22 data
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int i, j;
    int bit = 0;
    int byte = 0;
    int data_bits[40] = {0};
    unsigned int pulse_lengths[80] = {0};

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1 ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30 us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
        gpioDelay(1); // 1 us
        timeout++;
    }
    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for low signal\n");
        return data; // Indicate failure
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
        gpioDelay(1); // 1 us
        timeout++;
    }
    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for high signal\n");
        return data; // Indicate failure
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
        gpioDelay(1); // 1 us
        timeout++;
    }
    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for low signal after high\n");
        return data; // Indicate failure
    }

    // Read the 40-bit response
    for (i = 0; i < 80; i++) {
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
            gpioDelay(1); // 1 us
            timeout++;
        }
        if (timeout >= 100) {
            fprintf(stderr, "DHT22: Timeout waiting for low signal during bit %d\n", i);
            return data; // Indicate failure
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
            gpioDelay(1); // 1 us
            timeout++;
        }
        if (timeout >= 100) {
            fprintf(stderr, "DHT22: Timeout waiting for high signal during bit %d\n", i);
            return data; // Indicate failure
        }
        long end = gpioTick();

        pulse_lengths[i] = end - start;
    }

    // Decode the 40-bit response
    for (i = 0; i < 40; i++) {
        int index = i * 2;
        if (pulse_lengths[index] > pulse_lengths[index + 1]) {
            data_bits[i] = 1;
        } else {
            data_bits[i] = 0;
        }
    }

    // Convert the 40-bit response to temperature and humidity
    int humidity_int = 0;
    int temperature_int = 0;
    for (i = 0; i < 16; i++) {
        humidity_int <<= 1;
        humidity_int |= data_bits[i];
    }
    for (i = 16; i < 32; i++) {
        temperature_int <<= 1;
        temperature_int |= data_bits[i];
    }

    // Validate checksum
    int checksum = 0;
    for (i = 0; i < 16; i++) {
        checksum += data_bits[i];
    }
    for (i = 32; i < 40; i++) {
        checksum += data_bits[i];
    }
    int received_checksum = 0;
    for (i = 0; i < 8; i++) {
        received_checksum <<= 1;
        received_checksum |= data_bits[i + 32];
    }

    if (checksum != received_checksum) {
        fprintf(stderr, "DHT22: Checksum mismatch: calculated %d, received %d\n", checksum, received_checksum);
        return data; // Indicate failure
    }

    data.humidity = (float)humidity_int / 10.0;
    data.temperature = (float)temperature_int / 10.0;
    data.valid = 1; // Indicate success

    return data;
}

// Function to format data as JSON
char* format_json(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    char *json_string = (char*)malloc(256 * sizeof(char)); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    snprintf(json_string, 256, "{\"timestamp\": \"%s\", \"temperature\": %.1f, \"humidity\": %.1f}", timestamp, temperature, humidity);
    return json_string;
}

// Function to post data to the server
CURLcode post_data(const char *json_string) {
    CURL *curl;
    CURLcode res = CURLE_OK;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_string));

        // Set content type to application/json
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        res = CURLE_FAILED_INIT;
    }
    curl_global_cleanup();
    return res;
}

int main() {
    int retries = 0;
    int max_retries = MAX_RETRIES;
    int delay = RETRY_DELAY_MS;
    DHT22Data dht22_data;
    char *json_payload;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        dht22_data = read_dht22();

        if (dht22_data.valid) {
            json_payload = format_json(dht22_data.temperature, dht22_data.humidity);
            if (json_payload != NULL) {
                if (post_data(json_payload) == CURLE_OK) {
                    printf("Data posted successfully: %s\n", json_payload);
                } else {
                    fprintf(stderr, "Failed to post data\n");
                }
                free(json_payload);
            } else {
                fprintf(stderr, "Failed to format JSON\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 data\n");
        }

        if (retries < max_retries) {
            retries++;
            printf("Retrying in %d ms...\n", delay);
            gpioDelay(delay);
            delay *= 2; // Exponential backoff
        } else {
            fprintf(stderr, "Max retries reached. Exiting.\n");
            break;
        }
    }

    // Clean up
    gpioTerminate();
    return 0;
}

