    int max_retries = MAX_RETRIES;
    int delay = RETRY_DELAY_MS;
    DHT22Data dht22_data;
    char *json_payload;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        dht22_data = read_dht22();

        if (dht22_data.valid) {
            json_payload = format_json(dht22_data.temperature, dht22_data.humidity);
            if (json_payload != NULL) {
                if (post_data(json_payload) == CURLE_OK) {
                    printf("Data posted successfully: %s\n", json_payload);
                } else {
                    fprintf(stderr, "Failed to post data\n");
                }
                free(json_payload);
            } else {
                fprintf(stderr, "Failed to format JSON\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 data\n");
        }

        if (retries < max_retries) {
            retries++;
            printf("Retrying in %d ms...\n", delay);
            gpioDelay(delay);
            delay *= 2; // Exponential backoff
        } else {
            fprintf(stderr, "Max retries reached. Exiting.\n");
            break;
        }
    }

    // Clean up
    gpioTerminate();
    return 0;
}

