double calculate_pressure(int raw_pressure, int raw_temperature)
{
    long x1 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) >> 12) >> 11;
    long x4 = ((long)ac2 * b6) >> 11;
    long b3 = (((((long)ac1) * 4 + x3) << OSS) + 2) >> 2;

    unsigned long x1_u = ((unsigned long)ac3 * b6) >> 13;
    unsigned long x2_u = ((unsigned long)b1 * ((b6 * b6) >> 12)) >> 16;
    unsigned long b4 = ((unsigned long)x1_u + x2_u + 32768) >> 15;
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> OSS);

    long p;
    if (b7 < 0x80000000)
