        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (logging_enabled) {
            int raw_temperature, raw_pressure;
            if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                double temperature = calculate_temperature(raw_temperature);
                double pressure = calculate_pressure(raw_pressure, raw_temperature);
                log_pressure(pressure);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
            gpioDelay(2000000); // Wait 2 seconds
        } else {
            gpioDelay(100000); // Check every 0.1 seconds
        }
    }

    return 0;
}

