}

// Read DHT22 sensor data
int read_dht22(DHT22Data *data)
{
    unsigned char dht22_data[5] = {0};
    int i, j;
    int bit = 0;
    int byte = 0;
    unsigned int tick;

    // Send start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1 ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30 us

    // Set GPIO to input
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for response (low for ~80us, high for ~80us)
    tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 1) {
        if (gpioTick() - tick > DHT22_TIMEOUT) {
            log_message(LOG_ERR, "DHT22 timeout waiting for start signal");
            return -1;
        }
    }
    tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 0) {
        if (gpioTick() - tick > DHT22_TIMEOUT) {
            log_message(LOG_ERR, "DHT22 timeout waiting for start signal");
            return -1;
        }
    }
    tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 1) {
        if (gpioTick() - tick > DHT22_TIMEOUT) {
            log_message(LOG_ERR, "DHT22 timeout waiting for start signal");
            return -1;
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for low
        tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 0) {
            if (gpioTick() - tick > DHT22_TIMEOUT) {
                log_message(LOG_ERR, "DHT22 timeout waiting for bit start");
                return -1;
            }
        }

        // Measure high time
        tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 1) {
            if (gpioTick() - tick > DHT22_TIMEOUT) {
                log_message(LOG_ERR, "DHT22 timeout waiting for bit end");
                return -1;
            }
        }
        unsigned int high_time = gpioTick() - tick;

        // Determine bit value
        if (high_time > 30) { // Empirical threshold
            dht22_data[byte] |= (1 << (7 - bit));
        }

        bit++;
        if (bit == 8) {
            bit = 0;
            byte++;
        }
    }

    // Validate checksum
    if (validate_checksum(dht22_data, 5) != 0) {
        log_message(LOG_ERR, "DHT22 checksum failure");
        return -1;
    }

    // Convert data to temperature and humidity
    data->humidity = (float)(((unsigned int)dht22_data[0] << 8) | dht22_data[1]) / 10.0;
    data->temperature = (float)(((unsigned int)dht22_data[2] << 8) | dht22_data[3]) / 10.0;
    if (data->temperature > 125) {
        data->temperature = -1; // Indicate error
        data->humidity = -1;
        data->valid = 0;
        log_message(LOG_ERR, "DHT22 temperature out of range");
        return -1;
    }
    data->valid = 1;

    return 0;
}

// Validate DHT22 checksum
int validate_checksum(unsigned char *data, int len)
{
    unsigned char checksum = 0;
    int i;

    for (i = 0; i < len - 1; i++) {
        checksum += data[i];
    }

    return (checksum == data[len - 1]) ? 0 : -1;
}

