    int result = -1;

    while (retries < MAX_RETRIES) {
        result = retry_curl(api_url, json_data, MAX_RETRIES, BACKOFF_DELAY);
        if (result == 0) {
            break; // Success
        } else {
            retries++;
            sleep(BACKOFF_DELAY);
        }
    }

    if (result != 0) {
        log_message(LOG_ERR, "Failed to post humidity data");
    }

    return result;
}

