    // Initialize pigpio
    init_result = init_pigpio();
    if (init_result != 0) {
        closelog();
        return 1;
    }

    // Initialize libcurl
    if (init_curl() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    DHT22Data dht22_data;
    int read_result;

    while (running) {
        read_result = read_dht22(&dht22_data);

        if (read_result == 0) {
            log_message(LOG_INFO, "DHT22 read successful");
            if (dht22_data.valid) {
                log_message(LOG_INFO, "Temperature: %.1f°C, Humidity: %.1f%%", dht22_data.temperature, dht22_data.humidity);
