            } else {
                log_message(LOG_ERR, "DHT22 data invalid");
            }
        } else {
            log_message(LOG_ERR, "DHT22 read failed");
        }

        sleep(READ_DELAY);
    }

    // Cleanup
    gpioTerminate();
    curl_global_cleanup();
    closelog();

    return 0;
}

