#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 18
#define SPI_CLK 11
#define SPI_CS 8
#define SPI_DO 9

// Define SPI channel
#define SPI_CHANNEL 0

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define duty cycle range
#define DUTY_CYCLE_RANGE 100

// Define temperature limits
#define MIN_TEMP 0.0
#define MAX_TEMP 100.0

// Define PID gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Define MAX31855 fault bits
#define MAX31855_FAULT_BIT_1 0x01
#define MAX31855_FAULT_BIT_2 0x02
#define MAX31855_FAULT_BIT_3 0x04
#define MAX31855_FAULT_BIT_4 0x08

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int spi_handle;

// Structure to hold PID state
typedef struct {
    double kp;
    double ki;
    double kd;
    double integral;
    double previous_error;
} PIDState;

// Function prototypes
double read_temperature();
double calculate_pid(PIDState *pid_state, double setpoint, double actual_temperature);
void set_pwm_duty_cycle(int duty_cycle);
void log_data(double temperature, double duty_cycle, double pid_output);
void signal_handler(int signal);
void cleanup();
void initialize_pid(PIDState *pid_state);
int read_max31855(int *raw_data);

// Function to initialize the PID state
void initialize_pid(PIDState *pid_state) {
    pid_state->kp = KP;
    pid_state->ki = KI;
    pid_state->kd = KD;
    pid_state->integral = 0.0;
    pid_state->previous_error = 0.0;
}

// Function to read temperature from MAX31855
double read_temperature() {
    int raw_data;
    int fault = 0;

    if (read_max31855(&raw_data) != 0) {
        fprintf(stderr, "Error reading MAX31855 data.\n");
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (raw_data & MAX31855_FAULT_BIT_1) {
        fprintf(stderr, "MAX31855 Fault: Open circuit (bit 1 set).\n");
        log_data(-999.0, 0.0, 0.0); // Log error
        gpioPWM(HEATER_PIN, 0); // Turn off heater
        gpioDelay(100000); // Wait 100ms
        return -999.0;
    } else if (raw_data & MAX31855_FAULT_BIT_2) {
        fprintf(stderr, "MAX31855 Fault: Short to GND (bit 2 set).\n");
        log_data(-999.0, 0.0, 0.0); // Log error
        gpioPWM(HEATER_PIN, 0); // Turn off heater
        gpioDelay(100000); // Wait 100ms
        return -999.0;
    } else if (raw_data & MAX31855_FAULT_BIT_3) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC (bit 3 set).\n");
        log_data(-999.0, 0.0, 0.0); // Log error
        gpioPWM(HEATER_PIN, 0); // Turn off heater
        gpioDelay(100000); // Wait 100ms
        return -999.0;
    } else if (raw_data & MAX31855_FAULT_BIT_4) {
        fprintf(stderr, "MAX31855 Fault: Reserved bit (bit 4 set).\n");
        log_data(-999.0, 0.0, 0.0); // Log error
        gpioPWM(HEATER_PIN, 0); // Turn off heater
        gpioDelay(100000); // Wait 100ms
        return -999.0;
    }

    // Extract temperature data (signed 14-bit value)
    int16_t temp_raw = (raw_data >> 2) & 0x3FFF; // Mask and shift to get the 14-bit temperature
    if (temp_raw & 0x2000) {
        temp_raw |= 0xC000; // Sign extend if negative
    }

    double temperature = temp_raw * 0.25; // Each LSB is 0.25 degrees C

    return temperature;
}

// Function to read MAX31855 data
int read_max31855(int *raw_data) {
    char tx_buf[4] = {0x00, 0x00, 0x00, 0x00};
    char rx_buf[4];

    gpioWrite(SPI_CS, 0); // Select the MAX31855
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    gpioWrite(SPI_CS, 1); // Deselect the MAX31855

    if (result != 4) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    *raw_data = ((rx_buf[0] << 8) | rx_buf[1]) >> 2; // Combine and shift to get the 14-bit temperature
    return 0;
}

// Function to calculate PID output
double calculate_pid(PIDState *pid_state, double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    pid_state->integral += error;
    double derivative = error - pid_state->previous_error;
    double output = pid_state->kp * error + pid_state->ki * pid_state->integral + pid_state->kd * derivative;
    pid_state->previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > DUTY_CYCLE_RANGE) duty_cycle = DUTY_CYCLE_RANGE;
    gpioPWM(HEATER_PIN, duty_cycle);
}

// Function to log data to file
void log_data(double temperature, double duty_cycle, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f C, Duty Cycle: %d, PID Output: %.2f\n", timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioPWM(HEATER_PIN, 0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CLK, PI_OUTPUT);
    gpioSetMode(SPI_CS, PI_OUTPUT);
    gpioSetMode(SPI_DO, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, DUTY_CYCLE_RANGE);

    // Open SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, 500000, 0); // SPI0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize PID
    PIDState pid_state;
    initialize_pid(&pid_state);

    // Open log file
    log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int duty_cycle = 0;
    double temperature, pid_output;

    // Main loop
    while (running) {
        temperature = read_temperature();

        if (temperature > MAX_TEMP || temperature < MIN_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f C\n", temperature);
            log_data(-999.0, 0.0, 0.0); // Log error
            gpioPWM(HEATER_PIN, 0); // Turn off heater
            gpioDelay(100000); // Wait 100ms
            continue;
        }

        pid_output = calculate_pid(&pid_state, 50.0, temperature);
        duty_cycle = (int)pid_output;

        set_pwm_duty_cycle(duty_cycle);
        log_data(temperature, duty_cycle, pid_output);

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

