#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define I2C addresses for the sensors
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71

// Define the I2C bus
#define I2C_BUS 1

// Define the log file name
#define LOG_FILE "flow_log.txt"

// Define the number of retries for I2C communication
#define MAX_RETRIES 3

// Define the retry delay in milliseconds
#define RETRY_DELAY_MS 10

// Define the scaling factor for SLF3S-1300F (example value, check datasheet)
#define FLOW_SCALE 0.01 // Example: 0.01 ml/min per unit

// Global variables for I2C handles and log file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int i2c_handle, float *flow_rate);
int validate_checksum(uint8_t data[], int len);
int log_flow_data(float flow1, float flow2);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float flow1;
    float flow2;
} sensor_data_t;

// Function to read flow rate from the sensor
int read_sensor(int i2c_handle, float *flow_rate) {
    uint8_t data[3];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)data, 3);

        if (result == 3) {
            // CRC check
            if (validate_checksum(data, 3)) {
                // Convert raw data to flow rate
                int16_t raw_flow = (data[0] << 8) | data[1];
                *flow_rate = (float)raw_flow * FLOW_SCALE;
                return 0; // Success
            } else {
                fprintf(stderr, "CRC check failed for sensor data: %02X %02X %02X\n", data[0], data[1], data[2]);
                return -1; // CRC check failed
            }
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure after all retries
}

// Function to validate the checksum
int validate_checksum(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    uint8_t polynomial = 0x31; // CRC polynomial (example, check datasheet)

    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }

    return (crc == data[len - 1]);
}

// Function to log flow data to a file
int log_flow_data(float flow1, float flow2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);

    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (1) {
        // Read flow rates from both sensors
        if (read_sensor(i2c_handle1, &sensor_data.flow1) != 0) {
            fprintf(stderr, "Failed to read flow rate from sensor 1.\n");
        }
        if (read_sensor(i2c_handle2, &sensor_data.flow2) != 0) {
            fprintf(stderr, "Failed to read flow rate from sensor 2.\n");
        }

        // Log the flow data
        if (log_flow_data(sensor_data.flow1, sensor_data.flow2) != 0) {
            fprintf(stderr, "Failed to log flow data.\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second in microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

