#include <pigpio.h>

// Define GPIO pins for the rotary encoder
#define ENCODER_A_GPIO 17
#define ENCODER_B_GPIO 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the log file size limit (in bytes)
#define LOG_FILE_SIZE_LIMIT 1048576 // 1MB

// Global variables
static volatile int pulse_count = 0;
static volatile int encoder_state = 0; // 00, 01, 10, 11
static volatile int last_encoder_state = 0;
static volatile int running = 1; // Flag to control the main loop

// Function prototypes
int initialize_gpio();
int read_encoder();
void update_state(int a, int b);
double calculate_angle();
int log_data(double angle);
void cleanup();
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int gpio_initialized;
    FILE *log_file;
} ProgramState;

ProgramState state = {0, NULL};

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(ENCODER_A_GPIO, PI_INPUT);
    gpioSetMode(ENCODER_B_GPIO, PI_INPUT);

    // Enable pull-up resistors on the GPIO pins
    gpioSetPullUpDown(ENCODER_A_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_GPIO, PI_PUD_UP);

    state.gpio_initialized = 1;
    return 0;
}

// Function to read the current state of the encoder pins
int read_encoder() {
    int a_value = gpioRead(ENCODER_A_GPIO);
    int b_value = gpioRead(ENCODER_B_GPIO);
    return (a_value << 1) | b_value;
}

// Function to update the encoder state based on the current and previous states
void update_state(int a, int b) {
    encoder_state = (encoder_state << 1) | ((a << 1) | b);
    if (encoder_state == 0) {
        encoder_state = 0; // Reset to 0 if it overflows
    }
}

// Function to calculate the angular position based on the encoder state
double calculate_angle() {
    int current_state = encoder_state;
    int previous_state = last_encoder_state;

    if (current_state != previous_state) {
        if (current_state > previous_state) {
            pulse_count++;
        } else {
            pulse_count--;
        }
    }

    double angle = (double)pulse_count / PULSES_PER_REVOLUTION * 360.0;
    last_encoder_state = current_state;
    return angle;
}

