    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, angle);
    fclose(fp);

    // Check if the log file size exceeds the limit
    fp = fopen(LOG_FILE, "r");
    if (fp != NULL) {
        fseek(fp, 0, SEEK_END);
        long file_size = ftell(fp);
        fclose(fp);

        if (file_size > LOG_FILE_SIZE_LIMIT) {
            fp = fopen(LOG_FILE, "w"); // Open in write mode to truncate
            if (fp != NULL) {
                fprintf(fp, "Timestamp,AngularPosition\n"); // Write header
                fclose(fp);
            } else {
                fprintf(stderr, "Error truncating log file: %s\n", LOG_FILE);
                return -1;
            }
        }
    }

    return 0;
}

// Function to handle signals (SIGINT, SIGTERM) and perform cleanup
void cleanup() {
    printf("Cleaning up and exiting...\n");
    if (state.gpio_initialized) {
        gpioTerminate();
    }
    if (state.log_file != NULL) {
        fclose(state.log_file);
    }
    exit(0);
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        cleanup();
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    state.log_file = fopen(LOG_FILE, "a");
    if (state.log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Write the header to the log file
    fprintf(state.log_file, "Timestamp,AngularPosition\n");

    printf("Rotary encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int encoder_value = read_encoder();
        update_state(encoder_value);

        double angle = calculate_angle();
        if (log_data(angle) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(1000); // Delay for 1 millisecond
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

