#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL 1 // seconds

// Mutex for protecting the pulse counter
pthread_mutex_t pulse_mutex;

// Global variables
volatile int pulse_count = 0;
volatile int running = 1; // Flag to control the main loop

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(int pulse_count, double time_interval);
void log_rpm(double rpm);
void signal_handler(int signal);

// Interrupt service routine (ISR)
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Function to calculate RPM
double calculate_rpm(int pulse_count, double time_interval) {
    return (double)pulse_count / time_interval * 60.0;
}

// Function to log RPM to file
void log_rpm(double rpm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, RPM: %.2f\n", timestamp, rpm);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0; // Stop the main loop
    gpioTerminate(); // Terminate pigpio
    pthread_mutex_destroy(&pulse_mutex); // Destroy the mutex
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-down resistor
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        gpioTerminate();
        return 1;
    }

    // Register interrupt service routine
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t start_time, current_time;
    double time_interval;
    double rpm;

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Record start time
        time(&start_time);

        // Main loop
        while (running) {
            // Wait for 1 second
            time_sleep(SAMPLE_INTERVAL);

            // Record end time
            time(&current_time);

            // Calculate time interval
            time_interval = difftime(current_time, start_time);

            // Calculate RPM
            rpm = calculate_rpm(pulse_count, time_interval);

            // Log RPM
            log_rpm(rpm);

            // Reset pulse count
            pulse_count = 0;

            // Update start time
            time(&start_time);
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);

    return 0;
}

