    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Function to calculate RPM
double calculate_rpm(int pulse_count, double time_interval) {
    return (double)pulse_count / time_interval * 60.0;
}

// Function to log RPM to file
void log_rpm(double rpm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, RPM: %.2f\n", timestamp, rpm);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0; // Stop the main loop
    gpioTerminate(); // Terminate pigpio
    pthread_mutex_destroy(&pulse_mutex); // Destroy the mutex
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-down resistor
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        gpioTerminate();
        return 1;
    }

    // Register interrupt service routine
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t start_time, current_time;
    double time_interval;
    double rpm;

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Record start time
        time(&start_time);

        // Main loop
        while (running) {
            // Wait for 1 second
            time_sleep(SAMPLE_INTERVAL);

            // Record end time
            time(&current_time);

            // Calculate time interval
            time_interval = difftime(current_time, start_time);

            // Calculate RPM
            rpm = calculate_rpm(pulse_count, time_interval);

            // Log RPM
            log_rpm(rpm);

            // Reset pulse count
            pulse_count = 0;

            // Update start time
            time(&start_time);
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);

    return 0;
}

