// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *ir, uint16_t *red);
int log_data(uint16_t ir, uint16_t red);
int control_led(uint16_t ir);
