#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define INTRUSION_THRESHOLD 5 // seconds

static volatile int running = 1;
static volatile int tamper_detected = 0;
static volatile time_t tamper_start_time = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value
int read_sensor() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to check for tamper event
int check_tamper() {
    int sensor_value = read_sensor();
    if (sensor_value < 0) {
        return 0; // Return 0 to avoid triggering on read error
    }

    if (sensor_value == 1) {
        if (!tamper_detected) {
            tamper_detected = 1;
            tamper_start_time = time(NULL);
            printf("Tamper detected!\n");
        } else {
            // Check if the tamper has been active for INTRUSION_THRESHOLD seconds
            time_t current_time = time(NULL);
            if (difftime(current_time, tamper_start_time) >= INTRUSION_THRESHOLD) {
                printf("INTRUSION DETECTED!\n");
            }
        }
    } else {
        // Reset the tamper detection timer if the sensor is released
        tamper_detected = 0;
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set GPIO_PIN as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        check_tamper();
        gpioDelay(100); // Poll every 100 milliseconds
    }

    // Cleanup before exiting
    gpioTerminate();
    printf("Tamper detection system stopped.\n");
    return EXIT_SUCCESS;
}

