#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

#define GPIO_PIN 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define FORMAT SND_PCM_FORMAT_S16_LE
#define PERIOD_SIZE 1024
#define BUFFER_COUNT 4

static volatile int running = 1;
static snd_pcm_t *pcm_handle = NULL;
static FILE *audio_file = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize ALSA
int initialize_alsa(snd_pcm_t **pcm_handle) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, FORMAT)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_PIN);
        return -1;
    }
    gpioWrite(GPIO_PIN, 1); // Initially set to HIGH (L channel)
    return 0;
}

// Function to write audio data to file
int write_audio_data(FILE *audio_file, short *buffer, int num_samples) {
    size_t bytes_written = fwrite(buffer, sizeof(short), num_samples, audio_file);
    if (bytes_written != num_samples) {
        fprintf(stderr, "Error writing to file: wrote %zu samples, expected %d\n", bytes_written, num_samples);
        return -1;
    }
    return 0;
}

int main() {
    snd_pcm_t *pcm_handle = NULL;
    short *buffer = NULL;
    int err;
    int i;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize ALSA
    if (initialize_alsa(&pcm_handle) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Allocate buffer
    buffer = (short *)malloc(PERIOD_SIZE * NUM_CHANNELS * sizeof(short));
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating buffer\n");
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Open audio file for writing
    audio_file = fopen("audio_capture.pcm", "wb");
    if (audio_file == NULL) {
        fprintf(stderr, "Error opening audio file\n");
        free(buffer);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read audio data
        if ((err = snd_pcm_readi(pcm_handle, buffer, PERIOD_SIZE)) != PERIOD_SIZE) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
            running = 0; // Stop on error
            continue; // Skip the rest of the loop and try again
        }

        // Write audio data to file
        if (write_audio_data(audio_file, buffer, err) != 0) {
            running = 0; // Stop on error
            break; // Exit the loop
        }

        // Delay to achieve desired sampling rate
        gpioDelay(1000000 / SAMPLE_RATE); // Delay in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (audio_file != NULL) {
        fclose(audio_file);
    }
    if (pcm_handle != NULL) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    free(buffer);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

