    printf("Cleaning up...\n");
    if (audio_file != NULL) {
        fclose(audio_file);
    }
    if (pcm_handle != NULL) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    free(buffer);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

