static FILE *log_file = NULL;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log events to a file
void log_event(const char *event) {
    char *timestamp = get_iso8601_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened. Event: %s\n", event);
    }
    free(timestamp);
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to configure GPIO pins
int configure_gpio() {
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_GPIO);
        return 1;
    }
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        return 1;
    }
    return 0;
}

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int i;
    for (i = 0; i < 5; i++) { // Read 5 times
        if (gpioRead(FLAME_SENSOR_GPIO) == 0) { // Flame detected (LOW signal)
            return 0; // Flame detected
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay for debouncing
    }
    return 1; // No flame detected after multiple attempts
}

// Function to start the PWM signal
void start_pwm() {
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", FAN_GPIO);
        return;
    }
    gpioPWM(FAN_GPIO, 128); // 50% duty cycle (adjust as needed)
}

// Function to stop the PWM signal
void stop_pwm() {
    gpioPWM(FAN_GPIO, 0); // Turn off the fan
}

