void reset_gpio() {
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT); // Set flame sensor back to input
    gpioSetMode(FAN_GPIO, PI_INPUT); // Set fan back to input
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor
    gpioSetPullUpDown(FAN_GPIO, PI_PUD_DOWN); // Enable pull-down resistor
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    log_event("Program shutdown due to signal");
    stop_pwm();
    reset_gpio();
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

