            if (!flame_detected) {
                log_event("Flame detected");
                start_time = time(NULL);
                flame_detected = 1;
                timeout_count = 0;
            }
        } else {
            if (flame_detected) {
                time_t current_time = time(NULL);
                if (difftime(current_time, start_time) > TIMEOUT_MS) {
                    log_event("Flame timeout");
                    timeout_count++;
                    if (timeout_count >= 3) {
                        log_event("Sensor absent");
                        timeout_count = 0;
                        flame_detected = 0; // Reset flame detection
                    }
                } else {
                    log_event("Flame ended");
                    timeout_count = 0;
                    flame_detected = 0;
                }
            }
        }

        if (flame_detected) {
            start_pwm();
        } else {
            stop_pwm();
        }

        gpioDelay(50 * 1000); // 50ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_pwm();
    reset_gpio();
    gpioTerminate();
    fclose(log_file);
    log_event("System stopped");

    return 0;
}

