#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration structure
typedef struct {
    float start_freq;
    float end_freq;
    int num_chirps;
    int num_samples;
} config_t;

// Global variables
static int spi_handle;
static FILE *log_file;
static config_t config;
static volatile int running = 1;

// Function prototypes
int spi_init(int spi_channel, int spi_speed);
int spi_transfer(int spi_handle, const uint8_t *tx_data, uint32_t tx_len, uint8_t *rx_data, uint32_t rx_len);
int spi_close(int spi_handle);
int gpio_init(int gpio_pin, int mode);
int gpio_set_mode(int gpio_pin, int mode);
int gpio_set_pullUpDown(int gpio_pin, int pud);
int gpio_read(int gpio_pin);
int gpio_write(int gpio_pin, int value);
void signal_handler(int signal);
int log_data(const uint8_t *data, size_t data_len);
int load_config(const char *filename, config_t *config);

// SPI initialization function
int spi_init(int spi_channel, int spi_speed) {
    int handle = spiOpen(spi_channel, spi_speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (%d)\n", handle);
        return -1;
    }
    return handle;
}

// SPI transfer function
int spi_transfer(int spi_handle, const uint8_t *tx_data, uint32_t tx_len, uint8_t *rx_data, uint32_t rx_len) {
    int result = spiXfer(spi_handle, tx_data, rx_data, tx_len);
    if (result != tx_len) {
        fprintf(stderr, "Error: spiXfer failed (%d)\n", result);
        return -1;
    }
    return 0;
}

// SPI close function
int spi_close(int spi_handle) {
    int result = spiClose(spi_handle);
    if (result != 0) {
        fprintf(stderr, "Error: spiClose failed (%d)\n", result);
        return -1;
    }
    return 0;
}

// GPIO initialization function
int gpio_init(int gpio_pin, int mode) {
    if (gpioSetMode(gpio_pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// GPIO set pull-up/down function
int gpio_set_pullUpDown(int gpio_pin, int pud) {
    gpioSetPullUpDown(gpio_pin, pud);
    return 0;
}

// GPIO read function
int gpio_read(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// GPIO write function
int gpio_write(int gpio_pin, int value) {
    gpioWrite(gpio_pin, value);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = 0;
}

// Data logging function
int log_data(const uint8_t *data, size_t data_len) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    // Write magic number
    if (fwrite(&4144, sizeof(uint8_t), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write magic number to log file.\n");
        return -1;
    }

    // Write timestamp
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    if (fwrite(&ts.tv_sec, sizeof(uint32_t), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write timestamp to log file.\n");
        return -1;
    }
    if (fwrite(&ts.tv_nsec, sizeof(uint32_t), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write timestamp to log file.\n");
        return -1;
    }

    // Write configuration struct
    if (fwrite(&config.start_freq, sizeof(float), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write start frequency to log file.\n");
        return -1;
    }
    if (fwrite(&config.end_freq, sizeof(float), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write end frequency to log file.\n");
        return -1;
    }
    if (fwrite(&config.num_chirps, sizeof(int), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write number of chirps to log file.\n");
        return -1;
    }
    if (fwrite(&config.num_samples, sizeof(int), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write number of samples to log file.\n");
        return -1;
    }

    // Write frame header
    if (fwrite(&ts.tv_sec, sizeof(uint32_t), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write frame timestamp to log file.\n");
        return -1;
    }
    if (fwrite(&ts.tv_nsec, sizeof(uint32_t), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write frame timestamp to log file.\n");
        return -1;
    }
    if (fwrite(&1, sizeof(uint8_t), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write frame number to log file.\n");
        return -1;
    }

    // Write data
    if (fwrite(data, sizeof(uint8_t), data_len, log_file) != data_len) {
        fprintf(stderr, "Error: Failed to write data to log file.\n");
        return -1;
    }

    // Write frame header
    if (fwrite(&ts.tv_sec, sizeof(uint32_t), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write frame timestamp to log file.\n");
        return -1;
    }
    if (fwrite(&ts.tv_nsec, sizeof(uint32_t), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write frame timestamp to log file.\n");
        return -1;
    }
    if (fwrite(&2, sizeof(uint8_t), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write frame number to log file.\n");
        return -1;
    }

    return 0;
}

// Load configuration from file
int load_config(const char *filename, config_t *config) {
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open config file %s\n", filename);
        return -1;
    }

    size_t read_config = fread(config, sizeof(config_t), 1, fp);
    if (read_config != 1) {
        fprintf(stderr, "Error: Could not read config file %s\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Load configuration
    if (load_config("config.txt", &config) != 0) {
        fprintf(stderr, "Error: Failed to load configuration. Using default values.\n");
        config.start_freq = 77.0;
        config.end_freq = 79.0;
        config.num_chirps = 64;
        config.num_samples = 256;
    }

    // Initialize SPI
    spi_handle = spi_init(0, 1000000); // SPI channel 0, 1 MHz
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO pins
    if (gpio_init(23, PI_INPUT) != 0) { // Frame trigger
        spi_close(spi_handle);
        gpioTerminate();
        return 1;
    }
    if (gpio_init(24, PI_INPUT) != 0) { // Data ready
        spi_close(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set pull-up/down resistors (optional, adjust as needed)
    gpio_set_pullUpDown(23, PI_PUD_DOWN); // Frame trigger
    gpio_set_pullUpDown(24, PI_PUD_DOWN); // Data ready

    // Open log file
    log_file = fopen("radar_data.bin", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        spi_close(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Radar data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Wait for frame trigger
        while (running && !gpio_read(23)) {
            gpioDelay(1000); // Check every 1 ms
        }

        if (!running) break;

        // Read data ready pin
        while (running && !gpio_read(24)) {
            gpioDelay(1000); // Check every 1 ms
        }

        if (!running) break;

        // Read data
        uint8_t *data = malloc(32768); // Allocate memory for 32KB of data
        if (data == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for data\n");
            running = 0; // Exit loop to prevent further errors
            break;
        }

        // Read data from SPI
        if (spi_transfer(spi_handle, data, 32768, data, 32768) != 0) {
            fprintf(stderr, "Error: Failed to read data from SPI\n");
            free(data);
            running = 0; // Exit loop to prevent further errors
            break;
        }

        // Log data
        if (log_data(data, 32768) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
            running = 0; // Exit loop to prevent further errors
            break;
        }

        free(data);

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    spi_close(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

