// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the flame state to a file
int log_flame_state(const char *timestamp, const char *state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s,%s\n", timestamp, state);
    if (ferror(fp)) {
        perror("Failed to write to log file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO20 as an input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    int previous_state = gpioRead(GPIO_PIN);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state != previous_state) {
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                if (log_flame_state(timestamp, current_state == 0 ? "Flame Detected" : "Flame Cleared") != 0) {
                    fprintf(stderr, "Failed to log flame state.\n");
                }
                free(timestamp);
            } else {
                fprintf(stderr, "Failed to get timestamp.\n");
            }
            previous_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

