#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C address of the OPT3001 sensor
#define OPT3001_ADDR 0x44

// Define the register addresses
#define RESULT_REG 0x00
#define CONFIG_REG 0x01

// Define the continuous conversion mode and auto range settings
#define CONFIG_VALUE 0xCB10 // Continuous conversion, Auto range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float lux;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(uint16_t *raw_data);
float convert_to_lux(uint16_t raw_data);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(1, OPT3001_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Sensor configuration function
int configure_sensor() {
    uint16_t config_value = CONFIG_VALUE;
    char buf[3];
    buf[0] = (config_value >> 8) & 0xFF;
    buf[1] = config_value & 0xFF;
    buf[2] = 0x00; // Dummy byte for writing to the register

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Data reading function
int read_sensor_data(uint16_t *raw_data) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *raw_data = (buf[0] << 8) | buf[1];
    return 0;
}

// Lux conversion function
float convert_to_lux(uint16_t raw_data) {
    uint16_t exponent = (raw_data >> 12) & 0x0F;
    uint16_t result = raw_data & 0x0FFF;
    return 0.01 * pow(2, exponent) * result;
}

// Data logging function
int log_data(float lux) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s,%.2f\n", buf, lux);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    uint16_t raw_data;
    float lux;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_data) == 0) {
            // Convert to lux
            lux = convert_to_lux(raw_data);

            // Log the data
            log_data(lux);

            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

