#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define POLL_INTERVAL_MS 1000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int current_value, previous_value;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_message[50];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Request GPIO line
    gpio_status = gpioRequestLine(GPIO_PIN, PI_INPUT, PI_PUD_UP);
    if (gpio_status < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %d\n", GPIO_PIN, gpio_status);
        gpioTerminate();
        return 1;
    }

    // Set initial value
    previous_value = gpioRead(GPIO_PIN);

    printf("Flame detection program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        current_value = gpioRead(GPIO_PIN);

        if (current_value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %d\n", GPIO_PIN, current_value);
            gpioTerminate();
            return 1;
        }

        if (current_value != previous_value) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (current_value == 0) {
                strcpy(log_message, "Flame Detected: YES");
            } else {
                strcpy(log_message, "Flame Detected: NO");
            }

            printf("%s %s\n", timestamp, log_message);
        }

        previous_value = current_value;
        gpioDelay(POLL_INTERVAL_MS);
    }

    // Release GPIO line
    gpioReleaseLine(GPIO_PIN);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

