#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define the GPIO pins for the TTP226 channels
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = 8;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < num_channels; ++i) {
        if (gpioSetMode(gpio_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", gpio_pins[i]);
            return -1;
        }
    }
    return 0;
}

// Function to read the state of a single GPIO pin
int read_gpio(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to format the sensor data into a string
char* format_sensor_data(int *channel_states) {
    static char buffer[256]; // Static buffer to hold the formatted string
    snprintf(buffer, sizeof(buffer), "%s", channel_states);
    return buffer;
}

// Function to print the sensor data to the console
void print_sensor_data(const char *data) {
    printf("%s\n", data);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    for (int i = 0; i < num_channels; ++i) {
        gpioSetMode(gpio_pins[i], PI_INPUT); // Set back to input
    }
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop to read and print sensor data
    while (program_running) {
        int channel_states[num_channels];
        for (int i = 0; i < num_channels; ++i) {
            channel_states[i] = read_gpio(gpio_pins[i]);
        }

        // Format the sensor data
        char *formatted_data = format_sensor_data(channel_states);

        // Print the sensor data
        print_sensor_data(formatted_data);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

