int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to configure the GPIO pins as inputs with pull-down resistors
int configure_gpio_pins() {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN);
    }
    return 0;
}

// Function to read the sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    for (int i = 0; i < NUM_CHANNELS; i++) {
        data.channel1 = gpioRead(sensor_pins[i]);
        if (i == 0) data.channel1 = gpioRead(sensor_pins[0]);
        if (i == 1) data.channel2 = gpioRead(sensor_pins[1]);
        if (i == 2) data.channel3 = gpioRead(sensor_pins[2]);
        if (i == 3) data.channel4 = gpioRead(sensor_pins[3]);
        if (i == 4) data.channel5 = gpioRead(sensor_pins[4]);
        if (i == 5) data.channel6 = gpioRead(sensor_pins[5]);
        if (i == 6) data.channel7 = gpioRead(sensor_pins[6]);
        if (i == 7) data.channel8 = gpioRead(sensor_pins[7]);
    }
    return data;
}

