    if (initialize_gpio() != 0) {
        return 1;
    }

    // Configure the GPIO pins
    if (configure_gpio_pins() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read the sensor data
        sensor_data_t sensor_data = read_sensor_data();

        // Format the sensor data
