        format_sensor_data(sensor_data, data_string, sizeof(data_string));

        // Print the sensor data
        print_sensor_data(data_string);

        // Wait for 100ms
        gpioDelay(100000);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

