#include <signal.h>
#include <pigpio.h>

// Define the GPIO pins for the TTP226 sensor channels
#define SENSOR_1 2
#define SENSOR_2 3
#define SENSOR_3 4
#define SENSOR_4 17
#define SENSOR_5 27
#define SENSOR_6 22
#define SENSOR_7 10
#define SENSOR_8 9

// Structure to hold the sensor states
typedef struct {
    int sensor1;
    int sensor2;
    int sensor3;
    int sensor4;
    int sensor5;
    int sensor6;
    int sensor7;
    int sensor8;
} sensor_states_t;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read the sensor states
sensor_states_t read_sensor_states() {
    sensor_states_t states;
    states.sensor1 = gpioRead(SENSOR_1);
    states.sensor2 = gpioRead(SENSOR_2);
    states.sensor3 = gpioRead(SENSOR_3);
    states.sensor4 = gpioRead(SENSOR_4);
    states.sensor5 = gpioRead(SENSOR_5);
    states.sensor6 = gpioRead(SENSOR_6);
    states.sensor7 = gpioRead(SENSOR_7);
    states.sensor8 = gpioRead(SENSOR_8);
    return states;
}

// Function to format the sensor data into a CSV string
char* format_csv(sensor_states_t states) {
    char *csv_string = (char*)malloc(50 * sizeof(char)); // Allocate memory for the CSV string
    if (csv_string == NULL) {
        perror("Failed to allocate memory for CSV string");
        return NULL;
    }

    sprintf(csv_string, "%s,%d,%d,%d,%d,%d,%d,%d,%d",
            get_iso8601_timestamp(), states.sensor1, states.sensor2, states.sensor3, states.sensor4,
            states.sensor5, states.sensor6, states.sensor7, states.sensor8);
    return csv_string;
}

// Function to print the CSV string to the console
void print_csv(char *csv_string) {
    if (csv_string != NULL) {
        printf("%s\n", csv_string);
        free(csv_string);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    gpioSetMode(SENSOR_1, PI_INPUT);
    gpioSetMode(SENSOR_2, PI_INPUT);
    gpioSetMode(SENSOR_3, PI_INPUT);
    gpioSetMode(SENSOR_4, PI_INPUT);
    gpioSetMode(SENSOR_5, PI_INPUT);
    gpioSetMode(SENSOR_6, PI_INPUT);
    gpioSetMode(SENSOR_7, PI_INPUT);
    gpioSetMode(SENSOR_8, PI_INPUT);

    // Disable pull-up resistors (optional, depends on sensor configuration)
    gpioSetPullUpDown(SENSOR_1, PI_PUD_OFF);
    gpioSetPullUpDown(SENSOR_2, PI_PUD_OFF);
    gpioSetPullUpDown(SENSOR_3, PI_PUD_OFF);
    gpioSetPullUpDown(SENSOR_4, PI_PUD_OFF);
    gpioSetPullUpDown(SENSOR_5, PI_PUD_OFF);
    gpioSetPullUpDown(SENSOR_6, PI_PUD_OFF);
    gpioSetPullUpDown(SENSOR_7, PI_PUD_OFF);
    gpioSetPullUpDown(SENSOR_8, PI_PUD_OFF);

