    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int tilt_state;
    int previous_tilt_state = -1; // Initialize to an invalid state

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    // Print startup banner
    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read the current tilt state
        tilt_state = gpioRead(TILT_SENSOR_GPIO);

        // Validate the read
        if (tilt_state != 0 && tilt_state != 1) {
            fprintf(stderr, "Error: Invalid GPIO read: %d\n", tilt_state);
            gpioTerminate();
            return 1;
        }

        // Check if the tilt state has changed
        if (tilt_state != previous_tilt_state) {
            // Print the current tilt state
            if (tilt_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }

            // Update the previous tilt state
            previous_tilt_state = tilt_state;
        }

        // Wait for 100 milliseconds
        gpioDelay(100); // pigpio's replacement for usleep
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

