#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define REG_PARTID 0x00
#define REG_REVID 0x01
#define REG_SEQID 0x02

#define REG_UCOEF0 0x13
#define REG_UCOEF1 0x14
#define REG_UCOEF2 0x15
#define REG_UCOEF3 0x16

#define REG_PARAM_WR 0x17
#define REG_COMMAND 0x18
#define REG_RESPONSE0 0x20
#define REG_RESPONSE1 0x21
#define REG_RESPONSE2 0x22
#define REG_RESPONSE3 0x23

#define REG_IRQ_ENABLE 0x03
#define REG_IRQ_MODE1 0x04
#define REG_HW_KEY 0x07

#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23

#define REG_UVINDEX0 0x2C
#define REG_UVINDEX1 0x2D

// Commands
#define CMD_RESET 0x01
#define CMD_ALS_FORCE 0x06
#define CMD_ALS_AUTO 0x0F
#define CMD_ALS_FORCE_ALS 0x10

// Parameters
#define PARAM_CHLIST 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_si1145_data(float *uv_index, uint16_t *als_visible);
void log_data(float uv_index, uint16_t als_visible);
void signal_handler(int signal);
char* get_timestamp();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Get timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Initialize Si1145 sensor
int init_si1145() {
    // Reset the device
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure parameters (example configuration)
    if (i2cWriteByteData(i2c_handle, REG_PARAM_WR, 0x77) < 0) {
        fprintf(stderr, "Error: Failed to write parameter 1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_ALS_AUTO) < 0) {
        fprintf(stderr, "Error: Failed to start ALS auto mode\n");
        return -1;
    }

    return 0;
}

// Read UV index and visible light data from Si1145
int read_si1145_data(float *uv_index, uint16_t *als_visible) {
    uint8_t data[4];

    // Read UV index
    if (i2cReadI2CBlockData(i2c_handle, REG_UVINDEX0, (char *)data, 2) < 0) {
        fprintf(stderr, "Error: Failed to read UV index\n");
        return -1;
    }
    *uv_index = (float)(((uint16_t)data[1] << 8) | data[0]) / 100.0f; // UV index

    // Read visible light
    if (i2cReadI2CBlockData(i2c_handle, REG_ALS_VIS_DATA0, (char *)data, 2) < 0) {
        fprintf(stderr, "Error: Failed to read visible light\n");
        return -1;
    }
    *als_visible = (uint16_t)(((uint16_t)data[1] << 8) | data[0]);

    return 0;
}

// Log data to CSV file
void log_data(float uv_index, uint16_t als_visible) {
    char *timestamp = get_timestamp();
    fprintf(log_file, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (init_si1145() < 0) {
        fprintf(stderr, "Error: Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,UV Index,Visible Light\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float uv_index;
    uint16_t als_visible;

    // Main loop
    while (!terminate) {
        if (read_si1145_data(&uv_index, &als_visible) == 0) {
            log_data(uv_index, als_visible);
            printf("UV Index: %.2f, Visible Light: %u\n", uv_index, als_visible);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

