#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define ALARM_GPIO 17
#define START_CMD_1 0x30
#define START_CMD_2 0x00
#define MEASUREMENT_CMD_1 0x00
#define MEASUREMENT_CMD_2 0x10
#define CRC_POLYNOMIAL 0x31
#define INITIAL_REGISTER 0x00
#define LOG_FILE "flow_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define START_DELAY_MS 100

// Global variables
int i2c_handle1, i2c_handle2;
FILE *log_file, *error_log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int handle;
    int valid;
    float flow_rate;
} sensor_t;

// Function prototypes
int init_sensor(int i2c_handle);
int read_sensor(int i2c_handle, float *flow_rate);
float calculate_average(float flow_rate1, float flow_rate2);
void control_alarm(float average_flow_rate);
void log_data(float flow_rate1, float flow_rate2, float average_flow_rate);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// CRC calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize a sensor
int init_sensor(int i2c_handle) {
    char buf[2];
    buf[0] = START_CMD_1;
    buf[1] = START_CMD_2;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        log_error("Failed to send start command.");
        return -1;
    }
    gpioDelay(START_DELAY_MS * 1000); // Delay for 100ms

    return 0;
}

// Read flow rate from a sensor
int read_sensor(int i2c_handle, float *flow_rate) {
    char buf[1];
    char data[3];
    uint8_t crc;

    buf[0] = MEASUREMENT_CMD_1;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        log_error("Failed to send measurement command.");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        log_error("Failed to read data from sensor.");
        return -1;
    }

    crc = crc8(data, 2);
    if (crc != data[2]) {
        log_error("CRC check failed.");
        return -1;
    }

    int16_t raw_flow = (data[0] << 8) | data[1];
    *flow_rate = (float)raw_flow / 120.0; // Scaling factor from datasheet

    return 0;
}

// Calculate the average flow rate
float calculate_average(float flow_rate1, float flow_rate2) {
    if (flow_rate1 < 0 && flow_rate2 < 0) {
        return 0.0;
    } else if (flow_rate1 < 0) {
        return flow_rate2;
    } else if (flow_rate2 < 0) {
        return flow_rate1;
    } else {
        return (flow_rate1 + flow_rate2) / 2.0;
    }
}

// Control the alarm
void control_alarm(float average_flow_rate) {
    if (average_flow_rate < 0.5) {
        gpioWrite(ALARM_GPIO, 1); // Activate alarm
    } else {
        gpioWrite(ALARM_GPIO, 0); // Deactivate alarm
    }
}

// Log data to file
void log_data(float flow_rate1, float flow_rate2, float average_flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Flow Rate 1: %.2f ml/min, Flow Rate 2: %.2f ml/min, Average Flow: %.2f ml/min\n",
