void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// CRC calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize a sensor
int init_sensor(int i2c_handle) {
    char buf[2];
    buf[0] = START_CMD_1;
    buf[1] = START_CMD_2;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        log_error("Failed to send start command.");
        return -1;
    }
    gpioDelay(START_DELAY_MS * 1000); // Delay for 100ms

    return 0;
}

// Read flow rate from a sensor
int read_sensor(int i2c_handle, float *flow_rate) {
    char buf[1];
    char data[3];
    uint8_t crc;

    buf[0] = MEASUREMENT_CMD_1;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        log_error("Failed to send measurement command.");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        log_error("Failed to read data from sensor.");
        return -1;
    }

    crc = crc8(data, 2);
    if (crc != data[2]) {
        log_error("CRC check failed.");
        return -1;
    }

    int16_t raw_flow = (data[0] << 8) | data[1];
    *flow_rate = (float)raw_flow / 120.0; // Scaling factor from datasheet

    return 0;
}

