#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_MS 50

// Structure to hold the timestamp and sensor reading
typedef struct {
    time_t timestamp;
    int sensor_reading;
} DetectionEvent;

// Circular buffer
DetectionEvent detection_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_detection(time_t timestamp, int reading);
void dump_buffer();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    printf("Obstacle avoidance sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor value
        int sensor_value = read_sensor();

        // Get current timestamp
        time_t current_time = time(NULL);

        // Add detection event to the circular buffer
        add_detection(current_time, sensor_value);

        // Check for obstacle detection (LOW signal)
        if (sensor_value == 0) {
            printf("Obstacle detected!\n");
        }

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Dump the circular buffer before exiting
    dump_buffer();

    // Release pigpio resources
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as an input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Enable pull-up resistor on GPIO4
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to add a detection event to the circular buffer
void add_detection(time_t timestamp, int reading) {
    detection_buffer[buffer_index].timestamp = timestamp;
    detection_buffer[buffer_index].sensor_reading = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to dump the contents of the circular buffer to stdout
void dump_buffer() {
    printf("\n--- Detection Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        time_t timestamp = detection_buffer[index].timestamp;
        int reading = detection_buffer[index].sensor_reading;
        char time_str[30];
        ctime_r(&timestamp, time_str);
        // Remove trailing newline from ctime
        time_str[strcspn(time_str, "\n")] = 0;
        printf("[%s] Sensor Reading: %s\n", time_str, reading ? "HIGH" : "LOW");
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

