#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDRESS 0x4C
#define GPIO_SDA 2
#define GPIO_SCL 3
#define SAMPLE_RATE_MS 500
#define POLLING_WINDOW_S 1
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Data structure for sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Global variables
int i2c_fd = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int initialize_gpio();
int configure_sensor();
sensor_data_t read_sensor_data();
int write_data_to_csv(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization
int initialize_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, D7S_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// GPIO initialization
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_SDA, PI_ALT0); // SDA as ALT0
    gpioSetMode(GPIO_SCL, PI_ALT0); // SCL as ALT0

    return 0;
}

// Sensor configuration
int configure_sensor() {
    // Example configuration (replace with actual D7S configuration)
    // This might involve writing to specific registers to set the measurement mode, data rate, etc.
    // Refer to the D7S datasheet for the correct register addresses and values.
    // For example:
    // char config_data[] = {0x01, 0x02}; // Example configuration data
    // if (write(i2c_fd, config_data, sizeof(config_data)) != sizeof(config_data)) {
    //     perror("Error writing to I2C device");
    //     return -1;
    // }

    // In this example, we are not configuring the sensor, just reading data.
    return 0;
}

// Data acquisition
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char reg = 0x00; // Register to read from (example)
    unsigned char buffer[6]; // Buffer to store 6 bytes of data (X, Y, Z)

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        data.x = 0; data.y = 0; data.z = 0; // Return default values
        return data;
    }

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading from I2C device");
        data.x = 0; data.y = 0; data.z = 0; // Return default values
        return data;
    }

    // Assuming X, Y, Z are 16-bit values, little-endian
    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Data logging
int write_data_to_csv(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fp = fopen("fan_health.csv", "a+");
    if (fp == NULL) {
        perror("Error opening CSV file");
        return -1;
    }

    // Check if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,X,Y,Z\n");
    }

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);

    fclose(fp);
    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() < 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        cleanup();
        return 1;
    }

    printf("Fan Health Monitoring started. Press Ctrl+C to exit.\n");

    time_t start_time = time(NULL);
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        if (write_data_to_csv(data) < 0) {
            fprintf(stderr, "Error writing data to CSV\n");
        }
        time_t current_time = time(NULL);
        if (difftime(current_time, start_time) >= POLLING_WINDOW_S) {
            break;
        }
        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay in microseconds
    }

    cleanup();
    printf("Fan Health Monitoring stopped.\n");
    return 0;
}

