#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN 25

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read sensor values
int read_sensors() {
    int sensor1_value = gpioRead(SENSOR1_PIN);
    int sensor2_value = gpioRead(SENSOR2_PIN);
    return (sensor1_value << 1) | sensor2_value; // Combine sensor values into a single integer
}

// Function to control the LED
void control_led(int sensor_values) {
    if (sensor_values == 0) { // Obstacle detected by either sensor
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else if (sensor_values == 3) { // No obstacle detected by either sensor
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_values = read_sensors();
        control_led(sensor_values);
        gpioDelay(100); // Poll every 100 ms
    }

    // Clean up GPIO resources before exiting
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio

    printf("Program terminated.\n");
    return 0;
}

