#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define STALL_LOG_FILE "stall_log.txt"
#define STALL_DURATION_SEC 2
#define DEBOUNCE_DELAY_MS 50

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int sensor1_value;
    int sensor2_value;
    time_t timestamp;
} SensorData;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int verify_stall(int sensor1_value, int sensor2_value);
int log_stall(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    return 0;
}

// Read sensor value
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Verify stall condition
int verify_stall(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

// Log stall event
int log_stall(SensorData data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    if (fprintf(log_file, "%ld: Stall detected\n", data.timestamp) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return 1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(STALL_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    printf("Stall detection started. Press Ctrl+C to exit.\n");

    time_t last_stall_time = 0;
    int stall_detected = 0;

    while (program_running) {
        SensorData current_data;
        current_data.timestamp = time(NULL);

        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);

        if (verify_stall(sensor1_value, sensor2_value)) {
            if (!stall_detected) {
                last_stall_time = current_data.timestamp;
                stall_detected = 1;
                printf("Stall detected!\n");
            } else {
                // Check if stall duration has exceeded STALL_DURATION_SEC
                if (difftime(current_data.timestamp, last_stall_time) >= STALL_DURATION_SEC) {
                    if (log_stall(current_data) == 0) {
                        printf("Stall logged.\n");
                    } else {
                        fprintf(stderr, "Error logging stall.\n");
                    }
                    stall_detected = 0; // Reset stall detection
                }
            }
        } else {
            stall_detected = 0; // Reset stall detection if not verified
        }

        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
    }

    cleanup();
    printf("Program terminated.\n");
    return 0;
}

