// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor
    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to generate an alert message
void generate_alert() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("ALERT: Water detected at %s\n", timestamp);

    // Log the alert to the file
    if (log_file != NULL) {
        fprintf(log_file, "%s ALERT: Water detected\n", timestamp);
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to log errors to the log file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "ERROR: %s\n", message);

    if (log_file != NULL) {
        fprintf(log_file, "%s ERROR: %s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to re-initialize the GPIO
int reinitialize_gpio() {
    if (initialize_gpio() != 0) {
        log_error("GPIO re-initialization failed.");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_error("GPIO initialization failed. Exiting.");
        fclose(log_file);
        return 1;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sensor_value = read_sensor();

        if (sensor_value == 1) {
            generate_alert();
        } else if (sensor_value < 0) {
            log_error("Error reading sensor value.");
            reinitialize_gpio();
        }

        gpioDelay(POLL_INTERVAL * 1000); // Delay for 2 seconds
    }

    return 0;
}

