#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL 1 // seconds

static volatile int pulse_count = 0;
static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Callback function for rising edge detection
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

// Function to calculate RPM
double calculate_rpm(int pulse_count, double time_interval) {
    return (double)pulse_count / time_interval * 60.0;
}

// Function to log RPM to file
int log_rpm(double rpm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s %.2f\n", timestamp, rpm);
    if (ferror(fp)) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt callback for rising edge detection
    if (gpioSetAlertFunc(GPIO_PIN, pulse_callback) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t start_time, current_time;
    double time_interval;
    int current_pulse_count;
    double rpm;

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Record start time
        start_time = time(NULL);

        // Wait for 1 second
        time_sleep(SAMPLE_INTERVAL);

        // Record end time
        current_time = time(NULL);

        // Calculate time interval
        time_interval = difftime(current_time, start_time);

        // Get current pulse count
        current_pulse_count = pulse_count;

        // Calculate RPM
        rpm = calculate_rpm(current_pulse_count, time_interval);

        // Log RPM to file
        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Error logging RPM\n");
        }

        // Print RPM to stdout
        printf("RPM: %.2f\n", rpm);

        // Reset pulse count
        pulse_count = 0;
    }

    // Disable interrupt callback
    gpioSetAlertFunc(GPIO_PIN, NULL);

    // Terminate pigpio library
    gpioTerminate();

    printf("RPM monitoring stopped.\n");

    return 0;
}

