#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define TOUCH_PIN 23
#define LED_PIN 18

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

int main() {
    int touch_state;
    int led_state;
    int result;

    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    syslog(LOG_INFO, "Starting touch_led program...");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set TOUCH_PIN as input");
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set LED_PIN as output");
        gpioTerminate();
        closelog();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Touch sensor and LED initialized.");

    while (program_running) {
        touch_state = gpioRead(TOUCH_PIN);
        if (touch_state < 0) {
            syslog(LOG_ERR, "Failed to read TOUCH_PIN");
            break;
        }

        if (touch_state == 1) {
            led_state = 1;
        } else {
            led_state = 0;
        }

        if (gpioWrite(LED_PIN, led_state) != 0) {
            syslog(LOG_ERR, "Failed to write to LED_PIN");
            break;
        }

        gpioDelay(50); // 50ms delay
    }

    syslog(LOG_INFO, "Shutting down touch_led program...");

    gpioWrite(LED_PIN, 0); // Turn off LED on exit
    gpioTerminate();
    closelog();

    return 0;
}

