#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_PIN 17
#define LED_PIN 18

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set GPIO modes
    result = gpioSetMode(TOUCH_PIN, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO%d to input: %d\n", TOUCH_PIN, result);
        gpioTerminate();
        return 1;
    }

    result = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO%d to output: %d\n", LED_PIN, result);
        gpioTerminate();
        return 1;
    }

    // Initialize LED to LOW
    result = gpioWrite(LED_PIN, 0);
    if (result != 0) {
        fprintf(stderr, "Failed to write 0 to GPIO%d: %d\n", LED_PIN, result);
        gpioTerminate();
        return 1;
    }

    printf("Touch sensor program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Wait for rising edge on TOUCH_PIN
        result = gpioEventWait(TOUCH_PIN, 1, 50); // 50ms debounce
        if (result != 0) {
            fprintf(stderr, "Event wait failed: %d\n", result);
            break; // Exit loop on error
        }

        // Toggle LED state
        result = gpioWrite(LED_PIN, !gpioRead(LED_PIN));
        if (result != 0) {
            fprintf(stderr, "Failed to write to GPIO%d: %d\n", LED_PIN, result);
            break; // Exit loop on error
        }
    }

    // Release resources before exiting
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioSetMode(TOUCH_PIN, PI_INPUT); // Release the line
    gpioSetMode(LED_PIN, PI_INPUT); // Release the line
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

