#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_INTERVAL_MS 500

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the rain sensor state
int read_rain_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to log rain events to a file
int log_rain_event(int rain_detected) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    if (rain_detected) {
        fprintf(fp, "%s Rain Detected\n", timestamp);
    } else {
        fprintf(fp, "%s No Rain\n", timestamp);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", LOG_FILE);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Enable pull-up resistor
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int previous_state = -1; // Initialize to an invalid state

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = read_rain_sensor();

        if (current_state != previous_state) {
            if (log_rain_event(current_state) != 0) {
                fprintf(stderr, "Error logging rain event\n");
            }
            previous_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("Rain sensor monitoring stopped.\n");
    return 0;
}

