#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
int initialize_gpio();
SensorStates read_sensor_states();
double calculate_rpm(SensorStates previous_states, SensorStates current_states);
void log_data(SensorStates current_states, double rpm);
void cleanup();
void signal_handler(int signal);

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Enable pull-up resistors on the GPIO pins
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the current states of the Hall-Effect sensors
SensorStates read_sensor_states() {
    SensorStates states;
    states.sensor1_state = gpioRead(SENSOR1_GPIO);
    states.sensor2_state = gpioRead(SENSOR2_GPIO);
    return states;
}

// Function to calculate the RPM based on the sensor states
double calculate_rpm(SensorStates previous_states, SensorStates current_states) {
    static int last_state1 = 0; // Store the last known state of sensor 1
    static int last_state2 = 0; // Store the last known state of sensor 2

    int state1_diff = current_states.sensor1_state != last_state1;
    int state2_diff = current_states.sensor2_state != last_state2;

    if (state1_diff || state2_diff) {
        // Debounce the sensor states
        gpioDelay(DEBOUNCE_TIME * 1000); // Convert milliseconds to microseconds

        int debounced_state1 = gpioRead(SENSOR1_GPIO);
        int debounced_state2 = gpioRead(SENSOR2_GPIO);

        if (debounced_state1 != previous_states.sensor1_state) {
            state1_diff = 1; // Consider it a valid change after debounce
        }
        if (debounced_state2 != previous_states.sensor2_state) {
            state2_diff = 1; // Consider it a valid change after debounce
        }

        if (state1_diff || state2_diff) {
            // Calculate RPM based on the change in sensor states
            if (state1_diff && state2_diff) {
                // Both sensors changed state simultaneously, no RPM change
                return 0.0;
            } else if (state1_diff) {
                // Only sensor 1 changed state
                return 60.0; // Assuming a 6-pulse per revolution setup
            } else if (state2_diff) {
                // Only sensor 2 changed state
                return 60.0; // Assuming a 6-pulse per revolution setup
            }
        }
    }

    // Update the last known states
    last_state1 = current_states.sensor1_state;
    last_state2 = current_states.sensor2_state;

    return 0.0; // No RPM change
}

// Function to log the sensor data and calculated RPM to a CSV file
void log_data(SensorStates current_states, double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%.2f\n", timestamp, current_states.sensor1_state, current_states.sensor2_state, rpm);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Function to perform cleanup operations before exiting
void cleanup() {
    printf("Cleaning up and exiting...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Signal handler for Ctrl+C (SIGINT)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        running = 0;
        cleanup();
        exit(0);
    }
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write the CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1_state,sensor2_state,rpm\n");
    }

    SensorStates previous_states = {0, 0};
    double rpm = 0.0;

    // Main loop
    while (running) {
        SensorStates current_states = read_sensor_states();
        rpm = calculate_rpm(previous_states, current_states);
        log_data(current_states, rpm);
        previous_states = current_states;

        // Print RPM to the console
        printf("RPM: %.2f\n", rpm);

        gpioDelay(1000); // Delay for 1 second (1000 ms)
    }

    cleanup();
    return 0;
}

