#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define ALARM_PIN 27

// Define alarm duration (in seconds)
#define ALARM_DURATION 2

// Define log file name
#define LOG_FILE "bridge_integrity.log"

// Global variables
FILE *log_file = NULL;
int alarm_active = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int log_event(const char *event_type, const char *timestamp);
void activate_alarm();
void deactivate_alarm();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1_value;
    int sensor2_value;
} SensorData;

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    gpioWrite(ALARM_PIN, 0); // Initialize alarm to LOW
    return 0; // Indicate success
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log event to file
int log_event(const char *event_type, const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1; // Indicate failure
    }

    fprintf(log_file, "%s %s\n", timestamp, event_type);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0; // Indicate success
}

// Function to activate alarm
void activate_alarm() {
    if (!alarm_active) {
        gpioWrite(ALARM_PIN, 1); // Activate alarm (HIGH)
        alarm_active = 1;
        log_event("ALARM_ACTIVATED", "ALARM_ACTIVATED");
    }
}

// Function to deactivate alarm
void deactivate_alarm() {
    if (alarm_active) {
        gpioWrite(ALARM_PIN, 0); // Deactivate alarm (LOW)
        alarm_active = 0;
        log_event("ALARM_DEACTIVATED", "ALARM_DEACTIVATED");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1; // Exit if log file opening fails
    }

    SensorData sensor_data;
    time_t start_time = 0;
    int threshold_exceeded = 0;

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        // Read sensor values
        sensor_data.sensor1_value = read_sensor(SENSOR1_PIN);
        sensor_data.sensor2_value = read_sensor(SENSOR2_PIN);

        // Get current timestamp
        time_t current_time = time(NULL);
        struct tm *time_info = localtime(&current_time);
        char timestamp[20]; // YYYY-MM-DDTHH:MM:SS\0
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

        // Check for tilt start event
        if (sensor_data.sensor1_value == 1 || sensor_data.sensor2_value == 1) {
            if (!threshold_exceeded) {
                log_event("TILOT_START", timestamp);
                start_time = current_time;
                threshold_exceeded = 1;
            }
        } else {
            threshold_exceeded = 0;
        }

        // Check for threshold exceeded event
        if (threshold_exceeded && (current_time - start_time) >= ALARM_DURATION) {
            log_event("THRESHOLD_EXCEEDED", timestamp);
            activate_alarm();
        } else if (threshold_exceeded && (current_time - start_time) < ALARM_DURATION) {
            // Do nothing, just wait
        } else if (!threshold_exceeded) {
            // Do nothing, just wait
        } else {
            // Check for tilt end event
            if (sensor_data.sensor1_value == 0 && sensor_data.sensor2_value == 0) {
                log_event("TILOT_END", timestamp);
