    if (!alarm_active) {
        gpioWrite(ALARM_PIN, 1); // Activate alarm (HIGH)
        alarm_active = 1;
        log_event("ALARM_ACTIVATED", "ALARM_ACTIVATED");
    }
}

// Function to deactivate alarm
void deactivate_alarm() {
    if (alarm_active) {
        gpioWrite(ALARM_PIN, 0); // Deactivate alarm (LOW)
        alarm_active = 0;
        log_event("ALARM_DEACTIVATED", "ALARM_DEACTIVATED");
    }
}

