#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x4C
#define CTRL1_REG 0x10
#define CTRL2_REG 0x11
#define DATA_REG 0x02
#define ALERT_LED_GPIO 17
#define THRESHOLD 500
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *data);
int detect_event(int *data);
void log_event(int *data);
void alert_led(int on);
void signal_handler(int signal);

// Structure for sensor data (example)
typedef struct {
    int x;
    int y;
    int z;
} sensor_data_t;

// Function to initialize the sensor
int initialize_sensor() {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        // Verify sensor presence (read CTRL1 register)
        int ctrl1_value = i2cReadByteData(i2c_handle, CTRL1_REG);
        if (ctrl1_value >= 0) {
            // Check if the sensor is powered on (CTRL1[0] is 0)
            if ((ctrl1_value & 0x01) == 0) {
                // Clear power-down bit (CTRL1[0])
                if (i2cWriteByteData(i2c_handle, CTRL1_REG, 0x01) >= 0) {
                    printf("Sensor initialized successfully.\n");
                    return 0; // Success
                } else {
                    fprintf(stderr, "Error clearing power-down bit. Retrying...\n");
                }
            } else {
                fprintf(stderr, "Sensor not powered on. Retrying...\n");
            }
        } else {
            fprintf(stderr, "Error reading CTRL1 register. Retrying...\n");
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries--;
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Function to read sensor data
int read_sensor_data(int *data) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        int raw_data = i2cReadWordData(i2c_handle, DATA_REG);
        if (raw_data >= 0) {
            // Convert raw data to signed 16-bit integers
            data[0] = (int16_t)raw_data;
            data[1] = (int16_t)(raw_data >> 2); // Shift right by 2 bits
            data[2] = (int16_t)(raw_data >> 4); // Shift right by 4 bits
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries--;
    }
    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Function to detect earthquake-like events
int detect_event(int *data) {
    // Calculate the Euclidean magnitude of the vibration
    double magnitude = sqrt(pow(data[0], 2) + pow(data[1], 2) + pow(data[2], 2));

    // Check if the magnitude exceeds the threshold
    if (magnitude > THRESHOLD) {
        return 1; // Event detected
    } else {
        return 0; // No event detected
    }
}

// Function to log events to a file
void log_event(int *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, data[0], data[1], data[2]);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Function to control the alert LED
void alert_led(int on) {
    gpioWrite(ALERT_LED_GPIO, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for the alert LED
    gpioSetMode(ALERT_LED_GPIO, PI_OUTPUT);

    // Open the log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int sensor_data[3];
    int event_detected;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Detect event
            event_detected = detect_event(sensor_data);

            // Log event if detected
            if (event_detected) {
                log_event(sensor_data);
                printf("Event detected! Magnitude: %.2f\n", sqrt(pow(sensor_data[0], 2) + pow(sensor_data[1], 2) + pow(sensor_data[2], 2)));
                alert_led(1); // Turn on LED
                gpioDelay(1000 * 1000); // Wait for 1 second
                alert_led(0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 100ms.\n");
        }

        gpioDelay(100 * 1000); // Poll every 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

