#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the flame sensors
#define SENSOR1_PIN 2
#define SENSOR2_PIN 3
#define SENSOR3_PIN 4
#define SENSOR4_PIN 17
#define SENSOR5_PIN 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Log file path
#define LOG_FILE "/var/log/flame_events.log"

// Global variables
static volatile sig_atomic_t terminate = 0;
static int sensor_lines[5] = {0}; // Array to store file descriptors for each sensor
static int sensor_fds[5] = {0}; // Array to store file descriptors for each sensor
static int sensor_pins[5] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN, SENSOR5_PIN};

// Function prototypes
void signal_handler(int signal);
int initialize();
void cleanup();
void log_event(int sensor_id, const char *message);
void read_sensor(int pin, int *value);
int acquire_line(int sensor_id);
int release_line(int sensor_id);
int open_sensor(int sensor_id);
int get_line(int sensor_id, char *line, int max_len);
int request_line(int sensor_id);
int read_line(int sensor_id, char *line, int max_len);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_USER | LOG_PID, "Signal received: %d. Terminating...", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    syslog(LOG_USER | LOG_PID, "Cleaning up resources...");

    // Release all acquired lines
    for (int i = 0; i < 5; i++) {
        if (sensor_fds[i] > 0) {
            release_line(i);
        }
    }

    // Close the chip
    gpioTerminate();

    // Close syslog
    closelog();
}

// Log event function
void log_event(int sensor_id, const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s - Sensor ID: %d (GPIO %d) - %s", buf, sensor_id, sensor_pins[sensor_id], message);

    syslog(LOG_USER | LOG_PID, "%s", log_message);
    printf("%s\n", log_message);
}

