#include <pigpio.h>

// Define the GPIO pins for the touch sensor channels
const int touch_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_pins = sizeof(touch_pins) / sizeof(touch_pins[0]);

// Structure to hold the previous touch states
struct {
    int previous_states[8];
} last_states;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a touch event
void log_touch_event(int sensor_index, int pin, int state) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return;
    }

    if (state == 1) {
        printf("%s Sensor %d (BCM %d) - Touch Detected\n", timestamp, sensor_index, pin);
    } else {
        printf("%s Sensor %d (BCM %d) - Touch Released\n", timestamp, sensor_index, pin);
    }

    free(timestamp);
}

// Function to read the touch sensor state
int read_touch_sensor(int pin) {
    int state = gpioRead(pin);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1; // Indicate an error
    }
    return state;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set the GPIO pins as inputs
    for (int i = 0; i < num_pins; i++) {
        gpioSetMode(touch_pins[i], PI_INPUT);
    }

    // Initialize the previous touch states
    for (int i = 0; i < num_pins; i++) {
        last_states.previous_states[i] = read_touch_sensor(touch_pins[i]);
        if (last_states.previous_states[i] < 0) {
            fprintf(stderr, "Error initializing previous states, exiting\n");
            gpioTerminate();
            return 1;
        }
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        for (int i = 0; i < num_pins; i++) {
            int current_state = read_touch_sensor(touch_pins[i]);
            if (current_state < 0) {
                fprintf(stderr, "Error reading sensor %d, continuing...\n", i);
                continue; // Continue to the next sensor
            }

            if (current_state != last_states.previous_states[i]) {
                log_touch_event(i, touch_pins[i], current_state);
                last_states.previous_states[i] = current_state; // Update previous state
            }
        }

        gpioDelay(50); // Wait 50 milliseconds
    }

    // The program should never reach here, but it's good practice to include gpioTerminate()
    gpioTerminate();
    return 0;
}

