#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define GPIO_LED 18
#define PWM_FREQUENCY 1000
#define LOG_FILE "grow_log.txt"

// VEML7700 Registers
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_sensor();
int read_lux();
int map_lux_to_brightness(int lux);
int set_brightness(int brightness);
int log_data(int lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    uint16_t integration_time;
    uint16_t gain;
} sensor_config_t;

// Function to initialize the sensor configuration
int init_sensor() {
    // Example configuration: Integration time = 100ms, Gain = 1/8
    sensor_config_t config = {
        .integration_time = 0x00, // 100ms
        .gain = 0x08  // 1/8
    };

    // Write the configuration to the sensor
    char buf[3];
    buf[0] = VEML7700_CONFIG;
    buf[1] = config.integration_time;
    buf[2] = config.gain;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read lux value from the sensor
int read_lux() {
    char buf[1];
    char data[2];

    // Read ALS data register
    buf[0] = VEML7700_ALS_DATA;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 ALS data register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from VEML7700 ALS data register: %d\n", result);
        return -1;
    }

    // Combine the two bytes to form the lux value
    uint16_t als_data = (data[1] << 8) | data[0];

    // Apply lux calculation formula (example, adjust as needed)
    float lux = (float)als_data * 0.0576; // Example conversion factor

    return (int)lux;
}

// Function to map lux value to brightness level
int map_lux_to_brightness(int lux) {
    if (lux < 100) {
        return 100;
    } else if (lux < 500) {
        return 75;
    } else if (lux < 1000) {
        return 50;
    } else {
        return 25;
    }
}

// Function to set the LED brightness using PWM
int set_brightness(int brightness) {
    if (brightness < 0 || brightness > 100) {
        fprintf(stderr, "Invalid brightness value: %d\n", brightness);
        return -1;
    }

    int dutycycle = (int)((brightness / 100.0) * 255.0); // pigpio PWM range is 0-255
    gpioPWM(GPIO_LED, dutycycle);
    return 0;
}

// Function to log data to file
int log_data(int lux, int brightness, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    set_brightness(0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int lux = read_lux();
