#define VEML7700_ALS_DATA 0x04

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_sensor();
int read_lux();
int map_lux_to_brightness(int lux);
int set_brightness(int brightness);
int log_data(int lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    uint16_t integration_time;
    uint16_t gain;
} sensor_config_t;

// Function to initialize the sensor configuration
int init_sensor() {
    // Example configuration: Integration time = 100ms, Gain = 1/8
    sensor_config_t config = {
        .integration_time = 0x00, // 100ms
        .gain = 0x08  // 1/8
    };

    // Write the configuration to the sensor
    char buf[3];
    buf[0] = VEML7700_CONFIG;
    buf[1] = config.integration_time;
    buf[2] = config.gain;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read lux value from the sensor
int read_lux() {
    char buf[1];
    char data[2];

    // Read ALS data register
    buf[0] = VEML7700_ALS_DATA;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 ALS data register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from VEML7700 ALS data register: %d\n", result);
        return -1;
    }

    // Combine the two bytes to form the lux value
    uint16_t als_data = (data[1] << 8) | data[0];

    // Apply lux calculation formula (example, adjust as needed)
    float lux = (float)als_data * 0.0576; // Example conversion factor

    return (int)lux;
}

