#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for touch sensor channels and LED
#define TOUCH_CHANNEL_1 2
#define TOUCH_CHANNEL_2 3
#define TOUCH_CHANNEL_3 4
#define TOUCH_CHANNEL_4 5
#define TOUCH_CHANNEL_5 6
#define TOUCH_CHANNEL_6 7
#define TOUCH_CHANNEL_7 8
#define TOUCH_CHANNEL_8 9
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static volatile unsigned long last_touch_time = 0;

// Function prototypes
int initialize_gpio();
int read_touch_channel(int channel);
int debounce_touch_channel(int channel);
int log_touch_event(int channel);
int control_led(int state);
void signal_handler(int signal);

// Structure to hold GPIO pin configurations
typedef struct {
    int touch_channels[8];
    int led_pin;
} gpio_config_t;

// Global GPIO configuration
gpio_config_t gpio_config = {
    {TOUCH_CHANNEL_1, TOUCH_CHANNEL_2, TOUCH_CHANNEL_3, TOUCH_CHANNEL_4, TOUCH_CHANNEL_5, TOUCH_CHANNEL_6, TOUCH_CHANNEL_7, TOUCH_CHANNEL_8},
    LED_PIN
};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio library.\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read touch sensor channels
        for (int i = 0; i < 8; i++) {
            if (debounce_touch_channel(gpio_config.touch_channels[i]) == 0) {
                log_touch_event(i + 1);
            }
        }

        // Poll the LED pin every 50ms
        gpioDelay(50); // pigpio's delay function
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set touch sensor channels as inputs with pull-down resistors
    for (int i = 0; i < 8; i++) {
        gpioSetMode(gpio_config.touch_channels[i], PI_INPUT);
        gpioSetPullUpDown(gpio_config.touch_channels[i], PI_PUD_DOWN);
    }

    // Set LED pin as output
    gpioSetMode(gpio_config.led_pin, PI_OUTPUT);

    return 0;
}

// Function to read the state of a touch sensor channel
int read_touch_channel(int channel) {
    return gpioRead(channel);
}

// Function to debounce a touch sensor channel
int debounce_touch_channel(int channel) {
    int current_state = read_touch_channel(channel);
    unsigned long current_time = gpioTick();

    if (current_state == 1) {
        if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) {
            last_touch_time = current_time;
            return 1; // Valid touch
        }
    }

    return 0; // No valid touch
}

// Function to log a touch event to a file
int log_touch_event(int channel) {
    FILE *fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening touch_log.txt for writing.\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s – Channel %d Touched\n", timestamp, channel);
    fclose(fp);

    return 0;
}

// Function to control the LED
int control_led(int state) {
    gpioWrite(gpio_config.led_pin, state);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

