#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_VALUE 0xCB10 // Continuous conversion mode, 100ms conversion time
#define LUX_SCALE 0.01
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int write_config();
int read_result(uint16_t *raw_value);
float convert_to_lux(uint16_t raw_value);
int format_data(float lux_value, char *buffer, size_t buffer_size);
int write_to_log(const char *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Write configuration to OPT3001
int write_config() {
    char buf[2];
    uint16_t config_value = (uint16_t)CONFIG_VALUE; // Cast to uint16_t

    // Byte swap for big-endian to little-endian conversion
    buf[0] = (config_value >> 8) & 0xFF; // MSB
    buf[1] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write configuration: %d\n", result);
        return -1;
    }

    return 0;
}

// Read result from OPT3001
int read_result(uint16_t *raw_value) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Failed to read result: %d\n", result);
        return -1;
    }

    // Byte swap for big-endian to little-endian conversion
    *raw_value = (buf[0] << 8) | buf[1];

    return 0;
}

// Convert raw value to lux
float convert_to_lux(uint16_t raw_value) {
    uint16_t exponent = (raw_value >> 12) & 0x0F;
    uint16_t mantissa = raw_value & 0x0FFF;

    return mantissa * (LUX_SCALE * (1 << exponent));
}

// Format data into string
int format_data(float lux_value, char *buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    if (strftime(buffer, buffer_size, "%Y-%m-%d %H:%M:%S, %.2f", timeinfo) == 0) {
        fprintf(stderr, "Failed to format data\n");
        return -1;
    }

    return 0;
}

// Write data to log file
int write_to_log(const char *data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", data) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write configuration
    if (write_config() != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting light sensor data logging...\n");

    while (!terminate) {
        uint16_t raw_value;
        float lux_value;
        char data_buffer[100];

        // Read result
        if (read_result(&raw_value) == 0) {
            // Convert to lux
            lux_value = convert_to_lux(raw_value);

            // Format data
            if (format_data(lux_value, data_buffer, sizeof(data_buffer)) == 0) {
                // Write to log file
                if (write_to_log(data_buffer) != 0) {
                    fprintf(stderr, "Failed to write data to log file\n");
                }

                // Print to stdout
                printf("%s", data_buffer);
            } else {
                fprintf(stderr, "Failed to format data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

