#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define DEBOUNCE_MS 50
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;

// Function to get the current timestamp in the format YYYY-MM-DD HH:MM:SS:nanoseconds
char* get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    time_t t = ts.tv_sec;
    struct tm tm_info;
    localtime_r(&t, &tm_info);
    static char timestamp[30]; // Ensure static allocation to avoid stack overflow
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);
    return timestamp;
}

// Function to log the touch event to the log file
int log_touch_event(const char* event_type) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    char* timestamp = get_timestamp();
    fprintf(fp, "%s: %s\n", timestamp, event_type);
    if (ferror(fp)) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file\n");
        return -1;
    }

    return 0;
}

// Callback function for touch events
void touch_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge (touch detected)
        if (log_touch_event("Touch Detected") != 0) {
            fprintf(stderr, "Error logging touch detected event\n");
        }
    } else if (level == 0) { // Falling edge (touch released)
        if (log_touch_event("Touch Released") != 0) {
            fprintf(stderr, "Error logging touch released event\n");
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as an input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Enable pull-down resistor
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Set up interrupt on GPIO4
    if (gpioSetAlertFunc(GPIO_PIN, touch_callback) != 0) {
        fprintf(stderr, "Error setting alert function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(DEBOUNCE_MS * 1000); // Delay for debounce interval
    }

    // Clean up and exit
    gpioSetAlertFunc(GPIO_PIN, NULL); // Disable callback
    gpioTerminate(); // Terminate pigpio

    return 0;
}

