#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define MEASURE_CMD 0x3608
#define FLOW_MIN 0.0
#define FLOW_MAX 100.0
#define LOG_FILE "cooling_log.csv"

int i2c_handle;
FILE *log_file;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(int i2c_handle, float *flow_rate, uint8_t *flags, char *status) {
    uint8_t buffer[3];
    int result;

    // Read 3 bytes from the sensor
    result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1; // Indicate I2C read error
    }

    // Extract flow rate and CRC
    int16_t flow_raw = (buffer[0] << 8) | buffer[1];
    uint8_t crc = buffer[2];

    // CRC validation
    uint8_t calculated_crc = crc8(buffer, 2);
    if (crc != calculated_crc) {
        fprintf(stderr, "CRC error: calculated 0x%02X, received 0x%02X\n", calculated_crc, crc);
        strcpy(status, "ERROR");
        return -1; // Indicate CRC error
    }

    // Convert flow rate to ml/min (refer to SLF3S‑1300F datasheet)
    *flow_raw = flow_raw; // Placeholder, replace with actual conversion
    *flow_rate = (float)*flow_raw; // Placeholder, replace with actual conversion

    // Validate flow rate range
    if (*flow_rate < FLOW_MIN || *flow_rate > FLOW_MAX) {
        strcpy(status, "INVALID");
        return -1; // Indicate out-of-range value
    }

    // Extract flags (assuming flags are in the first byte)
    *flags = buffer[0];

    strcpy(status, "OK");
    return 0; // Indicate success
}

// Function to log data to a CSV file
int log_data(FILE *log_file, float flow_rate, uint8_t flags, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%u,%s\n", timestamp, flow_rate, flags, status);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    float flow_rate;
    uint8_t flags;
    char status[20];
    int retry_count;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        retry_count = 0;
        do {
            if (read_sensor_data(i2c_handle, &flow_rate, &flags, status) == 0) {
                log_data(log_file, flow_rate, flags, status);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Error reading sensor data, retrying...\n");
                retry_count++;
                if (retry_count < 3) {
                    gpioDelay(100); // Wait 100ms before retrying
                } else {
                    fprintf(stderr, "Max retries reached, exiting.\n");
                    break; // Exit main loop after max retries
                }
            }
        } while (retry_count < 3);

        if (retry_count >= 3) {
            fprintf(stderr, "Max retries reached, exiting.\n");
            break; // Exit main loop after max retries
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

