#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 23
#define LED_PIN 24
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the touch event to a file
int log_touch_event(const char* timestamp, int led_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s, LED: %s\n", timestamp, led_state ? "ON" : "OFF");
    fclose(fp);
    return 0;
}

// Function to toggle the LED state
int toggle_led(int current_state) {
    return !current_state;
}

int main() {
    int touch_state = 0;
    int led_state = 0;
    char* timestamp;
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Main loop
    while (running) {
        // Read touch sensor state
        touch_state = gpioRead(TOUCH_PIN);

        // Check for rising edge (active-high)
        if (touch_state == 1 && gpioRead(TOUCH_PIN) == 0) {
            // Debounce: Wait for the touch to release
            while (gpioRead(TOUCH_PIN) == 1 && running) {
                gpioDelay(1000); // Wait 1ms
            }

            // Toggle LED state
            led_state = toggle_led(led_state);

            // Get timestamp
            timestamp = get_iso8601_timestamp();
            if (timestamp == NULL) {
                fprintf(stderr, "Failed to get timestamp\n");
                continue; // Skip logging if timestamp fails
            }

            // Log the event
            if (log_touch_event(timestamp, led_state) != 0) {
                fprintf(stderr, "Failed to log touch event\n");
            }

            free(timestamp); // Free the allocated memory

            // Wait for 1 second
            gpioDelay(1000000); // 1 second = 1000000 microseconds
        } else {
            gpioDelay(100000); // Check every 0.1 seconds
        }
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio

    printf("Program terminated.\n");
    return 0;
}

