#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define LOG_FILE "alert_log.txt"
#define POLL_INTERVAL_MS 100

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Signal received, shutting down...\n");
    running = 0;
}

// Function to log messages to the alert log file
void log_message(const char *message) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file); // Ensure the message is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is initially off

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Function to activate the buzzer for 2 seconds
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    gpioDelay(2000);           // Wait for 2 seconds
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
}

// Function to log a flame detection event
void log_flame_detection() {
    log_message("FLAME DETECTED");
}

// Function to check for shutdown signals
void check_shutdown() {
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        gpioTerminate();
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(EXIT_FAILURE);
    }
}

int main() {
    // Check if the program is run with root privileges
    if (geteuid() != 0) {
        fprintf(stderr, "This program must be run with root privileges. Use sudo.\n");
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Write the "System started" message to the log file
    log_message("System started");

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message("GPIO initialization failed");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Check for shutdown signals
    check_shutdown();

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) { // Flame detected (active-low)
            log_flame_detection();
            activate_buzzer();
        }

        gpioDelay(POLL_INTERVAL_MS); // Wait before next poll
    }

    // Cleanup
    log_message("System stopped");
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();           // Terminate pigpio
    fclose(log_file);           // Close the log file

    return 0;
}

