FILE *log_file = NULL;
sensor_data_t sensors[] = {
    {SENSOR1_GPIO, 1, -1},
    {SENSOR2_GPIO, 2, -1},
    {SENSOR3_GPIO, 3, -1}
};
int num_sensors = sizeof(sensors) / sizeof(sensors[0]);

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int log_state_change(int sensor_id, int state);
void signal_handler(int signal);
void cleanup();

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

