        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        for (int i = 0; i < num_sensors; i++) {
            int current_state = read_sensor(sensors[i].gpio);

            if (current_state == -1) {
                fprintf(stderr, "Error reading sensor %d\n", sensors[i].sensor_id);
