            }

            if (current_state != sensors[i].last_state) {
                if (log_state_change(sensors[i].sensor_id, current_state) != 0) {
                    fprintf(stderr, "Error logging state change for sensor %d\n", sensors[i].sensor_id);
                }
                sensors[i].last_state = current_state;
            }
        }

        gpioDelay(100); // Poll every 100ms
    }

    return 0;
}

