    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < num_sensors; i++) {
        if (gpioSetMode(sensors[i].gpio, PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", sensors[i].gpio);
            return 1;
        }
        if (gpioSetPullUpDown(sensors[i].gpio, PI_PUD_UP) != 0) {
