#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define PART_ID 0x00
#define HW_REV 0x01
#define HEART_RATE_REG 0x24
#define MOVING_AVG_SIZE 5
#define BPM_MIN 30
#define BPM_MAX 220
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    uint8_t part_id;
    uint8_t hw_rev;
    uint8_t led_drive_strength;
    uint8_t led_pulse_width;
    uint8_t led_pulse_period;
    uint8_t led_drive_strength2;
    uint8_t led_pulse_width2;
    uint8_t led_pulse_period2;
} sensor_config_t;

// Function prototypes
int initialize_sensor();
int configure_sensor(sensor_config_t config);
int read_sensor_data(uint16_t *heart_rate);
int validate_bpm(uint16_t bpm);
int log_data(uint16_t bpm);
void signal_handler(int signal);
int read_register(uint8_t reg, uint8_t *value);
int write_register(uint8_t reg, uint8_t value);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Read a single byte from a register
int read_register(uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Write a single byte to a register
int write_register(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Initialize the sensor
int initialize_sensor() {
    uint8_t part_id, hw_rev;

    if (read_register(PART_ID, &part_id) != 0 || read_register(HW_REV, &hw_rev) != 0) {
        fprintf(stderr, "Error reading sensor ID. Check if sensor is present.\n");
        return -1;
    }

    if (part_id != 0x53 || hw_rev != 0x01) {
        fprintf(stderr, "Incorrect sensor ID. Check if sensor is present and correctly connected.\n");
        return -1;
    }

    printf("Sensor initialized successfully. Part ID: 0x%02X, HW Rev: 0x%02X\n", part_id, hw_rev);
    return 0;
}

// Configure the sensor
int configure_sensor(sensor_config_t config) {
    if (write_register(0x02, config.led_drive_strength) != 0) return -1;
    if (write_register(0x03, config.led_pulse_width) != 0) return -1;
    if (write_register(0x04, config.led_pulse_period) != 0) return -1;
    if (write_register(0x06, config.led_drive_strength2) != 0) return -1;
    if (write_register(0x07, config.led_pulse_width2) != 0) return -1;
    if (write_register(0x08, config.led_pulse_period2) != 0) return -1;

    return 0;
}

// Read heart rate data
int read_sensor_data(uint16_t *heart_rate) {
    uint8_t msb, lsb;

    if (read_register(HEART_RATE_REG, &msb) != 0) return -1;
    if (read_register(HEART_RATE_REG + 1, &lsb) != 0) return -1;

    *heart_rate = ((uint16_t)msb << 8) | (uint16_t)lsb;
    return 0;
}

// Validate BPM
int validate_bpm(uint16_t bpm) {
    return (bpm >= BPM_MIN && bpm <= BPM_MAX);
}

// Log data to file
int log_data(uint16_t bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, bpm);
    fflush(log_file);

    return 0;
}

int main() {
    uint16_t heart_rate, filtered_heart_rate;
    sensor_config_t config = {0x53, 0x01, 0x3F, 0x10, 0x05, 0x3F, 0x10, 0x05}; // Example config

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(config) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,BPM\n");
    }
    fflush(log_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&heart_rate) == 0) {
            // Apply moving average filter
            int sum = 0;
            for (int i = 0; i < MOVING_AVG_SIZE; i++) {
                int retry = 0;
                while (retry < RETRY_COUNT) {
                    if (read_sensor_data(&filtered_heart_rate) == 0) {
                        sum += filtered_heart_rate;
                        break;
                    } else {
                        fprintf(stderr, "Retrying I2C read...\n");
                        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                        retry++;
                    }
                }
                if (retry == RETRY_COUNT) {
                    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
                    continue; // Skip to the next iteration
                }
            }
            filtered_heart_rate = sum / MOVING_AVG_SIZE;

            // Validate BPM
            if (validate_bpm(filtered_heart_rate)) {
                // Log data
                if (log_data(filtered_heart_rate) != 0) {
                    fprintf(stderr, "Error logging data!\n");
                }
            } else {
                fprintf(stderr, "Invalid BPM value: %u\n", filtered_heart_rate);
            }
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

