#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN_1 5
#define SENSOR_PIN_2 6
#define SENSOR_PIN_3 7
#define SENSOR_PIN_4 8
#define SENSOR_PIN_5 9
#define SENSOR_PIN_6 10
#define SENSOR_PIN_7 11
#define SENSOR_PIN_8 12
#define OUTPUT_PIN_0 17
#define OUTPUT_PIN_1 18
#define OUTPUT_PIN_2 19
#define OUTPUT_PIN_3 20
#define OUTPUT_PIN_4 21
#define OUTPUT_PIN_5 22
#define OUTPUT_PIN_6 23
#define OUTPUT_PIN_7 24
#define OUTPUT_PIN_8 25

// Define GPIO pins for SPI communication with MCP3008
#define SPI_CE 8  // Chip Enable pin for MCP3008
#define SPI_MOSI 10 // Master Out Slave In
#define SPI_MISO 9  // Master In Slave Out
#define SPI_SCLK 11 // Serial Clock

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 channel for ADC
#define ADC_CHANNEL 0

// Define ADC reference voltage
#define ADC_REF_VOLTAGE 3.3

// Define counter pins
#define COUNTER_PIN_0 0 // Output pin 0
#define COUNTER_PIN_1 1 // Output pin 1
#define COUNTER_PIN_2 2 // Output pin 2
#define COUNTER_PIN_3 3 // Output pin 3
#define COUNTER_PIN_4 4 // Output pin 4
#define COUNTER_PIN_5 5 // Output pin 5
#define COUNTER_PIN_6 6 // Output pin 6
#define COUNTER_PIN_7 7 // Output pin 7

// Define SPI handle
int spi_handle;

// Global variables
volatile int counter = 0;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int pin);
int write_output(int pin, int value);
int spi_read_adc(int channel);
int spi_write(int channel, int value);
int update_output_pins();
int log_event(int channel, int counter);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read a sensor pin
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor pin %d: %s\n", pin, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to write to an output pin
int write_output(int pin, int value) {
    int result = gpioWrite(pin, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to output pin %d: %s\n", pin, strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

// Function to read from MCP3008 ADC via SPI
int spi_read_adc(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message to read from MCP3008
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to write to MCP3008 via SPI
int spi_write(int channel, int value) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message to write to MCP3008
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel << 4)) | value; // Single-ended mode, channel select, value
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    return 0;
}

// Function to update the output pins based on the counter
int update_output_pins() {
    for (int i = 0; i < 8; i++) {
        int pin = OUTPUT_PIN_i; // Define OUTPUT_PIN_i
        int value = (counter >> i) & 1; // Determine output value
        if (write_output(pin, value) != 0) {
            fprintf(stderr, "Error writing to output pin %d\n", pin);
            return -1; // Indicate error
        }
    }
    return 0;
}

// Function to log the event to a file
int log_event(int channel, int counter) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    // Set sensor pins as inputs
    for (int i = 0; i < 8; i++) {
        int pin = SENSOR_PIN_i; // Define SENSOR_PIN_i
        gpioSetMode(pin, PI_INPUT);
        gpioSetPullUpDown(pin, PI_PUD_DOWN); // Enable pull-down resistor
    }

    // Set output pins as outputs
    for (int i = 0; i < 8; i++) {
        int pin = OUTPUT_PIN_i; // Define OUTPUT_PIN_i
        gpioSetMode(pin, PI_OUTPUT);
        gpioWrite(pin, 0); // Initialize to 0
    }

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Reset output pins
    for (int i = 0; i < 8; i++) {
        int pin = OUTPUT_PIN_i; // Define OUTPUT_PIN_i
        gpioWrite(pin, 0);
    }

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting.\n");
        return 1;
    }

    // Stabilization delay
    gpioDelay(200000); // 200 ms

    // Main loop
    while (1) {
        int touched = 0;
        for (int i = 0; i < 8; i++) {
            int pin = SENSOR_PIN_i; // Define SENSOR_PIN_i
            int sensor_value = read_sensor(pin);
            if (sensor_value < 0) {
                fprintf(stderr, "Error reading sensor pin %d, skipping.\n", pin);
                continue; // Skip to the next channel
            }

            if (sensor_value == 1) {
                touched = 1;
                break; // Exit the loop if any sensor is touched
            }
        }

        if (touched) {
            counter = (counter + 1) % 256; // Increment counter and wrap around
            if (update_output_pins() != 0) {
                fprintf(stderr, "Error updating output pins.\n");
            } else {
                if (log_event(i + 1, counter) != 0) {
                    fprintf(stderr, "Error logging event.\n");
                }
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
        }

        gpioDelay(10000); // 10 ms
    }

    return 0;
}

