        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    // Set sensor pins as inputs
    for (int i = 0; i < 8; i++) {
        int pin = SENSOR_PIN_i; // Define SENSOR_PIN_i
        gpioSetMode(pin, PI_INPUT);
        gpioSetPullUpDown(pin, PI_PUD_DOWN); // Enable pull-down resistor
    }

    // Set output pins as outputs
    for (int i = 0; i < 8; i++) {
        int pin = OUTPUT_PIN_i; // Define OUTPUT_PIN_i
        gpioSetMode(pin, PI_OUTPUT);
        gpioWrite(pin, 0); // Initialize to 0
    }

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Reset output pins
    for (int i = 0; i < 8; i++) {
        int pin = OUTPUT_PIN_i; // Define OUTPUT_PIN_i
        gpioWrite(pin, 0);
    }

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting.\n");
        return 1;
    }

    // Stabilization delay
    gpioDelay(200000); // 200 ms

    // Main loop
    while (1) {
        int touched = 0;
        for (int i = 0; i < 8; i++) {
            int pin = SENSOR_PIN_i; // Define SENSOR_PIN_i
            int sensor_value = read_sensor(pin);
            if (sensor_value < 0) {
                fprintf(stderr, "Error reading sensor pin %d, skipping.\n", pin);
                continue; // Skip to the next channel
            }

            if (sensor_value == 1) {
                touched = 1;
                break; // Exit the loop if any sensor is touched
            }
        }

        if (touched) {
            counter = (counter + 1) % 256; // Increment counter and wrap around
            if (update_output_pins() != 0) {
                fprintf(stderr, "Error updating output pins.\n");
            } else {
                if (log_event(i + 1, counter) != 0) {
                    fprintf(stderr, "Error logging event.\n");
                }
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
        }

        gpioDelay(10000); // 10 ms
    }

    return 0;
}

