#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 100

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in the required format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
void log_event(int sensor_number) {
    char *timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to cleanup the GPIO pins
void cleanup_gpio() {
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_OFF);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_OFF);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("/var/log/tilt_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    int last_state_1 = 1; // Initialize to active-low pull-up
    int last_state_2 = 1;
    int current_state_1, current_state_2;
    int edge_detected_1 = 0;
    int edge_detected_2 = 0;
    struct timespec last_edge_time_1, last_edge_time_2;
    clock_gettime(CLOCK_MONOTONIC, &last_edge_time_1);
    clock_gettime(CLOCK_MONOTONIC, &last_edge_time_2);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor 1
        current_state_1 = gpioRead(SENSOR_1_GPIO);
        if (current_state_1 < 0) {
            fprintf(stderr, "Error reading sensor 1\n");
            continue; // Continue to the next iteration
        }

        // Read sensor 2
        current_state_2 = gpioRead(SENSOR_2_GPIO);
        if (current_state_2 < 0) {
            fprintf(stderr, "Error reading sensor 2\n");
            continue; // Continue to the next iteration
        }

        // Debounce sensor 1
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long time_diff_ms = (now.tv_sec - last_edge_time_1.tv_sec) * 1000 + (now.tv_nsec - last_edge_time_1.tv_nsec) / 1000000;

        if (current_state_1 == 0 && last_state_1 == 1 && time_diff_ms >= DEBOUNCE_MS) {
            log_event(1);
            edge_detected_1 = 1;
        }

        // Debounce sensor 2
        clock_gettime(CLOCK_MONOTONIC, &now);
        time_diff_ms = (now.tv_sec - last_edge_time_2.tv_sec) * 1000 + (now.tv_nsec - last_edge_time_2.tv_nsec) / 1000000;

        if (current_state_2 == 0 && last_state_2 == 1 && time_diff_ms >= DEBOUNCE_MS) {
            log_event(2);
            edge_detected_2 = 1;
        }

        // Update last states
        last_state_1 = current_state_1;
        last_state_2 = current_state_2;

        // Poll interval
        gpioDelay(POLL_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    cleanup_gpio();

    printf("Exiting.\n");
    return 0;
}

