    int result = gpioWrite(gpio_pin, state);
    if (result < 0) {
        fprintf(stderr, "Error writing to LED on GPIO %d: %d\n", gpio_pin, result);
        return -1; // Indicate error
    }
    return 0;
}

// Function to log data to file
int log_data(FILE *fp, time_t timestamp, int sensor1, int sensor2, int led_state) {
    if (fprintf(fp, "%ld,%d,%d,%d\n", timestamp, sensor1, sensor2, led_state) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("obstacle_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensors, skipping this iteration.\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Determine LED state
        int led_state = (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;

        // Control LED
        if (control_led(LED_PIN, led_state) == -1) {
            fprintf(stderr, "Error controlling LED, skipping this iteration.\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Get current timestamp
        time_t current_time = time(NULL);

        // Log data
        if (log_data(log_file, current_time, sensor1_value, sensor2_value, led_state) == -1) {
            fprintf(stderr, "Error logging data, skipping this iteration.\n");
        }

        // Delay for 100ms
        gpioDelay(100000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

