#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_MIC 4
#define GPIO_LED 17
#define SAMPLE_PERIOD_US 125000 // 125 ms
#define LED_ON_TIME_MS 100

volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to detect sound peaks
int detect_peak(int gpio_pin) {
    int level = gpioRead(gpio_pin);
    return (level == 1) ? 1 : 0;
}

// Function to control the LED
void control_led(int gpio_pin, int on_time_ms) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(on_time_ms * 1000); // Wait for specified time
    gpioWrite(gpio_pin, 0); // Turn LED off
}

// Function to get the current timestamp in milliseconds
long long get_timestamp_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)(ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input
    if (gpioSetMode(GPIO_MIC, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_MIC);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Sampling started. Press Ctrl+C to exit.\n");

    // Sampling loop
    while (program_running) {
        if (detect_peak(GPIO_MIC)) {
            long long timestamp = get_timestamp_ms();
            printf("%lld: Sound peak detected\n", timestamp);
            control_led(GPIO_LED, LED_ON_TIME_MS);
        }
        gpioDelay(SAMPLE_PERIOD_US); // Delay to achieve 8kHz sampling rate
    }

    // Clean up and exit
    gpioWrite(GPIO_LED, 0); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio

    printf("Program terminated.\n");
    return 0;
}

