#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 17
#define CENTER_SENSOR 27
#define RIGHT_SENSOR 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor values
int read_sensors() {
    int left_value = gpioRead(LEFT_SENSOR);
    int center_value = gpioRead(CENTER_SENSOR);
    int right_value = gpioRead(RIGHT_SENSOR);

    if (left_value < 0 || center_value < 0 || right_value < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        return -1; // Indicate an error
    }

    return (left_value << 10) | (center_value << 5) | right_value;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetPullUpDown(CENTER_SENSOR, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    // Main loop to read and log sensor data
    while (program_running) {
        int sensor_data = read_sensors();

        if (sensor_data >= 0) {
            printf("Left: %d, Center: %d, Right: %d\n", (sensor_data >> 10) & 0x1FF, (sensor_data >> 5) & 0x1FF, sensor_data & 0x1FF);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(100); // Wait for 100 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

