#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a register from the Si1175
int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a register to the Si1175
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read the ALS data from the Si1175
int read_als_data(int handle, uint16_t *als_data) {
    int lsb = read_register(handle, REG_ALS_VIS_DATA0);
    int msb = read_register(handle, REG_ALS_VIS_DATA1);

    if (lsb < 0 || msb < 0) {
        return -1;
    }

    *als_data = (uint16_t)((msb << 8) | lsb);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t als_data;
        int result = read_als_data(i2c_handle, &als_data);

        if (result == 0) {
            printf("ALS Data: 0x%04X\n", als_data);
        } else {
            fprintf(stderr, "Error reading ALS data\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup (should not reach here in normal execution due to the signal handler)
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

