#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_PIN 2
#define MIDDLE_PIN 3
#define RIGHT_PIN 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int left_value, middle_value, right_value;
    int left_fd, middle_fd, right_fd;
    int left_result, middle_result, right_result;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_PIN, PI_INPUT);
    gpioSetMode(RIGHT_PIN, PI_INPUT);

    // Main loop
    while (!terminate) {
        // Open GPIO pins for reading
        left_fd = gpioSetMode(LEFT_PIN, PI_INPUT);
        middle_fd = gpioSetMode(MIDDLE_PIN, PI_INPUT);
        right_fd = gpioSetMode(RIGHT_PIN, PI_INPUT);

        if (left_fd != 0 || middle_fd != 0 || right_fd != 0) {
            fprintf(stderr, "Failed to set GPIO mode. Exiting.\n");
            break;
        }

        // Read sensor values
        left_result = gpioRead(LEFT_PIN);
        middle_result = gpioRead(MIDDLE_PIN);
        right_result = gpioRead(RIGHT_PIN);

        if (left_result < 0 || middle_result < 0 || right_result < 0) {
            fprintf(stderr, "Failed to read GPIO value. Exiting.\n");
            break;
        }

        // Log sensor values
        printf("L:%d M:%d R:%d\n", left_result, middle_result, right_result);

        // Close GPIO pins (optional, but good practice)
        gpioSetMode(LEFT_PIN, PI_INPUT); // Revert to input mode
        gpioSetMode(MIDDLE_PIN, PI_INPUT);
        gpioSetMode(RIGHT_PIN, PI_INPUT);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

