#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the touch sensor channels
#define TP1 5
#define TP2 6
#define TP3 13
#define TP4 19
#define TP5 26
#define TP6 12
#define TP7 16
#define TP8 20

// Structure to hold the last read time for each channel
struct timespec last_read_time[8];

// Function prototypes
int read_touch_sensor(int gpio_pin);
int get_timestamp(char *timestamp_str, size_t timestamp_str_size);
int format_output(char *output_str, size_t output_str_size, int *channel_values, size_t num_channels);
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("\nCaught signal %d, exiting gracefully...\n", signal);
    }
}

// Function to read the state of a single GPIO pin
int read_touch_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp in the format "HH:MM:SS.nanoseconds"
int get_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1; // Indicate an error
    }

    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        perror("localtime_r");
        return -1; // Indicate an error
    }

    if (strftime(timestamp_str, timestamp_str_size, "%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1; // Indicate an error
    }

    snprintf(timestamp_str + strlen(timestamp_str), timestamp_str_size - strlen(timestamp_str), ".%09ld", ts.tv_nsec);

    return 0; // Indicate success
}

// Function to format the output string
int format_output(char *output_str, size_t output_str_size, int *channel_values, size_t num_channels) {
    int i;
    for (i = 0; i < num_channels; i++) {
        char ch = '0' + i; // '0' for CH1, '1' for CH2, etc.
        char value_str[3]; // Enough space for two digits and null terminator
