#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Function to generate a random hue value
int generate_random_hue() {
    int hue = rand() % 360;
    return hue;
}

// Function to calculate RGB values from a given hue
void hsv_to_rgb(int hue, int saturation, int value, int *red, int *green, int *blue) {
    float h = hue / 60.0;
    float x = value * (1 - fabs(fmod(h, 2) - 1));
    float r, g, b;

    if (h < 1) {
        r = value; g = x; b = 0;
    } else if (h < 2) {
        r = x; g = value; b = 0;
    } else if (h < 3) {
        r = 0; g = value; b = x;
    } else if (h < 4) {
        r = 0; g = x; b = value;
    } else if (h < 5) {
        r = x; g = 0; b = value;
    } else {
        r = value; g = 0; b = x;
    }

    *red   = (int)(r * 255 / 255.0);
    *green = (int)(g * 255 / 255.0);
    *blue  = (int)(b * 255 / 255.0);
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

int main() {
    // Initialize syslog
    openlog("rgb_led", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator with /dev/urandom
    FILE *urandom_fd = fopen("/dev/urandom", "r");
    if (urandom_fd == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        perror("fopen");
        fclose(NULL); // Corrected to fclose(NULL) as NULL is not a valid file pointer
        return 1;
    }
    unsigned char buffer[4];
    fread(buffer, 1, 4, urandom_fd);
    fclose(urandom_fd);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Generate random hue
        int hue = generate_random_hue();

        // Calculate RGB values
        int red, green, blue;
        hsv_to_rgb(hue, 1, 255, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Wait for 5 seconds
        sleep(5);
    }

    // Turn off the LED before exiting
    set_led_color(0, 0, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

