#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         0x29
#define TCS34725_COMMAND_BIT     0x80
#define TCS34725_ENABLE          0x00
#define TCS34725_ATIME           0x01
#define TCS34725_CDATA           0x14
#define TCS34725_RDATA           0x16
#define TCS34725_GDATA           0x18
#define TCS34725_BDATA           0x1A

// GPIO Pin for LED
#define LED_PIN                 17

// Red Value Threshold
#define RED_THRESHOLD           200

// I2C Bus
#define I2C_BUS                 1

// Global Variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int tcs34725_init(int fd);
int tcs34725_read_data(int fd, uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear);
void led_control(int gpio_pin, int red_value);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// TCS34725 Initialization
int tcs34725_init(int fd) {
    uint8_t buf[2];

    // Power ON
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    buf[1] = 0x01; // PON
    if (write(fd, buf, 2) != 2) {
        perror("Failed to power on TCS34725");
        return -1;
    }
    usleep(3); // Wait for power-on

    // Enable RGBC
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    buf[1] = 0x02; // AEN
    if (write(fd, buf, 2) != 2) {
        perror("Failed to enable RGBC on TCS34725");
        return -1;
    }

    // Set Integration Time (ATIME) - 154ms
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ATIME;
    buf[1] = 0xD5; // 154ms
    if (write(fd, buf, 2) != 2) {
        perror("Failed to set integration time on TCS34725");
        return -1;
    }

    return 0;
}

// Read Data from TCS34725
int tcs34725_read_data(int fd, uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear) {
    uint8_t buf[8];

    // Read Clear, Red, Green, Blue data
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_CDATA;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to set register address for reading");
        return -1;
    }
    if (read(fd, buf, 8) != 8) {
        perror("Failed to read data from TCS34725");
        return -1;
    }

    *clear = (buf[1] << 8) | buf[0];
    *red   = (buf[3] << 8) | buf[2];
    *green = (buf[5] << 8) | buf[4];
    *blue  = (buf[7] << 8) | buf[6];

    return 0;
}

// LED Control
void led_control(int gpio_pin, int red_value) {
    if (red_value > RED_THRESHOLD) {
        gpioWrite(gpio_pin, 1); // HIGH
    } else {
        gpioWrite(gpio_pin, 0); // LOW
    }
}

int main() {
    uint16_t red, green, blue, clear;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read data from TCS34725
        status = tcs34725_read_data(i2c_fd, &red, &green, &blue, &clear);
        if (status < 0) {
            fprintf(stderr, "Failed to read data, re-initializing...\n");
            close(i2c_fd);
            i2c_fd = open("/dev/i2c-1", O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C bus");
                gpioTerminate();
                return 1;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "TCS34725 initialization failed\n");
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }
            continue; // Skip to the next iteration
        }

        // Control LED based on Red value
        led_control(LED_PIN, red);

        // Print data to console
        printf("R: %5d, G: %5d, B: %5d, C: %5d\n", red, green, blue, clear);

        // Wait 200ms
        usleep(200000);
    }

    // Cleanup
    close(i2c_fd);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

