    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read data from TCS34725
        status = tcs34725_read_data(i2c_fd, &red, &green, &blue, &clear);
        if (status < 0) {
            fprintf(stderr, "Failed to read data, re-initializing...\n");
            close(i2c_fd);
            i2c_fd = open("/dev/i2c-1", O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C bus");
                gpioTerminate();
                return 1;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "TCS34725 initialization failed\n");
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }
            continue; // Skip to the next iteration
        }

        // Control LED based on Red value
        led_control(LED_PIN, red);

        // Print data to console
        printf("R: %5d, G: %5d, B: %5d, C: %5d\n", red, green, blue, clear);

        // Wait 200ms
        usleep(200000);
    }

    // Cleanup
    close(i2c_fd);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

