#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define WS2812B_GPIO 18
#define NUM_LEDS 10
#define PWM_FREQUENCY 800000  // 800 kHz
#define PWM_RANGE 1000
#define LOG_BASE 0.5
#define MAX_LUX 1000.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_lux();
int map_lux_to_brightness(float lux);
void generate_ws2812b_data(int brightness, uint8_t *data);
void send_ws2812b_data(uint8_t *data);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750
float read_lux() {
    char config[1] = {0x10}; // Continuous high resolution mode
    int result;

    result = i2cWriteDevice(i2c_handle, config, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1.0;
    }

    gpioDelay(180); // Wait 180ms

    char buffer[2];
    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1.0;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return (float)raw_value / 1.2; // Convert to lux
}

// Map lux value to brightness level (logarithmic)
int map_lux_to_brightness(float lux) {
    if (lux < 0) return 0; // Handle invalid lux values
    if (lux > MAX_LUX) lux = MAX_LUX; // Cap lux value

    float log_lux = log10(lux / LOG_BASE);
    int brightness = (int)(log_lux / log10(MAX_LUX / LOG_BASE) * NUM_LEDS);

    if (brightness < 0) brightness = 0;
    if (brightness > NUM_LEDS) brightness = NUM_LEDS;

    return brightness;
}

// Generate WS2812B data
void generate_ws2812b_data(int brightness, uint8_t *data) {
    for (int i = 0; i < NUM_LEDS; i++) {
        data[i] = 0; // All LEDs off initially
    }

    for (int i = 0; i < brightness; i++) {
        data[i] = 0xFF; // Turn on LEDs
    }
}

// Send WS2812B data using pigpio wave
void send_ws2812b_data(uint8_t *data) {
    gpioWaveClear();

    gpioPulse_t pulse[NUM_LEDS * 24 + 1];
    int pulse_index = 0;

    // Start signal
    pulse[pulse_index].gpioOn = 0;
    pulse[pulse_index].gpioOff = 0;
    pulse[pulse_index].usDelay = 50000; // 50us
    pulse_index++;

    // LED data
    for (int i = 0; i < NUM_LEDS; i++) {
        for (int j = 7; j >= 0; j--) {
            if ((data[i] >> j) & 1) {
                pulse[pulse_index].gpioOn = (1 << WS2812B_GPIO);
                pulse[pulse_index].gpioOff = 0;
                pulse[pulse_index].usDelay = 800; // 0.8us
                pulse_index++;

                pulse[pulse_index].gpioOn = 0;
                pulse[pulse_index].gpioOff = (1 << WS2812B_GPIO);
                pulse[pulse_index].usDelay = 450; // 0.45us
                pulse_index++;
            } else {
                pulse[pulse_index].gpioOn = (1 << WS2812B_GPIO);
                pulse[pulse_index].gpioOff = 0;
                pulse[pulse_index].usDelay = 450; // 0.45us
                pulse_index++;

                pulse[pulse_index].gpioOn = 0;
                pulse[pulse_index].gpioOff = (1 << WS2812B_GPIO);
                pulse[pulse_index].usDelay = 800; // 0.8us
                pulse_index++;
            }
        }
    }

    // End signal
    pulse[pulse_index].gpioOn = 0;
    pulse[pulse_index].gpioOff = 0;
    pulse[pulse_index].usDelay = 50000; // 50us
    pulse_index++;

    gpioWaveAddGeneric(pulse_index, pulse);
    int wave_id = gpioWaveCreate();

    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT); // Send once
        while (gpioWaveTxBusy()) gpioDelay(10); // Wait for transmission
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Error creating wave: %d\n", wave_id);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure WS2812B GPIO as output
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    uint8_t ws2812b_data[NUM_LEDS];

    // Main loop
    while (!terminate) {
        // Read lux value
        float lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Map lux to brightness
        int brightness = map_lux_to_brightness(lux);

        // Generate WS2812B data
        generate_ws2812b_data(brightness, ws2812b_data);

        // Send WS2812B data
        send_ws2812b_data(ws2812b_data);

        // Delay
        gpioDelay(100); // 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

