#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SPI_BUS 0
#define SPI_SPEED 1000000 // 1 MHz
#define BH1750_ADDR 0x23
#define APA102_N_LEDS 10
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define ZERO_START_FRAME 0x00
#define END_FRAME 0xFF
#define LED_FRAME_SIZE 4
#define MAX_RETRIES 3

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
int socket_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float lux;
    int status;
} sensor_data_t;

// Structure for LED data
typedef struct {
    uint8_t brightness;
    uint8_t blue;
    uint8_t green;
    uint8_t red;
} led_data_t;

// Function prototypes
int init_i2c();
int init_spi();
int init_socket();
sensor_data_t read_bh1750();
led_data_t scale_lux_to_led(float lux);
int send_led_data(led_data_t *led_data, int num_leds);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to initialize SPI
int init_spi() {
    spi_fd = spiOpen(SPI_BUS, SPI_SPEED, 0); // Mode 0
    if (spi_fd < 0) {
        perror("Error opening SPI bus");
        return -1;
    }
    return 0;
}

// Function to initialize the socket
int init_socket() {
    struct sockaddr_in server_addr;

    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        perror("Error creating socket");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(socket_fd);
        return -1;
    }

    if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error connecting to server");
        close(socket_fd);
        return -1;
    }

    return 0;
}

// Function to read data from BH1750 sensor
sensor_data_t read_bh1750() {
    sensor_data_t data = {0.0, 0};
    uint8_t buf[2];
    int retries = 0;

    // Send start measurement command (High Resolution Mode)
    if (i2cWriteByte(i2c_fd, 0x10) < 0) {
        perror("Error writing to I2C device");
        data.status = -1;
        return data;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(200000); // 200ms

    // Read 2 bytes of data
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        data.status = -1;
        return data;
    }

    // Convert to lux
    uint16_t raw_value = (buf[0] << 8) | buf[1];
    data.lux = (float)raw_value / 1.2;

    data.status = 0;
    return data;
}

// Function to scale lux value to LED brightness
led_data_t scale_lux_to_led(float lux) {
    led_data_t led_data;

    // Map lux to brightness (0-255)
    led_data.brightness = (uint8_t)(lux * 0.5); // Example scaling
    if (led_data.brightness > 255) {
        led_data.brightness = 255;
    } else if (led_data.brightness < 0) {
        led_data.brightness = 0;
    }

    // Set blue, green, and red to the same brightness
    led_data.blue = led_data.brightness;
    led_data.green = led_data.brightness;
    led_data.red = led_data.brightness;

    return led_data;
}

// Function to send LED data via SPI
int send_led_data(led_data_t *led_data, int num_leds) {
    uint8_t frame[4 + num_leds * LED_FRAME_SIZE + 4];
    int i;

    // Construct the APA102 frame
    frame[0] = ZERO_START_FRAME;
    frame[1] = ZERO_START_FRAME;
    for (i = 0; i < num_leds; i++) {
        frame[2 + i * 4] = led_data[i].brightness;
        frame[3 + i * 4] = led_data[i].blue;
        frame[4 + i * 4] = led_data[i].green;
        frame[5 + i * 4] = led_data[i].red;
    }
    frame[2 + num_leds * LED_FRAME_SIZE] = END_FRAME;
    frame[3 + num_leds * LED_FRAME_SIZE] = END_FRAME;

    // Send the frame
    for (i = 0; i < sizeof(frame); i++) {
        if (spiWrite(spi_fd, &frame[i], 1) != 0) {
            perror("Error writing to SPI device");
            return -1;
        }
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        spiClose(spi_fd);
    }
    if (socket_fd != -1) {
        close(socket_fd);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize socket
    if (init_socket() != 0) {
        fprintf(stderr, "Socket initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t sensor_data = read_bh1750();

        if (sensor_data.status == 0) {
            // Scale lux to LED brightness
            led_data_t led_data[APA102_N_LEDS];
            for (int i = 0; i < APA102_N_LEDS; i++) {
                led_data[i] = scale_lux_to_led(sensor_data.lux);
            }

            // Send LED data
            if (send_led_data(led_data, APA102_N_LEDS) != 0) {
                fprintf(stderr, "Failed to send LED data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait before next reading
        gpioDelay(200000); // 200ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

