#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define ALS_DATA_REG 0x04
#define ALS_CONFIG_REG 0x00
#define WS2812B_GPIO 18
#define PWM_FREQUENCY 800000
#define PWM_RANGE 255
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define LOG_FILE "error.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int veml7700_read_als(int i2c_handle, uint16_t *als_data);
float gamma_correct(uint16_t raw_als, float gamma);
int ws2812b_set_brightness(int gpio, int brightness);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Error logging function
void log_error(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        perror("Error opening log file");
    }
}

// VEML7700 read ALS data function
int veml7700_read_als(int i2c_handle, uint16_t *als_data) {
    char buf[2];
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadI2CBlockData(i2c_handle, ALS_DATA_REG, buf, 2);
        if (result == 2) {
            *als_data = (buf[1] << 8) | buf[0];
            return 0; // Success
        } else {
            log_error("I2C read failed, retrying...");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    log_error("I2C read failed after multiple retries.");
    return -1; // Failure
}

// Gamma correction function
float gamma_correct(uint16_t raw_als, float gamma) {
    float lux = (float)raw_als;
    return powf(lux, gamma);
}

// WS2812B set brightness function
int ws2812b_set_brightness(int gpio, int brightness) {
    if (brightness < 0 || brightness > PWM_RANGE) {
        log_error("Invalid brightness value.");
        return -1;
    }

    for (int i = 0; i < 24; ++i) {
        gpioWrite(gpio, (brightness > PWM_RANGE / 2) ? 1 : 0);
        gpioDelay(50); // Delay for 50us
    }

    gpioWrite(gpio, 0);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Configure VEML7700 (example configuration)
    uint16_t config = 0x0000; // Integration time = 100ms, Gain = 1
    char config_buf[3];
    config_buf[0] = ALS_CONFIG_REG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    int result = i2cWriteI2CBlockData(i2c_handle, config_buf[0], config_buf + 1, 2);
    if (result != 2) {
        log_error("Failed to configure VEML7700");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set WS2812B GPIO as output
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t als_data;
        float lux = 0.0;
        float brightness = 0.0;

        // Read ALS data
        if (veml7700_read_als(i2c_handle, &als_data) == 0) {
            lux = (float)als_data; // Raw ALS value is directly proportional to lux in this example
        } else {
            lux = -1.0; // Indicate error
        }

        // Gamma correct
        brightness = gamma_correct(als_data, 0.5); // Example gamma value

        // Set LED brightness
        if (brightness >= 0) {
            if (ws2812b_set_brightness(WS2812B_GPIO, (int)brightness) != 0) {
                log_error("Failed to set LED brightness");
            }
        } else {
            log_error("Failed to read ALS data, setting LED to off.");
            ws2812b_set_brightness(WS2812B_GPIO, 0);
        }

        // Print data
        printf("Lux: %.2f, Brightness: %.2f\n", lux, brightness);

        gpioDelay(200000); // 200ms delay
    }

    // Cleanup
    ws2812b_set_brightness(WS2812B_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

