#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define error patterns
#define ERROR_BLINK_RATE 100  // ms
#define ERROR_BLINK_COUNT 5

#define ERROR_SHORT_SHORT_LONG_SHORT_PATTERN[] = {200, 200, 600, 200, 200};
#define ERROR_BLINK_PATTERN[] = {100, 100};

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_flame_sensor();
void activate_buzzer(int duration_ms);
void activate_led(int duration_ms);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Error pattern functions
void error_short_short_long_short();
void error_rapid_blink();

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to activate the buzzer
void activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
}

// Function to activate the LED
void activate_led(int duration_ms) {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(LED_PIN, 0); // Turn LED off
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    cleanup();
    exit(0);
}

// Cleanup function to release GPIO resources
void cleanup() {
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Error pattern functions
void error_short_short_long_short() {
    for (int i = 0; i < 3; i++) {
        activate_buzzer(200);
        activate_buzzer(200);
        activate_buzzer(600);
        activate_buzzer(200);
    }
}

void error_rapid_blink() {
    for (int i = 0; i < ERROR_BLINK_COUNT; i++) {
        activate_led(ERROR_BLINK_RATE);
        activate_led(ERROR_BLINK_RATE);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("flame_sensor.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Perform startup self-test
