#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_LED 17
#define SAMPLE_INTERVAL_SEC 1
#define BUFFER_SIZE 60
#define MIN_FREQUENCY 0.5
#define MAX_FREQUENCY 5.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
void init_gpio();
void set_led_frequency(float lux);
void update_circular_buffer(CircularBuffer *cb, float lux);
float calculate_average_lux(CircularBuffer *cb);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read the BH1750 sensor
int read_bh1750(float *lux) {
    char config[1] = {0x10}; // Continuous high-resolution mode
    char data[2];
    int result;

    result = i2cWriteDevice(i2c_handle, config, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(200); // Wait for measurement (at least 180ms)

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (data[0] << 8) | data[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Function to initialize the GPIO pin
void init_gpio() {
    gpioSetMode(GPIO_LED, PI_OUTPUT);
}

// Function to set the LED frequency based on lux value
void set_led_frequency(float lux) {
    float frequency = MIN_FREQUENCY + (lux - 0) * (MAX_FREQUENCY - MIN_FREQUENCY) / (1000.0 + lux);
    int period = 1000000 / (int)(frequency * 2); // Period in microseconds
    gpioPWM(GPIO_LED, 128); // 50% duty cycle
    gpioDelay(period / 2); // Half period
    gpioDelay(period / 2); // Half period
}

// Function to update the circular buffer
void update_circular_buffer(CircularBuffer *cb, float lux) {
    cb->buffer[cb->head] = lux;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to calculate the average lux from the circular buffer
float calculate_average_lux(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Set back to input
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    init_gpio();

    // Initialize circular buffer
    CircularBuffer lux_buffer;
    init_circular_buffer(&lux_buffer);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float lux;
    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);
            update_circular_buffer(&lux_buffer, lux);
            float average_lux = calculate_average_lux(&lux_buffer);
            printf("Average Lux: %.2f\n", average_lux);
            set_led_frequency(average_lux);
        } else {
            fprintf(stderr, "Failed to read lux value. Retrying...\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

