#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define the number of segments
#define NUM_SEGMENTS 8

// Define the delay between clock pulses (in microseconds)
#define DELAY_US 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DATA_PIN, PI_OUTPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LATCH_PIN, PI_OUTPUT);

    // Ensure all pins are low initially
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    return 0;
}

// Function to shift out data to the 74HC595
void shift_out(unsigned char data) {
    for (int i = 0; i < NUM_SEGMENTS; i++) {
        // Set the data pin based on the current bit
        gpioWrite(DATA_PIN, (data >> (NUM_SEGMENTS - 1 - i)) & 1);

        // Clock the data out
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(DELAY_US);
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(DELAY_US);
    }
}

// Function to latch the data
void latch() {
    gpioWrite(LATCH_PIN, 1);
    gpioDelay(DELAY_US);
    gpioWrite(LATCH_PIN, 0);
    gpioDelay(DELAY_US);
}

// Function to display a digit on the seven-segment display
void display_digit(int digit) {
    unsigned char data = 0;

    // Define the segment patterns for digits 0-9 (MSB first)
    switch (digit) {
        case 0:
            data = 0b00111111;
            break;
        case 1:
            data = 0b00000110;
            break;
        case 2:
            data = 0b01011011;
            break;
        case 3:
            data = 0b01001111;
            break;
        case 4:
            data = 0b01100110;
            break;
        case 5:
            data = 0b01101101;
            break;
        case 6:
            data = 0b01111101;
            break;
        case 7:
            data = 0b00000111;
            break;
        case 8:
            data = 0b01111111;
            break;
        case 9:
            data = 0b01101111;
            break;
        default:
            fprintf(stderr, "Invalid digit: %d\n", digit);
            return;
    }

    shift_out(data);
    latch();
}

// Function to blink the digit
void blink_digit(int digit, int delay_ms) {
    display_digit(digit);
    gpioDelay(delay_ms * 1000); // Convert ms to us
    display_digit(0); // Turn off the display
    gpioDelay(delay_ms * 1000);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Seven-segment display blinking started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        blink_digit(5, 500); // Blink the digit '5'
    }

    // Release the GPIO pins before exiting
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

