    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Seven-segment display blinking started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
