    }

    // Release the GPIO pins before exiting
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

