#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define LED_GPIO 17
#define BUTTON_GPIO 18
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define DHT22_GPIO 4
#define MAX_SENSORS 3

// Global variables
static int spi_fd = -1;
static int dht22_fd = -1;
static volatile int running = 1;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int request_gpio(int gpio, int mode);
int set_gpio(int gpio, int value);
int get_gpio(int gpio);
int open_spi_device(const char *device);
int close_spi_device();
int read_mcp3008(int channel);
int read_dht22(float *temperature, float *humidity);
void blink_led(int duration);
void signal_handler(int signal);
void cleanup();

// Function to request a GPIO line
int request_gpio(int gpio, int mode) {
    int fd = open("/sys/class/gpio/gpio%d", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }

    char buf[3];
    int len = snprintf(buf, sizeof(buf), "%d", mode);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Error setting GPIO %d mode: %s\n", gpio, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set a GPIO line
int set_gpio(int gpio, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO %d value: %s\n", gpio, strerror(errno));
        return -1;
    }

    char buf[2];
    int len = snprintf(buf, sizeof(buf), "%d", value);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Error setting GPIO %d value: %s\n", gpio, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to get a GPIO line value
int get_gpio(int gpio) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO %d value for reading: %s\n", gpio, strerror(errno));
        return -1;
    }

    char buf[2];
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading GPIO %d value: %s\n", gpio, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return (buf[0] == '1') ? 1 : 0;
}

// Function to open the SPI device
int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Configure bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to close the SPI device
int close_spi_device() {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "Error sending SPI message: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to read DHT22 sensor data
int read_dht22(float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int j = 0;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, PI_HIGH);
    gpioDelay(500);
    gpioWrite(DHT22_GPIO, PI_LOW);
    gpioDelay(20);
    gpioWrite(DHT22_GPIO, PI_HIGH);
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read data
    for (int i = 0; i < 85; i++) {
        int counter = 0;
        while (gpioRead(DHT22_GPIO) == laststate) {
            counter++;
            gpioDelay(1);
            if (counter == 255) {
                break;
            }
        }
        laststate = gpioRead(DHT22_GPIO);

        if (counter == 255) break;

        // Ignore first 3 transitions
        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16) data[j / 8] |= 1;
            j++;
        }
    }

    // Check checksum
    if (j >= 40 && (data[0] + data[1] + data[2] + data[3]) == data[4]) {
        float h = (float)((data[0] << 8) + data[1]) / 10;
        float t = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10;
        if (data[2] & 0x80) t *= -1;

        *humidity = h;
        *temperature = t;
        return 0;
    } else {
        fprintf(stderr, "DHT22 checksum error\n");
        return -1;
    }
}

// Function to blink the LED
void blink_led(int duration) {
    if (set_gpio(LED_GPIO, 1) != 0) {
        fprintf(stderr, "Error setting LED high\n");
        return;
    }
    gpioDelay(duration * 1000); // Convert seconds to milliseconds
    if (set_gpio(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error setting LED low\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_fd != -1) {
        close_spi_device();
    }
    if (dht22_fd != -1) {
        // No direct close for dht22_fd, but we can reset the GPIO
        request_gpio(DHT22_GPIO, PI_INPUT);
        set_gpio(DHT22_GPIO, 0);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Request GPIO lines
    if (request_gpio(LED_GPIO, PI_OUTPUT) != 0) {
        cleanup();
        return 1;
    }
    if (request_gpio(BUTTON_GPIO, PI_INPUT) != 0) {
        cleanup();
        return 1;
    }
    if (request_gpio(DHT22_GPIO, PI_INPUT) != 0) {
        cleanup();
        return 1;
    }

    // Open SPI device
    spi_fd = open_spi_device(SPI_DEVICE);
    if (spi_fd < 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Smart Agriculture Monitoring System started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor data
        int light_level = read_mcp3008(MCP3008_CHANNEL);
        float temperature, humidity;
        if (read_dht22(&temperature, &humidity) == 0) {
            printf("Light: %d, Temperature: %.1f, Humidity: %.1f\n", light_level, temperature, humidity);
        } else {
            fprintf(stderr, "Error reading DHT22 sensor\n");
        }

        // Blink LED
        blink_led(1);

        // Check button press
        int button_state = get_gpio(BUTTON_GPIO);
        if (button_state == 0) { // Assuming button pulls GPIO low on press
            printf("Button pressed!\n");
            blink_led(0); // Turn off LED
            cleanup();
            return 0;
        }

        gpioDelay(1000); // Check every 1 second
    }

    cleanup();
    return 0;
}

