        printf("\nCtrl+C pressed. Exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the RGB LED color
void set_rgb_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to generate a random color value
int generate_random_color() {
    return (rand() % 101);
}

