#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303DLHC Accelerometer I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC Registers
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// GPIO pin for impact interrupt
#define IMPACT_PIN 17

// Default impact threshold (G)
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
double impact_threshold = DEFAULT_THRESHOLD;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_accelerometer();
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void impact_interrupt();
void log_data(int16_t x, int16_t y, int16_t z, double magnitude);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x19, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the accelerometer
int init_accelerometer() {
    // Enable accelerometer, 50 Hz data rate, +/- 2G range
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    // Set full-scale range to +/- 2G
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to calculate the magnitude of the acceleration vector
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 16384.0; // Assuming +/- 2G range
    double y_g = (double)y / 16384.0;
    double z_g = (double)z / 16384.0;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Function to handle the impact interrupt
void impact_interrupt() {
    gpioWrite(IMPACT_PIN, 1); // Set GPIO HIGH
    gpioDelay(50);            // Wait for 50ms
    gpioWrite(IMPACT_PIN, 0); // Set GPIO LOW
}

// Function to log the data to a file
void log_data(int16_t x, int16_t y, int16_t z, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %.4f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        impact_threshold = atof(argv[1]);
        printf("Impact threshold set to: %.2f G\n", impact_threshold);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(IMPACT_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize accelerometer
    if (init_accelerometer() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    double magnitude;

    // Main loop
    while (!terminate) {
        if (read_accelerometer_data(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > impact_threshold) {
                impact_interrupt();
                log_data(x, y, z, magnitude);
            } else {
                log_data(x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
        }

        gpioDelay(50); // 10 Hz sampling rate
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(IMPACT_PIN, 0); // Ensure GPIO is LOW
    fclose(log_file);
    gpioTerminate();

    return 0;
}

