#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define ALS_LSB_REG 0x00
#define ALS_MSB_REG 0x01
#define RED_LSB_REG 0x02
#define RED_MSB_REG 0x03
#define GREEN_LSB_REG 0x04
#define GREEN_MSB_REG 0x05
#define BLUE_LSB_REG 0x06
#define BLUE_MSB_REG 0x07
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
int control_led(uint16_t als);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor_data(&sensor_data.als, &sensor_data.red, &sensor_data.green, &sensor_data.blue) == 0) {
            if (log_data(sensor_data.als, sensor_data.red, sensor_data.green, sensor_data.blue) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
            if (control_led(sensor_data.als) != 0) {
                fprintf(stderr, "Failed to control LED.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    return 0;
}

int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[1];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        // Read ALS data
        buf[0] = ALS_LSB_REG;
        result = i2cWriteDevice(i2c_handle, buf, 1);
        if (result != 0) {
            fprintf(stderr, "Failed to write ALS LSB register address: %s\n", strerror(errno));
            gpioDelay(10000); // 10ms delay
            continue;
        }
        char als_lsb_buf[2];
        result = i2cReadDevice(i2c_handle, als_lsb_buf, 2);
        if (result != 2) {
            fprintf(stderr, "Failed to read ALS LSB data: %s\n", strerror(errno));
            gpioDelay(10000); // 10ms delay
