#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define FXOS8700CQ_ADDR 0x1F
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VALUE 0xC7
#define STANDBY_REG 0x2A
#define OUT_X_MSB_REG 0x01
#define CTRL_REG1 0x2A
#define ACCEL_RANGE_2G 0x00
#define ODR_200HZ 0x0A
#define IMPACT_THRESHOLD 2.0f
#define LOG_FILE "impact_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_fxos8700c();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
int log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the FXOS8700CQ sensor
int init_fxos8700c() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: WHO_AM_I value mismatch. Expected 0x%X, got 0x%X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }

    // Standby mode
    if (i2cWriteByteData(i2c_handle, STANDBY_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to STANDBY_REG\n");
        return -1;
    }

    // Configure accelerometer range to ±2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, ACCEL_RANGE_2G | 0x02) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (range)\n");
        return -1;
    }

    // Set output data rate to 200 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, ACCEL_RANGE_2G | 0x0A) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (ODR)\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the sensor
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB_REG, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    x_raw = (int16_t)((raw_data[0] << 8) | raw_data[1]) >> 2;
    y_raw = (int16_t)((raw_data[2] << 8) | raw_data[3]) >> 2;
    z_raw = (int16_t)((raw_data[4] << 8) | raw_data[5]) >> 2;

    // Convert to g-force units (assuming ±2g range)
    *x = (float)x_raw / 4096.0f;
    *y = (float)y_raw / 4096.0f;
    *z = (float)z_raw / 4096.0f;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Log impact data to file
int log_impact(float x, float y, float z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700c() < 0) {
        fprintf(stderr, "FXOS8700CQ initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

