// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the FXOS8700CQ sensor
int init_fxos8700c() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: WHO_AM_I value mismatch. Expected 0x%X, got 0x%X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }

    // Standby mode
    if (i2cWriteByteData(i2c_handle, STANDBY_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to STANDBY_REG\n");
        return -1;
    }

    // Configure accelerometer range to ±2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, ACCEL_RANGE_2G | 0x02) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (range)\n");
        return -1;
    }

    // Set output data rate to 200 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, ACCEL_RANGE_2G | 0x0A) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (ODR)\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the sensor
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB_REG, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    x_raw = (int16_t)((raw_data[0] << 8) | raw_data[1]) >> 2;
    y_raw = (int16_t)((raw_data[2] << 8) | raw_data[3]) >> 2;
    z_raw = (int16_t)((raw_data[4] << 8) | raw_data[5]) >> 2;

    // Convert to g-force units (assuming ±2g range)
    *x = (float)x_raw / 4096.0f;
    *y = (float)y_raw / 4096.0f;
    *z = (float)z_raw / 4096.0f;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Log impact data to file
int log_impact(float x, float y, float z, float magnitude) {
