        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        gyro_data_t data;
        if (read_gyro_data(&data.x, &data.y, &data.z) == 0) {
            // Apply calibration offsets
            data.x -= (int16_t)x_offset;
            data.y -= (int16_t)y_offset;
            data.z -= (int16_t)z_offset;

            // Log the data
            log_data(data.x, data.y, data.z);

            // Check for alerts
            check_alert(data.x, data.y, data.z);
        } else {
