        gpioDelay(SAMPLE_PERIOD_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize the gyroscope
int initialize_gyro() {
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REGISTER);
    if (who_am_i < 0 || who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I check failed: Expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        i2cClose(i2c_handle);
        return 1;
    }

    // Configure gyroscope (example: enable all axes, 100Hz ODR)
    // Refer to the L3G4200D datasheet for the correct register settings
    // This is a simplified example, adjust as needed
    if (i2cWriteByteData(i2c_handle, 0x20, 0x0F) < 0) { // Enable all axes, 100Hz ODR
        fprintf(stderr, "Failed to write to gyroscope configuration register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, 0x28, buffer, 6) != 6) { // Read X, Y, Z data (6 bytes)
        fprintf(stderr, "Failed to read gyro data: %s\n", strerror(errno));
        return 1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate the gyroscope
void calibrate_gyro() {
    int16_t x, y, z;
    float x_sum = 0.0, y_sum = 0.0, z_sum = 0.0;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            x_sum += x;
            y_sum += y;
            z_sum += z;
        } else {
            fprintf(stderr, "Calibration failed: Could not read gyro data\n");
            exit(1);
        }
        gpioDelay(1000); // 1ms delay
    }

    x_offset = x_sum / CALIBRATION_SAMPLES;
    y_offset = y_sum / CALIBRATION_SAMPLES;
    z_offset = z_sum / CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", x_offset, y_offset, z_offset);
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Check for alerts
void check_alert(int16_t x, int16_t y, int16_t z) {
    if (abs(x) > ALERT_THRESHOLD || abs(y) > ALERT_THRESHOLD || abs(z) > ALERT_THRESHOLD) {
        fprintf(log_file, "ALERT: %s, X=%.2f, Y=%.2f, Z=%.2f\n", __TIME__, x, y, z);
        fflush(log_file);
        fprintf(stderr, "ALERT: %s, X=%.2f, Y=%.2f, Z=%.2f\n", __TIME__, x, y, z);
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

