// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Full resolution mode
#define ADXL345_FULL_RES_MODE 0x0B

// LED GPIO pin (BCM numbering)
#define LED_GPIO 17

// Acceleration threshold (g)
#define ACCEL_THRESHOLD 2.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int adxl345_init();
accelerometer_data_t read_acceleration();
void log_data(accelerometer_data_t data);
void control_led(float x, float y, float z);
void signal_handler(int signal);
int write_register(int handle, uint8_t reg, uint8_t value);
int read_register(int handle, uint8_t reg, uint8_t *value);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to write to an ADXL345 register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read from an ADXL345 register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to initialize the ADXL345
int adxl345_init() {
    uint8_t device_id;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Verify device ID
    if (read_register(i2c_handle, ADXL345_REG_DEVID, &device_id) != 0) {
        fprintf(stderr, "Error reading device ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0xE5)\n", device_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set to full resolution mode
    if (write_register(i2c_handle, ADXL345_REG_POWER_CTL, ADXL345_FULL_RES_MODE) != 0) {
        fprintf(stderr, "Error setting full resolution mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    return 0;
}

// Function to read acceleration data from the ADXL345
accelerometer_data_t read_acceleration() {
    accelerometer_data_t data;
    uint8_t x0, x1, y0, y1, z0, z1;
    int16_t x, y, z;

    // Read acceleration data
    if (read_register(i2c_handle, ADXL345_REG_DATAX0, &x0) != 0) {
        data.x = 0.0; // Set to 0.0 to avoid garbage values
    } else if (read_register(i2c_handle, ADXL345_REG_DATAX1, &x1) != 0) {
        data.x = 0.0;
    } else {
        x = (int16_t)((x1 << 8) | x0);
        data.x = (float)x / 256.0; // Convert to g
    }

    if (read_register(i2c_handle, ADXL345_REG_DATAY0, &y0) != 0) {
        data.y = 0.0;
    } else if (read_register(i2c_handle, ADXL345_REG_DATAY1, &y1) != 0) {
        data.y = 0.0;
    } else {
        y = (int16_t)((y1 << 8) | y0);
        data.y = (float)y / 256.0; // Convert to g
    }

    if (read_register(i2c_handle, ADXL345_REG_DATAZ0, &z0) != 0) {
        data.z = 0.0;
    } else if (read_register(i2c_handle, ADXL345_REG_DATAZ1, &z1) != 0) {
        data.z = 0.0;
    } else {
        z = (int16_t)((z1 << 8) | z0);
        data.z = (float)z / 256.0; // Convert to g
    }

