#define ACC_OUT_Z_H_A 0x2D
#define ACC_CTRL_REG1_A 0x20
#define ACC_CTRL_REG2_A 0x21

// Sensitivity values (adjust based on your sensor's configuration)
#define ACC_SENSITIVITY 0.061  // g/LSB (for +/- 2g range)
#define MAG_SENSITIVITY 0.08   // gauss/LSB (for +/- 1.3 gauss range)

// Global variables
int i2c_handle_mag = -1;
int i2c_handle_acc = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_accelerometer();
int init_magnetometer();
int read_accelerometer(float *x, float *y, float *z);
int read_magnetometer(float *x, float *y, float *z);
float calculate_heading(float ax, float ay, float az, float mx, float my, float mz);
void log_data(float ax, float ay, float az, float mx, float my, float mz, float heading);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
