    if (init_magnetometer() != 0) {
        fprintf(stderr, "Magnetometer initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,AccX,AccY,AccZ,MagX,MagY,MagZ\n");
    }

    // Main loop
    float ax, ay, az, mx, my, mz, heading;
    while (!terminate) {
        // Read sensor data
        if (read_accelerometer(&ax, &ay, &az) != 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }
        if (read_magnetometer(&mx, &my, &mz) != 0) {
            fprintf(stderr, "Failed to read magnetometer data\n");
        }

        // Calculate heading
        heading = calculate_heading(ax, ay, az, mx, my, mz);

        // Log data
        log_data(ax, ay, az, mx, my, mz, heading);

        // Sleep for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle_mag = i2cOpen(1, MAG_ADDR, 0); // I2C bus 1, magnetometer address
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Failed to open I2C device for magnetometer: %d\n", i2c_handle_mag);
        return 1;
    }

    i2c_handle_acc = i2cOpen(1, ACC_ADDR, 0); // I2C bus 1, accelerometer address
    if (i2c_handle_acc < 0) {
        fprintf(stderr, "Failed to open I2C device for accelerometer: %d\n", i2c_handle_acc);
        i2cClose(i2c_handle_mag);
        return 1;
    }

    return 0;
}

// Initialize accelerometer
int init_accelerometer() {
    // Set accelerometer to +/- 2g range
    if (i2cWriteByteData(i2c_handle_acc, ACC_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Failed to write to accelerometer CTRL_REG1_A\n");
        return 1;
    }

    // Set accelerometer to 100 Hz ODR
    if (i2cWriteByteData(i2c_handle_acc, ACC_CTRL_REG2_A, 0x10) < 0) {
        fprintf(stderr, "Failed to write to accelerometer CTRL_REG2_A\n");
        return 1;
    }

    return 0;
}

// Initialize magnetometer
int init_magnetometer() {
    // Set magnetometer to continuous conversion mode
    if (i2cWriteByteData(i2c_handle_mag, MAG_CTRL_REG1_M, 0x70) < 0) {
        fprintf(stderr, "Failed to write to magnetometer MAG_CTRL_REG1_M\n");
        return 1;
    }

    // Set magnetometer to +/- 1.3 gauss range
    if (i2cWriteByteData(i2c_handle_mag, MAG_CTRL_REG2_M, 0x20) < 0) {
        fprintf(stderr, "Failed to write to magnetometer MAG_CTRL_REG2_M\n");
        return 1;
    }

    // Set magnetometer to continuous conversion mode
    if (i2cWriteByteData(i2c_handle_mag, MAG_CTRL_REG3_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to magnetometer MAG_CTRL_REG3_M\n");
        return 1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_acc, ACC_OUT_X_L_A | 0x80, buffer, 6) != 6) { // Enable auto-increment
        fprintf(stderr, "Failed to read accelerometer data\n");
        return 1;
    }

    // Combine high and low bytes, and convert to g
    *x = (float)((int16_t)(buffer[1] << 8 | buffer[0])) * ACC_SENSITIVITY;
    *y = (float)((int16_t)(buffer[3] << 8 | buffer[2])) * ACC_SENSITIVITY;
    *z = (float)((int16_t)(buffer[5] << 8 | buffer[4])) * ACC_SENSITIVITY;

    return 0;
}

// Read magnetometer data
int read_magnetometer(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_mag, MAG_OUT_X_L_M | 0x80, buffer, 6) != 6) { // Enable auto-increment
        fprintf(stderr, "Failed to read magnetometer data\n");
        return 1;
    }

    // Combine high and low bytes, and convert to gauss
    *x = (float)((int16_t)(buffer[0] << 8 | buffer[1])) * MAG_SENSITIVITY;
    *y = (float)((int16_t)(buffer[2] << 8 | buffer[3])) * MAG_SENSITIVITY;
    *z = (float)((int16_t)(buffer[4] << 8 | buffer[5])) * MAG_SENSITIVITY;

    return 0;
}

// Calculate tilt-compensated heading
float calculate_heading(float ax, float ay, float az, float mx, float my, float mz) {
    float roll = atan2(ay, az);
    float pitch = atan2(-ax, sqrt(ay * ay + az * az));

    float heading = atan2(my * cos(roll) - mz * sin(roll), -mx * cos(pitch) + my * sin(pitch) * cos(roll) + mz * sin(pitch) * cos(roll));

    // Convert to degrees
    heading = heading * 180 / M_PI;

    // Normalize to 0-360 degrees
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Log data to file
void log_data(float ax, float ay, float az, float mx, float my, float mz, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", timestamp, heading, ax, ay, az, mx, my, mz);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle_mag >= 0) {
        i2cClose(i2c_handle_mag);
    }
    if (i2c_handle_acc >= 0) {
        i2cClose(i2c_handle_acc);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

