int init_vl6180x() {
    int status;

    // Check sensor ID
    status = i2cReadByteData(i2c_handle, VL6180X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", status);
        return -1;
    }
    if (status != 0xB4) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", status);
        return -1;
    }

    // Mandatory initialization sequence
    status = i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to SYSTEM_FRESH_OUT_OF_RESET: %d\n", status);
        return -1;
    }
    gpioDelay(10000); // 10ms

    status = i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_MODE_GPIO1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to SYSTEM_MODE_GPIO1: %d\n", status);
        return -1;
    }
    gpioDelay(10000); // 10ms

    status = i2cWriteByteData(i2c_handle, VL6180X_REG_SYSRANGE_START, 0x01);
    if (status < 0) {
