#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Define sensor addresses and I2C bus
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define I2C_BUS 1

// Define sampling interval in milliseconds
#define SAMPLING_INTERVAL_MS 10

// Define the number of retries for I2C communication
#define MAX_RETRIES 3

// Define the maximum TDOA value (in nanoseconds)
#define MAX_TDOA 1000000000 // 1 second

// Global variables for I2C handles and log file
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_sensor_data(int i2c_handle, int *data);
int write_tdoa_to_log(FILE *log_file, int sensor1, int sensor2, long long tdoa);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1;
    int sensor2;
    long long tdoa;
} SensorData;

// Function to initialize I2C communication
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read sensor data from the IMP23ABSU
int read_sensor_data(int i2c_handle, int *data) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *data = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to write TDOA to the log file
int write_tdoa_to_log(FILE *log_file, int sensor1, int sensor2, long long tdoa) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long sec = ts.tv_sec;
    long long nsec = ts.tv_nsec;

    if (fprintf(log_file, "%lld,%lld,%d,%d,%lld\n", sec, nsec, sensor1, sensor2, tdoa) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize I2C communication for both sensors
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_data, sensor2_data;
        long long tdoa = 0;

        // Retry loop for sensor 1
        int retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sensor_data(i2c_handle1, &sensor1_data) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Retrying sensor 1 read (%d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(1); // Small delay before retrying
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor 1 data after %d retries\n", MAX_RETRIES);
            continue; // Skip to the next iteration
        }

        // Retry loop for sensor 2
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sensor_data(i2c_handle2, &sensor2_data) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Retrying sensor 2 read (%d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(1); // Small delay before retrying
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor 2 data after %d retries\n", MAX_RETRIES);
            continue; // Skip to the next iteration
        }

        // Calculate TDOA (simple difference between timestamps)
        clock_gettime(CLOCK_REALTIME, &ts);
        long long current_time_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;

        // Write TDOA to the log file
        if (write_tdoa_to_log(log_file, sensor1_data, sensor2_data, tdoa) != 0) {
            fprintf(stderr, "Error writing TDOA to log file\n");
        }

        // Delay for the sampling interval
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

