        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

