#include <pigpio.h>

// ADIS16488A Register Addresses
#define ADIS16488A_GYRO_XOUT 0x04
#define ADIS16488A_GYRO_YOUT 0x06
#define ADIS16488A_GYRO_ZOUT 0x08
#define ADIS16488A_ACCL_XOUT 0x0A
#define ADIS16488A_ACCL_YOUT 0x0C
#define ADIS16488A_ACCL_ZOUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define STALL_TIME_US 40000 // 40 us

// Global Variables
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    double gyro_x, gyro_y, gyro_z;
    double accel_x, accel_y, accel_z;
} sensor_data_t;

// Function Prototypes
int spi_read_register(uint8_t reg_addr, uint16_t *data);
int spi_write_register(uint8_t reg_addr, uint16_t data);
int read_sensor_data(sensor_data_t *data);
int log_data(const sensor_data_t *data);
void cleanup();
void signal_handler(int signal);

// Helper function to get timestamp
double get_timestamp_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (double)ts.tv_sec * 1000.0 + (double)ts.tv_nsec / 1000000.0;
}

// SPI Read Register Function
int spi_read_register(uint8_t reg_addr, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = reg_addr | 0x80; // Set MSB to 1 for read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    *data = (rx_buf[1] << 8) | rx_buf[2];
    return 0;
}

// SPI Write Register Function
int spi_write_register(uint8_t reg_addr, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = reg_addr & 0x7F; // Set MSB to 0 for write
    tx_buf[1] = (data >> 8) & 0xFF;
    tx_buf[2] = data & 0xFF;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

// Read Sensor Data Function
int read_sensor_data(sensor_data_t *data) {
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    if (spi_read_register(ADIS16488A_GYRO_XOUT, &raw_gyro_x) != 0) return -1;
    if (spi_read_register(ADIS16488A_GYRO_YOUT, &raw_gyro_y) != 0) return -1;
    if (spi_read_register(ADIS16488A_GYRO_ZOUT, &raw_gyro_z) != 0) return -1;
    if (spi_read_register(ADIS16488A_ACCL_XOUT, &raw_accel_x) != 0) return -1;
    if (spi_read_register(ADIS16488A_ACCL_YOUT, &raw_accel_y) != 0) return -1;
    if (spi_read_register(ADIS16488A_ACCL_ZOUT, &raw_accel_z) != 0) return -1;

    // Convert raw data to physical units
    data->gyro_x = (double)raw_gyro_x * 0.005; // deg/sec
    data->gyro_y = (double)raw_gyro_y * 0.005; // deg/sec
    data->gyro_z = (double)raw_gyro_z * 0.005; // deg/sec
    data->accel_x = (double)raw_accel_x * 0.00025; // g
    data->accel_y = (double)raw_accel_y * 0.00025; // g
    data->accel_z = (double)raw_accel_z * 0.00025; // g

    return 0;
}

// Log Data Function
int log_data(const sensor_data_t *data) {
    double timestamp = get_timestamp_ms();
    if (fprintf(fp, "%.3f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                timestamp, data->gyro_x, data->gyro_y, data->gyro_z,
                data->accel_x, data->accel_y, data->accel_z) < 0) {
        fprintf(stderr, "File write error\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup Function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

