#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// ADIS16448 Register Addresses
#define ADIS16448_GYRO_XOUT 0x04
#define ADIS16448_GYRO_YOUT 0x06
#define ADIS16448_GYRO_ZOUT 0x08
#define ADIS16448_ACCL_XOUT 0x0A
#define ADIS16448_ACCL_YOUT 0x0C
#define ADIS16448_ACCL_ZOUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.02  // dps/LSB
#define ACCL_SCALE 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (BCM)

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float gyro_x, gyro_y, gyro_z;
    float accl_x, accl_y, accl_z;
} sensor_data_t;

// Function prototypes
int spi_init();
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_register(uint8_t reg_addr, uint16_t *data);
sensor_data_t process_data(uint16_t gyro_x, uint16_t gyro_y, uint16_t gyro_z, uint16_t accl_x, uint16_t accl_y, uint16_t accl_z);
void signal_handler(int signal);
void cleanup();

// SPI Initialization function
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// SPI Transfer function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    int result = spiXfer(spi_handle, tx_buf, rx_buf, len);
    if (result != len) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read a single register via single register read protocol
int read_register(uint8_t reg_addr, uint16_t *data) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the SPI message for single register read
    tx_buf[0] = reg_addr | 0x80; // Set MSB to 1 for single read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spi_transfer(tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed during register read.\n");
        return -1;
    }

    // Extract the 16-bit data from the response
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

// Function to process raw data and apply scaling factors
sensor_data_t process_data(uint16_t gyro_x, uint16_t gyro_y, uint16_t gyro_z, uint16_t accl_x, uint16_t accl_y, uint16_t accl_z) {
    sensor_data_t data;

    data.gyro_x = (float)gyro_x * GYRO_SCALE;
    data.gyro_y = (float)gyro_y * GYRO_SCALE;
    data.gyro_z = (float)gyro_z * GYRO_SCALE;
    data.accl_x = (float)accl_x * ACCL_SCALE;
    data.accl_y = (float)accl_y * ACCL_SCALE;
    data.accl_z = (float)accl_z * ACCL_SCALE;

    return data;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close SPI and terminate pigpio
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Ensure CS is initially high

    // Initialize SPI
    if (spi_init() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z;

        // Read sensor data
        if (read_register(ADIS16448_GYRO_XOUT, &gyro_x) != 0 ||
            read_register(ADIS16448_GYRO_YOUT, &gyro_y) != 0 ||
            read_register(ADIS16448_GYRO_ZOUT, &gyro_z) != 0 ||
            read_register(ADIS16448_ACCL_XOUT, &accl_x) != 0 ||
            read_register(ADIS16448_ACCL_YOUT, &accl_y) != 0 ||
            read_register(ADIS16448_ACCL_ZOUT, &accl_z) != 0) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Process the data
        sensor_data_t sensor_data = process_data(gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z);

        // Print the data to the console
        printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps, Accl X: %.6f g, Accl Y: %.6f g, Accl Z: %.6f g\n",
               sensor_data.gyro_x, sensor_data.gyro_y, sensor_data.gyro_z,
               sensor_data.accl_x, sensor_data.accl_y, sensor_data.accl_z);

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

