#define ADIS16448_ACCEL_YOUT 0x0C
#define ADIS16448_ACCEL_ZOUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Scaling factors
#define GYRO_SCALE 0.05  // degrees/second per LSB
#define ACCEL_SCALE 0.00025 // g per LSB

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
