    terminate = 1;
}

// Function to read a 16-bit register from ADIS16448
int16_t read_register(uint8_t address) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the SPI message: read command (MSB = 1) + address + dummy byte
    tx_buffer[0] = 0x80 | (address << 1); // Read command + address
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    // Transfer the data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the received bytes into a 16-bit value
    int16_t value = (rx_buffer[1] << 8) | rx_buffer[2];

