        int16_t accel_x_raw = read_register(ADIS16448_ACCEL_XOUT);
        int16_t accel_y_raw = read_register(ADIS16448_ACCEL_YOUT);
        int16_t accel_z_raw = read_register(ADIS16448_ACCEL_ZOUT);

        // Check for read errors
        if (gyro_x_raw == -1 || gyro_y_raw == -1 || gyro_z_raw == -1 ||
            accel_x_raw == -1 || accel_y_raw == -1 || accel_z_raw == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(10000); // 10ms delay
            continue;
        }

        // Convert raw data to physical units
        sensor_data_t data = convert_data(gyro_x_raw, gyro_y_raw, gyro_z_raw, accel_x_raw, accel_y_raw, accel_z_raw);

        // Print the data
        printf("Gyro X: %.2f deg/s, Gyro Y: %.2f deg/s, Gyro Z: %.2f deg/s, Accel X: %.6f g, Accel Y: %.6f g, Accel Z: %.6f g\n",
               data.gyro_x, data.gyro_y, data.gyro_z, data.accel_x, data.accel_y, data.accel_z);

        // Delay for 100ms
        gpioDelay(100000); // 100ms
    }

    // Close SPI channel and terminate pigpio library
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

