// MPU6886 I2C address
#define MPU6886_ADDR 0x68

// MPU6886 register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCtrl+C pressed. Exiting...\n");
}

// Function to read a 16-bit value from the I2C device
int16_t read_i2c_word(int handle, uint8_t reg) {
    int16_t value;
    int retries = 3;

    while (retries > 0) {
        value = i2cReadWordData(handle, reg);
        if (value >= 0) {
            return value;
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d. Retrying...\n", reg, value);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return 0; // Return 0 on failure
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, MPU6886_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU6886 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU6886\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read accelerometer and gyroscope data
        int16_t accel_x = read_i2c_word(i2c_handle, ACCEL_XOUT_H);
        int16_t accel_y = read_i2c_word(i2c_handle, ACCEL_XOUT_H + 2);
        int16_t accel_z = read_i2c_word(i2c_handle, ACCEL_XOUT_H + 4);
        int16_t gyro_x  = read_i2c_word(i2c_handle, GYRO_XOUT_H);
        int16_t gyro_y  = read_i2c_word(i2c_handle, GYRO_XOUT_H + 2);
        int16_t gyro_z  = read_i2c_word(i2c_handle, GYRO_XOUT_H + 4);

        // Print the data
        printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Delay for 50ms
        gpioDelay(50000);
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

