int verify_adxl345_id() {
    int device_id = i2cReadByteData(i2c_handle, ADXL345_REG_DEVICE_ID);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%X (expected 0xE5)\n", device_id);
        return -1;
    }
    return 0;
}

