#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 Registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Sensitivity scales (adjust as needed based on your sensor's configuration)
#define ACCEL_SCALE 16384.0f  // +/- 2g
#define GYRO_SCALE  131.0f    // +/- 250 dps

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} imu_data_t;

// Function prototypes
int init_imu();
imu_data_t read_imu_data();
void log_data(imu_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the IMU
int init_imu() {
    // Wake up the sensor (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up IMU\n");
        return -1;
    }
    gpioDelay(100); // Short delay after waking up
    return 0;
}

// Read IMU data
imu_data_t read_imu_data() {
    imu_data_t data;
    char buffer[14];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer and gyroscope data in one go
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 14) < 0) {
        fprintf(stderr, "Error: Could not read IMU data\n");
        data.accel_x = data.accel_y = data.accel_z = 0.0f;
        data.gyro_x = data.gyro_y = data.gyro_z = 0.0f;
        return data;
    }

    // Combine high and low bytes for accelerometer data
    raw_accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    raw_accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Combine high and low bytes for gyroscope data
    raw_gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
    raw_gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
    raw_gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);

    // Convert to g and dps
    data.accel_x = (float)raw_accel_x / ACCEL_SCALE;
    data.accel_y = (float)raw_accel_y / ACCEL_SCALE;
    data.accel_z = (float)raw_accel_z / ACCEL_SCALE;
    data.gyro_x  = (float)raw_gyro_x  / GYRO_SCALE;
    data.gyro_y  = (float)raw_gyro_y  / GYRO_SCALE;
    data.gyro_z  = (float)raw_gyro_z  / GYRO_SCALE;

    return data;
}

// Log data to file
void log_data(imu_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize IMU
    if (init_imu() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        imu_data_t data = read_imu_data();
        log_data(data);
        gpioDelay(100); // 100 ms delay for 10 Hz sampling
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

