float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void control_led(int on);
void log_data(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize MMA8451Q
int init_mma8451q() {
    // Set to active mode, 100Hz data rate
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    return 0;
}

// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate magnitude of acceleration
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = x * SENSITIVITY;
    float y_g = y * SENSITIVITY;
    float z_g = z * SENSITIVITY;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, X: %d, Y: %d, Z: %d, Magnitude: %.2f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z, magnitude);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MMA8451Q
    if (init_mma8451q() < 0) {
        fprintf(stderr, "MMA8451Q initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > THRESHOLD) {
                control_led(1); // Turn on LED
                gpioDelay(500);  // Wait 500ms
                control_led(0); // Turn off LED
            }

            log_data(x, y, z, magnitude);
        } else {
            fprintf(stderr, "Error reading acceleration, retrying...\n");
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

