#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATAX0 0x32
#define GPIO_PIN 17
#define FREEFALL_DURATION_MS 200
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int adxl345_read_register(int reg);
int adxl345_write_register(int reg, int value);
int adxl345_read_acceleration(int *x, int *y, int *z);
int adxl345_freefall_detect();
void signal_handler(int signal);
void log_data(int x, int y, int z);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// ADXL345 initialization
int adxl345_init() {
    int devid;

    // Verify device ID
    devid = adxl345_read_register(ADXL345_REG_DEVID);
    if (devid != 0xE5) {
        fprintf(stderr, "Error: Invalid device ID: 0x%X\n", devid);
        return -1;
    }

    // Place sensor in standby mode
    if (adxl345_write_register(ADXL345_REG_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Could not put sensor in standby mode.\n");
        return -1;
    }

    // Enable freefall interrupt
    if (adxl345_write_register(ADXL345_REG_INT_ENABLE, 0x40) < 0) { // Enable freefall interrupt
        fprintf(stderr, "Error: Could not enable freefall interrupt.\n");
        return -1;
    }

    return 0;
}

// Read a register from the ADXL345
int adxl345_read_register(int reg) {
    int value = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (value < 0) {
        fprintf(stderr, "Error: I2C read failed for register 0x%X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Write a register to the ADXL345
int adxl345_write_register(int reg, int value) {
    int result = i2c_smbus_write_byte_data(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error: I2C write failed for register 0x%X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read acceleration data from the ADXL345
int adxl345_read_acceleration(int *x, int *y, int *z) {
    char data[6];
    int result = i2c_smbus_read_i2c_block_data(i2c_fd, ADXL345_REG_DATAX0, data, 6);
    if (result < 0) {
        fprintf(stderr, "Error: I2C read failed for acceleration data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Detect freefall
int adxl345_freefall_detect() {
    int int_source = adxl345_read_register(ADXL345_REG_INT_SOURCE);
    return (int_source & 0x40) ? 1 : 0;
}

// Log data to file
void log_data(int x, int y, int z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    char milliseconds[5];
    snprintf(milliseconds, sizeof(milliseconds), ".%03ld", ts.tv_nsec / 1000000);
    strcat(timestamp, milliseconds);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);
}

int main() {
    int x, y, z;
    int freefall_active = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Check for freefall
        if (adxl345_freefall_detect()) {
            if (!freefall_active) {
                freefall_active = 1;
                printf("Freefall detected!\n");
            }

            // Read acceleration data
            if (adxl345_read_acceleration(&x, &y, &z) == 0) {
                log_data(x, y, z);
            }
        } else {
            freefall_active = 0;
        }

        // Poll GPIO for interrupt
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    printf("Disabling interrupts...\n");
    adxl345_write_register(ADXL345_REG_INT_ENABLE, 0x00); // Disable freefall interrupt
    close(i2c_fd);
    gpioSetMode(GPIO_PIN, PI_INPUT); // Release the GPIO line
    gpioTerminate();
    fclose(log_file);

    return 0;
}

