    if (adxl345_init() < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Check for freefall
        if (adxl345_freefall_detect()) {
            if (!freefall_active) {
                freefall_active = 1;
                printf("Freefall detected!\n");
            }

            // Read acceleration data
            if (adxl345_read_acceleration(&x, &y, &z) == 0) {
                log_data(x, y, z);
            }
        } else {
            freefall_active = 0;
        }

        // Poll GPIO for interrupt
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    printf("Disabling interrupts...\n");
    adxl345_write_register(ADXL345_REG_INT_ENABLE, 0x00); // Disable freefall interrupt
    close(i2c_fd);
    gpioSetMode(GPIO_PIN, PI_INPUT); // Release the GPIO line
    gpioTerminate();
    fclose(log_file);

    return 0;
}

