#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27

// Scaling factors
#define ACCEL_SCALE 0.061  // mg/LSB for ±2g range
#define GYRO_SCALE 8.75   // mdps/LSB for ±250 dps range

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2 // g
#define IMPACT_THRESHOLD 2.5  // g
#define IMPACT_WINDOW 1.0     // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x;
    float accel_y;
    float accel_z;
    float gyro_x;
    float gyro_y;
    float gyro_z;
} sensor_data_t;

// Function prototypes
int init_lsm6dsr();
int read_sensor_data(sensor_data_t *data);
float calculate_acceleration_magnitude(const sensor_data_t *data);
void log_data(const sensor_data_t *data);
void fall_detection(const sensor_data_t *data, float *state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize LSM6DSR sensor
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x69\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: ±2g range, 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80 | 0x04) < 0) { // 104 Hz, ±2g
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: ±250 dps, 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80 | 0x04) < 0) { // 104 Hz, ±250 dps
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Read accelerometer and gyroscope data from LSM6DSR
int read_sensor_data(sensor_data_t *data) {
    char buffer[12];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Read gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    raw_gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g and dps
    data->accel_x = (float)raw_accel_x * ACCEL_SCALE / 1000.0;
    data->accel_y = (float)raw_accel_y * ACCEL_SCALE / 1000.0;
    data->accel_z = (float)raw_accel_z * ACCEL_SCALE / 1000.0;
    data->gyro_x = (float)raw_gyro_x * GYRO_SCALE / 1000.0;
    data->gyro_y = (float)raw_gyro_y * GYRO_SCALE / 1000.0;
    data->gyro_z = (float)raw_gyro_z * GYRO_SCALE / 1000.0;

    return 0;
}

// Calculate acceleration magnitude
float calculate_acceleration_magnitude(const sensor_data_t *data) {
    return sqrt(data->accel_x * data->accel_x + data->accel_y * data->accel_y + data->accel_z * data->accel_z);
}

// Log sensor data to CSV file
void log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Fall detection state machine
void fall_detection(const sensor_data_t *data, float *state) {
    static float last_acceleration = 0.0;
    static time_t last_impact_time = 0;
    static int impact_detected = 0;

    float acceleration_magnitude = calculate_acceleration_magnitude(data);

    if (acceleration_magnitude < FREEFALL_THRESHOLD) {
        if (*state != FREEFALL) {
            *state = FREEFALL;
            printf("Transitioned to FREEFALL state\n");
        }
    } else {
        if (*state == FREEFALL) {
            if (acceleration_magnitude > IMPACT_THRESHOLD) {
                time_t current_time = time(NULL);
                if (difftime(current_time, last_impact_time) <= IMPACT_WINDOW) {
                    *state = IMPACT;
                    printf("Transitioned to IMPACT state\n");
                    impact_detected = 1;
                } else {
                    *state = IDLE;
                    printf("Transitioned back to IDLE state\n");
                }
                last_impact_time = current_time;
            } else {
                *state = IDLE;
                printf("Transitioned back to IDLE state\n");
            }
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "Timestamp,Accel_X(g),Accel_Y(g),Accel_Z(g),Gyro_X(dps),Gyro_Y(dps),Gyro_Z(dps)\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    float current_state = IDLE;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
            fall_detection(&sensor_data, &current_state);
            printf("Current state: %s\n", (current_state == IDLE) ? "IDLE" : (current_state == FREEFALL) ? "FREEFALL" : "IMPACT");
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(10); // 100 Hz sampling rate (10 ms delay)
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

