#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADIS16266 Register Addresses
#define WHO_AM_I 0x02
#define GYRO_XOUT_L 0x04
#define GYRO_XOUT_H 0x05
#define GYRO_YOUT_L 0x06
#define GYRO_YOUT_H 0x07
#define GYRO_ZOUT_L 0x08
#define GYRO_ZOUT_H 0x09
#define SMPL_PRD 0x16
#define GLOB_CMD 0x1E
#define GLOB_CTRL1 0x1B
#define GLOB_CTRL2 0x1C

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t reg_addr, uint16_t *data);
int spi_write_register(uint8_t reg_addr, uint16_t data);
int adis16266_init();
void signal_handler(int signal);
void log_data(float gyro_x, float gyro_y, float gyro_z);

// Structure to hold gyroscope data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
} gyro_data_t;

// Function to read a register from the ADIS16266
int spi_read_register(uint8_t reg_addr, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    *data = (rx_buf[1] << 8) | rx_buf[2];
    return 0;
}

// Function to write a register to the ADIS16266
int spi_write_register(uint8_t reg_addr, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF; // LSB of data

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to initialize the ADIS16266
int adis16266_init() {
    // Verify WHO_AM_I register
    uint16_t who_am_i;
    if (spi_read_register(WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x3F) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x3F, got 0x%04X\n", who_am_i);
        return -1;
    }

    // Set sample period (optional, default is 1000)
    if (spi_write_register(SMPL_PRD, 1000) != 0) {
        fprintf(stderr, "Error setting sample period\n");
        return -1;
    }

    // Enable continuous measurement mode (optional, default is on)
    if (spi_write_register(GLOB_CTRL1, 0x0400) != 0) {
        fprintf(stderr, "Error enabling continuous measurement mode\n");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to log data to a CSV file
void log_data(float gyro_x, float gyro_y, float gyro_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f,%.4f\n", timestamp, gyro_x, gyro_y, gyro_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADIS16266
    if (adis16266_init() != 0) {
        fprintf(stderr, "ADIS16266 initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
