    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
        }
        gpioDelay(10000); // 10ms delay
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

