#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_MS 500

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set the GPIO pin as an input
int setup_gpio_input() {
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable internal pull-up resistor
    return 0;
}

// Function to read the GPIO pin value
int read_gpio_value() {
    return gpioRead(GPIO_PIN);
}

// Function to write a log entry to the file
int write_log_entry(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", buf, message);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Function to handle flame detection
void handle_flame_detection() {
    printf("FLAME DETECTED!\n");
    write_log_entry("Flame detected");
}

// Function to log errors to the file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s - ERROR: %s\n", buf, message);
        fflush(log_file);
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Setup GPIO pin as input
    if (setup_gpio_input() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int gpio_value = read_gpio_value();

        if (gpio_value == 0) { // Flame detected (LOW signal)
            handle_flame_detection();
        } else { // No flame (HIGH signal)
            write_log_entry("No flame");
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for 500ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

