#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define LOG_FILE "conveyor_log.txt"
#define HALT_THRESHOLD 0 // Logic 1

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int log_data(int sensor1_state, int sensor2_state);
void handle_halt();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorData;

int main() {
    SensorData sensor_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor states
        sensor_data.sensor1_state = read_sensor(SENSOR1_GPIO);
        sensor_data.sensor2_state = read_sensor(SENSOR2_GPIO);

        // Log the data
        if (log_data(sensor_data.sensor1_state, sensor_data.sensor2_state) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Check for halt condition
        if (sensor_data.sensor1_state == HALT_THRESHOLD && sensor_data.sensor2_state == HALT_THRESHOLD) {
            handle_halt();
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0;
}

// Read the state of a sensor
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio);
        return -1; // Indicate an error
    }
    return value;
}

// Log sensor data to a file
int log_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_state, sensor2_state) < 0) {
        perror("Error writing to log file");
        return 1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Handle the halt condition
void handle_halt() {
    printf("CONVEYOR HALTED!\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received (%d). Shutting down...\n", signal);
}

