void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, MMA8452Q_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Verify sensor identity
int verify_sensor() {
    int who_am_i = i2cReadByteData(i2c_fd, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    printf("Sensor verified (WHO_AM_I = 0x%02X)\n", who_am_i);
    return 0;
}

// Configure accelerometer
int configure_accelerometer() {
    int status = i2cWriteByteData(i2c_fd, CTRL_REG1, DATA_RATE_100HZ);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Place the sensor in standby mode
    status = i2cWriteByteData(i2c_fd, CTRL_REG1, 0x02); // Standby mode
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby): %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(100); // Wait for standby to complete

    // Re-enable active mode
    status = i2cWriteByteData(i2c_fd, CTRL_REG1, DATA_RATE_100HZ);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active): %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(100); // Wait for active mode to start

    printf("Accelerometer configured for 100 Hz data rate\n");
    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    int status = i2cReadI2CBlockData(i2c_fd, DATA_REG_START, data, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Calculate tilt angle
float calculate_tilt(int16_t x, int16_t y, int16_t z) {
    float tilt_x = atan2((float)x, (float)z) * 180.0f / M_PI;
    float tilt_y = atan2((float)y, (float)z) * 180.0f / M_PI;
    return (tilt_x > 45.0f || tilt_y > 45.0f) ? 1.0f : 0.0f;
}

// Log tilt event
int log_tilt_event(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() != 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure accelerometer
    if (configure_accelerometer() != 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    while (!terminate) {
        if (read_accelerometer_data(&x, &y, &z) == 0) {
            float tilt = calculate_tilt(x, y, z);

            if (tilt > 0.0f) {
                if (log_tilt_event(x, y, z) != 0) {
                    fprintf(stderr, "Error logging tilt event\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
        }

        gpioDelay(10); // 10 ms delay for 100 Hz data rate
    }

    // Cleanup
    printf("Closing I2C device...\n");
    i2cClose(i2c_fd);

    printf("Closing log file...\n");
    fclose(log_file);

    printf("Terminating pigpio...\n");
    gpioTerminate();

    printf("Exiting...\n");
    return 0;
}

