#include <string.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_OUT_X_L   0x28
#define LIS3MDL_OUT_X_H   0x29
#define LIS3MDL_OUT_Y_L   0x2A
#define LIS3MDL_OUT_Y_H   0x2B
#define LIS3MDL_OUT_Z_L   0x2C
#define LIS3MDL_OUT_Z_H   0x2D

// Calibration constants
#define OFFSET_X 0.0
#define OFFSET_Y 0.0
#define OFFSET_Z 0.0
#define SCALE 0.146 // mG/LSB

// Metal detector threshold
#define METAL_THRESHOLD 800.0 // mG

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lis3mdl();
int read_magnetic_data(int16_t *x, int16_t *y, int16_t *z);
float calibrate_data(int16_t x, int16_t y, int16_t z);
float calculate_magnitude(float x, float y, float z);
void log_data(float x, float y, float z);
void metal_detector_alert(float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize LIS3MDL sensor
int init_lis3mdl() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Set CTRL_REG1: 100 Hz, Continuous conversion, Enable X, Y, Z axes
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70); //0b01110000
        if (status >= 0) break; // Success
        fprintf(stderr, "Error writing to CTRL_REG1, retrying...\n");
        gpioDelay(10000); // 10ms delay
        retries--;
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to initialize LIS3MDL after multiple retries.\n");
        return -1;
    }

    // Set CTRL_REG3: ±4 gauss full scale
    status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00); //0b00000000
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG3, retrying...\n");
        gpioDelay(10000); // 10ms delay
        retries--;
    } else {
        if (retries == 0) {
            fprintf(stderr, "Failed to initialize LIS3MDL after multiple retries.\n");
            return -1;
        }
    }

    return 0;
}

// Read magnetic data from LIS3MDL
int read_magnetic_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading magnetic data, retrying...\n");
        gpioDelay(10000); // 10ms delay
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate magnetic data
float calibrate_data(int16_t x, int16_t y, int16_t z) {
    return (float)x * OFFSET_X + (float)y * OFFSET_Y + (float)z * OFFSET_Z;
}

// Calculate magnitude of magnetic field
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log data to file
void log_data(float x, float y, float z) {
    fprintf(log_file, "%f,%f,%f\n", x, y, z);
    fflush(log_file);
}

// Metal detector alert
void metal_detector_alert(float magnitude) {
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal Detector Alert: Magnitude = %.2f mG\n", magnitude);
    }
}

int main() {
    int16_t x_raw, y_raw, z_raw;
    float x_calibrated, y_calibrated, z_calibrated, magnitude;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3MDL sensor
    if (init_lis3mdl() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read magnetic data
        if (read_magnetic_data(&x_raw, &y_raw, &z_raw) == 0) {
            // Calibrate data
            x_calibrated = calibrate_data(x_raw, y_raw, z_raw);
            y_calibrated = calibrate_data(x_raw, y_raw, z_raw);
            z_calibrated = calibrate_data(x_raw, y_raw, z_raw);

            // Calculate magnitude
            magnitude = calculate_magnitude(x_calibrated, y_calibrated, z_calibrated);

            // Log data
            log_data(x_calibrated, y_calibrated, z_calibrated);

            // Metal detector alert
            metal_detector_alert(magnitude);
        } else {
            fprintf(stderr, "Failed to read magnetic data.\n");
        }

        gpioDelay(100000); // 100ms delay (10 Hz)
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

