#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL354B Register Addresses
#define ADXL354B_PARTID 0x02
#define ADXL354B_RESET 0x08
#define ADXL354B_POWER_CTL 0x2D
#define ADXL354B_STATUS 0x00
#define ADXL354B_XDATA_L 0x08
#define ADXL354B_XDATA_H 0x09
#define ADXL354B_YDATA_L 0x0A
#define ADXL354B_YDATA_H 0x0B
#define ADXL354B_ZDATA_L 0x0C
#define ADXL354B_ZDATA_H 0x0D

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int spi_read_register(int handle, uint8_t reg, uint8_t *value);
int adxl354b_reset(int handle);
int adxl354b_set_run(int handle);
int adxl354b_check_sensor_presence(int handle);
int adxl354b_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z);
void log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// SPI Write Function
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx[2];
    char rx[2];

    tx[0] = reg | 0x80; // Set MSB for write
    tx[1] = value;

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI Write Error: Register 0x%02X, Value 0x%02X\n", reg, value);
        return -1;
    }

    return 0;
}

// SPI Read Function
int spi_read_register(int handle, uint8_t reg, uint8_t *value) {
    char tx[2];
    char rx[2];

    tx[0] = reg & 0x7F; // Clear MSB for read
    tx[1] = 0x00; // Dummy byte for reading

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI Read Error: Register 0x%02X\n", reg);
        return -1;
    }

    *value = rx[1];
    return 0;
}

// Reset Function
int adxl354b_reset(int handle) {
    if (spi_write_register(handle, ADXL354B_RESET, 0x52) != 0) {
        fprintf(stderr, "Reset Failed\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay
    return 0;
}

// Set Run Function
int adxl354b_set_run(int handle) {
    if (spi_write_register(handle, ADXL354B_POWER_CTL, 0x02) != 0) {
        fprintf(stderr, "Set Run Failed\n");
        return -1;
    }
    return 0;
}

// Check Sensor Presence Function
int adxl354b_check_sensor_presence(int handle) {
    uint8_t partid;
    if (spi_read_register(handle, ADXL354B_PARTID, &partid) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }

    if (partid != 0x34) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X (expected 0x34)\n", partid);
        return -1;
    }

    return 0;
}

// Read Acceleration Data Function
int adxl354b_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char tx[7];
    char rx[7];

    tx[0] = ADXL354B_XDATA_L | 0x80; // Read X, Y, Z data
    tx[1] = 0x80; // Read multiple bytes
    tx[2] = 0x00;
    tx[3] = 0x00;
    tx[4] = 0x00;
    tx[5] = 0x00;
    tx[6] = 0x00;

    if (spiXfer(handle, tx, rx, 7) != 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    *x = (int16_t)((rx[2] << 8) | rx[1]);
    *y = (int16_t)((rx[4] << 8) | rx[3]);
    *z = (int16_t)((rx[6] << 8) | rx[5]);

    return 0;
}

// Log Data Function
void log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int16_t x, y, z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Reset the device
    if (adxl354b_reset(spi_handle) != 0) {
        fprintf(stderr, "Reset failed, exiting\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

