    char tx_buffer[2];
    char rx_buffer[2];

    // Read X Gyro
    tx_buffer[0] = X_GYRO_OUT | 0x80; // MSB = 1 for read
    tx_buffer[1] = 0x00; // Dummy byte
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    data.x_gyro = (int16_t)((rx_buffer[0] << 8) | rx_buffer[1]);

    // Read Y Gyro
    tx_buffer[0] = Y_GYRO_OUT | 0x80;
    tx_buffer[1] = 0x00;
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    data.y_gyro = (int16_t)((rx_buffer[0] << 8) | rx_buffer[1]);

    // Read Z Gyro
    tx_buffer[0] = Z_GYRO_OUT | 0x80;
    tx_buffer[1] = 0x00;
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    data.z_gyro = (int16_t)((rx_buffer[0] << 8) | rx_buffer[1]);

    // Read X Accel
    tx_buffer[0] = X_ACCEL_OUT | 0x80;
    tx_buffer[1] = 0x00;
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    data.x_accel = (int16_t)((rx_buffer[0] << 8) | rx_buffer[1]);

