    tx_buffer[0] = Z_ACCEL_OUT | 0x80;
    tx_buffer[1] = 0x00;
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    data.z_accel = (int16_t)((rx_buffer[0] << 8) | rx_buffer[1]);

    return data;
}

