void process_imu_data(imu_data_t data) {
    data.x_gyro *= GYRO_SCALE;
    data.y_gyro *= GYRO_SCALE;
    data.z_gyro *= GYRO_SCALE;
    data.x_accel *= ACCEL_SCALE;
    data.y_accel *= ACCEL_SCALE;
    data.z_accel *= ACCEL_SCALE;
