#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define POLLING_INTERVAL_MS 1000 // 1 second
#define DEBOUNCE_DELAY_MS 50

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle Ctrl+C signal
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO line
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the sensor value with debouncing
int read_sensor() {
    int value = gpioRead(GPIO_PIN);
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
    return value;
}

// Function to log the message with timestamp
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Function to simulate self-parking sequence completion
void simulate_sequence_completion() {
    log_message("Self-parking sequence completed");
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("obstacle_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Self-parking sequence started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) { // Obstacle detected (LOW signal)
            log_message("Self-parking sequence started");
            simulate_sequence_completion();
            break; // Exit the loop after detection
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Wait for 1 second
    }

    // Clean up
    log_message("Self-parking sequence stopped");
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

