    if (sensor2_value < 0) {
        fprintf(stderr, "Error reading sensor 2: %d\n", sensor2_value);
        return -1; // Indicate an error
    }

    return (sensor1_value << 1) | sensor2_value; // Combine the two values into a single integer
}

