#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// ADIS16266 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define SMPL_PRD  0x36
#define GLOB_CMD  0x68

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_CS_GPIO 8      // GPIO8 (BCM)
#define SPI_DEVICE "/dev/spidev0.0"

// Scale factor for angular rates (deg/sec/LSB)
#define SCALE_FACTOR 0.02

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int spi_init();
int adis16266_read_register(uint8_t reg_addr, uint16_t *data);
int adis16266_write_register(uint8_t reg_addr, uint16_t data);
int adis16266_read_gyro_data(gyro_data_t *gyro_data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI interface
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read a register from the ADIS16266
int adis16266_read_register(uint8_t reg_addr, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading two bytes
    tx_buf[2] = 0x00; // Dummy byte for reading two bytes

    // Transfer the data
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract the data from the receive buffer
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

// Write a register in the ADIS16266
int adis16266_write_register(uint8_t reg_addr, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer
    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF; // LSB of data

    // Transfer the data
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    return 0;
}

// Read gyroscope data from the ADIS16266
int adis16266_read_gyro_data(gyro_data_t *gyro_data) {
    uint16_t x_raw, y_raw, z_raw;

    // Read X, Y, and Z gyroscope data
    if (adis16266_read_register(XGYRO_OUT, &x_raw) != 0) return -1;
    if (adis16266_read_register(YGYRO_OUT, &y_raw) != 0) return -1;
    if (adis16266_read_register(ZGYRO_OUT, &z_raw) != 0) return -1;

    // Convert raw data to degrees per second
    gyro_data->x = (float)((int16_t)x_raw) * SCALE_FACTOR;
    gyro_data->y = (float)((int16_t)y_raw) * SCALE_FACTOR;
    gyro_data->z = (float)((int16_t)z_raw) * SCALE_FACTOR;

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    gyro_data_t gyro_data;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 ms

    while (!terminate) {
        // Read gyroscope data
        if (adis16266_read_gyro_data(&gyro_data) == 0) {
            // Print gyroscope data
            printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", gyro_data.x, gyro_data.y, gyro_data.z);
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        // Sleep for 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

