#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27

// Sensitivity values (adjust based on your configuration)
#define ACCEL_SENSITIVITY 0.061  // mg/LSB, for +/- 2g range
#define GYRO_SENSITIVITY 4.375  // mdps/LSB, for +/- 250 dps range

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg)
{
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from an I2C register
int read_block(int handle, uint8_t reg, char *buf, int count)
{
    int result = i2cReadI2CBlockData(handle, reg, buf, count);
    if (result < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to initialize the LSM6DSR
int init_lsm6dsr(int handle)
{
    // Check WHO_AM_I register
    int who_am_i = read_register(handle, WHO_AM_I);
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I register mismatch: 0x%02X (expected 0x69)\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: +/- 2g, 104 Hz
    if (write_register(handle, CTRL1_XL, 0x60) < 0) return -1; // 01100000

    // Configure gyroscope: +/- 250 dps, 104 Hz
    if (write_register(handle, CTRL2_G, 0x60) < 0) return -1; // 01100000

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_imu_data(int handle, float *ax, float *ay, float *az, float *gx, float *gy, float *gz)
{
    char buf[12];

    if (read_block(handle, OUTX_L_XL, buf, 12) < 0) return -1;

    // Combine high and low bytes, convert to g and dps
    int16_t raw_ax = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_ay = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_az = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t raw_gx = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t raw_gy = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raw_gz = (int16_t)((buf[11] << 8) | buf[10]);

    *ax = (float)raw_ax * ACCEL_SENSITIVITY / 1000.0f; // Convert to g
    *ay = (float)raw_ay * ACCEL_SENSITIVITY / 1000.0f;
    *az = (float)raw_az * ACCEL_SENSITIVITY / 1000.0f;
    *gx = (float)raw_gx * GYRO_SENSITIVITY / 1000.0f; // Convert to dps
    *gy = (float)raw_gy * GYRO_SENSITIVITY / 1000.0f;
    *gz = (float)raw_gz * GYRO_SENSITIVITY / 1000.0f;

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr(i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    float ax, ay, az, gx, gy, gz;
    while (!terminate) {
        if (read_imu_data(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: %.3f %.3f %.3f  Gyro: %.3f %.3f %.3f\n", ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Error reading IMU data\n");
        }
        gpioDelay(100000); // 100 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

