#define FXOS8700_REG_OUT_Z_LSB 0x06
#define FXOS8700_REG_OUT_MAG_X_MSB 0x33
#define FXOS8700_REG_OUT_MAG_X_LSB 0x34
#define FXOS8700_REG_OUT_MAG_Y_MSB 0x35
#define FXOS8700_REG_OUT_MAG_Y_LSB 0x36
#define FXOS8700_REG_OUT_MAG_Z_MSB 0x37
#define FXOS8700_REG_OUT_MAG_Z_LSB 0x38
#define FXOS8700_REG_CTRL_REG1 0x2A
#define FXOS8700_REG_CTRL_REG2 0x2B
#define FXOS8700_REG_M_CTRL 0x5B
#define FXOS8700_REG_M_CTRL_M 0x5C
#define FXOS8700_REG_ID 0x0D

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read a single byte from the FXOS8700
int read_register(int handle, uint8_t reg) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d. Retrying...\n", reg, result);
            gpioDelay(10); // Small delay before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to write a single byte to the FXOS8700
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0;
        } else {
            fprintf(stderr, "Error writing to register 0x%02X: %d. Retrying...\n", reg, result);
            gpioDelay(10); // Small delay before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to write to register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

