    // Initialize the sensor
    if (write_register(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x01) != 0) { // Active mode, 100 Hz ODR
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (write_register(i2c_handle, FXOS8700_REG_CTRL_REG2, 0x02) != 0) { // High resolution
        fprintf(stderr, "Failed to write to CTRL_REG2\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (write_register(i2c_handle, FXOS8700_REG_M_CTRL, 0x1F) != 0) { // Hybrid mode
        fprintf(stderr, "Failed to write to M_CTRL\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (write_register(i2c_handle, FXOS8700_REG_M_CTRL_M, 0x00) != 0) { // Continuous conversion
        fprintf(stderr, "Failed to write to M_CTRL_M\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

