        // Read block of data
        if (read_block(i2c_handle, FXOS8700_REG_OUT_X_MSB, block_data, 12) == 0) {
            // Extract accelerometer data
            int16_t accel_x = (int16_t)((block_data[0] << 6) | (block_data[1] >> 2));
            int16_t accel_y = (int16_t)((block_data[2] << 6) | (block_data[3] >> 2));
            int16_t accel_z = (int16_t)((block_data[4] << 6) | (block_data[5] >> 2));

