#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// Tilt threshold (degrees)
#define TILT_THRESHOLD 30.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_adxl345();
int read_acceleration_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
int log_tilt_event(float angle);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function to initialize the ADXL345
int initialize_adxl345() {
    // Set power control register to start measurement
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error: Could not initialize ADXL345.\n");
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration_data(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    // Read 6 bytes of data starting from DATAX0
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, data, 6) != 6) {
        fprintf(stderr, "Error: Could not read acceleration data.\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Function to calculate tilt angle from accelerometer data
float calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 256.0; // Convert to g's (assuming +/- 2g range)
    float y_g = (float)y / 256.0;
    float z_g = (float)z / 256.0;

    float angle_x = atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180 / M_PI;
    float angle_y = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180 / M_PI;
    float angle_z = atan2(z_g, sqrt(x_g * x_g + y_g * y_g)) * 180 / M_PI;

    return angle_z; // Return roll angle
}

// Function to log tilt event to file
int log_tilt_event(float angle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open log file in append mode
    fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return -1;
    }

    // Write log entry
    fprintf(fp, "%s - Tilt angle: %.2f degrees\n", timestamp, angle);

    // Close log file
    fclose(fp);

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    float tilt_angle;

    // Main loop
    while (program_running) {
        // Read acceleration data
        if (read_acceleration_data(&x, &y, &z) == 0) {
            // Calculate tilt angle
            tilt_angle = calculate_tilt_angle(x, y, z);

            // Check if tilt exceeds threshold
            if (fabs(tilt_angle) > TILT_THRESHOLD) {
                // Log tilt event
                if (log_tilt_event(tilt_angle) != 0) {
                    fprintf(stderr, "Error: Could not log tilt event.\n");
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

