// Function to calculate tilt angle from accelerometer data
float calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 256.0; // Convert to g's (assuming +/- 2g range)
    float y_g = (float)y / 256.0;
    float z_g = (float)z / 256.0;

    float angle_x = atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180 / M_PI;
    float angle_y = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180 / M_PI;
    float angle_z = atan2(z_g, sqrt(x_g * x_g + y_g * y_g)) * 180 / M_PI;

    return angle_z; // Return roll angle
}

// Function to log tilt event to file
int log_tilt_event(float angle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open log file in append mode
    fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return -1;
    }

    // Write log entry
    fprintf(fp, "%s - Tilt angle: %.2f degrees\n", timestamp, angle);

    // Close log file
    fclose(fp);

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    float tilt_angle;

    // Main loop
    while (program_running) {
        // Read acceleration data
        if (read_acceleration_data(&x, &y, &z) == 0) {
            // Calculate tilt angle
            tilt_angle = calculate_tilt_angle(x, y, z);

            // Check if tilt exceeds threshold
            if (fabs(tilt_angle) > TILT_THRESHOLD) {
                // Log tilt event
                if (log_tilt_event(tilt_angle) != 0) {
                    fprintf(stderr, "Error: Could not log tilt event.\n");
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

