#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5 // Seconds
#define SAMPLE_RATE 1000 // Hz
#define THRESHOLD 0 // Default threshold

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
int calculate_high_count(int *samples, int num_samples);
int check_threshold(int high_count, int threshold);
void log_message(const char *message);
void signal_handler(int signal);
void cleanup();

int main(int argc, char *argv[]) {
    int threshold = THRESHOLD; // Default threshold

    // Parse command-line argument
    if (argc > 1) {
        char *endptr;
        threshold = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || threshold <= 0) {
            fprintf(stderr, "Error: Invalid threshold value. Using default threshold of 0.\n");
            threshold = 0;
        }
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("sound_sensor.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        cleanup();
        return 1;
    }

    log_message("Program started.");

    // Main loop
    while (program_running) {
        int samples[WINDOW_SIZE * SAMPLE_RATE];
        int sample_index = 0;

        // Sample the sensor for the current window
        for (int i = 0; i < WINDOW_SIZE * SAMPLE_RATE; ++i) {
            int sample = read_sensor();
            if (sample < 0) {
                log_message("Error reading sensor.");
                program_running = 0; // Stop on sensor read error
                break;
            }
            samples[sample_index++] = sample;
            gpioDelay(1000); // 1 ms delay
        }

        // Calculate high count
        int high_count = calculate_high_count(samples, sample_index);

        // Check threshold and log message
        if (check_threshold(high_count, threshold)) {
            log_message("ALERT");
        } else {
            log_message("OK");
        }

        gpioDelay(1000); // 1 second delay
    }

    // Cleanup and exit
    cleanup();
    log_message("Program terminated.");
    return 0;
}

// Initialize pigpio and set GPIO mode
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

// Read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Calculate the number of high readings in the samples
int calculate_high_count(int *samples, int num_samples) {
    int high_count = 0;
    for (int i = 0; i < num_samples; ++i) {
        if (samples[i] == 1) {
            high_count++;
        }
    }
    return high_count;
}

// Check if the high count exceeds the threshold
int check_threshold(int high_count, int threshold) {
    return high_count > threshold;
}

// Log a message to the log file with a timestamp
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the message is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_message("Signal received, shutting down...");
}

// Cleanup resources before exiting
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

