#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for door locks
#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27

// Define access log file
#define ACCESS_LOG_FILE "access_log.txt"

// Define security code range
#define SECURITY_CODE_MIN 100000
#define SECURITY_CODE_MAX 999999

// Define access duration (seconds)
#define ACCESS_DURATION 5

// Define debounce delay (milliseconds)
#define DEBOUNCE_DELAY 500

// Define pigpio library version
#define PIGPIO_VERSION 3.5

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *access_log_file = NULL;

// Function prototypes
int initialize_gpio();
int generate_security_code();
int read_user_input(int *code);
int compare_codes(int generated_code, int entered_code);
int log_access(const char *security_code);
void unlock_door(int door_gpio);
void lock_door(int door_gpio);
void signal_handler(int signal);

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(DOOR_A_GPIO, PI_OUTPUT);
    gpioSetMode(DOOR_B_GPIO, PI_OUTPUT);

    // Set initial state to LOW (locks energized)
    gpioWrite(DOOR_A_GPIO, 0);
    gpioWrite(DOOR_B_GPIO, 0);

    return 0; // Indicate success
}

// Function to generate a random six-digit security code
int generate_security_code() {
    return (rand() % (SECURITY_CODE_MAX - SECURITY_CODE_MIN + 1)) + SECURITY_CODE_MIN;
}

// Function to read user input and validate it as a six-digit number
int read_user_input(int *code) {
    char input[7]; // Buffer to store user input (6 digits + null terminator)
    int i = 0;

    printf("Enter security code: ");
    if (fgets(input, sizeof(input), stdin) == NULL) {
        fprintf(stderr, "Error reading input\n");
        return 1; // Indicate failure
    }

    // Remove trailing newline character
    input[strcspn(input, "\n")] = 0;

    // Validate input
    if (strlen(input) != 6 || !isdigit(input[0]) || !isdigit(input[1]) ||
        !isdigit(input[2]) || !isdigit(input[3]) || !isdigit(input[4]) || !isdigit(input[5])) {
        fprintf(stderr, "Invalid input. Please enter a six-digit number.\n");
        return 1; // Indicate failure
    }

    // Convert input to integer
    *code = atoi(input);

    return 0; // Indicate success
}

// Function to compare two six-digit numbers
int compare_codes(int generated_code, int entered_code) {
    return (generated_code == entered_code) ? 0 : 1;
}

// Function to log access to the access log file
int log_access(const char *security_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (access_log_file != NULL) {
        fprintf(access_log_file, "%s,%s\n", timestamp, security_code);
        fflush(access_log_file); // Ensure data is written to disk immediately
        return 0; // Indicate success
    } else {
        fprintf(stderr, "Error: Access log file is not open.\n");
        return 1; // Indicate failure
    }
}

// Function to unlock a door
void unlock_door(int door_gpio) {
    gpioWrite(door_gpio, 1); // Set GPIO HIGH to unlock the door
    printf("Door unlocked\n");
}

// Function to lock a door
void lock_door(int door_gpio) {
    gpioWrite(door_gpio, 0); // Set GPIO LOW to lock the door
    printf("Door locked\n");
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    // Open access log file
    access_log_file = fopen(ACCESS_LOG_FILE, "a");
    if (access_log_file == NULL) {
        fprintf(stderr, "Error opening access log file!\n");
        gpioTerminate(); // Clean up GPIO before exiting
        return 1; // Exit if file opening fails
    }

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Generate security code
        int security_code = generate_security_code();
        printf("Generated security code: %d\n", security_code);

        // Read user input
        int entered_code;
        if (read_user_input(&entered_code) != 0) {
            continue; // Skip to the next iteration if input is invalid
        }

        // Compare codes
        int code_match = compare_codes(security_code, entered_code);

        // Log access if code is correct
        if (code_match == 0) {
            printf("Access granted!\n");
            log_access((char*)security_code);
            unlock_door(DOOR_A_GPIO);
            sleep(ACCESS_DURATION);
            lock_door(DOOR_A_GPIO);
        } else {
            printf("Access denied!\n");
        }

        // Debounce delay
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
    }

    // Clean up resources before exiting
    printf("Cleaning up resources...\n");
    lock_door(DOOR_A_GPIO);
    lock_door(DOOR_B_GPIO);
    fclose(access_log_file);
    gpioTerminate();

    printf("Door access control system stopped.\n");

    return 0;
}

