#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "light_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read BH1750FVI sensor
int read_bh1750(float *lux) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Send start measurement command
        if (i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(180000); // Wait for conversion (at least 180ms)

        // Read 2 bytes of data
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Convert to lux
            uint16_t raw_value = (buf[0] << 8) | buf[1];
            *lux = (float)raw_value / 1.2;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device: %d\n", result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read BH1750FVI after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

