#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFT_RESET 0x80
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42

// GPIO pin for PWM output
#define PWM_PIN 18

// PWM frequency
#define PWM_FREQUENCY 440

// TCP port
#define TCP_PORT 12345

// Shared secret
#define SHARED_SECRET "MySecretKey"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_data(unsigned short *touch_data);
int tcp_server_setup(int port);
void handle_client(int client_socket);
void play_tone(int frequency);
void log_frequency(int frequency);
void signal_handler(int signal);

// Structure to hold MPR121 configuration
typedef struct {
    int touch_threshold;
    int release_threshold;
} mpr121_config_t;

// Function to initialize the MPR121
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFT_RESET, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity
    mpr121_config_t config = {
        .touch_threshold = 0x30, // Touch threshold for all electrodes
        .release_threshold = 0x10  // Release threshold for all electrodes
    };

    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, config.touch_threshold) < 0) {
        fprintf(stderr, "Error: Failed to set touch threshold\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG + 2, config.release_threshold) < 0) {
        fprintf(stderr, "Error: Failed to set release threshold\n");
        return -1;
    }

    return 0;
}

// Function to read touch data from the MPR121
int mpr121_read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }

    *touch_data = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to set PWM frequency
void set_pwm_frequency(int frequency) {
    gpioSetPWMfrequency(PWM_PIN, frequency);
}

// Function to play a tone
void play_tone(int frequency) {
    set_pwm_frequency(frequency);
    gpioPWM(PWM_PIN, 128); // 50% duty cycle
    gpioDelay(5000000);    // 5 seconds
    gpioPWM(PWM_PIN, 0);   // Stop the tone
}

// Function to log frequency to file
void log_frequency(int frequency) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %d Hz\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fflush(log_file);
}

// Function to handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data");
        return;
    }

    // Check for authentication
    if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0) {
        char *shared_secret = strstr(buffer, SHARED_SECRET);
        if (shared_secret != NULL) {
            // Check if the secret is present and correct
            if (strlen(shared_secret) == strlen(SHARED_SECRET)) {
                // Extract frequency from the message
                int frequency = atoi(shared_secret + strlen(SHARED_SECRET) + 1);

                // Play the tone
                play_tone(frequency);

                // Log the frequency
                log_frequency(frequency);

                printf("Authentication successful. Frequency: %d Hz\n", frequency);
            } else {
                fprintf(stderr, "Error: Invalid shared secret\n");
            }
        } else {
            fprintf(stderr, "Error: Shared secret not found\n");
        }
    } else {
        fprintf(stderr, "Error: Invalid command\n");
    }
    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioPWM(PWM_PIN, 0); // Stop PWM
    i2cClose(i2c_handle);
    close(server_fd);
    close(new_socket);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C interface
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM pin as output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency (optional, can be changed later)
    set_pwm_frequency(PWM_FREQUENCY);

    // Open log file
    log_file = fopen("frequency_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up TCP server
    server_fd = tcp_server_setup(TCP_PORT);
    if (server_fd < 0) {
        fprintf(stderr, "Error: TCP server setup failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", TCP_PORT);

    // Accept incoming connections
    struct sockaddr_in client_addr;
    int client_socket;
    socklen_t client_len = sizeof(client_addr);

    while (1) {
        client_socket = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        handle_client(client_socket);
    }

    // The following lines will never be reached due to the infinite loop
    close(server_fd);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

int tcp_server_setup(int port) {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    // Forcefully attaching socket to the port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        return -1;
    }

    return server_fd;
}

