#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define LSM303_REG_M_CTRL_REG1_A 0x20
#define LSM303_REG_M_CTRL_REG2_A 0x21
#define LSM303_REG_M_OUT_X_L_A 0x28
#define LSM303_REG_M_OUT_X_H_A 0x29
#define LSM303_REG_M_OUT_Y_L_A 0x2A
#define LSM303_REG_M_OUT_Y_H_A 0x2B
#define LSM303_REG_M_OUT_Z_L_A 0x2C
#define LSM303_REG_M_OUT_Z_H_A 0x2D

// LED GPIO pin (BCM numbering)
#define LED_PIN 17

// PWM Range
#define PWM_RANGE 1024

// Global variables
static int i2c_fd;
static volatile sig_atomic_t keep_running = 1;

// Function prototypes
int init_i2c(int address);
int init_magnetometer(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void set_led_brightness(int brightness);
void signal_handler(int sig);

// Signal handler to catch SIGINT and SIGTERM
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

// Initialize I2C communication
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Initialize the magnetometer
int init_magnetometer(int fd) {
    // Set to continuous conversion mode (100 Hz)
    if (wiringPiI2CWriteReg8(fd, LSM303_REG_M_CTRL_REG1_A, 0x70) == -1) {
        fprintf(stderr, "Error writing to CTRL_REG1_A: %s\n", strerror(errno));
        return -1;
    }

