#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Hard iron offsets
#define NUM_SAMPLES 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int initialize_magnetometer();
magnetometer_data_t read_magnetometer_data();
void apply_hard_iron_offsets(magnetometer_data_t raw_data, float *x_offset, float *y_offset, float *z_offset, magnetometer_data_t *offset_data);
void update_running_average(float x, float y, float z, float *running_average_x, float *running_average_y, float *running_average_z, int *sample_index);
void print_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the HMC5883L magnetometer
int initialize_magnetometer() {
    // Configure register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configure register B: Gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Function to read raw magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to apply hard iron offsets
void apply_hard_iron_offsets(magnetometer_data_t raw_data, float *x_offset, float *y_offset, float *z_offset, magnetometer_data_t *offset_data) {
    float x = (float)raw_data.x;
    float y = (float)raw_data.y;
    float z = (float)raw_data.z;

    offset_data->x = (int16_t)(x - *x_offset);
    offset_data->y = (int16_t)(y - *y_offset);
    offset_data->z = (int16_t)(z - *z_offset);

    *x_offset = *x_offset + x;
    *y_offset = *y_offset + y;
    *z_offset = *z_offset + z;
}

// Function to update the running average
void update_running_average(float x, float y, float z, float *running_average_x, float *running_average_y, float *running_average_z, int *sample_index) {
    static int samples[NUM_SAMPLES];
    static int index = 0;

    if (*sample_index == index) {
        samples[*sample_index] = x;
        samples[*sample_index + 1] = y;
        samples[*sample_index + 2] = z;
        *sample_index = (*sample_index + 3) % (NUM_SAMPLES * 3);
        index = (*sample_index + 3) % (NUM_SAMPLES * 3);
    } else {
        samples[*sample_index] = x;
        samples[*sample_index + 1] = y;
        samples[*sample_index + 2] = z;
        *sample_index = (*sample_index + 3) % (NUM_SAMPLES * 3);
    }

    *running_average_x = 0.0;
    *running_average_y = 0.0;
    *running_average_z = 0.0;

    for (int i = 0; i < NUM_SAMPLES; i++) {
        *running_average_x += samples[i * 3];
        *running_average_y += samples[i * 3 + 1];
        *running_average_z += samples[i * 3 + 2];
    }

    *running_average_x /= NUM_SAMPLES;
    *running_average_y /= NUM_SAMPLES;
    *running_average_z /= NUM_SAMPLES;
}

// Function to print the data
void print_data(float x, float y, float z) {
    printf("X: %.2f, Y: %.2f, Z: %.2f\n", x, y, z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (initialize_magnetometer() < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize running averages
    float running_average_x = 0.0;
    float running_average_y = 0.0;
    float running_average_z = 0.0;
    int sample_index = 0;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t raw_data = read_magnetometer_data();

        // Apply hard iron offsets
        magnetometer_data_t offset_data;
        apply_hard_iron_offsets(raw_data, &running_average_x, &running_average_y, &running_average_z, &offset_data);

        // Update running average
        update_running_average((float)offset_data.x, (float)offset_data.y, (float)offset_data.z, &running_average_x, &running_average_y, &running_average_z, &sample_index);

        // Print data
        print_data((float)offset_data.x, (float)offset_data.y, (float)offset_data.z);

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

