#define INT1_PIN 16 // BCM GPIO 23

// Configuration
#define SAMPLE_RATE 10 // ms
#define BUFFER_SIZE 64
#define SAMPLE_DELAY (1000 / SAMPLE_RATE) // microseconds

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

// Circular buffer
accelerometer_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_lsm303d();
accelerometer_data_t read_accelerometer_data();
void dump_buffer();
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
int verify_device_id();

// Function to verify the LSM303D device ID
int verify_device_id() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i != 0x33) {
        fprintf(stderr, "Error: Incorrect device ID (0x%02X, expected 0x33)\n", who_am_i);
        return -1;
    }
    printf("LSM303D device ID: 0x%02X\n", who_am_i);
    return 0;
}

// Function to initialize the LSM303D accelerometer
int initialize_lsm303d() {
    // Enable accelerometer (100Hz, all axes)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error: Failed to write to CTRL_REG1_A\n");
        return -1;
    }

    // Set full-scale range to +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write to CTRL_REG4_A\n");
        return -1;
    }

    // Configure interrupt 1 (rising edge)
    if (i2cWriteByteData(i2c_handle, 0x30, 0x01) < 0) { // Enable INT1
        fprintf(stderr, "Error: Failed to write to INT1 register\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A, raw_data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    data.y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    data.z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    return data;
}

// Function to dump the circular buffer to the console
void dump_buffer() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s", timestamp);
    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        printf(" %d %d %d", buffer[index].x, buffer[index].y, buffer[index].z);
    }
    printf("\n");
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data; // Unused parameters
    dump_buffer();
}

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Unused parameter
    printf("Caught signal, exiting gracefully...\n");
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, LSM303D_ADDR, 0); // Bus 1, address 0x1D, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303D
    if (initialize_lsm303d() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetISRFuncEx(INT1_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Could not set up interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read accelerometer data
        accelerometer_data_t data = read_accelerometer_data();

        // Store data in circular buffer
        buffer[buffer_index] = data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Delay for the specified sample rate
        gpioDelay(SAMPLE_DELAY);
    }

    // Disable accelerometer (set to sleep mode)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to disable accelerometer\n");
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

