#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the solenoids
#define SOLENOID_1_GPIO 17
#define SOLENOID_2_GPIO 27

// Function prototypes
int initialize_gpio();
void activate_solenoid(int gpio_pin);
void deactivate_solenoid(int gpio_pin);
void switch_solenoids();
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track the current active solenoid
int current_active_solenoid = 0; // 0 for solenoid 1, 1 for solenoid 2

int main() {
    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Main loop to switch between solenoids
    while (1) {
        switch_solenoids();
    }

    return 0; // This line will not be reached due to the infinite loop
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_GPIO, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_GPIO, PI_OUTPUT);

    // Ensure both solenoids are initially deactivated
    deactivate_solenoid(SOLENOID_1_GPIO);
    deactivate_solenoid(SOLENOID_2_GPIO);

    return 0;
}

// Function to activate a solenoid by setting the corresponding GPIO pin HIGH
void activate_solenoid(int gpio_pin) {
    if (gpio_pin == SOLENOID_1_GPIO) {
        gpioWrite(SOLENOID_1_GPIO, 1); // Set GPIO HIGH
    } else if (gpio_pin == SOLENOID_2_GPIO) {
        gpioWrite(SOLENOID_2_GPIO, 1); // Set GPIO HIGH
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin specified.\n");
    }
}

// Function to deactivate a solenoid by setting the corresponding GPIO pin LOW
void deactivate_solenoid(int gpio_pin) {
    if (gpio_pin == SOLENOID_1_GPIO) {
        gpioWrite(SOLENOID_1_GPIO, 0); // Set GPIO LOW
    } else if (gpio_pin == SOLENOID_2_GPIO) {
        gpioWrite(SOLENOID_2_GPIO, 0); // Set GPIO LOW
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin specified.\n");
    }
}

// Function to switch between the two solenoids
void switch_solenoids() {
    int gpio_pin_to_activate;

    if (current_active_solenoid == 0) {
        gpio_pin_to_activate = SOLENOID_2_GPIO;
    } else {
        gpio_pin_to_activate = SOLENOID_1_GPIO;
    }

    activate_solenoid(gpio_pin_to_activate);
    deactivate_solenoid(SOLENOID_1_GPIO + (current_active_solenoid == 0));
    current_active_solenoid = 1 - current_active_solenoid;

    // Use nanosleep for a 500ms delay
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 500 milliseconds
    nanosleep(&sleep_time, NULL);
}

// Function to clean up GPIO pins and terminate the pigpio library
void cleanup_gpio() {
    // Deactivate both solenoids
    deactivate_solenoid(SOLENOID_1_GPIO);
    deactivate_solenoid(SOLENOID_2_GPIO);

    // Terminate the pigpio library
    gpioTerminate();
}

// Signal handler function to catch SIGINT and SIGTERM signals
void signal_handler(int signal) {
    printf("Caught signal %d. Cleaning up and exiting.\n", signal);
    cleanup_gpio();
    exit(0);
}

