#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY1_GPIO 17
#define RELAY2_GPIO 27
#define UART_PORT1 "/dev/serial0"
#define UART_PORT2 "/dev/serial1"
#define BAUD_RATE 9600
#define TIMEOUT_MS 5000
#define LOCK_DURATION_MS 2000

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int uart_handle1 = -1;
int uart_handle2 = -1;

// Function prototypes
int initialize_uart(const char *port, int baud_rate);
int read_uart(int uart_handle, char *buffer, int buffer_size, int timeout_ms);
int validate_code(const char *code);
int control_relay(int gpio_pin, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);

    // Deactivate relays
    control_relay(RELAY1_GPIO, 0);
    control_relay(RELAY2_GPIO, 0);

    // Close UART ports
    if (uart_handle1 != -1) {
        close(uart_handle1);
    }
    if (uart_handle2 != -1) {
        close(uart_handle2);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize the UART port
int initialize_uart(const char *port, int baud_rate) {
    int uart_handle = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART port %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(uart_handle, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(uart_handle);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_cc[VMIN] = 0;  // Non-blocking read
    tty.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(uart_handle, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(uart_handle);
        return -1;
    }

    return uart_handle;
}

// Function to read from the UART port
int read_uart(int uart_handle, char *buffer, int buffer_size, int timeout_ms) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(uart_handle, &readfds);

    timeout.tv_sec = timeout_ms / 1000;
    timeout.tv_usec = (timeout_ms % 1000) * 1000;

    int retval = select(uart_handle + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        fprintf(stderr, "Error from select: %s\n", strerror(errno));
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return -2;
    } else {
        // Data is available
        ssize_t bytes_read = read(uart_handle, buffer, buffer_size - 1);
        if (bytes_read < 0) {
            fprintf(stderr, "Error from read: %s\n", strerror(errno));
            return -1;
        } else {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            return bytes_read;
        }
    }
}

// Function to validate the code
int validate_code(const char *code) {
    if (strlen(code) != 6) {
        fprintf(stderr, "Invalid code length: %zu\n", strlen(code));
        return 0;
    }

    for (int i = 0; i < 6; i++) {
        if (code[i] < '0' || code[i] > '9') {
            fprintf(stderr, "Invalid character in code: %c\n", code[i]);
            return 0;
        }
    }

    return 1;
}

// Function to control the relay
int control_relay(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);

    // Initialize UART ports
    uart_handle1 = initialize_uart(UART_PORT1, BAUD_RATE);
    if (uart_handle1 == -1) {
        gpioTerminate();
