#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME 1 // seconds
#define FAILSAFE_TIMEOUT 10 // seconds

// Global variables
static volatile int running = 1;
static time_t motion_start_time = 0;
static int relay_state = 0; // 0 = off, 1 = on

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_relay(int state);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        running = 0;
        log_event("Received signal, shutting down...");
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Ensure relay is initially off
    control_relay(0);
    log_event("GPIO pins initialized");

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Control relay state
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        log_event("Failed to control relay");
        return 1;
    }
    relay_state = state;
    return 0;
}

// Log event to syslog
int log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
    return 0;
}

// Failsafe mechanism
int failsafe() {
    log_event("Failsafe triggered: Motion detected continuously for too long.");
    log_event("Relay de-energized.");
    control_relay(0);
    log_event("System shutting down...");
    return 1;
}

// Cleanup function
void cleanup() {
    log_event("Cleaning up...");
    control_relay(0); // Ensure relay is off
    gpioTerminate();
    log_event("GPIO terminated");
    closelog();
    exit(0);
}

int main() {
    // Open syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    log_event("Motion detection started");

    // Main loop
    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            if (motion_start_time == 0) {
                motion_start_time = time(NULL);
                log_event("Motion detected");
            } else {
                time_t current_time = time(NULL);
                double time_diff = difftime(current_time, motion_start_time);

                if (time_diff > FAILSAFE_TIMEOUT) {
                    failsafe();
                    return 0; // Exit after failsafe
                }

                if (relay_state == 0) {
                    control_relay(1);
                    log_event("Relay energized");
                }
                sleep(RELAY_ON_TIME);
                control_relay(0);
                log_event("Relay de-energized");
                motion_start_time = 0; // Reset timeout
            }
        } else {
            motion_start_time = 0; // Reset timeout if no motion
        }

        gpioDelay(50); // Poll every 50ms
    }

    cleanup();
    return 0;
}

