#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define the irrigation cycle duration (seconds)
#define IRRIGATION_DURATION 300

// Define the pause duration (seconds)
#define PAUSE_DURATION 60

// Define the total cycle duration (seconds)
#define CYCLE_DURATION (IRRIGATION_DURATION * 4 + PAUSE_DURATION * 3)

// Define the timer interval (seconds)
#define TIMER_INTERVAL 60

// Global variables
volatile sig_atomic_t program_running = 1;
int relay_states[4] = {1, 1, 1, 1}; // Initialize all relays to OFF (HIGH)

// Function prototypes
void signal_handler(int signal);
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void log_event(const char *message);
void timer_callback();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received signal, shutting down...");
    }
}

// Function to activate a relay
void activate_relay(int relay_number) {
    if (relay_number < 1 || relay_number > 4) {
        log_event("Error: Invalid relay number.");
        return;
    }

    if (relay_states[relay_number - 1] == 1) {
        log_event("Error: Relay already activated.");
        return;
    }

    gpioWrite(RELAY1_GPIO, 0); // Assuming active LOW
    gpioWrite(RELAY2_GPIO, 0);
    gpioWrite(RELAY3_GPIO, 0);
    gpioWrite(RELAY4_GPIO, 0);

    relay_states[relay_number - 1] = 0; // Update state
    char message[100];
    snprintf(message, sizeof(message), "Relay %d activated", relay_number);
    log_event(message);
}

// Function to deactivate a relay
void deactivate_relay(int relay_number) {
    if (relay_number < 1 || relay_number > 4) {
        log_event("Error: Invalid relay number.");
        return;
    }

    if (relay_states[relay_number - 1] == 0) {
        log_event("Error: Relay already deactivated.");
        return;
    }

    gpioWrite(RELAY1_GPIO, 1); // Assuming active LOW
    gpioWrite(RELAY2_GPIO, 1);
    gpioWrite(RELAY3_GPIO, 1);
    gpioWrite(RELAY4_GPIO, 1);

    relay_states[relay_number - 1] = 1; // Update state
    char message[100];
    snprintf(message, sizeof(message), "Relay %d deactivated", relay_number);
    log_event(message);
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Timer callback function
void timer_callback() {
    static int relay_number = 1;
    int current_relay = relay_number;

    if (current_relay > 4) {
        current_relay = 1;
    }

    activate_relay(current_relay);
    gpioDelay(IRRIGATION_DURATION * 1000000); // Delay for irrigation duration

    deactivate_relay(current_relay);
    gpioDelay(PAUSE_DURATION * 1000000); // Delay for pause duration

    relay_number++;
}

int main() {
    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("Error: pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    deactivate_relay(1);
    deactivate_relay(2);
    deactivate_relay(3);
    deactivate_relay(4);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the timer
    gpioSetTimerFuncEx(0, TIMER_INTERVAL * 1000000, timer_callback, NULL); // Timer 0, interval in microseconds

    log_event("Irrigation system started");

    // Main loop
    while (program_running) {
        gpioDelay(1000000); // Sleep for 1 second
    }

    // Clean up
    log_event("Shutting down...");
    deactivate_relay(1);
    deactivate_relay(2);
    deactivate_relay(3);
    deactivate_relay(4);
    gpioTerminate();
    closelog();

    return 0;
}

