#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_CONFIG 0x1C

// Driver library path
#define DRIVER_PATH "/sys/kernel/mpu6050_accel/latest"

// Circular buffer size
#define BUFFER_SIZE 10

// Global variables
int i2c_fd = -1;
int running = 1;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Circular buffer
accelerometer_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int init_driver();
int read_mpu6050(accelerometer_data_t *data);
int write_buffer_to_driver();
void timer_callback();
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Wake up the MPU6050
    if (i2c_smbus_write_byte_data(i2c_fd, PWR_MGMT_1, 0) < 0) {
        perror("Error writing to PWR_MGMT_1");
        close(i2c_fd);
        return -1;
    }

    // Configure accelerometer range to +/- 2g
    if (i2c_smbus_write_byte_data(i2c_fd, ACCEL_CONFIG, 0x00) < 0) {
        perror("Error writing to ACCEL_CONFIG");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to initialize the driver library
int init_driver() {
    if (access(DRIVER_PATH, F_OK) == 0) {
        return 0; // Driver exists
    } else {
        // Create the directory if it doesn't exist
        if (mkdir(DRIVER_PATH, 0777) == -1) {
            perror("Error creating directory");
            return -1;
        }
        return 0; // Driver created, but not yet initialized
    }
}

// Function to read accelerometer data from the MPU6050
int read_mpu6050(accelerometer_data_t *data) {
    char buf[6];
    if (read(i2c_fd, buf, 6) != 6) {
        perror("Error reading accelerometer data");
        return -1;
    }

    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to write the circular buffer to the driver
int write_buffer_to_driver() {
    accelerometer_data_t latest_data = buffer[buffer_index];
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    char buffer[18];
    int len = snprintf(buffer, sizeof(buffer), "%d,%d,%d,%d,%d,%d",
                       latest_data.x, latest_data.y, latest_data.z,
                       buffer[(buffer_index + 1) % BUFFER_SIZE].x,
                       buffer[(buffer_index + 2) % BUFFER_SIZE].y,
                       buffer[(buffer_index + 3) % BUFFER_SIZE].z);

    if (len < 0 || len >= sizeof(buffer)) {
        fprintf(stderr, "Error formatting data for driver\n");
        return -1;
    }

    int fd = open(DRIVER_PATH, O_WRONLY);
    if (fd < 0) {
        perror("Error opening driver file");
        return -1;
    }

    if (write(fd, buffer, len) != len) {
        perror("Error writing to driver file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Timer callback function
void timer_callback() {
    accelerometer_data_t data;
    if (read_mpu6050(&data) == 0) {
        buffer[buffer_index] = data;
        if (write_buffer_to_driver() != 0) {
            fprintf(stderr, "Error writing to driver\n");
        }
    } else {
        fprintf(stderr, "Error reading from MPU6050 in timer callback\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize driver
    if (init_driver() != 0) {
        fprintf(stderr, "Driver initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    if (gpioSetTimerFuncEx(0, 100, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer function\n");
        cleanup();
        return 1;
    }

    printf("MPU6050 data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1);
    }

    return 0;
}

