#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 18
#define RELAY2_GPIO 23
#define RELAY3_GPIO 24
#define RELAY4_GPIO 25

// Define the interval for each relay in seconds
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Ensure all relays are initially off
    gpioWrite(RELAY1_GPIO, 0);
    gpioWrite(RELAY2_GPIO, 0);
    gpioWrite(RELAY3_GPIO, 0);
    gpioWrite(RELAY4_GPIO, 0);

    return 0;
}

// Function to toggle a relay and return the new state
int toggle_relay(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    int new_state = !current_state;
    gpioWrite(gpio_pin, new_state);
    return new_state;
}

// Function to calculate the interval based on the relay number
int calculate_interval(int relay_number) {
    switch (relay_number) {
        case 1:
            return INTERVAL1;
        case 2:
            return INTERVAL2;
        case 3:
            return INTERVAL3;
        case 4:
            return INTERVAL4;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return -1; // Indicate an error
    }
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Calculate the interval for each relay
        int interval1 = calculate_interval(1);
        int interval2 = calculate_interval(2);
        int interval3 = calculate_interval(3);
        int interval4 = calculate_interval(4);

        // Check for errors in interval calculation
        if (interval1 == -1 || interval2 == -1 || interval3 == -1 || interval4 == -1) {
            fprintf(stderr, "Error calculating intervals. Exiting.\n");
            break;
        }

        // Calculate the time to sleep for each relay
        time_t start_time1 = time(NULL);
        time_t start_time2 = time(NULL);
        time_t start_time3 = time(NULL);
        time_t start_time4 = time(NULL);

        while (program_running) {
            // Relay 1
            time_t current_time1 = time(NULL);
            if (difftime(current_time1, start_time1) >= interval1) {
                toggle_relay(RELAY1_GPIO);
                start_time1 = current_time1;
            }

            // Relay 2
            time_t current_time2 = time(NULL);
            if (difftime(current_time2, start_time2) >= interval2) {
                toggle_relay(RELAY2_GPIO);
                start_time2 = current_time2;
            }

            // Relay 3
            time_t current_time3 = time(NULL);
            if (difftime(current_time3, start_time3) >= interval3) {
                toggle_relay(RELAY3_GPIO);
                start_time3 = current_time3;
            }

            // Relay 4
            time_t current_time4 = time(NULL);
            if (difftime(current_time4, start_time4) >= interval4) {
                toggle_relay(RELAY4_GPIO);
                start_time4 = current_time4;
            }

            // Small delay to prevent busy-waiting
            gpioDelay(1000); // 1 ms
        }

        // Cleanup GPIO resources before exiting
        gpioTerminate();
        return 0;
    }

    // Cleanup GPIO resources before exiting
    gpioTerminate();

    return 0;
}

