#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43

// Sensitivity scale factor for gyroscope (±250°/s)
#define GYRO_SCALE 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (degrees/second)
#define ANGULAR_VELOCITY_THRESHOLD 50.0

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Structure to hold the circular buffer
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_mpu6050();
gyro_data_t read_gyro_data();
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
double calculate_angular_velocity(gyro_data_t data);
void check_threshold(double angular_velocity);
void signal_handler(int signal);

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050. Error code: %d\n", errno);
        return -1;
    }

    // Configure gyroscope sensitivity (+/- 250°/s)
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope. Error code: %d\n", errno);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data. Error code: %d\n", errno);
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buf[0] << 8) | buf[1]);
    data.y = (int16_t)((buf[2] << 8) | buf[3]);
    data.z = (int16_t)((buf[4] << 8) | buf[5]);

    return data;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to calculate angular velocity
double calculate_angular_velocity(gyro_data_t data) {
    double x = (double)data.x / GYRO_SCALE;
    double y = (double)data.y / GYRO_SCALE;
    double z = (double)data.z / GYRO_SCALE;
    return sqrt(x * x + y * y + z * z);
}

// Function to check if the angular velocity exceeds the threshold
void check_threshold(double angular_velocity) {
    if (angular_velocity > ANGULAR_VELOCITY_THRESHOLD) {
        printf("Angular velocity exceeded threshold: %.2f degrees/second\n", angular_velocity);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device. Error code: %d\n", errno);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("MPU-6050 gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gyro_data_t data = read_gyro_data();
        add_to_buffer(&gyro_buffer, data);
        double angular_velocity = calculate_angular_velocity(data);
        check_threshold(angular_velocity);

        gpioDelay(10); // Delay for 10ms (adjust as needed)
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

