#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <sys/select.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define TIMEOUT_MS 1000
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define JSON_BUFFER_SIZE 256

// Structure to hold sensor data
typedef struct {
    unsigned int timestamp;
    float ppm;
    int error_flag;
} sensor_data_t;

// Global variables
int uart_fd = -1;
FILE *log_fp = NULL;
FILE *error_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_uart();
int read_sensor_data(unsigned char *data, int max_len);
int validate_checksum(const unsigned char *data, int len);
int parse_co2_ppm(const unsigned char *data);
int log_data(sensor_data_t data);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize UART
int init_uart() {
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(uart_fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;    // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN] = 0;              // read doesn't block
    tty.c_cc[VTIME] = 5;             // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(uart_fd);
        return -1;
    }

    return 0;
}

// Read sensor data with timeout
int read_sensor_data(unsigned char *data, int max_len) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(uart_fd, &readfds);

    timeout.tv_sec = 0;
    timeout.tv_usec = TIMEOUT_MS * 1000; // Convert milliseconds to microseconds

    int retval = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("select() error");
        return -1;
    } else if (retval) {
        // Data is available, read from UART
        int bytes_read = read(uart_fd, data, max_len);
        if (bytes_read == -1) {
            perror("Error reading from UART");
            return -1;
        }
        return bytes_read;
    } else {
        // Timeout occurred
        return 0;
    }
}

// Validate checksum
int validate_checksum(const unsigned char *data, int len) {
    if (len != 9) {
        return 0; // Not enough data for checksum
    }

    unsigned short checksum = (data[2] << 8) | data[3];
    unsigned short calculated_checksum = 0;
    for (int i = 0; i < 8; i++) {
        calculated_checksum += data[i];
    }

    return (checksum == calculated_checksum);
}

// Parse CO2 ppm value
int parse_co2_ppm(const unsigned char *data) {
    if (!validate_checksum(data, 9)) {
        return -1; // Checksum error
    }

    return (data[4] << 8) | data[5];
}

// Log data to file
int log_data(sensor_data_t data) {
    char json_string[JSON_BUFFER_SIZE];
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    data.timestamp = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    snprintf(json_string, JSON_BUFFER_SIZE, "{\"timestamp\":%u,\"ppm\":%.2f,\"error_flag\":%d}",
             data.timestamp, data.ppm, data.error_flag);

    if (fprintf(log_fp, "%s\n", json_string) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_fp); // Ensure data is written immediately
    return 0;
}

// Log error to file
int log_error(const char *message) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(error_fp, "%ld.%09ld: %s\n", ts.tv_sec, ts.tv_nsec, message);
    fflush(error_fp);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    if (error_fp != NULL) {
        fclose(error_fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (init_uart() != 0) {
        log_error("UART initialization failed");
        cleanup();
        return 1;
    }

    // Open log files
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    error_fp = fopen(ERROR_LOG_FILE, "a");
    if (error_fp == NULL) {
        perror("Error opening error log file");
        cleanup();
        return 1;
    }

    unsigned char sensor_data[9];
    int retry_count = 0;
    int read_result;

    while (!terminate) {
        retry_count = 0;
        do {
            read_result = read_sensor_data(sensor_data, sizeof(sensor_data));
            if (read_result > 0) {
                break; // Success, exit retry loop
            } else {
                retry_count++;
                log_error("Sensor read failed, retrying...");
                gpioDelay(100); // Wait before retrying
            }
        } while (retry_count < 3 && !terminate);

        if (read_result > 0) {
            int ppm = parse_co2_ppm(sensor_data);
            if (ppm != -1) {
                sensor_data_t data;
                data.ppm = (float)ppm;
                data.error_flag = 0;
                data.timestamp = 0; // Not used in log_data, but required by struct
                if (log_data(data) != 0) {
                    log_error("Failed to log data");
                }
                printf("{\"timestamp\":%u,\"ppm\":%.2f,\"error_flag\":0}\n", data.timestamp, data.ppm);
            } else {
                log_error("Checksum error or invalid data");
                sensor_data_t data;
                data.error_flag = 1;
                data.timestamp = 0; // Not used in log_data, but required by struct
                if (log_data(data) != 0) {
                    log_error("Failed to log data");
                }
                printf("{\"timestamp\":%u,\"ppm\":%.2f,\"error_flag\":1}\n", data.timestamp, data.ppm);
            }
        } else {
            log_error("Failed to read sensor data after multiple retries");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    cleanup();
    return 0;
}

