#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for output
#define GPIO_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
} magnetometer_data_t;

// Structure to hold heading data
typedef struct {
    float heading;
    magnetometer_data_t raw_data;
} heading_data_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Hard iron offsets
const int16_t hard_iron_x = 100;
const int16_t hard_iron_y = -50;

// Circular buffer
heading_data_t heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_magnetometer_data(magnetometer_data_t *data);
float calculate_heading(magnetometer_data_t raw_data);
void apply_hard_iron_compensation(float *heading, magnetometer_data_t *raw_data);
void store_heading(float heading);
float get_latest_heading();
void control_gpio(float current_heading);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure the magnetometer (example configuration)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) { // 8-average, 15 Hz, normal measurement
        fprintf(stderr, "Error writing to config A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0xA0) < 0) { // Gain = 5
        fprintf(stderr, "Error writing to config B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) { // Continuous measurement mode
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer_data(magnetometer_data_t *data) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate heading in degrees
float calculate_heading(magnetometer_data_t raw_data) {
    float heading_rad = atan2((float)raw_data.y, (float)raw_data.x);
    float heading_deg = heading_rad * 180.0 / M_PI;

    if (heading_deg < 0) {
        heading_deg += 360.0;
    }

    return heading_deg;
}

// Function to apply hard iron compensation
void apply_hard_iron_compensation(float *heading, magnetometer_data_t *raw_data) {
    float x_comp = (float)raw_data->x - hard_iron_x;
    float y_comp = (float)raw_data->y - hard_iron_y;

    *heading = calculate_heading({x_comp, y_comp});
}

// Function to store heading in the circular buffer
void store_heading(float heading) {
    heading_buffer[buffer_index].heading = heading;
    heading_buffer[buffer_index].raw_data = {hard_iron_x, hard_iron_y}; // Store hard iron values
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to get the latest heading from the buffer
float get_latest_heading() {
    return heading_buffer[buffer_index].heading;
}

// Function to control GPIO based on heading deviation
void control_gpio(float current_heading) {
    if (fabs(current_heading - 90.0) > 10.0) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO high
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO low
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    magnetometer_data_t raw_data;
    float current_heading;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&raw_data) == 0) {
            // Calculate heading
            current_heading = calculate_heading(raw_data);

            // Apply hard iron compensation
            apply_hard_iron_compensation(&current_heading, &raw_data);

            // Store heading in the buffer
            store_heading(current_heading);

            // Control GPIO
            control_gpio(current_heading);

            // Print current heading (for debugging)
            printf("Current Heading: %.2f degrees\n", current_heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Set GPIO low before exiting
    gpioTerminate();

    return 0;
}

