#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define I2C_BUS 1
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define LUX_THRESHOLD_RED 50
#define LUX_THRESHOLD_GREEN 150
#define LUX_THRESHOLD_BLUE 300
#define LOG_FILE "lighting_log.txt"
#define SLEEP_MS 1000 // 1 second

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int read_bh1750(int i2c_handle, float *lux);
int control_relays(float lux);
int log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioSetMode(RED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RED_GPIO);
        return -1;
    }
    if (gpioSetMode(GREEN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GREEN_GPIO);
        return -1;
    }
    if (gpioSetMode(BLUE_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", BLUE_GPIO);
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(int i2c_handle, float *lux) {
    char config_cmd = 0x10; // Continuous high-resolution mode
    char buffer[2];
    int result;

    result = i2cWriteByteData(i2c_handle, 0x00, config_cmd);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(200); // Wait for measurement (at least 180ms)

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Control RGB relays based on lux value
int control_relays(float lux) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux < LUX_THRESHOLD_RED) {
        red_state = 1;
    } else if (lux < LUX_THRESHOLD_GREEN) {
        green_state = 1;
    } else if (lux < LUX_THRESHOLD_BLUE) {
        blue_state = 1;
    }

    if (lux > LUX_THRESHOLD_BLUE) {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    gpioWrite(RED_GPIO, red_state);
    gpioWrite(GREEN_GPIO, green_state);
    gpioWrite(BLUE_GPIO, blue_state);

    return 0;
}

// Log data to file
int log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %d, %d, %d\n", timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    float lux;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Lighting control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        result = read_bh1750(i2c_handle, &lux);
        if (result == 0) {
            printf("Lux: %.2f\n", lux);
            control_relays(lux);
            log_data(lux, gpioRead(RED_GPIO), gpioRead(GREEN_GPIO), gpioRead(BLUE_GPIO));
        } else {
            fprintf(stderr, "Error reading lux value\n");
        }

        gpioDelay(SLEEP_MS); // Sleep for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

