#include <unistd.h>
#include <pigpio.h>

// Motor A
#define IN1 17
#define IN2 18

// Motor B
#define IN3 22
#define IN4 23

// PWM frequency
#define PWM_FREQUENCY 1000

// Distance thresholds (cm)
#define FORWARD_THRESHOLD 50
#define BACKWARD_THRESHOLD 50

// Global variables for distance readings
int distanceA = 0;
int distanceB = 0;

// Function prototypes
void motorA_forward(int dutyCycle);
void motorA_backward(int dutyCycle);
void motorA_stop();
void motorB_forward(int dutyCycle);
void motorB_backward(int dutyCycle);
void motorB_stop();
void set_motor_direction(int motor, int direction);
void set_pwm_duty_cycle(int motor, int dutyCycle);
void stop_motors();
void signal_handler(int signal);

// Function to set motor direction
void set_motor_direction(int motor, int direction) {
    if (motor == 1) { // Motor A
        if (direction == 1) { // Forward
            gpioWrite(IN1, 1);
            gpioWrite(IN2, 0);
        } else { // Backward
            gpioWrite(IN1, 0);
            gpioWrite(IN2, 1);
        }
    } else { // Motor B
        if (direction == 1) { // Forward
            gpioWrite(IN3, 1);
            gpioWrite(IN4, 0);
        } else { // Backward
            gpioWrite(IN3, 0);
            gpioWrite(IN4, 1);
        }
    }
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int motor, int dutyCycle) {
    if (motor == 1) { // Motor A
        gpioPWM(IN2, dutyCycle);
    } else { // Motor B
        gpioPWM(IN4, dutyCycle);
    }
}

// Function to stop motors
void stop_motors() {
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

// Function to drive Motor A forward
void motorA_forward(int dutyCycle) {
    set_motor_direction(1, 1);
    set_pwm_duty_cycle(1, dutyCycle);
}

// Function to drive Motor A backward
void motorA_backward(int dutyCycle) {
    set_motor_direction(1, 0);
    set_pwm_duty_cycle(1, dutyCycle);
}

// Function to stop Motor A
void motorA_stop() {
    stop_motors();
}

// Function to drive Motor B forward
void motorB_forward(int dutyCycle) {
    set_motor_direction(2, 1);
    set_pwm_duty_cycle(2, dutyCycle);
}

// Function to drive Motor B backward
void motorB_backward(int dutyCycle) {
    set_motor_direction(2, 0);
    set_pwm_duty_cycle(2, dutyCycle);
}

// Function to stop Motor B
void motorB_stop() {
    stop_motors();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_motors();
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    // Check for correct number of arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distanceA> <distanceB>\n", argv[0]);
        return 1;
    }

    // Parse distance arguments
    distanceA = atoi(argv[1]);
    distanceB = atoi(argv[2]);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(IN4, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(IN2, 255);
    gpioSetPWMrange(IN4, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (1) {
        // Proportional control logic
        int dutyCycleA = 0;
        int dutyCycleB = 0;

        if (distanceA < FORWARD_THRESHOLD) {
            // Forward
            dutyCycleA = (int)(((float)(distanceA - 10) / (50 - 10)) * 255);
            if (dutyCycleA > 255) dutyCycleA = 255;
            if (dutyCycleA < 0) dutyCycleA = 0;
        } else {
            // Stop
            dutyCycleA = 0;
        }

        if (distanceB < FORWARD_THRESHOLD) {
            // Forward
            dutyCycleB = (int)(((float)(distanceB - 10) / (50 - 10)) * 255);
            if (dutyCycleB > 255) dutyCycleB = 255;
            if (dutyCycleB < 0) dutyCycleB = 0;
        } else {
            // Stop
            dutyCycleB = 0;
        }

        // Drive motors
        motorA_forward(dutyCycleA);
        motorB_forward(dutyCycleB);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup (should not reach here in normal operation due to the while loop)
    stop_motors();
    gpioTerminate();
    return 0;
}

