// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Structure to represent a schedule entry
typedef struct {
    int relay_number;
    int on;
    time_t start_time;
    time_t end_time;
} schedule_entry_t;

// Global variables
FILE *schedule_file = NULL;
schedule_entry_t *schedule = NULL;
int num_entries = 0;
int running = 1;

// Function prototypes
int read_schedule(const char *filename, schedule_entry_t **schedule, int *num_entries);
void fade_lamp(int relay_number, int on);
void signal_handler(int signal);
void cleanup();

// Function to read the schedule from the file
int read_schedule(const char *filename, schedule_entry_t **schedule, int *num_entries) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    *num_entries = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Parse the line
        char *token = strtok(line, ",");
        int relay_number = atoi(token);

        token = strtok(NULL, ",");
        int on = atoi(token);

        token = strtok(NULL, ";");
        if (token == NULL) {
            fprintf(stderr, "Error: Invalid schedule format. Missing start time.\n");
            fclose(fp);
            return -1;
        }

        time_t start_time = time(NULL);
        token = strtok(NULL, ";");
        if (token == NULL) {
            fprintf(stderr, "Error: Invalid schedule format. Missing end time.\n");
            fclose(fp);
            return -1;
        }
        time_t end_time = time(NULL);

        // Allocate memory for the schedule entry
        schedule_entry_t *entry = (schedule_entry_t *)malloc(sizeof(schedule_entry_t));
        if (entry == NULL) {
            perror("Error allocating memory for schedule entry");
            fclose(fp);
            return -1;
        }

        entry->relay_number = relay_number;
        entry->on = on;
        entry->start_time = start_time;
        entry->end_time = end_time;

        // Store the schedule entry
        if (*schedule == NULL) {
            *schedule = (schedule_entry_t *)malloc(sizeof(schedule_entry_t));
            if (*schedule == NULL) {
                perror("Error allocating memory for schedule");
                free(entry);
                fclose(fp);
                return -1;
            }
            *schedule = entry;
        } else {
            *schedule = (schedule_entry_t *)realloc(*schedule, (*num_entries + 1) * sizeof(schedule_entry_t));
            if (*schedule == NULL) {
                perror("Error reallocating memory for schedule");
                free(entry);
                fclose(fp);
                return -1;
            }
            (*schedule + *num_entries)->relay_number = relay_number;
            (*schedule + *num_entries)->on = on;
            (*schedule + *num_entries)->start_time = start_time;
            (*schedule + *num_entries)->end_time = end_time;
        }

        (*num_entries)++;
    }

    fclose(fp);
    return 0;
}

