#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define TIMEOUT_US 50000 // 50ms timeout
#define MIN_ECHO_TIME 10 // Minimum echo time in microseconds

// Global variables
static volatile int running = 1;
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;

// Function prototypes
void trigger_sensor();
long measure_pulse_width();
double calculate_distance(long pulse_width);
int map_distance_to_frequency(double distance);
void set_buzzer_frequency(int frequency);
void signal_handler(int signal);
void log_error(const char *message);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long measure_pulse_width() {
    echo_start_tick = 0;
    echo_end_tick = 0;
    echo_received = 0;

    // Wait for echo to start
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        log_error("Timeout waiting for echo start");
        return -1; // Timeout
    }

    echo_start_tick = gpioTick();

    // Wait for echo to end
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        log_error("Timeout waiting for echo end");
        return -1; // Timeout
    }

    echo_end_tick = gpioTick();

    echo_received = 1;
    return echo_end_tick - echo_start_tick;
}

// Function to calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map the distance to a PWM frequency
int map_distance_to_frequency(double distance) {
    if (distance < 0) return -1; // Indicate error
    if (distance < 10) return MIN_FREQUENCY; // Minimum frequency
    if (distance > 100) return MAX_FREQUENCY; // Maximum frequency
    return (int)(MIN_FREQUENCY + (distance - 10) * (MAX_FREQUENCY - MIN_FREQUENCY) / 90.0);
}

// Function to set the PWM frequency
void set_buzzer_frequency(int frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        log_error("Frequency out of range");
        gpioPWM(PWM_PIN, 0); // Silence the buzzer
        return;
    }
    gpioSetPWMfrequency(PWM_PIN, frequency);
    gpioPWM(PWM_PIN, 128); // 50% duty cycle
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    log_error("Received signal, shutting down...");
    gpioPWM(PWM_PIN, 0); // Silence the buzzer
    gpioTerminate();
    exit(0);
}

// Function to log errors to stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency to 0 initially
    gpioSetPWMfrequency(PWM_PIN, 0);
    gpioPWM(PWM_PIN, 0);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            double distance = calculate_distance(pulse_width);
            if (distance > 0) {
                int frequency = map_distance_to_frequency(distance);
                if (frequency > 0) {
                    set_buzzer_frequency(frequency);
                }
            } else {
                log_error("Invalid distance measurement");
            }
        } else {
            log_error("Failed to measure distance");
        }

        gpioDelay(50); // 50ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();

    return 0;
}

