// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to set the RGB LED color using PWM
void set_led_color(float red, float green, float blue) {
    // Common anode, so invert the PWM duty cycle
    int red_duty = (int)(255.0 * (1.0 - red));
    int green_duty = (int)(255.0 * (1.0 - green));
    int blue_duty = (int)(255.0 * (1.0 - blue));

    gpioPWM(RED_PIN, red_duty);
    gpioPWM(GREEN_PIN, green_duty);
    gpioPWM(BLUE_PIN, blue_duty);
}

// Function to generate a smooth color transition based on a sine wave
void generate_color_transition(float *red, float *green, float *blue, float time) {
    *red   = 0.5 + 0.5 * sin(2 * M_PI * time);
    *green = 0.5 + 0.5 * sin(2 * M_PI * time + 2 * M_PI / 3);
    *blue = 0.5 + 0.5 * sin(2 * M_PI * time + 4 * M_PI / 3);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM range (0-255)
    if (gpioSetPWMrange(RED_PIN, 255) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, 255) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN, 255) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register signal handler\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    float time = 0.0;
    while (program_running) {
        float red, green, blue;
        generate_color_transition(&red, &green, &blue, time);
        set_led_color(red, green, blue);
        time += 0.01; // Increment time by 0.01 seconds
        gpioDelay(1000); // Delay for 1 millisecond (1000 microseconds)
    }

    // Turn off the LED before exiting
    set_led_color(0.0, 0.0, 0.0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

