#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor (for +/- 250 deg/s range)
#define GYRO_SCALE 131.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the MPU-6050
int init_mpu6050(int i2c_fd) {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2c_smbus_write_byte_data(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int i2c_fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    // Read raw gyroscope data
    raw_x = i2c_smbus_read_word_data(i2c_fd, GYRO_XOUT_H);
    if (raw_x < 0) {
        fprintf(stderr, "Error: Could not read gyro X data\n");
        return -1;
    }

    raw_y = i2c_smbus_read_word_data(i2c_fd, GYRO_YOUT_H);
    if (raw_y < 0) {
        fprintf(stderr, "Error: Could not read gyro Y data\n");
        return -1;
    }

    raw_z = i2c_smbus_read_word_data(i2c_fd, GYRO_ZOUT_H);
    if (raw_z < 0) {
        fprintf(stderr, "Error: Could not read gyro Z data\n");
        return -1;
    }

    // Convert raw data to degrees per second
    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

// Function to log data to file
int log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    // Write data to file
    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error: Could not write to log file\n");
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    float x, y, z;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            // Log data to file
            if (log_data(log_file, x, y, z) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

