#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_GPIO 17
#define BUZZER_GPIO 18

// Define melody notes (frequency, duration in ms)
const int melody[] = {
    {440, 200},   // A4, 200ms
    {494, 200},   // B4, 200ms
    {523, 200},   // C5, 200ms
    {587, 200},   // D5, 200ms
    {659, 200},   // E5, 200ms
    {698, 200},   // F5, 200ms
    {784, 200},   // G5, 200ms
    {880, 200}    // A5, 200ms
};

const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int play_flag = 0;
volatile int stop_flag = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Button ISR
void button_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    // Debounce the button
    if (current_tick - last_tick < 50000) { // 50ms debounce
        return;
    }
    last_tick = current_tick;

    // Check if the button is pressed (active-low)
    if (level == 0) {
        play_flag = 1;
    }
}

// Play melody function
void play_melody() {
    int i;
    for (i = 0; i < melody_length; i++) {
        gpioPWM(BUZZER_GPIO, 128); // 50% duty cycle
        gpioSetPWMfrequency(BUZZER_GPIO, melody[i].first);
        gpioDelay(melody[i].second * 1000); // Convert ms to us
    }
    stop_melody();
}

// Stop melody function
void stop_melody() {
    gpioPWM(BUZZER_GPIO, 0); // Stop PWM
    play_flag = 0;
    stop_flag = 1;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioPWM(BUZZER_GPIO, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP); // Internal pull-up
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Set PWM frequency (optional, can be adjusted)
    gpioSetPWMfrequency(BUZZER_GPIO, 440); // Set initial frequency

    // Set ISR for button press
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 50, button_isr, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (play_flag && !stop_flag) {
            play_melody();
        }
        gpioDelay(10000); // Check every 10ms
    }

    return 0;
}

