#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEFAULT_POLL_TIMEOUT 1000
#define WINDOW_SIZE 5
#define THRESHOLD 3

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int poll_timeout = DEFAULT_POLL_TIMEOUT;
    if (argc > 1) {
        poll_timeout = atoi(argv[1]);
        if (poll_timeout <= 0) {
            fprintf(stderr, "Error: Invalid poll timeout. Using default value of 1000 ms.\n");
            poll_timeout = DEFAULT_POLL_TIMEOUT;
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open log file
    FILE *log_file = fopen("vibration_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    int event_history[WINDOW_SIZE];
    int history_index = 0;
    int event_count = 0;

    while (program_running) {
        // Read GPIO value
        int value = gpioRead(GPIO_PIN);

        // Log event
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

        if (value == 1) {
            fprintf(log_file, "%s: Vibration detected (HIGH)\n", buf);
            fflush(log_file);
            event_count++;
        } else {
            fprintf(log_file, "%s: Vibration detected (LOW)\n", buf);
            fflush(log_file);
        }

        // Update event history
        event_history[history_index] = value;
        history_index = (history_index + 1) % WINDOW_SIZE;

        // Check for earthquake alert condition
        if (event_count >= THRESHOLD) {
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

            printf("EARTHQUAKE ALERT: %s\n", buf);
        }

        // Poll timeout
        if (poll_timeout > 0) {
            gpioDelay(poll_timeout * 1000); // pigpioDelay takes microseconds
            poll_timeout = 0; // Reset timeout after one poll
        }

        // Check for program termination signal
        if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
            fprintf(stderr, "Error: Could not install signal handler\n");
            program_running = 0;
        }
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

