        return 1;
    }

    int event_history[WINDOW_SIZE];
    int history_index = 0;
    int event_count = 0;

    while (program_running) {
        // Read GPIO value
        int value = gpioRead(GPIO_PIN);

        // Log event
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

        if (value == 1) {
            fprintf(log_file, "%s: Vibration detected (HIGH)\n", buf);
            fflush(log_file);
            event_count++;
        } else {
            fprintf(log_file, "%s: Vibration detected (LOW)\n", buf);
            fflush(log_file);
        }

        // Update event history
        event_history[history_index] = value;
        history_index = (history_index + 1) % WINDOW_SIZE;

        // Check for earthquake alert condition
        if (event_count >= THRESHOLD) {
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

            printf("EARTHQUAKE ALERT: %s\n", buf);
        }

        // Poll timeout
        if (poll_timeout > 0) {
            gpioDelay(poll_timeout * 1000); // pigpioDelay takes microseconds
            poll_timeout = 0; // Reset timeout after one poll
        }

        // Check for program termination signal
        if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
            fprintf(stderr, "Error: Could not install signal handler\n");
            program_running = 0;
        }
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

