#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define CRA_REG_M 0x00
#define CRB_REG_M 0x01
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Hard iron calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Compass directions
typedef enum {
    N, NE, E, SE, S, SW, W, NW
} compass_direction;

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_magnetometer();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
void apply_hard_iron_calibration(int16_t x, int16_t y, int16_t z, int16_t *calibrated_x, int16_t *calibrated_y, int16_t *calibrated_z);
float calculate_heading(int16_t x, int16_t y);
compass_direction map_heading_to_direction(float heading);
void log_data(int16_t x, int16_t y, int16_t z, float heading, compass_direction direction);
void print_heading_and_direction(float heading, compass_direction direction);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Configure magnetometer
int configure_magnetometer() {
    // Set CRA_REG_M (0x00) to 0x18 for 75 Hz output rate
    uint8_t config[2];
    config[0] = CRA_REG_M;
    config[1] = 0x18;
    if (write(i2c_fd, config, 2) != 2) {
        perror("Error writing to CRA_REG_M");
        return -1;
    }

    // Set CRB_REG_M (0x01) to 0x20 for +/- 1.3 Gauss full scale
    config[0] = CRB_REG_M;
    config[1] = 0x20;
    if (write(i2c_fd, config, 2) != 2) {
        perror("Error writing to CRB_REG_M");
        return -1;
    }

    // Set MR_REG_M (0x02) to 0x00 for continuous conversion mode
    config[0] = MR_REG_M;
    config[1] = 0x00;
    if (write(i2c_fd, config, 2) != 2) {
        perror("Error writing to MR_REG_M");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    // Read all 6 bytes at once
    if (read(i2c_fd, data, 6) != 6) {
        perror("Error reading magnetometer data");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Apply hard iron calibration
void apply_hard_iron_calibration(int16_t x, int16_t y, int16_t z, int16_t *calibrated_x, int16_t *calibrated_y, int16_t *calibrated_z) {
    *calibrated_x = x - X_OFFSET;
    *calibrated_y = y - Y_OFFSET;
    *calibrated_z = z - Z_OFFSET;
}

// Calculate heading in degrees
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Map heading to compass direction
compass_direction map_heading_to_direction(float heading) {
    if (heading >= 337.5 && heading < 45) return N;
    if (heading >= 45 && heading < 90) return NE;
    if (heading >= 90 && heading < 135) return E;
    if (heading >= 135 && heading < 180) return SE;
    if (heading >= 180 && heading < 225) return S;
    if (heading >= 225 && heading < 270) return SW;
    if (heading >= 270 && heading < 315) return W;
    if (heading >= 315 && heading < 360) return NW;
    return N; // Should not happen, but return N as a default
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z, float heading, compass_direction direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.2f,%d\n", timestamp, x, y, z, heading, direction);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Print heading and direction to console
void print_heading_and_direction(float heading, compass_direction direction) {
    printf("Heading: %.2f degrees, Direction: ", heading);
    switch (direction) {
        case N: printf("N"); break;
        case NE: printf("NE"); break;
        case E: printf("E"); break;
        case SE: printf("SE"); break;
        case S: printf("S"); break;
        case SW: printf("SW"); break;
        case W: printf("W"); break;
        case NW: printf("NW"); break;
        default: printf("Unknown"); break;
    }
    printf("\n");
}

int main() {
    int16_t x, y, z, calibrated_x, calibrated_y, calibrated_z;
    float heading;
    compass_direction direction;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure magnetometer
    if (configure_magnetometer() < 0) {
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Apply hard iron calibration
            apply_hard_iron_calibration(x, y, z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Map heading to direction
            direction = map_heading_to_direction(heading);

            // Log data
            log_data(calibrated_x, calibrated_y, calibrated_z, heading, direction);

            // Print heading and direction
            print_heading_and_direction(heading, direction);
        } else {
            fprintf(stderr, "Error reading magnetometer data, skipping.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

