#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE "relay_log.json"

static volatile int running = 1;
static volatile unsigned long last_touch_time = 0;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log relay state to file
int log_relay_state(const char *timestamp, const char *relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", timestamp, relay_state);
    fclose(fp);
    return 0;
}

// Interrupt handler for touch sensor
void touch_callback(int gpio, int level, unsigned int tick) {
    unsigned long current_time = gpioTick();
    if (current_time - last_touch_time > DEBOUNCE_DELAY_MS * 1000) {
        last_touch_time = current_time;

        // Toggle relay state
        int relay_state = gpioRead(RELAY_PIN) == 0 ? 1 : 0; // Assuming relay is active low
        gpioWrite(RELAY_PIN, relay_state);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp != NULL) {
            // Log relay state
            if (log_relay_state(timestamp, relay_state == 1 ? "ON" : "OFF") != 0) {
                fprintf(stderr, "Error logging relay state.\n");
            }
            free(timestamp);
        } else {
            fprintf(stderr, "Failed to get timestamp for logging.\n");
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    // Ensure relay is OFF
    gpioWrite(RELAY_PIN, 0);

    // Log final state
    char *timestamp = get_iso8601_timestamp();
    if (timestamp != NULL) {
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp != NULL) {
            fprintf(fp, "{\"timestamp\": \"%s\", \"relay_state\": \"OFF\"}\n", timestamp);
            fclose(fp);
        } else {
            perror("Error opening log file for final state");
        }
        free(timestamp);
    }

    // Clean up pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on touch pin
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Register interrupt handler
    if (gpioSetISRFuncEx(TOUCH_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Keep the program running until a signal is received
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    return 0;
}

