#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for servos
#define VALVE_GPIO 17
#define NOZZLE_GPIO 18

// Define moisture levels
#define MOISTURE_THRESHOLD 50

// Define watering cycle duration
#define WATERING_DURATION 5

// Define servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define servo sweep duration (seconds)
#define SERVO_SWEEP_DURATION 2

// Define backoff delay (milliseconds)
#define BACKOFF_DELAY 100

// Define servo open delay (seconds)
#define SERVO_OPEN_DELAY 5

// Define servo close delay (seconds)
#define SERVO_CLOSE_DELAY 5

// Define moisture cycle duration (seconds)
#define MOISTURE_CYCLE_DURATION 1

// Define moisture sequence
const int moisture_sequence[] = {20, 40, 60, 80, 100};
const int sequence_length = sizeof(moisture_sequence) / sizeof(moisture_sequence[0]);

// Global variables
volatile sig_atomic_t program_running = 1;
int valve_pulse_width = 0;
int nozzle_pulse_width = 0;

// Function prototypes
int set_servo_pulse_width(int gpio, int pulse_width);
int open_valve(int gpio);
int close_valve(int gpio);
int sweep_nozzle(int gpio, int start_pulse_width, int end_pulse_width, int duration);
int set_nozzle_angle(int gpio, int angle);
int check_moisture(int moisture_level);
void signal_handler(int signal);
void log_error(const char *message);

// Function to set servo pulse width
int set_servo_pulse_width(int gpio, int pulse_width) {
    if (gpioServo(gpio, pulse_width) != 0) {
        log_error("Failed to set servo pulse width.");
        return -1;
    }
    return 0;
}

// Function to open the valve
int open_valve(int gpio) {
    if (set_servo_pulse_width(gpio, SERVO_MAX_PULSE_WIDTH) != 0) {
        log_error("Failed to open valve.");
        return -1;
    }
    return 0;
}

// Function to close the valve
int close_valve(int gpio) {
    if (set_servo_pulse_width(gpio, SERVO_MIN_PULSE_WIDTH) != 0) {
        log_error("Failed to close valve.");
        return -1;
    }
    return 0;
}

// Function to sweep the nozzle through a sequence of angles
int sweep_nozzle(int gpio, int start_pulse_width, int end_pulse_width, int duration) {
    int current_pulse_width = start_pulse_width;
    int direction = 1; // 1 for increasing, -1 for decreasing

    for (int i = 0; i < duration * 100; i++) {
        if (set_servo_pulse_width(gpio, current_pulse_width) != 0) {
            log_error("Failed to set nozzle pulse width during sweep.");
            return -1;
        }
        gpioDelay(1000); // Delay for 1ms
        current_pulse_width += direction * 500; // Increment/decrement by 500us
        if (current_pulse_width > end_pulse_width) {
            current_pulse_width = end_pulse_width;
            direction = -1;
        } else if (current_pulse_width < start_pulse_width) {
            current_pulse_width = start_pulse_width;
            direction = 1;
        }
    }
    return 0;
}

// Function to set the nozzle angle
int set_nozzle_angle(int gpio, int angle) {
    // Map angle (0-180) to pulse width (500-2500)
    int pulse_width = (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);
    return set_servo_pulse_width(gpio, pulse_width);
}

// Function to check moisture level and trigger watering cycle
int check_moisture(int moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        return 1; // Watering needed
    } else {
        return 0; // No watering needed
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping program...\n", signal);
    // Stop both servos
    set_servo_pulse_width(VALVE_GPIO, 0);
    set_servo_pulse_width(NOZZLE_GPIO, 0);
    gpioServo(VALVE_GPIO, 0);
    gpioServo(NOZZLE_GPIO, 0);
    gpioTerminate();
    exit(0);
}

// Function to log errors with timestamps
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetMode(NOZZLE_GPIO, PI_OUTPUT);

    // Set initial servo pulse widths
    set_servo_pulse_width(VALVE_GPIO, 0);
    set_servo_pulse_width(NOZZLE_GPIO, 0);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Cycle through moisture levels
        for (int i = 0; i < sequence_length; i++) {
            int moisture_level = moisture_sequence[i];
            printf("Moisture level: %d%%\n", moisture_level);

            // Check if watering is needed
            if (check_moisture(moisture_level)) {
                printf("Watering needed...\n");

                // Open the valve
                if (open_valve(VALVE_GPIO) != 0) {
                    log_error("Failed to open valve during watering cycle.");
                    // Attempt to close the valve before exiting
                    close_valve(VALVE_GPIO);
                    gpioTerminate();
                    return 1;
                }

                // Sweep the nozzle through the angles
                if (sweep_nozzle(NOZZLE_GPIO, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH, SERVO_SWEEP_DURATION) != 0) {
                    log_error("Failed to sweep nozzle during watering cycle.");
                    // Attempt to close the valve before exiting
                    close_valve(VALVE_GPIO);
                    gpioTerminate();
                    return 1;
                }

                // Hold the spray for 5 seconds
                gpioDelay(WATERING_DURATION * 1000000); // Convert seconds to microseconds

                // Close the valve
                if (close_valve(VALVE_GPIO) != 0) {
                    log_error("Failed to close valve during watering cycle.");
                    // Attempt to close the valve before exiting
                    close_valve(VALVE_GPIO);
                    gpioTerminate();
                    return 1;
                }

                // Backoff delay
                gpioDelay(BACKOFF_DELAY * 1000); // Convert milliseconds to microseconds
            }

            // Wait for the next moisture cycle
            gpioDelay(MOISTURE_CYCLE_DURATION * 1000000); // Convert seconds to microseconds
        }
    }

    // Clean up and exit
    set_servo_pulse_width(VALVE_GPIO, 0);
    set_servo_pulse_width(NOZZLE_GPIO, 0);
    gpioServo(VALVE_GPIO, 0);
    gpioServo(NOZZLE_GPIO, 0);
    gpioTerminate();
    return 0;
}

