#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000 // 50ms timeout

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to generate a 10µs trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measure_pulse_width() {
    long start_tick, end_tick, diff;

    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Wait for rising edge
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for falling edge
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    if (diff < 0) {
        diff += 0xFFFFFFFF; // Handle tick rollover
    }
    return diff;
}

// Function to calculate distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * 0.0343 / 2.0;
}

// Function to log the distance to a file
void log_distance(float distance) {
    if (log_file != NULL) {
        fprintf(log_file, "%.2f\n", distance);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    int result;
    long pulse_width;
    float distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open the log file in append mode
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting distance measurement. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();
        pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            distance = calculate_distance(pulse_width);
            if (distance >= 0) {
                log_distance(distance);
                printf("Distance: %.2f cm\n", distance);
            } else {
                fprintf(stderr, "Error: Invalid distance measurement.\n");
                log_distance(-1.0);
            }
        } else {
            fprintf(stderr, "Error: Timeout waiting for echo.\n");
            log_distance(-1.0);
        }

        gpioDelay(60000); // Wait 60ms
    }

    // Clean up and exit
    fclose(log_file);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

