    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    int result;
    long pulse_width;
    float distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open the log file in append mode
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting distance measurement. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();
        pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            distance = calculate_distance(pulse_width);
            if (distance >= 0) {
                log_distance(distance);
                printf("Distance: %.2f cm\n", distance);
            } else {
                fprintf(stderr, "Error: Invalid distance measurement.\n");
                log_distance(-1.0);
            }
        } else {
            fprintf(stderr, "Error: Timeout waiting for echo.\n");
            log_distance(-1.0);
        }

        gpioDelay(60000); // Wait 60ms
    }

    // Clean up and exit
    fclose(log_file);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

