#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor for +/- 250 degrees/sec range
#define GYRO_SCALE 131.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg)
{
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int result = i2cReadI2CBlockData(handle, GYRO_XOUT_H, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading gyro data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU6050
    if (write_register(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t gyro_x, gyro_y, gyro_z;

        if (read_gyro_data(i2c_handle, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert to degrees per second
            float x_dps = (float)gyro_x / GYRO_SCALE;
            float y_dps = (float)gyro_y / GYRO_SCALE;
            float z_dps = (float)gyro_z / GYRO_SCALE;

            printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

