#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define watering duration (seconds)
#define WATERING_DURATION 5

// Define watering cycle duration (seconds)
#define WATERING_CYCLE_DURATION 86400

// Define log file name
#define LOG_FILE "watering_log.txt"

// Global variable to track the watering cycle start time
time_t watering_cycle_start_time = 0;

// Function prototypes
int initialize_gpio();
int set_gpio_output(int pin, int level);
int activate_relay(int pin, int duration);
int log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down gracefully...\n", signal);

        // Release all GPIO lines
        gpioWrite(RELAY1_PIN, 1);
        gpioWrite(RELAY2_PIN, 1);
        gpioWrite(RELAY3_PIN, 1);
        gpioWrite(RELAY4_PIN, 1);

        // Close the GPIO chip
        gpioTerminate();

        // Exit the program
        exit(0);
    }
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY3_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY4_PIN);
        gpioTerminate();
        return 1;
    }

    // Set initial state to HIGH (inactive)
    if (gpioWrite(RELAY1_PIN, 1) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(RELAY2_PIN, 1) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(RELAY3_PIN, 1) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY3_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(RELAY4_PIN, 1) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY4_PIN);
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to set the level of a GPIO pin
int set_gpio_output(int pin, int level) {
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", pin);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to activate a relay for a specified duration
int activate_relay(int pin, int duration) {
    if (gpioWrite(pin, 0) != 0) { // Activate relay (active low)
        fprintf(stderr, "Failed to activate relay on GPIO %d\n", pin);
        return 1; // Indicate failure
    }
    gpioDelay(duration * 1000000); // Delay for specified duration (microseconds)
    if (gpioWrite(pin, 1) != 0) { // Deactivate relay
        fprintf(stderr, "Failed to deactivate relay on GPIO %d\n", pin);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to log an event to the watering_log.txt file
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
    return 0; // Indicate success
}

int main() {
    // Install signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed, exiting\n");
        return 1;
    }

    // Log the start of the watering cycle
    log_event("Watering cycle started");

    // Main loop
    while (1) {
        // Check if the watering cycle has completed
        if (time(NULL) - watering_cycle_start_time >= WATERING_CYCLE_DURATION) {
            // Activate relays sequentially
