    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", pin);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to activate a relay for a specified duration
int activate_relay(int pin, int duration) {
    if (gpioWrite(pin, 0) != 0) { // Activate relay (active low)
        fprintf(stderr, "Failed to activate relay on GPIO %d\n", pin);
        return 1; // Indicate failure
    }
    gpioDelay(duration * 1000000); // Delay for specified duration (microseconds)
    if (gpioWrite(pin, 1) != 0) { // Deactivate relay
        fprintf(stderr, "Failed to deactivate relay on GPIO %d\n", pin);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

