    }
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (set_gpio_mode(RELAY1_GPIO, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY2_GPIO, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY3_GPIO, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY4_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (set_pwm_frequency(PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to set the GPIO mode for a given pin
int set_gpio_mode(int gpio, int mode) {
    int result = gpioSetMode(gpio, mode);
    if (result != 0) {
        char message[100];
        snprintf(message, sizeof(message), "Failed to set GPIO %d mode to %d (error code %d)", gpio, mode, result);
        log_event(message);
        return 1;
    }
    return 0;
}

// Function to set the PWM frequency
int set_pwm_frequency(int frequency) {
    int result = gpioSetPWMfrequency(0, frequency); // Use GPIO 0 as the PWM channel
    if (result != 0) {
        char message[100];
        snprintf(message, sizeof(message), "Failed to set PWM frequency to %d (error code %d)", frequency, result);
        log_event(message);
        return 1;
    }
    return 0;
}

