    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Sunrise effect
    for (int duty_cycle = 0; duty_cycle <= 255 && running; duty_cycle += 5) {
        char message[100];
        snprintf(message, sizeof(message), "Setting duty cycle to %d for GPIOs 17, 18, 27, 22", duty_cycle);
        log_event(message);

        if (set_pwm_duty_cycle(RELAY1_GPIO, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY2_GPIO, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY3_GPIO, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY4_GPIO, duty_cycle) != 0) {
            running = 0; // Stop the loop if there's an error
        }
        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    log_event("Sunrise effect complete, shutting down...");
    set_pwm_duty_cycle(RELAY1_GPIO, 0);
    set_pwm_duty_cycle(RELAY2_GPIO, 0);
    set_pwm_duty_cycle(RELAY3_GPIO, 0);
    set_pwm_duty_cycle(RELAY4_GPIO, 0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

