#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor for gyroscope (±250°/s)
#define GYRO_SCALE 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Threshold for angular velocity (deg/s)
#define THRESHOLD 250.0

// LED GPIO pin
#define LED_PIN 17

// I2C file descriptor
int fd;

// Circular buffer
int16_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_deg_per_sec(int16_t raw_data);
void update_led(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function to initialize the MPU-6050
int init_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        if (wiringPiI2CWriteReg8(fd, PWR_MGMT_1, 0x00) < 0) { // Wake up the MPU-6050
            fprintf(stderr, "Error: Could not wake up MPU-6050. Retrying... (%d retries left)\n", retries);
            retries--;
            delay(100); // Wait before retrying
            continue;
        }

        if (wiringPiI2CWriteReg8(fd, GYRO_CONFIG, 0x00) < 0) { // Set gyro full-scale range to ±250°/s
            fprintf(stderr, "Error: Could not set gyro configuration. Retrying... (%d retries left)\n", retries);
            retries--;
            delay(100); // Wait before retrying
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    int16_t x_h, x_l, y_h, y_l, z_h, z_l;

    x_h = wiringPiI2CReadReg8(fd, GYRO_XOUT_H);
    x_l = wiringPiI2CReadReg8(fd, GYRO_XOUT_H + 1);
    y_h = wiringPiI2CReadReg8(fd, GYRO_YOUT_H);
    y_l = wiringPiI2CReadReg8(fd, GYRO_YOUT_H + 1);
    z_h = wiringPiI2CReadReg8(fd, GYRO_ZOUT_H);
    z_l = wiringPiI2CReadReg8(fd, GYRO_ZOUT_H + 1);

    if (x_h < 0 || x_l < 0 || y_h < 0 || y_l < 0 || z_h < 0 || z_l < 0) {
        fprintf(stderr, "Error: Could not read gyro data. Retrying...\n");
        return -1; // Indicate failure
    }

    *x = (x_h << 8) | x_l;
    *y = (y_h << 8) | y_l;
    *z = (z_h << 8) | z_l;

    return 0; // Success
}

// Function to convert raw gyroscope data to degrees per second
float convert_to_deg_per_sec(int16_t raw_data) {
    return (float)raw_data / GYRO_SCALE;
}

// Function to update the LED based on angular velocity
void update_led(float x, float y, float z) {
    if (fabs(x) > THRESHOLD || fabs(y) > THRESHOLD || fabs(z) > THRESHOLD) {
        digitalWrite(LED_PIN, HIGH); // Turn on LED
    } else {
        digitalWrite(LED_PIN, LOW);  // Turn off LED
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    digitalWrite(LED_PIN, LOW); // Turn off LED
    close(fd);
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Could not initialize wiringPi.\n");
        return 1;
    }

    // Initialize I2C
    fd = wiringPiI2CSetup(MPU6050_ADDR);
    if (fd == -1) {
        fprintf(stderr, "Error: Could not initialize I2C communication.\n");
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() == -1) {
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int16_t raw_x, raw_y, raw_z;
        float deg_per_sec_x, deg_per_sec_y, deg_per_sec_z;

        // Read gyroscope data
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == -1) {
            fprintf(stderr, "Error: Failed to read gyro data. Continuing...\n");
            delay(50); // Small delay to avoid spamming errors
            continue;
        }

        // Convert raw data to degrees per second
        deg_per_sec_x = convert_to_deg_per_sec(raw_x);
        deg_per_sec_y = convert_to_deg_per_sec(raw_y);
        deg_per_sec_z = convert_to_deg_per_sec(raw_z);

        // Store data in circular buffer
        gyro_buffer[buffer_index] = deg_per_sec_x;
        gyro_buffer[buffer_index + 1] = deg_per_sec_y;
        gyro_buffer[buffer_index + 2] = deg_per_sec_z;

        buffer_index = (buffer_index + 3) % BUFFER_SIZE;

        // Update LED
        update_led(deg_per_sec_x, deg_per_sec_y, deg_per_sec_z);

        // Print data (optional)
        //printf("X: %.2f, Y: %.2f, Z: %.2f\n", deg_per_sec_x, deg_per_sec_y, deg_per_sec_z);

        // Delay for 50ms (20 Hz sampling rate)
        delay(50);
    }

    return 0;
}

