#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_CS_GPIO 8 // BCM GPIO 8
#define GYRO_SENSITIVITY 0.00875 // degrees/sec/LSB
#define SAMPLE_INTERVAL_MS 10
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(int spi_handle, char *tx_buf, char *rx_buf, int len);
int read_gyro_data(int spi_handle, float *x_rate, float *y_rate, float *z_rate);
int log_data(FILE *log_file, float x_rate, float y_rate, float z_rate);
void signal_handler(int signal);
int initialize();
void cleanup();

// SPI transfer function
int spi_transfer(int spi_handle, char *tx_buf, char *rx_buf, int len) {
    int result, i;
    for (i = 0; i < MAX_RETRIES; i++) {
        result = spiXfer(spi_handle, tx_buf, rx_buf, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n", i + 1, MAX_RETRIES, result);
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }
    fprintf(stderr, "SPI transfer failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read gyroscope data
int read_gyro_data(int spi_handle, float *x_rate, float *y_rate, float *z_rate) {
    char tx_buf[6] = {0x80, 0x00, 0x00, 0x00, 0x00, 0x00}; // Read all 6 bytes
    char rx_buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (spi_transfer(spi_handle, tx_buf, rx_buf, 6) != 0) {
        fprintf(stderr, "SPI transfer failed during gyro data read.\n");
        return -1;
    }

    raw_x = (rx_buf[1] << 8) | rx_buf[2];
    raw_y = (rx_buf[3] << 8) | rx_buf[4];
    raw_z = (rx_buf[5] << 8) | rx_buf[6];

    *x_rate = (float)raw_x * GYRO_SENSITIVITY;
    *y_rate = (float)raw_y * GYRO_SENSITIVITY;
    *z_rate = (float)raw_z * GYRO_SENSITIVITY;

    return 0;
}

// Function to log data to CSV file
int log_data(FILE *log_file, float x_rate, float y_rate, float z_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x_rate, y_rate, z_rate);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure CS GPIO as output
    gpioSetMode(SPI_CS_GPIO, PI_OUTPUT);
    gpioWrite(SPI_CS_GPIO, 1); // De-assert CS initially

    return 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");

    // Close SPI device
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // De-assert CS GPIO
    gpioWrite(SPI_CS_GPIO, 1);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    float x_rate, y_rate, z_rate;

    if (initialize() != 0) {
        return 1;
    }

    fprintf(stderr, "Gyroscope data logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_gyro_data(spi_handle, &x_rate, &y_rate, &z_rate) == 0) {
            if (log_data(log_file, x_rate, y_rate, z_rate) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyro data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 10 ms
    }

    cleanup();

    return 0;
}

