// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 3915781 // 3.9 MHz
#define GYRO_SENSITIVITY 131.0 // LSB/deg/s for ±250 deg/s range
#define THRESHOLD_DEGS_PER_SEC 200.0
#define LED_GPIO 17
#define BUFFER_SIZE 64

// MPU-6050 Registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    struct timespec timestamp[BUFFER_SIZE];
    int16_t x[BUFFER_SIZE];
    int16_t y[BUFFER_SIZE];
    int16_t z[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t gyro_buffer;

// Function prototypes
int init_spi();
int init_gpio();
int init_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void add_to_buffer(circular_buffer_t *buffer, struct timespec timestamp, int16_t x, int16_t y, int16_t z);
void check_threshold(int16_t x, int16_t y, int16_t z);
void blink_led(int gpio_pin, int duration_ms);
void signal_handler(int signal);
void print_buffer(circular_buffer_t *buffer);
void cleanup();

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (%d)\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    char data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00; // Clear sleep bit
    if (spiWrite(spi_handle, data, 2) != 0) {
        fprintf(stderr, "Error: Failed to wake up MPU-6050\n");
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to wake up

    // Configure gyroscope range to ±250°/s
    data[0] = GYRO_CONFIG;
    data[1] = 0x00; // Set full scale range to ±250°/s
    if (spiWrite(spi_handle, data, 2) != 0) {
        fprintf(stderr, "Error: Failed to configure gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char data[7];
    data[0] = GYRO_XOUT_H | 0x80; // Read multiple bytes starting from GYRO_XOUT_H

    if (spiXfer(spi_handle, data, data, 7) != 0) {
        fprintf(stderr, "Error: Failed to read gyroscope data\n");
        return -1;
    }

    *x = (data[0] << 8) | data[1];
    *y = (data[2] << 8) | data[3];
    *z = (data[4] << 8) | data[5];

    // Sign extend 16-bit values to 32-bit
    *x = (int32_t)*x;
    *y = (int32_t)*y;
    *z = (int32_t)*z;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, struct timespec timestamp, int16_t x, int16_t y, int16_t z) {
    buffer->timestamp[buffer->head] = timestamp;
    buffer->x[buffer->head] = x;
    buffer->y[buffer->head] = y;
    buffer->z[buffer->head] = z;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to check for threshold violation
void check_threshold(int16_t x, int16_t y, int16_t z) {
    double x_deg_per_sec = (double)x / GYRO_SENSITIVITY;
    double y_deg_per_sec = (double)y / GYRO_SENSITIVITY;
    double z_deg_per_sec = (double)z / GYRO_SENSITIVITY;

    if (x_deg_per_sec > THRESHOLD_DEGS_PER_SEC || x_deg_per_sec < -THRESHOLD_DEGS_PER_SEC) {
        fprintf(stderr, "Warning: X-axis threshold exceeded (%.2f deg/s)\n", x_deg_per_sec);
        blink_led(LED_GPIO, 500);
    }
    if (y_deg_per_sec > THRESHOLD_DEGS_PER_SEC || y_deg_per_sec < -THRESHOLD_DEGS_PER_SEC) {
        fprintf(stderr, "Warning: Y-axis threshold exceeded (%.2f deg/s)\n", y_deg_per_sec);
        blink_led(LED_GPIO, 500);
    }
    if (z_deg_per_sec > THRESHOLD_DEGS_PER_SEC || z_deg_per_sec < -THRESHOLD_DEGS_PER_SEC) {
        fprintf(stderr, "Warning: Z-axis threshold exceeded (%.2f deg/s)\n", z_deg_per_sec);
        blink_led(LED_GPIO, 500);
    }
}

// Function to blink the LED
void blink_led(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(gpio_pin, 0); // Turn LED off
    gpioDelay(duration_ms * 1000); // Delay for specified duration
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to print the circular buffer as CSV
void print_buffer(circular_buffer_t *buffer) {
    FILE *fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open gyro_data.csv for writing\n");
        return;
    }

    fprintf(fp, "Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer->count; i++) {
        int index = (buffer->head + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&buffer->timestamp[index].tv_sec);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(fp, "%s.%09ld,%d,%d,%d\n", timestamp_str, buffer->timestamp[index].tv_nsec, buffer->x[index], buffer->y[index], buffer->z[index]);
    }

    fclose(fp);
    printf("Gyro data saved to gyro_data.csv\n");
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    struct timespec ts;

    printf("Gyroscope monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &ts);

            // Add data to circular buffer
            add_to_buffer(&gyro_buffer, ts, x, y, z);

            // Check for threshold violation
            check_threshold(x, y, z);

            // Print buffer every 10 seconds
            if (ts.tv_sec % 10 == 0) {
                print_buffer(&gyro_buffer);
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data. Retrying...\n");
        }

        gpioDelay(10000); // Delay for 10ms (adjust as needed)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

