#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B

// Sensitivity scales
#define ACCEL_SCALE 16384.0f // +/- 2g range
#define GYRO_SCALE  131.0f   // +/- 250 deg/s range

// GPIO pin for LED
#define LED_PIN 21

// Global variables
int fd;
FILE *log_file;
bool running = true;

// Function prototypes
int init_mpu6050();
int16_t read_raw_data(int reg);
float calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z);
float calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z);
void log_data(float roll, float pitch);
void control_led(float roll, float pitch);
void signal_handler(int signal);

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (wiringPiI2CWriteReg8(fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050: %s\n", strerror(errno));
        return -1;
    }

    // Configure accelerometer range to +/- 2g
    if (wiringPiI2CWriteReg8(fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range: %s\n", strerror(errno));
        return -1;
    }

    // Configure gyroscope range to +/- 250 deg/s
    if (wiringPiI2CWriteReg8(fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read raw data from the MPU-6050
int16_t read_raw_data(int reg) {
    int16_t high = wiringPiI2CReadReg8(fd, reg);
    int16_t low = wiringPiI2CReadReg8(fd, reg + 1);

    if (high < 0 || low < 0) {
        fprintf(stderr, "Error: Could not read raw data from register 0x%02X: %s\n", reg, strerror(errno));
        return 0; // Return 0 on error
    }

    return (high << 8) | low;
}

// Function to calculate roll
float calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    float roll = atan2(accel_y, accel_z) * 180 / M_PI;
    return roll;
}

// Function to calculate pitch
float calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
    return pitch;
}

// Function to log data to file
void log_data(float roll, float pitch) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control the LED
void control_led(float roll, float pitch) {
    if (fabs(roll) > 45 || fabs(pitch) > 45) {
        digitalWrite(LED_PIN, HIGH); // Turn LED on
    } else {
        digitalWrite(LED_PIN, LOW);  // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = false;
    digitalWrite(LED_PIN, LOW); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Could not initialize wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    fd = wiringPiI2CSetup(MPU6050_ADDR);
    if (fd == -1) {
        fprintf(stderr, "Error: Could not initialize I2C: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() == -1) {
        fprintf(stderr, "Error: Could not initialize MPU-6050\n");
        return 1;
    }

    // Configure LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read raw accelerometer data
        int16_t accel_x = read_raw_data(ACCEL_XOUT_H);
        int16_t accel_y = read_raw_data(ACCEL_YOUT_H);
        int16_t accel_z = read_raw_data(ACCEL_ZOUT_H);

        // Calculate roll and pitch
        float roll = calculate_roll(accel_x, accel_y, accel_z);
        float pitch = calculate_pitch(accel_x, accel_y, accel_z);

        // Log data
        log_data(roll, pitch);

        // Control LED
        control_led(roll, pitch);

        // Delay for 100ms
        delay(100);
    }

    return 0;
}

