#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define AMBIENT_LIGHT_REG 0x22
#define PROXIMITY_REG 0x24
#define GPIO_PIN 17
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_si1145_register(int fd, uint8_t reg);
int write_si1145_register(int fd, uint8_t reg, uint8_t value);
int read_si1145_data(int fd, int *ambient_light, int *proximity);
void log_data(int ambient_light, int proximity);
void control_gpio(int state);
void signal_handler(int signal);

// Function to read a single register from the Si1145
int read_si1145_register(int fd, uint8_t reg) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadByteData(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d, retry %d\n", reg, result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "Failed to read register 0x%02X after %d retries\n", reg, RETRY_COUNT);
    return -1; // Indicate failure
}

// Function to write a single register to the Si1145
int write_si1145_register(int fd, uint8_t reg, uint8_t value) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteByteData(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing register 0x%02X: %d, retry %d\n", reg, result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "Failed to write register 0x%02X after %d retries\n", reg, RETRY_COUNT);
    return -1; // Indicate failure
}

// Function to read ambient light and proximity data from the Si1145
int read_si1145_data(int fd, int *ambient_light, int *proximity) {
    int ambient_low, ambient_high, proximity_low, proximity_high;

    ambient_low = read_si1145_register(fd, AMBIENT_LIGHT_REG);
    if (ambient_low < 0) return -1;

    ambient_high = read_si1145_register(fd, AMBIENT_LIGHT_REG + 1);
    if (ambient_high < 0) return -1;

    proximity_low = read_si1145_register(fd, PROXIMITY_REG);
    if (proximity_low < 0) return -1;

    proximity_high = read_si1145_register(fd, PROXIMITY_REG + 1);
    if (proximity_high < 0) return -1;

    *ambient_light = (ambient_high << 8) | ambient_low;
    *proximity = (proximity_high << 8) | proximity_low;

    return 0;
}

// Function to log the data to a file
void log_data(int ambient_light, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%d\n", timestamp, ambient_light, proximity);
    fflush(log_file); // Ensure data is written immediately
}

// Function to control the GPIO pin
void control_gpio(int state) {
    gpioWrite(GPIO_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int ambient_light, proximity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handlers
