#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (BCM)
#define SAMPLE_DELAY_MS 10
#define GYRO_DATA_REG 0x00 // Example register address
#define GYRO_DATA_LENGTH 4 // Number of bytes to read (2 for each axis)
#define CSV_FILE "gyro_data.csv"
#define MAX_REINIT_ATTEMPTS 3

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data);
int16_t read_gyro_data(int handle);
void log_data(FILE *fp, gyro_data_t data);
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read a single register from the ADXRS290
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set read bit
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    *data = rx_buf[1];
    return 0;
}

// Function to read gyroscope data (X and Y axis rates)
int16_t read_gyro_data(int handle) {
    uint8_t data[GYRO_DATA_LENGTH];
    int16_t x_rate, y_rate;

    if (spi_read_register(handle, GYRO_DATA_REG, data) != 0) {
        return 0; // Return 0 on error
    }

    x_rate = (int16_t)((data[0] << 8) | data[1]);
    y_rate = (int16_t)((data[2] << 8) | data[3]);

    return (x_rate, y_rate);
}

// Function to log data to a CSV file
void log_data(FILE *fp, gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp = (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    fprintf(fp, "%lld,%d,%d\n", timestamp, data.x_rate, data.y_rate);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Ensure CS is initially high

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen(CSV_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        cleanup();
        return 1;
    }

    // Write CSV header
    fprintf(fp, "timestamp,X_axis_rate,Y_axis_rate\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data(spi_handle);
        log_data(fp, data);
        gpioDelay(SAMPLE_DELAY_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

