#define ALERT_DURATION 2 // seconds
#define SEISMIC_EVENT_DURATION 0.5 // seconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void sensor1_callback(int gpio, int level, uint32_t tick);
void sensor2_callback(int gpio, int level, uint32_t tick);
void alert_callback(int gpio, int level, uint32_t tick);
void log_event();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1_state;
    int sensor2_state;
    time_t last_seismic_event;
} SensorData;

SensorData sensor_data = {0, 0, 0};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Check if both sensors are HIGH and the event duration has elapsed
        if (sensor_data.sensor1_state == 1 && sensor_data.sensor2_state == 1 &&
            (time(NULL) - sensor_data.last_seismic_event) >= SEISMIC_EVENT_DURATION) {
            alert_callback(ALERT_PIN, 1, 0); // Trigger alert
            log_event(); // Log the event
            sensor_data.last_seismic_event = time(NULL); // Reset the timer
        }
        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    fclose(log_file);
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

