        fprintf(stderr, "Failed to register callback for sensor 1\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFunc(SENSOR2_PIN, sensor2_callback) != 0) {
        fprintf(stderr, "Failed to register callback for sensor 2\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        sensor_data.sensor1_state = 1;
    } else {
        sensor_data.sensor1_state = 0;
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        sensor_data.sensor2_state = 1;
    } else {
        sensor_data.sensor2_state = 0;
    }
}

