// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define the total duration for the sunset simulation
int total_duration;

// Function prototypes
void lamp1_fade(int duration);
void lamp2_fade(int duration);
void lamp3_fade(int duration);
void cleanup(int signal);

// Global variable to track if the program should exit
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void cleanup(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off all lamps
    gpioPWM(LAMP1_GPIO, 0);
    gpioPWM(LAMP2_GPIO, 0);
    gpioPWM(LAMP3_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to fade a single lamp from full brightness to off
void lamp1_fade(int duration) {
    int i;
    int duty_cycle;

    // Full brightness
    gpioPWM(LAMP1_GPIO, 255);
    printf("Lamp 1: Full brightness (%d)\n", 255);

    // Fade out over the specified duration
    for (i = 255; i >= 0; i -= 5) {
        gpioPWM(LAMP1_GPIO, i);
        printf("Lamp 1: Brightness (%d)\n", i);
        sleep((duration * 1.0) / 255.0); // Adjust sleep time for smooth fade
    }

    printf("Lamp 1: Off\n");
}

void lamp2_fade(int duration) {
    int i;
    int duty_cycle;

    // Full brightness
    gpioPWM(LAMP2_GPIO, 255);
    printf("Lamp 2: Full brightness (%d)\n", 255);

    // Fade out over the specified duration
    for (i = 255; i >= 0; i -= 5) {
        gpioPWM(LAMP2_GPIO, i);
        printf("Lamp 2: Brightness (%d)\n", i);
        sleep((duration * 1.0) / 255.0); // Adjust sleep time for smooth fade
    }

    printf("Lamp 2: Off\n");
}

void lamp3_fade(int duration) {
    int i;
    int duty_cycle;

    // Full brightness
    gpioPWM(LAMP3_GPIO, 255);
    printf("Lamp 3: Full brightness (%d)\n", 255);

    // Fade out over the specified duration
    for (i = 255; i >= 0; i -= 5) {
        gpioPWM(LAMP3_GPIO, i);
        printf("Lamp 3: Brightness (%d)\n", i);
        sleep((duration * 1.0) / 255.0); // Adjust sleep time for smooth fade
    }

    printf("Lamp 3: Off\n");
}

int main(int argc, char *argv[]) {
    int i;

    // Check for the correct number of command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_seconds>\n", argv[0]);
        return 1;
    }

    // Parse the total duration from the command-line argument
    total_duration = atoi(argv[1]);

    // Validate the total duration
    if (total_duration < 1 || total_duration > 3600) {
        fprintf(stderr, "Error: Total duration must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(LAMP1_GPIO, 255);
    gpioSetPWMrange(LAMP2_GPIO, 255);
    gpioSetPWMrange(LAMP3_GPIO, 255);

    // Set initial duty cycle to 0 for all lamps
    gpioPWM(LAMP1_GPIO, 0);
    gpioPWM(LAMP2_GPIO, 0);
    gpioPWM(LAMP3_GPIO, 0);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    while (program_running) {
        // Fade in Lamp 1
        lamp1_fade(total_duration);

        // Fade in Lamp 2
        lamp2_fade(total_duration);

        // Fade in Lamp 3
        lamp3_fade(total_duration);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    cleanup(0);

    return 0;
}

