#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the traffic light
#define RED_PIN   17
#define YELLOW1_PIN 22
#define YELLOW2_PIN 23
#define GREEN_PIN 24

// Define the duration of each light phase in seconds
#define RED_DURATION 10
#define RED_YELLOW_DURATION 2
#define GREEN_DURATION 10
#define YELLOW_DURATION 3

// Global variable to track the current phase
int current_phase = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    // Deactivate all relays
    gpioWrite(RED_PIN, 1);
    gpioWrite(YELLOW1_PIN, 1);
    gpioWrite(YELLOW2_PIN, 1);
    gpioWrite(GREEN_PIN, 1);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to set the state of a GPIO pin
void set_gpio_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
    }
}

// Function to cycle through the traffic light sequence
void cycle_traffic_light() {
    int red_state = 1; // Active low, so HIGH de-energizes the relay
    int yellow1_state = 1;
    int yellow2_state = 1;
    int green_state = 1;

    switch (current_phase) {
        case 0: // Red
            set_gpio_state(RED_PIN, red_state);
            set_gpio_state(YELLOW1_PIN, yellow1_state);
            set_gpio_state(YELLOW2_PIN, yellow2_state);
            set_gpio_state(GREEN_PIN, green_state);
            printf("Red light ON\n");
            gpioDelay(RED_DURATION * 1000000); // Convert seconds to microseconds
            break;
        case 1: // Red + Yellow
            set_gpio_state(RED_PIN, red_state);
            set_gpio_state(YELLOW1_PIN, 0); // De-energize Yellow1
            set_gpio_state(YELLOW2_PIN, yellow2_state);
            set_gpio_state(GREEN_PIN, green_state);
            printf("Red + Yellow light ON\n");
            gpioDelay(RED_YELLOW_DURATION * 1000000); // Convert seconds to microseconds
            break;
        case 2: // Green
            set_gpio_state(RED_PIN, red_state);
            set_gpio_state(YELLOW1_PIN, yellow1_state);
            set_gpio_state(YELLOW2_PIN, yellow2_state);
            set_gpio_state(GREEN_PIN, 0); // De-energize Green
            printf("Green light ON\n");
            gpioDelay(GREEN_DURATION * 1000000); // Convert seconds to microseconds
            break;
        case 3: // Yellow
            set_gpio_state(RED_PIN, red_state);
            set_gpio_state(YELLOW1_PIN, yellow1_state);
            set_gpio_state(YELLOW2_PIN, 0); // De-energize Yellow2
            set_gpio_state(GREEN_PIN, green_state);
            printf("Yellow light ON\n");
            gpioDelay(YELLOW_DURATION * 1000000); // Convert seconds to microseconds
            break;
        default:
            fprintf(stderr, "Error: Invalid phase\n");
            break;
    }

    current_phase = (current_phase + 1) % 4; // Cycle through the phases
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(YELLOW1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", YELLOW1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(YELLOW2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", YELLOW2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to cycle through the traffic light sequence
    while (1) {
        cycle_traffic_light();
    }

    return 0; // This line will never be reached due to the infinite loop
}

