#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17 // BCM GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define TOUCH_THRESHOLD 0x0C // Touch threshold for electrode 0
#define RELEASE_THRESHOLD 0x0E // Release threshold for electrode 0
#define RELAY_ON_TIME_MS 500

// Global variables
static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init(int fd);
int mpr121_read_touch_status(int fd);
void relay_on(int pin);
void relay_off(int pin);
void log_error(const char *message);
void signal_handler(int signal);

// Function to initialize the MPR121
int mpr121_init(int fd) {
    // Stop mode
    if (wiringPiI2CWriteReg8(fd, 0x2B, 0x00) < 0) {
        log_error("Failed to set MPR121 to stop mode.");
        return -1;
    }

    // Electrode configuration
    if (wiringPiI2CWriteReg8(fd, 0x5E, 0x8F) < 0) { // Enable all electrodes
        log_error("Failed to enable electrodes.");
        return -1;
    }

    // Touch and release thresholds for electrode 0
    if (wiringPiI2CWriteReg8(fd, 0x41, TOUCH_THRESHOLD) < 0) {
        log_error("Failed to set touch threshold for electrode 0.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, 0x42, RELEASE_THRESHOLD) < 0) {
        log_error("Failed to set release threshold for electrode 0.");
        return -1;
    }

    // Configure baseline filtering
    if (wiringPiI2CWriteReg8(fd, 0x2B, 0x01) < 0) {
        log_error("Failed to set baseline filtering.");
        return -1;
    }

    // Start mode
    if (wiringPiI2CWriteReg8(fd, 0x2B, 0x10) < 0) {
        log_error("Failed to set MPR121 to start mode.");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(int fd) {
    int touch_status = wiringPiI2CReadReg8(fd, 0x00);
    if (touch_status < 0) {
        log_error("Failed to read touch status.");
        return -1;
    }
    return touch_status;
}

// Function to turn the relay ON
void relay_on(int pin) {
    digitalWrite(pin, HIGH);
}

// Function to turn the relay OFF
void relay_off(int pin) {
    digitalWrite(pin, LOW);
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s (errno: %d)\n", timestamp, message, errno);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "I2C initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) == -1) {
        fprintf(stderr, "MPR121 initialization failed.\n");
        return 1;
    }

    // Set relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    relay_off(RELAY_PIN); // Initialize relay to OFF

    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch relay program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status == -1) {
            log_error("Failed to read touch status in main loop.");
        } else {
            // Check if electrode 0 is touched
            if (touch_status & 0x01) {
                relay_on(RELAY_PIN);
                delay(RELAY_ON_TIME_MS);
                relay_off(RELAY_PIN);
                delay(DEBOUNCE_DELAY_MS);
            }
        }
        delay(10); // Check every 10ms
    }

    // Cleanup
    relay_off(RELAY_PIN);
    fclose(log_file);
    return 0;
}

