#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_1 17
#define FLAME_SENSOR_2 22
#define FLAME_SENSOR_3 23
#define BUZZER 18
#define LED 24

// Define constants
#define LOG_FILE "flame_log.txt"
#define DEBOUNCE_DELAY_MS 50
#define FLAME_DETECT_WINDOW_MS 150
#define BUZZER_DURATION_MS 500

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio);
int log_event(int gpio, const char *message);
void activate_buzzer(int duration_ms);
void deactivate_buzzer();
void activate_led(int duration_ms);
void deactivate_led();
void signal_handler(int signal);
int setup();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor value with debouncing
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    return value;
}

// Function to log events to file
int log_event(int gpio, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - GPIO %d: %s\n", timestamp, gpio, message);
        fflush(log_file); // Ensure immediate write to file
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Failure
    }
}

// Function to activate the buzzer
void activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER, 1); // Turn buzzer on
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioWrite(BUZZER, 0); // Turn buzzer off
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER, 0); // Turn buzzer off
}

// Function to activate the LED
void activate_led(int duration_ms) {
    gpioWrite(LED, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioWrite(LED, 0); // Turn LED off
}

// Function to deactivate the LED
void deactivate_led() {
    gpioWrite(LED, 0); // Turn LED off
}

// Setup function to initialize GPIO and logging
int setup() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_1, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_2, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_3, PI_INPUT);
    gpioSetMode(BUZZER, PI_OUTPUT);
    gpioSetMode(LED, PI_OUTPUT);

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Clean up pigpio before exiting
        return -1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Release GPIO lines
    gpioSetMode(FLAME_SENSOR_1, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_2, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_3, PI_INPUT);
    gpioSetMode(BUZZER, PI_INPUT);
    gpioSetMode(LED, PI_INPUT);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() != 0) {
        fprintf(stderr, "Setup failed, exiting.\n");
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    int flame_detected = 0;
    int sensor1_state = read_sensor(FLAME_SENSOR_1);
    int sensor2_state = read_sensor(FLAME_SENSOR_2);
    int sensor3_state = read_sensor(FLAME_SENSOR_3);

    while (program_running) {
        int current_sensor1_state = read_sensor(FLAME_SENSOR_1);
        int current_sensor2_state = read_sensor(FLAME_SENSOR_2);
        int current_sensor3_state = read_sensor(FLAME_SENSOR_3);

        if (current_sensor1_state == 0 && current_sensor2_state == 0 && current_sensor3_state == 0) {
            if (!flame_detected) {
                // Flame detected
                log_event(FLAME_SENSOR_1, "Flame Detected");
                log_event(FLAME_SENSOR_2, "Flame Detected");
                log_event(FLAME_SENSOR_3, "Flame Detected");

                activate_buzzer(BUZZER_DURATION_MS);
                activate_led(BUZZER_DURATION_MS);
                flame_detected = 1;
            }
        } else {
            // Flame cleared
            flame_detected = 0;
        }

        gpioDelay(50 * 1000); // Check every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

