#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define ENA 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENB 25

// Constants
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 255
#define OBSTACLE_THRESHOLD 20.0 // cm
#define LOG_FILE "balance_log.txt"

// PID Constants
#define KP 0.5
#define KI 0.01
#define KD 0.1

// Global variables
static volatile int running = 1;
FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void set_motor_speed(int motor, int speed);
void stop_motors();
float get_tilt_error();
float get_distance();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void obstacle_avoidance();

// PID variables
float integral = 0.0;
float previous_error = 0.0;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, stopping...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(ENB, PWM_FREQUENCY);
    gpioSetPWMrange(ENA, PWM_RANGE);
    gpioSetPWMrange(ENB, PWM_RANGE);

    return 0;
}

// Function to stop the motors
void stop_motors() {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioPWM(ENA, 0);
    gpioPWM(ENB, 0);
}

// Function to set the speed of a motor
void set_motor_speed(int motor, int speed) {
    if (speed < -PWM_RANGE || speed > PWM_RANGE) {
        fprintf(stderr, "Invalid motor speed: %d\n", speed);
        return;
    }

    if (motor == 0) { // Motor A
        gpioWrite(MOTOR_A_FORWARD, (speed > 0) ? 1 : 0);
        gpioWrite(MOTOR_A_BACKWARD, (speed < 0) ? 1 : 0);
        gpioPWM(ENA, abs(speed));
    } else { // Motor B
        gpioWrite(MOTOR_B_FORWARD, (speed > 0) ? 1 : 0);
        gpioWrite(MOTOR_B_BACKWARD, (speed < 0) ? 1 : 0);
        gpioPWM(ENB, abs(speed));
    }
}

// Function to get a simulated tilt error
float get_tilt_error() {
    return (float)(rand() % 2001 - 1000) / 100.0; // -10.0 to 10.0
}

// Function to get a simulated distance from the ultrasonic sensor
float get_distance() {
    return (float)(rand() % 1999 + 2) / 100.0; // 2.0 to 400.0
}

// Function to log data to a file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to handle obstacle avoidance
void obstacle_avoidance() {
    set_motor_speed(0, -128); // Reverse Motor A at 50% speed
    set_motor_speed(1, -128); // Reverse Motor B at 50% speed
    gpioDelay(200); // Reverse for 200ms
    stop_motors();
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    printf("Self-balancing robot started. Press Ctrl+C to stop.\n");

    while (running) {
        // Get sensor readings
        float tilt_error = get_tilt_error();
        float distance = get_distance();

        // Calculate PID output
        float error = tilt_error;
        integral += error;
        float derivative = error - previous_error;
        float output = KP * error + KI * integral + KD * derivative;

        // Clamp the output to the valid range
        int motor_a_speed = (int)output;
        int motor_b_speed = (int)output;

        if (motor_a_speed < -PWM_RANGE) motor_a_speed = -PWM_RANGE;
        if (motor_a_speed > PWM_RANGE) motor_a_speed = PWM_RANGE;
        if (motor_b_speed < -PWM_RANGE) motor_b_speed = -PWM_RANGE;
        if (motor_b_speed > PWM_RANGE) motor_b_speed = PWM_RANGE;

        // Set motor speeds
        set_motor_speed(0, motor_a_speed);
        set_motor_speed(1, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            obstacle_avoidance();
        }

        // Update previous error
        previous_error = error;

        // Delay for 50ms
        gpioDelay(50);
    }

    // Stop motors and cleanup
    stop_motors();
    fclose(log_file);
    cleanup_gpio();

    printf("Self-balancing robot stopped.\n");

    return 0;
}

// Cleanup function to stop motors and terminate pigpio
void cleanup_gpio() {
    gpioTerminate();
}

