#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d to input\n", TOUCH_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d to output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Enable pull-down resistor on the touch sensor pin
    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO%d\n", TOUCH_PIN);
        gpioTerminate();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the touch sensor value
        int touch_value = gpioRead(TOUCH_PIN);

        if (touch_value == 1) {
            // Touch detected
            printf("Touch detected!\n");
            // Toggle the relay state
            gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));

            // Debounce delay
            gpioDelay(50000); // 50ms
        }

        gpioDelay(10000); // Check every 10ms
    }

    // Cleanup
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

