#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

// Configuration
#define SAMPLE_RATE 8000
#define BUFFER_SIZE 1024
#define SENSITIVITY 1.0 // Default sensitivity
#define RED_GPIO 17
#define GREEN_GPIO 18
#define BLUE_GPIO 27
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define PWM_DUTY_CYCLE 50 // Percentage (0-100)

// Global variables
snd_pcm_t *pcm_handle;
int running = 1;

// Function prototypes
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int buffer_size);
double calculate_rms(const short *buffer, int buffer_size);
void map_amplitude_to_color(double rms, double sensitivity, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Release ALSA resources
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }

    // Release pigpio resources
    gpioTerminate();

    exit(0);
}

// Capture audio from ALSA
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int buffer_size) {
    int rc = snd_pcm_readi(pcm_handle, buffer, buffer_size);
    if (rc == -EPIPE) {
        fprintf(stderr, "Error: Overrun occurred\n");
        snd_pcm_prepare(pcm_handle);
        return -1;
    } else if (rc < 0) {
        fprintf(stderr, "Error: %s\n", snd_strerror(rc));
        return -1;
    } else if (rc != buffer_size) {
        fprintf(stderr, "Warning: Read %d frames, expected %d\n", rc, buffer_size);
    }
    return rc;
}

// Calculate RMS amplitude
double calculate_rms(const short *buffer, int buffer_size) {
    double sum_sq = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_sq += (double)buffer[i] * (double)buffer[i];
    }
    return sqrt(sum_sq / buffer_size);
}

// Map RMS amplitude to RGB color
void map_amplitude_to_color(double rms, double sensitivity, int *red, int *green, int *blue) {
    // Non-linear mapping (logarithmic)
    double log_rms = log10(rms + 0.0001); // Avoid log(0)
    double log_sensitivity = log10(sensitivity);

    // Normalize to 0-1 range
    double normalized_rms = log_rms / log10(10000.0); // Assuming max RMS is 10000 (adjust as needed)
    double normalized_sensitivity = log_sensitivity / log10(10000.0);

    // Map to RGB (simplified, adjust as needed)
    *red = (int)(normalized_rms * 255.0);
    *green = (int)((normalized_sensitivity * 0.5 + 0.5) * 255.0); // Adjust green sensitivity
    *blue = (int)(normalized_rms * 255.0);

    // Clamp to 0-255 range
    if (*red > 255) *red = 255;
    if (*green > 255) *green = 255;
    if (*blue > 255) *blue = 255;
}

// Set LED color using pigpio
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_GPIO, red);
    gpioPWM(GREEN_GPIO, green);
    gpioPWM(BLUE_GPIO, blue);
}

int main(int argc, char *argv[]) {
    int buffer_size = BUFFER_SIZE;
    double sensitivity = SENSITIVITY;

    // Parse command-line arguments
    if (argc > 1) {
        sensitivity = atof(argv[1]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RED_GPIO, PI_OUTPUT);
    gpioSetMode(GREEN_GPIO, PI_OUTPUT);
    gpioSetMode(BLUE_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(RED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(RED_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(GREEN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(GREEN_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(BLUE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(BLUE_GPIO, PWM_RANGE);

    // Set PWM duty cycle
    gpioPWM(RED_GPIO, PWM_DUTY_CYCLE);
    gpioPWM(GREEN_GPIO, PWM_DUTY_CYCLE);
    gpioPWM(BLUE_GPIO, PWM_DUTY_CYCLE);

    // Initialize ALSA
    snd_pcm_t *pcm_handle = NULL;
    int rc = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (rc < 0) {
        fprintf(stderr, "Error: %s\n", snd_strerror(rc));
        gpioTerminate();
        return 1;
    }

    // Configure ALSA
    rc = snd_pcm_hw_params_malloc(&snd_pcm_hw_params_any);
    if (rc < 0) {
        fprintf(stderr, "Error: %s\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params_any(pcm_handle, snd_pcm_hw_params_any);
    if (rc < 0) {
        fprintf(stderr, "Error: %s\n", snd_strerror(rc));
        snd_pcm_hw_params_free(snd_pcm_hw_params_any);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params_set_access(pcm_handle, snd_pcm_hw_params_any, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (rc < 0) {
        fprintf(stderr, "Error: %s\n", snd_strerror(rc));
        snd_pcm_hw_params_free(snd_pcm_hw_params_any);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params_set_format(pcm_handle, snd_pcm_hw_params_any, SND_PCM_FORMAT_S16_LE);
    if (rc < 0) {
        fprintf(stderr, "Error: %s\n", snd_strerror(rc));
        snd_pcm_hw_params_free(snd_pcm_hw_params_any);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params_set_channels(pcm_handle, snd_pcm_hw_params_any, 1);
    if (rc < 0) {
        fprintf(stderr, "Error: %s\n", snd_strerror(rc));
        snd_pcm_hw_params_free(snd_pcm_hw_params_any);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params_set_rate(pcm_handle, snd_pcm_hw_params_any, SAMPLE_RATE, 0);
    if (rc < 0) {
        fprintf(stderr, "Error: %s\n", snd_strerror(rc));
        snd_pcm_hw_params_free(snd_pcm_hw_params_any);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params_set_period_size_near(pcm_handle, snd_pcm_hw_params_any, &buffer_size, 0);
    if (rc < 0) {
        fprintf(stderr, "Error: %s\n", snd_strerror(rc));
        snd_pcm_hw_params_free(snd_pcm_hw_params_any);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params(pcm_handle, snd_pcm_hw_params_any);
    if (rc < 0) {
        fprintf(stderr, "Error: %s\n", snd_strerror(rc));
        snd_pcm_hw_params_free(snd_pcm_hw_params_any);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Prepare ALSA
    rc = snd_pcm_prepare(pcm_handle);
    if (rc < 0) {
        fprintf(stderr, "Error: %s\n", snd_strerror(rc));
        snd_pcm_hw_params_free(snd_pcm_hw_params_any);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    short *buffer = (short *)malloc(buffer_size * sizeof(short));
    if (!buffer) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Capture audio
        int frames_read = capture_audio(pcm_handle, buffer, buffer_size);
        if (frames_read < 0) {
            fprintf(stderr, "Error: Audio capture failed\n");
            break;
        }

        // Calculate RMS
        double rms = calculate_rms(buffer, buffer_size);

        // Map amplitude to color
        int red, green, blue;
        map_amplitude_to_color(rms, sensitivity, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Sleep for 10ms
        usleep(10000); // 10ms
    }

    // Clean up
    free(buffer);
    snd_pcm_drain(pcm_handle);
    snd_pcm_close(pcm_handle);
    gpioTerminate();

    return 0;
}

