#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Calibration values (replace with your calibrated values)
#define C_SCALE 0.5  // Example: 0.5 for no scaling
#define R_SCALE 0.5
#define G_SCALE 0.5
#define B_SCALE 0.5

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_tcs34725();
int read_tcs34725(uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b);
void log_data(uint32_t timestamp, uint16_t c, uint16_t r, uint16_t g, uint16_t b);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize TCS34725 sensor
int init_tcs34725() {
    // Enable the sensor (PON and AEN)
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to enable register: %s\n", strerror(errno));
        return -1;
    }

    // Set integration time (ATIME) to 154ms
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error writing to integration time register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read color data from TCS34725 sensor
int read_tcs34725(uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t buffer[8];

    // Read all color data registers in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CDATA, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Error reading color data: %s\n", strerror(errno));
        return -1;
    }

    *c = (buffer[1] << 8) | buffer[0];
    *r = (buffer[3] << 8) | buffer[2];
    *g = (buffer[5] << 8) | buffer[4];
    *b = (buffer[7] << 8) | buffer[6];

    return 0;
}

// Log data to CSV file
void log_data(uint32_t timestamp, uint16_t c, uint16_t r, uint16_t g, uint16_t b) {
    fprintf(fp, "%u,%u,%u,%u,%u\n", timestamp, c, r, g, b);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (init_tcs34725() < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening color_data.csv: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,C, R, G, B\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t c, r, g, b;
    uint32_t timestamp;

    // Main loop
    while (!terminate) {
        // Read color data
        if (read_tcs34725(&c, &r, &g, &b) == 0) {
            // Get timestamp
            timestamp = time(NULL);

            // Log data
            log_data(timestamp, c, r, g, b);
        } else {
            fprintf(stderr, "Failed to read color data. Logging zeros.\n");
            log_data(time(NULL), 0, 0, 0, 0);
        }

        // Wait 500ms
        gpioDelay(500000); // pigpio uses microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

