#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 34560

// Global variable to track the current phase
int current_phase = 0;

// Function prototypes
void sunrise();
void daytime();
void sunset();
void nighttime();
void signal_handler(int signal);

// Function to set the duty cycle of a relay
void set_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Invalid duty cycle value. Must be between 0 and 100.\n");
        return;
    }

    int pulse_width = (duty_cycle * 1000) / 100; // Calculate pulse width in microseconds
    gpioPWM(gpio_pin, pulse_width); // Set the PWM duty cycle
}

// Sunrise phase function
void sunrise() {
    int duty_cycle = 0;
    for (int i = 0; i < SUNRISE_DURATION; i++) {
        sleep(1); // Wait for 1 second
        duty_cycle += 10; // Increment duty cycle by 10%
        if (duty_cycle > 100) {
            duty_cycle = 100;
        }
        set_duty_cycle(RELAY1_PIN, duty_cycle);
        set_duty_cycle(RELAY2_PIN, duty_cycle);
        set_duty_cycle(RELAY3_PIN, duty_cycle);
        set_duty_cycle(RELAY4_PIN, duty_cycle);
    }
}

// Daytime phase function
void daytime() {
    for (int i = 0; i < DAYTIME_DURATION; i++) {
        sleep(1); // Wait for 1 second
        set_duty_cycle(RELAY1_PIN, 50); // Set duty cycle to 50%
        set_duty_cycle(RELAY2_PIN, 50);
        set_duty_cycle(RELAY3_PIN, 50);
        set_duty_cycle(RELAY4_PIN, 50);
    }
}

// Sunset phase function
void sunset() {
    int duty_cycle = 100;
    for (int i = 0; i < SUNSET_DURATION; i++) {
        sleep(1); // Wait for 1 second
        duty_cycle -= 10; // Decrement duty cycle by 10%
        if (duty_cycle < 0) {
            duty_cycle = 0;
        }
        set_duty_cycle(RELAY1_PIN, duty_cycle);
        set_duty_cycle(RELAY2_PIN, duty_cycle);
        set_duty_cycle(RELAY3_PIN, duty_cycle);
        set_duty_cycle(RELAY4_PIN, duty_cycle);
    }
}

// Nighttime phase function
void nighttime() {
    for (int i = 0; i < NIGHTTIME_DURATION; i++) {
        sleep(1); // Wait for 1 second
        set_duty_cycle(RELAY1_PIN, 0); // Turn off the relay
        set_duty_cycle(RELAY2_PIN, 0);
        set_duty_cycle(RELAY3_PIN, 0);
        set_duty_cycle(RELAY4_PIN, 0);
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Turn off all relays
    set_duty_cycle(RELAY1_PIN, 0);
    set_duty_cycle(RELAY2_PIN, 0);
    set_duty_cycle(RELAY3_PIN, 0);
    set_duty_cycle(RELAY4_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM range (0-1000 for pigpio)
    gpioSetPWMrange(RELAY1_PIN, 1000);
    gpioSetPWMrange(RELAY2_PIN, 1000);
    gpioSetPWMrange(RELAY3_PIN, 1000);
    gpioSetPWMrange(RELAY4_PIN, 1000);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        switch (current_phase) {
            case 0: // Sunrise
                sunrise();
                current_phase = 1;
                break;
            case 1: // Daytime
                daytime();
                current_phase = 2;
                break;
            case 2: // Sunset
                sunset();
                current_phase = 3;
                break;
            case 3: // Nighttime
                nighttime();
                current_phase = 0; // Reset to sunrise
                break;
        }
    }

    return 0;
}

