#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_DURATION_S 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"

static volatile int running = 1;
static volatile unsigned long last_trigger_time = 0;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a motion event to the log file
int log_motion_event(const char* timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
    return 0;
}

// Function to capture a video using raspivid
int capture_video() {
    char filename[100];
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for filename.\n");
        return -1;
    }

    snprintf(filename, sizeof(filename), "/home/pi/videos/%s.h264", timestamp);
    free(timestamp);

    char command[200];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, CAPTURE_DURATION_S * 1000); // Convert seconds to milliseconds

    int status = system(command);
    if (status == -1) {
        perror("Error executing raspivid command");
        return -1;
    }

    return 0;
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

// Function to cleanup the pigpio library
void cleanup_gpio() {
    gpioTerminate();
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register the signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = gpioRead(GPIO_PIN);

        if (sensor_value == 0) { // Motion detected (active-low)
            unsigned long current_time = gpioTick();

            // Debounce the sensor
            if (current_time - last_trigger_time > DEBOUNCE_DELAY_MS * 1000) {
                char* timestamp = get_iso8601_timestamp();
                if (timestamp != NULL) {
                    if (log_motion_event(timestamp) == 0) {
                        printf("Motion detected at %s. Logging event.\n", timestamp);
                    } else {
                        fprintf(stderr, "Failed to log motion event.\n");
                    }
                    free(timestamp);

                    if (capture_video() == 0) {
                        printf("Video capture started.\n");
                    } else {
                        fprintf(stderr, "Failed to capture video.\n");
                    }
                } else {
                    fprintf(stderr, "Failed to get timestamp for logging.\n");
                }

                last_trigger_time = current_time;
            }
        }

        gpioDelay(50); // Check every 50ms
    }

    // Cleanup
    cleanup_gpio();
    printf("Exiting.\n");
    return 0;
}

