void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Shutting down gracefully...\n");
        program_running = 0;

        // Deactivate all relays
        control_relay(RELAY1_PIN, 1);
        control_relay(RELAY2_PIN, 1);
        control_relay(RELAY3_PIN, 1);
        control_relay(RELAY4_PIN, 1);

        // Close the log file
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp != NULL) {
            fprintf(fp, "Program terminated by user.\n");
            fclose(fp);
        } else {
