int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Ensure all relays are initially OFF (HIGH)
    control_relay(RELAY1_PIN, 1);
    control_relay(RELAY2_PIN, 1);
    control_relay(RELAY3_PIN, 1);
    control_relay(RELAY4_PIN, 1);

    return 0; // Indicate success
}

// Function to read the simulated moisture sensor
int read_moisture_sensor() {
    srand(time(NULL)); // Seed the random number generator
    return rand() % 100; // Generate a random number between 0 and 99
}

