    // Main loop
    while (program_running) {
        // Read moisture sensor values
        int moisture1 = read_moisture_sensor();
        int moisture2 = read_moisture_sensor();
        int moisture3 = read_moisture_sensor();
        int moisture4 = read_moisture_sensor();

        // Control relays based on moisture levels
        int relay1_state = (moisture1 < MOISTURE_THRESHOLD) ? 0 : 1; // 0 = OFF, 1 = ON
        int relay2_state = (moisture2 < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay3_state = (moisture3 < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay4_state = (moisture4 < MOISTURE_THRESHOLD) ? 0 : 1;

        // Control relays
        control_relay(RELAY1_PIN, relay1_state);
        control_relay(RELAY2_PIN, relay2_state);
        control_relay(RELAY3_PIN, relay3_state);
        control_relay(RELAY4_PIN, relay4_state);

        // Log the data
        log_data(moisture1, moisture2, moisture3, moisture4, relay1_state, relay2_state, relay3_state, relay4_state);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // This point should not be reached unless program_running is set to 0 manually
    gpioTerminate();
    return 0;
}

