#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Free-fall threshold (0.2g)
#define FREEFALL_THRESHOLD 0.2

// Free-fall duration (0.5 seconds)
#define FREEFALL_DURATION 500

// Alarm duration (5 seconds)
#define ALARM_DURATION 5000

// GPIO pin for alarm
#define ALARM_GPIO 27

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
bool freefall_detected = false;
time_t freefall_start_time = 0;

// Function prototypes
int adxl345_init();
int adxl345_read_acceleration(float *x, float *y, float *z);
bool is_freefall(float x, float y, float z);
void trigger_alarm();
void log_freefall(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the ADXL345
int adxl345_init() {
    // Set power control register to start measurement
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not set ADXL345 to measurement mode.\n");
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int adxl345_read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int16_t x_raw, y_raw, z_raw;

    // Read 6 bytes of data starting from DATAX0
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, raw_data, 6) < 0) {
        fprintf(stderr, "Error: Could not read acceleration data.\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert raw values to g units (assuming +/- 2g range and 10-bit resolution)
    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

// Function to detect free-fall
bool is_freefall(float x, float y, float z) {
    return (fabs(x) < FREEFALL_THRESHOLD && fabs(y) < FREEFALL_THRESHOLD && fabs(z) < FREEFALL_THRESHOLD);
}

// Function to trigger the alarm
void trigger_alarm() {
    gpioWrite(ALARM_GPIO, 1); // Set GPIO high
    gpioDelay(ALARM_DURATION);  // Wait for alarm duration
    gpioWrite(ALARM_GPIO, 0); // Set GPIO low
}

// Function to log free-fall event to file
void log_freefall(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", buf, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(ALARM_GPIO, 0); // Turn off alarm
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float x, y, z;
    time_t start_time = 0;

    // Main loop
    while (1) {
        // Read acceleration data
        if (adxl345_read_acceleration(&x, &y, &z) == 0) {
            // Detect free-fall
            if (is_freefall(x, y, z)) {
                if (!freefall_detected) {
                    freefall_detected = true;
                    start_time = time(NULL);
                    printf("Potential free-fall detected.\n");
                } else {
                    // Check if free-fall duration has been reached
                    if (time(NULL) - start_time >= FREEFALL_DURATION) {
                        // Confirm free-fall
                        printf("Free-fall confirmed!\n");
                        trigger_alarm();
                        log_freefall(x, y, z);
                        freefall_detected = false; // Reset flag
                    }
                }
            } else {
                freefall_detected = false; // Reset flag if not in free-fall
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        gpioDelay(100); // Poll every 100 ms
    }

    return 0;
}

