#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TIMEOUT_US 100000 // 100ms timeout
#define MAX_PULSE_WIDTH_US 23200 // Maximum valid pulse width (4m range)
#define TIMEOUT_PULSE_WIDTH_US 23200 // Timeout pulse width

// Mutex for thread safety
pthread_mutex_t log_mutex;

// File pointer for logging
FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
void log_distance(uint32_t timestamp_ns, float distance_cm);
void signal_handler(int signal);

// Global variables
volatile uint32_t pulse_start = 0;
volatile uint32_t pulse_end = 0;
volatile int echo_received = 0;

// Function to generate a 10µs trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10µs pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) {
        pulse_start = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0) {
        pulse_end = tick;
        echo_received = 1; // Indicate falling edge received
    }
}

// Function to log distance data to a file
void log_distance(uint32_t timestamp_ns, float distance_cm) {
    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%u,%.2f\n", timestamp_ns, distance_cm);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    pthread_mutex_destroy(&log_mutex);
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize mutex
    if (pthread_mutex_init(&log_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        pthread_mutex_destroy(&log_mutex);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function\n");
        gpioTerminate();
        pthread_mutex_destroy(&log_mutex);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for echo
        uint32_t start_time = gpioTick();
        while (pulse_end == 0 && (gpioTick() - start_time) < TIMEOUT_US) {
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        // Check for timeout
        if (pulse_end == 0) {
            fprintf(stderr, "Timeout waiting for echo\n");
            continue; // Skip to the next iteration
        }

        // Calculate pulse width
        uint32_t pulse_width = pulse_end - pulse_start;

        // Check for invalid pulse width
        if (pulse_width > MAX_PULSE_WIDTH_US) {
            fprintf(stderr, "Invalid pulse width: %u us\n", pulse_width);
            continue; // Skip to the next iteration
        }

        // Calculate distance (speed of sound: 343 m/s)
        float distance_cm = (pulse_width / 1000000.0) * 34300.0 / 2.0;

        // Get timestamp
        uint32_t timestamp_ns = gpioTick();

        // Log distance data
        log_distance(timestamp_ns, distance_cm);

        // Wait before next measurement
        gpioDelay(200); // 200ms delay
    }

    return 0;
}

