#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_OUT_X_H 0x29
#define LIS3DH_OUT_Y_L 0x2A
#define LIS3DH_OUT_Y_H 0x2B
#define LIS3DH_OUT_Z_L 0x2C
#define LIS3DH_OUT_Z_H 0x2D

// Buzzer GPIO pin (BCM)
#define BUZZER_PIN 17

// Free-fall threshold (g)
#define FREE_FALL_THRESHOLD 0.2

// Impact threshold (g)
#define IMPACT_THRESHOLD 1.5

// Global variables
int i2c_handle;
bool running = true;

// Function prototypes
int init_i2c();
int init_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
bool detect_freefall(float magnitude);
bool detect_impact(float magnitude);
void activate_buzzer();
void deactivate_buzzer();
void signal_handler(int signal);

// Helper function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int result;
    for (int i = 0; i < 3; ++i) {
        result = i2cReadI2CBlockData(handle, reg, (char *)value, 1);
        if (result == 1) {
            return 0; // Success
        }
        gpioDelay(10); // Small delay before retry
    }
    fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
    return -1; // Failure
}

// Helper function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result;
    for (int i = 0; i < 3; ++i) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        }
        gpioDelay(10); // Small delay before retry
    }
    fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
    return -1; // Failure
}

int main(int argc, char *argv[]) {
    float freefall_threshold = FREE_FALL_THRESHOLD;
    float impact_threshold = IMPACT_THRESHOLD;

    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (running) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Detect free-fall and impact
            if (detect_freefall(magnitude)) {
                printf("Free-fall detected!\n");
            }
            if (detect_impact(magnitude)) {
                printf("Impact detected!\n");
                activate_buzzer();
                gpioDelay(1000); // Keep buzzer on for 1 second
                deactivate_buzzer();
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LIS3DH_ADDR, 0); // Bus 1, address 0x18, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LIS3DH
int init_lis3dh() {
    // Enable accelerometer (100Hz, normal mode)
    if (write_register(i2c_handle, LIS3DH_CTRL_REG1, 0x77) != 0) {
        return -1;
    }

    // Set full-scale range to +/- 2g
    if (write_register(i2c_handle, LIS3DH_CTRL_REG4, 0x00) != 0) {
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (read_register(i2c_handle, LIS3DH_OUT_X_L, &buffer[1]) != 0 ||
        read_register(i2c_handle, LIS3DH_OUT_X_H, &buffer[0]) != 0 ||
        read_register(i2c_handle, LIS3DH_OUT_Y_L, &buffer[3]) != 0 ||
        read_register(i2c_handle, LIS3DH_OUT_Y_H, &buffer[2]) != 0 ||
        read_register(i2c_handle, LIS3DH_OUT_Z_L, &buffer[5]) != 0 ||
        read_register(i2c_handle, LIS3DH_OUT_Z_H, &buffer[4]) != 0) {
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate acceleration magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 16384.0f; // Assuming +/- 2g range
    float y_g = (float)y / 16384.0f;
    float z_g = (float)z / 16384.0f;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Detect free-fall
bool detect_freefall(float magnitude) {
    return magnitude < freefall_threshold;
}

// Detect impact
bool detect_impact(float magnitude) {
    return magnitude > impact_threshold;
}

// Activate buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Set GPIO HIGH
}

// Deactivate buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_PIN, 0); // Set GPIO LOW
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

