            fprintf(stderr, "Error reading acceleration data\n");
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LIS3DH_ADDR, 0); // Bus 1, address 0x18, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LIS3DH
int init_lis3dh() {
    // Enable accelerometer (100Hz, normal mode)
    if (write_register(i2c_handle, LIS3DH_CTRL_REG1, 0x77) != 0) {
        return -1;
    }

    // Set full-scale range to +/- 2g
    if (write_register(i2c_handle, LIS3DH_CTRL_REG4, 0x00) != 0) {
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (read_register(i2c_handle, LIS3DH_OUT_X_L, &buffer[1]) != 0 ||
        read_register(i2c_handle, LIS3DH_OUT_X_H, &buffer[0]) != 0 ||
        read_register(i2c_handle, LIS3DH_OUT_Y_L, &buffer[3]) != 0 ||
        read_register(i2c_handle, LIS3DH_OUT_Y_H, &buffer[2]) != 0 ||
        read_register(i2c_handle, LIS3DH_OUT_Z_L, &buffer[5]) != 0 ||
        read_register(i2c_handle, LIS3DH_OUT_Z_H, &buffer[4]) != 0) {
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate acceleration magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 16384.0f; // Assuming +/- 2g range
    float y_g = (float)y / 16384.0f;
    float z_g = (float)z / 16384.0f;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Detect free-fall
bool detect_freefall(float magnitude) {
    return magnitude < freefall_threshold;
}

// Detect impact
bool detect_impact(float magnitude) {
    return magnitude > impact_threshold;
}

// Activate buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Set GPIO HIGH
}

// Deactivate buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_PIN, 0); // Set GPIO LOW
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

