#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>

// LIS3DH I2C address (default 0x18, can be 0x19 if SA0 is high)
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L   0x28
#define LIS3DH_OUT_X_H   0x29
#define LIS3DH_OUT_Y_L   0x2A
#define LIS3DH_OUT_Y_H   0x2B
#define LIS3DH_OUT_Z_L   0x2C
#define LIS3DH_OUT_Z_H   0x2D

// Configuration values
#define CTRL_REG1_DEFAULT 0x77 // Enable all axes, 100 Hz output data rate
#define CTRL_REG4_DEFAULT 0x88 // ±2g range, high-resolution

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold LIS3DH configuration
typedef struct {
    int i2c_address;
    float threshold;
} sensor_config_t;

// Function to initialize the LIS3DH accelerometer
int init_lis3dh(int i2c_handle) {
    // Enable all axes and set output data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG1, CTRL_REG1_DEFAULT) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set ±2g range and high-resolution mode
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG4, CTRL_REG4_DEFAULT) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the LIS3DH
int read_acceleration(int i2c_handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t x_raw, y_raw, z_raw;

    // Read all six registers in one go
    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_OUT_X_L | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine low and high bytes for each axis
    x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g units (assuming ±2g range and 16-bit resolution)
    *x = (float)x_raw / 16384.0f; // 2^15 = 32768, but we are using 16-bit
    *y = (float)y_raw / 16384.0f;
    *z = (float)z_raw / 16384.0f;

    return 0;
}

// Function to log data to a file
void log_data(float x, float y, float z) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open the log file in append mode
    fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    // Write data to the log file
    fprintf(fp, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z);

    // Close the log file
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main(int argc, char *argv[]) {
    int i2c_address = LIS3DH_ADDR;
    float threshold = 2.0f;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            i2c_address = strtol(argv[i + 1], NULL, 16);
            i++;
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = strtof(argv[i + 1], NULL);
            i++;
        }
    }

    // Validate I2C address
    if (i2c_address != 0x18 && i2c_address != 0x19) {
        fprintf(stderr, "Invalid I2C address. Must be 0x18 or 0x19\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh(i2c_handle) < 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            // Check if any axis exceeds the threshold
            if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
                // Log the data
                log_data(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, returning zeros\n");
        }

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

