    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int center_value = read_sensor(CENTER_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        if (left_value == -1 || center_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensor values, exiting...\n");
            break;
        }

        // Update circular buffer
        update_circular_buffer(left_value, center_value, right_value);

        // Check for line and control alert LED
        int line_detected = check_line(left_value, center_value, right_value);
        control_alert_led(line_detected);

        // Log sensor readings to console
        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10 ms
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

