#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define RELAY_GPIO 17
#define THRESHOLD 5.0 // mT
#define POLL_ATTEMPTS 50
#define RETRY_DELAY_MS 10
#define LOG_FILE "magnetic_events.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_sensor_data(int *raw_data);
float convert_to_mT(int raw_data);
int control_relay(int state);
int log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    int raw_data;
    float mT_value;
} sensor_data_t;

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int raw_data;
        float mT_value;

        if (read_sensor_data(&raw_data) == 0) {
            mT_value = convert_to_mT(raw_data);

            if (mT_value > THRESHOLD) {
                if (control_relay(1) == 0) { // Activate relay
                    log_event("Relay activated");
                } else {
                    log_event("Failed to activate relay");
                }
            } else {
                if (control_relay(0) == 0) { // Deactivate relay
                    log_event("Relay deactivated");
                } else {
                    log_event("Failed to deactivate relay");
                }
            }

            log_event("Sensor reading");
        } else {
            log_event("Failed to read sensor data");
        }

        gpioDelay(100); // Sample every 100 ms
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_sensor_data(int *raw_data) {
    char buf[2];
    int result;

    for (int i = 0; i < POLL_ATTEMPTS; ++i) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            *raw_data = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            log_event("I2C read failed, retrying...");
            gpioDelay(RETRY_DELAY_MS);
        }
    }

    log_event("I2C read failed after multiple attempts");
    return 1; // Failure after multiple retries
}

float convert_to_mT(int raw_data) {
    // Conversion formula from Si7210 datasheet
    // Assuming raw data is a 16-bit value representing the magnetic field
    // Adjust the formula based on your sensor's specific datasheet
    return (float)raw_data * 0.1; // Example conversion
}

int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

int log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
    return 0;
}

void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

void cleanup() {
    log_event("Cleaning up...");
    control_relay(0); // Deactivate relay
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    log_event("Shutdown complete");
}

