#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define PORT 5000
#define BUFFER_SIZE 1024

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int server_fd = -1;
int client_fd = -1;

// Function prototypes
int initialize_gpio();
int set_relay_state(int state);
int handle_client(int client_fd);
int create_server_socket(int port);
int accept_client_connection(int server_fd);
void log_event(const char *message);
void signal_handler(int signum);

// Function to initialize the GPIO library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    return 0;
}

// Function to set the relay state
int set_relay_state(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Function to handle client connections
int handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        char *command = strtok(buffer, " \t\n\r\f\v");
        char *rest = command;

        while (rest != NULL) {
            if (strcmp(rest, "ON") == 0) {
                if (set_relay_state(1) == 0) {
                    log_event("Relay ON");
                } else {
                    log_event("Error: Failed to turn relay ON");
                }
                break; // Process only the first command
            } else if (strcmp(rest, "OFF") == 0) {
                if (set_relay_state(0) == 0) {
                    log_event("Relay OFF");
                } else {
                    log_event("Error: Failed to turn relay OFF");
                }
                break; // Process only the first command
            } else {
                log_event("Error: Invalid command");
            }
            rest = NULL; // Prevent further parsing
        }
        if (bytes_received < 0) {
            perror("recv failed");
            log_event("Error: recv failed");
            break;
        }
    }

    if (bytes_received < 0) {
        perror("recv failed");
        log_event("Error: recv failed");
    } else {
        close(client_fd);
        client_fd = -1; // Reset client_fd
    }
    return 0;
}

// Function to create a server socket
int create_server_socket(int port) {
    int server_fd;
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    // Forcefully attaching socket to the port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }
    return server_fd;
}

// Function to accept a client connection
int accept_client_connection(int server_fd) {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int client_fd;

    if ((client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
        perror("accept");
        return -1;
    }
    return client_fd;
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("relay_log.txt", "a");
    if (fp == NULL) {
        perror("fopen failed");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler function
void signal_handler(int signum) {
    terminate = 1;
    log_event("Signal received, shutting down...");
    if (client_fd != -1) {
        close(client_fd);
    }
    if (server_fd != -1) {
        close(server_fd);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Create server socket
    server_fd = create_server_socket(PORT);
    if (server_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_event("Server started");

    while (!terminate) {
        // Accept client connection
        client_fd = accept_client_connection(server_fd);
        if (client_fd < 0) {
            // Non-fatal error, continue listening
            continue;
        }

        // Handle client
        handle_client(client_fd);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    return 0;
}

