int init_gpio(int gpio_pin) {
    if (gpioSetMode(gpio_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to start measurement
int start_measurement(int i2c_handle) {
    char cmd[2] = {0x36, 0x08}; // Start measurement command
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read flow rate
int read_flow_rate(int i2c_handle, uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading from I2C device: %d bytes read\n", bytes_read);
        return -1;
    }
    return 0;
}

