            // Validate CRC
            if (crc8(data1, 2) == data1[2] && crc8(data2, 2) == data2[2]) {
                // Convert raw data to flow rate (example conversion, adjust as needed)
                int16_t raw_flow1 = (data1[0] << 8) | data1[1];
                int16_t raw_flow2 = (data2[0] << 8) | data2[1];

