#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define RAIN_DETECTED 0 // Sensor output is LOW when rain is present
#define DRY 1
#define DEBOUNCE_DELAY_MS 100
#define MOTOR_RUN_TIME_S 5

// Global variables
static volatile int running = 1;
static int dry_count = 0;
static time_t last_rain_time = 0;

// Function prototypes
int read_rain_sensor();
void control_motor(int enable, int in1, int in2);
void log_event(int priority, const char *message);
void signal_handler(int signal);
void cleanup();

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to control the DC motor
void control_motor(int enable, int in1, int in2) {
    gpioWrite(in1, 1);
    gpioWrite(in2, 0);
    gpioWrite(enable, enable);
    gpioDelay(MOTOR_RUN_TIME_S * 1000); // Run for 5 seconds
    gpioWrite(in1, 0);
    gpioWrite(in2, 0);
    gpioWrite(enable, 0);
}

// Function to log events using syslog
void log_event(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(priority, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event(LOG_INFO, "Received signal, shutting down...");
    cleanup();
    exit(0);
}

// Cleanup function to stop the motor and release GPIO resources
void cleanup() {
    control_motor(0, MOTOR_IN1_PIN, MOTOR_IN2_PIN); // Stop the motor
    gpioTerminate(); // Terminate pigpio
    log_event(LOG_INFO, "GPIO resources released.");
}

int main() {
    // Initialize syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set pull-up resistor on the rain sensor pin
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    log_event(LOG_INFO, "Rain sensor monitoring started.");

    // Main loop
    while (running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected == RAIN_DETECTED) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_rain_time) > (DEBOUNCE_DELAY_MS / 1000.0)) {
                dry_count = 0; // Reset debounce counter
                last_rain_time = current_time;
                log_event(LOG_INFO, "Rain detected!");
                control_motor(1, MOTOR_IN1_PIN, MOTOR_IN2_PIN); // Start the motor
                log_event(LOG_INFO, "Motor started.");
            }
        } else {
            dry_count++;
            if (dry_count >= 3) {
                log_event(LOG_INFO, "Rain stopped.");
                dry_count = 0; // Reset counter after 3 dry readings
            }
        }

        gpioDelay(200); // Poll every 200ms
    }

    cleanup();
    closelog();
    return 0;
}

