    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set pull-up resistor on the rain sensor pin
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    log_event(LOG_INFO, "Rain sensor monitoring started.");

    // Main loop
    while (running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected == RAIN_DETECTED) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_rain_time) > (DEBOUNCE_DELAY_MS / 1000.0)) {
                dry_count = 0; // Reset debounce counter
                last_rain_time = current_time;
                log_event(LOG_INFO, "Rain detected!");
                control_motor(1, MOTOR_IN1_PIN, MOTOR_IN2_PIN); // Start the motor
                log_event(LOG_INFO, "Motor started.");
            }
        } else {
            dry_count++;
            if (dry_count >= 3) {
                log_event(LOG_INFO, "Rain stopped.");
                dry_count = 0; // Reset counter after 3 dry readings
            }
        }

        gpioDelay(200); // Poll every 200ms
    }

    cleanup();
    closelog();
    return 0;
}

