static volatile int running = 1;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log events to a file
int log_event(const char *event_type, const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    char *timestamp = get_iso8601_timestamp();
    fprintf(fp, "%s %s\n", timestamp, message);
    free(timestamp); // Free the allocated memory

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file!\n");
        return -1;
    }
    return 0;
}

// Function to turn the floodlight on
void floodlight_on() {
    gpioWrite(LED_GPIO, 1); // Set GPIO HIGH
    printf("Floodlight ON\n");
}

