#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define DEBOUNCE_MS 200
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x0B
#define ELE0_TOUCH_STATUS_REG 0x00
#define ELE0_RELEASE_STATUS_REG 0x01
#define MHD_NHD_NCL_FDL 0x0C
#define AUTO_CONFIG_RANGE 0x0F
#define AUTO_CONFIG_ENABLE 0x10
#define FFI_SFI_CDT 0x11

// Global variables
static int i2c_fd;
static volatile bool running = true;

// Function prototypes
int mpr121_init(int fd);
int mpr121_read_touch_status(int fd);
void relay_on(int pin);
void relay_off(int pin);
void signal_handler(int signal);

// Function to turn the relay ON
void relay_on(int pin) {
    digitalWrite(pin, HIGH);
}

// Function to turn the relay OFF
void relay_off(int pin) {
    digitalWrite(pin, LOW);
}

// Function to initialize the MPR121
int mpr121_init(int fd) {
    // Soft reset
    if (wiringPiI2CWriteReg8(fd, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed: %s\n", strerror(errno));
        return -1;
    }
    delay(100); // Wait for reset to complete

    // Configuration registers
    if (wiringPiI2CWriteReg8(fd, 0x5E, MHD_NHD_NCL_FDL) < 0) {
        fprintf(stderr, "Error: MHD_NHD_NCL_FDL write failed: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, 0x5F, NHD_NCL_FDL) < 0) {
        fprintf(stderr, "Error: NHD_NCL_FDL write failed: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, 0x60, NCL_FDL) < 0) {
        fprintf(stderr, "Error: NCL_FDL write failed: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, 0x61, FDL) < 0) {
        fprintf(stderr, "Error: FDL write failed: %s\n", strerror(errno));
        return -1;
    }

    if (wiringPiI2CWriteReg8(fd, 0x2B, AUTO_CONFIG_RANGE) < 0) {
        fprintf(stderr, "Error: AUTO_CONFIG_RANGE write failed: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, 0x2C, AUTO_CONFIG_ENABLE) < 0) {
        fprintf(stderr, "Error: AUTO_CONFIG_ENABLE write failed: %s\n", strerror(errno));
        return -1;
    }

    if (wiringPiI2CWriteReg8(fd, 0x5C, FFI_SFI_CDT) < 0) {
        fprintf(stderr, "Error: FFI_SFI_CDT write failed: %s\n", strerror(errno));
        return -1;
    }

    // Enable electrodes 0-11
    for (int i = 0; i < 12; i++) {
        if (wiringPiI2CWriteReg8(fd, 0x5D, 1) < 0) {
            fprintf(stderr, "Error: Enable electrode write failed: %s\n", strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Function to read the touch status of electrode 0
int mpr121_read_touch_status(int fd) {
    int touch_status = wiringPiI2CReadReg8(fd, ELE0_TOUCH_STATUS_REG);
    if (touch_status < 0) {
        fprintf(stderr, "Error: Reading touch status failed: %s\n", strerror(errno));
        return -1;
    }
    return touch_status;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    relay_off(RELAY_PIN);
    close(i2c_fd);
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: I2C setup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) == -1) {
        fprintf(stderr, "Error: MPR121 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Set relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    relay_off(RELAY_PIN); // Ensure relay is OFF at startup

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status == -1) {
            fprintf(stderr, "Error: Failed to read touch status. Retrying...\n");
            delay(100); // Wait before retrying
            continue;
        }

        // Check if electrode 0 is touched and debounced
        if (touch_status & 0x01) {
            delay(DEBOUNCE_MS); // Debounce
            int debounced_touch_status = mpr121_read_touch_status(i2c_fd);
            if (debounced_touch_status == -1) {
                fprintf(stderr, "Error: Failed to read debounced touch status. Retrying...\n");
                delay(100); // Wait before retrying
                continue;
            }
            if (debounced_touch_status & 0x01) {
                relay_on(RELAY_PIN);
                printf("Relay ON\n");
            }
        } else {
            relay_off(RELAY_PIN);
            printf("Relay OFF\n");
        }

        delay(50); // Small delay to prevent busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    relay_off(RELAY_PIN);
    close(i2c_fd);

    return 0;
}

