        fprintf(stderr, "Error: AUTO_CONFIG_RANGE write failed: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, 0x2C, AUTO_CONFIG_ENABLE) < 0) {
        fprintf(stderr, "Error: AUTO_CONFIG_ENABLE write failed: %s\n", strerror(errno));
        return -1;
    }

    if (wiringPiI2CWriteReg8(fd, 0x5C, FFI_SFI_CDT) < 0) {
        fprintf(stderr, "Error: FFI_SFI_CDT write failed: %s\n", strerror(errno));
        return -1;
    }

    // Enable electrodes 0-11
    for (int i = 0; i < 12; i++) {
        if (wiringPiI2CWriteReg8(fd, 0x5D, 1) < 0) {
            fprintf(stderr, "Error: Enable electrode write failed: %s\n", strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Function to read the touch status of electrode 0
int mpr121_read_touch_status(int fd) {
    int touch_status = wiringPiI2CReadReg8(fd, ELE0_TOUCH_STATUS_REG);
    if (touch_status < 0) {
        fprintf(stderr, "Error: Reading touch status failed: %s\n", strerror(errno));
        return -1;
    }
    return touch_status;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    relay_off(RELAY_PIN);
    close(i2c_fd);
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: I2C setup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) == -1) {
        fprintf(stderr, "Error: MPR121 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Set relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    relay_off(RELAY_PIN); // Ensure relay is OFF at startup

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status == -1) {
            fprintf(stderr, "Error: Failed to read touch status. Retrying...\n");
            delay(100); // Wait before retrying
            continue;
        }

        // Check if electrode 0 is touched and debounced
        if (touch_status & 0x01) {
            delay(DEBOUNCE_MS); // Debounce
            int debounced_touch_status = mpr121_read_touch_status(i2c_fd);
            if (debounced_touch_status == -1) {
                fprintf(stderr, "Error: Failed to read debounced touch status. Retrying...\n");
                delay(100); // Wait before retrying
                continue;
            }
            if (debounced_touch_status & 0x01) {
                relay_on(RELAY_PIN);
                printf("Relay ON\n");
            }
        } else {
            relay_off(RELAY_PIN);
            printf("Relay OFF\n");
        }

        delay(50); // Small delay to prevent busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    relay_off(RELAY_PIN);
    close(i2c_fd);

    return 0;
}

