#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define PWM_FREQUENCY 50
#define PWM_RANGE 2000
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define BUFFER_SIZE 1024

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int server_fd = -1;
int client_fd = -1;

// Function prototypes
int init_gpio();
int init_socket();
void handle_client(int client_fd);
void process_command(int client_fd, const char *command);
void send_response(int client_fd, const char *response);
void cleanup();
void signal_handler(int signum);
void log_message(int priority, const char *format, ...);

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN); // Pull-down resistor

    return 0;
}

// Function to initialize the socket
int init_socket() {
    int server_fd;
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_message(LOG_ERR, "Socket creation failed");
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_message(LOG_ERR, "Setsockopt failed");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed");
        close(server_fd);
        return -1;
    }
    log_message(LOG_INFO, "Server listening on port %d", PORT);
    return server_fd;
}

// Function to handle client connections
void handle_client(int client_fd) {
    char buffer[BUFFER_SIZE] = {0};
    ssize_t bytes_received;

    while (!terminate) {
        bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            log_message(LOG_INFO, "Received: %s", buffer);
            process_command(client_fd, buffer);
        } else if (bytes_received == 0) {
            log_message(LOG_INFO, "Client disconnected");
            break;
        } else {
            log_message(LOG_ERR, "Receive failed");
            break;
        }
    }
    close(client_fd);
}

// Function to process commands
void process_command(int client_fd, const char *command) {
    if (strncmp(command, "PIR", 3) == 0) {
        int pir_value = gpioRead(PIR_PIN);
        char response[4];
        snprintf(response, sizeof(response), "PIR:%d", pir_value);
        send_response(client_fd, response);
    } else if (strncmp(command, "servo_angle", 11) == 0) {
        int angle = atoi(command + 11);
        if (angle >= 0 && angle <= 180) {
            int pulse_width = MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
            gpioServo(SERVO_PIN, pulse_width);
            char response[50];
            snprintf(response, sizeof(response), "Servo angle set to %d", angle);
            log_message(LOG_INFO, "%s", response);
            send_response(client_fd, response);
        } else {
            log_message(LOG_ERR, "Invalid angle: %d", angle);
            send_response(client_fd, "Invalid angle");
        }
    } else {
        log_message(LOG_ERR, "Unknown command: %s", command);
        send_response(client_fd, "Unknown command");
    }
}

// Function to send a response
void send_response(int client_fd, const char *response) {
    if (client_fd != -1) {
        send(client_fd, response, strlen(response), 0);
    }
}

// Function to clean up resources
void cleanup() {
    log_message(LOG_INFO, "Cleaning up...");
    if (client_fd != -1) {
        close(client_fd);
    }
    if (server_fd != -1) {
        close(server_fd);
    }
    gpioTerminate();
    closelog();
}

// Signal handler function
void signal_handler(int signum) {
    log_message(LOG_INFO, "Signal received: %d", signum);
    terminate = 1;
    cleanup();
    exit(0);
}

// Function to log messages with timestamps
void log_message(int priority, const char *format, ...) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);
}

int main() {
    // Open syslog
    openlog("servo_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Initialize socket
    server_fd = init_socket();
    if (server_fd == -1) {
        log_message(LOG_ERR, "Socket initialization failed, exiting");
        cleanup();
        closelog();
        return 1;
    }

    // Main loop
    while (!terminate) {
        struct sockaddr_in address;
        int addrlen = sizeof(address);
        client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);
        if (client_fd < 0) {
            log_message(LOG_ERR, "Accept failed");
        } else {
            log_message(LOG_INFO, "Client connected");
            handle_client(client_fd);
        }
    }

    // Cleanup and exit
    cleanup();
    closelog();
    return 0;
}

