#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define GROW_LIGHT_GPIO 23
#define LUX_THRESHOLD 150
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define SAMPLING_INTERVAL_SEC 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(int i2c_handle, uint16_t *lux_value);
float calculate_lux(uint16_t raw_value);
int control_relay(int gpio_pin, int state);
int log_data(const char *filename, time_t timestamp, float lux_value);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read BH1750 sensor
int read_bh1750(int i2c_handle, uint16_t *lux_value) {
    char config_cmd = 0x10; // Continuous high resolution mode
    char buffer[2];
    int result;

    result = i2cWriteByteData(i2c_handle, 0x00, config_cmd); // Write to register 0x00
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    gpioDelay(200); // Wait for measurement (at least 180ms)

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2); // Read 2 bytes
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *lux_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Calculate lux value
float calculate_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Control relay
int control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

// Log data to file
int log_data(const char *filename, time_t timestamp, float lux_value) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp_str, lux_value) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GROW_LIGHT_GPIO, 0); // Turn off relay
    gpioTerminate();
}

int main() {
    uint16_t raw_lux;
    float lux;
    time_t current_time;
    int retry;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO23 as output
    gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Grow light control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_bh1750(i2c_handle, &raw_lux) == 0) {
                lux = calculate_lux(raw_lux);
                current_time = time(NULL);
                if (log_data("grow_log.txt", current_time, lux) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Error reading BH1750 sensor. Retry %d/%d\n", retry + 1, RETRY_COUNT);
                retry++;
                gpioDelay(RETRY_DELAY_MS); // Wait before retrying
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read BH1750 after %d retries. Skipping this cycle.\n", RETRY_COUNT);
        }

        // Control relay based on lux value
        if (lux < LUX_THRESHOLD) {
            control_relay(GROW_LIGHT_GPIO, 1); // Turn on relay
        } else {
            control_relay(GROW_LIGHT_GPIO, 0); // Turn off relay
        }

        gpioDelay(SAMPLING_INTERVAL_SEC * 1000); // Wait 2 seconds
    }

    cleanup();
    return 0;
}

