// Log data to file
int log_data(const char *filename, time_t timestamp, float lux_value) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp_str, lux_value) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GROW_LIGHT_GPIO, 0); // Turn off relay
    gpioTerminate();
}

int main() {
    uint16_t raw_lux;
    float lux;
    time_t current_time;
    int retry;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO23 as output
    gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Grow light control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_bh1750(i2c_handle, &raw_lux) == 0) {
                lux = calculate_lux(raw_lux);
                current_time = time(NULL);
                if (log_data("grow_log.txt", current_time, lux) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Error reading BH1750 sensor. Retry %d/%d\n", retry + 1, RETRY_COUNT);
                retry++;
                gpioDelay(RETRY_DELAY_MS); // Wait before retrying
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read BH1750 after %d retries. Skipping this cycle.\n", RETRY_COUNT);
        }

        // Control relay based on lux value
        if (lux < LUX_THRESHOLD) {
            control_relay(GROW_LIGHT_GPIO, 1); // Turn on relay
        } else {
            control_relay(GROW_LIGHT_GPIO, 0); // Turn off relay
        }

        gpioDelay(SAMPLING_INTERVAL_SEC * 1000); // Wait 2 seconds
    }

    cleanup();
    return 0;
}

