#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <getopt.h>
#include <time.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static double scale_factor = DEFAULT_SCALE;
static int threshold = DEFAULT_THRESHOLD;
static int solenoid_state = 0; // 0 = LOW, 1 = HIGH

// Function prototypes
int hx711_read();
double calculate_weight(int raw_value, double scale_factor);
void control_solenoid(int state);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[]);

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// HX711 read function
int hx711_read() {
    int i;
    int data = 0;
    int timeout = 0;

    // Wait for DOUT to go LOW
    while (gpioRead(HX711_DOUT) == 1 && timeout < 1000) {
        gpioDelay(1); // Wait 1 ms
        timeout++;
    }

    if (timeout >= 1000) {
        syslog(LOG_ERR, "HX711 timeout waiting for DOUT LOW");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // One extra clock pulse for gain selection (Channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    data = data ^ 0x800000; // Convert to signed

    return data;
}

// Calculate weight
double calculate_weight(int raw_value, double scale_factor) {
    return (double)raw_value * scale_factor;
}

// Control solenoid
void control_solenoid(int state) {
    if (state != solenoid_state) {
        gpioWrite(SOLENOID_PIN, state);
        solenoid_state = state;
        gpioDelay(state ? DEFAULT_DURATION : 0); // Activate for duration, de-activate immediately
        gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off after activation
    }
}

// Parse command-line arguments
int parse_arguments(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "s:t:d:")) != -1) {
        switch (opt) {
            case 's':
                scale_factor = atof(optarg);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                DEFAULT_DURATION = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s scale] [-t threshold] [-d duration]\n", argv[0]);
                return 1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int raw_value;
    double weight;
    int i;

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Parse command-line arguments
    if (parse_arguments(argc, argv) != 0) {
        closelog();
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Set solenoid to LOW initially
    gpioWrite(SOLENOID_PIN, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Perform startup tare
    long sum = 0;
    for (i = 0; i < 10; i++) {
        raw_value = hx711_read();
        if (raw_value == -1) {
            syslog(LOG_ERR, "Tare failed, exiting");
            gpioTerminate();
            closelog();
            return 1;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    double tare_value = (double)sum / 10.0;

    syslog(LOG_INFO, "Tare value: %lf", tare_value);

    // Main loop
    while (running) {
        sum = 0;
        for (i = 0; i < 5; i++) {
            raw_value = hx711_read();
            if (raw_value == -1) {
                syslog(LOG_ERR, "HX711 read error, retrying...");
                gpioDelay(100); // Wait before retrying
                i--; // Retry the current iteration
                continue;
            }
            sum += raw_value;
            gpioDelay(10); // Small delay between readings
        }
        weight = (double)sum / 5.0 - tare_value;
        weight = calculate_weight((int)raw_value, scale_factor);

        syslog(LOG_INFO, "Weight: %lf grams", weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Weight exceeds threshold, activating solenoid");
            control_solenoid(1);
        } else {
            control_solenoid(0);
        }

        gpioDelay(500); // Poll every 500 ms
    }

    // Shutdown sequence
    syslog(LOG_INFO, "Shutting down...");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();
    closelog();

    return 0;
}

