#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <pthread.h>
#include <mosquitto.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_QOS 0
#define MQTT_KEEPALIVE 60
#define MQTT_CLEAN_SESSION 1
#define MQTT_MAX_RECONNECT_ATTEMPTS 5
#define MQTT_RECONNECT_DELAY 5

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;
static int gpio_initialized = 0;

// Function prototypes
void signal_handler(int signum);
int initialize_gpio();
int set_gpio_output(int pin, int level);
int set_gpio_input(int pin);
int mqtt_connect(struct mosquitto **mosq, const char *client_id, const char *host, int port, int clean_session);
int mqtt_subscribe(struct mosquitto *mosq, const char *topic, int qos);
void mqtt_disconnect(struct mosquitto *mosq);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_message(const char *payload);
void cleanup();

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        syslog(LOG_USER, "Received signal %d, shutting down...", signum);
        running = 0;
    }
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    gpio_initialized = 1;
    set_gpio_output(GPIO_PIN, 0); // Set GPIO17 as output and turn relay OFF
    return 0;
}

// Set GPIO output
int set_gpio_output(int pin, int level) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", pin);
        return -1;
    }
    gpioWrite(pin, level);
    return 0;
}

// Set GPIO input
int set_gpio_input(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", pin);
        return -1;
    }
    return 0;
}

// MQTT connect
int mqtt_connect(struct mosquitto **mosq, const char *client_id, const char *host, int port, int clean_session) {
    *mosq = mosquitto_new(client_id, clean_session, NULL);
    if (!*mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto client");
        return -1;
    }

    int rc = mosquitto_connect(*mosq, host, port, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(*mosq);
        *mosq = NULL;
        return -1;
    }

    return 0;
}

// MQTT subscribe
int mqtt_subscribe(struct mosquitto *mosq, const char *topic, int qos) {
    int rc = mosquitto_subscribe(mosq, NULL, topic, qos);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to topic: %s", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

// MQTT disconnect
void mqtt_disconnect(struct mosquitto *mosq) {
    mosquitto_disconnect(mosq);
}

// MQTT disconnect callback
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_USER, "Disconnected from MQTT broker successfully");
    } else {
        syslog(LOG_ERR, "MQTT disconnect error: %s", mosquitto_strerror(result));
    }
}

// MQTT message callback
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        int result = parse_message(message->payload);
        if (result == 0) {
            if (result == 1) {
                set_gpio_output(GPIO_PIN, 1);
            } else {
                set_gpio_output(GPIO_PIN, 0);
            }
        } else {
            syslog(LOG_ERR, "Invalid message payload: %s", message->payload);
        }
    } else {
        syslog(LOG_ERR, "Empty message received");
    }
}

// Parse message
int parse_message(const char *payload) {
    if (strcmp(payload, "ON") == 0) {
        return 1;
    } else if (strcmp(payload, "OFF") == 0) {
        return 0;
    } else {
        return -1;
    }
}

// Cleanup resources
void cleanup() {
    if (gpio_initialized) {
        set_gpio_output(GPIO_PIN, 0);
        gpioTerminate();
        gpio_initialized = 0;
    }
    if (mosq) {
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    closelog();
}

int main() {
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // MQTT setup
    if (mqtt_connect(&mosq, MQTT_CLIENT_ID, MQTT_BROKER, MQTT_PORT, MQTT_CLEAN_SESSION) != 0) {
        syslog(LOG_ERR, "MQTT connection failed, exiting");
        cleanup();
        return 1;
    }

    if (mqtt_subscribe(mosq, MQTT_TOPIC, MQTT_QOS) != 0) {
        syslog(LOG_ERR, "MQTT subscription failed, exiting");
        cleanup();
        return 1;
    }

    // MQTT loop
    int reconnect_attempts = 0;
    while (running) {
        int rc = mosquitto_loop(mosq, -1, 1); // -1 means loop forever, 1 is the max number of messages to process
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(rc));
            if (reconnect_attempts < MQTT_MAX_RECONNECT_ATTEMPTS) {
                syslog(LOG_WARNING, "MQTT reconnect attempt %d", reconnect_attempts + 1);
                reconnect_attempts++;
                sleep(MQTT_RECONNECT_DELAY);
                if (mqtt_connect(&mosq, MQTT_CLIENT_ID, MQTT_BROKER, MQTT_PORT, MQTT_CLEAN_SESSION) != 0) {
                    syslog(LOG_ERR, "MQTT reconnect failed, exiting");
                    running = 0;
                } else if (mqtt_subscribe(mosq, MQTT_TOPIC, MQTT_QOS) != 0) {
                    syslog(LOG_ERR, "MQTT subscription failed after reconnect, exiting");
                    running = 0;
                }
            } else {
                syslog(LOG_ERR, "MQTT reconnect failed too many times, exiting");
                running = 0;
            }
        } else {
            // Check for disconnections during loop
            if (mosq->last_will != NULL) {
                mosquitto_will_set(mosq, MQTT_TOPIC, MQTT_QOS, "not_subscribed", 1);
            }
        }
    }

    // Cleanup
    mqtt_disconnect(mosq);
    cleanup();

    return 0;
}

