#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the servos
#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define target pulse widths (microseconds)
#define TARGET_PULSE_WIDTH_1 1000
#define TARGET_PULSE_WIDTH_2 1500
#define TARGET_PULSE_WIDTH_3 2000
#define TARGET_PULSE_WIDTH_4 500
#define TARGET_PULSE_WIDTH_5 2500

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the PWM duty cycle for a servo
int set_servo_pulse_width(int gpio_pin, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d us). Must be between %d and %d us.\n", pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1; // Indicate an error
    }

    // Calculate the duty cycle (percentage of the period)
    int duty_cycle = (int)(((float)pulse_width / 1000000.0) * 10000.0); // 1000000 us is the period

    // Set the PWM duty cycle
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle for GPIO %d.\n", gpio_pin);
        return -1; // Indicate an error
    }

    return 0; // Indicate success
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1; // Exit with an error code
    }

    // Set the GPIO pins as outputs
    gpioSetMode(SERVO1_PIN, PI_OUTPUT);
    gpioSetMode(SERVO2_PIN, PI_OUTPUT);
    gpioSetMode(SERVO3_PIN, PI_OUTPUT);
    gpioSetMode(SERVO4_PIN, PI_OUTPUT);
    gpioSetMode(SERVO5_PIN, PI_OUTPUT);

    // Set the PWM frequency
    gpioSetPWMfrequency(SERVO1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO4_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO5_PIN, PWM_FREQUENCY);

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop: set servos to target positions and wait
    while (program_running) {
        // Set Servo 1 to 1000 us
        if (set_servo_pulse_width(SERVO1_PIN, TARGET_PULSE_WIDTH_1) != 0) {
            fprintf(stderr, "Error setting Servo 1.\n");
        }
        sleep(3);

        // Set Servo 2 to 1500 us
        if (set_servo_pulse_width(SERVO2_PIN, TARGET_PULSE_WIDTH_2) != 0) {
            fprintf(stderr, "Error setting Servo 2.\n");
        }
        sleep(3);

        // Set Servo 3 to 2000 us
        if (set_servo_pulse_width(SERVO3_PIN, TARGET_PULSE_WIDTH_3) != 0) {
            fprintf(stderr, "Error setting Servo 3.\n");
        }
        sleep(3);

        // Set Servo 4 to 500 us
        if (set_servo_pulse_width(SERVO4_PIN, TARGET_PULSE_WIDTH_4) != 0) {
            fprintf(stderr, "Error setting Servo 4.\n");
        }
        sleep(3);

        // Set Servo 5 to 2500 us
        if (set_servo_pulse_width(SERVO5_PIN, TARGET_PULSE_WIDTH_5) != 0) {
            fprintf(stderr, "Error setting Servo 5.\n");
        }
        sleep(3);
    }

    // Stop the PWM signal for each servo
    gpioPWM(SERVO1_PIN, 0); // Stop Servo 1
    gpioPWM(SERVO2_PIN, 0); // Stop Servo 2
    gpioPWM(SERVO3_PIN, 0); // Stop Servo 3
    gpioPWM(SERVO4_PIN, 0); // Stop Servo 4
    gpioPWM(SERVO5_PIN, 0); // Stop Servo 5

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

