#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18
// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23
// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5
// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// PI Controller Gains
#define KP 0.5
#define KI 0.01

// Target RPM
#define TARGET_RPM 50

// Encoder Ticks per Revolution
#define TPR 64

// Stall Detection Time
#define STALL_TIME 2 // seconds

// Global Variables
volatile int encoderA_ticks = 0;
volatile int encoderB_ticks = 0;
volatile int pwmA = 0;
volatile int pwmB = 0;
volatile int last_encoderA_state = 0;
volatile int last_encoderB_state = 0;
volatile int encoder_stall_count = 0;

// PI Controller Variables
double integralA = 0;
double integralB = 0;

// Function Prototypes
void encoderA_callback(int gpio, int level, uint32_t tick, void *user);
void encoderB_callback(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int encoder_ticks);
double calculate_pwm(double target_rpm, double current_rpm);
void set_motor_speed(int motor, int pwm_value);
void signal_handler(int signal);

// Encoder Callback Functions
void encoderA_callback(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = tick;
    uint32_t diff = current_tick - last_tick;

    if (diff > 500) { // Debounce
        if (level == PI_LOW) {
            encoderA_ticks++;
        } else {
            encoderA_ticks--;
        }
        last_tick = current_tick;
    }
}

void encoderB_callback(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = tick;
    uint32_t diff = current_tick - last_tick;

    if (diff > 500) { // Debounce
        if (level == PI_LOW) {
            encoderB_ticks++;
        } else {
            encoderB_ticks--;
        }
        last_tick = current_tick;
    }
}

// Function to calculate RPM
double calculate_rpm(int encoder_ticks) {
    return (double)encoder_ticks * 60.0 / TPR;
}

// Function to calculate PWM duty cycle using PI controller
double calculate_pwm(double target_rpm, double current_rpm) {
    static double errorA = 0;
    static double errorB = 0;

    double rpmA = calculate_rpm(encoderA_ticks);
    double rpmB = calculate_rpm(encoderB_ticks);

    errorA = target_rpm - rpmA;
    integralA += errorA;
    double pwmA_calc = KP * errorA + KI * integralA;

    errorB = target_rpm - rpmB;
    integralB += errorB;
    double pwmB_calc = KP * errorB + KI * integralB;

    // Clamp PWM values
    if (pwmA_calc > 255) pwmA_calc = 255;
    if (pwmA_calc < 0) pwmA_calc = 0;
    if (pwmB_calc > 255) pwmB_calc = 255;
    if (pwmB_calc < 0) pwmB_calc = 0;

    return pwmA_calc;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int pwm_value) {
    if (motor == 1) {
        gpioPWM(MOTOR_A_PWM, pwm_value);
        gpioWrite(MOTOR_A_DIR, 1); // Forward
    } else if (motor == 2) {
        gpioPWM(MOTOR_B_PWM, pwm_value);
        gpioWrite(MOTOR_B_DIR, 1); // Forward
    }
}

// Signal Handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Stopping motors and exiting.\n");
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, 10000);
    gpioSetPWMfrequency(MOTOR_B_PWM, 10000);

    // Register ISR for Encoder A
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoderA_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder A A\n");
        gpioTerminate();
        return 1;
    }

    // Register ISR for Encoder B
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoderB_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder B A\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Calculate RPM
        double rpmA = calculate_rpm(encoderA_ticks);
        double rpmB = calculate_rpm(encoderB_ticks);

        // Calculate PWM duty cycle
        double pwmA_calc = calculate_pwm(TARGET_RPM, rpmA);
        double pwmB_calc = calculate_pwm(TARGET_RPM, rpmB);

        // Set motor speeds
        set_motor_speed(1, (int)pwmA_calc);
        set_motor_speed(2, (int)pwmB_calc);

        // Print RPM and PWM duty cycle
        printf("Motor A RPM: %.2f, PWM: %d\n", rpmA, pwmA_calc);
        printf("Motor B RPM: %.2f, PWM: %d\n", rpmB, pwmB_calc);

        // Stall detection
        if (encoderA_ticks == 0 && encoderB_ticks == 0) {
            encoder_stall_count++;
            if (encoder_stall_count >= STALL_TIME) {
                printf("Motor stall detected!\n");
                encoder_stall_count = 0; // Reset stall count after warning
            }
        } else {
            encoder_stall_count = 0; // Reset stall count if motion is detected
        }

        // Delay
        gpioDelay(100000); // 100ms
    }

    return 0;
}

