int init_i2c();
int init_gpio();
int init_logging();
void cleanup();
void signal_handler(int signal);
int read_lux();
void control_relay(int lux);
void log_data(int lux, int relay_state);
void log_error(const char *message);

// Structure to hold sensor data
typedef struct {
    int lux;
    int relay_state;
} SensorData;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initialize relay to OFF (LOW)
    return 0;
}

// Function to initialize logging
int init_logging() {
    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Function to read lux value from BH1750 sensor
int read_lux() {
    char config[1] = {0x10}; // Continuous high-resolution mode
    char buffer[2];
    int lux = -1;

    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        log_error("Failed to write to I2C device");
        return -1;
    }

    gpioDelay(180); // Wait for measurement (at least 180ms)

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        log_error("Failed to read from I2C device");
        return -1;
    }

    lux = (buffer[0] << 8) | buffer[1];
    return lux;
}

// Function to control the relay
void control_relay(int lux) {
    static int relay_state = 0; // 0 = OFF, 1 = ON
    static int last_lux = 0;
    int current_lux = lux;

    if (current_lux < LUX_DUSK_THRESHOLD && relay_state == 0) {
        gpioWrite(GPIO_RELAY, 1); // Turn ON relay
        relay_state = 1;
    } else if (current_lux > LUX_DAWN_THRESHOLD + HYSTERESIS && relay_state == 1) {
        gpioWrite(GPIO_RELAY, 0); // Turn OFF relay
        relay_state = 0;
    }

    log_data(current_lux, relay_state);
}

// Function to log data to file
void log_data(int lux, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Lux = %d, Relay = %s\n", timestamp, lux, relay_state == 1 ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to log errors to file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize resources
    if (init_pigpio() != 0) return 1;
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }
    if (init_logging() != 0) {
        cleanup();
        return 1;
    }

    printf("Chicken Coop Monitoring System started\n");

    // Main loop
    while (!terminate) {
        int lux = read_lux();
        if (lux >= 0) {
            control_relay(lux);
        } else {
            log_error("Failed to read lux value");
        }

        sleep(READ_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    printf("Chicken Coop Monitoring System stopped\n");
    return 0;
}

