#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variable to store the relay state
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_touch_sensor();
int control_relay(int state);
int log_relay_state(int state);
void signal_handler(int signal);

// Function to read the touch sensor with debouncing
int read_touch_sensor() {
    int i;
    int stable_state = 0;

    // Read the sensor multiple times to ensure stability
    for (i = 0; i < 5; i++) {
        if (gpioRead(TOUCH_SENSOR_PIN) == 1) {
            stable_state++;
        }
        gpioDelay(DEBOUNCE_TIME * 1000); // Delay in microseconds
    }

    // Return 1 only if the sensor is HIGH for all readings
    return (stable_state == 5) ? 1 : 0;
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error writing to relay pin\n");
        return -1;
    }
    return 0;
}

// Function to log the relay state with timestamp
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (state == 1) {
        printf("%s Relay is ON\n", timestamp);
    } else {
        printf("%s Relay is OFF\n", timestamp);
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    control_relay(0); // Turn off the relay
    gpioTerminate();   // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting TOUCH_SENSOR_PIN to input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting RELAY_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    // Set initial relay state to OFF
    control_relay(0);
    log_relay_state(0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (read_touch_sensor()) {
            // Toggle the relay state
            relay_state = !relay_state;
            if (control_relay(relay_state) != 0) {
                fprintf(stderr, "Error controlling relay\n");
            }
            log_relay_state(relay_state);
        }
        gpioDelay(10000); // Sleep for 10ms
    }

    return 0;
}

