#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LOG_FILE "water_flow.log"
#define SAMPLE_INTERVAL_SEC 1
#define HISTORICAL_SAMPLES 5
#define HISTORICAL_SAMPLE_SIZE 10 // Number of samples to store in the circular buffer

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
int solenoid_state = 1; // 1 = open, 0 = closed
FILE *log_file = NULL;
int running = 1;

// Structure to hold historical flow data
typedef struct {
    float flow_history[HISTORICAL_SAMPLES];
    int history_index;
} FlowHistory;

FlowHistory flow_history = {{0.0}, 0};

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *userdata);
float calculate_lpm(int pulse_count, float time_interval);
void control_solenoid(float lpm);
void log_data(float lpm, int solenoid_state);
void signal_handler(int signal);
void cleanup();
void update_flow_history(float lpm);

// ISR callback function
void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

// Function to calculate LPM
float calculate_lpm(int pulse_count, float time_interval) {
    return (float)pulse_count / PULSES_PER_LITER / time_interval * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(float lpm) {
    if (lpm > 5.0) {
        if (solenoid_state == 0) { // Only close if already closed
            gpioWrite(SOLENOID_GPIO, 0);
            solenoid_state = 0;
            log_data(lpm, solenoid_state);
        }
    } else if (lpm < 4.5) {
        if (solenoid_state == 1) { // Only open if already open
            gpioWrite(SOLENOID_GPIO, 1);
            solenoid_state = 1;
            log_data(lpm, solenoid_state);
        }
    }
}

// Function to log data to file
void log_data(float lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "Open" : "Closed");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Cleaning up...\n", signal);
    log_data(0.0, solenoid_state); // Log the current state before exiting
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    pthread_mutex_destroy(&pulse_mutex);
    gpioWrite(SOLENOID_GPIO, 1); // Ensure solenoid is open on exit
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Function to update the flow history
void update_flow_history(float lpm) {
    flow_history.flow_history[flow_history.history_index] = lpm;
    flow_history.history_index = (flow_history.history_index + 1) % HISTORICAL_SAMPLES;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up ISR
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "ISR setup failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_sample_time = time(NULL);
    int pulse_count_local = 0;

    // Main loop
    while (running) {
        time_t current_time = time(NULL);
        int current_pulse_count = 0;

        // Debounce and read pulse count
        gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL);
        gpioDelay(1000); // Wait 1ms
        gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable ISR

        if (pulse_count > 0) {
            current_pulse_count = pulse_count;
            pulse_count = 0; // Reset pulse count after reading
        }

        // Calculate LPM
        float lpm = calculate_lpm(current_pulse_count, (float)(current_time - last_sample_time));

        // Update flow history
        update_flow_history(lpm);

        // Control solenoid
        control_solenoid(lpm);

        // Log data
        log_data(lpm, solenoid_state);

        // Update last sample time
        last_sample_time = current_time;

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL_SEC);
    }

    return 0;
}

