#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration
#define CONFIG_FILE "config.ini"
#define DEFAULT_CALIBRATION_FACTOR 100.0
#define DEFAULT_TIMEOUT 1000
#define DEFAULT_PULSE_WIDTH 1500
#define DEFAULT_WEIGHT_RANGE 1000
#define DEFAULT_LOG_FILE "dispensing_log.json"
#define PORT 12345
#define MAX_CLIENTS 5
#define MAX_RETRIES 3

// GPIO pins
#define HX711_DATA 23
#define HX711_SCK 24
#define SERVO_PIN 18

// Global variables
static volatile int running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static int timeout = DEFAULT_TIMEOUT;
static int pulse_width = DEFAULT_PULSE_WIDTH;
static int weight_range = DEFAULT_WEIGHT_RANGE;
static char *log_file_path = DEFAULT_LOG_FILE;

// Structure to hold HX711 data
typedef struct {
    int data;
    int pulses;
} HX711Data;

// Function prototypes
int read_hx711(int timeout);
double convert_to_grams(int raw_value, double calibration_factor);
int send_api_call(int pulse_width, int weight_range);
int receive_target_weight(int socket_fd);
int dispense_ingredient(int pulse_width, int weight_range);
int read_calibration_factor(const char *filename);
int log_event(const char *message);
void signal_handler(int signal);
int setup();
void cleanup();
void cleanup_gpio();
void cleanup_socket();
void cleanup_log();

// Function to read HX711 data with timeout
int read_hx711(int timeout) {
    HX711Data data = {0, 0};
    int i;

    gpioSetMode(HX711_DATA, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for the HX711 to be ready
    for (i = 0; i < timeout; i++) {
        if (gpioRead(HX711_DATA) == 0) {
            break;
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (i == timeout) {
        log_event("HX711 timeout: Sensor not ready.");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // 1 us pulse width
        data.pulses = data.pulses << 1;
        if (gpioRead(HX711_DATA)) {
            data.pulses++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // 1 us pulse width
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // 1 us pulse width
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // 1 us pulse width

    // Convert to signed 2's complement
    if (data.pulses & 0x800000) {
        data.pulses |= 0xFF000000;
    }

    return data.pulses;
}

// Function to convert raw HX711 value to grams
double convert_to_grams(int raw_value, double calibration_factor) {
    return (double)raw_value / calibration_factor;
}

// Function to send API call to the load cell
int send_api_call(int pulse_width, int weight_range) {
    int socket_fd;
    char buffer[256];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        socket_fd = socket(AF_INET, SOCK_STREAM, 0);
        if (socket_fd < 0) {
            log_event("Error creating socket.");
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        struct sockaddr_in address;
        address.sin_family = AF_INET;
        address.sin_addr.s_addr = INADDR_ANY;
        address.sin_port = htons(PORT);

        if (connect(socket_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
            log_event("Error connecting to server.");
            close(socket_fd);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        snprintf(buffer, sizeof(buffer), "pulse_width=%d&weight_range=%d", pulse_width, weight_range);
        if (send(socket_fd, buffer, strlen(buffer), 0) < 0) {
            log_event("Error sending API call.");
            close(socket_fd);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        close(socket_fd);
        return 0; // Success
    }

    log_event("Failed to send API call after multiple retries.");
    return -1; // Failure
}

// Function to receive target weight from client
int receive_target_weight(int socket_fd) {
    char buffer[256];
    ssize_t bytes_received;

    bytes_received = recv(socket_fd, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        log_event("Error receiving target weight.");
        return -1; // Indicate error
    }
    buffer[bytes_received] = '\0';

    char *endptr;
    long target_weight = strtol(buffer, &endptr, 10);

    if (*endptr != '\0' || target_weight < 0 || target_weight > 10000) {
        log_event("Invalid target weight received.");
        return -1; // Indicate error
    }

    return (int)target_weight;
}

// Function to dispense ingredient
int dispense_ingredient(int pulse_width, int weight_range) {
    int raw_value = read_hx711(timeout);
    if (raw_value == -1) {
        log_event("Error reading HX711.");
        return -1; // Indicate error
    }

    double target_weight = (double)weight_range / 1000.0;
    double actual_weight = convert_to_grams(raw_value, calibration_factor);

    if (actual_weight < 0) {
        log_event("Invalid weight reading.");
        return -1; // Indicate error
    }

    // Send API call
    if (send_api_call(pulse_width, weight_range) != 0) {
        log_event("Failed to send API call.");
        return -1; // Indicate error
    }

    gpioDelay(1000); // Wait 1 second

    // Receive actual weight
    int actual_pulse_width = read_hx711(timeout);
    if (actual_pulse_width == -1) {
        log_event("Error reading HX711 after dispensing.");
        return -1; // Indicate error
    }

    // Log event
    char message[256];
    snprintf(message, sizeof(message), "Target: %d, Actual: %.2f, Pulse Width: %d", weight_range, actual_weight, actual_pulse_width);
    log_event(message);

    return 0; // Success
}

// Function to read calibration factor from config file
int read_calibration_factor(const char *filename) {
    json_t *root, *calibration;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        log_event("Error loading config file: " + error.text);
        return -1;
    }

    calibration = json_object_get(root, "calibration_factor");
    if (!calibration) {
        log_event("Calibration factor not found in config file.");
        calibration = json_real(DEFAULT_CALIBRATION_FACTOR);
    } else if (!json_is_real(calibration)) {
        log_event("Calibration factor is not a number.");
        calibration = json_real(DEFAULT_CALIBRATION_FACTOR);
    } else {
        calibration_factor = json_real_value(calibration);
    }

    json_decref(root);
    return 0;
}

// Function to log events to file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char json_string[512];
    snprintf(json_string, sizeof(json_string), "{\"timestamp\": \"%s\", \"message\": \"%s\"}", timestamp, message);

    if (log_file != NULL) {
        fprintf(log_file, "%s\n", json_string);
        fflush(log_file); // Ensure immediate write
    } else {
        log_event("Error: Log file not opened.");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Setup function
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DATA, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Read calibration factor
    if (read_calibration_factor(CONFIG_FILE) != 0) {
        log_event("Failed to read calibration factor. Using default.");
    }

    // Open log file
    log_file = fopen(log_file_path, "a");
    if (log_file == NULL) {
        log_event("Error opening log file.");
        cleanup_gpio();
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources.\n");
    cleanup_gpio();
    cleanup_socket();
    cleanup_log();
    gpioTerminate();
}

// Cleanup GPIO
void cleanup_gpio() {
    gpioWrite(SERVO_PIN, 0); // Stop servo
    gpioSetMode(HX711_DATA, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_INPUT);
}

// Cleanup socket
void cleanup_socket() {
    if (server_fd != -1) {
        close(server_fd);
    }
}

// Cleanup log file
void cleanup_log() {
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    int client_fd;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int opt = 1;

    // Setup
    if (setup() != 0) {
        return 1;
    }

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_event("Socket creation failed");
        cleanup();
        return 1;
    }

    // Forcefully attaching socket to the port 12345
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_event("setsockopt failed");
        cleanup();
        return 1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 12345
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_event("Bind failed");
        cleanup();
        return 1;
    }
    if (listen(server_fd, MAX_CLIENTS) < 0) {
        log_event("Listen failed");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    while (running) {
        // Accept connection
        if ((client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            log_event("Accept failed");
            cleanup();
            return 1;
        }

        // Receive target weight
        int target_weight = receive_target_weight(client_fd);
        if (target_weight < 0) {
            close(client_fd);
            continue; // Move to the next client
        }

        // Dispense ingredient
        if (dispense_ingredient(pulse_width, weight_range) != 0) {
            log_event("Dispensing failed.");
        }

        // Send actual weight back to client
        char weight_str[64];
        snprintf(weight_str, sizeof(weight_str), "%d", (int)actual_weight);
        send(client_fd, weight_str, strlen(weight_str), 0);
        close(client_fd);
    }

    cleanup();
    return 0;
}

