#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define DEFAULT_DEBOUNCE_MS 50

static volatile int running = 1;
static int debounce_ms = DEFAULT_DEBOUNCE_MS;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    running = 0;
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to get current timestamp
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log relay state
void log_relay_state(int state) {
    char timestamp[20];
    get_timestamp(timestamp);
    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
}

// Function to read touch sensor
int read_touch_sensor() {
    return gpioRead(4);
}

// Function to control relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        long ms = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || ms <= 0) {
            fprintf(stderr, "Invalid debounce time: %s. Using default value (%d ms).\n", argv[1], DEFAULT_DEBOUNCE_MS);
            debounce_ms = DEFAULT_DEBOUNCE_MS;
        } else {
            debounce_ms = (int)ms;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(4, PI_INPUT); // Touch sensor GPIO
    gpioSetMode(RELAY_GPIO, PI_OUTPUT); // Relay GPIO

    // Set initial relay state to OFF
    control_relay(0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = 0; // Store the last known state of the touch sensor
    int current_state;
    int rising_edge_count = 0;

    printf("Monitoring touch sensor... Press Ctrl+C to exit.\n");

    while (running) {
        current_state = read_touch_sensor();

        if (current_state == 1 && last_state == 0) {
            rising_edge_count++;
            if (rising_edge_count >= 5) { // Debounce: 5 * debounce_ms = 250ms
                rising_edge_count = 0; // Reset the counter after debounce
                control_relay(1); // Turn on relay
                log_relay_state(1);
                last_state = 1; // Update last state to HIGH
            }
        } else if (current_state == 0 && last_state == 1) {
            rising_edge_count = 0; // Reset the counter if state goes LOW
            control_relay(0); // Turn off relay
            log_relay_state(0);
            last_state = 0; // Update last state to LOW
        } else {
            last_state = current_state; // Update last state if no change
        }

        gpioDelay(debounce_ms * 1000); // Delay for debounce time (microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio

    return 0;
}

