#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define PWM_PERIOD (1000000 / PWM_FREQUENCY) // 20 ms period in microseconds

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int pulse_width;
    int angle;
    char key;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(SERVO_PIN, 2000); // Range of 2000 for 500-2500 us

    // Set initial pulse width (90 degrees)
    pulse_width = 1500;
    gpioPWM(SERVO_PIN, pulse_width / 1000); // Convert us to range
    gpioDelay(500); // Allow servo to move

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Enter angle (0-180) or 'q' to quit: ");
    scanf(" %c", &key);

    while (!terminate) {
        if (key == 'q') {
            break;
        }

        if (key == '+') {
            angle = 90 + 10;
        } else if (key == '-') {
            angle = 90 - 10;
        } else {
            continue; // Ignore invalid input
        }

        // Clamp angle
        if (angle < 0) angle = 0;
        if (angle > 180) angle = 180;

        // Calculate pulse width
        pulse_width = (int)((500 + (angle * 2000) / 180) / 1000); // Calculate pulse width in us

        // Validate pulse width
        if (pulse_width < 500 || pulse_width > 2500) {
            fprintf(stderr, "Error: Pulse width out of range (500-2500 us)\n");
            continue; // Skip to next iteration
        }

        // Set PWM
        gpioPWM(SERVO_PIN, pulse_width / 1000); // Convert us to range
        gpioDelay(500); // Allow servo to move

        // Print current angle
        printf("Angle: %d\n", angle);

        // Read next key
        scanf(" %c", &key);
    }

    // Stop PWM
    gpioPWM(SERVO_PIN, 0); // Set duty cycle to 0 to stop PWM

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

