void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    unsigned long current_time = (unsigned long)(ts.tv_sec * 1000000 + ts.tv_nsec / 1000);

    if (current_time - state.last_pulse_time > DEBOUNCE_MS * 1000) {
        state.last_pulse_time = current_time;
        if (level == 1) { // Rising edge
            // Increment pulse count
            // No need to store the pulse count, just calculate RPM
        }
    }
}

// Function to calculate RPM
double calculate_rpm(unsigned long pulse_count, double time_interval) {
    if (pulse_count == 0) {
        return 0.0;
    }
    return (double)pulse_count * 60.0 / time_interval;
}

