    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Enable pull-up resistor
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

