    signal(SIGTERM, signal_handler);

    printf("Motor RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Calculate time interval
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        unsigned long time_interval = (unsigned long)(ts.tv_sec * 1000000 + ts.tv_nsec / 1000);

        // Calculate RPM
        double rpm = calculate_rpm(1, time_interval); // Assuming one pulse per revolution

        // Log RPM
        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Failed to log RPM\n");
