        // Print RPM to stdout
        printf("RPM: %.2f\n", rpm);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Clean up
    printf("Cleaning up...\n");
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable interrupt
    fclose(log_file);
    gpioTerminate();

    return 0;
}

