#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define TIMEOUT_MS 10000
#define RELAY_ON_TIME_MS 500

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

int main() {
    int touch_state, relay_state = 0;
    unsigned int last_touch_time = 0;
    int pigpio_init_result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d to input\n", TOUCH_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d to output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        touch_state = gpioRead(TOUCH_PIN);

        if (touch_state == PI_HIGH) {
            unsigned int current_time = gpioTick();

            if (last_touch_time == 0) {
                last_touch_time = current_time;
            } else {
                if ((current_time - last_touch_time) > TIMEOUT_MS * 1000) {
