#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define PWM_GPIO 18
#define FLOW_SENSOR_GPIO 24
#define VALVE_ENABLE_GPIO 23
#define PWM_FREQUENCY 1000 // Hz
#define TARGET_FLOW_RATE_MIN 0.0
#define TARGET_FLOW_RATE_MAX 100.0
#define TARGET_FLOW_RATE_DEFAULT 50.0
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_MS 100

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold configuration data
typedef struct {
    double Kp;
    double target_flow_rate;
} Config;

// Function prototypes
int initialize_gpio();
double calculate_flow_rate();
int calculate_pwm_duty_cycle(double flow_rate, double target_flow_rate, double Kp);
int set_valve_position(int duty_cycle);
int enable_valve();
int disable_valve();
int log_data(double flow_rate, int duty_cycle);
void signal_handler(int signal);
void pulse_callback(int gpio, int level, uint32_t tick, void *user);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(VALVE_ENABLE_GPIO, PI_OUTPUT);

    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, 255);

    gpioWrite(VALVE_ENABLE_GPIO, 1); // Enable the valve
    return 0;
}

// Callback function for flow sensor interrupt
void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

// Function to calculate flow rate (L/min) from pulse count
double calculate_flow_rate() {
    double flow_rate = (double)pulse_count / SAMPLE_INTERVAL_MS * 60.0; // pulses per second * 60 seconds / pulses per L
    pulse_count = 0; // Reset pulse count
    return flow_rate;
}

// Function to calculate PWM duty cycle using proportional control
int calculate_pwm_duty_cycle(double flow_rate, double target_flow_rate, double Kp) {
    double error = target_flow_rate - flow_rate;
    double duty_cycle = Kp * error;
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;
    return (int)duty_cycle;
}

// Function to set the PWM duty cycle
int set_valve_position(int duty_cycle) {
    gpioPWM(PWM_GPIO, duty_cycle);
    return 0;
}

// Function to enable the valve
int enable_valve() {
    gpioWrite(VALVE_ENABLE_GPIO, 1);
    return 0;
}

// Function to disable the valve
int disable_valve() {
    gpioWrite(VALVE_ENABLE_GPIO, 0);
    return 0;
}

// Function to log data to a CSV file
int log_data(double flow_rate, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, duty_cycle);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    Config config = {1.0, TARGET_FLOW_RATE_DEFAULT};

    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        double target_flow_rate = strtod(argv[1], &endptr);
        if (*endptr != '\0' || target_flow_rate < TARGET_FLOW_RATE_MIN || target_flow_rate > TARGET_FLOW_RATE_MAX) {
            fprintf(stderr, "Error: Invalid target flow rate. Using default value: %.2f L/min\n", config.target_flow_rate);
        } else {
            config.target_flow_rate = target_flow_rate;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt-driven pulse counting
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL);

    // Main loop
    while (running) {
        // Calculate flow rate
        double flow_rate = calculate_flow_rate();

        // Calculate PWM duty cycle
        int duty_cycle = calculate_pwm_duty_cycle(flow_rate, config.target_flow_rate, config.Kp);

        // Set valve position
        set_valve_position(duty_cycle);

        // Log data
        log_data(flow_rate, duty_cycle);

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Shutdown sequence
    set_valve_position(0); // Set duty cycle to 0
    disable_valve();       // Disable the valve
    fclose(log_file);       // Close the log file
    gpioTerminate();        // Terminate pigpio

    return 0;
}

