#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100kHz
#define SPI_MODE 0

// Define RFID tag length
#define RFID_TAG_LENGTH 10

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 50

// Define lock engagement time (in seconds)
#define LOCK_ENGAGEMENT_TIME 5

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rfid_tag(unsigned char *tag);
int verify_tag(const unsigned char *tag);
int button_pressed();
void engage_locks();
void disengage_locks();
void log_event(const char *event);
void signal_handler(int signal);

// Function to read RFID tag from SPI
int read_rfid_tag(unsigned char *tag) {
    char tx_buf[1] = {0x00}; // Dummy data to initiate read
    char rx_buf[10]; // Buffer to store the 10-byte tag

    if (spiXfer(spi_handle, tx_buf, rx_buf, 10) != 10) {
        log_event("SPI read failed");
        return -1;
    }

    memcpy(tag, rx_buf, RFID_TAG_LENGTH);
    return 0;
}

// Function to verify the RFID tag
int verify_tag(const unsigned char *tag) {
    // Check if the tag is valid (e.g., contains a specific checksum)
    // This is a placeholder; replace with your actual verification logic
    // For this example, we'll just check if the tag is not all zeros
    for (int i = 0; i < RFID_TAG_LENGTH; i++) {
        if (tag[i] != 0) {
            return 0; // Tag is valid
        }
    }
    return -1; // Tag is invalid (all zeros)
}

// Function to detect button press with debouncing
int button_pressed() {
    int i;
    int last_state = 1; // Assume button is not pressed initially (active-low)
    int current_state;

    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable internal pull-up

    for (i = 0; i < 5; i++) { // Allow multiple presses
        current_state = gpioRead(BUTTON_PIN);
        if (current_state == 0 && last_state == 1) { // Button pressed (active-low)
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
            if (gpioRead(BUTTON_PIN) == 0) { // Check if still pressed after delay
                return 1; // Button pressed
            }
        }
        last_state = current_state;
        gpioDelay(1000); // Check every 1ms
    }
    return 0; // Button not pressed
}

// Function to engage both locks
void engage_locks() {
    gpioWrite(LOCK1_PIN, 0);
    gpioWrite(LOCK2_PIN, 0);
    log_event("Engaging locks");
    gpioDelay(LOCK_ENGAGEMENT_TIME * 1000000); // Wait for engagement time
    disengage_locks();
}

// Function to disengage both locks
void disengage_locks() {
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
    log_event("Disengaging locks");
}

// Function to log events with timestamps
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Signal received, shutting down...");
    disengage_locks();
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    unsigned char tag[RFID_TAG_LENGTH];
    int tag_valid;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);

    // Open SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Door access control system started");

    // Main loop
    while (program_running) {
        // Read RFID tag
        if (read_rfid_tag(tag) == 0) {
            log_event("RFID tag read");

            // Verify tag
            tag_valid = verify_tag(tag);
            if (tag_valid == 0) {
                log_event("Tag verified");
                if (button_pressed()) {
                    log_event("Button pressed");
                    engage_locks();
                } else {
                    log_event("Button not pressed");
                }
            } else {
                log_event("Tag verification failed");
            }
        } else {
            log_event("RFID read failed");
        }

        gpioDelay(100000); // Delay for 100ms (adjust as needed)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

