        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Door access control system started");

    // Main loop
    while (program_running) {
        // Read RFID tag
        if (read_rfid_tag(tag) == 0) {
            log_event("RFID tag read");

            // Verify tag
            tag_valid = verify_tag(tag);
