        }

        gpioDelay(100000); // Delay for 100ms (adjust as needed)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

