// Encoder 1
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID Constants
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

