#define PID_SAMPLE_TIME 100

// PWM Frequency (Hz)
#define PWM_FREQUENCY 100

// Hardcoded Target Speed (RPM)
#define TARGET_SPEED 60.0

// Global Variables
volatile int motor1_rpm = 0;
volatile int motor2_rpm = 0;
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
FILE *log_file = NULL;
int running = 1;

// PID Variables
double last_error = 0;
double integral = 0;

// Function Prototypes
void motor1_forward(int speed);
void motor1_backward(int speed);
void motor1_stop();
void motor2_forward(int speed);
void motor2_backward(int speed);
void motor2_stop();
void encoder1_isr(int gpio, int level, uint32_t tick, void *user);
void encoder2_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int count, double time_interval);
double pid_control(double setpoint, double actual_value);
void log_data(double motor1_speed, double motor2_speed, double pid_output);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Motor Control Functions
void motor1_forward(int speed) {
    gpioWrite(MOTOR1_IN1, 1);
    gpioWrite(MOTOR1_IN2, 0);
    gpioPWM(MOTOR1_ENA, speed);
}

void motor1_backward(int speed) {
