    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
    gpioPWM(MOTOR2_ENB, 0);
}

// Encoder Interrupt Service Routine
void encoder1_isr(int gpio, int level, uint32_t tick, void *user) {
    static int last_state = 0;
    int current_state = gpioRead(ENCODER1_B);
    if (current_state != last_state) {
        if (current_state == 0) {
            encoder1_count++;
        } else {
            encoder1_count--;
