    double error = setpoint - actual_value;
    double proportional = Kp * error;
    integral += Ki * error * (double)PID_SAMPLE_TIME;
    double derivative = Kd * (error - last_error) / (double)PID_SAMPLE_TIME;
    double output = proportional + integral + derivative;
    last_error = error;
    return output;
}

