int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Motor 1
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_ENA, 255);

    // Motor 2
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR2_ENB, 255);

    // Encoder 1
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP);

    // Encoder 2
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP);

    // Interrupt Service Routines
    gpioSetISRFuncEx(ENCODER1_A, EITHER_EDGE, 0, encoder1_isr, NULL);
    gpioSetISRFuncEx(ENCODER2_A, EITHER_EDGE, 0, encoder2_isr, NULL);

    return 0;
}

// GPIO Cleanup Function
void cleanup_gpio() {
    motor1_stop();
    motor2_stop();
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("motor_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,PID_Output\n");
    fflush(log_file);

