    struct timespec start, end;
    double time_interval;
    int prev_encoder1_count = 0;
    int prev_encoder2_count = 0;

    // Main loop
    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &start);

        // Calculate time interval
        clock_gettime(CLOCK_MONOTONIC, &end);
        time_interval = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;

        // Calculate RPM for Motor 1
        int current_encoder1_count = encoder1_count;
        motor1_rpm = calculate_rpm(current_encoder1_count - prev_encoder1_count, time_interval);
        prev_encoder1_count = current_encoder1_count;

        // Calculate RPM for Motor 2
        int current_encoder2_count = encoder2_count;
        motor2_rpm = calculate_rpm(current_encoder2_count - prev_encoder2_count, time_interval);
        prev_encoder2_count = current_encoder2_count;

        // PID Control
        double pid_output = pid_control(TARGET_SPEED, motor1_rpm);

        // Motor Control (using PID output as PWM duty cycle)
        int motor1_speed = (int)pid_output;
        int motor2_speed = (int)pid_output;

        if (motor1_speed > 255) motor1_speed = 255;
        if (motor1_speed < 0) motor1_speed = 0;
        if (motor2_speed > 255) motor2_speed = 255;
        if (motor2_speed < 0) motor2_speed = 0;

        if (motor1_speed > 0) {
            motor1_forward(motor1_speed);
        } else if (motor1_speed < 0) {
            motor1_backward(-motor1_speed);
        } else {
            motor1_stop();
        }

        if (motor2_speed > 0) {
            motor2_forward(motor2_speed);
        } else if (motor2_speed < 0) {
            motor2_backward(-motor2_speed);
        } else {
            motor2_stop();
        }

        // Log data
        log_data(motor1_rpm, motor2_rpm, pid_output);

        // Sleep for PID sample time
        gpioDelay(PID_SAMPLE_TIME * 1000); // Convert ms to us
    }

    // Cleanup
    cleanup_gpio();
    fclose(log_file);

    return 0;
}

