#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define LOG_FILE "relay_log.txt"
#define POLL_INTERVAL_MS 50

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_BASELINE_FILTER_CONFIG 0x5B
#define MPR121_TOUCH_THRESHOLD 0x41
#define MPR121_RELEASE_THRESHOLD 0x42
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// Global variables
static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init(int fd);
int mpr121_read_touch_status(int fd);
void relay_control(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Function to write a register value to the MPR121
int mpr121_write_register(int fd, uint8_t reg, uint8_t value) {
    int result = wiringPiI2CWriteReg8(fd, reg, value);
    if (result == -1) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a register value from the MPR121
int mpr121_read_register(int fd, uint8_t reg) {
    int result = wiringPiI2CReadReg8(fd, reg);
    if (result == -1) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to initialize the MPR121
int mpr121_init(int fd) {
    // Soft reset
    if (mpr121_write_register(fd, MPR121_ECR, 0x00) == -1) return -1;
    delay(100); // Wait for reset to complete

    // Configure Electrode Configuration Register (ECR)
    if (mpr121_write_register(fd, MPR121_ECR, 0x00) == -1) return -1; // Disable all electrodes

    // Configure Baseline Filter Configuration Register (CONFIG1)
    if (mpr121_write_register(fd, MPR121_CONFIG1, 0x10) == -1) return -1; // Set filter configuration

    // Configure Touch and Release Thresholds for each electrode
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_register(fd, MPR121_TOUCH_THRESHOLD + 2 * i, 40) == -1) return -1; // Touch threshold
        if (mpr121_write_register(fd, MPR121_RELEASE_THRESHOLD + 2 * i, 20) == -1) return -1; // Release threshold
    }

    // Enable Run Mode
    if (mpr121_write_register(fd, MPR121_ECR, 0x0F) == -1) return -1; // Enable all electrodes

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(int fd) {
    int touch_status_l = mpr121_read_register(fd, MPR121_TOUCHSTATUS_L);
    int touch_status_h = mpr121_read_register(fd, MPR121_TOUCHSTATUS_H);

    if (touch_status_l == -1 || touch_status_h == -1) {
        return -1; // Indicate error
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to control the relay
void relay_control(int state) {
    digitalWrite(RELAY_PIN, state);
}

// Function to log the relay state with a timestamp
void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    relay_control(0); // Turn off the relay
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

