#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_PIN 17
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_event(const char *event);
void unlock_door();
void rate_limit();
void motion_detected_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int relay_state; // 0 = off, 1 = on
    time_t last_unlock_time;
} ProgramState;

ProgramState state = {0, 0};

int main() {
    // Install signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup_gpio();
        return 1;
    }

    // Set up interrupt callback for motion detection
    if (gpioSetAlertFuncEx(PIR_PIN, motion_detected_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function. Exiting.\n");
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup and exit
    cleanup_gpio();
    fclose(log_file);
    printf("Exiting cleanly.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR pin as input with pull-down resistor
    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN);

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

// Log event to file with millisecond precision
void log_event(const char *event) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    fprintf(log_file, "%ld.%03ld: %s\n", ts.tv_sec, milliseconds, event);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Unlock the door by activating the relay
void unlock_door() {
    if (state.relay_state == 0) {
        gpioWrite(RELAY_PIN, 1); // Activate relay
        state.relay_state = 1;
        log_event("Door unlocked");
        gpioDelay(UNLOCK_DURATION_MS); // Keep relay on for specified duration
        gpioWrite(RELAY_PIN, 0); // Deactivate relay
        state.relay_state = 0;
        log_event("Door locked");
    } else {
        fprintf(stderr, "Error: Relay is already activated.\n");
    }
}

// Enforce rate limiting
void rate_limit() {
    time_t now = time(NULL);
    if (difftime(now, state.last_unlock_time) < (RATE_LIMIT_MS / 1000.0)) {
        fprintf(stderr, "Error: Rate limiting applied. Motion ignored.\n");
    } else {
        state.last_unlock_time = now;
    }
}

// Callback function for motion detection
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge (motion detected)
        unlock_door();
        rate_limit();
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Signal received, exiting...\n");
}

