    fflush(log_file); // Ensure data is written to disk immediately
}

// Unlock the door by activating the relay
void unlock_door() {
    if (state.relay_state == 0) {
        gpioWrite(RELAY_PIN, 1); // Activate relay
        state.relay_state = 1;
        log_event("Door unlocked");
        gpioDelay(UNLOCK_DURATION_MS); // Keep relay on for specified duration
        gpioWrite(RELAY_PIN, 0); // Deactivate relay
        state.relay_state = 0;
        log_event("Door locked");
    } else {
        fprintf(stderr, "Error: Relay is already activated.\n");
    }
}

// Enforce rate limiting
void rate_limit() {
    time_t now = time(NULL);
    if (difftime(now, state.last_unlock_time) < (RATE_LIMIT_MS / 1000.0)) {
        fprintf(stderr, "Error: Rate limiting applied. Motion ignored.\n");
    } else {
        state.last_unlock_time = now;
    }
}

// Callback function for motion detection
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge (motion detected)
        unlock_door();
        rate_limit();
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Signal received, exiting...\n");
}

