#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define THRESHOLD_KG 10.0
#define TIMEOUT_MS 500
#define NUM_CALIBRATION_READINGS 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static double scale_factor = 1.0;
static double offset = 0.0;
static int solenoid_state = 0; // 0 = off, 1 = on

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value);
void engage_solenoid();
void disengage_solenoid();
void log_weight(double weight);
void calibrate_sensor();
void load_calibration_data();
void save_calibration_data();
void signal_handler(int signal);
int read_calibration_data(const char *filename, double *scale, double *offset);

// Function to read raw data from HX711
int read_hx711() {
    int32_t value = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < TIMEOUT_MS) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= TIMEOUT_MS) {
        fprintf(stderr, "Error: HX711 timeout waiting for data pin to go low\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        value = value << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // 25th pulse for gain selection (channel A, gain factor 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Clock pulse width
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Clock pulse width

    // Sign extend if negative
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value) {
    return (double)(raw_value - offset) / scale_factor;
}

// Function to engage the solenoid
void engage_solenoid() {
    if (solenoid_state == 0) {
        gpioWrite(SOLENOID_PIN, 1);
        solenoid_state = 1;
        printf("Solenoid engaged\n");
    }
}

// Function to disengage the solenoid
void disengage_solenoid() {
    if (solenoid_state == 1) {
        gpioWrite(SOLENOID_PIN, 0);
        solenoid_state = 0;
        printf("Solenoid disengaged\n");
    }
}

// Function to log weight to file
void log_weight(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to calibrate the sensor
void calibrate_sensor() {
    double sum = 0.0;
    int raw_value;

    printf("Calibrating sensor... Please ensure no weight is applied.\n");
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: Calibration failed due to HX711 timeout\n");
            return;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    offset = sum / NUM_CALIBRATION_READINGS;
    printf("Calibration complete. Offset: %.2f\n", offset);
}

// Function to load calibration data from file
void load_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s. Using default values.\n", CALIBRATION_FILE);
        scale_factor = 1.0;
        offset = 0.0;
    } else {
        if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
            fprintf(stderr, "Error: Invalid calibration data in file %s. Using default values.\n", CALIBRATION_FILE);
            scale_factor = 1.0;
            offset = 0.0;
        }
        fclose(fp);
        printf("Calibration data loaded: scale=%.2f, offset=%.2f\n", scale_factor, offset);
    }
}

// Function to save calibration data to file
void save_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s for writing.\n", CALIBRATION_FILE);
        return;
    }
    fprintf(fp, "%lf %lf", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved: scale=%.2f, offset=%.2f\n", scale_factor, offset);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to read calibration data from file
int read_calibration_data(const char *filename, double *scale, double *offset) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        return -1; // File not found or error opening
    }

    if (fscanf(fp, "%lf %lf", scale, offset) != 2) {
        fclose(fp);
        return -1; // Invalid data format
    }

    fclose(fp);
    return 0; // Success
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    if (read_calibration_data(CALIBRATION_FILE, &scale_factor, &offset) != 0) {
        fprintf(stderr, "Error: Could not read calibration data. Calibrating...\n");
        calibrate_sensor();
        save_calibration_data();
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: HX711 read timeout. Skipping iteration.\n");
            gpioDelay(500); // Wait before next attempt
            continue;
        }

        double weight = calculate_weight(raw_value);
        printf("Raw: %d, Weight: %.2f kg\n", raw_value, weight);

        log_weight(weight);

        if (weight > THRESHOLD_KG) {
            engage_solenoid();
        } else {
            disengage_solenoid();
        }

        gpioDelay(500); // Read every 500ms
    }

    // Cleanup
    disengage_solenoid();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

