#include <pigpio.h>

// Define GPIO pins
#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17

// Calibration factor (adjust based on your setup)
#define CALIBRATION_FACTOR 100.0

// Threshold weight in grams
#define WEIGHT_THRESHOLD 100.0

// Lock activation duration in seconds
#define LOCK_DURATION 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
long hx711_read();
double convert_to_grams(long raw_value);
void control_solenoid(int state);
void log_event(const char *message);
void signal_handler(int signal);

// HX711 read function
long hx711_read() {
    long value = 0;
    int i;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DT to go low
    int timeout = 0;
    while (gpioRead(HX711_DT) == 1 && timeout < 100) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= 100) {
        log_event("HX711 timeout waiting for data line to go low");
        return -1; // Indicate error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Short delay
        value = value << 1;
        if (gpioRead(HX711_DT)) {
            value++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Short delay
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Short delay

    // Sign extend if negative
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// Convert raw value to grams
double convert_to_grams(long raw_value) {
    return (double)raw_value / CALIBRATION_FACTOR;
}

// Control the solenoid lock
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
    log_event("Solenoid lock activated");
    gpioDelay(LOCK_DURATION * 1000); // Delay for lock duration
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
    log_event("Solenoid lock deactivated");
}

// Log events to file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    // Open log file
    log_file = fopen("stock_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    // Main loop
    while (running) {
        long raw_value = hx711_read();
        if (raw_value == -1) {
            log_event("Error reading from HX711");
        } else {
            double weight = convert_to_grams(raw_value);
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Weight: %.2f g", weight);
            log_event(log_message);

            if (weight < WEIGHT_THRESHOLD) {
                control_solenoid(1); // Activate solenoid
            }
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Cleanup (should not reach here if signal handler works)
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

