static volatile int running = 1;
static FILE *log_file = NULL;
static double calibration_factor = 0.0;

// Function prototypes
int read_hx711();
double calibrate_sensor();
double convert_to_kg(int raw_value, double calibration_factor);
void activate_solenoid();
void deactivate_solenoid();
void log_data(double weight);
void signal_handler(int signal);
int read_calibration_factor();

// Function to read a single bit from HX711
int read_hx711_bit() {
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1 us delay

    int bit = gpioRead(HX711_DATA_PIN);
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1 us delay

    return bit;
}

// Function to read a byte from HX711
int read_hx711_byte() {
    int byte = 0;
    for (int i = 0; i < 8; i++) {
        byte |= (read_hx711_bit() << i);
    }
    return byte;
}

// Function to read a 24-bit signed integer from HX711
int read_hx711() {
    int32_t raw_value = 0;
    for (int i = 0; i < 24; i++) {
        raw_value = raw_value << 1;
        raw_value |= read_hx711_bit();
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // 1 us delay
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // 1 us delay
    }

    // Sign extend if the 24th bit is set
    if (raw_value & 0x800000) {
        raw_value |= 0xFF000000;
    }

    return raw_value;
}

// Function to calibrate the sensor
double calibrate_sensor() {
    int raw_value;
    double known_weight;
    double sum = 0.0;
    int num_readings = 5; // Number of readings to average

    printf("Place a known weight on the load cell (e.g., 1000g = 1.0kg).\n");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid weight entered.\n");
        return -1.0; // Indicate error
    }

    printf("Reading %d readings...\n", num_readings);
    for (int i = 0; i < num_readings; i++) {
        raw_value = read_hx711();
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    double average_raw_value = sum / num_readings;
    double calibration_factor = known_weight / average_raw_value;

    printf("Calibration factor: %lf\n", calibration_factor);
    return calibration_factor;
}

// Function to convert raw value to kg
double convert_to_kg(int raw_value, double calibration_factor) {
    return (double)raw_value / calibration_factor;
}

// Function to activate the solenoid
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1);
    gpioDelay(SOLENOID_ACTIVATION_TIME * 1000); // Convert seconds to milliseconds
    deactivate_solenoid();
}

// Function to deactivate the solenoid
void deactivate_solenoid() {
    gpioWrite(SOLENOID_PIN, 0);
}

// Function to log data to file
void log_data(double weight) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f kg\n", timestamp, weight);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to read the calibration factor from file
double read_calibration_factor() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file. Using default value of 0.0.\n");
        return 0.0;
    }

    double factor;
    if (fscanf(fp, "%lf", &factor) != 1) {
        fprintf(stderr, "Error: Could not read calibration factor from file. Using default value of 0.0.\n");
        fclose(fp);
        return 0.0;
    }

    fclose(fp);
    return factor;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Initialize solenoid to OFF
    deactivate_solenoid();

    // Read calibration factor
    calibration_factor = read_calibration_factor();

    // Open log file
    log_file = fopen("security.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        double weight = convert_to_kg(raw_value, calibration_factor);

        printf("Raw value: %d, Weight: %.2f kg\n", raw_value, weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Activating solenoid.\n");
            activate_solenoid();
            log_data(weight);
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    deactivate_solenoid();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

