#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_GPIO 16
#define RELAY_GPIO 20
#define LOG_FILE "relay_events.log"

static volatile int running = 1;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log relay events to a file
int log_relay_event(const char* event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s Relay %s\n", timestamp, event);
    free(timestamp);
    fclose(fp);
    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_GPIO);
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    int relay_state = 0; // 0 = OFF, 1 = ON
    int previous_sensor_state = -1; // Initialize to an invalid state

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value\n");
            log_relay_event("Sensor read error");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        if (sensor_value == 0 && previous_sensor_state != 0) { // Obstacle detected (active-low)
            relay_state = !relay_state; // Toggle relay state
            control_relay(relay_state);
            if (log_relay_event(relay_state == 1 ? "ON" : "OFF") != 0) {
                fprintf(stderr, "Error logging relay event\n");
            }
            previous_sensor_state = 0;
        } else if (sensor_value == 1 && previous_sensor_state != 1) { // No obstacle
            previous_sensor_state = 1;
        }

        gpioDelay(50); // Debounce and reduce CPU usage
    }

    // Clean up GPIO resources before exiting
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF on exit
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

