#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"
#define MAX_CONFIG_VALUE 3600
#define MIN_CONFIG_VALUE 1

volatile sig_atomic_t program_running = 1;

// Function to read the watering duration from the configuration file
int read_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open configuration file %s\n", CONFIG_FILE);
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Empty configuration file %s\n", CONFIG_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *key = strtok(line, "=");
    char *value = strtok(NULL, "=");

    if (key == NULL || value == NULL) {
        fprintf(stderr, "Error: Malformed configuration file %s\n", CONFIG_FILE);
        return -1;
    }

    char *endptr;
    long duration = strtol(value, &endptr, 10);

    if (*endptr != '\0' || duration < MIN_CONFIG_VALUE || duration > MAX_CONFIG_VALUE) {
        fprintf(stderr, "Error: Invalid watering duration in %s: %s\n", CONFIG_FILE, value);
        return -1;
    }

    return (int)duration;
}

// Function to set the GPIO pin state
int set_gpio(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return 0;
}

// Function to log the valve state with a timestamp
void log_state(int state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (state == 0) {
        printf("%s: Valve OFF\n", timestamp);
    } else {
        printf("%s: Valve ON\n", timestamp);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set initial state to OFF (valve closed)
    if (set_gpio(0) != 0) {
        gpioTerminate();
        return 1;
    }

    // Read configuration
    int duration = read_config();
    if (duration == -1) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Turn valve ON
        if (set_gpio(1) != 0) {
            gpioTerminate();
            return 1;
        }
        log_state(1);
        sleep(duration);

        // Turn valve OFF
        if (set_gpio(0) != 0) {
            gpioTerminate();
            return 1;
        }
        log_state(0);
    }

    // Cleanup
    set_gpio(0); // Ensure valve is off before exiting
    gpioTerminate();

    return 0;
}

