    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set initial state to OFF (valve closed)
    if (set_gpio(0) != 0) {
        gpioTerminate();
        return 1;
    }

    // Read configuration
    int duration = read_config();
    if (duration == -1) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Turn valve ON
        if (set_gpio(1) != 0) {
            gpioTerminate();
            return 1;
        }
        log_state(1);
        sleep(duration);

        // Turn valve OFF
        if (set_gpio(0) != 0) {
            gpioTerminate();
            return 1;
        }
        log_state(0);
    }

    // Cleanup
    set_gpio(0); // Ensure valve is off before exiting
    gpioTerminate();

    return 0;
}

