#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define BH1750_ADDR 0x23
#define GPIO_RELAY 23
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY_MS 180
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(int i2c_handle, float *lux);
int control_relay(int gpio_pin, int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);

// Structure for sensor configuration (optional)
typedef struct {
    int i2c_address;
    int measurement_mode;
} sensor_config_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read illuminance from BH1750 sensor
int read_bh1750(int i2c_handle, float *lux) {
    char config_cmd = 0x10; // Continuous high-resolution mode
    char buffer[2];
    int result;

    result = i2cWriteByteData(i2c_handle, 0x00, config_cmd);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(200); // Wait for measurement (datasheet specifies 180ms)

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Control the relay (on/off)
int control_relay(int gpio_pin, int state) {
    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, state);
    return 0;
}

// Log data to file
int log_data(float lux, int relay_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    fprintf(log_file, "%ld.%03ld,%.2f,%d\n", milliseconds, 0, lux, relay_state);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

int main() {
    float lux;
    int relay_state = 0; // 0 = off, 1 = on

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Grow lamp control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_bh1750(i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(GPIO_RELAY, 1);
                relay_state = 1;
                log_data(lux, relay_state);
                printf("Turning on grow lamp.\n");
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(GPIO_RELAY, 0);
                relay_state = 0;
                log_data(lux, relay_state);
                printf("Turning off grow lamp.\n");
            }
        } else {
            fprintf(stderr, "Error reading lux value.\n");
        }

        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    control_relay(GPIO_RELAY, 0); // Turn off relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

