#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define SERVO_PIN 18

// Define servo pulse widths (microseconds)
#define LOCK_PULSE_WIDTH 1000
#define UNLOCK_PULSE_WIDTH 2000

// Define safe servo pulse width range (microseconds)
#define SAFE_PULSE_WIDTH_MIN 500
#define SAFE_PULSE_WIDTH_MAX 2500

// Debounce delay (milliseconds)
#define DEBOUNCE_DELAY 100

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0; // Set the flag to exit the main loop
    }
}

// Function to read the state of a GPIO pin with debouncing
int read_button(int gpio_pin) {
    int reading = gpioRead(gpio_pin);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Delay for debouncing
    return reading;
}

// Function to control the servo motor
void control_servo(int pulse_width) {
    if (pulse_width < SAFE_PULSE_WIDTH_MIN || pulse_width > SAFE_PULSE_WIDTH_MAX) {
        fprintf(stderr, "Error: Invalid pulse width. Must be between %d and %d.\n", SAFE_PULSE_WIDTH_MIN, SAFE_PULSE_WIDTH_MAX);
        return;
    }

    gpioServo(SERVO_PIN, pulse_width);
    printf("Servo pulse width set to %d µs\n", pulse_width);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-up resistors (active-low logic)
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check lock button
        if (read_button(LOCK_BUTTON) == 0) {
            printf("Lock button pressed\n");
            control_servo(LOCK_PULSE_WIDTH);
            gpioDelay(500 * 1000); // Delay for 0.5 seconds
        }

        // Check unlock button
        if (read_button(UNLOCK_BUTTON) == 0) {
            printf("Unlock button pressed\n");
            control_servo(UNLOCK_PULSE_WIDTH);
            gpioDelay(500 * 1000); // Delay for 0.5 seconds
        }

        gpioDelay(10 * 1000); // Small delay to prevent busy-waiting
    }

    // Cleanly release resources before exiting
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();

    return 0;
}

