#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <syslog.h>
#include <errno.h>
#include <wiringPi.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ port
#define PORT 5555

// Define sound sensor polling interval (in milliseconds)
#define POLLING_INTERVAL 10

// Define alarm duration (in seconds)
#define ALARM_DURATION 1

// Define sound sensor mode
#define SOUND_SENSOR_MODE 1

// Define alarm node mode
#define ALARM_NODE_MODE 2

// Global variables
volatile sig_atomic_t program_running = 1;
int zeromq_socket = -1;
int zeromq_context = -1;

// Function prototypes
void signal_handler(int signal);
int setup_gpio(void);
int setup_zeromq(void);
void cleanup(void);
void sound_sensor_callback(void);
void alarm_node_callback(void);
void publish_alert(void);
void subscribe_alert(void);
void log_message(const char *message);

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    log_message("Signal received, exiting...");
}

// GPIO setup function
int setup_gpio(void) {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(SOUND_SENSOR_PIN, INPUT);
    pinMode(ALARM_LED_PIN, OUTPUT);

    return 0;
}

// ZeroMQ setup function
int setup_zeromq(void) {
    zeromq_context = zmq_ctx_new();
    if (!zeromq_context) {
        fprintf(stderr, "Error creating ZeroMQ context: %s\n", zmq_strerror(errno));
        return -1;
    }

    zeromq_socket = zmq_socket(zeromq_context, ZMQ_PUB);
    if (!zeromq_socket) {
        fprintf(stderr, "Error creating ZeroMQ socket: %s\n", zmq_strerror(errno));
        zmq_ctx_destroy(zeromq_context);
        return -1;
    }

    int bind_result = zmq_bind(zeromq_socket, "tcp://*:5555");
    if (bind_result != 0) {
        fprintf(stderr, "Error binding ZeroMQ socket: %s\n", zmq_strerror(errno));
        zmq_close(zeromq_socket);
        zmq_ctx_destroy(zeromq_context);
        return -1;
    }

    log_message("ZeroMQ socket bound to port 5555");
    return 0;
}

// Cleanup function
void cleanup(void) {
    log_message("Cleaning up resources...");

    if (zeromq_socket != -1) {
        zmq_close(zeromq_socket);
    }
    if (zeromq_context != -1) {
        zmq_ctx_destroy(zeromq_context);
    }

    digitalWrite(ALARM_LED_PIN, LOW); // Turn off LED
    wiringPiSetupGpio(); // Reinitialize to default state
    pinMode(SOUND_SENSOR_PIN, INPUT); // Set back to input
    pinMode(ALARM_LED_PIN, INPUT); // Set back to input

    closelog();
}

// Sound sensor callback function
void sound_sensor_callback(void) {
    int sensor_value = digitalRead(SOUND_SENSOR_PIN);

    if (sensor_value == LOW) {
        publish_alert();
    }
}

// Alarm node callback function
void alarm_node_callback(void) {
    char message[] = "ALARM_TRIGGERED";
    publish_alert();
}

// Publish alert function
void publish_alert(void) {
    char message[] = "SOUND_ALERT";
    zmq_msg_t message_zmq;
    int message_size = strlen(message);

    zmq_msg_init_size(&message_zmq, message_size);
    memcpy(zmq_msg_data(&message_zmq), message, message_size);

    int send_result = zmq_msg_send(&message_zmq, zeromq_socket, 0);
    if (send_result == -1) {
        fprintf(stderr, "Error sending message: %s\n", zmq_strerror(errno));
        log_message("Error sending message");
    } else {
        log_message("Alert published");
    }

    zmq_msg_close(&message_zmq);
}

// Subscribe alert function
void subscribe_alert(void) {
    char message[256];
    int message_size = sizeof(message);

    zmq_msg_t message_zmq;
    int recv_result;

    while (program_running) {
        recv_result = zmq_msg_recv(&message_zmq, zeromq_socket, 0);
        if (recv_result == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            fprintf(stderr, "Error receiving message: %s\n", zmq_strerror(errno));
            log_message("Error receiving message");
            continue; // Continue to next iteration
        }

        memcpy(message, zmq_msg_data(&message_zmq), message_size);
        message[message_size] = '\0'; // Null-terminate the message

        printf("Received: %s\n", message);
        log_message(message);

        digitalWrite(ALARM_LED_PIN, HIGH);
        delay(ALARM_DURATION * 1000); // Wait for alarm duration
        digitalWrite(ALARM_LED_PIN, LOW);
    }
    zmq_msg_close(&message_zmq);
}

// Logging function
void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
    printf("%s\n", message);
}

int main(int argc, char *argv[]) {
    openlog("sound_alarm", LOG_PID | LOG_CONS, LOG_USER);

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        log_message("Starting sound sensor mode");
        if (setup_gpio() != 0) {
            return 1;
        }
        if (setup_zeromq() != 0) {
            return 1;
        }

        if (wiringPiISR(SOUND_SENSOR_PIN, INT_EDGE_FALLING, sound_sensor_callback) < 0) {
            fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
            return 1;
        }

        while (program_running) {
            delay(POLLING_INTERVAL);
        }

        cleanup();
        return 0;
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        log_message("Starting alarm node mode");
        if (setup_gpio() != 0) {
            return 1;
        }

        if (setup_zeromq() != 0) {
            return 1;
        }

        if (zmq_bind(zeromq_socket, "tcp://*:5555") != 0) {
            return 1;
        }

        while (program_running) {
            subscribe_alert();
        }

        cleanup();
        return 0;
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        return 1;
    }

    return 0;
}

