#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <pthread.h>
#include <mosquitto.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define GPIO_PIN 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define PULSE_BUFFER_SIZE 256
#define MARK_DURATION 9000 // 9ms
#define SPACE_DURATION 4500 // 4.5ms
#define LOG_FILE "/var/log/ir_decoder.log"

// NEC Protocol Constants
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_ADDRESS_MARK 9000
#define NEC_ADDRESS_SPACE 4500
#define NEC_INVERTED_ADDRESS_MARK 9000
#define NEC_INVERTED_ADDRESS_SPACE 4500
#define NEC_BIT_LENGTH 560
#define NEC_ONE_SPACE_LENGTH 1690
#define NEC_ZERO_SPACE_LENGTH 560
#define NEC_ADDRESS_LENGTH 32

// Global Variables
static volatile int pulse_count = 0;
static volatile unsigned int pulse_buffer[PULSE_BUFFER_SIZE];
static volatile int pulse_buffer_index = 0;
static volatile int running = 1;
static struct mosquitto *mosq = NULL;
static pthread_t mqtt_thread;
static int mqtt_connected = 0;

// Function Prototypes
void signal_handler(int signal);
void alert_callback(int gpio, int level, uint32_t tick);
int decode_nec(const unsigned int *pulse_buffer, int pulse_count, unsigned int *address, unsigned int *command);
int validate_checksum(unsigned int address, unsigned int command);
int publish_mqtt(const char *topic, const char *payload);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);

// Structure to hold MQTT callback functions
typedef struct {
    void (*connect_callback)(struct mosquitto *mosq, void *userdata, int result);
    void (*disconnect_callback)(struct mosquitto *mosq, void *userdata, int rc);
    void (*message_callback)(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
} mqtt_callbacks_t;

// Signal Handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Alert Callback
void alert_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge
        if (pulse_count < PULSE_BUFFER_SIZE) {
            pulse_buffer[pulse_buffer_index] = tick;
            pulse_buffer_index++;
            pulse_count++;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow!");
            pulse_count = 0; // Reset buffer
            pulse_buffer_index = 0;
        }
    }
}

// Decode NEC Protocol
int decode_nec(const unsigned int *pulse_buffer, int pulse_count, unsigned int *address, unsigned int *command) {
    if (pulse_count < NEC_ADDRESS_LENGTH + 2) {
        syslog(LOG_WARNING, "Incomplete NEC frame received.");
        return -1;
    }

    unsigned int address_raw = 0;
    unsigned int command_raw = 0;

    // Extract address and command
