#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define NUM_SENSORS 4
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define START_CONVERSION_CMD 0x10
#define LUX_SCALE_FACTOR 1.2
#define SLEEP_MS 180
#define LOOP_DELAY_S 1

// Sensor addresses
const int sensor_addresses[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};

// Global variables
int i2c_handle[NUM_SENSORS];
int terminate_flag = 0;

// Function prototypes
int init_i2c(int address);
int read_bh1750(int i2c_handle);
float calculate_lux(uint16_t raw_value);
int send_udp_multicast(const char *message);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    float lux;
} sensor_data_t;

// Function to initialize I2C for a given sensor address
int init_i2c(int address) {
    int handle = i2cOpen(I2C_BUS, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", address, handle);
        return -1;
    }
    return handle;
}

// Function to read data from a BH1750 sensor
int read_bh1750(int i2c_handle) {
    char buf[2];
    int result = i2cWriteByte(i2c_handle, START_CONVERSION_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(SLEEP_MS); // Wait for conversion

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    return (buf[0] << 8) | buf[1]; // Combine the two bytes
}

// Function to calculate lux value from raw data
float calculate_lux(uint16_t raw_value) {
    return (float)raw_value / LUX_SCALE_FACTOR;
}

// Function to send data via UDP multicast
int send_udp_multicast(const char *message) {
    int sockfd;
    struct sockaddr_in addr;
    int ttl = 1; // Time-to-live for multicast packets

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket failed");
        return -1;
    }

    // Set TTL for multicast
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("setsockopt (TTL) failed");
        close(sockfd);
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send data
    if (sendto(sockfd, message, strlen(message), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate_flag = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C handles for each sensor
