#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define LOG_FILE "airflow_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
int validate_checksum(uint8_t msb, uint8_t lsb, uint8_t checksum);
float calculate_flow_rate(uint16_t raw_flow);
int log_data(float flow_rate);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint8_t data[2];
    uint8_t checksum;
} sensor_data_t;

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t sensor_data[3]; // 2 bytes of data + 1 byte of checksum
        int retries = 0;

        // Read sensor data with retries
        while (retries < RETRY_COUNT) {
            if (read_sensor_data(sensor_data) == 0) {
                // Check checksum
                if (validate_checksum(sensor_data[0], sensor_data[1], sensor_data[2]) == 0) {
                    // Calculate flow rate
                    float flow_rate = calculate_flow_rate((uint16_t)(sensor_data[0] << 8 | sensor_data[1]));

                    // Log data
                    if (log_data(flow_rate) != 0) {
                        fprintf(stderr, "Failed to log data\n");
                    }

                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Checksum validation failed\n");
                }
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }

            retries++;
            if (retries < RETRY_COUNT) {
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retries == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after multiple retries\n");
        }

        gpioDelay(1000000); // Wait 1 second (in microseconds)
    }

    // Cleanup
    i2cClose(i2c_fd);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_fd);
        return 1;
    }
    return 0;
}

// Read sensor data with retries
int read_sensor_data(uint8_t *data) {
    int result;
    for (int i = 0; i < RETRY_COUNT; i++) {
        result = i2cWriteDevice(i2c_fd, "\0", 0); // Zero-length write to trigger start condition
        if (result == 0) {
            result = i2cReadDevice(i2c_fd, (char *)data, 3); // Read 3 bytes (2 data + 1 checksum)
            if (result == 3) {
                return 0; // Success
            } else {
                fprintf(stderr, "I2C read failed: %d\n", result);
            }
        } else {
            fprintf(stderr, "I2C write failed: %d\n", result);
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }
    return 1; // Failure after retries
}

// Validate checksum
int validate_checksum(uint8_t msb, uint8_t lsb, uint8_t checksum) {
    uint8_t data[2] = {msb, lsb};
    uint8_t calculated_checksum = 0;
    for (int i = 0; i < 2; i++) {
        calculated_checksum += data[i];
    }
    return calculated_checksum != checksum;
}

// Calculate flow rate (SLPM)
float calculate_flow_rate(uint16_t raw_flow) {
    return (float)raw_flow / 4.0;
}

// Log data to file
int log_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return 1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

