        return -1;
    }
    return handle;
}

// Function to read sensor data with retries
int read_sensor_data(int handle, float *x, float *y, float *z) {
    int retries = 0;
    int result;
    char buf[6];

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(handle, D7S_REG_X_LSB, buf, 6);
        if (result == 6) {
            // Combine LSB and MSB, convert to g (adjust scaling factor as needed)
            int16_t x_raw = (buf[1] << 8) | buf[0];
            int16_t y_raw = (buf[3] << 8) | buf[2];
            int16_t z_raw = (buf[5] << 8) | buf[4];

            *x = (float)x_raw / 1000.0; // Example scaling factor
            *y = (float)y_raw / 1000.0;
