    error_file = fopen(ERROR_LOG_FILE, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Error opening error log file.\n");
        gpioTerminate();
        return 1;
    }

    // Open data log file
    data_file = fopen(filename, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data log file.\n");
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(i2c_address);
    if (i2c_handle < 0) {
        log_error("I2C initialization failed.");
        cleanup();
        return 1;
    }

