float read_bh1750(int i2c_fd) {
    char buf[2];
    int bytes_read;
    uint16_t raw_value;
    float lux;

    // Send start measurement command
    if (i2cWriteByteData(i2c_fd, BH1750_ADDR, CONTINUOUS_HIGH_RES_MODE) < 0) {
