#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD_LENGTH 8
#define TLV_TYPE_RANGE 1
#define TLV_TYPE_VELOCITY 2
#define MAX_BUFFER_SIZE 4096
#define MAX_OBJECTS 10

// Structure to hold radar data
typedef struct {
    int object_index;
    float range_m;
    float velocity_mps;
} RadarData;

// Global variables
int uart_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_uart();
void close_resources();
void signal_handler(int signal);
int read_uart_data(char *buffer, int buffer_size);
int parse_tlv_data(const char *data, int data_len, RadarData *radar_data);
int validate_tlv_payload(const char *data, int data_len);
int extract_range_velocity(const char *tlv_data, int tlv_len, RadarData *radar_data);
int write_to_csv(const RadarData *radar_data, int object_index);
int log_error(const char *message);

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize UART
int initialize_uart() {
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(uart_fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;    // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN] = 0;              // read doesn't block
    tty.c_cc[VTIME] = 5;             // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    cfsetospeed(&tty, B921600);
    cfsetispeed(&tty, B921600);

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(uart_fd);
        return -1;
    }

    return 0;
}

// Close resources
void close_resources() {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

// Read data from UART
int read_uart_data(char *buffer, int buffer_size) {
    ssize_t bytes_read = read(uart_fd, buffer, buffer_size);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read == 0) {
        // No data available
        return 0;
    }
    return (int)bytes_read;
}

// Parse TLV data
int parse_tlv_data(const char *data, int data_len, RadarData *radar_data) {
    int offset = 0;
    while (offset < data_len - 4) {
        // Check for magic word
        unsigned char magic_word[MAGIC_WORD_LENGTH];
        if (data_len < offset + MAGIC_WORD_LENGTH) {
            log_error("Incomplete magic word");
            return -1;
        }
        memcpy(magic_word, &data[offset], MAGIC_WORD_LENGTH);
        if (memcmp(magic_word, "\x01\x02\x03\x04", MAGIC_WORD_LENGTH) != 0) {
            offset += 8; // Skip to the next potential TLV
            continue;
        }

        // Read TLV type and length
        unsigned short tlv_type = *((unsigned short *)(data + offset + 4));
        unsigned short tlv_length = *((unsigned short *)(data + offset + 6));

        if (offset + 8 + tlv_length > data_len) {
            log_error("TLV length exceeds data buffer");
            return -1;
        }

        // Extract range and velocity based on TLV type
        if (tlv_type == TLV_TYPE_RANGE) {
            if (extract_range_velocity(data + offset + 8, tlv_length, radar_data) != 0) {
                log_error("Failed to extract range and velocity");
                return -1;
            }
        } else if (tlv_type == TLV_TYPE_VELOCITY) {
            // Validate TLV payload for velocity
            if (validate_tlv_payload(data + offset + 8, tlv_length) != 0) {
                log_error("Invalid velocity TLV payload");
                return -1;
            }
        }

        offset += 8 + tlv_length;
    }
    return 0;
}

// Validate TLV payload
int validate_tlv_payload(const char *data, int data_len) {
    // Implement your validation logic here
    // For example, check the data type (e.g., float)
    // This is a placeholder, replace with actual validation
    return 0; // Return 0 for success, -1 for failure
}

// Extract range and velocity from TLV data
int extract_range_velocity(const char *tlv_data, int tlv_len, RadarData *radar_data) {
    if (tlv_len != 8) {
        log_error("Invalid TLV length for range/velocity");
        return -1;
    }

    radar_data->range_m = *((float *)tlv_data);
    radar_data->velocity_mps = *((float *)(tlv_data + 4));

    return 0;
}

// Write data to CSV file
int write_to_csv(const RadarData *radar_data, int object_index) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (csv_file == NULL) {
        log_error("CSV file not opened");
        return -1;
    }

    fprintf(csv_file, "%s,%d,%.2f,%.2f\n", timestamp, object_index, radar_data->range_m, radar_data->velocity_mps);
    fflush(csv_file); // Ensure data is written immediately

    return 0;
}

// Log errors to stderr
int log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s Error: %s\n", timestamp, message);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen("radar_data.csv", "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close_resources();
        return 1;
    }

    // Main loop
    char buffer[MAX_BUFFER_SIZE];
    int buffer_index = 0;
    RadarData radar_data[MAX_OBJECTS];
    int num_objects = 0;

    printf("Radar data acquisition started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int bytes_read = read_uart_data(buffer, MAX_BUFFER_SIZE);
        if (bytes_read > 0) {
            buffer_index += bytes_read;

            if (buffer_index > MAX_BUFFER_SIZE) {
                log_error("Buffer overflow");
                buffer_index = 0; // Reset buffer
                continue;
            }

            // Attempt to parse TLV data
            if (buffer_index >= 8) { // Ensure enough data for magic word
                if (parse_tlv_data(buffer, buffer_index, &radar_data[num_objects]) == 0) {
                    if (num_objects < MAX_OBJECTS) {
                        if (write_to_csv(&radar_data[num_objects], num_objects) != 0) {
                            log_error("Failed to write to CSV");
                        }
                        num_objects++;
                    } else {
                        log_error("Too many objects detected");
                    }
                } else {
                    // Discard the incomplete frame
                    buffer_index = 0;
                }
            }
        } else if (bytes_read < 0) {
            // Error reading from UART, reset buffer
            buffer_index = 0;
        }

        // Small delay to avoid busy-waiting
        usleep(1000); // 1 ms
    }

    // Clean up
    close_resources();

    printf("Radar data acquisition stopped.\n");

    return 0;
}

