#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/select.h>
#include <sys/time.h>

#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define MAX_BUFFER_SIZE 256
#define MAX_LINE_LENGTH 64

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the UART
int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, no hardware flow control
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 0; // Wait for 0.1 seconds (0.1 * 1000000 us / 1000000 us/sec = 100 us)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART with timeout
int read_uart(int fd, char *buffer, size_t buffer_size, int timeout_sec) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = timeout_sec;
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("Error in select");
        return -1;
    } else if (retval) {
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            perror("Error reading from UART");
            return -1;
        }
        buffer[bytes_read] = '\0';
        return bytes_read;
    } else {
        // Timeout occurred
        return 0;
    }
}

// Function to parse the data and extract range
float parse_data(const char *data) {
    char *token;
    char *line = strdup(data); // Duplicate the string to avoid modifying the original
    if (line == NULL) {
        perror("strdup failed");
        return -1.0;
    }

    token = strtok(line, "\n");
    if (token == NULL) {
        free(line);
        return -1.0;
    }

    char *timestamp = token;
    char *range = strtok(NULL, "\n");
    if (range == NULL) {
        free(line);
        return -1.0;
    }

    // Convert timestamp to YYYY-MM-DD HH:MM:SS format
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp_str[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Extract range value
    char *endptr;
    float meters = strtof(range, &endptr);
    if (endptr == range) {
        fprintf(stderr, "Error: No digits were found in the range value\n");
        free(line);
        return -1.0;
    } else if (endptr == NULL) {
        fprintf(stderr, "Error: No digits were found in the range value\n");
        free(line);
        return -1.0;
    }

    free(line);
    return meters;
}

// Function to format the output string
void format_output(float range, char *output_buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp_str[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(output_buffer, buffer_size, "Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

// Function to log the data to stdout
void log_data(const char *output_buffer) {
    printf("%s", output_buffer);
}

int main() {
    char buffer[MAX_BUFFER_SIZE];
    int bytes_read;
    float range;
    char output_buffer[MAX_LINE_LENGTH];

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_PORT);
    if (uart_fd == -1) {
        fprintf(stderr, "UART initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("UART initialized successfully.\n");

    // Main loop
    while (program_running) {
        bytes_read = read_uart(uart_fd, buffer, MAX_BUFFER_SIZE, TIMEOUT_SEC);
        if (bytes_read > 0) {
            // Parse the data
            range = parse_data(buffer);
            if (range >= 0.0) {
                // Format the output
                format_output(range, output_buffer, sizeof(output_buffer));
                // Log the data
                log_data(output_buffer);
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Exiting.\n");
            break;
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Close UART
    if (uart_fd != -1) {
        close(uart_fd);
    }

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

