#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define UART port
#define UART_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Define emergency stop string
#define EMERGENCY_STOP_STRING "EMERGENCY STOP!\n"

// Global variable for UART handle
int uart_handle = -1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int log_sensor_data(int left, int middle, int right);
int send_uart_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close UART port if it's open
    if (uart_handle != -1) {
        gpioSerialReadClose(uart_handle);
        printf("UART port closed.\n");
    }

    // Terminate pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log the sensor data with a timestamp
int log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);

    return 0;
}

// Function to send a message over the UART port
int send_uart_message(const char *message) {
    int bytes_written = serWrite(uart_handle, message, strlen(message));

    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to UART: %s\n", message);
        return -1;
    } else {
        printf("Sent: %s", message);
    }

    return 0;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open UART port
    uart_handle = serOpen(UART_PORT, BAUD_RATE, 0); // 0 for no flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART port: %s\n", UART_PORT);
        gpioTerminate();
        return 1;
    }

    printf("UART port opened successfully.\n");

    // Main loop
    while (1) {
        // Read sensor values
        int left_sensor = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor data
        log_sensor_data(left_sensor, middle_sensor, right_sensor);

        // Check for emergency stop condition
        if (left_sensor == 0 && middle_sensor == 0 && right_sensor == 0) {
            send_uart_message(EMERGENCY_STOP_STRING);
        }

        // Delay for 100ms (10Hz)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

